    @Test
    fun disabledBuildGateReturnsActionableMessage() {
        assumeFalse(BuildConfig.NODEJS_EMBEDDED_SCRIPT_EXECUTION_BUILD_ENABLED)

        val result = runEmbeddedScript("console.log('should not run');")

        assertFalse(result.succeeded)
        assertEquals("EmbeddedScriptExecutionError", result.errorName)
        assertEquals("ERR_AUTOJS6_NODE_DISABLED", result.errorCode)
        assertEquals("ERR_AUTOJS6_NODE_DISABLED", result.nativeValues["embedded_script.error_code"])
        assertTrue(result.errorMessage.orEmpty().contains("Embedded Node.js script execution is disabled."))
        assertTrue(result.errorMessage.orEmpty().contains("-Pautojs.nodejs.embedded.script.enabled=true"))
    }

    @Test
    fun nodeSourceDetectionRoutesCommonNodeFilesToNodeEngine() {
        val scriptDir = File(context.cacheDir, "embedded-node-source-detection-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create source detection dir: $absolutePath" }
        }
        try {
            val mjs = File(scriptDir, "module.mjs").apply { writeText("console.log('mjs');") }
            val cjs = File(scriptDir, "common.cjs").apply { writeText("console.log('cjs');") }
            val nodeJs = File(scriptDir, "explicit.node.js").apply { writeText("console.log('node.js');") }
            val directiveJs = File(scriptDir, "directive.js").apply { writeText(""""nodejs"; console.log('directive');""") }
            val rhinoJs = File(scriptDir, "rhino.js").apply { writeText("console.log('rhino');") }
            val autoFile = File(scriptDir, "tap.auto").apply { writeText("auto();") }
            val projectDir = File(scriptDir, "node-project").apply {
                check(mkdirs()) { "Failed to create project dir: $absolutePath" }
            }
            File(projectDir, "project.json").writeText("""{"type":"node"}""")
            val projectMain = File(projectDir, "main.js").apply { writeText("console.log('project');") }
            val projectHelper = File(projectDir, "helper.js").apply { writeText("console.log('helper');") }

            assertEquals(JavaScriptSource.ENGINE_NODEJS, JavaScriptFileSource(mjs).engineName)
            assertEquals(JavaScriptSource.ENGINE_NODEJS, JavaScriptFileSource(cjs).engineName)
            assertEquals(JavaScriptSource.ENGINE_NODEJS, JavaScriptFileSource(nodeJs).engineName)
            assertEquals(JavaScriptSource.ENGINE_NODEJS, JavaScriptFileSource(directiveJs).engineName)
            assertEquals(JavaScriptSource.ENGINE_NODEJS, JavaScriptFileSource(projectMain).engineName)
            assertEquals(JavaScriptSource.ENGINE, JavaScriptFileSource(rhinoJs).engineName)
            assertEquals(projectDir.canonicalFile, JavaScriptFileSource(projectMain).nodeProjectRoot)
            assertEquals(null, JavaScriptFileSource(rhinoJs).nodeProjectRoot)
            assertEquals(ScriptFile.TYPE_JAVASCRIPT, ScriptFile(cjs).type)
            assertEquals(JavaScriptSource.ENGINE_NODEJS, ScriptFile(cjs).toSource().engineName)
            val projectMainSource = ScriptFile(projectMain).toSource()
            assertEquals(JavaScriptSource.ENGINE_NODEJS, projectMainSource.engineName)
            assertTrue(projectMainSource is NodeProjectLaunchSource)
            assertEquals(
                NodeProjectLaunchKind.PROJECT_ENTRY,
                (projectMainSource as NodeProjectLaunchSource).nodeProjectLaunchKind,
            )
            val projectMainLaunch = ScriptLaunchSourceFactory.createSourceLaunch(projectMainSource)
            assertEquals(projectDir.canonicalPath, projectMainLaunch.workingDirectory)
            assertEquals(projectDir.canonicalPath, Scripts.createLaunchExecutionConfig(projectMainLaunch, ExecutionConfig()).workingDirectory)
            assertNodeProjectLaunchRequest(
                "script file project main source",
                projectMainLaunch,
                ExpectedNodeProjectRequest(
                    projectRoot = projectDir,
                    launchKind = NodeProjectLaunchKind.PROJECT_ENTRY,
                ),
            )
            val projectHelperSource = ScriptFile(projectHelper).toSource()
            assertEquals(JavaScriptSource.ENGINE_NODEJS, projectHelperSource.engineName)
            assertFalse(projectHelperSource is NodeProjectLaunchSource)
            assertTrue(ScriptFile(autoFile).toSource() is AutoFileSource)
            assertEquals(JavaScriptSource.ENGINE, ScriptFile(rhinoJs).toSource().engineName)
            assertPendingTaskEngineName(cjs, JavaScriptSource.ENGINE_NODEJS)
            assertPendingTaskEngineName(mjs, JavaScriptSource.ENGINE_NODEJS)
            assertPendingTaskEngineName(nodeJs, JavaScriptSource.ENGINE_NODEJS)
            assertPendingTaskEngineName(directiveJs, JavaScriptSource.ENGINE_NODEJS)
            assertPendingTaskEngineName(projectMain, JavaScriptSource.ENGINE_NODEJS)
            assertPendingTaskEngineName(autoFile, AutoFileSource.ENGINE)
            assertPendingTaskEngineName(rhinoJs, JavaScriptSource.ENGINE)
            assertPendingTaskNodeProjectLaunchKind(projectMain, NodeProjectLaunchKind.PROJECT_ENTRY)
            assertPendingTaskNodeProjectLaunchKind(projectHelper, null)
            assertPendingTaskNodeProjectLaunchKind(autoFile, null)
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scriptLaunchSourceFactoryBuildsPathLaunchAndRejectsPreExecuteForNodeProjectEntry() {
        val scriptDir = File(context.cacheDir, "embedded-node-script-launch-source-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create script launch source dir: $absolutePath" }
        }
        try {
            val regular = File(scriptDir, "regular.js").apply {
                writeText("console.log('regular');", StandardCharsets.UTF_8)
            }
            val regularLaunch = ScriptLaunchSourceFactory.createPathLaunch(
                regular.absolutePath,
                preExecuteScript = "console.log('pre');",
            )
            assertEquals(regular.parentFile?.absolutePath, regularLaunch.workingDirectory)
            assertEquals(JavaScriptSource.ENGINE, regularLaunch.engineName)
            assertEquals(null, regularLaunch.nodeProjectLaunchKind)
            assertEquals(null, regularLaunch.buildNodeProjectRequestOrNull())
            assertFalse(regularLaunch.source is NodeProjectLaunchSource)
            val regularFileLaunch = ScriptLaunchSourceFactory.createFileLaunch(regular)
            assertEquals(regular.parentFile?.absolutePath, regularFileLaunch.workingDirectory)
            assertEquals(JavaScriptSource.ENGINE, regularFileLaunch.engineName)
            assertEquals(null, regularFileLaunch.nodeProjectLaunchSource)
            assertEquals(null, regularFileLaunch.buildNodeProjectRequestOrNull())
            assertEquals(
                regular.parentFile?.absolutePath,
                Scripts.createLaunchExecutionConfig(regularFileLaunch, ExecutionConfig()).workingDirectory,
            )
            assertTrue(regularFileLaunch.source is JavaScriptFileSource)
            val regularSourceLaunch = ScriptLaunchSourceFactory.createSourceLaunch(regularFileLaunch.source)
            assertEquals(regular.parentFile?.canonicalPath, regularSourceLaunch.workingDirectory)
            assertEquals(null, regularSourceLaunch.buildNodeProjectRequestOrNull())
            assertEquals(
                scriptDir.absolutePath,
                RuntimeEngines.createExecScriptFileExecutionConfig(
                    regularFileLaunch,
                    ExecutionConfig(workingDirectory = scriptDir.absolutePath),
                ).workingDirectory,
            )

            val autoFile = File(scriptDir, "regular.auto").apply {
                writeText("auto();", StandardCharsets.UTF_8)
            }
            val autoLaunch = ScriptLaunchSourceFactory.createFileLaunch(autoFile)
            assertEquals(autoFile.parentFile?.canonicalPath, autoLaunch.workingDirectory)
            assertEquals(AutoFileSource.ENGINE, autoLaunch.engineName)
            assertEquals(null, autoLaunch.nodeProjectLaunchKind)
            assertEquals(null, autoLaunch.buildNodeProjectRequestOrNull())
            assertTrue(autoLaunch.source is AutoFileSource)

            val projectRoot = File(scriptDir, "node-project").apply {
                check(mkdirs()) { "Failed to create script launch source node project dir: $absolutePath" }
            }
            File(projectRoot, "project.json").writeText(
                """
                {
                  "type": "node",
                  "main": "src/main.js"
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            val main = File(projectRoot, "src/main.js").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText(""""nodejs"; console.log("main");""" + "\n", StandardCharsets.UTF_8)
            }
            val helper = File(projectRoot, "helper.js").apply {
                writeText(""""nodejs"; console.log("helper");""" + "\n", StandardCharsets.UTF_8)
            }
            val workspace = File(projectRoot, "workspace").apply {
                check(mkdirs()) { "Failed to create script launch source workspace: $absolutePath" }
            }
            NodeProjectLaunchDescriptor.descriptorFile(projectRoot).writeText(
                JSONObject()
                    .put("launchKind", "package-script")
                    .put("scriptName", "build")
                    .put("workingDirectory", "workspace")
                    .put("argv", JSONArray().put("--from-script-launch-source"))
                    .put("env", JSONObject().put("SCRIPT_LAUNCH_SOURCE_ENV", "source-secret"))
                    .toString(),
                StandardCharsets.UTF_8,
            )

            val launch = ScriptLaunchSourceFactory.createPathLaunch(main.absolutePath)
            assertEquals(workspace.canonicalPath, launch.workingDirectory)
            assertEquals(JavaScriptSource.ENGINE_NODEJS, launch.engineName)
            assertEquals(NodeProjectLaunchKind.PACKAGE_SCRIPT, launch.nodeProjectLaunchKind)
            assertTrue(launch.source is NodeProjectLaunchSource)
            val fileLaunch = ScriptLaunchSourceFactory.createFileLaunch(main)
            assertEquals(workspace.canonicalPath, fileLaunch.workingDirectory)
            assertEquals(JavaScriptSource.ENGINE_NODEJS, fileLaunch.engineName)
            assertEquals(NodeProjectLaunchKind.PACKAGE_SCRIPT, fileLaunch.nodeProjectLaunchKind)
            assertTrue(fileLaunch.source is NodeProjectLaunchSource)
            val explicitWorkingDirectory = File(projectRoot, "explicit-workspace").apply {
                check(mkdirs()) { "Failed to create explicit working directory: $absolutePath" }
            }
            assertEquals(
                explicitWorkingDirectory.absolutePath,
                fileLaunch.createExecutionConfig(
                    ExecutionConfig(workingDirectory = explicitWorkingDirectory.absolutePath),
                    overrideWorkingDirectory = false,
                ).workingDirectory,
            )
            assertEquals(
                workspace.canonicalPath,
                fileLaunch.createExecutionConfig(ExecutionConfig(), overrideWorkingDirectory = false).workingDirectory,
            )
            assertEquals(
                workspace.canonicalPath,
                Scripts.createLaunchExecutionConfig(fileLaunch, ExecutionConfig()).workingDirectory,
            )
            assertEquals(
                workspace.canonicalPath,
                RuntimeEngines.createExecScriptFileExecutionConfig(
                    fileLaunch,
                    ExecutionConfig(workingDirectory = explicitWorkingDirectory.absolutePath),
                ).workingDirectory,
            )
            assertEquals(
                workspace.canonicalPath,
                RuntimeEngines.createExecScriptFileExecutionConfig(fileLaunch, ExecutionConfig()).workingDirectory,
            )
            val launchSource = launch.source as NodeProjectLaunchSource
            assertEquals(launchSource, launch.nodeProjectLaunchSource)
            assertEquals(NodeProjectLaunchKind.PACKAGE_SCRIPT, launchSource.nodeProjectLaunchKind)
            val expectedRequest = ExpectedNodeProjectRequest(
                projectRoot = projectRoot,
                launchKind = NodeProjectLaunchKind.PACKAGE_SCRIPT,
                workingDirectory = workspace,
                scriptName = "build",
                argv = listOf("--from-script-launch-source"),
                env = mapOf("SCRIPT_LAUNCH_SOURCE_ENV" to "source-secret"),
            )
            val request = assertNodeProjectLaunchRequest("script launch source path", launch, expectedRequest)
            val sourceLaunch = ScriptLaunchSourceFactory.createSourceLaunch(launch.source)
            assertEquals(request, assertNodeProjectLaunchRequest("script launch source source", sourceLaunch, expectedRequest))
            assertEquals(request, ScriptLaunchSourceFactory.createNodeProjectRequestOrNull(main))
            val pendingTask = Task.PendingTask(
                context,
                TimedTask().apply { scriptPath = main.absolutePath },
            )
            val pendingTaskLaunch = pendingTask.createLaunch()
            assertEquals(request, assertTaskNodeProjectRequest("script launch source pending task", pendingTask, pendingTaskLaunch, expectedRequest))
            assertEquals(
                workspace.canonicalPath,
                pendingTask.createLaunchExecutionConfig(
                    pendingTaskLaunch,
                    ExecutionConfig(workingDirectory = explicitWorkingDirectory.absolutePath),
                ).workingDirectory,
            )

            val helperLaunch = ScriptLaunchSourceFactory.createPathLaunch(
                helper.absolutePath,
                preExecuteScript = "console.log('pre');",
            )
            assertEquals(helper.parentFile?.absolutePath, helperLaunch.workingDirectory)
            assertFalse(helperLaunch.source is NodeProjectLaunchSource)

            val failure = runCatching {
                ScriptLaunchSourceFactory.createPathLaunch(
                    main.absolutePath,
                    preExecuteScript = "console.log('pre');",
                )
            }.exceptionOrNull()
            val message = failure?.message.orEmpty()
            assertTrue(message, failure is IllegalArgumentException)
            assertTrue(message, message.contains("does not support preExecuteScript"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scriptIntentsPrepareLaunchBuildsConfigAndRejectsNodeProjectPreExecute() {
        val scriptDir = File(context.cacheDir, "embedded-node-script-intents-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create script intents dir: $absolutePath" }
        }
        try {
            val pureScriptIntent = Intent()
                .putExtra(ScriptIntents.EXTRA_KEY_PRE_EXECUTE_SCRIPT, """console.log("intent script");""")
                .putExtra(ScriptIntents.EXTRA_KEY_DELAY, 17L)
                .putExtra(ScriptIntents.EXTRA_KEY_LOOP_TIMES, 3)
                .putExtra(ScriptIntents.EXTRA_KEY_LOOP_INTERVAL, 23L)

            val pureScriptLaunch = checkNotNull(ScriptIntents.prepareLaunch(context, pureScriptIntent))
            assertEquals(JavaScriptSource.ENGINE, pureScriptLaunch.launch.engineName)
            assertEquals(17L, pureScriptLaunch.config.delay)
            assertEquals(3, pureScriptLaunch.config.loopTimes)
            assertEquals(23L, pureScriptLaunch.config.interval)
            assertEquals(pureScriptIntent, pureScriptLaunch.config.getArgument("intent"))

            val regular = File(scriptDir, "regular.js").apply {
                writeText("""console.log("regular");""", StandardCharsets.UTF_8)
            }
            val regularIntent = Intent()
                .putExtra(ScriptIntents.EXTRA_KEY_PATH, regular.absolutePath)
                .putExtra(ScriptIntents.EXTRA_KEY_PRE_EXECUTE_SCRIPT, """console.log("pre");""")
            val regularLaunch = checkNotNull(ScriptIntents.prepareLaunch(context, regularIntent))
            assertEquals(JavaScriptSource.ENGINE, regularLaunch.launch.engineName)
            assertEquals(regular.parentFile?.absolutePath, regularLaunch.launch.workingDirectory)
            assertEquals(regular.parentFile?.absolutePath, regularLaunch.config.workingDirectory)
            assertEquals(null, regularLaunch.launch.buildNodeProjectRequestOrNull())

            val extraFile = File(scriptDir, "extra-dir/extra.js").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText("""console.log("extra");""", StandardCharsets.UTF_8)
            }
            val jsonFile = File(scriptDir, "json-dir/json.js").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText("""console.log("json");""", StandardCharsets.UTF_8)
            }
            val jsonOverrideIntent = Intent()
                .putExtra(ScriptIntents.EXTRA_KEY_PATH, extraFile.absolutePath)
                .putExtra(ScriptIntents.EXTRA_KEY_PRE_EXECUTE_SCRIPT, """console.log("extra-pre");""")
                .putExtra(
                    ScriptIntents.EXTRA_KEY_JSON,
                    JSONObject()
                        .put(ScriptIntents.EXTRA_KEY_PATH, jsonFile.absolutePath)
                        .put(ScriptIntents.EXTRA_KEY_PRE_EXECUTE_SCRIPT, """console.log("json-pre");""")
                        .toString(),
                )
            val jsonOverrideLaunch = checkNotNull(ScriptIntents.prepareLaunch(context, jsonOverrideIntent))
            assertEquals(jsonFile.parentFile?.absolutePath, jsonOverrideLaunch.launch.workingDirectory)
            assertEquals(jsonFile.parentFile?.absolutePath, jsonOverrideLaunch.config.workingDirectory)
            val jsonOverrideScript = (jsonOverrideLaunch.launch.source as JavaScriptSource).script
            assertTrue(jsonOverrideScript, jsonOverrideScript.contains("""console.log("json-pre");"""))
            assertTrue(jsonOverrideScript, jsonOverrideScript.contains("""console.log("json");"""))
            assertFalse(jsonOverrideScript, jsonOverrideScript.contains("""console.log("extra-pre");"""))
            assertFalse(jsonOverrideScript, jsonOverrideScript.contains("""console.log("extra");"""))

            val invalidJsonLaunch = checkNotNull(
                ScriptIntents.prepareLaunch(
                    context,
                    Intent()
                        .putExtra(ScriptIntents.EXTRA_KEY_PATH, regular.absolutePath)
                        .putExtra(ScriptIntents.EXTRA_KEY_JSON, "{not-json"),
                ),
            )
            assertEquals(regular.parentFile?.absolutePath, invalidJsonLaunch.launch.workingDirectory)

            val invalidPathTypeFailure = runCatching {
                ScriptIntents.prepareLaunch(
                    context,
                    Intent().putExtra(
                        ScriptIntents.EXTRA_KEY_JSON,
                        JSONObject().put(ScriptIntents.EXTRA_KEY_PATH, 7).toString(),
                    ),
                )
            }.exceptionOrNull()
            val invalidPathTypeMessage = invalidPathTypeFailure?.message.orEmpty()
            assertTrue(invalidPathTypeMessage, invalidPathTypeFailure is IllegalArgumentException)
            assertTrue(invalidPathTypeMessage, invalidPathTypeMessage.contains("Script intent JSON field must be a string"))
            assertTrue(invalidPathTypeMessage, invalidPathTypeMessage.contains(ScriptIntents.EXTRA_KEY_PATH))
            assertFalse(invalidPathTypeMessage, invalidPathTypeMessage.contains("7"))

            val projectRoot = File(scriptDir, "node-project").apply {
                check(mkdirs()) { "Failed to create script intents node project dir: $absolutePath" }
            }
            File(projectRoot, "project.json").writeText(
                """
                {
                  "type": "node",
                  "main": "main.js"
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            val main = File(projectRoot, "main.js").apply {
                writeText(""""nodejs"; console.log("main");""" + "\n", StandardCharsets.UTF_8)
            }
            val workspace = File(projectRoot, "workspace").apply {
                check(mkdirs()) { "Failed to create script intents node project workspace: $absolutePath" }
            }
            NodeProjectLaunchDescriptor.descriptorFile(projectRoot).writeText(
                JSONObject()
                    .put("launchKind", "package-script")
                    .put("scriptName", "intent-build")
                    .put("workingDirectory", "workspace")
                    .put("argv", JSONArray().put("--from-intent-json"))
                    .put("env", JSONObject().put("INTENT_JSON_ENV", "json-secret"))
                    .toString(),
                StandardCharsets.UTF_8,
            )
            val nodeJsonLaunch = checkNotNull(
                ScriptIntents.prepareLaunch(
                    context,
                    Intent()
                        .putExtra(ScriptIntents.EXTRA_KEY_PATH, regular.absolutePath)
                        .putExtra(
                            ScriptIntents.EXTRA_KEY_JSON,
                            JSONObject()
                                .put(ScriptIntents.EXTRA_KEY_PATH, main.absolutePath)
                                .toString(),
                        ),
                ),
            )
            val nodeJsonExpectedRequest = ExpectedNodeProjectRequest(
                projectRoot = projectRoot,
                launchKind = NodeProjectLaunchKind.PACKAGE_SCRIPT,
                workingDirectory = workspace,
                scriptName = "intent-build",
                argv = listOf("--from-intent-json"),
                env = mapOf("INTENT_JSON_ENV" to "json-secret"),
            )
            val nodeJsonRequest = assertNodeProjectLaunchRequest(
                "script intent node JSON",
                nodeJsonLaunch.launch,
                nodeJsonExpectedRequest,
            )
            assertEquals(workspace.canonicalPath, nodeJsonLaunch.config.workingDirectory)
            val scriptIntentTask = Task.PendingTask(
                context,
                IntentTask().apply {
                    scriptPath = main.absolutePath
                    action = "org.autojs.autojs.NODE_SCRIPT_INTENT"
                },
            )
            val scriptIntentTaskLaunch = scriptIntentTask.createLaunch()
            assertEquals(
                nodeJsonRequest,
                assertTaskNodeProjectRequest(
                    "script intent pending task",
                    scriptIntentTask,
                    scriptIntentTaskLaunch,
                    nodeJsonExpectedRequest,
                ),
            )

            val packageDir = File(projectRoot, "packages/intent-tool").apply {
                check(mkdirs()) { "Failed to create script intents package bin package dir: $absolutePath" }
            }
            val binWorkspace = File(projectRoot, "bin-workspace").apply {
                check(mkdirs()) { "Failed to create script intents package bin workspace: $absolutePath" }
            }
            NodeProjectLaunchDescriptor.descriptorFile(projectRoot).writeText(
                JSONObject()
                    .put("launchKind", "package-bin")
                    .put("packageDir", "packages/intent-tool")
                    .put("binName", "intent-tool")
                    .put("workingDirectory", "bin-workspace")
                    .put("argv", JSONArray().put("--from-intent-bin"))
                    .put("env", JSONObject().put("INTENT_BIN_ENV", "bin-secret"))
                    .put("timeoutMs", 3456L)
                    .toString(),
                StandardCharsets.UTF_8,
            )
            val nodeBinLaunch = checkNotNull(
                ScriptIntents.prepareLaunch(
                    context,
                    Intent().putExtra(ScriptIntents.EXTRA_KEY_PATH, main.absolutePath),
                ),
            )
            val nodeBinExpectedRequest = ExpectedNodeProjectRequest(
                projectRoot = projectRoot,
                launchKind = NodeProjectLaunchKind.PACKAGE_BIN,
                packageDir = packageDir,
                workingDirectory = binWorkspace,
                binName = "intent-tool",
                argv = listOf("--from-intent-bin"),
                env = mapOf("INTENT_BIN_ENV" to "bin-secret"),
                timeoutMs = 3456L,
            )
            val nodeBinRequest = assertNodeProjectLaunchRequest(
                "script intent package bin",
                nodeBinLaunch.launch,
                nodeBinExpectedRequest,
            )
            assertEquals(binWorkspace.canonicalPath, nodeBinLaunch.config.workingDirectory)
            val binIntentTask = Task.PendingTask(
                context,
                IntentTask().apply {
                    scriptPath = main.absolutePath
                    action = "org.autojs.autojs.NODE_BIN_INTENT"
                },
            )
            val binIntentTaskLaunch = binIntentTask.createLaunch()
            assertEquals(
                nodeBinRequest,
                assertTaskNodeProjectRequest(
                    "bin intent pending task",
                    binIntentTask,
                    binIntentTaskLaunch,
                    nodeBinExpectedRequest,
                ),
            )

            val receivedBroadcastIntent = Intent("org.autojs.autojs.NODE_BIN_BROADCAST")
                .putExtra("broadcast_payload", "payload-value")
            val internalLaunchIntent = Intent()
                .putExtra(ScriptIntents.EXTRA_KEY_PATH, main.absolutePath)
            val broadcastPreparedLaunch = checkNotNull(
                ScriptIntents.prepareLaunch(
                    context,
                    internalLaunchIntent,
                    receivedBroadcastIntent,
                ),
            )
            assertEquals(NodeProjectLaunchKind.PACKAGE_BIN, broadcastPreparedLaunch.launch.nodeProjectLaunchKind)
            assertEquals(binWorkspace.canonicalPath, broadcastPreparedLaunch.launch.workingDirectory)
            assertEquals(binWorkspace.canonicalPath, broadcastPreparedLaunch.config.workingDirectory)
            assertEquals(receivedBroadcastIntent, broadcastPreparedLaunch.config.getArgument("intent"))
            assertFalse(internalLaunchIntent === broadcastPreparedLaunch.config.getArgument("intent"))
            assertEquals(
                nodeBinRequest,
                assertNodeProjectLaunchRequest(
                    "broadcast prepared package bin",
                    broadcastPreparedLaunch.launch,
                    nodeBinExpectedRequest,
                ),
            )

            val failure = runCatching {
                ScriptIntents.prepareLaunch(
                    context,
                    Intent()
                        .putExtra(ScriptIntents.EXTRA_KEY_PATH, main.absolutePath)
                        .putExtra(ScriptIntents.EXTRA_KEY_PRE_EXECUTE_SCRIPT, """console.log("pre");"""),
                )
            }.exceptionOrNull()
            val message = failure?.message.orEmpty()
            assertTrue(message, failure is IllegalArgumentException)
            assertTrue(message, message.contains("Node project launch source does not support preExecuteScript"))
            assertTrue(message, message.contains("run the project entry without preExecuteScript"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun baseBroadcastReceiverRunTaskExecutesNodeProjectPackageBinDescriptor() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-node-broadcast-intent-task-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create broadcast intent task dir: $absolutePath" }
        }
        try {
            File(projectRoot, "project.json").writeText(
                """
                {
                  "type": "node",
                  "main": "src/main.js"
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            val main = File(projectRoot, "src/main.js").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText(
                    """"nodejs"; require("fs").writeFileSync("./unexpected-broadcast-main.txt", "main", "utf8");""" + "\n",
                    StandardCharsets.UTF_8,
                )
            }
            val packageDir = File(projectRoot, "packages/broadcast-tool").apply {
                check(mkdirs()) { "Failed to create broadcast package dir: $absolutePath" }
            }
            File(packageDir, "bin/cli.js").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText(
                    """
                    "nodejs";
                    const fs = require("fs");
                    const normalizeDataPath = (value) => String(value).replace(/^\/data\/user\/0\//, "/data/data/");
                    const entryOk =
                      normalizeDataPath(process.argv[1] || "") === normalizeDataPath(__filename) &&
                      __filename.replace(/\\/g, "/").endsWith("/packages/broadcast-tool/bin/cli.js");
                    const cwdOk = process.cwd().replace(/\\/g, "/").endsWith("/workspace/broadcast-workspace");
                    const argvOk = process.argv.includes("--from-broadcast-descriptor");
                    const envOk = process.env.BROADCAST_RECEIVER_ENV === "receiver-secret";
                    const requireMainOk = require.main === module && module.parent === null;
                    const mainNotRun = !fs.existsSync("../../unexpected-broadcast-main.txt");
                    const packageDirOk = __filename.replace(/\\/g, "/").includes("/packages/broadcast-tool/");
                    const workingDirectoryOk = process.cwd().replace(/\\/g, "/").endsWith("/workspace/broadcast-workspace");
                    const ready =
                      entryOk &&
                      cwdOk &&
                      argvOk &&
                      envOk &&
                      requireMainOk &&
                      mainNotRun &&
                      packageDirOk &&
                      workingDirectoryOk;
                    fs.writeFileSync("./broadcast-receiver-output.txt", ready ? "ok" : "bad", "utf8");
                    console.log("broadcast_receiver.intent_task.ready=" + ready);
                    console.log("broadcast_receiver.intent_task.entry=" + entryOk);
                    console.log("broadcast_receiver.intent_task.cwd=" + cwdOk);
                    console.log("broadcast_receiver.intent_task.argv=" + argvOk);
                    console.log("broadcast_receiver.intent_task.env=" + envOk);
                    console.log("broadcast_receiver.intent_task.package_dir=" + packageDirOk);
                    console.log("broadcast_receiver.intent_task.working_directory=" + workingDirectoryOk);
                    console.log("broadcast_receiver.intent_task.require_main=" + requireMainOk);
                    console.log("broadcast_receiver.intent_task.main_not_run=" + mainNotRun);
                    """.trimIndent() + "\n",
                    StandardCharsets.UTF_8,
                )
            }
            File(packageDir, "package.json").writeText(
                """
                {
                  "name": "broadcast-tool",
                  "version": "1.0.0",
                  "bin": {
                    "broadcast-tool": "./bin/cli.js"
                  }
                }
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )
            val workspace = File(projectRoot, "workspace/broadcast-workspace").apply {
                check(mkdirs()) { "Failed to create broadcast workspace dir: $absolutePath" }
            }
            NodeProjectLaunchDescriptor.descriptorFile(projectRoot).writeText(
                JSONObject()
                    .put("launchKind", "package-bin")
                    .put("packageDir", "packages/broadcast-tool")
                    .put("binName", "broadcast-tool")
                    .put("workingDirectory", "workspace/broadcast-workspace")
                    .put("argv", JSONArray().put("--from-broadcast-descriptor"))
                    .put("env", JSONObject().put("BROADCAST_RECEIVER_ENV", "receiver-secret"))
                    .toString(),
                StandardCharsets.UTF_8,
            )

            BaseBroadcastReceiver.runTask(
                context,
                Intent("org.autojs.autojs.NODE_BIN_BROADCAST").putExtra("broadcast_payload", "payload-value"),
                IntentTask().apply {
                    scriptPath = main.absolutePath
                    action = "org.autojs.autojs.NODE_BIN_BROADCAST"
                },
            )

            assertEquals(
                "ok",
                waitForFileText(File(workspace, "broadcast-receiver-output.txt")).trim(),
            )
        } finally {
            projectRoot.deleteRecursively()
        }
    }

