            assertEquals(listOf("--fixture", "--from-explicit-launch"), plan.argv)
            assertEquals("build", plan.scriptName)
            assertEquals("node scripts/build.js --fixture", plan.scriptCommand)
            assertEquals("node scripts/build.js", plan.resolvedCommand)
        } finally {
            projectRoot.deleteRecursively()
        }
    }

