    @Test
    fun nodeEngineFactoryUsesEmbeddedBackendButAutoDoesNotEnterEmbedded() {
        val propertyName = "autojs.nodejs.backend"
        val previous = System.getProperty(propertyName)
        try {
            System.clearProperty(propertyName)
            assertTrue(NodeJavaScriptEngineFactory.create(context) is NativeNodeEmbeddedJavaScriptEngine)

            System.setProperty(propertyName, "embedded")
            assertTrue(NodeJavaScriptEngineFactory.create(context) is NativeNodeEmbeddedJavaScriptEngine)

            System.setProperty(propertyName, "auto")
            assertFalse(NodeJavaScriptEngineFactory.create(context) is NativeNodeEmbeddedJavaScriptEngine)
        } finally {
            if (previous == null) {
                System.clearProperty(propertyName)
            } else {
                System.setProperty(propertyName, previous)
            }
        }
    }

