        assertEquals(
            listOf("first", ""),
            nodeEmbeddedConsoleOutputLines("first\n\n").toList(),
        )
        assertEquals(listOf(""), nodeEmbeddedConsoleOutputLines("\n").toList())
        assertEquals(listOf("first", "second"), nodeEmbeddedConsoleOutputLines("first\r\nsecond\r\n").toList())
    }

