    @Test
    fun timersBuiltinAndProcessNextTickOrderingAreStable() {
        assumeEmbeddedScriptExecutionEnabled()

        val result = runEmbeddedScript(
            """
            "nodejs";
            const timers = require("timers");
            const nodeTimers = require("node:timers");
            const order = [];
            function mark(value) {
              order.push(value);
              console.log("nextTick.order.step=" + value);
            }
            mark("sync:start");
            process.nextTick((first, second) => {
              mark(first + ":" + second);
              process.nextTick(() => {
                mark("nextTick:nested");
              });
            }, "nextTick", "args");
            Promise.resolve().then(() => {
              mark("promise");
            });
            queueMicrotask(() => {
              mark("queueMicrotask");
            });
            timers.setTimeout(() => {
              mark("timeout");
              console.log("timers.builtin.same=" + (timers === nodeTimers));
              console.log("timers.builtin.resolve=" + [
                require.resolve("timers"),
                require.resolve("node:timers")
              ].join("|"));
              console.log("timers.builtin.surface=" + (
                typeof timers.setTimeout === "function" &&
                typeof timers.clearTimeout === "function" &&
                typeof timers.setInterval === "function" &&
                typeof timers.clearInterval === "function" &&
                typeof timers.setImmediate === "function" &&
                typeof timers.clearImmediate === "function" &&
                typeof timers.promises === "undefined" &&
                Object.isFrozen(timers)
              ));
              console.log("nextTick.order=" + order.join(">"));
            }, 0);
            mark("sync:end");
            """.trimIndent(),
            "<embedded-nexttick-timers-order-source.js>",
        )

        assertTrue(result.errorMessage.orEmpty(), result.succeeded)
        assertOutputOrder(
            result.stdout,
            "nextTick.order.step=sync:start",
            "nextTick.order.step=sync:end",
            "nextTick.order.step=nextTick:args",
            "nextTick.order.step=nextTick:nested",
            "nextTick.order.step=promise",
            "nextTick.order.step=queueMicrotask",
            "nextTick.order.step=timeout",
        )
        assertTrue(result.stdout.contains("timers.builtin.same=true"))
        assertTrue(result.stdout.contains("timers.builtin.resolve=timers|timers"))
        assertTrue(result.stdout.contains("timers.builtin.surface=true"))
        assertTrue(result.stdout.contains("nextTick.order=sync:start>sync:end>nextTick:args>nextTick:nested>promise>queueMicrotask>timeout"))
    }

