    @Test
    fun unclearedIntervalDoesNotBypassServiceTimeout() {
        assumeEmbeddedScriptExecutionEnabled()

        val result = runEmbeddedScript(
            """
            "nodejs";
            setInterval(() => {}, 100);
            console.log("interval:started");
            """.trimIndent(),
            "<embedded-interval-timeout-source.js>",
            timeoutMs = 2500L,
        )

        assertFalse(result.succeeded)
        assertEquals("EmbeddedScriptTimeoutError", result.errorName)
        assertEquals("ERR_AUTOJS6_EMBEDDED_NODE_SCRIPT_TIMEOUT", result.errorCode)
        assertEquals(124, result.exitCode ?: -1)
        assertTrue(result.timedOut)
        assertEquals(2500L, result.timeoutMs ?: -1L)
        assertEquals("<embedded-interval-timeout-source.js>", result.sourceName)
        assertEquals(context.cacheDir.absolutePath, result.workingDirectory)
        assertEquals(true, result.pendingTimers)
        assertEquals(1, result.pendingTimerCount ?: -1)
        assertTrue(result.errorMessage.orEmpty().contains("Embedded Node.js script timed out after 2500ms"))
        assertTrue(result.errorMessage.orEmpty().contains("source=<embedded-interval-timeout-source.js>"))
        assertTrue(result.errorMessage.orEmpty().contains("workingDirectory=${context.cacheDir.absolutePath}"))
        assertTrue(result.errorMessage.orEmpty().contains("pendingTimers=true"))
    }

    @Test
    fun embeddedRuntimeLifecycleLogsNormalAndTimeoutStateTransitions() {
        assumeEmbeddedScriptExecutionEnabled()

        clearEmbeddedNodeLifecycleLogcat()
        val success = runEmbeddedScript(
            """
            "nodejs";
            console.log("lifecycle.success");
            """.trimIndent(),
            "<embedded-lifecycle-success-source.js>",
        )

        assertTrue(success.errorMessage.orEmpty(), success.succeeded)
        val successExecutionId = success.nativeValues["embedded_script.execution_id"].orEmpty()
        assertTrue("Missing execution id in success result", successExecutionId.isNotBlank())
        assertEquals("STOPPED", success.nativeValues["embedded_script.runtime_state"])
        assertEquals(
            "CREATED->STARTING|STARTING->RUNNING|RUNNING->DRAINING|DRAINING->STOPPED",
            success.nativeValues["embedded_script.lifecycle_transitions"],
        )
        val successLog = waitForEmbeddedNodeLifecycleLogcatMarkers(
            listOf(
                "executionId=$successExecutionId CREATED -> STARTING",
                "executionId=$successExecutionId STARTING -> RUNNING",
                "executionId=$successExecutionId RUNNING -> DRAINING",
                "executionId=$successExecutionId DRAINING -> STOPPED",
                "executionId=$successExecutionId STOPPED -> DESTROYED",
            ),
        )
        assertOutputOrder(
            successLog,
            "executionId=$successExecutionId CREATED -> STARTING",
            "executionId=$successExecutionId STARTING -> RUNNING",
            "executionId=$successExecutionId RUNNING -> DRAINING",
            "executionId=$successExecutionId DRAINING -> STOPPED",
            "executionId=$successExecutionId STOPPED -> DESTROYED",
        )

        settleEmbeddedScriptServiceProcess()
        clearEmbeddedNodeLifecycleLogcat()

        val timeout = runEmbeddedScript(
            """
            "nodejs";
            setInterval(() => {}, 100);
            """.trimIndent(),
            "<embedded-lifecycle-timeout-source.js>",
            timeoutMs = 900L,
        )

        assertFalse(timeout.succeeded)
        assertTrue(timeout.timedOut)
        val timeoutExecutionId = timeout.nativeValues["embedded_script.execution_id"].orEmpty()
        assertTrue("Missing execution id in timeout result", timeoutExecutionId.isNotBlank())
        assertEquals("DESTROYED", timeout.nativeValues["embedded_script.runtime_state"])
        assertTrue(
            timeout.nativeValues["embedded_script.lifecycle_transitions"].orEmpty(),
            timeout.nativeValues["embedded_script.lifecycle_transitions"].orEmpty()
                .contains("RUNNING->TIMED_OUT|TIMED_OUT->STOPPING"),
        )
        val timeoutLog = waitForEmbeddedNodeLifecycleLogcatMarkers(
            listOf(
                "executionId=$timeoutExecutionId RUNNING -> TIMED_OUT",
                "executionId=$timeoutExecutionId TIMED_OUT -> STOPPING",
            ),
        )
        assertOutputOrder(
            timeoutLog,
            "executionId=$timeoutExecutionId RUNNING -> TIMED_OUT",
            "executionId=$timeoutExecutionId TIMED_OUT -> STOPPING",
        )
    }

    @Test
    fun embeddedRuntimeTimelineTraceIsOptInAndContainsRequiredEvents() {
        assumeEmbeddedScriptExecutionEnabled()

        val quiet = runEmbeddedScript(
            """
            "nodejs";
            console.log("timeline.quiet");
            """.trimIndent(),
            "<embedded-timeline-quiet-source.js>",
        )
        assertTrue(quiet.errorMessage.orEmpty(), quiet.succeeded)
        assertFalse(
            "Timeline trace should stay off unless explicitly enabled.",
            quiet.nativeValues.containsKey("embedded_script.timeline_json"),
        )

        settleEmbeddedScriptServiceProcess()

        val traced = runEmbeddedScript(
            """
            "nodejs";
            setTimeout(() => console.log("timeline.async"), 0);
            console.log("timeline.sync");
            """.trimIndent(),
            "<embedded-timeline-trace-source.js>",
            env = mapOf("AUTOJS6_NODE_TIMELINE_TRACE" to "1"),
        )
        assertTrue(traced.errorMessage.orEmpty(), traced.succeeded)
        assertEquals("true", traced.nativeValues["embedded_script.timeline_trace_enabled"])

        val timeline = JSONArray(traced.nativeValues["embedded_script.timeline_json"].orEmpty())
        assertEquals(
            timeline.length().toString(),
            traced.nativeValues["embedded_script.timeline_event_count"],
        )
        val names = (0 until timeline.length()).map { index ->
            timeline.getJSONObject(index).getString("name")
        }
        listOf(
            "service_start",
            "bridge_transport_start",
            "bridge_transport_ready",
            "native_enter",
            "native_libs_loaded",
            "v8_initialized",
            "node_env_created",
            "bootstrap_loaded",
            "user_script_entered",
            "first_stdout",
            "pending_callbacks",
            "timers_scheduled",
            "bridge_calls",
            "stop_requested",
            "drain_complete",
            "destroy_complete",
        ).forEach { required ->
            assertTrue("Missing timeline event $required in $names", names.contains(required))
        }
        assertOutputOrder(
            names.joinToString("|"),
            "service_start",
            "bridge_transport_start",
            "bridge_transport_ready",
            "native_enter",
            "native_libs_loaded",
            "bootstrap_loaded",
            "user_script_entered",
            "first_stdout",
            "stop_requested",
            "drain_complete",
            "destroy_complete",
        )

        var previousElapsed = -1L
        for (index in 0 until timeline.length()) {
            val event = timeline.getJSONObject(index)
            assertEquals(index, event.getInt("index"))
            val elapsedMs = event.getLong("elapsedMs")
            assertTrue("Timeline elapsedMs must be monotonic at index $index", elapsedMs >= previousElapsed)
            previousElapsed = elapsedMs
            assertTrue(
                "Timeline event $index should carry execution id.",
                event.getJSONObject("details").getString("executionId").isNotBlank(),
            )
        }
    }

    @Test
    fun timeoutDoesNotPoisonNextEmbeddedScriptRun() {
        assumeEmbeddedScriptExecutionEnabled()

        val timeout = runEmbeddedScript(
            """
            "nodejs";
            setInterval(() => console.log("timeout.tick"), 50);
            console.log("timeout.started");
            """.trimIndent(),
            "<embedded-timeout-recovery-timeout-source.js>",
            timeoutMs = 1200L,
        )

        assertFalse(timeout.succeeded)
        assertTrue(timeout.timedOut)
        assertEquals("ERR_AUTOJS6_EMBEDDED_NODE_SCRIPT_TIMEOUT", timeout.errorCode)

        settleEmbeddedScriptServiceProcess()

        val recovery = runEmbeddedScript(
            """
            "nodejs";
            const fs = require("fs");
            fs.writeFile("./after-timeout.txt", "ok", "utf8", (writeError) => {
              if (writeError) throw writeError;
              fs.readFile("./after-timeout.txt", "utf8", (readError, text) => {
                if (readError) throw readError;
                console.log("after.timeout.node=" + process.version);
                console.log("after.timeout.fs=" + text);
              });
            });
            """.trimIndent(),
            "<embedded-timeout-recovery-success-source.js>",
        )

        assertTrue(recovery.errorMessage.orEmpty(), recovery.succeeded)
        assertFalse(recovery.timedOut)
        assertTrue(recovery.stdout.contains("after.timeout.node=v24.5.0"))
        assertTrue(recovery.stdout.contains("after.timeout.fs=ok"))
        assertFalse(recovery.stdout.contains("timeout.tick"))
    }

    @Test
    fun mixedPendingCallbackDrainWaitsForFsCryptoTimersAndPromiseResult() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-pending-drain-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create pending drain dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const crypto = require("crypto");
                return (async () => {
                  await new Promise((resolve, reject) => {
                    setImmediate(() => {
                      fs.writeFile("./drain.txt", "alpha", "utf8", (writeError) => {
                        if (writeError) return reject(writeError);
                        crypto.randomBytes(4, (cryptoError, bytes) => {
                          if (cryptoError) return reject(cryptoError);
                          setTimeout(() => {
                            fs.readFile("./drain.txt", "utf8", (readError, text) => {
                              if (readError) return reject(readError);
                              console.log("drain.order=fs>crypto>timer>read");
                              console.log("drain.text=" + text);
                              console.log("drain.bytes=" + bytes.length);
                              resolve();
                            });
                          }, 1);
                        });
                      });
                    });
                  });
                  console.log("drain.done");
                  return "drain-result";
                })();
                """.trimIndent(),
                "<embedded-pending-drain-source.js>",
                workingDirectory = scriptDir.absolutePath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertEquals("drain-result", result.resultText)
            assertFalse(result.timedOut)
            assertEquals(false, result.pendingTimers)
            assertEquals(0, result.pendingTimerCount ?: -1)
            assertEquals(0, result.pendingScopedFsCallbacks ?: -1)
            assertEquals(0, result.pendingCryptoCallbacks ?: -1)
            assertEquals(0, result.pendingAsyncCallbacks ?: -1)
            assertOutputOrder(
                result.stdout,
                "drain.order=fs>crypto>timer>read",
                "drain.text=alpha",
                "drain.bytes=4",
                "drain.done",
            )
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun embeddedScriptRunsAreIsolatedForGlobalsCacheAndProcessEnv() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-run-isolation-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create run isolation dir: $absolutePath" }
        }
        try {
            val scriptRoot = scriptDir.canonicalFile
            val state = File(scriptDir, "state.js").apply {
                writeText("""module.exports = { count: 0 };""", StandardCharsets.UTF_8)
            }
            val firstEntry = File(scriptRoot, "first.js")
            val secondEntry = File(scriptRoot, "second.js")
            val moduleSources = moduleSourcesFor(state)
            val first = runEmbeddedScript(
                """
                "nodejs";
                globalThis.__autojs6RunLeak = "bad";
                process.env.AUTOJS6_RUN_LEAK = "bad";
                const state = require("./state");
                state.count += 1;
                console.log("first.global=" + globalThis.__autojs6RunLeak);
                console.log("first.env=" + process.env.AUTOJS6_RUN_LEAK);
                console.log("first.count=" + state.count);
                console.log("first.cache=" + Boolean(require.cache[require.resolve("./state")]));
                """.trimIndent(),
                firstEntry.absolutePath,
                workingDirectory = scriptRoot.absolutePath,
                moduleSources = moduleSources,
            )

            assertTrue(first.errorMessage.orEmpty(), first.succeeded)
            assertTrue(first.stdout.contains("first.global=bad"))
            assertTrue(first.stdout.contains("first.env=bad"))
            assertTrue(first.stdout.contains("first.count=1"))
            assertTrue(first.stdout.contains("first.cache=true"))

            settleEmbeddedScriptServiceProcess()

            val second = runEmbeddedScript(
                """
                "nodejs";
                const resolved = require.resolve("./state");
                console.log("second.global=" + String(globalThis.__autojs6RunLeak));
                console.log("second.env=" + String(process.env.AUTOJS6_RUN_LEAK));
                console.log("second.cache.before=" + Boolean(require.cache[resolved]));
                const state = require("./state");
                console.log("second.count=" + state.count);
                console.log("second.cache.after=" + Boolean(require.cache[resolved]));
                """.trimIndent(),
                secondEntry.absolutePath,
                workingDirectory = scriptRoot.absolutePath,
                moduleSources = moduleSources,
            )

            assertTrue(second.errorMessage.orEmpty(), second.succeeded)
            assertTrue(second.stdout.contains("second.global=undefined"))
            assertTrue(second.stdout.contains("second.env=undefined"))
            assertTrue(second.stdout.contains("second.cache.before=false"))
            assertTrue(second.stdout.contains("second.count=0"))
            assertTrue(second.stdout.contains("second.cache.after=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

