    @Test
    fun consoleModuleProvidesScopedOutputAndConsoleConstructor() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-console-module-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create console module test dir: $absolutePath" }
        }
        try {
            val consoleShadow = File(scriptDir, "node_modules/console/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                """
                "nodejs";
                const consoleBuiltin = require("console");
                const nodeConsoleBuiltin = require("node:console");
                let stdoutCaptured = "";
                let stderrCaptured = "";
                let customStdout = "";
                let customStderr = "";
                let callableStdout = "";
                let callableStderr = "";
                const originalStdoutWrite = process.stdout.write;
                const originalStderrWrite = process.stderr.write;
                process.stdout.write = function(chunk) {
                  stdoutCaptured += String(chunk);
                  return true;
                };
                process.stderr.write = function(chunk) {
                  stderrCaptured += String(chunk);
                  return true;
                };
                let taskValue = "";
                try {
                  consoleBuiltin.log("module", "log");
                  consoleBuiltin.info("module", { value: 1 });
                  consoleBuiltin.debug("module", "debug");
                  consoleBuiltin.dir({ dir: true });
                  consoleBuiltin.table(["table"]);
                  consoleBuiltin.group("grouped");
                  consoleBuiltin.groupEnd();
                  consoleBuiltin.warn("module", "warn");
                  consoleBuiltin.error(new Error("module boom"));
                  consoleBuiltin.assert(false, "module assert", 42);
                  consoleBuiltin.count("items");
                  consoleBuiltin.count("items");
                  consoleBuiltin.countReset("items");
                  consoleBuiltin.time("phase");
                  consoleBuiltin.timeLog("phase", "middle");
                  consoleBuiltin.timeEnd("phase");
                  consoleBuiltin.trace("module trace");
                  taskValue = consoleBuiltin.createTask("task").run((value) => value + "-ok", "task");
                  consoleBuiltin.context("scope").log("context", "log");
                  const custom = new consoleBuiltin.Console({
                    stdout: {
                      write(chunk) {
                        customStdout += String(chunk);
                        return true;
                      }
                    },
                    stderr: {
                      write(chunk) {
                        customStderr += String(chunk);
                        return true;
                      }
                    }
                  });
                  custom.log("custom", "out");
                  custom.info("custom", { ok: true });
                  custom.warn("custom", "warn");
                  custom.error("custom", "err");
                  custom.count("custom-count");
                  custom.countReset("custom-count");
                  custom.time("custom-phase");
                  custom.timeEnd("custom-phase");
                  custom.trace("custom-trace");
                  const callable = consoleBuiltin.Console({
                    stdout: {
                      write(chunk) {
                        callableStdout += String(chunk);
                        return true;
                      }
                    },
                    stderr: {
                      write(chunk) {
                        callableStderr += String(chunk);
                        return true;
                      }
                    }
                  });
                  callable.log("callable", "out");
                  callable.error("callable", "err");
                } finally {
                  process.stdout.write = originalStdoutWrite;
                  process.stderr.write = originalStderrWrite;
                }
                const helperTypes = [
                  typeof consoleBuiltin.Console,
                  typeof consoleBuiltin.log,
                  typeof consoleBuiltin.info,
                  typeof consoleBuiltin.debug,
                  typeof consoleBuiltin.warn,
                  typeof consoleBuiltin.error,
                  typeof consoleBuiltin.dir,
                  typeof consoleBuiltin.dirxml,
                  typeof consoleBuiltin.table,
                  typeof consoleBuiltin.assert,
                  typeof consoleBuiltin.count,
                  typeof consoleBuiltin.countReset,
                  typeof consoleBuiltin.time,
                  typeof consoleBuiltin.timeLog,
                  typeof consoleBuiltin.timeEnd,
                  typeof consoleBuiltin.trace,
                  typeof consoleBuiltin.clear,
                  typeof consoleBuiltin.group,
                  typeof consoleBuiltin.groupCollapsed,
                  typeof consoleBuiltin.groupEnd,
                  typeof consoleBuiltin.context,
                  typeof consoleBuiltin.createTask,
                  typeof consoleBuiltin.profile,
                  typeof consoleBuiltin.profileEnd,
                  typeof consoleBuiltin.timeStamp
                ].join(",");
                console.log("console.same=" + (consoleBuiltin === nodeConsoleBuiltin));
                console.log("console.shadow=" + (consoleBuiltin.shadow === true));
                console.log("console.frozen=" + Object.isFrozen(consoleBuiltin));
                console.log("console.prototype_frozen=" + Object.isFrozen(consoleBuiltin.Console.prototype));
                console.log("console.keys=" + Object.keys(consoleBuiltin).sort().join(","));
                console.log("console.prototype=" + Object.keys(consoleBuiltin.Console.prototype).sort().join(","));
                console.log("console.helpers=" + helperTypes);
                console.log("console.hidden=" + [
                  typeof consoleBuiltin._stdout,
                  typeof consoleBuiltin._stderr,
                  typeof consoleBuiltin._times,
                  typeof consoleBuiltin.Console._stdout
                ].join(","));
                console.log("console.stdout=" + (
                  stdoutCaptured.includes("module log") &&
                  stdoutCaptured.includes("module {\"value\":1}") &&
                  stdoutCaptured.includes("module debug") &&
                  stdoutCaptured.includes("{\"dir\":true}") &&
                  stdoutCaptured.includes("[\"table\"]") &&
                  stdoutCaptured.includes("grouped") &&
                  stdoutCaptured.includes("items: 1") &&
                  stdoutCaptured.includes("items: 2") &&
                  stdoutCaptured.includes("phase:") &&
                  stdoutCaptured.includes("middle") &&
                  stdoutCaptured.includes("context log")
                ));
                console.log("console.stderr=" + (
                  stderrCaptured.includes("module warn") &&
                  stderrCaptured.includes("Error: module boom") &&
                  stderrCaptured.includes("Assertion failed: module assert 42") &&
                  stderrCaptured.includes("Trace: module trace")
                ));
                console.log("console.custom=" + (
                  customStdout.includes("custom out") &&
                  customStdout.includes("custom {\"ok\":true}") &&
                  customStdout.includes("custom-count: 1") &&
                  customStdout.includes("custom-phase:") &&
                  customStderr.includes("custom warn") &&
                  customStderr.includes("custom err") &&
                  customStderr.includes("Trace: custom-trace") &&
                  callableStdout.includes("callable out") &&
                  callableStderr.includes("callable err")
                ));
                console.log("console.task=" + taskValue);
                console.log("console.resolve=" + [
                  require.resolve("console"),
                  require.resolve("node:console")
                ].join("|"));
                """.trimIndent(),
                "<embedded-console-module-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(consoleShadow),
            )

            assertTrue(result.errorMessage.orEmpty() + "\n" + result.stdout, result.succeeded)
            assertTrue(result.stdout.contains("console.same=true"))
            assertTrue(result.stdout.contains("console.shadow=false"))
            assertTrue(result.stdout.contains("console.frozen=true"))
            assertTrue(result.stdout.contains("console.prototype_frozen=true"))
            assertTrue(result.stdout.contains("console.keys=Console,assert,clear,context,count,countReset,createTask,debug,dir,dirxml,error,group,groupCollapsed,groupEnd,info,log,profile,profileEnd,table,time,timeEnd,timeLog,timeStamp,trace,warn"))
            assertTrue(result.stdout.contains("console.prototype=assert,clear,count,countReset,debug,dir,dirxml,error,group,groupCollapsed,groupEnd,info,log,table,time,timeEnd,timeLog,trace,warn"))
            assertTrue(result.stdout.contains("console.helpers=function,function,function,function,function,function,function,function,function,function,function,function,function,function,function,function,function,function,function,function,function,function,function,function,function"))
            assertTrue(result.stdout.contains("console.hidden=undefined,undefined,undefined,undefined"))
            assertTrue(result.stdout.contains("console.stdout=true"))
            assertTrue(result.stdout.contains("console.stderr=true"))
            assertTrue(result.stdout.contains("console.custom=true"))
            assertTrue(result.stdout.contains("console.task=task-ok"))
            assertTrue(result.stdout.contains("console.resolve=console|console"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun assertCompatibilitySweepSupportsLimitedWrapperAliasesStrictAndAsync() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-assert-compat-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create assert compatibility test dir: $absolutePath" }
        }
        try {
            val assertShadow = File(scriptDir, "node_modules/assert/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val result = runEmbeddedScript(
                """
                "nodejs";
                return (async function() {
                  const assert = require("assert");
                  const nodeAssert = require("node:assert");
                  const strict = require("assert/strict");
                  const nodeStrict = require("node:assert/strict");
                  const helperTypes = [
                    typeof assert,
                    typeof assert.AssertionError,
                    typeof assert.ok,
                    typeof assert.fail,
                    typeof assert.equal,
                    typeof assert.notEqual,
                    typeof assert.deepEqual,
                    typeof assert.notDeepEqual,
                    typeof assert.deepStrictEqual,
                    typeof assert.notDeepStrictEqual,
                    typeof assert.strictEqual,
                    typeof assert.notStrictEqual,
                    typeof assert.partialDeepStrictEqual,
                    typeof assert.match,
                    typeof assert.doesNotMatch,
                    typeof assert.throws,
                    typeof assert.rejects,
                    typeof assert.doesNotThrow,
                    typeof assert.doesNotReject,
                    typeof assert.ifError,
                    typeof assert.strict
                  ].join(",");
                  const expectedHelperTypes = "function,function,function,function,function,function,function,function,function,function,function,function,function,function,function,function,function,function,function,function,function";
                  const hidden = [
                    typeof assert.CallTracker,
                    typeof assert.Assert,
                    typeof strict.CallTracker,
                    typeof strict.Assert
                  ].join(",");
                  assert(true);
                  assert.ok(true);
                  assert.equal("1", 1);
                  assert.notEqual("1", 2);
                  assert.deepEqual({ a: "1" }, { a: 1 });
                  assert.notDeepEqual({ a: 1 }, { a: 2 });
                  assert.deepStrictEqual({ a: 1 }, { a: 1 });
                  assert.notDeepStrictEqual({ a: 1 }, { a: 2 });
                  assert.strictEqual(1, 1);
                  assert.notStrictEqual(1, "1");
                  assert.partialDeepStrictEqual({ a: 1, nested: { value: 2 } }, { nested: { value: 2 } });
                  assert.match("assert-ready", /ready/);
                  assert.doesNotMatch("assert-ready", /missing/);
                  assert.throws(() => { throw new Error("assert throw"); }, /assert throw/);
                  assert.doesNotThrow(() => true);
                  assert.ifError(null);
                  strict.equal(1, 1);
                  strict.deepEqual({ a: 1 }, { a: 1 });
                  await assert.rejects(Promise.reject(new Error("assert reject")), /assert reject/);
                  await assert.doesNotReject(Promise.resolve("ok"));
                  let failure = "";
                  try {
                    strict.strictEqual(1, 2, "strict boom");
                  } catch (error) {
                    failure = [
                      error.name,
                      error.code,
                      error instanceof assert.AssertionError,
                      String(error.message).includes("strict boom")
                    ].join("/");
                  }
                  console.log("assert.same=" + (assert === nodeAssert));
                  console.log("assert.strict.same=" + (strict === nodeStrict && assert.strict === strict && strict.strict === strict));
                  console.log("assert.shadow=" + (assert.shadow === true || strict.shadow === true));
                  console.log("assert.frozen=" + (Object.isFrozen(assert) && Object.isFrozen(strict)));
                  console.log("assert.helpers=" + (helperTypes === expectedHelperTypes) + "/" + helperTypes);
                  console.log("assert.hidden=" + hidden);
                  console.log("assert.failure=" + failure);
                  console.log("assert.resolve=" + [
                    require.resolve("assert"),
                    require.resolve("node:assert"),
                    require.resolve("assert/strict"),
                    require.resolve("node:assert/strict")
                  ].join("|"));
                  console.log("assert.async=true");
                })();
                """.trimIndent(),
                "<embedded-assert-compat-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(assertShadow),
            )

            assertTrue(result.errorMessage.orEmpty() + "\n" + result.stdout, result.succeeded)
            assertTrue(result.stdout.contains("assert.same=true"))
            assertTrue(result.stdout.contains("assert.strict.same=true"))
            assertTrue(result.stdout.contains("assert.shadow=false"))
            assertTrue(result.stdout.contains("assert.frozen=true"))
            assertTrue(result.stdout.contains("assert.helpers=true/"))
            assertTrue(result.stdout.contains("assert.hidden=undefined,undefined,undefined,undefined"))
            assertTrue(result.stdout.contains("assert.failure=AssertionError/ERR_ASSERTION/true/true"))
            assertTrue(result.stdout.contains("assert.resolve=assert|assert|assert/strict|assert/strict"))
            assertTrue(result.stdout.contains("assert.async=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun eventsTimersAndProcessWarningCompatibilitySurfaceWorks() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-events-timers-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create events/timers test dir: $absolutePath" }
        }
        try {
            val eventsShadow = File(scriptDir, "node_modules/events/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val timersShadow = File(scriptDir, "node_modules/timers/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val timersPromisesShadow = File(scriptDir, "node_modules/timers/promises.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                """
                "nodejs";
                const events = require("events");
                const nodeEvents = require("node:events");
                const timers = require("timers");
                const nodeTimers = require("node:timers");
                const timerPromises = require("timers/promises");
                const nodeTimerPromises = require("node:timers/promises");
                const emitter = new events.EventEmitter();
                let count = 0;
                function listener(value) {
                  count += value;
                }
                emitter.on("inc", listener);
                emitter.emit("inc", 1);
                emitter.off("inc", listener);
                emitter.emit("inc", 100);
                emitter.once("once", () => {
                  count += 10;
                });
                emitter.emit("once");
                emitter.emit("once");
                emitter.on("remove", () => {});
                emitter.removeAllListeners("remove");
                const callableEmitter = new events();
                let callableValue = "";
                callableEmitter.on("callable", (value) => {
                  callableValue = value;
                });
                callableEmitter.emit("callable", "callable-ok");
                const listenerSnapshotOk =
                  events.getEventListeners(emitter, "inc").length === 0 &&
                  events.listenerCount(emitter, "inc") === 0;
                events.setMaxListeners(3, emitter);
                const maxListenersOk = events.getMaxListeners(emitter) === 3;
                const monitored = [];
                const errorEmitter = new events.EventEmitter();
                errorEmitter.on(events.errorMonitor, (error) => {
                  monitored.push("monitor:" + error.message);
                });
                errorEmitter.on("error", (error) => {
                  monitored.push("handler:" + error.message);
                });
                errorEmitter.emit("error", new Error("monitored boom"));
                const onceErrorEmitter = new events.EventEmitter();
                const onceErrorPromise = events.once(onceErrorEmitter, "ready").then(
                  () => false,
                  (error) => error.message === "once boom"
                );
                timers.setImmediate(() => {
                  onceErrorEmitter.emit("error", new Error("once boom"));
                });
                const iteratorPromise = (async () => {
                  const iteratorEmitter = new events.EventEmitter();
                  const values = [];
                  const iterator = events.on(iteratorEmitter, "item");
                  timers.setImmediate(() => {
                    iteratorEmitter.emit("item", "a");
                    iteratorEmitter.emit("item", "b");
                  });
                  for await (const args of iterator) {
                    values.push(args[0]);
                    if (values.length === 2) break;
                  }
                  return values.join("|") + "/" + iteratorEmitter.listenerCount("item");
                })();
                let abortSeen = 0;
                const addAbortListenerSignal = {
                  aborted: false,
                  listener: null,
                  removed: false,
                  addEventListener(name, listener) {
                    if (name === "abort") this.listener = listener;
                  },
                  removeEventListener(name, listener) {
                    if (name === "abort" && this.listener === listener) this.removed = true;
                  }
                };
                const abortDisposable = events.addAbortListener(addAbortListenerSignal, () => {
                  abortSeen += 1;
                });
                addAbortListenerSignal.aborted = true;
                addAbortListenerSignal.listener.call(addAbortListenerSignal, { type: "abort" });
                if (abortDisposable && typeof abortDisposable[Symbol.dispose] === "function") {
                  abortDisposable[Symbol.dispose]();
                }
                const oncePromise = events.once(emitter, "ready").then((args) => {
                  console.log("events.once.value=" + args[0]);
                });
                const warnings = [];
                function warningListener(warning) {
                  warnings.push(warning);
                  console.log(
                    "warning.shape=" +
                      (warning instanceof Error) +
                      "/" +
                      warning.name +
                      "/" +
                      warning.message.includes("legacy api") +
                      "/" +
                      warning.code
                  );
                }
                process.on("warning", warningListener);
                process.emitWarning("legacy api", "DeprecationWarning", "AUTOJS6_TEST");
                process.nextTick(() => {
                  process.off("warning", warningListener);
                  process.emitWarning("ignored warning", "Warning", "AUTOJS6_IGNORED");
                });
                timers.setImmediate(() => {
                  console.log("timers.immediate=true");
                });
                const timeout = timers.setTimeout(() => {
                  console.log("timers.should-not-run");
                }, 0);
                timers.clearTimeout(timeout);
                let intervalCount = 0;
                const interval = timers.setInterval(() => {
                  intervalCount += 1;
                  if (intervalCount === 2) {
                    timers.clearInterval(interval);
                    console.log("timers.interval.done=true");
                    emitter.emit("ready", "ok");
                  }
                }, 1);
                timers.setImmediate(() => {
                  console.log("warning.count=" + warnings.length);
                });
                const promiseTimeout = timerPromises.setTimeout(1, "timeout-ok");
                const promiseImmediate = timerPromises.setImmediate("immediate-ok");
                const schedulerPromise = timerPromises.scheduler.wait(1).then(() => {
                  return timerPromises.scheduler.yield();
                }).then(() => "scheduler-ok");
                const abortSignal = {
                  aborted: false,
                  listener: null,
                  removed: false,
                  addEventListener(name, listener) {
                    if (name === "abort") this.listener = listener;
                  },
                  removeEventListener(name, listener) {
                    if (name === "abort" && this.listener === listener) this.removed = true;
                  }
                };
                const abortedPromise = timerPromises.setTimeout(20, "abort-bad", { signal: abortSignal }).then(
                  () => "abort-false",
                  (error) => [
                    error.name,
                    error.code,
                    String(error.message).includes("aborted"),
                    abortSignal.removed
                  ].join("/")
                );
                abortSignal.aborted = true;
                abortSignal.listener.call(abortSignal, { type: "abort" });
                const intervalPromise = (async () => {
                  const values = [];
                  for await (const value of timerPromises.setInterval(1, "interval-ok")) {
                    values.push(value);
                    if (values.length === 2) break;
                  }
                  return values.join("|");
                })();
                for (const name of [
                  "child_process",
                  "worker_threads"
                ]) {
                  try {
                    require(name);
                    console.log("events.timers.denied." + name + "=false");
                  } catch (error) {
                    console.log("events.timers.denied." + name + "=" + error.message.includes(name));
                  }
                }
                try {
                  process.getBuiltinModule("timers");
                  console.log("events.timers.getBuiltinModule=false");
                } catch (error) {
                  console.log("events.timers.getBuiltinModule=" + error.message.includes("disabled"));
                }
                Promise.all([
                  oncePromise,
                  iteratorPromise,
                  onceErrorPromise,
                  promiseTimeout,
                  promiseImmediate,
                  schedulerPromise,
                  abortedPromise,
                  intervalPromise
                ]).then((results) => {
                  console.log("events.same=" + (events === nodeEvents));
                  console.log("events.callable=" + (callableValue === "callable-ok" && events === events.EventEmitter));
                  console.log("events.shadow=" + (events.shadow === true));
                  console.log("events.frozen=" + Object.isFrozen(events));
                  console.log("events.count=" + count);
                  console.log("events.listenerCount=" + emitter.listenerCount("inc"));
                  console.log("events.listeners=" + emitter.listeners("inc").length);
                  console.log("events.listenerHelpers=" + (listenerSnapshotOk && maxListenersOk));
                  console.log("events.removeAll=" + emitter.listenerCount("remove"));
                  console.log("events.once.type=" + typeof events.once);
                  console.log("events.on.type=" + typeof events.on);
                  console.log("events.helper.types=" + [
                    typeof events.getEventListeners,
                    typeof events.getMaxListeners,
                    typeof events.setMaxListeners,
                    typeof events.addAbortListener,
                    typeof events.errorMonitor,
                    typeof events.captureRejectionSymbol
                  ].join(","));
                  console.log("events.errorMonitor=" + monitored.join("|"));
                  console.log("events.iterator=" + results[1]);
                  console.log("events.once.error=" + results[2]);
                  console.log("events.abort=" + (abortSeen === 1 && addAbortListenerSignal.removed === true));
                  console.log("events.hidden=" + typeof events.EventEmitterAsyncResource);
                  console.log("events.defaultMaxListeners=" + (typeof events.defaultMaxListeners));
                  console.log("timers.same=" + (timers === nodeTimers));
                  console.log("timers.shadow=" + (timers.shadow === true));
                  console.log("timers.frozen=" + Object.isFrozen(timers));
                  console.log("timers.hidden=" + [typeof timers.promises, typeof timers.enroll].join(","));
                  console.log("timers.promises.same=" + (timerPromises === nodeTimerPromises));
                  console.log("timers.promises.shadow=" + (timerPromises.shadow === true));
                  console.log("timers.promises.frozen=" + Object.isFrozen(timerPromises));
                  console.log("timers.promises.schedulerFrozen=" + Object.isFrozen(timerPromises.scheduler));
                  console.log("timers.promises.types=" + [
                    typeof timerPromises.setTimeout,
                    typeof timerPromises.setImmediate,
                    typeof timerPromises.setInterval,
                    typeof timerPromises.scheduler,
                    typeof timerPromises.scheduler.wait,
                    typeof timerPromises.scheduler.yield
                  ].join(","));
                  console.log("timers.promises.results=" + results.slice(3).join("|"));
                  console.log("timers.promises.resolve=" + [
                    require.resolve("timers/promises"),
                    require.resolve("node:timers/promises")
                  ].join("|"));
                });
                """.trimIndent(),
                "<embedded-events-timers-warning-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(eventsShadow, timersShadow, timersPromisesShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("warning.shape=true/DeprecationWarning/true/AUTOJS6_TEST"))
            assertTrue(result.stdout.contains("warning.count=1"))
            assertTrue(result.stdout.contains("timers.immediate=true"))
            assertTrue(result.stdout.contains("timers.interval.done=true"))
            assertFalse(result.stdout.contains("timers.should-not-run"))
            assertTrue(result.stdout.contains("events.once.value=ok"))
            assertTrue(result.stdout.contains("events.same=true"))
            assertTrue(result.stdout.contains("events.callable=true"))
            assertTrue(result.stdout.contains("events.shadow=false"))
            assertTrue(result.stdout.contains("events.frozen=true"))
            assertTrue(result.stdout.contains("events.count=11"))
            assertTrue(result.stdout.contains("events.listenerCount=0"))
            assertTrue(result.stdout.contains("events.listeners=0"))
            assertTrue(result.stdout.contains("events.listenerHelpers=true"))
            assertTrue(result.stdout.contains("events.removeAll=0"))
            assertTrue(result.stdout.contains("events.once.type=function"))
            assertTrue(result.stdout.contains("events.on.type=function"))
            assertTrue(result.stdout.contains("events.helper.types=function,function,function,function,symbol,symbol"))
            assertTrue(result.stdout.contains("events.errorMonitor=monitor:monitored boom|handler:monitored boom"))
            assertTrue(result.stdout.contains("events.iterator=a|b/0"))
            assertTrue(result.stdout.contains("events.once.error=true"))
            assertTrue(result.stdout.contains("events.abort=true"))
            assertTrue(result.stdout.contains("events.hidden=undefined"))
            assertTrue(result.stdout.contains("events.defaultMaxListeners=number"))
            assertTrue(result.stdout.contains("timers.same=true"))
            assertTrue(result.stdout.contains("timers.shadow=false"))
            assertTrue(result.stdout.contains("timers.frozen=true"))
            assertTrue(result.stdout.contains("timers.hidden=undefined,undefined"))
            assertTrue(result.stdout.contains("timers.promises.same=true"))
            assertTrue(result.stdout.contains("timers.promises.shadow=false"))
            assertTrue(result.stdout.contains("timers.promises.frozen=true"))
            assertTrue(result.stdout.contains("timers.promises.schedulerFrozen=true"))
            assertTrue(result.stdout.contains("timers.promises.types=function,function,function,object,function,function"))
            assertTrue(result.stdout.contains("timers.promises.results=timeout-ok|immediate-ok|scheduler-ok|AbortError/ABORT_ERR/true/true|interval-ok|interval-ok"))
            assertTrue(result.stdout.contains("timers.promises.resolve=timers/promises|timers/promises"))
            listOf(
                "child_process",
                "worker_threads",
            ).forEach { name ->
                assertTrue(result.stdout.contains("events.timers.denied.$name=true"))
            }
            assertTrue(result.stdout.contains("events.timers.getBuiltinModule=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun asyncHooksAndDiagnosticsChannelExposeScopedContextAndPublishSubscribe() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-async-diagnostics-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create async diagnostics test dir: $absolutePath" }
        }
        try {
            val asyncHooksShadow = File(scriptDir, "node_modules/async_hooks/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val diagnosticsShadow = File(scriptDir, "node_modules/diagnostics_channel/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                """
                "nodejs";
                const asyncHooks = require("async_hooks");
                const nodeAsyncHooks = require("node:async_hooks");
                const diagnostics = require("diagnostics_channel");
                const nodeDiagnostics = require("node:diagnostics_channel");

                const asyncLocalStorage = new asyncHooks.AsyncLocalStorage();
                const asyncResult = asyncLocalStorage.run({ value: "context" }, async () => {
                  const promiseValue = await Promise.resolve().then(() => asyncLocalStorage.getStore().value);
                  const resource = new asyncHooks.AsyncResource("autojs6.async.test");
                  const resourceValue = await new Promise((resolve) => {
                    resource.runInAsyncScope(() => {
                      resolve(asyncLocalStorage.getStore().value);
                    });
                  });
                  resource.emitDestroy();
                  return [
                    promiseValue,
                    resourceValue,
                    typeof resource.asyncId,
                    typeof resource.triggerAsyncId,
                    typeof resource.runInAsyncScope,
                    typeof resource.emitDestroy
                  ].join("|");
                });

                const channel = diagnostics.channel("autojs6.diagnostics");
                const nodeChannel = nodeDiagnostics.channel("autojs6.diagnostics");
                const seen = [];
                function listener(message, name) {
                  seen.push(name + ":" + message.value);
                }
                function globalListener(message, name) {
                  seen.push("global:" + name + ":" + message.value);
                }
                channel.subscribe(listener);
                diagnostics.subscribe("autojs6.diagnostics", globalListener);
                const hasSubscribersBefore = channel.hasSubscribers && diagnostics.hasSubscribers("autojs6.diagnostics");
                channel.publish({ value: "one" });
                diagnostics.unsubscribe("autojs6.diagnostics", globalListener);
                channel.unsubscribe(listener);
                const hasSubscribersAfter = channel.hasSubscribers;
                channel.publish({ value: "after" });

                const tracing = diagnostics.tracingChannel("autojs6.trace");
                const traceSeen = [];
                tracing.start.subscribe((message, name) => {
                  traceSeen.push("start:" + name + ":" + message.value);
                });
                tracing.end.subscribe((message, name) => {
                  traceSeen.push("end:" + name + ":" + message.result);
                });
                const traceValue = tracing.traceSync(() => "trace-ok", { value: "trace" });

                return asyncResult.then((asyncSummary) => {
                  console.log("async_hooks.same=" + (asyncHooks === nodeAsyncHooks));
                  console.log("async_hooks.shadow=" + (asyncHooks.shadow === true));
                  console.log("async_hooks.frozen=" + Object.isFrozen(asyncHooks));
                  console.log("async_hooks.context=" + asyncSummary);
                  console.log("async_hooks.helpers=" + [
                    typeof asyncHooks.AsyncLocalStorage,
                    typeof asyncHooks.AsyncResource,
                    typeof asyncHooks.createHook,
                    typeof asyncHooks.executionAsyncId,
                    typeof asyncHooks.executionAsyncResource,
                    typeof asyncHooks.asyncWrapProviders
                  ].join(","));
                  console.log("async_hooks.resolve=" + [
                    require.resolve("async_hooks"),
                    require.resolve("node:async_hooks")
                  ].join("|"));
                  console.log("diagnostics.same=" + (diagnostics === nodeDiagnostics));
                  console.log("diagnostics.shadow=" + (diagnostics.shadow === true));
                  console.log("diagnostics.frozen=" + Object.isFrozen(diagnostics));
                  console.log("diagnostics.channel_same=" + (channel === nodeChannel));
                  console.log("diagnostics.events=" + seen.join("|"));
                  console.log("diagnostics.hasSubscribers=" + hasSubscribersBefore + "/" + hasSubscribersAfter);
                  console.log("diagnostics.tracing=" + traceValue + "/" + traceSeen.join("|"));
                  console.log("diagnostics.helpers=" + [
                    typeof diagnostics.channel,
                    typeof diagnostics.hasSubscribers,
                    typeof diagnostics.subscribe,
                    typeof diagnostics.unsubscribe,
                    typeof diagnostics.tracingChannel,
                    typeof diagnostics.Channel,
                    typeof channel.publish,
                    typeof channel.subscribe,
                    typeof channel.unsubscribe,
                    typeof channel._subscribers,
                    typeof tracing.traceSync,
                    typeof tracing.tracePromise,
                    typeof tracing.traceCallback
                  ].join(","));
                  console.log("diagnostics.resolve=" + [
                    require.resolve("diagnostics_channel"),
                    require.resolve("node:diagnostics_channel")
                  ].join("|"));
                });
                """.trimIndent(),
                "<embedded-async-diagnostics-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(asyncHooksShadow, diagnosticsShadow),
            )

            assertTrue(result.errorMessage.orEmpty() + "\n" + result.stdout, result.succeeded)
            assertTrue(result.stdout.contains("async_hooks.same=true"))
            assertTrue(result.stdout.contains("async_hooks.shadow=false"))
            assertTrue(result.stdout.contains("async_hooks.frozen=true"))
            assertTrue(result.stdout.contains("async_hooks.context=context|context|function|function|function|function"))
            assertTrue(result.stdout.contains("async_hooks.helpers=function,function,undefined,undefined,undefined,undefined"))
            assertTrue(result.stdout.contains("async_hooks.resolve=async_hooks|async_hooks"))
            assertTrue(result.stdout.contains("diagnostics.same=true"))
            assertTrue(result.stdout.contains("diagnostics.shadow=false"))
            assertTrue(result.stdout.contains("diagnostics.frozen=true"))
            assertTrue(result.stdout.contains("diagnostics.channel_same=true"))
            assertTrue(result.stdout.contains("diagnostics.events=autojs6.diagnostics:one|global:autojs6.diagnostics:one"))
            assertTrue(result.stdout.contains("diagnostics.hasSubscribers=true/false"))
            assertTrue(result.stdout.contains("diagnostics.tracing=trace-ok/start:tracing:autojs6.trace:start:trace|end:tracing:autojs6.trace:end:trace-ok"))
            assertTrue(result.stdout.contains("diagnostics.helpers=function,function,function,function,function,undefined,function,function,function,undefined,function,function,function"))
            assertTrue(result.stdout.contains("diagnostics.resolve=diagnostics_channel|diagnostics_channel"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun perfHooksExposeScopedPerformanceMarksAndObserver() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-perf-hooks-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create perf hooks test dir: $absolutePath" }
        }
        try {
            val perfHooksShadow = File(scriptDir, "node_modules/perf_hooks/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                """
                "nodejs";
                const perfHooks = require("perf_hooks");
                const nodePerfHooks = require("node:perf_hooks");
                const performance = perfHooks.performance;
                const nowA = performance.now();
                performance.mark("autojs6-start");
                performance.mark("autojs6-end");
                performance.measure("autojs6-measure", "autojs6-start", "autojs6-end");
                const markEntries = performance.getEntriesByType("mark").filter((entry) => entry.name.indexOf("autojs6-") === 0);
                const measureEntries = performance.getEntriesByName("autojs6-measure", "measure");
                const observed = new Promise((resolve) => {
                  const observer = new perfHooks.PerformanceObserver((list) => {
                    const summary = list.getEntries().map((entry) => entry.name + ":" + entry.entryType).join("|");
                    observer.disconnect();
                    resolve(summary);
                  });
                  observer.observe({ entryTypes: ["mark", "measure"] });
                  performance.mark("autojs6-observed-start");
                  performance.mark("autojs6-observed-end");
                  performance.measure("autojs6-observed-measure", "autojs6-observed-start", "autojs6-observed-end");
                });
                return observed.then((observedSummary) => {
                  const nowB = performance.now();
                  const json = performance.toJSON();
                  const eluBefore = performance.eventLoopUtilization();
                  const eluDelta = performance.eventLoopUtilization(eluBefore);
                  console.log("perf_hooks.same=" + (perfHooks === nodePerfHooks));
                  console.log("perf_hooks.shadow=" + (perfHooks.shadow === true));
                  console.log("perf_hooks.frozen=" + Object.isFrozen(perfHooks));
                  console.log("perf_hooks.performance_frozen=" + Object.isFrozen(performance));
                  console.log("perf_hooks.now=" + (typeof nowA === "number" && nowB >= nowA));
                  console.log("perf_hooks.entries=" + (
                    markEntries.length >= 2 &&
                    measureEntries.length === 1 &&
                    measureEntries[0].entryType === "measure"
                  ));
                  console.log("perf_hooks.observer=" + (
                    observedSummary.includes("autojs6-observed-start:mark") &&
                    observedSummary.includes("autojs6-observed-measure:measure")
                  ));
                  console.log("perf_hooks.supported=" + (
                    Object.isFrozen(perfHooks.PerformanceObserver.supportedEntryTypes) &&
                    perfHooks.PerformanceObserver.supportedEntryTypes.join(",")
                  ));
                  console.log("perf_hooks.elu=" + [
                    typeof performance.eventLoopUtilization,
                    Object.isFrozen(eluBefore),
                    Object.isFrozen(eluDelta),
                    typeof eluBefore.idle,
                    typeof eluDelta.active,
                    typeof eluDelta.utilization
                  ].join(","));
                  console.log("perf_hooks.helpers=" + [
                    typeof perfHooks.performance,
                    typeof performance.now,
                    typeof performance.mark,
                    typeof performance.measure,
                    typeof performance.getEntries,
                    typeof performance.getEntriesByName,
                    typeof performance.getEntriesByType,
                    typeof performance.clearMarks,
                    typeof performance.clearMeasures,
                    typeof performance.timeOrigin,
                    typeof perfHooks.PerformanceObserver,
                    typeof perfHooks.PerformanceEntry,
                    typeof perfHooks.PerformanceMark,
                    typeof perfHooks.PerformanceMeasure
                  ].join(","));
                  console.log("perf_hooks.hidden=" + [
                    typeof perfHooks.monitorEventLoopDelay,
                    typeof perfHooks.createHistogram,
                    typeof perfHooks.timerify,
                    typeof perfHooks.eventLoopUtilization,
                    typeof performance.timerify,
                    typeof performance.nodeTiming,
                    typeof performance.markResourceTiming
                  ].join(","));
                  console.log("perf_hooks.toJSON=" + (typeof json.timeOrigin === "number"));
                  console.log("perf_hooks.resolve=" + [
                    require.resolve("perf_hooks"),
                    require.resolve("node:perf_hooks")
                  ].join("|"));
                  performance.clearMarks("autojs6-start");
                  performance.clearMarks("autojs6-end");
                  performance.clearMarks("autojs6-observed-start");
                  performance.clearMarks("autojs6-observed-end");
                  performance.clearMeasures("autojs6-measure");
                  performance.clearMeasures("autojs6-observed-measure");
                });
                """.trimIndent(),
                "<embedded-perf-hooks-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(perfHooksShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("perf_hooks.same=true"))
            assertTrue(result.stdout.contains("perf_hooks.shadow=false"))
            assertTrue(result.stdout.contains("perf_hooks.frozen=true"))
            assertTrue(result.stdout.contains("perf_hooks.performance_frozen=true"))
            assertTrue(result.stdout.contains("perf_hooks.now=true"))
            assertTrue(result.stdout.contains("perf_hooks.entries=true"))
            assertTrue(result.stdout.contains("perf_hooks.observer=true"))
            assertTrue(result.stdout.contains("perf_hooks.supported=mark,measure"))
            assertTrue(result.stdout.contains("perf_hooks.elu=function,true,true,number,number,number"))
            assertTrue(result.stdout.contains("perf_hooks.helpers=object,function,function,function,function,function,function,function,function,number,function,function,function,function"))
            assertTrue(result.stdout.contains("perf_hooks.hidden=undefined,undefined,undefined,undefined,undefined,undefined,undefined"))
            assertTrue(result.stdout.contains("perf_hooks.toJSON=true"))
            assertTrue(result.stdout.contains("perf_hooks.resolve=perf_hooks|perf_hooks"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun v8BuiltinExposesScopedSerializationAndReadOnlyStats() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-v8-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create v8 test dir: $absolutePath" }
        }
        try {
            val v8Shadow = File(scriptDir, "node_modules/v8/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                """
                "nodejs";
                const v8 = require("v8");
                const nodeV8 = require("node:v8");
                const value = {
                  text: "hello",
                  list: [1, 2, 3],
                  nested: { ok: true },
                  map: new Map([["k", "v"]]),
                  date: new Date(1234),
                  big: 42n
                };
                const serialized = v8.serialize(value);
                const restored = v8.deserialize(serialized);
                const heap = v8.getHeapStatistics();
                const spaces = v8.getHeapSpaceStatistics();
                const code = v8.getHeapCodeStatistics();
                const helperTypes = [
                  typeof v8.cachedDataVersionTag,
                  typeof v8.serialize,
                  typeof v8.deserialize,
                  typeof v8.getHeapStatistics,
                  typeof v8.getHeapSpaceStatistics,
                  typeof v8.getHeapCodeStatistics,
                  typeof v8.isStringOneByteRepresentation
                ].join(",");
                const hiddenTypes = [
                  typeof v8.Serializer,
                  typeof v8.Deserializer,
                  typeof v8.DefaultSerializer,
                  typeof v8.DefaultDeserializer,
                  typeof v8.setFlagsFromString,
                  typeof v8.getHeapSnapshot,
                  typeof v8.writeHeapSnapshot,
                  typeof v8.takeCoverage,
                  typeof v8.stopCoverage,
                  typeof v8.promiseHooks,
                  typeof v8.startupSnapshot,
                  typeof v8.setHeapSnapshotNearHeapLimit,
                  typeof v8.GCProfiler,
                  typeof v8.queryObjects,
                  typeof v8.startCpuProfile,
                  typeof v8.getCppHeapStatistics
                ].join(",");
                function rejectsOutOfRange(action) {
                  try {
                    action();
                    return false;
                  } catch (error) {
                    return error && error.code === "ERR_OUT_OF_RANGE";
                  }
                }
                const deserializeLimitOk = rejectsOutOfRange(() => v8.deserialize(Buffer.alloc(1024 * 1024 + 1)));
                const serializeLimitOk = rejectsOutOfRange(() => v8.serialize("x".repeat(1024 * 1024)));
                console.log("v8.same=" + (v8 === nodeV8));
                console.log("v8.shadow=" + (v8.shadow === true));
                console.log("v8.frozen=" + Object.isFrozen(v8));
                console.log("v8.keys=" + Object.keys(v8).sort().join(","));
                console.log("v8.helpers=" + helperTypes);
                console.log("v8.hidden=" + hiddenTypes);
                console.log("v8.serialized=" + (
                  Buffer.isBuffer(serialized) &&
                  restored.text === "hello" &&
                  restored.list.join("|") === "1|2|3" &&
                  restored.nested.ok === true &&
                  restored.map instanceof Map &&
                  restored.map.get("k") === "v" &&
                  restored.date instanceof Date &&
                  restored.date.getTime() === 1234 &&
                  restored.big === 42n
                ));
                console.log("v8.stats=" + (
                  Object.isFrozen(heap) &&
                  Object.isFrozen(spaces) &&
                  spaces.length > 0 &&
                  Object.isFrozen(spaces[0]) &&
                  Object.isFrozen(code) &&
                  typeof heap.total_heap_size === "number" &&
                  typeof spaces[0].space_name === "string" &&
                  typeof spaces[0].space_size === "number" &&
                  typeof code.code_and_metadata_size === "number"
                ));
                console.log("v8.one_byte=" + (
                  v8.isStringOneByteRepresentation("abc") === true &&
                  typeof v8.isStringOneByteRepresentation("你好") === "boolean"
                ));
                console.log("v8.cached=" + (typeof v8.cachedDataVersionTag() === "number"));
                console.log("v8.limits=" + (deserializeLimitOk && serializeLimitOk));
                console.log("v8.resolve=" + [
                  require.resolve("v8"),
                  require.resolve("node:v8")
                ].join("|"));
                """.trimIndent(),
                "<embedded-v8-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(v8Shadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("v8.same=true"))
            assertTrue(result.stdout.contains("v8.shadow=false"))
            assertTrue(result.stdout.contains("v8.frozen=true"))
            assertTrue(result.stdout.contains("v8.keys=cachedDataVersionTag,deserialize,getHeapCodeStatistics,getHeapSpaceStatistics,getHeapStatistics,isStringOneByteRepresentation,serialize"))
            assertTrue(result.stdout.contains("v8.helpers=function,function,function,function,function,function,function"))
            assertTrue(result.stdout.contains("v8.hidden=undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined"))
            assertTrue(result.stdout.contains("v8.serialized=true"))
            assertTrue(result.stdout.contains("v8.stats=true"))
            assertTrue(result.stdout.contains("v8.one_byte=true"))
            assertTrue(result.stdout.contains("v8.cached=true"))
            assertTrue(result.stdout.contains("v8.limits=true"))
            assertTrue(result.stdout.contains("v8.resolve=v8|v8"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

