    @Test
    fun streamMemoryCompatibilitySurfaceWorksAndKeepsLargeSurfacesDenied() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-stream-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create stream test dir: $absolutePath" }
        }
        try {
            val streamShadow = File(scriptDir, "node_modules/stream/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                """
                "nodejs";
                const stream = require("stream");
                const nodeStream = require("node:stream");
                const fs = require("fs");

                console.log("stream.same=" + (stream === nodeStream));
                console.log("stream.shadow=" + (stream.shadow === true));
                console.log("stream.frozen=" + Object.isFrozen(stream));
                console.log("stream.classes=" + [
                  typeof stream.Stream,
                  typeof stream.Readable,
                  typeof stream.Writable,
                  typeof stream.Duplex,
                  typeof stream.Transform,
                  typeof stream.PassThrough
                ].join(","));
                console.log("stream.helpers=" + [
                  typeof stream.pipeline,
                  typeof stream.finished,
                  typeof stream.addAbortSignal,
                  typeof stream.compose,
                  typeof stream.duplexPair,
                  typeof stream.promises
                ].join(","));
                console.log("stream.stateHelpers=" + [
                  typeof stream.isReadable,
                  typeof stream.isWritable,
                  typeof stream.isErrored,
                  typeof stream.isDestroyed,
                  typeof stream.isDisturbed
                ].join(","));
                console.log("stream.fsStreams=" + [typeof fs.createReadStream, typeof fs.createWriteStream].join(","));
                fs.writeFileSync("./stream-input.txt", "file-stream", "utf8");

                const readablePromise = new Promise((resolve) => {
                  const readable = stream.Readable.from(["a", Buffer.from("b")]);
                  let text = "";
                  readable.on("data", (chunk) => {
                    text += chunk.toString();
                  });
                  readable.on("end", () => {
                    console.log("stream.readable=" + text);
                    resolve();
                  });
                });

                const passPromise = new Promise((resolve) => {
                  const pass = new stream.PassThrough();
                  let out = "";
                  pass.on("data", (chunk) => {
                    out += chunk.toString();
                  });
                  pass.on("end", () => {
                    console.log("stream.pass=" + out);
                    resolve();
                  });
                  pass.write(Buffer.from("hello"));
                  pass.end(" world");
                });

                const writablePromise = new Promise((resolve) => {
                  let collected = "";
                  const writable = new stream.Writable({
                    write(chunk, encoding, callback) {
                      collected += chunk.toString();
                      callback();
                    }
                  });
                  writable.on("finish", () => {
                    console.log("stream.writable=" + collected);
                    resolve();
                  });
                  writable.write("x");
                  writable.end(Buffer.from("y"));
                });

                const transformPromise = new Promise((resolve) => {
                  let transformed = "";
                  const transform = new stream.Transform({
                    transform(chunk, encoding, callback) {
                      callback(null, chunk.toString().toUpperCase());
                    }
                  });
                  transform.on("data", (chunk) => {
                    transformed += chunk.toString();
                  });
                  transform.on("end", () => {
                    console.log("stream.transform=" + transformed);
                    resolve();
                  });
                  transform.write("a");
                  transform.end(Buffer.from("b"));
                });

                const pipePromise = new Promise((resolve) => {
                  let piped = "";
                  const writable = new stream.Writable({
                    write(chunk, encoding, callback) {
                      piped += chunk.toString();
                      callback();
                    }
                  });
                  writable.on("finish", () => {
                    console.log("stream.pipe=" + piped);
                    resolve();
                  });
                  stream.Readable.from(["p", "i", "p", "e"]).pipe(writable);
                });

                const pipelinePromise = new Promise((resolve, reject) => {
                  let collected = "";
                  const writable = new stream.Writable({
                    write(chunk, encoding, callback) {
                      collected += chunk.toString();
                      callback();
                    }
                  });
                  stream.pipeline(
                    stream.Readable.from(["pipe", Buffer.from("line")]),
                    writable,
                    (error) => {
                      if (error) {
                        reject(error);
                        return;
                      }
                      console.log("stream.pipeline=" + collected);
                      resolve();
                    }
                  );
                });

                const finishedPromise = new Promise((resolve, reject) => {
                  const pass = new stream.PassThrough();
                  stream.finished(pass, (error) => {
                    if (error) {
                      reject(error);
                      return;
                    }
                    console.log("stream.finished=true");
                    resolve();
                  });
                  pass.resume();
                  pass.end("finished");
                });

                const pipelineErrorPromise = new Promise((resolve) => {
                  const failedTransform = new stream.Transform({
                    transform(chunk, encoding, callback) {
                      callback(new Error("pipeline boom"));
                    }
                  });
                  const writable = new stream.Writable({
                    write(chunk, encoding, callback) {
                      callback();
                    }
                  });
                  stream.pipeline(
                    stream.Readable.from(["bad"]),
                    failedTransform,
                    writable,
                    (error) => {
                      console.log("stream.pipeline.error=" + (
                        error &&
                        error.message === "pipeline boom" &&
                        stream.isErrored(failedTransform) === true &&
                        stream.isDestroyed(failedTransform) === true
                      ));
                      resolve();
                    }
                  );
                });

                const finishedErrorPromise = new Promise((resolve) => {
                  const failed = new stream.PassThrough();
                  stream.finished(failed, (error) => {
                    console.log("stream.finished.error=" + (
                      error &&
                      error.message === "finished boom" &&
                      stream.isErrored(failed) === true &&
                      stream.isDestroyed(failed) === true
                    ));
                    resolve();
                  });
                  failed.destroy(new Error("finished boom"));
                });

                const statePromise = new Promise((resolve) => {
                  const readable = stream.Readable.from(["state"]);
                  const writable = new stream.Writable({
                    write(chunk, encoding, callback) {
                      callback();
                    }
                  });
                  const before =
                    stream.isReadable(readable) === true &&
                    stream.isWritable(writable) === true &&
                    stream.isErrored(readable) === false &&
                    stream.isDestroyed(readable) === false &&
                    stream.isDisturbed(readable) === false;
                  readable.on("end", () => {
                    console.log("stream.state=" + (
                      before &&
                      stream.isReadable(readable) === false &&
                      stream.isDisturbed(readable) === true
                    ));
                    resolve();
                  });
                  readable.resume();
                });

                const abortSignalPromise = new Promise((resolve) => {
                  const pass = new stream.PassThrough();
                  const controller = new AbortController();
                  const returned = stream.addAbortSignal(controller.signal, pass);
                  pass.on("error", (error) => {
                    console.log("stream.addAbortSignal=" + (
                      returned === pass &&
                      error &&
                      error.name === "AbortError" &&
                      error.code === "ABORT_ERR" &&
                      stream.isErrored(pass) === true &&
                      stream.isDestroyed(pass) === true
                    ));
                    resolve();
                  });
                  controller.abort();
                });

                const composePromise = new Promise((resolve, reject) => {
                  let output = "";
                  const upper = new stream.Transform({
                    transform(chunk, encoding, callback) {
                      callback(null, chunk.toString().toUpperCase());
                    }
                  });
                  const suffix = new stream.Transform({
                    transform(chunk, encoding, callback) {
                      callback(null, chunk.toString() + "!");
                    }
                  });
                  const composed = stream.compose(upper, suffix);
                  composed.on("data", (chunk) => {
                    output += chunk.toString();
                  });
                  composed.on("error", reject);
                  composed.on("end", () => {
                    console.log("stream.compose=" + (
                      composed instanceof stream.Duplex &&
                      output === "AB!"
                    ));
                    resolve();
                  });
                  composed.write("ab");
                  composed.end();
                });

                const duplexPairPromise = new Promise((resolve, reject) => {
                  const pair = stream.duplexPair();
                  let leftText = "";
                  let rightText = "";
                  let ended = 0;
                  function maybeDone() {
                    ended += 1;
                    if (ended === 2) {
                      console.log("stream.duplexPair=" + (
                        Array.isArray(pair) &&
                        pair.length === 2 &&
                        pair[0] instanceof stream.Duplex &&
                        pair[1] instanceof stream.Duplex &&
                        leftText === "right" &&
                        rightText === "left"
                      ));
                      resolve();
                    }
                  }
                  pair[0].on("data", (chunk) => {
                    leftText += chunk.toString();
                  });
                  pair[1].on("data", (chunk) => {
                    rightText += chunk.toString();
                  });
                  pair[0].on("error", reject);
                  pair[1].on("error", reject);
                  pair[0].on("end", maybeDone);
                  pair[1].on("end", maybeDone);
                  pair[1].end("right");
                  pair[0].end("left");
                });

                const fileStreamPromise = new Promise((resolve, reject) => {
                  const readable = fs.createReadStream("./stream-input.txt", { encoding: "utf8" });
                  const writable = fs.createWriteStream("./stream-output.txt", { encoding: "utf8" });
                  readable.on("error", reject);
                  writable.on("error", reject);
                  writable.on("finish", () => {
                    console.log("stream.fsFile=" + fs.readFileSync("./stream-output.txt", "utf8"));
                    resolve();
                  });
                  readable.pipe(writable);
                });

                try {
                  process.getBuiltinModule("stream");
                  console.log("stream.getBuiltinModule=false");
                } catch (error) {
                  console.log("stream.getBuiltinModule=" + error.message.includes("disabled"));
                }

                Promise.all([
                  readablePromise,
                  passPromise,
                  writablePromise,
                  transformPromise,
                  pipePromise,
                  pipelinePromise,
                  finishedPromise,
                  pipelineErrorPromise,
                  finishedErrorPromise,
                  statePromise,
                  abortSignalPromise,
                  composePromise,
                  duplexPairPromise,
                  fileStreamPromise
                ]);
                """.trimIndent(),
                "<embedded-stream-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(streamShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("stream.same=true"))
            assertTrue(result.stdout.contains("stream.shadow=false"))
            assertTrue(result.stdout.contains("stream.frozen=true"))
            assertTrue(result.stdout.contains("stream.classes=function,function,function,function,function,function"))
            assertTrue(result.stdout.contains("stream.helpers=function,function,function,function,function,undefined"))
            assertTrue(result.stdout.contains("stream.stateHelpers=function,function,function,function,function"))
            assertTrue(result.stdout.contains("stream.fsStreams=function,function"))
            assertTrue(result.stdout.contains("stream.readable=ab"))
            assertTrue(result.stdout.contains("stream.pass=hello world"))
            assertTrue(result.stdout.contains("stream.writable=xy"))
            assertTrue(result.stdout.contains("stream.transform=AB"))
            assertTrue(result.stdout.contains("stream.pipe=pipe"))
            assertTrue(result.stdout.contains("stream.fsFile=file-stream"))
            assertTrue(result.stdout.contains("stream.pipeline=pipeline"))
            assertTrue(result.stdout.contains("stream.finished=true"))
            assertTrue(result.stdout.contains("stream.pipeline.error=true"))
            assertTrue(result.stdout.contains("stream.finished.error=true"))
            assertTrue(result.stdout.contains("stream.state=true"))
            assertTrue(result.stdout.contains("stream.addAbortSignal=true"))
            assertTrue(result.stdout.contains("stream.compose=true"))
            assertTrue(result.stdout.contains("stream.duplexPair=true"))
            assertTrue(result.stdout.contains("stream.getBuiltinModule=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun streamPromisesBuiltinSupportsSafePromiseHelpersAndKeepsLargeSurfacesDenied() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-stream-promises-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create stream promises test dir: $absolutePath" }
        }
        try {
            val streamPromisesShadow = File(scriptDir, "node_modules/stream/promises.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                """
                "nodejs";
                const stream = require("stream");
                const promises = require("stream/promises");
                const nodePromises = require("node:stream/promises");
                const fs = require("fs");
                const fsp = require("fs/promises");

                async function run() {
                  fs.mkdirSync("./stream-promises-files", { recursive: true });
                  fs.writeFileSync("./stream-promises-files/input.txt", "file-pipeline", "utf8");

                  let pipelineText = "";
                  const pipelineWritable = new stream.Writable({
                    write(chunk, encoding, callback) {
                      pipelineText += chunk.toString("utf8");
                      callback();
                    }
                  });
                  await promises.pipeline(
                    stream.Readable.from(["promise", Buffer.from("line")]),
                    pipelineWritable
                  );

                  const finishedPass = new stream.PassThrough();
                  const finishedWait = promises.finished(finishedPass);
                  finishedPass.resume();
                  finishedPass.end("finished");
                  await finishedWait;

                  const failedTransform = new stream.Transform({
                    transform(chunk, encoding, callback) {
                      callback(new Error("promise pipeline boom"));
                    }
                  });
                  const pipelineErrorOk = await promises.pipeline(
                    stream.Readable.from(["bad"]),
                    failedTransform,
                    new stream.Writable({
                      write(chunk, encoding, callback) {
                        callback();
                      }
                    })
                  ).then(
                    () => false,
                    (error) => (
                      error &&
                      error.message === "promise pipeline boom" &&
                      stream.isErrored(failedTransform) === true &&
                      stream.isDestroyed(failedTransform) === true
                    )
                  );

                  const failedFinished = new stream.PassThrough();
                  const finishedErrorWait = promises.finished(failedFinished).then(
                    () => false,
                    (error) => (
                      error &&
                      error.message === "promise finished boom" &&
                      stream.isErrored(failedFinished) === true &&
                      stream.isDestroyed(failedFinished) === true
                    )
                  );
                  failedFinished.destroy(new Error("promise finished boom"));
                  const finishedErrorOk = await finishedErrorWait;

                  const upperFile = new stream.Transform({
                    transform(chunk, encoding, callback) {
                      callback(null, chunk.toString().toUpperCase());
                    }
                  });
                  await promises.pipeline(
                    fs.createReadStream("./stream-promises-files/input.txt", { encoding: "utf8" }),
                    upperFile,
                    fs.createWriteStream("./stream-promises-files/output.txt", { encoding: "utf8" })
                  );
                  const fsPipelineText = fs.readFileSync("./stream-promises-files/output.txt", "utf8");

                  const readHandle = await fsp.open("./stream-promises-files/output.txt", "r");
                  const writeHandle = await fsp.open("./stream-promises-files/filehandle-output.txt", "w");
                  await promises.pipeline(
                    readHandle.createReadStream({ encoding: "utf8", autoClose: false }),
                    writeHandle.createWriteStream({ encoding: "utf8", autoClose: false })
                  );
                  await readHandle.close();
                  await writeHandle.close();
                  const fileHandlePipelineText = fs.readFileSync("./stream-promises-files/filehandle-output.txt", "utf8");

                  const abortController = new AbortController();
                  abortController.abort();
                  const abortOk = await promises.pipeline(
                    stream.Readable.from(["abort"]),
                    new stream.Writable({
                      write(chunk, encoding, callback) {
                        callback();
                      }
                    }),
                    { signal: abortController.signal }
                  ).then(
                    () => false,
                    (error) => error && error.code === "ABORT_ERR"
                  );

                  let escapeOk = false;
                  try {
                    await promises.pipeline(
                      fs.createReadStream("../stream-promises-outside.txt"),
                      new stream.Writable({
                        write(chunk, encoding, callback) {
                          callback();
                        }
                      })
                    );
                  } catch (error) {
                    escapeOk = error instanceof Error && String(error.message).includes("escapes working directory");
                  }

                  console.log("stream.promises.same=" + (promises === nodePromises));
                  console.log("stream.promises.keys=" + Object.keys(promises).sort().join(","));
                  console.log("stream.promises.pipeline=" + (pipelineText === "promiseline"));
                  console.log("stream.promises.finished=true");
                  console.log("stream.promises.pipeline_error=" + pipelineErrorOk);
                  console.log("stream.promises.finished_error=" + finishedErrorOk);
                  console.log("stream.promises.fs_pipeline=" + (fsPipelineText === "FILE-PIPELINE"));
                  console.log("stream.promises.filehandle_pipeline=" + (fileHandlePipelineText === "FILE-PIPELINE"));
                  console.log("stream.promises.abort=" + abortOk);
                  console.log("stream.promises.escape=" + escapeOk);
                  console.log("stream.promises.resolve=" + (
                    require.resolve("stream/promises") + "/" +
                    require.resolve("node:stream/promises")
                  ));
                  console.log("stream.promises.shadow=" + (
                    promises.shadow === true ||
                    Object.keys(require.cache).some((filename) => {
                      return filename.replace(/\\/g, "/").includes("/node_modules/stream/promises");
                    })
                  ));
                  console.log("stream.promises.frozen=" + Object.isFrozen(promises));
                  console.log("stream.promises.root_hidden=" + (typeof stream.promises));
                  console.log("stream.promises.hidden=" + [
                    typeof promises.Readable,
                    typeof promises.Writable,
                    typeof promises.consumers,
                    typeof promises.promises
                  ].join(","));

                  for (const name of ["worker_threads"]) {
                    try {
                      require(name);
                      console.log("stream.promises.denied." + name + "=false");
                    } catch (error) {
                      console.log("stream.promises.denied." + name + "=" + error.message.includes(name));
                    }
                  }
                }

                run().catch((error) => {
                  console.log("stream.promises.error=" + (error && error.message || error));
                  throw error;
                });
                """.trimIndent(),
                "<embedded-stream-promises-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(streamPromisesShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("stream.promises.same=true"))
            assertTrue(result.stdout.contains("stream.promises.keys=finished,pipeline"))
            assertTrue(result.stdout.contains("stream.promises.pipeline=true"))
            assertTrue(result.stdout.contains("stream.promises.finished=true"))
            assertTrue(result.stdout.contains("stream.promises.pipeline_error=true"))
            assertTrue(result.stdout.contains("stream.promises.finished_error=true"))
            assertTrue(result.stdout.contains("stream.promises.fs_pipeline=true"))
            assertTrue(result.stdout.contains("stream.promises.filehandle_pipeline=true"))
            assertTrue(result.stdout.contains("stream.promises.abort=true"))
            assertTrue(result.stdout.contains("stream.promises.escape=true"))
            assertTrue(result.stdout.contains("stream.promises.resolve=stream/promises/stream/promises"))
            assertTrue(result.stdout.contains("stream.promises.shadow=false"))
            assertTrue(result.stdout.contains("stream.promises.frozen=true"))
            assertTrue(result.stdout.contains("stream.promises.root_hidden=undefined"))
            assertTrue(result.stdout.contains("stream.promises.hidden=undefined,undefined,undefined,undefined"))
            listOf(
                "worker_threads",
            ).forEach { name ->
                assertTrue(result.stdout.contains("stream.promises.denied.$name=true"))
            }
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun readlineBuiltinsSupportScopedLineReadersAndPromiseQuestions() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-readline-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create readline test dir: $absolutePath" }
        }
        try {
            val readlineShadow = File(scriptDir, "node_modules/readline/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val readlinePromisesShadow = File(scriptDir, "node_modules/readline/promises.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const fsp = require("fs/promises");
                const stream = require("stream");
                const readline = require("readline");
                const nodeReadline = require("node:readline");
                const readlinePromises = require("readline/promises");
                const nodeReadlinePromises = require("node:readline/promises");

                async function collectLines(iterable) {
                  const values = [];
                  for await (const line of iterable) {
                    values.push(line);
                  }
                  return values.join("|");
                }

                function captureEscape(action) {
                  try {
                    action();
                    return false;
                  } catch (error) {
                    return error instanceof Error &&
                      String(error.message || "").includes("escapes working directory");
                  }
                }

                async function run() {
                  fs.mkdirSync("./readline-files", { recursive: true });
                  fs.writeFileSync("./readline-files/input.txt", "alpha\nbeta\ngamma\n", "utf8");

                  const callbackInterface = readline.createInterface({
                    input: fs.createReadStream("./readline-files/input.txt", { encoding: "utf8" }),
                    crlfDelay: Infinity
                  });
                  const callbackLines = await collectLines(callbackInterface);

                  const promiseInterface = readlinePromises.createInterface({
                    input: fs.createReadStream("./readline-files/input.txt", { encoding: "utf8" }),
                    crlfDelay: Infinity
                  });
                  const promiseLines = await collectLines(promiseInterface);

                  const handle = await fsp.open("./readline-files/input.txt", "r");
                  const handleLines = await collectLines(handle.readLines({
                    encoding: "utf8",
                    autoClose: false
                  }));
                  const handleStillOpen = typeof handle.fd === "number" && handle.fd >= 0;
                  await handle.close();

                  const questionInput = new stream.PassThrough();
                  const questionOutput = new stream.PassThrough();
                  let promptText = "";
                  questionOutput.on("data", (chunk) => {
                    promptText += chunk.toString("utf8");
                  });
                  const questionInterface = readlinePromises.createInterface({
                    input: questionInput,
                    output: questionOutput,
                    terminal: false
                  });
                  const questionPending = questionInterface.question("Name: ");
                  questionInput.end("autojs6\n");
                  const questionAnswer = await questionPending;
                  questionInterface.close();

                  const abortInput = new stream.PassThrough();
                  const abortOutput = new stream.PassThrough();
                  abortOutput.resume();
                  const abortInterface = readlinePromises.createInterface({
                    input: abortInput,
                    output: abortOutput,
                    terminal: false
                  });
                  const abortController = new AbortController();
                  const abortPending = abortInterface.question("Abort: ", {
                    signal: abortController.signal
                  }).then(
                    () => false,
                    (error) => error && error.code === "ABORT_ERR" && error.name === "AbortError"
                  );
                  abortController.abort();
                  const abortOk = await abortPending;
                  abortInterface.close();

                  const terminal = new stream.PassThrough();
                  let terminalText = "";
                  terminal.on("data", (chunk) => {
                    terminalText += chunk.toString("utf8");
                  });
                  readline.cursorTo(terminal, 0);
                  readline.moveCursor(terminal, 1, 0);
                  readline.clearLine(terminal, 0);
                  readline.clearScreenDown(terminal);

                  const callbackEscapeOk = captureEscape(() => readline.createInterface({
                    input: fs.createReadStream("../readline-outside.txt")
                  }));
                  const promisesEscapeOk = captureEscape(() => readlinePromises.createInterface({
                    input: fs.createReadStream("../readline-promises-outside.txt")
                  }));
                  const shadowLoaded = Object.keys(require.cache).some((filename) => {
                    return filename.replace(/\\/g, "/").includes("/node_modules/readline/");
                  });

                  console.log("readline.same=" + (readline === nodeReadline));
                  console.log("readline.promises.same=" + (readlinePromises === nodeReadlinePromises));
                  console.log("readline.keys=" + Object.keys(readline).sort().join(","));
                  console.log("readline.promises.keys=" + Object.keys(readlinePromises).sort().join(","));
                  console.log("readline.callback_lines=" + callbackLines);
                  console.log("readline.promises.lines=" + promiseLines);
                  console.log("readline.filehandle_lines=" + [handleLines, handleStillOpen].join("|"));
                  console.log("readline.promises.question=" + [questionAnswer, promptText].join("|"));
                  console.log("readline.promises.abort=" + abortOk);
                  console.log("readline.terminal_helpers=" + (terminalText.length > 0));
                  console.log("readline.escape=" + (callbackEscapeOk && promisesEscapeOk));
                  console.log("readline.resolve=" + [
                    require.resolve("readline"),
                    require.resolve("node:readline"),
                    require.resolve("readline/promises"),
                    require.resolve("node:readline/promises")
                  ].join("/"));
                  console.log("readline.shadow=" + (
                    readline.shadow === true ||
                    readlinePromises.shadow === true ||
                    shadowLoaded
                  ));
                  console.log("readline.frozen=" + [
                    Object.isFrozen(readline),
                    Object.isFrozen(readlinePromises)
                  ].join(","));
                  console.log("readline.hidden=" + [
                    typeof readline.promises,
                    typeof readlinePromises.clearLine,
                    typeof readlinePromises.cursorTo,
                    typeof readlinePromises.promises
                  ].join(","));

                  for (const name of ["worker_threads"]) {
                    try {
                      require(name);
                      console.log("readline.denied." + name + "=false");
                    } catch (error) {
                      console.log("readline.denied." + name + "=" + error.message.includes(name));
                    }
                  }
                }

                return run().catch((error) => {
                  console.log("readline.error=" + (error && error.message || error));
                  throw error;
                });
                """.trimIndent(),
                "<embedded-readline-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(readlineShadow, readlinePromisesShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("readline.same=true"))
            assertTrue(result.stdout.contains("readline.promises.same=true"))
            assertTrue(result.stdout.contains("readline.keys=Interface,clearLine,clearScreenDown,createInterface,cursorTo,emitKeypressEvents,moveCursor"))
            assertTrue(result.stdout.contains("readline.promises.keys=Interface,Readline,createInterface"))
            assertTrue(result.stdout.contains("readline.callback_lines=alpha|beta|gamma"))
            assertTrue(result.stdout.contains("readline.promises.lines=alpha|beta|gamma"))
            assertTrue(result.stdout.contains("readline.filehandle_lines=alpha|beta|gamma|true"))
            assertTrue(result.stdout.contains("readline.promises.question=autojs6|Name: "))
            assertTrue(result.stdout.contains("readline.promises.abort=true"))
            assertTrue(result.stdout.contains("readline.terminal_helpers=true"))
            assertTrue(result.stdout.contains("readline.escape=true"))
            assertTrue(result.stdout.contains("readline.resolve=readline/readline/readline/promises/readline/promises"))
            assertTrue(result.stdout.contains("readline.shadow=false"))
            assertTrue(result.stdout.contains("readline.frozen=true,true"))
            assertTrue(result.stdout.contains("readline.hidden=undefined,undefined,undefined,undefined"))
            listOf(
                "worker_threads",
            ).forEach { name ->
                assertTrue(result.stdout.contains("readline.denied.$name=true"))
            }
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun streamWebBuiltinSupportsSafeWebStreamsAndShadowProtection() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-stream-web-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create stream web test dir: $absolutePath" }
        }
        try {
            val streamWebShadow = File(scriptDir, "node_modules/stream/web.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                """
                "nodejs";
                const stream = require("stream");
                const web = require("stream/web");
                const nodeWeb = require("node:stream/web");

                async function readAll(readable) {
                  const reader = readable.getReader();
                  const values = [];
                  while (true) {
                    const next = await reader.read();
                    if (next.done) {
                      return values;
                    }
                    values.push(next.value);
                  }
                }

                async function run() {
                  const readableText = (await readAll(new web.ReadableStream({
                    start(controller) {
                      controller.enqueue("hello");
                      controller.enqueue(" web");
                      controller.close();
                    }
                  }))).join("");

                  let writableText = "";
                  const writable = new web.WritableStream({
                    write(chunk) {
                      writableText += String(chunk);
                    }
                  });
                  const writableWriter = writable.getWriter();
                  await writableWriter.write("write");
                  await writableWriter.write("-web");
                  await writableWriter.close();

                  const transform = new web.TransformStream({
                    transform(chunk, controller) {
                      controller.enqueue(String(chunk).toUpperCase());
                    }
                  });
                  const transformValues = readAll(transform.readable);
                  const transformWriter = transform.writable.getWriter();
                  await transformWriter.write("transform");
                  await transformWriter.write("-web");
                  await transformWriter.close();
                  const transformedText = (await transformValues).join("");

                  const encoder = new web.TextEncoderStream();
                  const encodedValues = readAll(encoder.readable);
                  const encoderWriter = encoder.writable.getWriter();
                  await encoderWriter.write("encoded-web");
                  await encoderWriter.close();
                  const encodedText = Buffer.concat((await encodedValues).map((chunk) => Buffer.from(chunk))).toString("utf8");

                  const decoder = new web.TextDecoderStream();
                  const decodedValues = readAll(decoder.readable);
                  const decoderWriter = decoder.writable.getWriter();
                  await decoderWriter.write(Buffer.from("decoded-web"));
                  await decoderWriter.close();
                  const decodedText = (await decodedValues).join("");

                  const countStrategy = new web.CountQueuingStrategy({ highWaterMark: 2 });
                  const byteStrategy = new web.ByteLengthQueuingStrategy({ highWaterMark: 8 });
                  const strategyOk =
                    countStrategy.highWaterMark === 2 &&
                    countStrategy.size("value") === 1 &&
                    byteStrategy.highWaterMark === 8 &&
                    byteStrategy.size(new Uint8Array([1, 2, 3])) === 3;

                  console.log("stream.web.same=" + (web === nodeWeb));
                  console.log("stream.web.keys=" + Object.keys(web).sort().join(","));
                  console.log("stream.web.readable=" + (readableText === "hello web"));
                  console.log("stream.web.writable=" + (writableText === "write-web"));
                  console.log("stream.web.transform=" + (transformedText === "TRANSFORM-WEB"));
                  console.log("stream.web.encoder=" + (encodedText === "encoded-web"));
                  console.log("stream.web.decoder=" + (decodedText === "decoded-web"));
                  console.log("stream.web.strategy=" + strategyOk);
                  console.log("stream.web.resolve=" + (
                    require.resolve("stream/web") + "/" +
                    require.resolve("node:stream/web")
                  ));
                  console.log("stream.web.shadow=" + (
                    web.shadow === true ||
                    Object.keys(require.cache).some((filename) => {
                      return filename.replace(/\\/g, "/").includes("/node_modules/stream/web");
                    })
                  ));
                  console.log("stream.web.frozen=" + Object.isFrozen(web));
                  console.log("stream.web.root_hidden=" + (typeof stream.web));
                  console.log("stream.web.hidden=" + [
                    typeof web.CompressionStream,
                    typeof web.DecompressionStream,
                    typeof web.ReadableStreamDefaultReader,
                    typeof web.WritableStreamDefaultWriter,
                    typeof web.TransformStreamDefaultController,
                    typeof web.ReadableByteStreamController
                  ].join(","));

                  for (const name of ["worker_threads"]) {
                    try {
                      require(name);
                      console.log("stream.web.denied." + name + "=false");
                    } catch (error) {
                      console.log("stream.web.denied." + name + "=" + error.message.includes(name));
                    }
                  }
                }

                run().catch((error) => {
                  console.log("stream.web.error=" + (error && error.message || error));
                  throw error;
                });
                """.trimIndent(),
                "<embedded-stream-web-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(streamWebShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("stream.web.same=true"))
            assertTrue(result.stdout.contains("stream.web.keys=ByteLengthQueuingStrategy,CountQueuingStrategy,ReadableStream,TextDecoderStream,TextEncoderStream,TransformStream,WritableStream"))
            assertTrue(result.stdout.contains("stream.web.readable=true"))
            assertTrue(result.stdout.contains("stream.web.writable=true"))
            assertTrue(result.stdout.contains("stream.web.transform=true"))
            assertTrue(result.stdout.contains("stream.web.encoder=true"))
            assertTrue(result.stdout.contains("stream.web.decoder=true"))
            assertTrue(result.stdout.contains("stream.web.strategy=true"))
            assertTrue(result.stdout.contains("stream.web.resolve=stream/web/stream/web"))
            assertTrue(result.stdout.contains("stream.web.shadow=false"))
            assertTrue(result.stdout.contains("stream.web.frozen=true"))
            assertTrue(result.stdout.contains("stream.web.root_hidden=undefined"))
            assertTrue(result.stdout.contains("stream.web.hidden=undefined,undefined,undefined,undefined,undefined,undefined"))
            listOf(
                "worker_threads",
            ).forEach { name ->
                assertTrue(result.stdout.contains("stream.web.denied.$name=true"))
            }
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun streamConsumersBuiltinSupportsSafeConsumersAndShadowProtection() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-stream-consumers-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create stream consumers test dir: $absolutePath" }
        }
        try {
            val streamConsumersShadow = File(scriptDir, "node_modules/stream/consumers.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                """
                "nodejs";
                const stream = require("stream");
                const consumers = require("stream/consumers");
                const nodeConsumers = require("node:stream/consumers");

                const pass = new stream.PassThrough();
                const passValuePromise = consumers.text(pass);
                pass.end("pass-through");

                Promise.all([
                  consumers.text(stream.Readable.from(["hello", Buffer.from(" consumers")])),
                  consumers.json(stream.Readable.from(['{"ok":', 'true}'])),
                  consumers.buffer(stream.Readable.from([Buffer.from("buf"), "fer"])),
                  consumers.arrayBuffer(stream.Readable.from([Buffer.from("array")])),
                  consumers.blob(stream.Readable.from([Buffer.from("blob"), " value"])),
                  passValuePromise
                ]).then(async ([textValue, jsonValue, bufferValue, arrayBufferValue, blobValue, passValue]) => {
                  const blobText = await blobValue.text();
                  console.log("stream.consumers.same=" + (consumers === nodeConsumers));
                  console.log("stream.consumers.keys=" + Object.keys(consumers).sort().join(","));
                  console.log("stream.consumers.text=" + (textValue === "hello consumers"));
                  console.log("stream.consumers.json=" + (jsonValue.ok === true));
                  console.log("stream.consumers.buffer=" + (
                    Buffer.isBuffer(bufferValue) &&
                    bufferValue.toString("utf8") === "buffer"
                  ));
                  console.log("stream.consumers.arrayBuffer=" + (
                    arrayBufferValue instanceof ArrayBuffer &&
                    Buffer.from(arrayBufferValue).toString("utf8") === "array"
                  ));
                  console.log("stream.consumers.blob=" + (
                    blobValue.size === 10 &&
                    blobText === "blob value"
                  ));
                  console.log("stream.consumers.pass=" + (passValue === "pass-through"));
                  console.log("stream.consumers.resolve=" + (
                    require.resolve("stream/consumers") + "/" +
                    require.resolve("node:stream/consumers")
                  ));
                  console.log("stream.consumers.shadow=" + (
                    consumers.shadow === true ||
                    Object.keys(require.cache).some((filename) => {
                      return filename.replace(/\\/g, "/").includes("/node_modules/stream/consumers");
                    })
                  ));
                  console.log("stream.consumers.frozen=" + Object.isFrozen(consumers));
                  console.log("stream.consumers.hidden=" + [
                    typeof consumers.finished,
                    typeof consumers.pipeline,
                    typeof consumers.Readable
                  ].join(","));
                }).catch((error) => {
                  console.log("stream.consumers.error=" + (error && error.message || error));
                  throw error;
                });
                """.trimIndent(),
                "<embedded-stream-consumers-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(streamConsumersShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("stream.consumers.same=true"))
            assertTrue(result.stdout.contains("stream.consumers.keys=arrayBuffer,blob,buffer,json,text"))
            assertTrue(result.stdout.contains("stream.consumers.text=true"))
            assertTrue(result.stdout.contains("stream.consumers.json=true"))
            assertTrue(result.stdout.contains("stream.consumers.buffer=true"))
            assertTrue(result.stdout.contains("stream.consumers.arrayBuffer=true"))
            assertTrue(result.stdout.contains("stream.consumers.blob=true"))
            assertTrue(result.stdout.contains("stream.consumers.pass=true"))
            assertTrue(result.stdout.contains("stream.consumers.resolve=stream/consumers/stream/consumers"))
            assertTrue(result.stdout.contains("stream.consumers.shadow=false"))
            assertTrue(result.stdout.contains("stream.consumers.frozen=true"))
            assertTrue(result.stdout.contains("stream.consumers.hidden=undefined,undefined,undefined"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun limitedZlibBuiltinSupportsSyncCompressionAndKeepsLargeSurfacesDenied() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-limited-zlib-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create limited zlib test dir: $absolutePath" }
        }
        try {
            val zlibShadow = File(scriptDir, "node_modules/zlib/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val outputBombBase64 = gzipBase64(ByteArray(2 * 1024 * 1024 + 1) { 'A'.code.toByte() })

            val result = runEmbeddedScript(
                """
                "nodejs";
                const zlib = require("zlib");
                const nodeZlib = require("node:zlib");
                const stream = require("stream");
                const streamPromises = require("stream/promises");
                console.log("zlib.same=" + (zlib === nodeZlib));
                console.log("zlib.shadow=" + (zlib.shadow === true));
                console.log("zlib.frozen=" + Object.isFrozen(zlib));
                console.log("zlib.apis=" + [
                  typeof zlib.gzipSync,
                  typeof zlib.gunzipSync,
                  typeof zlib.deflateSync,
                  typeof zlib.inflateSync,
                  typeof zlib.deflateRawSync,
                  typeof zlib.inflateRawSync,
                  typeof zlib.brotliCompressSync,
                  typeof zlib.brotliDecompressSync
                ].join(","));
                console.log("zlib.callback.apis=" + [
                  typeof zlib.gzip,
                  typeof zlib.gunzip,
                  typeof zlib.deflate,
                  typeof zlib.inflate,
                  typeof zlib.deflateRaw,
                  typeof zlib.inflateRaw,
                  typeof zlib.brotliCompress,
                  typeof zlib.brotliDecompress
                ].join(","));
                console.log("zlib.stream.apis=" + [
                  typeof zlib.createGzip,
                  typeof zlib.createGunzip,
                  typeof zlib.createDeflate,
                  typeof zlib.createInflate,
                  typeof zlib.createDeflateRaw,
                  typeof zlib.createInflateRaw,
                  typeof zlib.createBrotliCompress,
                  typeof zlib.createBrotliDecompress
                ].join(","));
                console.log("zlib.hidden=" + typeof zlib.promises);
                function collectZlibPipeline(chunks, transforms) {
                  const values = [];
                  const writable = new stream.Writable({
                    write(chunk, encoding, callback) {
                      values.push(Buffer.from(chunk));
                      callback();
                    }
                  });
                  return streamPromises.pipeline(
                    stream.Readable.from(chunks),
                    ...transforms,
                    writable
                  ).then(() => Buffer.concat(values).toString("utf8"));
                }
                async function zlibPipelineError(chunks, transforms) {
                  try {
                    await collectZlibPipeline(chunks, transforms);
                    return "ok";
                  } catch (error) {
                    return [
                      error && error.name,
                      error && error.code
                    ].join("/");
                  }
                }
                const zlibStreamChecks = (async () => {
                  const gzipText = await collectZlibPipeline(
                    [Buffer.from("stream-"), "gzip"],
                    [zlib.createGzip(), zlib.createGunzip()]
                  );
                  const rawText = await collectZlibPipeline(
                    [Buffer.from("stream-raw")],
                    [zlib.createDeflateRaw(), zlib.createInflateRaw()]
                  );
                  const brotliText = await collectZlibPipeline(
                    [Buffer.from("stream-brotli")],
                    [
                      zlib.createBrotliCompress({
                        params: {
                          [zlib.constants.BROTLI_PARAM_QUALITY]: 1
                        }
                      }),
                      zlib.createBrotliDecompress()
                    ]
                  );
                  const streamInputLimit = await zlibPipelineError(
                    [Buffer.alloc(512 * 1024 + 1)],
                    [zlib.createGzip()]
                  );
                  const streamOutputLimit = await zlibPipelineError(
                    [Buffer.from("$outputBombBase64", "base64")],
                    [zlib.createGunzip()]
                  );
                  const streamCorrupt = await zlibPipelineError(
                    [Buffer.from("not-gzip")],
                    [zlib.createGunzip()]
                  );
                  console.log("zlib.stream.roundtrip=" + [gzipText, rawText, brotliText].join("|"));
                  console.log("zlib.stream.limits=" + [streamInputLimit, streamOutputLimit].join("|"));
                  console.log("zlib.stream.corrupt=" + (streamCorrupt !== "ok"));
                })();
                const gz = zlib.gzipSync(Buffer.from("hello"));
                console.log("zlib.gzip.buffer=" + Buffer.isBuffer(gz) + "/" + zlib.gunzipSync(gz).toString("utf8"));
                const gzString = zlib.gzipSync("hello");
                console.log("zlib.gzip.string=" + zlib.gunzipSync(gzString).toString("utf8"));
                const deflated = zlib.deflateSync("hello");
                console.log("zlib.deflate=" + zlib.inflateSync(deflated).toString("utf8"));
                const typed = new Uint8Array(Buffer.from("typed"));
                console.log("zlib.typed=" + zlib.gunzipSync(zlib.gzipSync(typed)).toString("utf8"));
                const raw = zlib.deflateRawSync(Buffer.from("raw"));
                const brotli = zlib.brotliCompressSync(Buffer.from("brotli"), {
                  params: {
                    [zlib.constants.BROTLI_PARAM_QUALITY]: 1
                  }
                });
                console.log("zlib.raw_brotli=" + [
                  zlib.inflateRawSync(raw).toString("utf8"),
                  zlib.brotliDecompressSync(brotli).toString("utf8"),
                  Object.isFrozen(zlib.constants),
                  typeof zlib.constants.BROTLI_PARAM_QUALITY
                ].join("|"));

                function expectCode(label, action, expectedCode) {
                  try {
                    action();
                    console.log(label + "=false");
                  } catch (error) {
                    console.log(label + "=" + (error && error.code === expectedCode));
                  }
                }
                expectCode("zlib.invalidArg", () => zlib.gzipSync(42), "ERR_INVALID_ARG_TYPE");
                expectCode("zlib.inputLimit", () => zlib.gzipSync(Buffer.alloc(512 * 1024 + 1)), "ERR_OUT_OF_RANGE");
                expectCode("zlib.brotliInputLimit", () => zlib.brotliCompressSync(Buffer.alloc(512 * 1024 + 1)), "ERR_OUT_OF_RANGE");
                expectCode("zlib.callback.missing", () => zlib.gzip(Buffer.from("x")), "ERR_INVALID_ARG_TYPE");
                expectCode("zlib.callback.type", () => zlib.gzip(Buffer.from("x"), "bad"), "ERR_INVALID_ARG_TYPE");
                expectCode("zlib.callback.inputLimit", () => zlib.gzip(Buffer.alloc(512 * 1024 + 1), () => {}), "ERR_OUT_OF_RANGE");
                expectCode(
                  "zlib.outputLimit",
                  () => zlib.gunzipSync(Buffer.from("$outputBombBase64", "base64")),
                  "ERR_OUT_OF_RANGE"
                );
                try {
                  zlib.gunzipSync(Buffer.from("not-gzip"));
                  console.log("zlib.corrupt=false");
                } catch (error) {
                  console.log("zlib.corrupt=" + (error instanceof Error));
                }
                let gzipCallbackSync = true;
                zlib.gzip(Buffer.from("callback"), (error, value) => {
                  console.log("zlib.callback.gzip.async=" + (!gzipCallbackSync));
                  console.log("zlib.callback.gzip=" + (
                    error === null &&
                    Buffer.isBuffer(value) &&
                    zlib.gunzipSync(value).toString("utf8") === "callback"
                  ));
                });
                gzipCallbackSync = false;
                zlib.deflateRaw(Buffer.from("raw-callback"), (error, value) => {
                  console.log("zlib.callback.raw=" + (
                    error === null &&
                    Buffer.isBuffer(value) &&
                    zlib.inflateRawSync(value).toString("utf8") === "raw-callback"
                  ));
                });
                zlib.brotliCompress(Buffer.from("brotli-callback"), {
                  params: {
                    [zlib.constants.BROTLI_PARAM_QUALITY]: 1
                  }
                }, (error, value) => {
                  if (error) {
                    console.log("zlib.callback.brotli=false");
                    return;
                  }
                  zlib.brotliDecompress(value, (decompressError, decompressed) => {
                    console.log("zlib.callback.brotli=" + (
                      decompressError === null &&
                      decompressed.toString("utf8") === "brotli-callback"
                    ));
                  });
                });
                zlib.gunzip(Buffer.from("not-gzip"), (error) => {
                  console.log("zlib.callback.corrupt=" + (error instanceof Error));
                });
                zlib.gunzip(Buffer.from("$outputBombBase64", "base64"), (error) => {
                  console.log("zlib.callback.outputLimit=" + (error && error.code === "ERR_OUT_OF_RANGE"));
                });
                for (const name of [
                  "zlib/promises",
                  "node:zlib/promises",
                  "child_process",
                  "worker_threads"
                ]) {
                  try {
                    require(name);
                    console.log("zlib.denied." + name + "=false");
                  } catch (error) {
                    console.log("zlib.denied." + name + "=" + error.message.includes(name));
                  }
                }
                try {
                  process.getBuiltinModule("zlib");
                  console.log("zlib.getBuiltinModule=false");
                } catch (error) {
                  console.log("zlib.getBuiltinModule=" + error.message.includes("disabled"));
                }
                console.log("zlib.scheduled=true");
                return zlibStreamChecks;
                """.trimIndent(),
                "<embedded-zlib-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(zlibShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertOutputOrder(result.stdout, "zlib.scheduled=true", "zlib.callback.gzip.async=true")
            assertTrue(result.stdout.contains("zlib.same=true"))
            assertTrue(result.stdout.contains("zlib.shadow=false"))
            assertTrue(result.stdout.contains("zlib.frozen=true"))
            assertTrue(result.stdout.contains("zlib.apis=function,function,function,function,function,function,function,function"))
            assertTrue(result.stdout.contains("zlib.callback.apis=function,function,function,function,function,function,function,function"))
            assertTrue(result.stdout.contains("zlib.stream.apis=function,function,function,function,function,function,function,function"))
            assertTrue(result.stdout.contains("zlib.hidden=undefined"))
            assertTrue(result.stdout.contains("zlib.stream.roundtrip=stream-gzip|stream-raw|stream-brotli"))
            assertTrue(result.stdout.contains("zlib.stream.limits=RangeError/ERR_OUT_OF_RANGE|RangeError/ERR_OUT_OF_RANGE"))
            assertTrue(result.stdout.contains("zlib.stream.corrupt=true"))
            assertTrue(result.stdout.contains("zlib.gzip.buffer=true/hello"))
            assertTrue(result.stdout.contains("zlib.gzip.string=hello"))
            assertTrue(result.stdout.contains("zlib.deflate=hello"))
            assertTrue(result.stdout.contains("zlib.typed=typed"))
            assertTrue(result.stdout.contains("zlib.raw_brotli=raw|brotli|true|number"))
            assertTrue(result.stdout.contains("zlib.invalidArg=true"))
            assertTrue(result.stdout.contains("zlib.inputLimit=true"))
            assertTrue(result.stdout.contains("zlib.brotliInputLimit=true"))
            assertTrue(result.stdout.contains("zlib.callback.missing=true"))
            assertTrue(result.stdout.contains("zlib.callback.type=true"))
            assertTrue(result.stdout.contains("zlib.callback.inputLimit=true"))
            assertTrue(result.stdout.contains("zlib.outputLimit=true"))
            assertTrue(result.stdout.contains("zlib.corrupt=true"))
            assertTrue(result.stdout.contains("zlib.callback.gzip=true"))
            assertTrue(result.stdout.contains("zlib.callback.raw=true"))
            assertTrue(result.stdout.contains("zlib.callback.brotli=true"))
            assertTrue(result.stdout.contains("zlib.callback.corrupt=true"))
            assertTrue(result.stdout.contains("zlib.callback.outputLimit=true"))
            listOf(
                "zlib/promises",
                "node:zlib/promises",
                "child_process",
                "worker_threads",
            ).forEach { name ->
                assertTrue(result.stdout.contains("zlib.denied.$name=true"))
            }
            assertTrue(result.stdout.contains("zlib.getBuiltinModule=true"))
            assertEquals(0, result.pendingZlibCallbacks ?: -1)
            assertEquals(0, result.pendingAsyncCallbacks ?: -1)
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun limitedCryptoBuiltinSupportsHashRandomBytesAndKeepsDangerousApisHidden() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-limited-crypto-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create limited crypto test dir: $absolutePath" }
        }
        try {
            val cryptoShadow = File(scriptDir, "node_modules/crypto/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val result = runEmbeddedScript(
                """
                "nodejs";
                const crypto = require("crypto");
                const nodeCrypto = require("node:crypto");
                console.log("crypto.same=" + (crypto === nodeCrypto));
                console.log("crypto.shadow=" + (crypto.shadow === true));
                const random = crypto.randomBytes(16);
                console.log("crypto.random.sync=" + Buffer.isBuffer(random) + "/" + random.length);
                let sync = true;
                crypto.randomBytes(8, (error, value) => {
                  console.log("crypto.random.callback.async=" + (!sync));
                  console.log("crypto.random.callback=" + (error === null) + "/" + Buffer.isBuffer(value) + "/" + value.length);
                });
                sync = false;
                const fill = Buffer.alloc(8, 7);
                const filled = crypto.randomFillSync(fill, 2, 4);
                console.log("crypto.randomFill.sync=" + (
                  filled === fill &&
                  fill.length === 8 &&
                  fill[0] === 7 &&
                  fill[1] === 7 &&
                  fill[6] === 7 &&
                  fill[7] === 7
                ));
                const fillDefaultOffset = Buffer.alloc(6, 5);
                const filledDefaultOffset = crypto.randomFillSync(fillDefaultOffset, undefined, 2);
                console.log("crypto.randomFill.sync.defaultOffset=" + (
                  filledDefaultOffset === fillDefaultOffset &&
                  fillDefaultOffset.length === 6 &&
                  fillDefaultOffset[2] === 5 &&
                  fillDefaultOffset[3] === 5 &&
                  fillDefaultOffset[4] === 5 &&
                  fillDefaultOffset[5] === 5
                ));
                let fillSync = true;
                const fillTarget = Buffer.alloc(6, 5);
                crypto.randomFill(fillTarget, 1, 3, (error, value) => {
                  console.log("crypto.randomFill.callback.async=" + (!fillSync));
                  console.log("crypto.randomFill.callback=" + (
                    error === null &&
                    value === fillTarget &&
                    fillTarget.length === 6 &&
                    fillTarget[0] === 5 &&
                    fillTarget[4] === 5 &&
                    fillTarget[5] === 5
                  ));
                });
                fillSync = false;
                let fillDefaultOffsetSync = true;
                const fillDefaultOffsetTarget = Buffer.alloc(6, 5);
                crypto.randomFill(fillDefaultOffsetTarget, undefined, 2, (error, value) => {
                  console.log("crypto.randomFill.callback.defaultOffset.async=" + (!fillDefaultOffsetSync));
                  console.log("crypto.randomFill.callback.defaultOffset=" + (
                    error === null &&
                    value === fillDefaultOffsetTarget &&
                    fillDefaultOffsetTarget.length === 6 &&
                    fillDefaultOffsetTarget[2] === 5 &&
                    fillDefaultOffsetTarget[3] === 5 &&
                    fillDefaultOffsetTarget[4] === 5 &&
                    fillDefaultOffsetTarget[5] === 5
                  ));
                });
                fillDefaultOffsetSync = false;
                const randomIntValue = crypto.randomInt(5);
                console.log("crypto.randomInt.sync=" + (
                  Number.isInteger(randomIntValue) &&
                  randomIntValue >= 0 &&
                  randomIntValue < 5
                ));
                let randomIntSync = true;
                crypto.randomInt(5, 10, (error, value) => {
                  console.log("crypto.randomInt.callback.async=" + (!randomIntSync));
                  console.log("crypto.randomInt.callback=" + (
                    error === null &&
                    Number.isInteger(value) &&
                    value >= 5 &&
                    value < 10
                  ));
                });
                randomIntSync = false;
                const uuid = crypto.randomUUID();
                console.log("crypto.randomUUID=" + /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(uuid));
                console.log("crypto.sha256=" + crypto.createHash("sha256").update("abc").digest("hex"));
                console.log("crypto.sha1=" + crypto.createHash("sha1").update(Buffer.from("abc")).digest("hex"));
                console.log("crypto.md5=" + crypto.createHash("md5").update("abc").digest("hex"));
                console.log("crypto.sha512.prefix=" + crypto.createHash("sha512").update("abc").digest("hex").slice(0, 16));
                console.log("crypto.hmac.sha256=" + crypto.createHmac("sha256", "key").update("abc").digest("hex"));
                console.log("crypto.hmac.sha512.prefix=" + crypto.createHmac("sha512", Buffer.from("key")).update("abc").digest("base64").slice(0, 24));
                const secretKey = crypto.createSecretKey(Buffer.from("key"));
                const secretKeyText = crypto.createSecretKey("key", "utf8");
                const secretKeyTyped = crypto.createSecretKey(new Uint8Array([0x6b, 0x65, 0x79]));
                const secretKeyJwk = secretKey.export({ format: "jwk" });
                console.log("crypto.secretKey.surface=" + (
                  typeof crypto.createSecretKey === "function" &&
                  typeof crypto.KeyObject === "function" &&
                  secretKey instanceof crypto.KeyObject &&
                  Object.prototype.toString.call(secretKey) === "[object KeyObject]" &&
                  Object.isFrozen(secretKey) &&
                  secretKey.type === "secret" &&
                  secretKey.symmetricKeySize === 3 &&
                  typeof secretKey.toCryptoKey === "undefined"
                ));
                console.log("crypto.secretKey.export=" + [
                  secretKey.export().toString("hex"),
                  secretKeyTyped.export().toString("hex"),
                  secretKeyJwk.kty,
                  secretKeyJwk.k
                ].join("/"));
                console.log("crypto.secretKey.equals=" + [
                  secretKey.equals(secretKeyText),
                  secretKey.equals(crypto.createSecretKey("other"))
                ].join("/"));
                console.log("crypto.hmac.keyobject=" + crypto.createHmac("sha256", secretKey).update("abc").digest("hex"));
                console.log("crypto.hkdf.keyobject=" + Buffer.from(
                  crypto.hkdfSync("sha256", crypto.createSecretKey("ikm"), "salt", "info", 16)
                ).toString("hex"));
                console.log("crypto.timingSafeEqual=" + [
                  crypto.timingSafeEqual(Buffer.from("same"), Buffer.from("same")),
                  crypto.timingSafeEqual(Buffer.from("same"), Buffer.from("diff"))
                ].join("/"));
                const pbkdf2Sync = crypto.pbkdf2Sync("password", "salt", 1, 16, "sha256");
                const scryptSync = crypto.scryptSync("password", "salt", 16, { N: 1024, r: 8, p: 1 });
                const hkdfSync = crypto.hkdfSync("sha256", "ikm", "salt", "info", 16);
                console.log("crypto.kdf.sync=" + [
                  pbkdf2Sync.toString("hex"),
                  scryptSync.toString("hex"),
                  Buffer.from(hkdfSync).toString("hex")
                ].join("|"));
                let pbkdf2CallbackSync = true;
                crypto.pbkdf2("password", "salt", 1, 16, "sha256", (error, value) => {
                  console.log("crypto.pbkdf2.callback.async=" + (!pbkdf2CallbackSync));
                  console.log("crypto.pbkdf2.callback=" + (
                    error === null &&
                    Buffer.isBuffer(value) &&
                    value.toString("hex") === "120fb6cffcf8b32c43e7225256c4f837"
                  ));
                });
                pbkdf2CallbackSync = false;
                let scryptCallbackSync = true;
                crypto.scrypt("password", "salt", 16, { N: 1024, r: 8, p: 1 }, (error, value) => {
                  console.log("crypto.scrypt.callback.async=" + (!scryptCallbackSync));
                  console.log("crypto.scrypt.callback=" + (
                    error === null &&
                    Buffer.isBuffer(value) &&
                    value.toString("hex") === "16dbc8906763c7f048977a68f9d305f7"
                  ));
                });
                scryptCallbackSync = false;
                let hkdfCallbackSync = true;
                crypto.hkdf("sha256", "ikm", "salt", "info", 16, (error, value) => {
                  console.log("crypto.hkdf.callback.async=" + (!hkdfCallbackSync));
                  console.log("crypto.hkdf.callback=" + (
                    error === null &&
                    value instanceof ArrayBuffer &&
                    Buffer.from(value).toString("hex") === "fe8f9615d2374c0d17f77d1aeaf408c2"
                  ));
                });
                hkdfCallbackSync = false;
                console.log("crypto.kdf.apis=" + [
                  typeof crypto.pbkdf2,
                  typeof crypto.pbkdf2Sync,
                  typeof crypto.scrypt,
                  typeof crypto.scryptSync,
                  typeof crypto.hkdf,
                  typeof crypto.hkdfSync
                ].join(","));
                console.log("crypto.getHashes=" + crypto.getHashes().join(","));
                console.log("crypto.webcrypto.alias=" + [
                  typeof crypto.webcrypto,
                  crypto.webcrypto === globalThis.crypto,
                  crypto.subtle === globalThis.crypto.subtle,
                  typeof crypto.webcrypto.subtle.importKey,
                  typeof crypto.subtle.sign,
                  Object.isFrozen(crypto.webcrypto),
                  Object.isFrozen(crypto.subtle),
