                ].join("|"));
                console.log("crypto.dangerous=" + [
                  typeof crypto.createPrivateKey,
                  typeof crypto.createPublicKey,
                  typeof crypto.generateKeyPair,
                  typeof crypto.createCipheriv,
                  typeof crypto.createSign,
                  typeof crypto.createVerify,
                  typeof crypto.createDecipheriv
                ].join(","));
                function invalid(label, action) {
                  try {
                    action();
                    console.log(label + ".threw=false");
                  } catch (error) {
                    console.log(label + ".name=" + error.name);
                    console.log(label + ".code=" + error.code);
                  }
                }
                invalid("random.type", () => crypto.randomBytes("8"));
                invalid("random.negative", () => crypto.randomBytes(-1));
                invalid("random.tooLarge", () => crypto.randomBytes(65537));
                invalid("random.callback", () => crypto.randomBytes(1, "not-callback"));
                invalid("randomFill.target", () => crypto.randomFillSync("not-buffer"));
                invalid("randomFill.tooLarge", () => crypto.randomFillSync(Buffer.alloc(65537)));
                invalid("randomInt.callback", () => crypto.randomInt(1, 2, "not-callback"));
                invalid("hash.unsupported", () => crypto.createHash("sha384"));
                invalid("hmac.unsupported", () => crypto.createHmac("sha384", "key"));
                invalid("hmac.keyTooLarge", () => crypto.createHmac("sha256", Buffer.alloc(65537)));
                invalid("secretKey.type", () => crypto.createSecretKey(42));
                invalid("secretKey.keyTooLarge", () => crypto.createSecretKey(Buffer.alloc(65537)));
                invalid("secretKey.exportOptions", () => secretKey.export("buffer"));
                invalid("secretKey.exportFormat", () => secretKey.export({ format: "pem" }));
                invalid("secretKey.equalsType", () => secretKey.equals(Buffer.from("key")));
                invalid("timing.length", () => crypto.timingSafeEqual(Buffer.from("a"), Buffer.from("aa")));
                invalid("pbkdf2.iterations", () => crypto.pbkdf2Sync("password", "salt", 200001, 16, "sha256"));
                invalid("pbkdf2.keylen", () => crypto.pbkdf2Sync("password", "salt", 1, 65537, "sha256"));
                invalid("pbkdf2.digest", () => crypto.pbkdf2Sync("password", "salt", 1, 16, "sha384"));
                invalid("pbkdf2.callback", () => crypto.pbkdf2("password", "salt", 1, 16, "sha256"));
                invalid("scrypt.cost", () => crypto.scryptSync("password", "salt", 16, { N: 32768 }));
                invalid("scrypt.keylen", () => crypto.scryptSync("password", "salt", 65537));
                invalid("scrypt.callback", () => crypto.scrypt("password", "salt", 16));
                invalid("hkdf.digest", () => crypto.hkdfSync("sha384", "ikm", "salt", "info", 16));
                invalid("hkdf.info", () => crypto.hkdfSync("sha256", "ikm", "salt", Buffer.alloc(1025), 16));
                invalid("hkdf.callback", () => crypto.hkdf("sha256", "ikm", "salt", "info", 16));
                console.log("crypto.scheduled=true");
                """.trimIndent(),
                "<embedded-limited-crypto-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(cryptoShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
