    @Test
    fun limitedOsBuiltinProvidesScopedPlatformInfoAndHidesDeviceInfoApis() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-limited-os-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create limited os test dir: $absolutePath" }
        }
        try {
            val osShadow = File(scriptDir, "node_modules/os/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val result = runEmbeddedScript(
                """
                "nodejs";
                const os = require("os");
                const nodeOs = require("node:os");
                const constantsBuiltin = require("constants");
                console.log("os.same=" + (os === nodeOs));
                console.log("os.shadow=" + (os.shadow === true));
                console.log("os.platform=" + os.platform());
                console.log("os.platform.same=" + (os.platform() === process.platform));
                console.log("os.arch.same=" + (os.arch() === process.arch));
                console.log("os.tmpdir.same=" + (os.tmpdir() === process.cwd()));
                console.log("os.homedir.same=" + (os.homedir() === process.cwd()));
                console.log("os.endianness=" + os.endianness());
                console.log("os.type.type=" + typeof os.type());
                console.log("os.release.type=" + typeof os.release());
                const parallelism = os.availableParallelism();
                const machine = os.machine();
                const userInfo = os.userInfo();
                const userInfoBuffer = os.userInfo({ encoding: "buffer" });
                const networkInterfaces = os.networkInterfaces();
                const cpuList = os.cpus();
                const loadAverage = os.loadavg();
                const osConstants = os.constants;
                let setPriorityDisabled = false;
                try {
                  os.setPriority(0);
                } catch (error) {
                  setPriorityDisabled = error.message.includes("disabled");
                }
                console.log("os.extended=" + [
                  typeof os.availableParallelism,
                  typeof os.machine,
                  typeof os.version
                ].join(","));
                console.log("os.availableParallelism=" + (Number.isInteger(parallelism) && parallelism >= 1));
                console.log("os.machine=" + (typeof machine === "string" && machine.length > 0));
                console.log("os.version.type=" + typeof os.version());
                console.log("os.eol=" + JSON.stringify(os.EOL));
                console.log("os.devNull=" + os.devNull);
                console.log("os.safe.types=" + [
                  typeof os.networkInterfaces,
                  typeof os.userInfo,
                  typeof os.cpus,
                  typeof os.freemem,
                  typeof os.totalmem,
                  typeof os.loadavg,
                  typeof os.hostname,
                  typeof os.uptime,
                  typeof os.getPriority,
                  typeof os.setPriority,
                  typeof os.constants
                ].join(","));
                console.log("os.userInfo=" + (
                  userInfo.username === "autojs6" &&
                  userInfo.uid === 0 &&
                  userInfo.gid === 0 &&
                  userInfo.shell === null &&
                  userInfo.homedir === process.cwd() &&
                  Object.isFrozen(userInfo)
                ));
                console.log("os.userInfo.buffer=" + (
                  Buffer.isBuffer(userInfoBuffer.username) &&
                  userInfoBuffer.username.toString() === "autojs6" &&
                  Buffer.isBuffer(userInfoBuffer.homedir) &&
                  userInfoBuffer.homedir.toString() === process.cwd() &&
                  userInfoBuffer.shell === null &&
                  Object.isFrozen(userInfoBuffer)
                ));
                console.log("os.networkInterfaces=" + (
                  networkInterfaces &&
                  typeof networkInterfaces === "object" &&
                  Object.keys(networkInterfaces).length === 0 &&
                  Object.isFrozen(networkInterfaces)
                ));
                console.log("os.hostname=" + os.hostname());
                console.log("os.cpus=" + (
                  Array.isArray(cpuList) &&
                  cpuList.length === 1 &&
                  Object.isFrozen(cpuList) &&
                  Object.isFrozen(cpuList[0]) &&
                  cpuList[0].model === "AutoJs6 Embedded CPU" &&
                  cpuList[0].speed === 0 &&
                  cpuList[0].times.user === 0 &&
                  cpuList[0].times.nice === 0 &&
                  cpuList[0].times.sys === 0 &&
                  cpuList[0].times.idle === 0 &&
                  cpuList[0].times.irq === 0 &&
                  Object.isFrozen(cpuList[0].times)
                ));
                console.log("os.memory=" + (os.freemem() === 268435456 && os.totalmem() === 536870912));
                console.log("os.loadavg=" + (Array.isArray(loadAverage) && loadAverage.join(",") === "0,0,0" && Object.isFrozen(loadAverage)));
                console.log("os.uptime=" + (typeof os.uptime() === "number" && os.uptime() >= 0));
                console.log("os.priority=" + (os.getPriority() === 0 && setPriorityDisabled));
                console.log("os.constants=" + (
                  osConstants &&
                  typeof osConstants === "object" &&
                  Object.isFrozen(osConstants) &&
                  Object.isFrozen(osConstants.signals) &&
                  Object.isFrozen(osConstants.errno) &&
                  Object.isFrozen(osConstants.dlopen) &&
                  Object.isFrozen(osConstants.priority) &&
                  osConstants.signals.SIGINT === 2 &&
                  osConstants.signals.SIGTERM === 15 &&
                  osConstants.errno.EPERM === 1 &&
                  osConstants.errno.ENOENT === 2 &&
                  osConstants.errno.EACCES === 13 &&
                  osConstants.dlopen.RTLD_NOW === 2 &&
                  osConstants.priority.PRIORITY_NORMAL === 0 &&
                  constantsBuiltin.os === osConstants &&
                  constantsBuiltin.signals === osConstants.signals &&
                  constantsBuiltin.errno === osConstants.errno &&
                  constantsBuiltin.SIGINT === osConstants.signals.SIGINT &&
                  constantsBuiltin.EACCES === osConstants.errno.EACCES
                ));
                """.trimIndent(),
                "<embedded-limited-os-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(osShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("os.same=true"))
            assertTrue(result.stdout.contains("os.shadow=false"))
            assertTrue(result.stdout.contains("os.platform.same=true"))
            assertTrue(result.stdout.contains("os.arch.same=true"))
            assertTrue(result.stdout.contains("os.tmpdir.same=true"))
            assertTrue(result.stdout.contains("os.homedir.same=true"))
            assertTrue(result.stdout.contains("os.endianness="))
            assertTrue(result.stdout.contains("os.type.type=string"))
            assertTrue(result.stdout.contains("os.release.type=string"))
            assertTrue(result.stdout.contains("os.extended=function,function,function"))
            assertTrue(result.stdout.contains("os.availableParallelism=true"))
            assertTrue(result.stdout.contains("os.machine=true"))
            assertTrue(result.stdout.contains("os.version.type=string"))
            assertTrue(result.stdout.contains("os.eol=\"\\n\""))
            assertTrue(result.stdout.contains("os.devNull=/dev/null"))
            assertTrue(result.stdout.contains("os.safe.types=function,function,function,function,function,function,function,function,function,function,object"))
            assertTrue(result.stdout.contains("os.userInfo=true"))
            assertTrue(result.stdout.contains("os.userInfo.buffer=true"))
            assertTrue(result.stdout.contains("os.networkInterfaces=true"))
            assertTrue(result.stdout.contains("os.hostname=localhost"))
            assertTrue(result.stdout.contains("os.cpus=true"))
            assertTrue(result.stdout.contains("os.memory=true"))
            assertTrue(result.stdout.contains("os.loadavg=true"))
            assertTrue(result.stdout.contains("os.uptime=true"))
            assertTrue(result.stdout.contains("os.priority=true"))
            assertTrue(result.stdout.contains("os.constants=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun limitedDnsBuiltinSupportsLocalLookupsAndBlocksNetworkResolution() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-limited-dns-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create limited dns test dir: $absolutePath" }
        }
        try {
            val dnsShadow = File(scriptDir, "node_modules/dns/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val dnsPromisesShadow = File(scriptDir, "node_modules/dns/promises.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val result = runEmbeddedScript(
                """
                "nodejs";
                const dns = require("dns");
                const nodeDns = require("node:dns");
                const dnsPromises = require("dns/promises");
                const nodeDnsPromises = require("node:dns/promises");
                const moduleBuiltin = require("module");

                function lookup(hostname, options) {
                  return new Promise((resolve) => {
                    const done = (error, address, family) => resolve({
                      code: error && error.code,
                      address,
                      family
                    });
                    if (arguments.length === 1) {
                      dns.lookup(hostname, done);
                    } else {
                      dns.lookup(hostname, options, done);
                    }
                  });
                }
                function lookupAll(hostname, options) {
                  return new Promise((resolve) => {
                    dns.lookup(hostname, Object.assign({ all: true }, options || {}), (error, addresses) => resolve({
                      code: error && error.code,
                      addresses: addresses || []
                    }));
                  });
                }
                function lookupService(address, port) {
                  return new Promise((resolve) => {
                    dns.lookupService(address, port, (error, hostname, service) => resolve({
                      code: error && error.code,
                      hostname,
                      service
                    }));
                  });
                }
                function resolve4(hostname) {
                  return new Promise((resolve) => {
                    dns.resolve4(hostname, (error) => resolve(error && error.code));
                  });
                }

                async function run() {
                  const local4 = await lookup("localhost", { family: 4 });
                  const local6 = await dnsPromises.lookup("localhost", { family: 6 });
                  const literal4 = await dnsPromises.lookup("127.0.0.1");
                  const literal6 = await dnsPromises.lookup("::1");
                  const allLocal = await lookupAll("localhost");
                  const deniedLookup = await lookup("example.com");
                  const deniedPromiseLookup = await dnsPromises.lookup("example.com").then(
                    () => "allowed",
                    (error) => error && error.code
                  );
                  const deniedResolve = await resolve4("example.com");
                  const deniedPromiseResolve = await dnsPromises.resolve6("example.com").then(
                    () => "allowed",
                    (error) => error && error.code
                  );
                  const service4 = await lookupService("127.0.0.1", 443);
                  const service6 = await dnsPromises.lookupService("::1", 8443);
                  const deniedService = await lookupService("192.0.2.1", 443);
                  const resolverDenied = await new dns.Resolver().resolve4("example.com", (error) => {
                    console.log("dns.resolver.callback=" + (error && error.code));
                  });
                  const promiseResolverDenied = await new dnsPromises.Resolver().resolve4("example.com").then(
                    () => "allowed",
                    (error) => error && error.code
                  );
                  const beforeOrder = dns.getDefaultResultOrder();
                  dns.setDefaultResultOrder("ipv6first");
                  const ordered6 = await dnsPromises.lookup("localhost", { all: true });
                  dns.setDefaultResultOrder("ipv4first");
                  const ordered4 = await dnsPromises.lookup("localhost", { all: true });
                  dns.setDefaultResultOrder(beforeOrder);
                  let invalidOrderCode = "";
                  try {
                    dns.setDefaultResultOrder("bad");
                  } catch (error) {
                    invalidOrderCode = error && error.code;
                  }
                  dns.setServers([]);
                  let setServersCode = "";
                  try {
                    dns.setServers(["8.8.8.8"]);
                  } catch (error) {
                    setServersCode = error && error.code;
                  }
                  const shadowLoaded = Object.keys(require.cache).some((filename) => {
                    const normalized = filename.replace(/\\/g, "/");
                    return normalized.includes("/node_modules/dns/");
                  });
                  console.log("dns.same=" + (dns === nodeDns));
                  console.log("dns.promises.same=" + (dns.promises === dnsPromises && dnsPromises === nodeDnsPromises));
                  console.log("dns.shadow=" + (dns.shadow === undefined && dnsPromises.shadow === undefined && !shadowLoaded));
                  console.log("dns.local=" + (
                    local4.address === "127.0.0.1" &&
                    local4.family === 4 &&
                    local6.address === "::1" &&
                    local6.family === 6
                  ));
                  console.log("dns.literal=" + (
                    literal4.address === "127.0.0.1" &&
                    literal4.family === 4 &&
                    literal6.address === "::1" &&
                    literal6.family === 6
                  ));
                  console.log("dns.all=" + (
                    allLocal.addresses.length >= 2 &&
                    allLocal.addresses.some((entry) => entry.address === "127.0.0.1" && entry.family === 4) &&
                    allLocal.addresses.some((entry) => entry.address === "::1" && entry.family === 6)
                  ));
                  console.log("dns.lookup.denied=" + deniedLookup.code + "/" + deniedPromiseLookup);
                  console.log("dns.resolve.denied=" + deniedResolve + "/" + deniedPromiseResolve);
                  console.log("dns.lookupService=" + (
                    service4.hostname === "localhost" &&
                    service4.service === "443" &&
                    service6.hostname === "localhost" &&
                    service6.service === "8443" &&
                    deniedService.code === "ENOTFOUND"
                  ));
                  console.log("dns.resolver.promise=" + promiseResolverDenied);
                  console.log("dns.servers=" + (
                    Array.isArray(dns.getServers()) &&
                    dns.getServers().length === 0 &&
                    Object.isFrozen(dns.getServers()) &&
                    setServersCode === "ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED"
                  ));
                  console.log("dns.order=" + (
                    ordered6[0].family === 6 &&
                    ordered4[0].family === 4 &&
                    dns.getDefaultResultOrder() === beforeOrder &&
                    invalidOrderCode === "ERR_INVALID_ARG_VALUE"
                  ));
                  console.log("dns.constants=" + (
                    typeof dns.ADDRCONFIG === "number" &&
                    typeof dns.ALL === "number" &&
                    typeof dns.V4MAPPED === "number" &&
                    dns.NOTFOUND === "ENOTFOUND"
                  ));
                  console.log("dns.frozen=" + (
                    Object.isFrozen(dns) &&
                    Object.isFrozen(dns.promises) &&
                    Object.isFrozen(dns.Resolver.prototype) &&
                    Object.isFrozen(dnsPromises.Resolver.prototype)
                  ));
                  console.log("dns.helpers=" + [
                    typeof dns.lookup,
                    typeof dns.lookupService,
                    typeof dns.resolve4,
                    typeof dns.reverse,
                    typeof dns.Resolver,
                    typeof dns.promises.lookup,
                    typeof dnsPromises.Resolver,
                    typeof dns.ADDRCONFIG,
                    typeof dns.NOTFOUND
                  ].join(","));
                  console.log("dns.resolve=" + [
                    require.resolve("dns"),
                    require.resolve("node:dns"),
                    require.resolve("dns/promises"),
                    require.resolve("node:dns/promises")
                  ].join("/"));
                  console.log("dns.moduleBuiltin=" + (
                    moduleBuiltin.isBuiltin("dns") &&
                    moduleBuiltin.isBuiltin("node:dns/promises") &&
                    moduleBuiltin.builtinModules.includes("dns") &&
                    moduleBuiltin.builtinModules.includes("dns/promises")
                  ));
                }
                const runPromise = run();
                console.log("dns.scheduled=true");
                return runPromise;
                """.trimIndent(),
                "<embedded-limited-dns-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(dnsShadow, dnsPromisesShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertOutputOrder(result.stdout, "dns.scheduled=true", "dns.same=true")
            assertTrue(result.stdout.contains("dns.same=true"))
            assertTrue(result.stdout.contains("dns.promises.same=true"))
            assertTrue(result.stdout.contains("dns.shadow=true"))
            assertTrue(result.stdout.contains("dns.local=true"))
            assertTrue(result.stdout.contains("dns.literal=true"))
            assertTrue(result.stdout.contains("dns.all=true"))
            assertTrue(result.stdout.contains("dns.lookup.denied=ENOTFOUND/ENOTFOUND"))
            assertTrue(result.stdout.contains("dns.resolve.denied=ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED/ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED"))
            assertTrue(result.stdout.contains("dns.lookupService=true"))
            assertTrue(result.stdout.contains("dns.resolver.callback=ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED"))
            assertTrue(result.stdout.contains("dns.resolver.promise=ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED"))
            assertTrue(result.stdout.contains("dns.servers=true"))
            assertTrue(result.stdout.contains("dns.order=true"))
            assertTrue(result.stdout.contains("dns.constants=true"))
            assertTrue(result.stdout.contains("dns.frozen=true"))
            assertTrue(result.stdout.contains("dns.helpers=function,function,function,function,function,function,function,number,string"))
            assertTrue(result.stdout.contains("dns.resolve=dns/dns/dns/promises/dns/promises"))
            assertTrue(result.stdout.contains("dns.moduleBuiltin=true"))
            assertEquals(0, result.pendingDnsCallbacks ?: -1)
            assertEquals(0, result.pendingAsyncCallbacks ?: -1)
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun limitedNetBuiltinSupportsIpHelpersAndBlocksNetworkSockets() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-limited-net-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create limited net test dir: $absolutePath" }
        }
        try {
            val netShadow = File(scriptDir, "node_modules/net/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val result = runEmbeddedScript(
                """
                "nodejs";
                const net = require("net");
                const nodeNet = require("node:net");
                const moduleBuiltin = require("module");

                function disabled(action) {
                  try {
                    action();
                    return "allowed";
                  } catch (error) {
                    return error && error.code;
                  }
                }
                async function tick() {
                  await new Promise((resolve) => setImmediate(resolve));
                }

                async function run() {
                  const socket = new net.Socket({ allowHalfOpen: true });
                  let socketWriteCode = "";
                  const socketWriteReturn = socket.write("blocked", (error) => {
                    socketWriteCode = error && error.code;
                  });
                  await tick();
                  socket.setTimeout(1, () => {});
                  socket.setNoDelay(true).setKeepAlive(false).ref().unref().pause().resume().destroy();

                  const server = net.createServer(() => {});
                  let getConnectionsSummary = "";
                  let closeSeen = false;
                  server.getConnections((error, count) => {
                    getConnectionsSummary = (error === null) + "/" + count;
                  });
                  server.close(() => {
                    closeSeen = true;
                  });
                  await tick();

                  const blockList = new net.BlockList();
                  blockList.addAddress("127.0.0.1");
                  blockList.addRange("10.0.0.1", "10.0.0.3");
                  blockList.addSubnet("192.168.1.0", 24);
                  const socketAddress = new net.SocketAddress({ address: "127.0.0.1", port: 8080 });
                  const parsed4 = net.SocketAddress.parse("127.0.0.1:8080");
                  const parsed6 = net.SocketAddress.parse("[::1]:443");
                  const shadowLoaded = Object.keys(require.cache).some((filename) => {
                    return filename.replace(/\\/g, "/").includes("/node_modules/net/");
                  });
                  let invalidSocketAddress = "";
                  try {
                    new net.SocketAddress({ address: "localhost", port: 80 });
                  } catch (error) {
                    invalidSocketAddress = error && error.code;
                  }
                  let invalidBlockList = "";
                  try {
                    blockList.addSubnet("127.0.0.1", 33);
                  } catch (error) {
                    invalidBlockList = error && error.code;
                  }
                  net.setDefaultAutoSelectFamily(false);
                  net.setDefaultAutoSelectFamilyAttemptTimeout(123);
                  let invalidAutoFamily = "";
                  try {
                    net.setDefaultAutoSelectFamily("yes");
                  } catch (error) {
                    invalidAutoFamily = error && error.code;
                  }
                  let invalidAutoTimeout = "";
                  try {
                    net.setDefaultAutoSelectFamilyAttemptTimeout(0);
                  } catch (error) {
                    invalidAutoTimeout = error && error.code;
                  }

                  console.log("net.same=" + (net === nodeNet));
                  console.log("net.shadow=" + (net.shadow === undefined && !shadowLoaded));
                  console.log("net.ip=" + [
                    net.isIP("127.0.0.1"),
                    net.isIP("::1"),
                    net.isIP("localhost"),
                    net.isIPv4("127.0.0.1"),
                    net.isIPv6("2001:db8::1"),
                    net.isIPv6("127.0.0.1")
                  ].join("/"));
                  console.log("net.socket=" + (
                    socket instanceof net.Socket &&
                    socket instanceof net.Stream &&
                    socket.allowHalfOpen === true &&
                    socketWriteReturn === false &&
                    socketWriteCode === "ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED" &&
                    socket.destroyed === true &&
                    disabled(() => socket.connect(80, "example.com")) === "ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED"
                  ));
                  console.log("net.server=" + (
                    server instanceof net.Server &&
                    server.listening === false &&
                    server.address() === null &&
                    getConnectionsSummary === "true/0" &&
                    closeSeen === true &&
                    disabled(() => server.listen(0)) === "ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED"
                  ));
                  console.log("net.blockList=" + (
                    blockList.check("127.0.0.1") &&
                    blockList.check("10.0.0.2") &&
                    blockList.check("192.168.1.42") &&
                    !blockList.check("10.0.0.4") &&
                    blockList.rules.length === 3 &&
                    Object.isFrozen(blockList.rules) &&
                    invalidBlockList === "ERR_INVALID_ARG_VALUE"
                  ));
                  console.log("net.socketAddress=" + (
                    socketAddress.address === "127.0.0.1" &&
                    socketAddress.port === 8080 &&
                    socketAddress.family === "ipv4" &&
                    parsed4.port === 8080 &&
                    parsed6.address === "::1" &&
                    parsed6.family === "ipv6" &&
                    net.SocketAddress.parse("bad") === undefined &&
                    net.isSocketAddress(socketAddress) &&
                    invalidSocketAddress === "ERR_INVALID_ARG_VALUE" &&
                    Object.isFrozen(socketAddress)
                  ));
                  console.log("net.disabled=" + [
                    disabled(() => net.connect(80, "example.com")),
                    disabled(() => net.createConnection(80, "example.com")),
                    disabled(() => net.createServer().listen(0))
                  ].join("/"));
                  console.log("net.autoSelect=" + (
                    net.getDefaultAutoSelectFamily() === false &&
                    net.getDefaultAutoSelectFamilyAttemptTimeout() === 123 &&
                    invalidAutoFamily === "ERR_INVALID_ARG_TYPE" &&
                    invalidAutoTimeout === "ERR_INVALID_ARG_VALUE"
                  ));
                  console.log("net.frozen=" + (
                    Object.isFrozen(net) &&
                    Object.isFrozen(net.Socket) &&
                    Object.isFrozen(net.Socket.prototype) &&
                    Object.isFrozen(net.Server.prototype) &&
                    Object.isFrozen(net.BlockList.prototype) &&
                    Object.isFrozen(net.SocketAddress)
                  ));
                  console.log("net.helpers=" + [
                    typeof net.isIP,
                    typeof net.isIPv4,
                    typeof net.isIPv6,
                    typeof net.connect,
                    typeof net.createConnection,
                    typeof net.createServer,
                    typeof net.Socket,
                    typeof net.Server,
                    typeof net.BlockList,
                    typeof net.SocketAddress,
                    typeof net.SocketAddress.parse,
                    typeof net._createServerHandle
                  ].join(","));
                  console.log("net.resolve=" + [
                    require.resolve("net"),
                    require.resolve("node:net")
                  ].join("/"));
                  console.log("net.moduleBuiltin=" + (
                    moduleBuiltin.isBuiltin("net") &&
                    moduleBuiltin.isBuiltin("node:net") &&
                    moduleBuiltin.builtinModules.includes("net")
                  ));
                }
                const runPromise = run();
                console.log("net.scheduled=true");
                return runPromise;
                """.trimIndent(),
                "<embedded-limited-net-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(netShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertOutputOrder(result.stdout, "net.scheduled=true", "net.same=true")
            assertTrue(result.stdout.contains("net.same=true"))
            assertTrue(result.stdout.contains("net.shadow=true"))
            assertTrue(result.stdout.contains("net.ip=4/6/0/true/true/false"))
            assertTrue(result.stdout.contains("net.socket=true"))
            assertTrue(result.stdout.contains("net.server=true"))
            assertTrue(result.stdout.contains("net.blockList=true"))
            assertTrue(result.stdout.contains("net.socketAddress=true"))
            assertTrue(result.stdout.contains("net.disabled=ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED/ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED/ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED"))
            assertTrue(result.stdout.contains("net.autoSelect=true"))
            assertTrue(result.stdout.contains("net.frozen=true"))
            assertTrue(result.stdout.contains("net.helpers=function,function,function,function,function,function,function,function,function,function,function,undefined"))
            assertTrue(result.stdout.contains("net.resolve=net/net"))
            assertTrue(result.stdout.contains("net.moduleBuiltin=true"))
            assertEquals(0, result.pendingAsyncCallbacks ?: -1)
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun limitedHttpBuiltinsExposeMetadataAndBlockNetworkRequests() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-limited-http-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create limited http test dir: $absolutePath" }
        }
        try {
            val httpShadow = File(scriptDir, "node_modules/http/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val httpsShadow = File(scriptDir, "node_modules/https/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val result = runEmbeddedScript(
                """
                "nodejs";
                const http = require("http");
                const nodeHttp = require("node:http");
                const https = require("https");
                const nodeHttps = require("node:https");
                const moduleBuiltin = require("module");

                function disabled(action) {
                  try {
                    action();
                    return "allowed";
                  } catch (error) {
                    return error && error.code;
                  }
                }
                async function tick() {
                  await new Promise((resolve) => setImmediate(resolve));
                }

                async function run() {
                  const shadowLoaded = Object.keys(require.cache).some((filename) => {
                    const normalized = filename.replace(/\\/g, "/");
                    return normalized.includes("/node_modules/http/") ||
                      normalized.includes("/node_modules/https/");
                  });
                  const agent = new http.Agent({ keepAlive: true, maxSockets: 3 });
                  const secureAgent = new https.Agent({ keepAlive: true });
                  const request = new http.ClientRequest("http://example.com/a?b=1");
                  request.setHeader("X-Test", "yes");
                  const requestHeaders = request.getHeaders();
                  let requestEnded = false;
                  request.end(() => {
                    requestEnded = true;
                  });
                  request.abort();
                  const incoming = new http.IncomingMessage();
                  const response = new http.ServerResponse(incoming);
                  response.setHeader("X-Response", "ok");
                  response.writeHead(201, { "X-Head": "yes" });
                  let responseEnded = false;
                  response.end(() => {
                    responseEnded = true;
                  });
                  const server = http.createServer(() => {});
                  const secureServer = https.createServer(() => {});
                  let closeSeen = false;
                  server.setTimeout(1, () => {}).ref().unref();
                  server.close(() => {
                    closeSeen = true;
                  });
                  await tick();

                  let invalidHeaderName = "";
                  try {
                    http.validateHeaderName("bad header");
                  } catch (error) {
                    invalidHeaderName = error && error.code;
                  }
                  let invalidHeaderValue = "";
                  try {
                    http.validateHeaderValue("x-test", "bad\nvalue");
                  } catch (error) {
                    invalidHeaderValue = error && error.code;
                  }
                  let invalidParserCount = "";
                  try {
                    http.setMaxIdleHTTPParsers(0);
                  } catch (error) {
                    invalidParserCount = error && error.code;
                  }
                  http.validateHeaderName("x-ok");
                  http.validateHeaderValue("x-ok", ["a", "b"]);
                  http.setMaxIdleHTTPParsers(1);

                  console.log("http.same=" + (http === nodeHttp && https === nodeHttps));
                  console.log("http.shadow=" + (
                    http.shadow === undefined &&
                    https.shadow === undefined &&
                    !shadowLoaded
                  ));
                  console.log("http.constants=" + (
                    http.METHODS.includes("GET") &&
                    http.METHODS.includes("POST") &&
                    http.STATUS_CODES[200] === "OK" &&
                    http.STATUS_CODES[404] === "Not Found" &&
                    Object.isFrozen(http.METHODS) &&
                    Object.isFrozen(http.STATUS_CODES)
                  ));
                  console.log("http.agent=" + (
                    agent instanceof http.Agent &&
                    secureAgent instanceof https.Agent &&
                    agent.keepAlive === true &&
                    agent.defaultPort === 80 &&
                    agent.protocol === "http:" &&
                    secureAgent.defaultPort === 443 &&
                    secureAgent.protocol === "https:" &&
                    agent.getName({ host: "example.com", port: 8080 }).startsWith("example.com:8080") &&
                    disabled(() => agent.createConnection({})) === "ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED"
                  ));
                  console.log("http.messages=" + (
                    request instanceof http.ClientRequest &&
                    request instanceof http.OutgoingMessage &&
                    request.method === "GET" &&
                    request.path === "/a?b=1" &&
                    request.getHeader("x-test") === "yes" &&
                    requestHeaders["x-test"] === "yes" &&
                    request.hasHeader("X-Test") &&
                    Object.isFrozen(request.getHeaderNames()) &&
                    requestEnded === true &&
                    request.aborted === true &&
                    incoming instanceof http.IncomingMessage &&
                    incoming.httpVersion === "1.1" &&
                    response instanceof http.ServerResponse &&
                    response instanceof http.OutgoingMessage &&
                    response.statusCode === 201 &&
                    response.statusMessage === "Created" &&
                    response.getHeader("x-response") === "ok" &&
                    response.getHeader("x-head") === "yes" &&
                    response.headersSent === true &&
                    responseEnded === true
                  ));
                  console.log("http.server=" + (
                    server instanceof http.Server &&
                    secureServer instanceof https.Server &&
                    server.address() === null &&
                    server.timeout === 1 &&
                    closeSeen === true &&
                    disabled(() => server.listen(0)) === "ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED" &&
                    disabled(() => secureServer.listen(0)) === "ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED"
                  ));
                  console.log("http.disabled=" + [
                    disabled(() => http.request("http://example.com")),
                    disabled(() => http.get("http://example.com")),
                    disabled(() => https.request("https://example.com")),
                    disabled(() => https.get("https://example.com"))
                  ].join("/"));
                  console.log("http.validation=" + [
                    invalidHeaderName,
                    invalidHeaderValue,
                    invalidParserCount
                  ].join("/"));
                  console.log("http.frozen=" + (
                    Object.isFrozen(http) &&
                    Object.isFrozen(https) &&
                    Object.isFrozen(http.Agent) &&
                    Object.isFrozen(http.Agent.prototype) &&
                    Object.isFrozen(http.ClientRequest.prototype) &&
                    Object.isFrozen(http.Server.prototype) &&
                    Object.isFrozen(http.ServerResponse.prototype)
                  ));
                  console.log("http.helpers=" + [
                    typeof http.request,
                    typeof http.get,
                    typeof http.createServer,
                    typeof http.Agent,
                    typeof http.ClientRequest,
                    typeof http.IncomingMessage,
                    typeof http.OutgoingMessage,
                    typeof http.Server,
                    typeof http.ServerResponse,
                    typeof http.validateHeaderName,
                    typeof http.validateHeaderValue,
                    typeof http.setMaxIdleHTTPParsers,
                    typeof http.globalAgent,
                    typeof http.METHODS,
                    typeof http.STATUS_CODES,
                    typeof http._connectionListener
                  ].join(","));
                  console.log("http.resolve=" + [
                    require.resolve("http"),
                    require.resolve("node:http"),
                    require.resolve("https"),
                    require.resolve("node:https")
                  ].join("/"));
                  console.log("http.moduleBuiltin=" + (
                    moduleBuiltin.isBuiltin("http") &&
                    moduleBuiltin.isBuiltin("node:https") &&
                    moduleBuiltin.builtinModules.includes("http") &&
                    moduleBuiltin.builtinModules.includes("https")
                  ));
                }
                const runPromise = run();
                console.log("http.scheduled=true");
                return runPromise;
                """.trimIndent(),
                "<embedded-limited-http-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(httpShadow, httpsShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertOutputOrder(result.stdout, "http.scheduled=true", "http.same=true")
            assertTrue(result.stdout.contains("http.same=true"))
            assertTrue(result.stdout.contains("http.shadow=true"))
            assertTrue(result.stdout.contains("http.constants=true"))
            assertTrue(result.stdout.contains("http.agent=true"))
            assertTrue(result.stdout.contains("http.messages=true"))
            assertTrue(result.stdout.contains("http.server=true"))
            assertTrue(result.stdout.contains("http.disabled=ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED/ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED/ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED/ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED"))
            assertTrue(result.stdout.contains("http.validation=ERR_INVALID_HTTP_TOKEN/ERR_INVALID_CHAR/ERR_INVALID_ARG_VALUE"))
            assertTrue(result.stdout.contains("http.frozen=true"))
            assertTrue(result.stdout.contains("http.helpers=function,function,function,function,function,function,function,function,function,function,function,function,object,object,object,undefined"))
            assertTrue(result.stdout.contains("http.resolve=http/http/https/https"))
            assertTrue(result.stdout.contains("http.moduleBuiltin=true"))
            assertEquals(0, result.pendingAsyncCallbacks ?: -1)
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun limitedTlsBuiltinExposesContextMetadataAndBlocksTlsSockets() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-limited-tls-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create limited tls test dir: $absolutePath" }
        }
        try {
            val tlsShadow = File(scriptDir, "node_modules/tls/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val result = runEmbeddedScript(
                """
                "nodejs";
                const tls = require("tls");
                const nodeTls = require("node:tls");
                const net = require("net");
                const moduleBuiltin = require("module");

                function disabled(action) {
                  try {
                    action();
                    return "allowed";
                  } catch (error) {
                    return error && error.code;
                  }
                }
                async function tick() {
                  await new Promise((resolve) => setImmediate(resolve));
                }

                async function run() {
                  const shadowLoaded = Object.keys(require.cache).some((filename) => {
                    return filename.replace(/\\/g, "/").includes("/node_modules/tls/");
                  });
                  const context = tls.createSecureContext({ minVersion: "TLSv1.2", ca: "cert" });
                  const socket = new tls.TLSSocket(new net.Socket(), { servername: "example.com" });
                  let renegotiateCode = "";
                  const renegotiateReturn = socket.renegotiate({}, (error) => {
                    renegotiateCode = error && error.code;
                  });
                  await tick();
                  const detailedCert = socket.getPeerCertificate(true);
                  const cipher = socket.getCipher();
                  let invalidFragment = "";
                  try {
                    socket.setMaxSendFragment(0);
                  } catch (error) {
                    invalidFragment = error && error.code;
                  }
                  const server = tls.createServer({ requestCert: true }, () => {});
                  server.addContext("example.com", context);
                  server.setSecureContext({ minVersion: "TLSv1.3" });
                  server.setTicketKeys(Buffer.alloc(48));
                  const ticketKeys = server.getTicketKeys();
                  let invalidTicketKeys = "";
                  try {
                    server.setTicketKeys(Buffer.alloc(16));
                  } catch (error) {
                    invalidTicketKeys = error && error.code;
                  }
                  let closeSeen = false;
                  server.close(() => {
                    closeSeen = true;
                  });
                  await tick();
                  let invalidHostname = "";
                  try {
                    tls.checkServerIdentity(123, {});
                  } catch (error) {
                    invalidHostname = error && error.code;
                  }

                  console.log("tls.same=" + (tls === nodeTls));
                  console.log("tls.shadow=" + (tls.shadow === undefined && !shadowLoaded));
                  console.log("tls.context=" + (
                    context instanceof tls.SecureContext &&
                    context.secureProtocol === "TLSv1.2" &&
                    context.context.ca === "cert" &&
                    Object.isFrozen(context) &&
                    Object.isFrozen(context.context)
                  ));
                  console.log("tls.socket=" + (
                    socket instanceof tls.TLSSocket &&
                    socket instanceof net.Socket &&
                    socket.encrypted === true &&
                    socket.servername === "example.com" &&
                    socket.getProtocol() === null &&
                    cipher.name === "TLS_AES_256_GCM_SHA384" &&
                    Object.isFrozen(socket.getSharedSigalgs()) &&
                    Object.isFrozen(socket.getEphemeralKeyInfo()) &&
                    Object.isFrozen(detailedCert.ext_key_usage) &&
                    socket.setMaxSendFragment(1024) === true &&
                    invalidFragment === "ERR_INVALID_ARG_VALUE" &&
                    renegotiateReturn === false &&
                    renegotiateCode === "ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED" &&
                    disabled(() => socket.connect(443, "example.com")) === "ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED" &&
                    disabled(() => socket.exportKeyingMaterial(16, "label")) === "ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED"
                  ));
                  console.log("tls.server=" + (
                    server instanceof tls.Server &&
                    server instanceof net.Server &&
                    server.requestCert === true &&
                    server.rejectUnauthorized === true &&
                    server.secureContext instanceof tls.SecureContext &&
                    ticketKeys.length === 48 &&
                    invalidTicketKeys === "ERR_INVALID_ARG_VALUE" &&
                    closeSeen === true &&
                    disabled(() => server.listen(0)) === "ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED"
                  ));
                  console.log("tls.disabled=" + [
                    disabled(() => tls.connect(443, "example.com")),
                    disabled(() => tls.createConnection(443, "example.com")),
                    disabled(() => tls.createServer().listen(0))
                  ].join("/"));
                  console.log("tls.constants=" + (
                    tls.getCiphers().includes("TLS_AES_256_GCM_SHA384") &&
                    Object.isFrozen(tls.getCiphers()) &&
                    Array.isArray(tls.rootCertificates) &&
                    Object.isFrozen(tls.rootCertificates) &&
                    tls.DEFAULT_MIN_VERSION === "TLSv1.2" &&
                    tls.DEFAULT_MAX_VERSION === "TLSv1.3" &&
                    tls.DEFAULT_ECDH_CURVE === "auto" &&
                    tls.CLIENT_RENEG_LIMIT === 3 &&
                    tls.checkServerIdentity("example.com", {}) === undefined &&
                    invalidHostname === "ERR_INVALID_ARG_TYPE"
                  ));
                  console.log("tls.frozen=" + (
                    Object.isFrozen(tls) &&
                    Object.isFrozen(tls.SecureContext) &&
                    Object.isFrozen(tls.SecureContext.prototype) &&
                    Object.isFrozen(tls.TLSSocket) &&
                    Object.isFrozen(tls.TLSSocket.prototype) &&
                    Object.isFrozen(tls.Server.prototype)
                  ));
                  console.log("tls.helpers=" + [
                    typeof tls.connect,
                    typeof tls.createConnection,
                    typeof tls.createServer,
                    typeof tls.createSecureContext,
                    typeof tls.checkServerIdentity,
                    typeof tls.getCiphers,
                    typeof tls.TLSSocket,
                    typeof tls.Server,
                    typeof tls.SecureContext,
                    typeof tls.rootCertificates,
                    typeof tls.DEFAULT_MIN_VERSION,
                    typeof tls.createSecurePair
                  ].join(","));
                  console.log("tls.resolve=" + [
                    require.resolve("tls"),
                    require.resolve("node:tls")
                  ].join("/"));
                  console.log("tls.moduleBuiltin=" + (
                    moduleBuiltin.isBuiltin("tls") &&
                    moduleBuiltin.isBuiltin("node:tls") &&
                    moduleBuiltin.builtinModules.includes("tls")
                  ));
                }
                const runPromise = run();
                console.log("tls.scheduled=true");
                return runPromise;
                """.trimIndent(),
                "<embedded-limited-tls-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(tlsShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertOutputOrder(result.stdout, "tls.scheduled=true", "tls.same=true")
            assertTrue(result.stdout.contains("tls.same=true"))
            assertTrue(result.stdout.contains("tls.shadow=true"))
            assertTrue(result.stdout.contains("tls.context=true"))
            assertTrue(result.stdout.contains("tls.socket=true"))
            assertTrue(result.stdout.contains("tls.server=true"))
            assertTrue(result.stdout.contains("tls.disabled=ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED/ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED/ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED"))
            assertTrue(result.stdout.contains("tls.constants=true"))
            assertTrue(result.stdout.contains("tls.frozen=true"))
            assertTrue(result.stdout.contains("tls.helpers=function,function,function,function,function,function,function,function,function,object,string,undefined"))
            assertTrue(result.stdout.contains("tls.resolve=tls/tls"))
            assertTrue(result.stdout.contains("tls.moduleBuiltin=true"))
            assertEquals(0, result.pendingAsyncCallbacks ?: -1)
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
