                        kdf: derived.summary,
                        secret: secret.summary,
                        webcrypto: web.summary,
                        uuid: signed.uuidSummary,
                        platform: osInfo.platform,
                        tmpdirSame: osInfo.tmpdirSame,
                        osExtended: [
                          osInfo.parallelismOk,
