            val kdf = File(scriptDir, "node_modules/pkg-kdf-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const crypto = require("crypto");
                    exports.derive = function derive() {
                      const pbkdf2 = crypto.pbkdf2Sync("password", "salt", 1, 16, "sha256").toString("hex");
                      const scrypt = crypto.scryptSync("password", "salt", 16, { N: 1024, r: 8, p: 1 }).toString("hex");
                      const hkdf = Buffer.from(crypto.hkdfSync("sha256", "ikm", "salt", "info", 16)).toString("hex");
                      return {
                        ok: pbkdf2 === "120fb6cffcf8b32c43e7225256c4f837" &&
