                        constantsBuiltin.ENOENT === osConstants.errno.ENOENT &&
                        setPriorityDisabled;
                      return {
                        platform: os.platform(),
                        arch: os.arch(),
                        tmpdirSame: os.tmpdir() === process.cwd(),
                        homedirSame: os.homedir() === process.cwd(),
                        parallelismOk: Number.isInteger(parallelism) && parallelism >= 1,
                        machineOk: typeof machine === "string" && machine.length > 0,
                        versionOk: typeof os.version() === "string",
                        safeOsOk,
                        processTimingOk: typeof process.uptime === "function" &&
                          process.uptime() >= 0 &&
                          Array.isArray(hr) &&
                          hr.length === 2 &&
                          Number.isInteger(hr[0]) &&
                          Number.isInteger(hr[1]) &&
                          Array.isArray(hrDiff) &&
                          hrDiff.length === 2 &&
                          typeof process.hrtime.bigint === "function" &&
                          hrBigint > 0n,
                        processUsageOk: typeof process.cpuUsage === "function" &&
                          typeof cpu.user === "number" &&
                          typeof cpu.system === "number" &&
                          typeof cpuDiff.user === "number" &&
                          typeof cpuDiff.system === "number" &&
