            assertTrue(result.stdout.contains("crypto.os.hmac=9c196e32dc"))
            assertTrue(result.stdout.contains("crypto.os.kdf=120fb6cf/16dbc890/fe8f9615"))
            assertTrue(result.stdout.contains("crypto.os.secret=secret/6/b82fcb79/c2VjcmV0"))
            assertTrue(result.stdout.contains("crypto.os.webcrypto=true/true/b82fcb79/true/c2VjcmV0"))
            assertTrue(result.stdout.contains("crypto.os.uuid=36/"))
