            assertTrue(result.stdout.contains("crypto.os.alias=true"))
            assertTrue(result.stdout.contains("crypto.os.getBuiltinModule=true"))
            assertTrue(result.stdout.contains("crypto.os.worker.denied=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun bufferCompatibilitySweepSupportsCommonEncodingAndMutationApis() {
        assumeEmbeddedScriptExecutionEnabled()

        val result = runEmbeddedScript(
            """
            "nodejs";
            const fromUtf8 = Buffer.from("hello", "utf8");
            const fromHex = Buffer.from("68656c6c6f", "hex");
            const allocated = Buffer.alloc(4);
            const unsafe = Buffer.allocUnsafe(4);
            allocated.write("ab");
            const concat = Buffer.concat([Buffer.from("a"), Buffer.from("b")]);
            const slice = Buffer.from("abcdef").slice(1, 4);
            const subarray = Buffer.from("abcdef").subarray(2, 5);
            console.log("buffer.from.utf8.hex=" + fromUtf8.toString("hex"));
            console.log("buffer.from.hex.utf8=" + fromHex.toString("utf8"));
            console.log("buffer.alloc.write=" + allocated.toString("utf8", 0, 2));
            console.log("buffer.allocUnsafe=" + Buffer.isBuffer(unsafe) + "/" + unsafe.length);
            console.log("buffer.byteLength=" + Buffer.byteLength("你好", "utf8"));
            console.log("buffer.concat=" + concat.toString());
            console.log("buffer.isBuffer=" + Buffer.isBuffer(fromUtf8));
            console.log("buffer.compare=" + (Buffer.compare(Buffer.from("a"), Buffer.from("b")) < 0));
            console.log("buffer.equals=" + fromUtf8.equals(fromHex));
            console.log("buffer.slice=" + slice.toString());
            console.log("buffer.subarray=" + subarray.toString());
            console.log("buffer.base64=" + Buffer.from("hello").toString("base64"));
            """.trimIndent(),
            "<embedded-buffer-compat-source.js>",
        )

        assertTrue(result.errorMessage.orEmpty(), result.succeeded)
        assertTrue(result.stdout.contains("buffer.from.utf8.hex=68656c6c6f"))
        assertTrue(result.stdout.contains("buffer.from.hex.utf8=hello"))
        assertTrue(result.stdout.contains("buffer.alloc.write=ab"))
        assertTrue(result.stdout.contains("buffer.allocUnsafe=true/4"))
        assertTrue(result.stdout.contains("buffer.byteLength=6"))
        assertTrue(result.stdout.contains("buffer.concat=ab"))
        assertTrue(result.stdout.contains("buffer.isBuffer=true"))
        assertTrue(result.stdout.contains("buffer.compare=true"))
        assertTrue(result.stdout.contains("buffer.equals=true"))
        assertTrue(result.stdout.contains("buffer.slice=bcd"))
        assertTrue(result.stdout.contains("buffer.subarray=cde"))
        assertTrue(result.stdout.contains("buffer.base64=aGVsbG8="))
    }

    @Test
    fun bufferBuiltinWrapperSupportsNodeAliasesAndShadowProtection() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-buffer-builtin-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create buffer builtin test dir: $absolutePath" }
        }
        try {
            val bufferShadow = File(scriptDir, "node_modules/buffer/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true, Buffer: function ShadowBuffer() {} };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                """
                "nodejs";
                return (async () => {
                const fs = require("fs");
                const buffer = require("buffer");
                const nodeBuffer = require("node:buffer");
                const encoded = buffer.Buffer.from("builtin", "utf8").toString("base64");
                const decoded = nodeBuffer.Buffer.from(encoded, "base64").toString("utf8");
                const slowOk = typeof buffer.SlowBuffer !== "function" || Buffer.isBuffer(buffer.SlowBuffer(2));
                const blob = new buffer.Blob([buffer.Buffer.from("blob"), " ok"], { type: "text/plain" });
                const file = new buffer.File(["file ok"], "safe.txt", { type: "text/plain" });
                fs.writeFileSync("./blob-url.txt", "fs-blob", "utf8");
                const fsBlob = await fs.openAsBlob("./blob-url.txt", { type: "text/plain" });
                const blobUrl = URL.createObjectURL(blob);
                const resolvedBlob = buffer.resolveObjectURL(blobUrl);
                const blobUrlText = await resolvedBlob.text();
                URL.revokeObjectURL(blobUrl);
                const revokedBlob = buffer.resolveObjectURL(blobUrl);
                const fsBlobUrl = URL.createObjectURL(fsBlob);
                const resolvedFsBlob = buffer.resolveObjectURL(fsBlobUrl);
                const fsBlobUrlText = await resolvedFsBlob.text();
                URL.revokeObjectURL(fsBlobUrl);
                const revokedFsBlob = buffer.resolveObjectURL(fsBlobUrl);
                const transcodeUtf16 = buffer.transcode(buffer.Buffer.from("builtin", "utf8"), "utf8", "utf16le");
                const transcodeRoundtrip = buffer.transcode(transcodeUtf16, "utf16le", "utf8").toString("utf8");
                const transcodeLatin1Hex = buffer.transcode(
                  buffer.Buffer.from([0x63, 0x61, 0x66, 0xe9]),
                  "latin1",
                  "utf8"
                ).toString("hex");
                const transcodeTypedArrayHex = buffer.transcode(
                  new Uint8Array(buffer.Buffer.from("abc")),
                  "utf8",
                  "utf16le"
                ).toString("hex");
                let transcodeLimit = "";
                try {
                  buffer.transcode(buffer.Buffer.alloc(512 * 1024 + 1), "utf8", "utf8");
                } catch (error) {
                  transcodeLimit = error && error.code;
                }
                let transcodeInvalid = "";
                try {
                  buffer.transcode(buffer.Buffer.from("abc"), "bad", "utf8");
                } catch (error) {
                  transcodeInvalid = error && error.code;
                }
                const transcodeOk =
                  typeof buffer.transcode === "function" &&
                  transcodeRoundtrip === "builtin" &&
                  transcodeLatin1Hex === "636166c3a9" &&
                  transcodeTypedArrayHex === "610062006300" &&
                  transcodeLimit === "ERR_OUT_OF_RANGE" &&
                  transcodeInvalid === "U_ILLEGAL_ARGUMENT_ERROR";
                const hasOwnOk =
                  buffer.hasOwnProperty("Buffer") === true &&
                  buffer.Buffer.hasOwnProperty("from") === true;
                const objectUrlOk =
                  typeof buffer.resolveObjectURL === "function" &&
                  typeof URL.createObjectURL === "function" &&
                  typeof URL.revokeObjectURL === "function" &&
                  resolvedBlob instanceof buffer.Blob &&
                  blobUrlText === "blob ok" &&
                  revokedBlob === undefined &&
                  resolvedFsBlob instanceof buffer.Blob &&
                  resolvedFsBlob.type === "text/plain" &&
                  fsBlobUrlText === "fs-blob" &&
                  revokedFsBlob === undefined;
                const surfaceOk =
                  typeof buffer.atob === "function" &&
                  typeof buffer.btoa === "function" &&
                  typeof buffer.isUtf8 === "function" &&
                  typeof buffer.isAscii === "function" &&
                  typeof buffer.Blob === "function" &&
                  typeof buffer.File === "function" &&
                  typeof buffer.resolveObjectURL === "function" &&
                  typeof buffer.transcode === "function" &&
                  typeof buffer.INSPECT_MAX_BYTES === "number" &&
                  buffer.atob("aGVsbG8=") === "hello" &&
                  buffer.btoa("hello") === "aGVsbG8=" &&
                  buffer.isUtf8(buffer.Buffer.from("hello")) === true &&
                  buffer.isAscii(buffer.Buffer.from("hello")) === true &&
                  buffer.isAscii(buffer.Buffer.from([0xff])) === false &&
                  /*
                  buffer.isAscii(buffer.Buffer.from("浣犲ソ")) === false &&
                  */
                  blob.size === 7 &&
                  blob.type === "text/plain" &&
                  file.name === "safe.txt" &&
                  file.size === 7 &&
                  file.type === "text/plain";
                const shadowLoaded = Object.keys(require.cache).some((filename) => {
                  return filename.replace(/\\/g, "/").includes("/node_modules/buffer/");
                });

                console.log("buffer.builtin.same=" + (buffer === nodeBuffer));
                console.log("buffer.builtin.global=" + (buffer.Buffer === Buffer && nodeBuffer.Buffer === Buffer));
                console.log("buffer.builtin.roundtrip=" + decoded);
                console.log("buffer.builtin.slow=" + slowOk);
                console.log("buffer.builtin.surface=" + surfaceOk);
                console.log("buffer.builtin.has_own=" + hasOwnOk);
                console.log("buffer.builtin.object_url=" + objectUrlOk);
                console.log("buffer.builtin.transcode=" + [
                  transcodeRoundtrip,
                  transcodeLatin1Hex,
                  transcodeTypedArrayHex,
                  transcodeLimit,
                  transcodeInvalid
                ].join("|"));
                console.log("buffer.builtin.constants=" + (
                  !buffer.constants ||
                  typeof buffer.constants.MAX_LENGTH === "number" ||
                  typeof buffer.constants.MAX_STRING_LENGTH === "number"
                ));
                console.log("buffer.builtin.resolve=" + require.resolve("buffer") + "/" + require.resolve("node:buffer"));
                console.log("buffer.builtin.shadow=" + (buffer.shadow !== true && nodeBuffer.shadow !== true && !shadowLoaded));

                try {
                  process.getBuiltinModule("buffer");
                  console.log("buffer.builtin.getBuiltinModule=false");
                } catch (error) {
                  console.log("buffer.builtin.getBuiltinModule=" + (
                    error &&
                    error.code === "ERR_AUTOJS6_EMBEDDED_NODE_BUILTIN_DISABLED" &&
                    String(error.message).includes("process.getBuiltinModule")
                  ));
                }
                })();
                """.trimIndent(),
                "<embedded-buffer-builtin-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(bufferShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("buffer.builtin.same=true"))
            assertTrue(result.stdout.contains("buffer.builtin.global=true"))
            assertTrue(result.stdout.contains("buffer.builtin.roundtrip=builtin"))
            assertTrue(result.stdout.contains("buffer.builtin.slow=true"))
            assertTrue(result.stdout.contains("buffer.builtin.surface=true"))
            assertTrue(result.stdout.contains("buffer.builtin.has_own=true"))
            assertTrue(result.stdout.contains("buffer.builtin.object_url=true"))
            assertTrue(result.stdout.contains("buffer.builtin.transcode=builtin|636166c3a9|610062006300|ERR_OUT_OF_RANGE|U_ILLEGAL_ARGUMENT_ERROR"))
            assertTrue(result.stdout.contains("buffer.builtin.constants=true"))
            assertTrue(result.stdout.contains("buffer.builtin.resolve=buffer/buffer"))
            assertTrue(result.stdout.contains("buffer.builtin.shadow=true"))
            assertTrue(result.stdout.contains("buffer.builtin.getBuiltinModule=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun webDataGlobalsSupportBlobFileFormDataRequestResponseAndDisableFetch() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-web-globals-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create web globals test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                return (async () => {
                const buffer = require("buffer");
                const types = [
                  typeof Blob,
                  typeof File,
                  typeof FormData,
                  typeof Headers,
                  typeof Request,
                  typeof Response,
                  typeof fetch
                ].join(",");
                const blob = new Blob([Buffer.from("we"), "b"], { type: "text/plain" });
                const file = new File(["file"], "file.txt", { type: "text/plain", lastModified: 42 });
                const [blobText, fileText] = await Promise.all([
                  blob.text(),
                  file.text()
                ]);
                const form = new FormData();
                form.append("field", "value");
                form.append("blob", blob, "blob.txt");
                form.append("file", file);
                const formBlob = form.get("blob");
                const formFile = form.get("file");
                const [formBlobText, formFileText] = await Promise.all([
                  formBlob.text(),
                  formFile.text()
                ]);
                const headers = new Headers();
                headers.set("content-type", "text/plain");
                headers.append("x-test", "yes");
                const request = new Request("https://example.invalid/api", {
                  method: "POST",
                  headers,
                  body: "payload"
                });
                const requestText = await request.text();
                const response = new Response("ok", {
                  status: 201,
                  headers: {
                    "x-test": "yes"
                  }
                });
                const responseText = await response.text();
                let fetchCode = "";
                let fetchReturnedPromise = false;
                try {
                  const fetchResult = fetch("https://example.invalid/blocked");
                  fetchReturnedPromise = !!fetchResult && typeof fetchResult.then === "function";
                  await fetchResult;
                } catch (error) {
                  fetchCode = error && error.code;
                }
                function limitedHttpRequire(name, target) {
                  const mod = require(name);
                  try {
                    mod.request(target);
                    return false;
                  } catch (error) {
                    return mod.STATUS_CODES[200] === "OK" &&
                      typeof mod.Agent === "function" &&
                      error && error.code === "ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED";
                  }
                }
                const locked = [
                  "Blob",
                  "File",
                  "FormData",
                  "Headers",
                  "Request",
                  "Response",
                  "fetch"
                ].every((name) => {
                  const descriptor = Object.getOwnPropertyDescriptor(globalThis, name);
                  return descriptor && descriptor.writable === false;
                });

                console.log("web.globals.types=" + types);
                console.log("web.globals.blob=" + [
                  blobText,
                  file.name + "/" + file.lastModified + "/" + file.type + "/" + fileText,
                  blob instanceof buffer.Blob,
                  file instanceof buffer.File
                ].join("|"));
                console.log("web.globals.formdata=" + [
                  form.get("field"),
                  formBlob instanceof Blob,
                  formBlob instanceof File,
                  formBlob.name,
                  formBlobText,
                  formFile instanceof File,
                  formFile.name,
                  formFileText
                ].join("|"));
                console.log("web.globals.request=" + [
                  request.method,
                  request.headers.get("content-type"),
                  requestText
                ].join("|"));
                console.log("web.globals.response=" + [
                  response.status,
                  response.headers.get("x-test"),
                  responseText
                ].join("|"));
                console.log("web.globals.fetch=" + [
                  fetchCode,
                  fetchReturnedPromise,
                  limitedHttpRequire("http", "http://example.invalid"),
                  limitedHttpRequire("https", "https://example.invalid")
                ].join("|"));
                console.log("web.globals.locked=" + locked);
                })();
                """.trimIndent(),
                "<embedded-web-globals-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("web.globals.types=function,function,function,function,function,function,function"))
            assertTrue(result.stdout.contains("web.globals.blob=web|file.txt/42/text/plain/file|true|true"))
            assertTrue(result.stdout.contains("web.globals.formdata=value|true|true|blob.txt|web|true|file.txt|file"))
            assertTrue(result.stdout.contains("web.globals.request=POST|text/plain|payload"))
            assertTrue(result.stdout.contains("web.globals.response=201|yes|ok"))
            assertTrue(result.stdout.contains("web.globals.fetch=ERR_AUTOJS6_EMBEDDED_NODE_FETCH_DISABLED|true|true|true"))
            assertTrue(result.stdout.contains("web.globals.locked=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun webPlatformGlobalsSupportAbortEventsAndWebStreams() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-web-platform-globals-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create web platform globals test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                return (async () => {
                const streamWeb = require("stream/web");
                const streamConsumers = require("stream/consumers");
                const names = [
                  "AbortController",
                  "AbortSignal",
                  "DOMException",
                  "EventTarget",
                  "Event",
                  "CustomEvent",
                  "MessageEvent",
                  "performance",
                  "PerformanceObserver",
                  "PerformanceEntry",
                  "PerformanceMark",
                  "PerformanceMeasure",
                  "ReadableStream",
                  "WritableStream",
                  "TransformStream",
                  "TextEncoderStream",
                  "TextDecoderStream",
                  "ByteLengthQueuingStrategy",
                  "CountQueuingStrategy"
                ];
                const types = names.map((name) => typeof globalThis[name]).join(",");
                const locked = names.every((name) => {
                  const descriptor = Object.getOwnPropertyDescriptor(globalThis, name);
                  return descriptor && descriptor.writable === false;
                });

                const abortController = new AbortController();
                let abortEventSummary = "";
                abortController.signal.addEventListener("abort", (event) => {
                  abortEventSummary = [
                    event.type,
                    event instanceof Event,
                    abortController.signal.reason instanceof DOMException,
                    abortController.signal.reason && abortController.signal.reason.name
                  ].join("|");
                }, { once: true });
                abortController.abort(new DOMException("stop", "AbortError"));
                const abortedSignal = AbortSignal.abort("already");
                const abortAny = AbortSignal.any([abortedSignal]);
                const abortAnyController = new AbortController();
                const abortAnyLater = AbortSignal.any([abortAnyController.signal]);
                abortAnyController.abort("later");
                const abortTimeoutSummary = await new Promise((resolve) => {
                  const timeoutSignal = AbortSignal.timeout(5);
                  const guard = setTimeout(() => resolve("missed"), 100);
                  timeoutSignal.addEventListener("abort", () => {
                    clearTimeout(guard);
                    resolve([
                      timeoutSignal.aborted,
                      timeoutSignal.reason && timeoutSignal.reason.name
                    ].join("|"));
                  }, { once: true });
                });
                const abortStaticMethodsOk = ["abort", "any", "timeout"].every((name) => {
                  const descriptor = Object.getOwnPropertyDescriptor(AbortSignal, name);
                  return typeof AbortSignal[name] === "function" &&
                    descriptor &&
                    descriptor.value === AbortSignal[name];
                });
                const abortSummary = [
                  abortController.signal instanceof AbortSignal,
                  abortController.signal.aborted,
                  abortEventSummary,
                  abortedSignal.aborted,
                  abortAny.reason,
                  abortAnyLater.aborted,
                  abortAnyLater.reason,
                  abortTimeoutSummary,
                  abortStaticMethodsOk
                ].join("|");

                const target = new EventTarget();
                let eventSummary = "";
                target.addEventListener("custom", (event) => {
                  eventSummary = [
                    event.type,
                    event instanceof Event,
                    event.target === target
                  ].join("|");
                });
                target.dispatchEvent(new Event("custom"));
                const detailTarget = new EventTarget();
                let customEventSummary = "";
                const customEvent = new CustomEvent("custom-detail", {
                  detail: { value: "detail-global" },
                  bubbles: true,
                  cancelable: true
                });
                detailTarget.addEventListener("custom-detail", (event) => {
                  customEventSummary = [
                    event instanceof CustomEvent,
                    event instanceof Event,
                    event.detail.value,
                    event.bubbles,
                    event.cancelable,
                    event.target === detailTarget
                  ].join("|");
                });
                detailTarget.dispatchEvent(customEvent);
                const constructedMessageEvent = new MessageEvent("message", {
                  data: { text: "message-global" },
                  origin: "autojs6://embedded",
                  lastEventId: "global-id",
                  ports: []
                });
                const messageEventSummary = [
                  constructedMessageEvent instanceof MessageEvent,
                  constructedMessageEvent instanceof Event,
                  constructedMessageEvent.data.text,
                  constructedMessageEvent.origin,
                  constructedMessageEvent.lastEventId,
                  Array.isArray(constructedMessageEvent.ports),
                  constructedMessageEvent.ports.length
                ].join("|");
                const performanceNowA = performance.now();
                performance.mark("web-platform-global-start");
                performance.mark("web-platform-global-end");
                performance.measure("web-platform-global-measure", "web-platform-global-start", "web-platform-global-end");
                const performanceMarkEntries = performance.getEntriesByType("mark").filter((entry) => entry.name.indexOf("web-platform-global-") === 0);
                const performanceMeasureEntries = performance.getEntriesByName("web-platform-global-measure", "measure");
                const performanceObserved = await new Promise((resolve) => {
                  const observer = new PerformanceObserver((list) => {
                    const summary = list.getEntries().map((entry) => entry.name + ":" + entry.entryType).join("/");
                    observer.disconnect();
                    resolve(summary);
                  });
                  observer.observe({ entryTypes: ["mark", "measure"] });
                  performance.mark("web-platform-observed-start");
                  performance.mark("web-platform-observed-end");
                  performance.measure("web-platform-observed-measure", "web-platform-observed-start", "web-platform-observed-end");
                });
                const performanceNowB = performance.now();
                const performanceHiddenTypes = [
                  typeof performance.timerify,
                  typeof performance.eventLoopUtilization,
                  typeof performance.nodeTiming,
                  typeof performance.markResourceTiming
                ].join(",");
                const performanceSummary = [
                  Object.isFrozen(performance),
                  Object.isFrozen(PerformanceObserver.supportedEntryTypes),
                  PerformanceObserver.supportedEntryTypes.join(","),
                  typeof performanceNowA === "number" && performanceNowB >= performanceNowA,
                  performanceMarkEntries.length >= 2,
                  performanceMeasureEntries.length === 1,
                  performanceMeasureEntries[0] instanceof PerformanceMeasure,
                  performanceMarkEntries[0] instanceof PerformanceMark,
                  performanceMeasureEntries[0] instanceof PerformanceEntry,
                  performanceObserved.includes("web-platform-observed-start:mark"),
                  performanceObserved.includes("web-platform-observed-measure:measure"),
                  performanceHiddenTypes
                ].join("|");
                performance.clearMarks("web-platform-global-start");
                performance.clearMarks("web-platform-global-end");
                performance.clearMarks("web-platform-observed-start");
                performance.clearMarks("web-platform-observed-end");
                performance.clearMeasures("web-platform-global-measure");
                performance.clearMeasures("web-platform-observed-measure");

                async function readAll(readable) {
                  const reader = readable.getReader();
                  const values = [];
                  while (true) {
                    const next = await reader.read();
                    if (next.done) {
                      return values;
                    }
                    values.push(next.value);
                  }
                }

                const readableText = (await readAll(new ReadableStream({
                  start(controller) {
                    controller.enqueue("global");
                    controller.enqueue("-read");
                    controller.close();
                  }
                }))).join("");

                let writableText = "";
                const writable = new WritableStream({
                  write(chunk) {
                    writableText += String(chunk);
                  }
                });
                const writableWriter = writable.getWriter();
                await writableWriter.write("write");
                await writableWriter.write("-global");
                await writableWriter.close();

                const transform = new TransformStream({
                  transform(chunk, controller) {
                    controller.enqueue(String(chunk).toUpperCase());
                  }
                });
                const transformedValues = readAll(transform.readable);
                const transformWriter = transform.writable.getWriter();
                await transformWriter.write("transform");
                await transformWriter.write("-global");
                await transformWriter.close();
                const transformedText = (await transformedValues).join("");

                const blobStreamText = Buffer.concat((await readAll(
                  new Blob(["blob-stream"]).stream().pipeThrough(new TransformStream({
                    transform(chunk, controller) {
                      controller.enqueue(chunk);
                    }
                  }))
                )).map((chunk) => Buffer.from(chunk))).toString("utf8");

                const encodedChunks = [];
                const encoder = new TextEncoderStream();
                const encoderDone = encoder.readable.pipeTo(new WritableStream({
                  write(chunk) {
                    encodedChunks.push(Buffer.from(chunk));
                  }
                }));
                const encoderWriter = encoder.writable.getWriter();
                await encoderWriter.write("encoded-global");
                await encoderWriter.close();
                await encoderDone;

                const decodedChunks = [];
                const decoder = new TextDecoderStream();
                const decoderDone = decoder.readable.pipeTo(new WritableStream({
                  write(chunk) {
                    decodedChunks.push(chunk);
                  }
                }));
                const decoderWriter = decoder.writable.getWriter();
                await decoderWriter.write(Buffer.from("decoded-global"));
                await decoderWriter.close();
                await decoderDone;

                const countStrategy = new CountQueuingStrategy({ highWaterMark: 2 });
                const byteStrategy = new ByteLengthQueuingStrategy({ highWaterMark: 8 });
                const aliasOk =
                  ReadableStream === streamWeb.ReadableStream &&
                  WritableStream === streamWeb.WritableStream &&
                  TransformStream === streamWeb.TransformStream &&
                  TextEncoderStream === streamWeb.TextEncoderStream &&
                  TextDecoderStream === streamWeb.TextDecoderStream &&
                  CountQueuingStrategy === streamWeb.CountQueuingStrategy &&
                  ByteLengthQueuingStrategy === streamWeb.ByteLengthQueuingStrategy;

                console.log("web.platform.types=" + types);
                console.log("web.platform.abort=" + abortSummary);
                console.log("web.platform.event=" + [
                  eventSummary,
                  customEventSummary,
                  messageEventSummary,
                  performanceSummary
                ].join("|"));
                console.log("web.platform.streams=" + [
                  readableText,
                  writableText,
                  transformedText,
                  blobStreamText,
                  await streamConsumers.text(new Blob(["consumer-stream"]).stream())
                ].join("|"));
                console.log("web.platform.codec=" + [
                  Buffer.concat(encodedChunks).toString("utf8"),
                  decodedChunks.join("")
                ].join("|"));
                console.log("web.platform.strategy=" + [
                  countStrategy.highWaterMark,
                  countStrategy.size("value"),
                  byteStrategy.highWaterMark,
                  byteStrategy.size(new Uint8Array([1, 2, 3]))
                ].join("|"));
                console.log("web.platform.alias=" + aliasOk);
                console.log("web.platform.locked=" + locked);
                })();
                """.trimIndent(),
                "<embedded-web-platform-globals-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("web.platform.types=function,function,function,function,function,function,function,object,function,function,function,function,function,function,function,function,function,function,function"))
            assertTrue(result.stdout.contains("web.platform.abort=true|true|abort|true|true|AbortError|true|already|true|later|true|TimeoutError|true"))
            assertTrue(result.stdout.contains("web.platform.event=custom|true|true|true|true|detail-global|true|true|true|true|true|message-global|autojs6://embedded|global-id|true|0|true|true|mark,measure|true|true|true|true|true|true|true|true|undefined,undefined,undefined,undefined"))
            assertTrue(result.stdout.contains("web.platform.streams=global-read|write-global|TRANSFORM-GLOBAL|blob-stream|consumer-stream"))
            assertTrue(result.stdout.contains("web.platform.codec=encoded-global|decoded-global"))
            assertTrue(result.stdout.contains("web.platform.strategy=2|1|8|3"))
            assertTrue(result.stdout.contains("web.platform.alias=true"))
            assertTrue(result.stdout.contains("web.platform.locked=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun webCompressionGlobalsSupportLimitedGzipDeflateStreams() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-web-compression-globals-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create web compression global test dir: $absolutePath" }
        }
        try {
            val outputBombBase64 = gzipBase64(ByteArray(2 * 1024 * 1024 + 1) { 'A'.code.toByte() })
            val result = runEmbeddedScript(
                """
                "nodejs";
                return (async () => {
                const streamWeb = require("stream/web");

                async function collectBytes(transform, chunks) {
                  const reader = transform.readable.getReader();
                  const writer = transform.writable.getWriter();
                  const reads = (async () => {
                    const values = [];
                    while (true) {
                      const next = await reader.read();
                      if (next.done) {
                        return Buffer.concat(values.map((value) => Buffer.from(value)));
                      }
                      values.push(next.value);
                    }
                  })();
                  try {
                    for (const chunk of chunks) {
                      await writer.write(chunk);
                    }
                    await writer.close();
                  } catch (error) {
                    await reads.catch(() => {});
                    throw error;
                  }
                  return await reads;
                }

                async function captureAsync(action) {
                  try {
                    await action();
                    return "ok";
                  } catch (error) {
                    return [
                      error && error.name,
                      error && error.code,
                      error instanceof Error
                    ].join("/");
                  }
                }

                function captureSync(action) {
                  try {
                    action();
                    return "ok";
                  } catch (error) {
                    return [
                      error && error.name,
                      error && error.code,
                      error instanceof Error
                    ].join("/");
                  }
                }

                const gzipBytes = await collectBytes(
                  new CompressionStream("gzip"),
                  [new TextEncoder().encode("gzip-"), Buffer.from("global")]
                );
                const gzipText = (await collectBytes(
                  new DecompressionStream("gzip"),
                  [gzipBytes]
                )).toString("utf8");
                const deflateView = new DataView(new Uint8Array([103, 108, 111, 98, 97, 108]).buffer);
                const deflateBytes = await collectBytes(
                  new CompressionStream("deflate"),
                  ["deflate-", deflateView]
                );
                const deflateText = (await collectBytes(
                  new DecompressionStream("deflate"),
                  [deflateBytes]
                )).toString("utf8");
                const rawBytes = await collectBytes(
                  new CompressionStream("deflate-raw"),
                  [Buffer.from("raw-global")]
                );
                const rawText = (await collectBytes(
                  new DecompressionStream("deflate-raw"),
                  [rawBytes]
                )).toString("utf8");
                const brotliBytes = await collectBytes(
                  new CompressionStream("brotli"),
                  [Buffer.from("brotli-global")]
                );
                const brotliText = (await collectBytes(
                  new DecompressionStream("brotli"),
                  [brotliBytes]
                )).toString("utf8");
                const gzipStream = new CompressionStream("gzip");
                const brotliStream = new DecompressionStream("brotli");
                const descriptorCompression = Object.getOwnPropertyDescriptor(globalThis, "CompressionStream");
                const descriptorDecompression = Object.getOwnPropertyDescriptor(globalThis, "DecompressionStream");
                const hidden = [
                  typeof streamWeb.CompressionStream,
                  typeof streamWeb.DecompressionStream
                ].join(",");
                const invalidCompression = captureSync(() => new CompressionStream("br"));
                const invalidDecompression = captureSync(() => new DecompressionStream("br"));
                const invalidChunk = await captureAsync(() =>
                  collectBytes(new CompressionStream("gzip"), [new ArrayBuffer(1)])
                );
                const tooLargeInput = await captureAsync(() =>
                  collectBytes(new CompressionStream("gzip"), [Buffer.alloc(512 * 1024 + 1)])
                );
                const outputBomb = await captureAsync(() =>
                  collectBytes(new DecompressionStream("gzip"), [Buffer.from("$outputBombBase64", "base64")])
                );

                console.log("web.compression.types=" + [
                  typeof CompressionStream,
                  typeof DecompressionStream,
                  gzipStream instanceof CompressionStream,
                  brotliStream instanceof DecompressionStream,
                  gzipStream.readable instanceof ReadableStream,
                  gzipStream.writable instanceof WritableStream
                ].join(","));
                console.log("web.compression.roundtrip=" + [
                  gzipText,
                  deflateText,
                  rawText,
                  brotliText,
                  gzipBytes[0] === 0x1f && gzipBytes[1] === 0x8b,
                  deflateBytes.length > 0
                ].join("|"));
                console.log("web.compression.errors=" + [
                  invalidCompression,
                  invalidDecompression,
                  invalidChunk,
                  tooLargeInput,
                  outputBomb
                ].join("|"));
                console.log("web.compression.guards=" + [
                  descriptorCompression && descriptorCompression.writable === false,
                  descriptorDecompression && descriptorDecompression.writable === false,
                  hidden
                ].join("|"));
                })();
                """.trimIndent(),
                "<embedded-web-compression-globals-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("web.compression.types=function,function,true,true,true,true"))
            assertTrue(result.stdout.contains("web.compression.roundtrip=gzip-global|deflate-global|raw-global|brotli-global|true|true"))
            assertTrue(result.stdout.contains("web.compression.errors=TypeError/ERR_INVALID_ARG_VALUE/true|TypeError/ERR_INVALID_ARG_VALUE/true|TypeError/ERR_INVALID_ARG_TYPE/true|RangeError/ERR_OUT_OF_RANGE/true|RangeError/ERR_OUT_OF_RANGE/true"))
            assertTrue(result.stdout.contains("web.compression.guards=true|true|undefined,undefined"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun webCryptoGlobalSupportsRandomUuidAndLimitedDigestOnly() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-web-crypto-global-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create web crypto global test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                return (async () => {
                const nodeCrypto = require("crypto");
                const webCrypto = globalThis.crypto;
                const encoder = new TextEncoder();
                const data = encoder.encode("abc");
                function hex(arrayBuffer) {
                  return Buffer.from(arrayBuffer).toString("hex");
                }
                async function captureDigest(action) {
                  try {
                    const value = action();
                    const returnedPromise = !!value && typeof value.then === "function";
                    await value;
                    return "ok:" + returnedPromise;
                  } catch (error) {
                    return [
                      error && error.name,
                      error && error.code,
                      error instanceof Error
                    ].join("/");
                  }
                }
                function captureSync(action) {
                  try {
                    action();
                    return "ok";
                  } catch (error) {
                    return [
                      error && error.name,
                      error && error.code,
                      error instanceof Error
                    ].join("/");
                  }
                }

                const randomBytes = new Uint8Array(16);
                const randomWords = new Uint32Array(4);
                const returnedBytes = webCrypto.getRandomValues(randomBytes);
                const returnedWords = webCrypto.getRandomValues(randomWords);
                const randomOk =
                  returnedBytes === randomBytes &&
                  returnedWords === randomWords &&
                  randomBytes.byteLength === 16 &&
                  randomWords.byteLength === 16;
                const uuid = webCrypto.randomUUID();
                const uuidOk = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(uuid);
                const viewBuffer = new Uint8Array([97, 98, 99, 120]).buffer;
                const view = new DataView(viewBuffer, 0, 3);
                const [sha1, sha256, sha512, sha256Object, sha1View] = await Promise.all([
                  webCrypto.subtle.digest("SHA-1", data),
                  webCrypto.subtle.digest("SHA-256", data),
                  webCrypto.subtle.digest("SHA-512", data),
                  webCrypto.subtle.digest({ name: "sha-256" }, Buffer.from("abc")),
                  webCrypto.subtle.digest("SHA-1", view)
                ]);
                const hmacKey = await webCrypto.subtle.importKey(
                  "raw",
                  encoder.encode("secret"),
                  { name: "HMAC", hash: "SHA-256" },
                  true,
                  ["sign", "verify"]
                );
                const hmacJwkKey = await webCrypto.subtle.importKey(
                  "jwk",
                  { kty: "oct", k: "c2VjcmV0", key_ops: ["verify"], ext: true },
                  { name: "HMAC", hash: { name: "SHA-256" } },
                  true,
                  ["verify"]
                );
                const hmacSha512Key = await webCrypto.subtle.importKey(
                  "raw",
                  Buffer.from("secret"),
                  { name: "HMAC", hash: "SHA-512" },
                  true,
                  ["sign"]
                );
                const signOnlyKey = await webCrypto.subtle.importKey(
                  "raw",
                  Buffer.from("secret"),
                  { name: "HMAC", hash: "SHA-256" },
                  false,
                  ["sign"]
                );
                const payload = encoder.encode("payload");
                const hmacSignature = await webCrypto.subtle.sign("HMAC", hmacKey, payload);
                const hmacSha512Signature = await webCrypto.subtle.sign({ name: "HMAC" }, hmacSha512Key, payload);
                const hmacVerify = await webCrypto.subtle.verify("HMAC", hmacJwkKey, hmacSignature, payload);
                const hmacVerifyFalse = await webCrypto.subtle.verify("HMAC", hmacKey, hmacSignature, encoder.encode("other"));
                const hmacExportRaw = await webCrypto.subtle.exportKey("raw", hmacKey);
                const hmacExportJwk = await webCrypto.subtle.exportKey("jwk", hmacKey);
                const descriptor = Object.getOwnPropertyDescriptor(globalThis, "crypto");
                const hidden = [
                  typeof webCrypto.createHash,
                  typeof webCrypto.createHmac,
                  typeof webCrypto.randomBytes,
                  typeof webCrypto.webcrypto,
                  typeof webCrypto.subtle.encrypt,
                  typeof webCrypto.subtle.deriveBits,
                  typeof webCrypto.subtle.generateKey
                ].join(",");
                const nodeHidden = [
                  typeof nodeCrypto.webcrypto,
                  typeof nodeCrypto.subtle
                ].join(",");
                const nodeAlias = [
                  nodeCrypto.webcrypto === webCrypto,
                  nodeCrypto.subtle === webCrypto.subtle,
                  typeof nodeCrypto.webcrypto.subtle.importKey,
                  typeof nodeCrypto.subtle.sign
                ].join("|");
                const badDigest = await captureDigest(() => webCrypto.subtle.digest("MD5", data));
                const badData = await captureDigest(() => webCrypto.subtle.digest("SHA-256", "abc"));
                const badHmacAlgorithm = await captureDigest(() =>
                  webCrypto.subtle.importKey("raw", Buffer.from("secret"), { name: "AES-GCM" }, true, ["sign"])
                );
                const badHmacHash = await captureDigest(() =>
                  webCrypto.subtle.importKey("raw", Buffer.from("secret"), { name: "HMAC", hash: "SHA-1" }, true, ["sign"])
                );
                const badHmacUsage = await captureDigest(() =>
                  webCrypto.subtle.importKey("raw", Buffer.from("secret"), { name: "HMAC", hash: "SHA-256" }, true, ["encrypt"])
                );
                const badHmacData = await captureDigest(() => webCrypto.subtle.sign("HMAC", hmacKey, "payload"));
                const badHmacExport = await captureDigest(() => webCrypto.subtle.exportKey("raw", signOnlyKey));
                const tooLarge = captureSync(() => webCrypto.getRandomValues(new Uint8Array(65537)));
                const badRandomType = captureSync(() => webCrypto.getRandomValues(new Float32Array(1)));

                console.log("web.crypto.types=" + [
                  typeof webCrypto,
                  typeof webCrypto.getRandomValues,
                  typeof webCrypto.randomUUID,
                  typeof webCrypto.subtle,
                  typeof webCrypto.subtle.digest,
                  typeof webCrypto.subtle.importKey,
                  typeof webCrypto.subtle.sign,
                  typeof webCrypto.subtle.verify,
                  typeof webCrypto.subtle.exportKey,
                  typeof CryptoKey
                ].join(","));
                console.log("web.crypto.random=" + [
                  randomOk,
                  uuidOk,
                  uuid.length
                ].join("|"));
                console.log("web.crypto.digest=" + [
                  hex(sha1),
                  hex(sha256),
                  hex(sha512).slice(0, 16)
                ].join("|"));
                console.log("web.crypto.digest_inputs=" + [
                  hex(sha256Object),
                  hex(sha1View)
                ].join("|"));
                console.log("web.crypto.hmac=" + [
                  hmacKey instanceof CryptoKey,
                  Object.prototype.toString.call(hmacKey),
                  hmacKey.type,
                  hmacKey.extractable,
                  hmacKey.algorithm.name,
                  hmacKey.algorithm.hash.name,
                  hmacKey.algorithm.length,
                  hmacKey.usages.join(","),
                  hex(hmacSignature),
                  hmacVerify,
                  hmacVerifyFalse,
                  hex(hmacSha512Signature).slice(0, 16),
                  Buffer.from(hmacExportRaw).toString("utf8"),
                  hmacExportJwk.kty,
                  hmacExportJwk.k,
                  hmacExportJwk.alg,
                  hmacExportJwk.key_ops.join(",")
                ].join("|"));
                console.log("web.crypto.errors=" + [
                  badDigest,
                  badData,
                  badHmacAlgorithm,
                  badHmacHash,
                  badHmacUsage,
                  badHmacData,
                  badHmacExport,
                  tooLarge,
                  badRandomType
                ].join("|"));
                console.log("web.crypto.guards=" + [
                  Object.isFrozen(webCrypto),
                  Object.isFrozen(webCrypto.subtle),
                  descriptor && descriptor.writable === false,
                  Object.keys(webCrypto).sort().join(","),
                  hidden,
                  nodeHidden
                ].join("|"));
                console.log("web.crypto.node_alias=" + nodeAlias);
                })();
                """.trimIndent(),
                "<embedded-web-crypto-global-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("web.crypto.types=object,function,function,object,function,function,function,function,function,function"))
            assertTrue(result.stdout.contains("web.crypto.random=true|true|36"))
            assertTrue(result.stdout.contains("web.crypto.digest=a9993e364706816aba3e25717850c26c9cd0d89d|ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad|ddaf35a193617aba"))
            assertTrue(result.stdout.contains("web.crypto.digest_inputs=ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad|a9993e364706816aba3e25717850c26c9cd0d89d"))
            assertTrue(result.stdout.contains("web.crypto.hmac=true|[object CryptoKey]|secret|true|HMAC|SHA-256|48|sign,verify|b82fcb791acec57859b989b430a826488ce2e479fdf92326bd0a2e8375a42ba4|true|false|291ddaaa23cafa3a|secret|oct|c2VjcmV0|HS256|sign,verify"))
            assertTrue(result.stdout.contains("web.crypto.errors=NotSupportedError/9/true|TypeError/ERR_INVALID_ARG_TYPE/true|NotSupportedError/9/true|NotSupportedError/9/true|SyntaxError/12/true|TypeError/ERR_INVALID_ARG_TYPE/true|InvalidAccessError/15/true|QuotaExceededError/22/true|TypeMismatchError/17/true"))
            assertTrue(result.stdout.contains("web.crypto.guards=true|true|true|getRandomValues,randomUUID,subtle|undefined,undefined,undefined,undefined,undefined,undefined,undefined|object,object"))
            assertTrue(result.stdout.contains("web.crypto.node_alias=true|true|function|function"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun pathAndUrlCompatibilitySweepKeepsScopedFsAbsolutePathBoundary() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-path-url-compat-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create path url compatibility test dir: $absolutePath" }
        }
        try {
            val pathShadow = File(scriptDir, "node_modules/path/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val urlShadow = File(scriptDir, "node_modules/url/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const path = require("path");
                const nodePath = require("node:path");
                const url = require("url");
                const nodeUrl = require("node:url");
                fs.writeFileSync("./path-file.txt", "x", "utf8");
                const absolute = path.resolve("path-file.txt");
                const parsed = path.parse("/tmp/demo/file.txt");
                const formatted = path.format({ dir: "/tmp/demo", base: "file.txt" });
                const pathHidden = [
                  typeof path._makeLong,
                  typeof path.matchesGlob
                ].join(",");
                const pathHelperTypes = [
                  typeof path.resolve,
                  typeof path.normalize,
                  typeof path.isAbsolute,
                  typeof path.join,
                  typeof path.relative,
                  typeof path.dirname,
                  typeof path.basename,
                  typeof path.extname,
                  typeof path.format,
                  typeof path.parse,
                  typeof path.matchesGlob,
                  typeof path.toNamespacedPath,
                  typeof path.sep,
                  typeof path.delimiter,
                  typeof path.posix,
                  typeof path.win32
                ].join(",");
                const pathNamespaces =
                  path.posix.join("a", "b") === "a/b" &&
                  path.win32.basename("C:\\tmp\\file.txt") === "file.txt" &&
                  path.win32.join("C:\\tmp", "file.txt").replace(/\\/g, "/").endsWith("/file.txt");
                const target = new URL("https://example.com/a/b?x=1");
                target.searchParams.set("y", "2");
                const params = new URLSearchParams("a=1");
                params.append("b", "2");
                const wrapperUrl = new url.URL("https://example.com/w?q=1");
                const legacyParsed = url.parse("https://example.com/legacy?x=1", true);
                const legacyFormatted = url.format({ protocol: "https", host: "example.com", pathname: "/fmt", query: { a: "1" } });
                const legacyResolved = url.resolve("https://example.com/a/b", "../c");
                const parsedStatic = url.URL.parse("https://example.com/parsed?x=1");
                const routePattern = new URLPattern({ protocol: "https", hostname: "example.com", pathname: "/users/:id" });
                const routeMatch = routePattern.exec("https://example.com/users/42?debug=1#top");
                const relativePattern = new url.URLPattern("/relative/:slug", "https://example.com");
                const relativeMatch = relativePattern.exec("https://example.com/relative/core");
                const cloned = structuredClone({
                  nested: { value: "clone" },
                  values: new Map([["answer", 42]])
                });
                const webUtilityDescriptors = [
                  "URLPattern",
                  "structuredClone",
                  "atob",
                  "btoa",
                  "navigator",
                  "CustomEvent",
                  "MessageEvent",
                  "performance",
                  "PerformanceObserver",
                  "PerformanceEntry",
                  "PerformanceMark",
                  "PerformanceMeasure",
                  "MessageChannel",
                  "MessagePort",
                  "BroadcastChannel"
                ].every((name) => {
                  const descriptor = Object.getOwnPropertyDescriptor(globalThis, name);
                  return descriptor && descriptor.writable === false;
                });
                const encodedLatin1 = btoa("AutoJs6");
                console.log("path.join=" + path.join("a", "b", "..", "c"));
                console.log("path.resolve.absolute=" + path.isAbsolute(absolute));
                console.log("path.relative=" + path.relative(path.dirname(absolute), absolute));
                console.log("path.dirname=" + path.basename(path.dirname(absolute)).length);
                console.log("path.basename=" + path.basename(absolute));
                console.log("path.extname=" + path.extname(absolute));
                console.log("path.normalize=" + path.normalize("a/./b/../c"));
                console.log("path.parse=" + parsed.name + "/" + parsed.ext);
                console.log("path.format=" + formatted);
                console.log("path.sep.delimiter=" + (typeof path.sep) + "/" + (typeof path.delimiter));
                console.log("path.same=" + (path === nodePath));
                console.log("path.shadow=" + (path.shadow === true));
                console.log("path.frozen=" + (Object.isFrozen(path) && Object.isFrozen(path.posix) && Object.isFrozen(path.win32)));
                console.log("path.namespaces=" + pathNamespaces);
                console.log("path.helpers=" + pathHelperTypes);
                console.log("path.matchesGlob=" + (
                  path.matchesGlob("src/app.js", "src/*.js") &&
                  path.posix.matchesGlob("src/app.js", "src/*.js") &&
                  typeof path.win32.matchesGlob === "function" &&
                  !path.matchesGlob("src/app.css", "src/*.js")
                ));
                console.log("path.hidden=" + pathHidden);
                console.log("path.toNamespacedPath=" + path.toNamespacedPath("a/b"));
                console.log("path.absolute.fs.read=" + fs.readFileSync(absolute, "utf8"));
                try {
                  fs.readFileSync("/tmp/autojs6-outside.txt", "utf8");
                  console.log("path.absolute.fs.outside.denied=false");
                } catch (error) {
                  console.log("path.absolute.fs.outside.denied=" + String(error.message).includes("rejects absolute path"));
                }
                console.log("url.global=" + target.protocol + "/" + target.pathname + "/" + target.searchParams.get("y"));
                console.log("url.params=" + params.toString());
                console.log("url.wrapper.same=" + (url === nodeUrl));
                console.log("url.wrapper.shadow=" + (url.shadow === true));
                console.log("url.wrapper.URL=" + (wrapperUrl.searchParams.get("q") === "1"));
                console.log("url.wrapper.params=" + (new url.URLSearchParams("x=1").get("x")));
                console.log("url.domain=" + (typeof url.domainToASCII === "function"));
                console.log("url.static=" + (
                  typeof url.URL.canParse === "function" &&
                  typeof url.URL.parse === "function" &&
                  url.URL.canParse("/relative", "https://example.com") &&
                  parsedStatic &&
                  parsedStatic.pathname === "/parsed" &&
                  url.URL.parse("http://[") === null
                ));
                console.log("url.legacy=" + (
                  typeof url.parse === "function" &&
                  typeof url.format === "function" &&
                  typeof url.resolve === "function" &&
                  legacyParsed.query.x === "1" &&
                  legacyFormatted === "https://example.com/fmt?a=1" &&
                  legacyResolved === "https://example.com/c"
                ));
                console.log("url.pattern=" + (
                  typeof URLPattern === "function" &&
                  typeof url.URLPattern === "function" &&
                  url.URLPattern === URLPattern &&
                  routePattern.test("https://example.com/users/42") &&
                  routeMatch &&
                  routeMatch.pathname.groups.id === "42" &&
                  relativePattern.test("https://example.com/relative/core") &&
                  relativeMatch &&
                  relativeMatch.pathname.groups.slug === "core" &&
                  !routePattern.test("https://example.com/projects/42")
                ));
                console.log("web.utility=" + (
                  typeof structuredClone === "function" &&
                  cloned !== null &&
                  cloned.nested !== null &&
                  cloned.nested !== undefined &&
                  cloned.nested.value === "clone" &&
                  cloned.nested !== cloned &&
                  cloned.values instanceof Map &&
                  cloned.values.get("answer") === 42 &&
                  typeof atob === "function" &&
                  typeof btoa === "function" &&
                  encodedLatin1 === "QXV0b0pzNg==" &&
                  atob(encodedLatin1) === "AutoJs6" &&
                  typeof navigator === "object" &&
                  typeof navigator.userAgent === "string" &&
                  navigator.userAgent.length > 0 &&
                  typeof CustomEvent === "function" &&
                  typeof MessageEvent === "function" &&
                  typeof performance === "object" &&
                  typeof PerformanceObserver === "function" &&
                  typeof PerformanceEntry === "function" &&
                  typeof PerformanceMark === "function" &&
                  typeof PerformanceMeasure === "function" &&
                  typeof MessageChannel === "function" &&
                  typeof MessagePort === "function" &&
                  typeof BroadcastChannel === "function" &&
                  webUtilityDescriptors
                ));
                console.log("url.path.apis=" + [typeof url.fileURLToPath, typeof url.pathToFileURL].join(","));
                """.trimIndent(),
                "<embedded-path-url-compat-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(pathShadow, urlShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("path.join=a/c"))
            assertTrue(result.stdout.contains("path.resolve.absolute=true"))
            assertTrue(result.stdout.contains("path.relative=path-file.txt"))
            assertTrue(result.stdout.contains("path.basename=path-file.txt"))
            assertTrue(result.stdout.contains("path.extname=.txt"))
            assertTrue(result.stdout.contains("path.normalize=a/c"))
            assertTrue(result.stdout.contains("path.parse=file/.txt"))
            assertTrue(result.stdout.contains("path.format=/tmp/demo/file.txt"))
            assertTrue(result.stdout.contains("path.sep.delimiter=string/string"))
            assertTrue(result.stdout.contains("path.same=true"))
            assertTrue(result.stdout.contains("path.shadow=false"))
            assertTrue(result.stdout.contains("path.frozen=true"))
            assertTrue(result.stdout.contains("path.namespaces=true"))
            assertTrue(result.stdout.contains("path.helpers=function,function,function,function,function,function,function,function,function,function,function,function,string,string,object,object"))
            assertTrue(result.stdout.contains("path.matchesGlob=true"))
            assertTrue(result.stdout.contains("path.hidden=undefined,function"))
            assertTrue(result.stdout.contains("path.toNamespacedPath=a/b"))
            assertTrue(result.stdout.contains("path.absolute.fs.read=x"))
            assertTrue(result.stdout.contains("path.absolute.fs.outside.denied=true"))
            assertTrue(result.stdout.contains("url.global=https:/"))
            assertTrue(result.stdout.contains("url.params=a=1&b=2"))
            assertTrue(result.stdout.contains("url.wrapper.same=true"))
            assertTrue(result.stdout.contains("url.wrapper.shadow=false"))
            assertTrue(result.stdout.contains("url.wrapper.URL=true"))
            assertTrue(result.stdout.contains("url.wrapper.params=1"))
            assertTrue(result.stdout.contains("url.domain=true"))
            assertTrue(result.stdout.contains("url.static=true"))
            assertTrue(result.stdout.contains("url.legacy=true"))
            assertTrue(result.stdout.contains("url.pattern=true"))
            assertTrue(result.stdout.contains("web.utility=true"))
            assertTrue(result.stdout.contains("url.path.apis=function,function"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun limitedUrlFileInteropSupportsRoundTripAndScopedFsUrlPathLikeInputs() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-url-file-interop-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create URL file interop test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const fsp = require("fs/promises");
                const path = require("path");
                const url = require("url");
                const nodeUrl = require("node:url");

                function normalized(value) {
                  return String(value).replace(/\\/g, "/");
                }

                async function callbackRead(fileUrl) {
                  return new Promise((resolve, reject) => {
                    fs.readFile(fileUrl, "utf8", (error, text) => {
                      if (error) reject(error);
                      else resolve(text);
                    });
                  });
                }

                async function callbackReaddir(dirUrl) {
                  return new Promise((resolve, reject) => {
                    fs.readdir(dirUrl, { withFileTypes: true }, (error, entries) => {
                      if (error) reject(error);
                      else resolve(entries);
                    });
                  });
                }

                async function main() {
                  console.log("url.file.alias=" + (url === nodeUrl));
                  console.log("url.file.types=" + (
                    typeof url.fileURLToPath === "function" &&
                    typeof url.pathToFileURL === "function"
                  ));

                  fs.writeFileSync("./plain.txt", "sync", "utf8");
                  const plainUrl = url.pathToFileURL("./plain.txt");
                  const plainPath = url.fileURLToPath(plainUrl);
                  console.log("url.file.protocol=" + plainUrl.protocol);
                  console.log("url.file.roundtrip=" + normalized(plainPath).endsWith("/plain.txt"));
                  console.log("url.file.read.sync=" + fs.readFileSync(plainUrl, "utf8"));

                  const syncUrl = url.pathToFileURL("./sync-url.txt");
                  fs.writeFileSync(syncUrl, "sync-url", "utf8");
                  fs.appendFileSync(syncUrl, "+append", "utf8");
                  fs.accessSync(syncUrl, fs.constants.R_OK);
                  console.log("url.file.write.sync=" + fs.readFileSync(syncUrl, "utf8"));
                  console.log("url.file.stat.sync=" + (
                    fs.statSync(syncUrl).isFile() &&
                    fs.lstatSync(syncUrl).isFile() &&
                    fs.existsSync(syncUrl)
                  ));
                  fs.copyFileSync(syncUrl, url.pathToFileURL("./copy-url.txt"));
                  console.log("url.file.copy.sync=" + fs.readFileSync("./copy-url.txt", "utf8"));
                  console.log("url.file.realpath.sync=" + normalized(fs.realpathSync(syncUrl)).endsWith("/sync-url.txt"));
                  console.log("url.file.realpath.native=" + normalized(fs.realpathSync.native(syncUrl)).endsWith("/sync-url.txt"));

                  fs.mkdirSync("./url-dir/sub", { recursive: true });
                  const encodedRelative = "./url-dir/sub/space \u4e2d\u6587.txt";
                  fs.writeFileSync(encodedRelative, "encoded", "utf8");
                  const encodedUrl = url.pathToFileURL(encodedRelative);
                  console.log("url.file.encoded=" + (
                    encodedUrl.href.includes("%20") &&
                    encodedUrl.href.includes("%E4%B8%AD")
                  ));
                  console.log("url.file.encoded.read=" + fs.readFileSync(encodedUrl, "utf8"));

                  const dirUrl = url.pathToFileURL("./url-dir");
                  const syncDirents = fs.readdirSync(dirUrl, { withFileTypes: true });
                  console.log("url.file.dirent.sync=" + syncDirents.some((entry) => entry.name === "sub" && entry.isDirectory()));
                  const callbackDirents = await callbackReaddir(dirUrl);
                  console.log("url.file.dirent.callback=" + callbackDirents.some((entry) => entry.name === "sub" && entry.isDirectory()));

                  await fsp.mkdir(url.pathToFileURL("./promise-dir/sub"), { recursive: true });
                  const promiseUrl = url.pathToFileURL("./promise-dir/sub/promise.txt");
                  await fsp.writeFile(promiseUrl, "promise", "utf8");
                  await fsp.appendFile(promiseUrl, "+url", "utf8");
                  await fsp.access(promiseUrl, fs.constants.R_OK);
                  const promiseText = await fsp.readFile(promiseUrl, "utf8");
                  const promiseStat = await fsp.stat(promiseUrl);
                  const promiseLstat = await fsp.lstat(promiseUrl);
                  await fsp.copyFile(promiseUrl, url.pathToFileURL("./promise-dir/sub/copy.txt"));
                  const promiseEntries = await fsp.readdir(url.pathToFileURL("./promise-dir/sub"), { withFileTypes: true });
                  const promiseReal = await fsp.realpath(promiseUrl);
                  console.log("url.file.promise.read=" + promiseText);
                  console.log("url.file.promise.stat=" + (promiseStat.isFile() && promiseLstat.isFile()));
                  console.log("url.file.promise.readdir=" + promiseEntries.some((entry) => entry.name === "copy.txt" && entry.isFile()));
                  console.log("url.file.promise.copy=" + await fsp.readFile(url.pathToFileURL("./promise-dir/sub/copy.txt"), "utf8"));
                  console.log("url.file.promise.realpath=" + normalized(promiseReal).endsWith("/promise-dir/sub/promise.txt"));
                  await fsp.unlink(url.pathToFileURL("./promise-dir/sub/copy.txt"));

                  const opened = await fsp.opendir(url.pathToFileURL("./promise-dir/sub"));
                  const iterated = [];
                  for await (const entry of opened) {
                    iterated.push(String(entry.name) + ":" + entry.isFile());
                  }
                  console.log("url.file.opendir=" + iterated.includes("promise.txt:true"));

                  console.log("url.file.callback.read=" + await callbackRead(encodedUrl));

                  process.chdir("./url-dir");
                  const cwdUrl = url.pathToFileURL("./sub/space \u4e2d\u6587.txt");
                  console.log("url.file.chdir=" + fs.readFileSync(cwdUrl, "utf8"));
                  console.log("url.file.chdir.roundtrip=" + normalized(url.fileURLToPath(cwdUrl)).endsWith("/url-dir/sub/space \u4e2d\u6587.txt"));
                  process.chdir("..");

                  await fsp.rm(url.pathToFileURL("./promise-dir"), { recursive: true, force: true });
                  fs.rmSync(dirUrl, { recursive: true, force: true });
                  fs.unlinkSync(syncUrl);
                  fs.unlinkSync(url.pathToFileURL("./copy-url.txt"));
                  fs.unlinkSync(plainUrl);
                  console.log("url.file.cleanup=" + (
                    !fs.existsSync("./promise-dir") &&
                    !fs.existsSync("./url-dir") &&
                    !fs.existsSync("./sync-url.txt") &&
                    !fs.existsSync("./plain.txt")
                  ));
                }

                return main();
                """.trimIndent(),
                "<embedded-url-file-interop-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("url.file.alias=true"))
            assertTrue(result.stdout.contains("url.file.types=true"))
            assertTrue(result.stdout.contains("url.file.protocol=file:"))
            assertTrue(result.stdout.contains("url.file.roundtrip=true"))
            assertTrue(result.stdout.contains("url.file.read.sync=sync"))
            assertTrue(result.stdout.contains("url.file.write.sync=sync-url+append"))
            assertTrue(result.stdout.contains("url.file.stat.sync=true"))
            assertTrue(result.stdout.contains("url.file.copy.sync=sync-url+append"))
            assertTrue(result.stdout.contains("url.file.realpath.sync=true"))
            assertTrue(result.stdout.contains("url.file.realpath.native=true"))
            assertTrue(result.stdout.contains("url.file.encoded=true"))
            assertTrue(result.stdout.contains("url.file.encoded.read=encoded"))
            assertTrue(result.stdout.contains("url.file.dirent.sync=true"))
            assertTrue(result.stdout.contains("url.file.dirent.callback=true"))
            assertTrue(result.stdout.contains("url.file.promise.read=promise+url"))
            assertTrue(result.stdout.contains("url.file.promise.stat=true"))
            assertTrue(result.stdout.contains("url.file.promise.readdir=true"))
            assertTrue(result.stdout.contains("url.file.promise.copy=promise+url"))
            assertTrue(result.stdout.contains("url.file.promise.realpath=true"))
            assertTrue(result.stdout.contains("url.file.opendir=true"))
            assertTrue(result.stdout.contains("url.file.callback.read=encoded"))
            assertTrue(result.stdout.contains("url.file.chdir=encoded"))
            assertTrue(result.stdout.contains("url.file.chdir.roundtrip=true"))
            assertTrue(result.stdout.contains("url.file.cleanup=true"))
            assertFalse(File(scriptDir, "promise-dir").exists())
            assertFalse(File(scriptDir, "url-dir").exists())
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun limitedUrlFileInteropRejectsUnsafeProtocolsAndSandboxEscapes() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-url-file-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create URL file deny test dir: $absolutePath" }
        }
        val outside = File(scriptDir.parentFile, "${scriptDir.name}-outside.txt").apply {
            delete()
        }
        try {
            val outsideUrl = outside.toURI().toString()
            val sandboxRootUrl = scriptDir.toURI().toString()
            val urlShadow = File(scriptDir, "node_modules/url/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const fsp = require("fs/promises");
                const url = require("url");
                const outsidePath = ${jsStringLiteral(outside.canonicalPath)};
                const outsideUrl = ${jsStringLiteral(outsideUrl)};
                const sandboxRootUrl = ${jsStringLiteral(sandboxRootUrl)};
                const nulPath = "bad" + String.fromCharCode(0) + "path";

                function messageOf(error) {
                  return String(error && error.message).replace(/\s+/g, " ");
                }

                function captureSync(label, action) {
                  try {
                    action();
                    console.log(label + ".unexpected=true");
                  } catch (error) {
                    const message = messageOf(error);
                    console.log(label + ".isError=" + (error instanceof Error));
                    console.log(label + ".code=" + error.code);
                    console.log(label + ".fileToken=" + message.includes("file URL"));
                    console.log(label + ".pathToFileURL=" + message.includes("pathToFileURL"));
                    console.log(label + ".fileURLToPath=" + message.includes("fileURLToPath"));
                    console.log(label + ".sandbox=" + message.includes("sandboxRoot"));
                  }
                }

                function capturePromise(label, action) {
                  return Promise.resolve()
                    .then(action)
                    .then(() => {
                      console.log(label + ".unexpected=true");
                    })
                    .catch((error) => {
                      const message = messageOf(error);
                      console.log(label + ".isError=" + (error instanceof Error));
                      console.log(label + ".code=" + error.code);
                      console.log(label + ".fileToken=" + message.includes("file URL"));
                      console.log(label + ".sandbox=" + message.includes("sandboxRoot"));
                    });
                }

                captureSync("url.reject.http", () => url.fileURLToPath("https://example.com/a.txt"));
                captureSync("url.reject.host", () => url.fileURLToPath("file://example.com/a.txt"));
                captureSync("url.reject.outside.file", () => url.fileURLToPath(outsideUrl));
                captureSync("url.reject.outside.path", () => url.pathToFileURL(outsidePath));
                captureSync("url.reject.escape.path", () => url.pathToFileURL("../outside.txt"));
                captureSync("url.reject.nul.path", () => url.pathToFileURL(nulPath));
                captureSync("url.reject.nul.file", () => url.fileURLToPath(new URL("bad%00path", sandboxRootUrl)));
                captureSync("url.reject.fs.sync", () => fs.readFileSync(new URL(outsideUrl), "utf8"));
                captureSync("url.reject.getBuiltinModule", () => process.getBuiltinModule("url"));
                console.log("url.reject.shadow=" + (url.shadow === true));

                return Promise.all([
                  capturePromise("url.reject.fs.promise", () => fsp.readFile(new URL(outsideUrl), "utf8")),
                  capturePromise("url.reject.opendir", () => fsp.opendir(new URL(outsideUrl)))
                ]).then(() => {
                  console.log("url.reject.done=true");
                });
                """.trimIndent(),
                "<embedded-url-file-deny-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(urlShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("url.reject.http.isError=true"))
            assertTrue(result.stdout.contains("url.reject.http.fileURLToPath=true"))
            assertTrue(result.stdout.contains("url.reject.host.isError=true"))
            assertTrue(result.stdout.contains("url.reject.host.fileURLToPath=true"))
            assertTrue(result.stdout.contains("url.reject.outside.file.isError=true"))
            assertTrue(result.stdout.contains("url.reject.outside.file.fileURLToPath=true"))
            assertTrue(result.stdout.contains("url.reject.outside.file.sandbox=true"))
            assertTrue(result.stdout.contains("url.reject.outside.path.isError=true"))
            assertTrue(result.stdout.contains("url.reject.outside.path.pathToFileURL=true"))
            assertTrue(result.stdout.contains("url.reject.outside.path.sandbox=true"))
            assertTrue(result.stdout.contains("url.reject.escape.path.isError=true"))
            assertTrue(result.stdout.contains("url.reject.escape.path.pathToFileURL=true"))
            assertTrue(result.stdout.contains("url.reject.escape.path.sandbox=true"))
            assertTrue(result.stdout.contains("url.reject.nul.path.isError=true"))
            assertTrue(result.stdout.contains("url.reject.nul.path.pathToFileURL=true"))
            assertTrue(result.stdout.contains("url.reject.nul.file.isError=true"))
            assertTrue(result.stdout.contains("url.reject.nul.file.fileURLToPath=true"))
            assertTrue(result.stdout.contains("url.reject.fs.sync.isError=true"))
            assertTrue(result.stdout.contains("url.reject.fs.sync.fileToken=true"))
            assertTrue(result.stdout.contains("url.reject.fs.sync.sandbox=true"))
            assertTrue(result.stdout.contains("url.reject.fs.promise.isError=true"))
            assertTrue(result.stdout.contains("url.reject.fs.promise.code=EPERM"))
            assertTrue(result.stdout.contains("url.reject.fs.promise.fileToken=true"))
            assertTrue(result.stdout.contains("url.reject.opendir.isError=true"))
            assertTrue(result.stdout.contains("url.reject.opendir.code=EPERM"))
            assertTrue(result.stdout.contains("url.reject.getBuiltinModule.isError=true"))
            assertTrue(result.stdout.contains("url.reject.shadow=false"))
            assertFalse(result.stdout.contains(".unexpected=true"))
            assertTrue(result.stdout.contains("url.reject.done=true"))
        } finally {
            scriptDir.deleteRecursively()
            outside.delete()
        }
    }

    @Test
    fun urlPathToolsLiteCorpusUsesFileUrlsForFsPromisesAndOpendirTraversal() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectDir = File(context.cacheDir, "embedded-url-path-tools-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create URL path tools project dir: $absolutePath" }
        }
        try {
            File(projectDir, "workspace/input").apply {
                check(mkdirs()) { "Failed to create URL path tools input dir: $absolutePath" }
            }
            File(projectDir, "workspace/input/a.txt").writeText("alpha", StandardCharsets.UTF_8)
            File(projectDir, "workspace/input/b.md").writeText("beta", StandardCharsets.UTF_8)
            val packageDir = File(projectDir, "node_modules/url-path-tools-lite").apply {
                check(mkdirs()) { "Failed to create url-path-tools-lite package dir: $absolutePath" }
            }
            File(packageDir, "package.json").writeText(
                """{"name":"url-path-tools-lite","version":"1.0.0","exports":{".":"./index.js"}}""",
                StandardCharsets.UTF_8,
            )
            val packageIndex = File(packageDir, "index.js").apply {
                writeText(
                    """
                    const fs = require("fs");
                    const fsp = require("fs/promises");
                    const path = require("path");
                    const { Buffer } = require("buffer");
                    const { pathToFileURL, fileURLToPath } = require("url");

                    function normalize(value) {
                      return String(value).replace(/\\/g, "/").replace(/^\.\/+/, "");
                    }

                    exports.run = async function run(options) {
                      const inputUrl = pathToFileURL(options.inputDir);
                      const names = [];
                      const dir = await fsp.opendir(inputUrl);
                      for await (const entry of dir) {
                        if (entry.isFile()) {
                          names.push(entry.name);
                        }
                      }
                      names.sort();
                      const textUrl = pathToFileURL(path.join(options.inputDir, "a.txt"));
                      const text = await fsp.readFile(textUrl, "utf8");
                      const outUrl = pathToFileURL(options.outFile);
                      await fsp.mkdir(path.dirname(options.outFile), { recursive: true });
                      await fsp.writeFile(outUrl, Buffer.from(JSON.stringify({
                        files: names,
                        text,
                        roundtrip: normalize(fileURLToPath(textUrl)).endsWith("/workspace/input/a.txt"),
                        dirent: fs.readdirSync(inputUrl, { withFileTypes: true }).some((entry) => entry.name === "a.txt" && entry.isFile())
                      }), "utf8"));
                      return JSON.parse(await fsp.readFile(outUrl, "utf8"));
                    };
                    """.trimIndent() + "\n",
                    StandardCharsets.UTF_8,
                )
            }
            val main = File(projectDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const tool = require("url-path-tools-lite");
                    return tool.run({
                      inputDir: "./workspace/input",
                      outFile: "./workspace/output/result.json"
                    }).then((result) => {
                      console.log("url.corpus.ready=" + (
                        result.files.join("|") === "a.txt|b.md" &&
                        result.text === "alpha" &&
                        result.roundtrip === true &&
                        result.dirent === true
                      ));
                      console.log("url.corpus.opendir=" + result.files.includes("a.txt"));
                      console.log("url.corpus.fs_url=" + (result.text === "alpha"));
                      console.log("url.corpus.output=" + result.dirent);
                    });
                    """.trimIndent() + "\n",
                    StandardCharsets.UTF_8,
                )
            }
            val result = runEmbeddedScript(
                main.readText(StandardCharsets.UTF_8),
                main.canonicalPath,
                workingDirectory = projectDir.canonicalPath,
                moduleSources = moduleSourcesFor(main, packageIndex),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("url.corpus.ready=true"))
            assertTrue(result.stdout.contains("url.corpus.opendir=true"))
            assertTrue(result.stdout.contains("url.corpus.fs_url=true"))
            assertTrue(result.stdout.contains("url.corpus.output=true"))
            assertTrue(File(projectDir, "workspace/output/result.json").isFile)
        } finally {
            projectDir.deleteRecursively()
        }
    }

    @Test
    fun packageBinScaffoldCopyLiteCorpusUsesFsPromisesCpAndUrlPaths() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectDir = File(context.cacheDir, "embedded-scaffold-copy-lite-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scaffold copy lite project dir: $absolutePath" }
        }
        try {
            File(projectDir, "workspace/template/nested").apply {
                check(mkdirs()) { "Failed to create scaffold template dir: $absolutePath" }
            }
            File(projectDir, "workspace/plugins").apply {
                check(mkdirs()) { "Failed to create scaffold plugin dir: $absolutePath" }
            }
            File(projectDir, "workspace/template/empty").mkdirs()
            File(projectDir, "workspace/template/index.txt").writeText("hello scaffold", StandardCharsets.UTF_8)
            File(projectDir, "workspace/template/nested/data.bin").writeBytes(byteArrayOf(5, 6, 7))
            File(projectDir, "workspace/config.json").writeText(
                """{"template":"template","output":"dist/generated","plugin":"suffix","useUrl":true}""",
                StandardCharsets.UTF_8,
            )
            File(projectDir, "workspace/plugins/suffix.js").writeText(
                """
                const processBuiltin = require("process");
                const constantsBuiltin = require("constants");
                const { Buffer } = require("buffer");

                exports.transform = function transform(text) {
                  return Buffer.from(String(text).toUpperCase() + "|" + (
                    processBuiltin.cwd().indexOf("workspace") >= 0 &&
                    typeof constantsBuiltin.F_OK === "number"
                  ), "utf8").toString("utf8");
                };
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )
            val packageDir = File(projectDir, "node_modules/scaffold-copy-lite").apply {
                check(mkdirs()) { "Failed to create scaffold-copy-lite package dir: $absolutePath" }
            }
            File(packageDir, "package.json").writeText(
                """{"name":"scaffold-copy-lite","version":"1.0.0","bin":{"scaffold-copy-lite":"./cli.js"}}""",
                StandardCharsets.UTF_8,
            )
            File(packageDir, "cli.js").writeText(
                """
                #!/usr/bin/env node
                const fs = require("fs");
                const fsp = require("fs/promises");
                const path = require("path");
                const processBuiltin = require("process");
                const constantsBuiltin = require("constants");
                const { Buffer } = require("buffer");
                const { createRequire } = require("module");
                const { pathToFileURL } = require("url");

                function argValue(name, fallback) {
                  const index = process.argv.indexOf(name);
                  return index >= 0 && index + 1 < process.argv.length ? process.argv[index + 1] : fallback;
                }

                async function main() {
                  const cwd = argValue("--cwd", ".");
                  process.chdir(cwd);
                  const configPath = path.resolve(argValue("--config", "config.json"));
                  const outDir = argValue("--out", "dist/generated");
                  const config = JSON.parse(await fsp.readFile(pathToFileURL(configPath), "utf8"));
                  await fsp.cp(
                    config.useUrl ? pathToFileURL(config.template) : config.template,
                    config.useUrl ? pathToFileURL(outDir) : outDir,
                    { recursive: true }
                  );
                  const configRequire = createRequire(configPath);
                  const transformer = configRequire("./plugins/" + config.plugin);
                  const indexPath = path.join(outDir, "index.txt");
                  const original = await fsp.readFile(pathToFileURL(indexPath), "utf8");
                  const transformed = transformer.transform(original);
                  await fsp.writeFile(pathToFileURL(indexPath), Buffer.from(transformed, "utf8"));
                  const nestedOk = fs.readFileSync(path.join(outDir, "nested/data.bin")).equals(Buffer.from([5, 6, 7]));
                  const emptyOk = fs.statSync(path.join(outDir, "empty")).isDirectory();
                  const output = await fsp.readFile(pathToFileURL(indexPath), "utf8");
                  console.log("scaffold.copy.ready=" + (
                    output === "HELLO SCAFFOLD|true" &&
                    processBuiltin.cwd().replace(/\\/g, "/").endsWith("/workspace") &&
                    constantsBuiltin.F_OK === fs.constants.F_OK
                  ));
                  console.log("scaffold.copy.files=" + (nestedOk && emptyOk));
                  console.log("scaffold.copy.url=" + config.useUrl);
                  console.log("scaffold.copy.plugin=" + (typeof transformer.transform === "function"));
                  console.log("scaffold.copy.output=" + fs.existsSync(indexPath));
                }

                main().catch((error) => {
                  console.error("scaffold.copy.error=" + (error && (error.stack || error.message) || error));
                  process.exitCode = 1;
                });
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )

            val result = runEmbeddedPackageBin(
                projectDir = projectDir,
                packageDir = packageDir,
                binName = "scaffold-copy-lite",
                args = listOf("--cwd", "workspace", "--config", "config.json", "--out", "dist/generated"),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("scaffold.copy.ready=true"))
            assertTrue(result.stdout.contains("scaffold.copy.files=true"))
            assertTrue(result.stdout.contains("scaffold.copy.url=true"))
            assertTrue(result.stdout.contains("scaffold.copy.plugin=true"))
            assertTrue(result.stdout.contains("scaffold.copy.output=true"))
            assertEquals(
                "HELLO SCAFFOLD|true",
                File(projectDir, "workspace/dist/generated/index.txt").readText(StandardCharsets.UTF_8),
            )
            assertArrayEquals(
                byteArrayOf(5, 6, 7),
                File(projectDir, "workspace/dist/generated/nested/data.bin").readBytes(),
            )
        } finally {
            projectDir.deleteRecursively()
        }
    }

    @Test
    fun packageBinWriteAtomicLiteCorpusUsesMkdtempRenameAndUrls() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectDir = File(context.cacheDir, "embedded-write-atomic-lite-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create write atomic lite project dir: $absolutePath" }
        }
        try {
            File(projectDir, "workspace").apply {
                check(mkdirs()) { "Failed to create write atomic workspace dir: $absolutePath" }
            }
            val packageDir = File(projectDir, "node_modules/write-atomic-lite").apply {
                check(mkdirs()) { "Failed to create write-atomic-lite package dir: $absolutePath" }
            }
            File(packageDir, "package.json").writeText(
                """{"name":"write-atomic-lite","version":"1.0.0","bin":{"atomic-tool":"./cli.js"},"exports":{".":"./index.js"}}""",
                StandardCharsets.UTF_8,
            )
            File(packageDir, "index.js").writeText(
                """
                const fs = require("fs");
                const fsp = require("fs/promises");
                const path = require("path");
                const processBuiltin = require("process");
                const constantsBuiltin = require("constants");
                const { Buffer } = require("buffer");
                const { pathToFileURL } = require("url");

                exports.writeAtomic = async function writeAtomic(outFile, text) {
                  const outDir = path.dirname(outFile);
                  await fsp.mkdir(outDir, { recursive: true });
                  const tmpDir = await fsp.mkdtemp(path.join(outDir, ".tmp-"));
                  const tmpFile = path.join(tmpDir, path.basename(outFile) + ".tmp");
                  await fsp.writeFile(tmpFile, Buffer.from(text, "utf8"));
                  await fsp.rename(tmpFile, pathToFileURL(outFile));
                  await fsp.rm(tmpDir, { recursive: true, force: true });
                  const tempLeftovers = (await fsp.readdir(outDir)).filter((name) => String(name).startsWith(".tmp-"));
                  return {
                    output: await fsp.readFile(pathToFileURL(outFile), "utf8"),
                    mkdtemp: fs.existsSync(outDir) && tmpDir.indexOf(".tmp-") >= 0,
                    rename: !fs.existsSync(tmpFile) && fs.existsSync(outFile),
                    url: pathToFileURL(outFile).protocol === "file:",
                    cleanup: tempLeftovers.length === 0,
                    process: processBuiltin.cwd().indexOf("workspace") >= 0,
                    constants: constantsBuiltin.F_OK === fs.constants.F_OK
                  };
                };
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )
            File(packageDir, "cli.js").writeText(
                """
                #!/usr/bin/env node
                const fs = require("fs");
                const fsp = require("fs/promises");
                const path = require("path");
                const processBuiltin = require("process");
                const atomic = require("./index.js");

                function argValue(name, fallback) {
                  const index = process.argv.indexOf(name);
                  return index >= 0 && index + 1 < process.argv.length ? process.argv[index + 1] : fallback;
                }

                async function main() {
                  process.chdir(argValue("--cwd", "."));
                  const outFile = argValue("--out", "output/final.txt");
                  const text = argValue("--text", "atomic");
                  const result = await atomic.writeAtomic(outFile, text);
                  await fsp.mkdir("dist", { recursive: true });
                  await fsp.cp(outFile, path.join("dist", path.basename(outFile)), { recursive: true });
                  const copied = await fsp.readFile(path.join("dist", path.basename(outFile)), "utf8");
                  console.log("atomic.write.ready=" + (
                    result.output === text &&
                    copied === text &&
                    result.process === true &&
                    processBuiltin.cwd().replace(/\\/g, "/").endsWith("/workspace")
                  ));
                  console.log("atomic.write.mkdtemp=" + result.mkdtemp);
                  console.log("atomic.write.rename=" + result.rename);
                  console.log("atomic.write.url=" + result.url);
                  console.log("atomic.write.cleanup=" + result.cleanup);
                }

                main().catch((error) => {
                  console.error("atomic.write.error=" + (error && (error.stack || error.message) || error));
                  process.exitCode = 1;
                });
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )

            val result = runEmbeddedPackageBin(
                projectDir = projectDir,
                packageDir = packageDir,
                binName = "atomic-tool",
                args = listOf("--cwd", "workspace", "--out", "output/final.txt", "--text", "atomic-value"),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("atomic.write.ready=true"))
            assertTrue(result.stdout.contains("atomic.write.mkdtemp=true"))
            assertTrue(result.stdout.contains("atomic.write.rename=true"))
            assertTrue(result.stdout.contains("atomic.write.url=true"))
            assertTrue(result.stdout.contains("atomic.write.cleanup=true"))
            assertEquals(
                "atomic-value",
                File(projectDir, "workspace/output/final.txt").readText(StandardCharsets.UTF_8),
            )
            assertEquals(
                "atomic-value",
                File(projectDir, "workspace/dist/final.txt").readText(StandardCharsets.UTF_8),
            )
        } finally {
            projectDir.deleteRecursively()
        }
    }

    @Test
    fun packageBinCacheCopyLiteCorpusUsesUtimesCpPreserveRenameAndUrls() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectDir = File(context.cacheDir, "embedded-cache-copy-lite-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create cache copy lite project dir: $absolutePath" }
        }
        try {
            File(projectDir, "workspace/source").apply {
                check(mkdirs()) { "Failed to create cache copy source dir: $absolutePath" }
            }
            File(projectDir, "workspace/source/input.txt").writeText("cache-source", StandardCharsets.UTF_8)
            val packageDir = File(projectDir, "node_modules/cache-copy-lite").apply {
                check(mkdirs()) { "Failed to create cache-copy-lite package dir: $absolutePath" }
            }
            File(packageDir, "package.json").writeText(
                """{"name":"cache-copy-lite","version":"1.0.0","bin":{"cache-copy-lite":"./cli.js"},"exports":{".":"./index.js"}}""",
                StandardCharsets.UTF_8,
            )
            File(packageDir, "index.js").writeText(
                """
                const fs = require("fs");
                const fsp = require("fs/promises");
                const path = require("path");
                const processBuiltin = require("process");
                const constantsBuiltin = require("constants");
                const { Buffer } = require("buffer");
                const { pathToFileURL } = require("url");

                function closeTime(actual, expected) {
                  return Math.abs(Number(actual) - Number(expected)) < 5000;
                }

                exports.copyToCache = async function copyToCache(options) {
                  const source = options.source;
                  const cacheDir = options.cacheDir;
                  const outFile = options.outFile;
                  const oldDate = new Date("2008-09-10T11:12:13Z");
                  await fsp.utimes(source, oldDate, oldDate);
                  await fsp.mkdir(cacheDir, { recursive: true });
                  const cached = path.join(cacheDir, path.basename(source));
                  await fsp.cp(pathToFileURL(source), pathToFileURL(cached), {
                    recursive: true,
                    preserveTimestamps: true
                  });
                  const sourceStat = await fsp.stat(source);
                  const cachedStat = await fsp.stat(cached);
                  const tempDir = await fsp.mkdtemp(path.join(cacheDir, ".tmp-"));
                  const tempFile = path.join(tempDir, path.basename(outFile) + ".tmp");
                  await fsp.writeFile(tempFile, Buffer.from(await fsp.readFile(cached, "utf8") + "|cache", "utf8"));
                  await fsp.mkdir(path.dirname(outFile), { recursive: true });
                  await fsp.rename(tempFile, pathToFileURL(outFile));
                  await fsp.rm(tempDir, { recursive: true, force: true });
                  const tempLeftovers = (await fsp.readdir(cacheDir)).filter((name) => String(name).startsWith(".tmp-"));
                  return {
                    text: await fsp.readFile(pathToFileURL(outFile), "utf8"),
                    utimes: closeTime(sourceStat.mtimeMs, oldDate.getTime()),
                    preserve: closeTime(cachedStat.mtimeMs, oldDate.getTime()),
                    rename: fs.existsSync(outFile) && !fs.existsSync(tempFile),
                    url: pathToFileURL(outFile).protocol === "file:",
                    cleanup: tempLeftovers.length === 0,
                    process: processBuiltin.cwd().indexOf("workspace") >= 0,
                    constants: constantsBuiltin.F_OK === fs.constants.F_OK
                  };
                };
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )
            File(packageDir, "cli.js").writeText(
                """
                #!/usr/bin/env node
                const cacheCopy = require("./index.js");
                const processBuiltin = require("process");

                function argValue(name, fallback) {
                  const index = process.argv.indexOf(name);
                  return index >= 0 && index + 1 < process.argv.length ? process.argv[index + 1] : fallback;
                }

                async function main() {
                  process.chdir(argValue("--cwd", "."));
                  const result = await cacheCopy.copyToCache({
                    source: argValue("--source", "source/input.txt"),
                    cacheDir: argValue("--cache", "cache"),
                    outFile: argValue("--out", "dist/output.txt")
                  });
                  console.log("cache.copy.ready=" + (
                    result.text === "cache-source|cache" &&
                    result.process === true &&
                    processBuiltin.cwd().replace(/\\/g, "/").endsWith("/workspace")
                  ));
                  console.log("cache.copy.utimes=" + result.utimes);
                  console.log("cache.copy.preserve=" + result.preserve);
                  console.log("cache.copy.rename=" + result.rename);
                  console.log("cache.copy.url=" + result.url);
                  console.log("cache.copy.cleanup=" + result.cleanup);
                }

                main().catch((error) => {
                  console.error("cache.copy.error=" + (error && (error.stack || error.message) || error));
                  process.exitCode = 1;
                });
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )

            val result = runEmbeddedPackageBin(
                projectDir = projectDir,
                packageDir = packageDir,
                binName = "cache-copy-lite",
                args = listOf(
                    "--cwd",
                    "workspace",
                    "--source",
                    "source/input.txt",
                    "--cache",
                    "cache",
                    "--out",
                    "dist/output.txt",
                ),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("cache.copy.ready=true"))
            assertTrue(result.stdout.contains("cache.copy.utimes=true"))
            assertTrue(result.stdout.contains("cache.copy.preserve=true"))
            assertTrue(result.stdout.contains("cache.copy.rename=true"))
            assertTrue(result.stdout.contains("cache.copy.url=true"))
            assertTrue(result.stdout.contains("cache.copy.cleanup=true"))
            assertEquals(
                "cache-source|cache",
                File(projectDir, "workspace/dist/output.txt").readText(StandardCharsets.UTF_8),
            )
        } finally {
            projectDir.deleteRecursively()
        }
    }

    @Test
    fun utilCompatibilitySweepSupportsFormattingTypesAndCallbackifyChain() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-util-compat-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create util compatibility test dir: $absolutePath" }
        }
        try {
            val utilShadow = File(scriptDir, "node_modules/util/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const util = require("util");
                const nodeUtil = require("node:util");
                fs.writeFileSync("./util.txt", "value", "utf8");
                const readFilePromise = util.promisify(fs.readFile);
                const readFileCallback = util.callbackify(readFilePromise);
                function Base() {}
                function Child() {}
                util.inherits(Child, Base);
                const debug = util.debuglog("autojs6-embedded-node-test");
                debug("hidden");
                const customInspect = {
                  [util.inspect.custom]() {
                    return "custom-inspect";
                  }
                };
                function customCallback(value, callback) {
                  callback(null, value + ":callback");
                }
                customCallback[util.promisify.custom] = function(value) {
                  return Promise.resolve(value + ":custom");
                };
                const customPromisified = util.promisify(customCallback)("promisify");
                const callbackifyError = new Promise((resolve) => {
                  util.callbackify(function() {
                    return Promise.reject(new Error("callback boom"));
                  })(function(error) {
                    resolve(error && error.message);
                  });
                });
                const callbackifyNull = new Promise((resolve) => {
                  util.callbackify(function() {
                    return Promise.reject(null);
                  })(function(error) {
                    resolve(error instanceof Error && error.reason === null);
                  });
                });
                const abortController = new AbortController();
                const abortedResult = util.aborted(abortController.signal, {}).then(() => abortController.signal.aborted);
                abortController.abort();
                const done = new Promise((resolve, reject) => {
                  readFileCallback("./util.txt", "utf8", (error, text) => {
                    if (error) {
                      reject(error);
                      return;
                    }
                    console.log("util.callbackify.text=" + text);
                    resolve();
                  });
                }).then(() => Promise.all([customPromisified, callbackifyError, callbackifyNull, abortedResult])).then((results) => {
                  const parsed = util.parseArgs({
                    args: ["--name", "autojs6", "--flag"],
                    options: {
                      name: { type: "string" },
                      flag: { type: "boolean" }
                    }
                  });
                  const encoder = new util.TextEncoder();
                  const decoder = new util.TextDecoder();
                  const mime = new util.MIMEType('Text/HTML; Charset="utf-8"; boundary=x');
                  mime.subtype = "plain";
                  mime.params.set("format", "flowed");
                  const mimeParams = new util.MIMEParams();
                  mimeParams.set("charset", "utf-8");
                  mimeParams.set("boundary", "x");
                  let invalidMime = "";
                  try {
                    new util.MIMEType("not valid");
                  } catch (error) {
                    invalidMime = error && error.code;
                  }
                  const escape = String.fromCharCode(27);
                  const systemErrorMap = util.getSystemErrorMap();
                  const systemErrorEntry = Array.from(systemErrorMap.entries())[0];
                  let systemErrorOk = false;
                  if (systemErrorEntry) {
                    const systemErrorCode = systemErrorEntry[0];
                    const systemErrorValue = systemErrorEntry[1];
                    const systemErrorName = util.getSystemErrorName(systemErrorCode);
                    const systemErrorMessage = util.getSystemErrorMessage(systemErrorCode);
                    systemErrorOk = systemErrorMap instanceof Map &&
                      Array.isArray(systemErrorValue) &&
                      systemErrorName === systemErrorValue[0] &&
                      typeof systemErrorMessage === "string" &&
                      systemErrorMessage.length > 0;
                  }
                  const parsedEnv = util.parseEnv("A=1\nB=\"two\"\nEMPTY=");
                  const styledText = util.styleText("red", "styled", { validateStream: false });
                  console.log("util.format=" + util.format("%s:%d", "x", 1));
                  console.log("util.formatWithOptions=" + util.formatWithOptions({ colors: false }, "%o", { nested: true }).includes("nested"));
                  console.log("util.inspect=" + util.inspect({ a: 1 }).includes("a"));
                  console.log("util.inspect.custom=" + util.inspect(customInspect));
                  console.log("util.inherits=" + (new Child() instanceof Base));
                  console.log("util.same=" + (util === nodeUtil));
                  console.log("util.shadow=" + (util.shadow === true));
                  console.log("util.frozen=" + Object.isFrozen(util));
                  console.log("util.types.frozen=" + Object.isFrozen(util.types));
                  console.log("util.promisify=" + (typeof util.promisify));
                  console.log("util.promisify.custom=" + (typeof util.promisify.custom) + "/" + results[0]);
                  console.log("util.callbackify=" + (typeof util.callbackify));
                  console.log("util.callbackify.error=" + results[1]);
                  console.log("util.callbackify.null=" + results[2]);
                  console.log("util.types=" + [
                    util.types.isDate(new Date()),
                    util.types.isRegExp(/x/),
                    util.types.isPromise(Promise.resolve()),
                    util.types.isMap(new Map())
                  ].join(","));
                  console.log("util.parseArgs=" + (parsed.values.name + "/" + parsed.values.flag));
                  console.log("util.textCodec=" + decoder.decode(encoder.encode("util-codec")));
                  console.log("util.mime=" + [
                    mime.essence,
                    mime.type,
                    mime.subtype,
                    mime.params.get("charset"),
                    mime.params.has("format"),
                    mimeParams.toString(),
                    Array.from(mimeParams).map((entry) => entry.join("=")).join("|"),
                    invalidMime
                  ].join("/"));
                  console.log("util.stripVT=" + util.stripVTControlCharacters(escape + "[31mred" + escape + "[0m"));
                  console.log("util.deepStrict=" + util.isDeepStrictEqual({ a: [1] }, { a: [1] }));
                  console.log("util.modern=" + [
                    typeof util.getSystemErrorName,
                    typeof util.getSystemErrorMap,
                    typeof util.getSystemErrorMessage,
                    typeof util.styleText,
                    typeof util.parseEnv,
                    typeof util.aborted
                  ].join(","));
                  console.log("util.systemError=" + systemErrorOk);
                  console.log("util.styleText=" + util.stripVTControlCharacters(styledText));
                  console.log("util.parseEnv=" + [
                    parsedEnv.A,
                    parsedEnv.B,
                    Object.prototype.hasOwnProperty.call(parsedEnv, "EMPTY"),
                    parsedEnv.EMPTY
                  ].join("/"));
                  console.log("util.aborted=" + results[3]);
                  console.log("util.symbols=" + [typeof util.inspect.custom, typeof util.promisify.custom].join(","));
                  console.log("util.constructors=" + [typeof util.MIMEType, typeof util.MIMEParams, typeof util.TextEncoder, typeof util.TextDecoder].join(","));
                  console.log("util.hidden=" + [
                    typeof util.getCallSites,
                    typeof util.transferableAbortController,
                    typeof util.setTraceSigInt
                  ].join(","));
                  console.log("util.debuglog=" + (typeof debug));
                });
                console.log("util.scheduled=true");
                return done;
                """.trimIndent(),
                "<embedded-util-compat-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(utilShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertOutputOrder(result.stdout, "util.scheduled=true", "util.callbackify.text=value", "util.types=true,true,true,true")
            assertTrue(result.stdout.contains("util.format=x:1"))
            assertTrue(result.stdout.contains("util.formatWithOptions=true"))
            assertTrue(result.stdout.contains("util.inspect=true"))
            assertTrue(result.stdout.contains("util.inspect.custom=custom-inspect"))
            assertTrue(result.stdout.contains("util.inherits=true"))
            assertTrue(result.stdout.contains("util.same=true"))
            assertTrue(result.stdout.contains("util.shadow=false"))
            assertTrue(result.stdout.contains("util.frozen=true"))
            assertTrue(result.stdout.contains("util.types.frozen=true"))
            assertTrue(result.stdout.contains("util.promisify=function"))
            assertTrue(result.stdout.contains("util.promisify.custom=symbol/promisify:custom"))
            assertTrue(result.stdout.contains("util.callbackify=function"))
            assertTrue(result.stdout.contains("util.callbackify.error=callback boom"))
            assertTrue(result.stdout.contains("util.callbackify.null=true"))
            assertTrue(result.stdout.contains("util.parseArgs=autojs6/true"))
            assertTrue(result.stdout.contains("util.textCodec=util-codec"))
            assertTrue(result.stdout.contains("util.mime=text/plain/text/plain/utf-8/true/charset=utf-8;boundary=x/charset=utf-8|boundary=x/ERR_INVALID_MIME_SYNTAX"))
            assertTrue(result.stdout.contains("util.stripVT=red"))
            assertTrue(result.stdout.contains("util.deepStrict=true"))
            assertTrue(result.stdout.contains("util.modern=function,function,function,function,function,function"))
            assertTrue(result.stdout.contains("util.systemError=true"))
            assertTrue(result.stdout.contains("util.styleText=styled"))
            assertTrue(result.stdout.contains("util.parseEnv=1/two/true/"))
            assertTrue(result.stdout.contains("util.aborted=true"))
            assertTrue(result.stdout.contains("util.symbols=symbol,symbol"))
            assertTrue(result.stdout.contains("util.constructors=function,function,function,function"))
            assertTrue(result.stdout.contains("util.hidden=undefined,undefined,undefined"))
            assertTrue(result.stdout.contains("util.debuglog=function"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun pureJsNpmCoreCompatibilitySmokeUsesBufferPathUrlUtilAndScopedFs() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-npm-core-compat-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create npm core compatibility test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const compose = require("pkg-core-compose-like");
                    const run = compose.run().then((result) => {
                      console.log("core.compat.ok=" + result.ok);
                      console.log("core.compat.codec=" + result.codec);
                      console.log("core.compat.pathDenied=" + result.pathDenied);
                      console.log("core.compat.path=" + result.path);
                      console.log("core.compat.query=" + result.query);
                      console.log("core.compat.formatted=" + result.formatted);
                      console.log("core.compat.util=" + result.util);
                      console.log("core.compat.util_modern=" + result.utilModern);
                      console.log("core.compat.mime=" + result.mime);
                      console.log("core.compat.buffer_blob=" + result.bufferBlob);
                      console.log("core.compat.buffer_transcode=" + result.bufferTranscode);
                      console.log("core.compat.web=" + result.web);
                      console.log("core.compat.web_platform=" + result.webPlatform);
                      console.log("core.compat.web_crypto=" + result.webCrypto);
                      console.log("core.compat.web_compression=" + result.webCompression);
                      console.log("core.compat.assert=" + result.assert);
                      console.log("core.compat.fs.promises=" + result.promisesType);
                    });
                    console.log("core.compat.scheduled=true");
                    return run;
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val compose = File(scriptDir, "node_modules/pkg-core-compose-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fs = require("fs");
                    const codec = require("pkg-buffer-codec-like");
                    const pathTools = require("pkg-path-tools-like");
                    const urlTools = require("pkg-url-query-like");
                    const utilTools = require("pkg-util-format-like");
                    const webTools = require("pkg-web-surface-like");
                    const assertTools = require("pkg-assert-tools-like");
                    exports.run = function run() {
                      fs.writeFileSync("./core.txt", "core", "utf8");
                      const pathResult = pathTools.check("./core.txt");
                      return Promise.all([
                        utilTools.readFormatted("./core.txt"),
                        utilTools.inspectUtilities(),
                        assertTools.checkAssertions(),
                        codec.blobRoundTrip(fs.openAsBlob("./core.txt", { type: "text/plain" })),
                        webTools.checkWebSurface(),
                        webTools.checkWebPlatform(),
                        webTools.checkWebCrypto(),
                        webTools.checkWebCompression()
                      ]).then((results) => {
                        const formatted = results[0];
                        const utilResult = results[1];
                        const assertResult = results[2];
                        const bufferBlobResult = results[3];
                        const webResult = results[4];
                        const webPlatformResult = results[5];
                        const webCryptoResult = results[6];
                        const webCompressionResult = results[7];
                        const bufferTranscodeResult = codec.transcodeSummary();
                        const codecText = codec.encode("core");
                        const query = urlTools.query("https://example.com/app?x=1");
                        return {
                          ok: codecText === "Y29yZQ==" &&
                            pathResult.denied &&
                            pathResult.basename === "core.txt" &&
                            pathResult.surface &&
                            query === "x=1&y=2|1|https://example.com/fmt?a=1|https://example.com/next|true|example.com" &&
                            formatted === "file:core" &&
                            utilResult.ok &&
                            utilResult.modernOk &&
                            utilResult.mimeOk &&
                            bufferBlobResult.ok &&
                            bufferTranscodeResult.ok &&
                            webResult.ok &&
                            webPlatformResult.ok &&
                            webCryptoResult.ok &&
                            webCompressionResult.ok &&
                            assertResult.ok &&
                            typeof fs.promises === "object" &&
                            typeof fs.promises.readFile === "function",
                          codec: codecText,
                          pathDenied: pathResult.denied,
                          path: pathResult.summary,
                          query,
                          formatted,
                          util: utilResult.summary,
                          utilModern: utilResult.modern,
                          mime: utilResult.mime,
                          bufferBlob: bufferBlobResult.summary,
                          bufferTranscode: bufferTranscodeResult.summary,
                          web: webResult.summary,
                          webPlatform: webPlatformResult.summary,
                          webCrypto: webCryptoResult.summary,
                          webCompression: webCompressionResult.summary,
                          assert: assertResult.summary,
                          promisesType: typeof fs.promises
                        };
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val bufferCodec = File(scriptDir, "node_modules/pkg-buffer-codec-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const { Blob, File, resolveObjectURL, transcode } = require("buffer");
                    exports.encode = function encode(text) {
                      return Buffer.concat([Buffer.from(text)]).toString("base64");
                    };
                    exports.transcodeSummary = function transcodeSummary() {
                      const utf16 = transcode(Buffer.from("core", "utf8"), "utf8", "utf16le");
                      const roundtrip = transcode(utf16, "utf16le", "utf8").toString("utf8");
                      const latin1Hex = transcode(Buffer.from([0x63, 0x61, 0x66, 0xe9]), "latin1", "utf8").toString("hex");
                      let invalid = "";
                      try {
                        transcode(Buffer.from("abc"), "bad", "utf8");
                      } catch (error) {
                        invalid = error && error.code;
                      }
                      return {
                        ok: typeof transcode === "function" &&
                          roundtrip === "core" &&
                          latin1Hex === "636166c3a9" &&
                          invalid === "U_ILLEGAL_ARGUMENT_ERROR",
                        summary: [roundtrip, latin1Hex, invalid].join("|")
                      };
                    };
                    exports.blobRoundTrip = async function blobRoundTrip(fsBlobPromise) {
                      const blob = new Blob([Buffer.from("core"), "-blob"], { type: "text/plain" });
                      const file = new File(["core-file"], "core.txt", { type: "text/plain", lastModified: 42 });
                      const fsBlob = await fsBlobPromise;
                      const blobUrl = URL.createObjectURL(blob);
                      const fsBlobUrl = URL.createObjectURL(fsBlob);
                      const resolvedBlob = resolveObjectURL(blobUrl);
                      const resolvedFsBlob = resolveObjectURL(fsBlobUrl);
                      const [blobText, fileText, fsBlobText] = await Promise.all([
                        resolvedBlob.text(),
                        file.text(),
                        resolvedFsBlob.text()
                      ]);
                      URL.revokeObjectURL(blobUrl);
                      URL.revokeObjectURL(fsBlobUrl);
                      return {
                        ok: typeof resolveObjectURL === "function" &&
                          typeof URL.createObjectURL === "function" &&
                          typeof URL.revokeObjectURL === "function" &&
                          resolvedBlob instanceof Blob &&
                          resolvedFsBlob instanceof Blob &&
                          blobText === "core-blob" &&
                          fileText === "core-file" &&
                          file.name === "core.txt" &&
                          file.lastModified === 42 &&
                          file.type === "text/plain" &&
                          fsBlobText === "core" &&
                          resolveObjectURL(blobUrl) === undefined &&
                          resolveObjectURL(fsBlobUrl) === undefined,
                        summary: [
                          blobText,
                          file.name + "/" + file.lastModified + "/" + fileText,
                          fsBlobText,
                          typeof resolveObjectURL,
                          typeof resolveObjectURL(blobUrl)
                        ].join("|")
                      };
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val webTools = File(scriptDir, "node_modules/pkg-web-surface-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    function limitedHttpRequire(name, target) {
                      const mod = require(name);
                      try {
                        mod.request(target);
                        return false;
                      } catch (error) {
                        return mod.STATUS_CODES[200] === "OK" &&
                          typeof mod.Agent === "function" &&
                          error && error.code === "ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED";
                      }
                    }

                    async function readAll(readable) {
                      const reader = readable.getReader();
                      const values = [];
                      while (true) {
                        const next = await reader.read();
                        if (next.done) {
                          return values;
                        }
                        values.push(next.value);
                      }
                    }

                    exports.checkWebSurface = async function checkWebSurface() {
                      const types = [
                        typeof Blob,
                        typeof File,
                        typeof FormData,
                        typeof Headers,
                        typeof Request,
                        typeof Response,
                        typeof fetch
                      ].join(",");
                      const blob = new Blob(["core-web"], { type: "text/plain" });
                      const file = new File(["core-file"], "core-web.txt", { type: "text/plain", lastModified: 42 });
                      const form = new FormData();
                      form.append("field", "value");
                      form.append("blob", blob, "blob.txt");
                      form.append("file", file);
                      const formBlob = form.get("blob");
                      const formFile = form.get("file");
                      const headers = new Headers({ "content-type": "text/plain" });
                      const request = new Request("https://example.invalid/core", {
                        method: "POST",
                        headers,
                        body: "payload"
                      });
                      const response = new Response("ok", {
                        status: 202,
                        headers: {
                          "x-core": "yes"
                        }
                      });
                      const [blobText, fileText, formBlobText, formFileText, requestText, responseText] = await Promise.all([
                        blob.text(),
                        file.text(),
                        formBlob.text(),
                        formFile.text(),
                        request.text(),
                        response.text()
                      ]);
                      let fetchCode = "";
                      let fetchReturnedPromise = false;
                      try {
                        const fetchResult = fetch("https://example.invalid/core-blocked");
                        fetchReturnedPromise = !!fetchResult && typeof fetchResult.then === "function";
                        await fetchResult;
                      } catch (error) {
                        fetchCode = error && error.code;
                      }
                      const locked = [
                        "Blob",
                        "File",
                        "FormData",
                        "Headers",
                        "Request",
                        "Response",
                        "fetch"
                      ].every((name) => {
                        const descriptor = Object.getOwnPropertyDescriptor(globalThis, name);
