    @Test
    fun legacyCoreBuiltinsExposeRestrictedWrappersAliasesAndShadowProtection() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-legacy-core-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create legacy core builtin test dir: $absolutePath" }
        }
        try {
            val querystringShadow = File(scriptDir, "node_modules/querystring/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val stringDecoderShadow = File(scriptDir, "node_modules/string_decoder/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val assertShadow = File(scriptDir, "node_modules/assert/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val punycodeShadow = File(scriptDir, "node_modules/punycode/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                """
                "nodejs";
                const querystring = require("querystring");
                const nodeQuerystring = require("node:querystring");
                const stringDecoder = require("string_decoder");
                const nodeStringDecoder = require("node:string_decoder");
                const assert = require("assert");
                const nodeAssert = require("node:assert");
                const punycode = require("punycode");
                const nodePunycode = require("node:punycode");
                const packagePunycode = require("punycode/");
                const packagePunycodeAgain = require("punycode/");
                const packagePunycodeResolved = require.resolve("punycode/");

                const encoded = querystring.stringify({ a: "1", b: "你好" });
                const parsed = querystring.parse("a=1&b=%E4%BD%A0%E5%A5%BD");
                const decoder = new stringDecoder.StringDecoder("utf8");
                const utf8 = Buffer.from("你好");
                const decoded = decoder.write(utf8.subarray(0, 1)) + decoder.write(utf8.subarray(1)) + decoder.end();
                const ascii = punycode.toASCII("mañana.com");
                const unicode = punycode.toUnicode(ascii);

                assert.ok(true);
                assert.equal("1", 1);
                assert.strictEqual(1, 1);
                assert.deepStrictEqual({ a: 1 }, { a: 1 });
                assert.throws(() => { throw new Error("assert-boom"); }, /assert-boom/);
                assert.doesNotThrow(() => {});
                const assertion = new assert.AssertionError({ message: "assertion" });

                console.log("legacy.querystring.same=" + (querystring === nodeQuerystring));
                console.log("legacy.querystring.shadow=" + (querystring.shadow === true));
                console.log("legacy.querystring.encoded=" + encoded.includes("a=1"));
                console.log("legacy.querystring.parsed=" + (parsed.b === "你好"));
                console.log("legacy.querystring.escape=" + (querystring.unescape(querystring.escape("x y")) === "x y"));
                console.log("legacy.querystring.hidden=" + [typeof querystring.decode, typeof querystring.encode].join(","));
                console.log("legacy.stringDecoder.same=" + (stringDecoder === nodeStringDecoder));
                console.log("legacy.stringDecoder.shadow=" + (stringDecoder.shadow === true));
                console.log("legacy.stringDecoder.decoded=" + decoded);
                console.log("legacy.stringDecoder.hidden=" + typeof stringDecoder.create);
                console.log("legacy.assert.same=" + (assert === nodeAssert));
                console.log("legacy.assert.shadow=" + (assert.shadow === true));
                console.log("legacy.assert.callable=" + (typeof assert));
                console.log("legacy.assert.error=" + (assertion instanceof Error));
                console.log("legacy.punycode.same=" + (punycode === nodePunycode));
                console.log("legacy.punycode.shadow=" + (punycode.shadow === true));
                console.log("legacy.punycode.package_root=" + (packagePunycode.shadow === true));
                console.log("legacy.punycode.package_cache=" + (packagePunycode === packagePunycodeAgain));
                console.log("legacy.punycode.package_resolve=" + packagePunycodeResolved.endsWith("/node_modules/punycode/index.js"));
                console.log("legacy.punycode.ascii=" + ascii.includes("xn--"));
                console.log("legacy.punycode.unicode=" + (unicode === "mañana.com"));
                console.log("legacy.punycode.ucs2=" + (typeof punycode.ucs2.decode));
                console.log("legacy.punycode.version=" + (typeof punycode.version));

                for (const name of ["child_process", "worker_threads"]) {
                  try {
                    require(name);
                    console.log("legacy.denied." + name + "=false");
                  } catch (error) {
                    console.log("legacy.denied." + name + "=" + error.message.includes(name));
                  }
                }
                try {
                  process.getBuiltinModule("querystring");
                  console.log("legacy.getBuiltinModule=false");
                } catch (error) {
                  console.log("legacy.getBuiltinModule=" + error.message.includes("disabled"));
                }
                """.trimIndent(),
                "<embedded-legacy-core-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(querystringShadow, stringDecoderShadow, assertShadow, punycodeShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("legacy.querystring.same=true"))
            assertTrue(result.stdout.contains("legacy.querystring.shadow=false"))
            assertTrue(result.stdout.contains("legacy.querystring.encoded=true"))
            assertTrue(result.stdout.contains("legacy.querystring.parsed=true"))
            assertTrue(result.stdout.contains("legacy.querystring.escape=true"))
            assertTrue(result.stdout.contains("legacy.querystring.hidden=undefined,undefined"))
            assertTrue(result.stdout.contains("legacy.stringDecoder.same=true"))
            assertTrue(result.stdout.contains("legacy.stringDecoder.shadow=false"))
            assertTrue(result.stdout.contains("legacy.stringDecoder.decoded=你好"))
            assertTrue(result.stdout.contains("legacy.stringDecoder.hidden=undefined"))
            assertTrue(result.stdout.contains("legacy.assert.same=true"))
            assertTrue(result.stdout.contains("legacy.assert.shadow=false"))
            assertTrue(result.stdout.contains("legacy.assert.callable=function"))
            assertTrue(result.stdout.contains("legacy.assert.error=true"))
            assertTrue(result.stdout.contains("legacy.punycode.same=true"))
            assertTrue(result.stdout.contains("legacy.punycode.shadow=false"))
            assertTrue(result.stdout.contains("legacy.punycode.package_root=true"))
            assertTrue(result.stdout.contains("legacy.punycode.package_cache=true"))
            assertTrue(result.stdout.contains("legacy.punycode.package_resolve=true"))
            assertTrue(result.stdout.contains("legacy.punycode.ascii=true"))
            assertTrue(result.stdout.contains("legacy.punycode.unicode=true"))
            assertTrue(result.stdout.contains("legacy.punycode.ucs2=function"))
            assertTrue(result.stdout.contains("legacy.punycode.version=string"))
            listOf("child_process", "worker_threads").forEach { name ->
                assertTrue(result.stdout.contains("legacy.denied.$name=true"))
            }
            assertTrue(result.stdout.contains("legacy.getBuiltinModule=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun pureJsNpmLegacyCoreSmokeUsesRestrictedBuiltinsTogether() {
        assumeEmbeddedScriptExecutionEnabled()

