        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const compose = require("pkg-legacy-core-compose-like");
                    const result = compose.run();
                    console.log("legacy.core.ok=" + result.ok);
                    console.log("legacy.core.query=" + result.query);
                    console.log("legacy.core.decoded=" + result.decoded);
                    console.log("legacy.core.domain=" + result.domain);
                    console.log("legacy.core.alias=" + result.alias);
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val compose = File(scriptDir, "node_modules/pkg-legacy-core-compose-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const query = require("pkg-querystring-like");
                    const decoder = require("pkg-string-decoder-like");
                    const assertion = require("pkg-assert-like");
                    const domain = require("pkg-punycode-like");
                    exports.run = function run() {
                      const queryResult = query.roundTrip({ a: "1", b: "你好" });
                      const decoded = decoder.decode(Buffer.from("你好"));
                      const assertOk = assertion.check({ a: 1 }, { a: 1 });
                      const domainResult = domain.convert("mañana.com");
                      return {
                        ok: queryResult.ok &&
                          decoded === "你好" &&
                          assertOk &&
                          domainResult.unicode === "mañana.com" &&
                          domainResult.alias,
                        query: queryResult.value,
                        decoded,
                        domain: domainResult.ascii,
                        alias: domainResult.alias
                      };
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val querystringLike = File(scriptDir, "node_modules/pkg-querystring-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const querystring = require("querystring");
                    const nodeQuerystring = require("node:querystring");
                    exports.roundTrip = function roundTrip(value) {
                      const text = querystring.stringify(value);
                      const parsed = nodeQuerystring.parse(text);
                      return {
                        ok: parsed.a === value.a && parsed.b === value.b && querystring === nodeQuerystring,
                        value: text
                      };
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val stringDecoderLike = File(scriptDir, "node_modules/pkg-string-decoder-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const { StringDecoder } = require("string_decoder");
                    exports.decode = function decode(buffer) {
                      const decoder = new StringDecoder("utf8");
                      return decoder.write(buffer.subarray(0, 1)) + decoder.write(buffer.subarray(1)) + decoder.end();
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val assertLike = File(scriptDir, "node_modules/pkg-assert-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const assert = require("assert");
                    exports.check = function check(left, right) {
                      assert.deepStrictEqual(left, right);
                      assert.throws(() => { throw new Error("expected"); }, /expected/);
                      return true;
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val punycodeLike = File(scriptDir, "node_modules/pkg-punycode-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const punycode = require("punycode");
                    const nodePunycode = require("node:punycode");
                    exports.convert = function convert(domain) {
                      const ascii = punycode.toASCII(domain);
                      return {
                        ascii,
                        unicode: nodePunycode.toUnicode(ascii),
                        alias: punycode === nodePunycode
                      };
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(compose, querystringLike, stringDecoderLike, assertLike, punycodeLike),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("legacy.core.ok=true"))
            assertTrue(result.stdout.contains("legacy.core.query="))
            assertTrue(result.stdout.contains("legacy.core.decoded=你好"))
            assertTrue(result.stdout.contains("legacy.core.domain=xn--"))
            assertTrue(result.stdout.contains("legacy.core.alias=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun pureJsNpmEventsTimersAndWarningsSmokeUsesPromiseDrain() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-npm-events-timers-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create npm events/timers test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const compose = require("pkg-events-timers-compose-like");
                    compose.run().then((result) => {
                      console.log("events.timers.ok=" + result.ok);
                      console.log("events.timers.event=" + result.eventValue);
                      console.log("events.timers.once=" + result.onceValue);
                      console.log("events.timers.iterator=" + result.iteratorValue);
                      console.log("events.timers.error=" + result.errorValue);
                      console.log("events.timers.abort=" + result.abortValue);
                      console.log("events.timers.helpers=" + result.helpers);
                      console.log("events.timers.scheduled=" + result.scheduled);
                      console.log("events.timers.warning=" + result.warning);
                      console.log("events.timers.alias=" + result.alias);
                    });
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val compose = File(scriptDir, "node_modules/pkg-events-timers-compose-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const eventEmitter = require("pkg-event-emitter-like");
                    const onceEvent = require("pkg-once-event-like");
                    const iteratorEvent = require("pkg-event-iterator-like");
                    const errorEvent = require("pkg-event-error-like");
                    const scheduler = require("pkg-timers-scheduler-like");
                    const warning = require("pkg-warning-like");
                    exports.run = function run() {
                      const eventResult = eventEmitter.run();
                      return Promise.all([
                        onceEvent.wait(),
                        iteratorEvent.collect(),
                        errorEvent.run(),
                        scheduler.run(),
                        warning.emit()
                      ]).then((results) => {
                        return {
                          ok: eventResult.ok && results[0].ok && results[1].ok && results[2].ok && results[3].ok && results[4].ok,
                          eventValue: eventResult.value,
                          onceValue: results[0].value,
                          iteratorValue: results[1].value,
                          errorValue: results[2].value,
                          abortValue: results[2].abort,
                          helpers: eventResult.helpers,
                          scheduled: results[3].value,
                          warning: results[4].value,
                          alias: eventResult.alias && results[3].alias
                        };
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val eventEmitter = File(scriptDir, "node_modules/pkg-event-emitter-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const events = require("events");
                    const nodeEvents = require("node:events");
                    exports.run = function run() {
                      const emitter = new events.EventEmitter();
                      let value = 0;
                      function inc(amount) {
                        value += amount;
                      }
                      emitter.on("inc", inc);
                      emitter.emit("inc", 1);
                      emitter.removeListener("inc", inc);
                      emitter.emit("inc", 100);
                      emitter.once("once", () => {
                        value += 10;
                      });
                      emitter.emit("once");
                      emitter.emit("once");
                      return {
                        ok: value === 11 &&
                          emitter.listenerCount("inc") === 0 &&
                          emitter.listeners("inc").length === 0 &&
                          events.getEventListeners(emitter, "inc").length === 0 &&
                          events.listenerCount(emitter, "inc") === 0 &&
                          typeof events.once === "function" &&
                          typeof events.on === "function" &&
                          typeof events.getEventListeners === "function" &&
                          typeof events.getMaxListeners === "function" &&
                          typeof events.setMaxListeners === "function" &&
                          typeof events.addAbortListener === "function" &&
                          typeof events.errorMonitor === "symbol" &&
                          typeof events.captureRejectionSymbol === "symbol" &&
                          typeof events.EventEmitterAsyncResource === "undefined" &&
                          typeof events.defaultMaxListeners === "number" &&
                          Object.isFrozen(events),
                        value,
                        helpers: [
                          typeof events.getEventListeners,
                          typeof events.getMaxListeners,
                          typeof events.setMaxListeners,
                          typeof events.addAbortListener,
                          typeof events.errorMonitor,
                          typeof events.captureRejectionSymbol,
                          typeof events.EventEmitterAsyncResource
                        ].join(","),
                        alias: events === nodeEvents && events === events.EventEmitter
                      };
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val onceEvent = File(scriptDir, "node_modules/pkg-once-event-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const events = require("events");
                    const timers = require("timers");
                    exports.wait = function wait() {
                      const emitter = new events.EventEmitter();
                      const ready = events.once(emitter, "ready").then((args) => {
                        return {
                          ok: args[0] === "once-ready",
                          value: args[0]
                        };
                      });
                      timers.setImmediate(() => {
                        emitter.emit("ready", "once-ready");
                      });
                      return ready;
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val iteratorEvent = File(scriptDir, "node_modules/pkg-event-iterator-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const events = require("events");
                    const timers = require("timers");
                    exports.collect = function collect() {
                      return (async () => {
                        const emitter = new events.EventEmitter();
                        const values = [];
                        const iterator = events.on(emitter, "item");
                        timers.setImmediate(() => {
                          emitter.emit("item", "one");
                          emitter.emit("item", "two");
                        });
                        for await (const args of iterator) {
                          values.push(args[0]);
                          if (values.length === 2) break;
                        }
                        return {
                          ok: values.join(",") === "one,two" && emitter.listenerCount("item") === 0,
                          value: values.join(",")
                        };
                      })();
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val errorEvent = File(scriptDir, "node_modules/pkg-event-error-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const events = require("events");
                    const timers = require("timers");
                    exports.run = function run() {
                      const monitored = [];
                      const emitter = new events.EventEmitter();
                      emitter.on(events.errorMonitor, (error) => {
                        monitored.push("monitor:" + error.message);
                      });
                      emitter.on("error", (error) => {
                        monitored.push("handler:" + error.message);
                      });
                      emitter.emit("error", new Error("compose error"));
                      const onceEmitter = new events.EventEmitter();
                      const onceRejected = events.once(onceEmitter, "ready").then(
                        () => false,
                        (error) => error.message === "compose once error"
                      );
                      timers.setImmediate(() => {
                        onceEmitter.emit("error", new Error("compose once error"));
                      });
                      let abortSeen = 0;
                      const abortSignal = {
                        aborted: false,
                        listener: null,
                        removed: false,
                        addEventListener(name, listener) {
                          if (name === "abort") this.listener = listener;
                        },
                        removeEventListener(name, listener) {
                          if (name === "abort" && this.listener === listener) this.removed = true;
                        }
                      };
                      const disposable = events.addAbortListener(abortSignal, () => {
                        abortSeen += 1;
                      });
                      abortSignal.aborted = true;
                      abortSignal.listener.call(abortSignal, { type: "abort" });
                      if (disposable && typeof disposable[Symbol.dispose] === "function") {
                        disposable[Symbol.dispose]();
                      }
                      return onceRejected.then((rejected) => {
                        return {
                          ok: rejected === true &&
                            abortSeen === 1 &&
                            abortSignal.removed === true &&
                            monitored.join("|") === "monitor:compose error|handler:compose error",
                          value: monitored.join("|") + "|" + rejected,
                          abort: abortSeen
                        };
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val scheduler = File(scriptDir, "node_modules/pkg-timers-scheduler-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const timers = require("timers");
                    const nodeTimers = require("node:timers");
                    const timerPromises = require("timers/promises");
                    const nodeTimerPromises = require("node:timers/promises");
                    exports.run = async function run() {
                      let shouldStayCleared = true;
                      let ticks = 0;
                      await new Promise((resolve) => {
                        const timeout = timers.setTimeout(() => {
                          shouldStayCleared = false;
                        }, 0);
                        timers.clearTimeout(timeout);
                        const interval = timers.setInterval(() => {
                          ticks += 1;
                          if (ticks === 2) {
                            timers.clearInterval(interval);
                            timers.setImmediate(() => {
                              resolve();
                            });
                          }
                        }, 1);
                      });
                      const promiseTimeout = await timerPromises.setTimeout(1, "promise-timeout");
                      const promiseImmediate = await timerPromises.setImmediate("promise-immediate");
                      await timerPromises.scheduler.wait(1);
                      await timerPromises.scheduler.yield();
                      const intervalValues = [];
                      for await (const value of timerPromises.setInterval(1, "promise-interval")) {
                        intervalValues.push(value);
                        if (intervalValues.length === 2) break;
                      }
                      return {
                        ok: shouldStayCleared &&
                          ticks === 2 &&
                          typeof timers.promises === "undefined" &&
                          promiseTimeout === "promise-timeout" &&
                          promiseImmediate === "promise-immediate" &&
                          intervalValues.join(",") === "promise-interval,promise-interval" &&
                          Object.isFrozen(timerPromises) &&
                          Object.isFrozen(timerPromises.scheduler),
                        value: "ticks:" + ticks + "|" + promiseTimeout + "|" + promiseImmediate + "|" + intervalValues.join(","),
                        alias: timers === nodeTimers && timerPromises === nodeTimerPromises
                      };
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val warning = File(scriptDir, "node_modules/pkg-warning-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    exports.emit = function emit() {
                      return new Promise((resolve) => {
                        const seen = [];
                        function listener(warning) {
                          seen.push(
                            warning.name +
                              "/" +
                              warning.code +
                              "/" +
                              warning.message.includes("compose warning")
                          );
                        }
                        process.on("warning", listener);
                        process.emitWarning("compose warning", "DeprecationWarning", "AUTOJS6_COMPOSE");
                        process.nextTick(() => {
                          process.off("warning", listener);
                        });
                        setImmediate(() => {
                          resolve({
                            ok: seen.length === 1 && seen[0] === "DeprecationWarning/AUTOJS6_COMPOSE/true",
                            value: seen.join("|")
                          });
                        });
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val eventsShadow = File(scriptDir, "node_modules/events/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val timersShadow = File(scriptDir, "node_modules/timers/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(
                    compose,
                    eventEmitter,
                    onceEvent,
                    iteratorEvent,
                    errorEvent,
                    scheduler,
                    warning,
                    eventsShadow,
                    timersShadow,
                ),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("events.timers.ok=true"))
            assertTrue(result.stdout.contains("events.timers.event=11"))
            assertTrue(result.stdout.contains("events.timers.once=once-ready"))
            assertTrue(result.stdout.contains("events.timers.iterator=one,two"))
            assertTrue(result.stdout.contains("events.timers.error=monitor:compose error|handler:compose error|true"))
            assertTrue(result.stdout.contains("events.timers.abort=1"))
            assertTrue(result.stdout.contains("events.timers.helpers=function,function,function,function,symbol,symbol,undefined"))
            assertTrue(result.stdout.contains("events.timers.scheduled=ticks:2|promise-timeout|promise-immediate|promise-interval,promise-interval"))
            assertTrue(result.stdout.contains("events.timers.warning=DeprecationWarning/AUTOJS6_COMPOSE/true"))
            assertTrue(result.stdout.contains("events.timers.alias=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun pureJsNpmStreamSmokeUsesMemoryStreamsAndPromiseDrain() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-npm-stream-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create npm stream test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const compose = require("pkg-stream-compose-like");
                    compose.run().then((result) => {
                      console.log("stream.npm.ok=" + result.ok);
                      console.log("stream.npm.readable=" + result.readable);
                      console.log("stream.npm.pass=" + result.pass);
                      console.log("stream.npm.writable=" + result.writable);
                      console.log("stream.npm.file=" + result.file);
                      console.log("stream.npm.pipeline=" + result.pipeline);
                      console.log("stream.npm.finished=" + result.finished);
                      console.log("stream.npm.helper=" + result.helper);
                      console.log("stream.npm.error=" + result.error);
                      console.log("stream.npm.state=" + result.state);
                      console.log("stream.npm.helpers=" + result.helpers);
                      console.log("stream.npm.event=" + result.event);
                      console.log("stream.npm.alias=" + result.alias);
                    });
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val compose = File(scriptDir, "node_modules/pkg-stream-compose-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const events = require("events");
                    const stream = require("stream");
                    const readable = require("pkg-readable-like");
                    const passThrough = require("pkg-pass-through-like");
                    const collector = require("pkg-writable-collector-like");
                    const fileStream = require("pkg-file-stream-like");
                    const pump = require("pkg-pump-like");
                    const endOfStream = require("pkg-end-of-stream-like");
                    const helper = require("pkg-stream-helper-like");
                    function collectWithPipeline(chunks) {
                      return new Promise((resolve, reject) => {
                        let collected = "";
                        const writable = new stream.Writable({
                          write(chunk, encoding, callback) {
                            collected += chunk.toString();
                            callback();
                          }
                        });
                        stream.pipeline(stream.Readable.from(chunks), writable, (error) => {
                          if (error) {
                            reject(error);
                            return;
                          }
                          resolve(collected);
                        });
                      });
                    }
                    exports.run = function run() {
                      const emitter = new events.EventEmitter();
                      let eventValue = "";
                      emitter.once("done", (value) => {
                        eventValue = value;
                      });
                      return Promise.all([
                        readable.read(),
                        passThrough.pass("pass"),
                        collector.collect([Buffer.from("w"), "rite"]),
                        fileStream.roundTrip("file-stream"),
                        collectWithPipeline(["pipe", Buffer.from("line")]),
                        pump.collect(["pu", Buffer.from("mp")]),
                        endOfStream.wait(stream.Readable.from(["end"])),
                        pump.fail(),
                        endOfStream.waitForError(new stream.PassThrough()),
                        helper.run()
                      ]).then((results) => {
                        emitter.emit("done", "stream-event");
                        return {
                          ok: results[0] === "readable" &&
                            results[1] === "pass-through" &&
                            results[2] === "write" &&
                            results[3] === "file-stream" &&
                            results[4] === "pipeline" &&
                            results[5].text === "pump" &&
                            results[5].state === "true/true/true" &&
                            results[6] === "finished" &&
                            results[7].message === "pump boom" &&
                            results[7].errored === true &&
                            results[7].destroyed === true &&
                            results[8] === "eos boom" &&
                            results[9].ok === true &&
                            eventValue === "stream-event" &&
                            stream === require("node:stream") &&
                            typeof stream.pipeline === "function" &&
                            typeof stream.finished === "function" &&
                            typeof stream.addAbortSignal === "function" &&
                            typeof stream.compose === "function" &&
                            typeof stream.duplexPair === "function" &&
                            typeof stream.isReadable === "function" &&
                            typeof stream.isWritable === "function" &&
                            typeof stream.isErrored === "function" &&
                            typeof stream.isDestroyed === "function" &&
                            typeof stream.isDisturbed === "function" &&
                            typeof stream.promises === "undefined",
                          readable: results[0],
                          pass: results[1],
                          writable: results[2],
                          file: results[3],
                          pipeline: results[4],
                          finished: results[6],
                          helper: results[9].value,
                          error: [results[7].message, results[8]].join("|"),
                          state: [results[5].state, results[7].errored, results[7].destroyed].join(","),
                          helpers: [
                            typeof stream.pipeline,
                            typeof stream.finished,
                            typeof stream.addAbortSignal,
                            typeof stream.compose,
                            typeof stream.duplexPair,
                            typeof stream.isReadable,
                            typeof stream.isWritable,
                            typeof stream.isErrored,
                            typeof stream.isDestroyed,
                            typeof stream.isDisturbed,
                            typeof stream.promises
                          ].join(","),
                          event: eventValue,
                          alias: stream === require("node:stream")
                        };
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val fileStream = File(scriptDir, "node_modules/pkg-file-stream-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fs = require("fs");
                    exports.roundTrip = function roundTrip(text) {
                      return new Promise((resolve, reject) => {
                        fs.mkdirSync("./stream-files", { recursive: true });
                        const input = "./stream-files/input.txt";
                        const output = "./stream-files/output.txt";
                        fs.writeFileSync(input, text, "utf8");
                        const readable = fs.createReadStream(input, { encoding: "utf8" });
                        const writable = fs.createWriteStream(output, { encoding: "utf8" });
                        readable.on("error", reject);
                        writable.on("error", reject);
                        writable.on("finish", () => {
                          try {
                            resolve(fs.readFileSync(output, "utf8"));
                          } catch (error) {
                            reject(error);
                          }
                        });
                        readable.pipe(writable);
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val pump = File(scriptDir, "node_modules/pkg-pump-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const stream = require("stream");
                    exports.collect = function collect(chunks) {
                      return new Promise((resolve, reject) => {
                        let collected = "";
                        const upper = new stream.Transform({
                          transform(chunk, encoding, callback) {
                            callback(null, chunk.toString().toUpperCase());
                          }
                        });
                        const writable = new stream.Writable({
                          write(chunk, encoding, callback) {
                            collected += chunk.toString().toLowerCase();
                            callback();
                          }
                        });
                        stream.pipeline(stream.Readable.from(chunks), upper, writable, (error) => {
                          if (error) {
                            reject(error);
                            return;
                          }
                          resolve({
                            text: collected,
                            state: [
                              stream.isReadable(upper) === false,
                              stream.isWritable(upper) === false,
                              stream.isDestroyed(upper) === true
                            ].join("/")
                          });
                        });
                      });
                    };
                    exports.fail = function fail() {
                      return new Promise((resolve) => {
                        const failed = new stream.Transform({
                          transform(chunk, encoding, callback) {
                            callback(new Error("pump boom"));
                          }
                        });
                        const writable = new stream.Writable({
                          write(chunk, encoding, callback) {
                            callback();
                          }
                        });
                        stream.pipeline(stream.Readable.from(["x"]), failed, writable, (error) => {
                          resolve({
                            message: error && error.message,
                            errored: stream.isErrored(failed),
                            destroyed: stream.isDestroyed(failed)
                          });
                        });
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val endOfStream = File(scriptDir, "node_modules/pkg-end-of-stream-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const stream = require("stream");
                    exports.wait = function wait(readable) {
                      return new Promise((resolve, reject) => {
                        stream.finished(readable, (error) => {
                          if (error) {
                            reject(error);
                            return;
                          }
                          resolve(stream.isDisturbed(readable) ? "finished" : "not-finished");
                        });
                        readable.resume();
                      });
                    };
                    exports.waitForError = function waitForError(target) {
                      return new Promise((resolve) => {
                        stream.finished(target, (error) => {
                          resolve(error && error.message);
                        });
                        target.destroy(new Error("eos boom"));
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val readable = File(scriptDir, "node_modules/pkg-readable-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const { Readable } = require("stream");
                    exports.read = function read() {
                      return new Promise((resolve) => {
                        const chunks = [];
                        const readable = Readable.from([Buffer.from("read"), "able"]);
                        readable.on("data", (chunk) => {
                          chunks.push(chunk.toString());
                        });
                        readable.on("end", () => {
                          resolve(chunks.join(""));
                        });
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val passThrough = File(scriptDir, "node_modules/pkg-pass-through-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const { PassThrough, Transform } = require("stream");
                    exports.pass = function pass(prefix) {
                      return new Promise((resolve) => {
                        const upper = new Transform({
                          transform(chunk, encoding, callback) {
                            callback(null, chunk.toString().toUpperCase());
                          }
                        });
                        const passThrough = new PassThrough();
                        let output = "";
                        upper.on("data", (chunk) => {
                          output += chunk.toString().toLowerCase();
                        });
                        upper.on("end", () => {
                          resolve(prefix + "-" + output);
                        });
                        passThrough.pipe(upper);
                        passThrough.write("th");
                        passThrough.end(Buffer.from("rough"));
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val collector = File(scriptDir, "node_modules/pkg-writable-collector-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const { Readable, Writable } = require("stream");
                    exports.collect = function collect(chunks) {
                      return new Promise((resolve) => {
                        let collected = "";
                        const writable = new Writable({
                          write(chunk, encoding, callback) {
                            collected += chunk.toString();
                            callback();
                          }
                        });
                        writable.on("finish", () => {
                          resolve(collected);
                        });
                        Readable.from(chunks).pipe(writable);
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val helper = File(scriptDir, "node_modules/pkg-stream-helper-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const stream = require("stream");
                    function composeValue() {
                      return new Promise((resolve, reject) => {
                        let output = "";
                        const upper = new stream.Transform({
                          transform(chunk, encoding, callback) {
                            callback(null, chunk.toString().toUpperCase());
                          }
                        });
                        const suffix = new stream.Transform({
                          transform(chunk, encoding, callback) {
                            callback(null, chunk.toString() + "?");
                          }
                        });
                        const composed = stream.compose(upper, suffix);
                        composed.on("data", (chunk) => {
                          output += chunk.toString();
                        });
                        composed.on("error", reject);
                        composed.on("end", () => {
                          resolve(output);
                        });
                        composed.write("ok");
                        composed.end();
                      });
                    }
                    function duplexValue() {
                      return new Promise((resolve, reject) => {
                        const pair = stream.duplexPair();
                        let left = "";
                        let right = "";
                        let ended = 0;
                        function done() {
                          ended += 1;
                          if (ended === 2) {
                            resolve(left + "/" + right);
                          }
                        }
                        pair[0].on("data", (chunk) => { left += chunk.toString(); });
                        pair[1].on("data", (chunk) => { right += chunk.toString(); });
                        pair[0].on("error", reject);
                        pair[1].on("error", reject);
                        pair[0].on("end", done);
                        pair[1].on("end", done);
                        pair[1].end("right");
                        pair[0].end("left");
                      });
                    }
                    function abortValue() {
                      return new Promise((resolve) => {
                        const pass = new stream.PassThrough();
                        const controller = new AbortController();
                        const returned = stream.addAbortSignal(controller.signal, pass);
                        pass.on("error", (error) => {
                          resolve(returned === pass && error.code === "ABORT_ERR" && stream.isErrored(pass));
                        });
                        controller.abort();
                      });
                    }
                    exports.run = async function run() {
                      const values = [await composeValue(), await duplexValue(), await abortValue()];
                      return {
                        ok: values[0] === "OK?" && values[1] === "right/left" && values[2] === true,
                        value: values.join("|")
                      };
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val streamShadow = File(scriptDir, "node_modules/stream/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(compose, pump, endOfStream, readable, passThrough, collector, fileStream, helper, streamShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("stream.npm.ok=true"))
            assertTrue(result.stdout.contains("stream.npm.readable=readable"))
            assertTrue(result.stdout.contains("stream.npm.pass=pass-through"))
            assertTrue(result.stdout.contains("stream.npm.writable=write"))
            assertTrue(result.stdout.contains("stream.npm.file=file-stream"))
            assertTrue(result.stdout.contains("stream.npm.pipeline=pipeline"))
            assertTrue(result.stdout.contains("stream.npm.finished=finished"))
            assertTrue(result.stdout.contains("stream.npm.helper=OK?|right/left|true"))
            assertTrue(result.stdout.contains("stream.npm.error=pump boom|eos boom"))
            assertTrue(result.stdout.contains("stream.npm.state=true/true/true,true,true"))
            assertTrue(result.stdout.contains("stream.npm.helpers=function,function,function,function,function,function,function,function,function,function,undefined"))
            assertTrue(result.stdout.contains("stream.npm.event=stream-event"))
            assertTrue(result.stdout.contains("stream.npm.alias=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun pureJsNpmReadlineSmokeUsesCallbackPromiseAndFileHandleLineReaders() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-npm-readline-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create npm readline test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const compose = require("pkg-readline-compose-like");
                    return compose.run().then((result) => {
                      console.log("readline.npm.ok=" + result.ok);
                      console.log("readline.npm.callback=" + result.callback);
                      console.log("readline.npm.promise=" + result.promise);
                      console.log("readline.npm.filehandle=" + result.filehandle);
                      console.log("readline.npm.question=" + result.question);
                      console.log("readline.npm.abort=" + result.abort);
                      console.log("readline.npm.resolve=" + result.resolve);
                      console.log("readline.npm.surface=" + result.surface);
                      console.log("readline.npm.alias=" + result.alias);
                    });
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val compose = File(scriptDir, "node_modules/pkg-readline-compose-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fs = require("fs");
                    const readline = require("readline");
                    const readlinePromises = require("readline/promises");
                    const callbackReader = require("pkg-readline-callback-reader-like");
                    const promiseReader = require("pkg-readline-promise-reader-like");
                    const questioner = require("pkg-readline-question-like");

                    exports.run = async function run() {
                      fs.mkdirSync("./readline-npm", { recursive: true });
                      const input = "./readline-npm/input.txt";
                      fs.writeFileSync(input, "one\ntwo\nthree\n", "utf8");
                      const callbackLines = await callbackReader.read(input);
                      const promiseLines = await promiseReader.read(input);
                      const fileHandleLines = await promiseReader.readHandle(input);
                      const question = await questioner.ask("node-answer");
                      const abort = await questioner.abort();
                      const resolve = [
                        require.resolve("readline"),
                        require.resolve("node:readline"),
                        require.resolve("readline/promises"),
                        require.resolve("node:readline/promises")
                      ].join("|");
                      const surface = [
                        typeof readline.createInterface,
                        typeof readline.clearLine,
                        typeof readline.promises,
                        typeof readlinePromises.createInterface,
                        typeof readlinePromises.Interface,
                        typeof readlinePromises.Readline
                      ].join(",");
                      const alias = readline === require("node:readline") &&
                        readlinePromises === require("node:readline/promises") &&
                        readline.shadow !== true &&
                        readlinePromises.shadow !== true;
                      return {
                        ok: callbackLines === "one|two|three" &&
                          promiseLines === "one|two|three" &&
                          fileHandleLines === "one|two|three|true" &&
                          question === "node-answer|Prompt: " &&
                          abort === "ABORT_ERR" &&
                          resolve === "readline|readline|readline/promises|readline/promises" &&
                          surface === "function,function,undefined,function,function,function" &&
                          alias,
                        callback: callbackLines,
                        promise: promiseLines,
                        filehandle: fileHandleLines,
                        question,
                        abort,
                        resolve,
                        surface,
                        alias
                      };
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val callbackReader = File(scriptDir, "node_modules/pkg-readline-callback-reader-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fs = require("fs");
                    const readline = require("readline");
                    exports.read = async function read(file) {
                      const reader = readline.createInterface({
                        input: fs.createReadStream(file, { encoding: "utf8" }),
                        crlfDelay: Infinity
                      });
                      const lines = [];
                      for await (const line of reader) {
                        lines.push(line);
                      }
                      return lines.join("|");
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val promiseReader = File(scriptDir, "node_modules/pkg-readline-promise-reader-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fs = require("fs");
                    const fsp = require("fs/promises");
                    const readlinePromises = require("readline/promises");
                    async function collect(iterable) {
                      const lines = [];
                      for await (const line of iterable) {
                        lines.push(line);
                      }
                      return lines.join("|");
                    }
                    exports.read = function read(file) {
                      return collect(readlinePromises.createInterface({
                        input: fs.createReadStream(file, { encoding: "utf8" }),
                        crlfDelay: Infinity
                      }));
                    };
                    exports.readHandle = async function readHandle(file) {
                      const handle = await fsp.open(file, "r");
                      try {
                        const text = await collect(handle.readLines({
                          encoding: "utf8",
                          autoClose: false
                        }));
                        return text + "|" + (typeof handle.fd === "number" && handle.fd >= 0);
                      } finally {
                        await handle.close();
                      }
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val questioner = File(scriptDir, "node_modules/pkg-readline-question-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const { PassThrough } = require("stream");
                    const readlinePromises = require("readline/promises");
                    exports.ask = async function ask(answer) {
                      const input = new PassThrough();
                      const output = new PassThrough();
                      let prompt = "";
                      output.on("data", (chunk) => {
                        prompt += chunk.toString("utf8");
                      });
                      const reader = readlinePromises.createInterface({
                        input,
                        output,
                        terminal: false
                      });
                      const pending = reader.question("Prompt: ");
                      input.end(answer + "\n");
                      const value = await pending;
                      reader.close();
                      return value + "|" + prompt;
                    };
                    exports.abort = async function abort() {
                      const input = new PassThrough();
                      const output = new PassThrough();
                      output.resume();
                      const reader = readlinePromises.createInterface({
                        input,
                        output,
                        terminal: false
                      });
                      const controller = new AbortController();
                      const pending = reader.question("Abort: ", {
                        signal: controller.signal
                      }).then(
                        () => "resolved",
                        (error) => error && error.code
                      );
                      controller.abort();
                      const code = await pending;
                      reader.close();
                      return code;
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val readlineShadow = File(scriptDir, "node_modules/readline/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val readlinePromisesShadow = File(scriptDir, "node_modules/readline/promises.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(
                    compose,
                    callbackReader,
                    promiseReader,
                    questioner,
                    readlineShadow,
                    readlinePromisesShadow,
                ),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("readline.npm.ok=true"))
            assertTrue(result.stdout.contains("readline.npm.callback=one|two|three"))
            assertTrue(result.stdout.contains("readline.npm.promise=one|two|three"))
            assertTrue(result.stdout.contains("readline.npm.filehandle=one|two|three|true"))
            assertTrue(result.stdout.contains("readline.npm.question=node-answer|Prompt: "))
            assertTrue(result.stdout.contains("readline.npm.abort=ABORT_ERR"))
            assertTrue(result.stdout.contains("readline.npm.resolve=readline|readline|readline/promises|readline/promises"))
            assertTrue(result.stdout.contains("readline.npm.surface=function,function,undefined,function,function,function"))
            assertTrue(result.stdout.contains("readline.npm.alias=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun pureJsNpmZlibSmokeUsesLimitedSyncCompression() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-npm-zlib-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create npm zlib test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const compose = require("pkg-zlib-compose-like");
                    const run = compose.run().then((result) => {
                      console.log("zlib.npm.ok=" + result.ok);
                      console.log("zlib.npm.gzip=" + result.gzip);
                      console.log("zlib.npm.deflate=" + result.deflate);
                      console.log("zlib.npm.raw=" + result.raw);
                      console.log("zlib.npm.brotli=" + result.brotli);
                      console.log("zlib.npm.stream=" + result.stream);
                      console.log("zlib.npm.promisify=" + result.promisify);
                      console.log("zlib.npm.json=" + result.json);
                      console.log("zlib.npm.constants=" + result.constants);
                      console.log("zlib.npm.alias=" + result.alias);
                    });
                    console.log("zlib.npm.scheduled=true");
                    return run;
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val compose = File(scriptDir, "node_modules/pkg-zlib-compose-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const gzip = require("pkg-zlib-gzip-like");
                    const deflate = require("pkg-zlib-deflate-like");
                    const raw = require("pkg-zlib-raw-like");
                    const brotli = require("pkg-zlib-brotli-like");
                    const streamLike = require("pkg-zlib-stream-like");
                    const compressedJson = require("pkg-compressed-json-like");
                    const zlib = require("zlib");
                    const { promisify } = require("util");
                    exports.run = async function run() {
                      const payload = { name: "autojs6", ok: true, count: 3 };
                      const packed = compressedJson.pack(payload);
                      const unpacked = compressedJson.unpack(packed);
                      const gzipValue = gzip.roundTrip("gzip-value");
                      const deflateValue = deflate.roundTrip(Buffer.from("deflate-value"));
                      const rawValue = raw.roundTrip(Buffer.from("raw-value"));
                      const brotliValue = await brotli.roundTrip("brotli-value");
                      const streamValue = await streamLike.roundTrip("stream-value");
                      const promisifiedGzip = await promisify(zlib.gzip)(Buffer.from("promisify-gzip"));
                      const promisifiedRaw = await promisify(zlib.deflateRaw)(Buffer.from("promisify-raw"));
                      return {
                        ok: gzipValue === "gzip-value" &&
                          deflateValue === "deflate-value" &&
                          rawValue === "raw-value" &&
                          brotliValue === "brotli-value" &&
                          streamValue === "stream-value/stream-raw/stream-brotli" &&
                          zlib.gunzipSync(promisifiedGzip).toString("utf8") === "promisify-gzip" &&
                          zlib.inflateRawSync(promisifiedRaw).toString("utf8") === "promisify-raw" &&
                          unpacked.name === payload.name &&
                          unpacked.ok === true &&
                          unpacked.count === payload.count &&
                          zlib === require("node:zlib") &&
                          Object.isFrozen(zlib.constants) &&
                          typeof zlib.constants.BROTLI_PARAM_QUALITY === "number" &&
                          typeof zlib.brotliCompressSync === "function" &&
                          typeof zlib.gzip === "function" &&
                          typeof zlib.brotliCompress === "function" &&
                          typeof zlib.createGzip === "function",
                        gzip: gzipValue,
                        deflate: deflateValue,
                        raw: rawValue,
                        brotli: brotliValue,
                        stream: streamValue,
                        promisify: [
                          zlib.gunzipSync(promisifiedGzip).toString("utf8"),
                          zlib.inflateRawSync(promisifiedRaw).toString("utf8")
                        ].join("/"),
                        json: unpacked.name + "/" + unpacked.count,
                        constants: Object.isFrozen(zlib.constants) + "/" + typeof zlib.constants.BROTLI_PARAM_QUALITY,
                        alias: zlib === require("node:zlib")
                      };
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val gzipLike = File(scriptDir, "node_modules/pkg-zlib-gzip-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const zlib = require("zlib");
                    exports.roundTrip = function roundTrip(value) {
                      const compressed = zlib.gzipSync(Buffer.from(String(value), "utf8"));
                      return zlib.gunzipSync(compressed).toString("utf8");
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val deflateLike = File(scriptDir, "node_modules/pkg-zlib-deflate-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const zlib = require("node:zlib");
                    exports.roundTrip = function roundTrip(value) {
                      const compressed = zlib.deflateSync(value);
                      return zlib.inflateSync(compressed).toString("utf8");
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val rawLike = File(scriptDir, "node_modules/pkg-zlib-raw-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const zlib = require("node:zlib");
                    exports.roundTrip = function roundTrip(value) {
                      const compressed = zlib.deflateRawSync(value);
                      return zlib.inflateRawSync(compressed).toString("utf8");
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val brotliLike = File(scriptDir, "node_modules/pkg-zlib-brotli-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const zlib = require("zlib");
                    exports.roundTrip = function roundTrip(value) {
                      return new Promise((resolve, reject) => {
                        zlib.brotliCompress(Buffer.from(String(value), "utf8"), {
                          params: {
                            [zlib.constants.BROTLI_PARAM_QUALITY]: 1
                          }
                        }, (error, compressed) => {
                          if (error) {
                            reject(error);
                            return;
                          }
                          zlib.brotliDecompress(compressed, (decompressError, plain) => {
                            if (decompressError) reject(decompressError);
                            else resolve(plain.toString("utf8"));
                          });
                        });
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val streamLike = File(scriptDir, "node_modules/pkg-zlib-stream-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const zlib = require("zlib");
                    const stream = require("stream");
                    const { pipeline } = require("stream/promises");

                    async function collect(chunks, transforms) {
                      const values = [];
                      const writable = new stream.Writable({
                        write(chunk, encoding, callback) {
                          values.push(Buffer.from(chunk));
                          callback();
                        }
                      });
                      await pipeline(
                        stream.Readable.from(chunks),
                        ...transforms,
                        writable
                      );
                      return Buffer.concat(values).toString("utf8");
                    }

                    exports.roundTrip = async function roundTrip(value) {
                      const gzip = await collect(
                        [Buffer.from(String(value), "utf8")],
                        [zlib.createGzip(), zlib.createGunzip()]
                      );
                      const raw = await collect(
                        [Buffer.from("stream-raw")],
                        [zlib.createDeflateRaw(), zlib.createInflateRaw()]
                      );
                      const brotli = await collect(
                        [Buffer.from("stream-brotli")],
                        [
                          zlib.createBrotliCompress({
                            params: {
                              [zlib.constants.BROTLI_PARAM_QUALITY]: 1
                            }
                          }),
                          zlib.createBrotliDecompress()
                        ]
                      );
                      return [gzip, raw, brotli].join("/");
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val compressedJsonLike = File(scriptDir, "node_modules/pkg-compressed-json-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const zlib = require("zlib");
                    exports.pack = function pack(value) {
                      return zlib.gzipSync(Buffer.from(JSON.stringify(value), "utf8"));
                    };
                    exports.unpack = function unpack(buffer) {
                      return JSON.parse(zlib.gunzipSync(buffer).toString("utf8"));
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val zlibShadow = File(scriptDir, "node_modules/zlib/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(compose, gzipLike, deflateLike, rawLike, brotliLike, streamLike, compressedJsonLike, zlibShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertOutputOrder(result.stdout, "zlib.npm.scheduled=true", "zlib.npm.ok=true")
            assertTrue(result.stdout.contains("zlib.npm.ok=true"))
            assertTrue(result.stdout.contains("zlib.npm.gzip=gzip-value"))
            assertTrue(result.stdout.contains("zlib.npm.deflate=deflate-value"))
            assertTrue(result.stdout.contains("zlib.npm.raw=raw-value"))
            assertTrue(result.stdout.contains("zlib.npm.brotli=brotli-value"))
            assertTrue(result.stdout.contains("zlib.npm.stream=stream-value/stream-raw/stream-brotli"))
            assertTrue(result.stdout.contains("zlib.npm.promisify=promisify-gzip/promisify-raw"))
            assertTrue(result.stdout.contains("zlib.npm.json=autojs6/3"))
            assertTrue(result.stdout.contains("zlib.npm.constants=true/number"))
            assertTrue(result.stdout.contains("zlib.npm.alias=true"))
            assertEquals(0, result.pendingZlibCallbacks ?: -1)
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun explicitDeniedBuiltinsHaveStableErrorCodeAndResolveCannotBypass() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-deny-hardening-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create deny hardening test dir: $absolutePath" }
        }
        try {
            val httpShadow = File(scriptDir, "node_modules/http/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val workerShadow = File(scriptDir, "node_modules/worker_threads/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }
            val denied = listOf(
                "dgram",
                "child_process",
                "worker_threads",
                "cluster",
                "inspector",
                "repl",
                "zlib/promises",
                "node:zlib/promises",
            )
            val allowed = listOf(
                "path",
                "fs",
                "fs/promises",
                "buffer",
                "console",
                "v8",
                "module",
                "util",
                "async_hooks",
                "diagnostics_channel",
                "perf_hooks",
                "tty",
                "events",
                "timers",
                "timers/promises",
                "tls",
                "crypto",
                "dns",
                "dns/promises",
                "http",
                "https",
                "net",
                "os",
                "url",
                "querystring",
                "string_decoder",
                "assert",
                "punycode",
                "readline",
                "readline/promises",
                "stream",
                "stream/promises",
                "stream/web",
                "zlib",
                "vm",
            )
            val result = runEmbeddedScript(
                """
                "nodejs";
                const disabledCode = "ERR_AUTOJS6_EMBEDDED_NODE_BUILTIN_DISABLED";
                const denied = ${denied.joinToString(prefix = "[", postfix = "]") { "\"$it\"" }};
                for (const name of denied) {
                  try {
                    require(name);
                    console.log("deny.require." + name + "=allowed");
                  } catch (error) {
                    console.log("deny.require." + name + "=" + (
                      error &&
                      error.code === disabledCode &&
                      String(error.message || "").includes(name)
                    ));
                  }
                  try {
                    require.resolve(name);
                    console.log("deny.resolve." + name + "=allowed");
                  } catch (error) {
                    console.log("deny.resolve." + name + "=" + (
                      error &&
                      error.code === disabledCode &&
                      String(error.message || "").includes(name)
                    ));
                  }
                }

                const allowed = ${allowed.joinToString(prefix = "[", postfix = "]") { "\"$it\"" }};
                for (const name of allowed) {
                  console.log("allow.resolve." + name + "=" + require.resolve(name));
                }

                try {
                  process.getBuiltinModule("http");
                  console.log("deny.getBuiltinModule=false");
                } catch (error) {
                  console.log("deny.getBuiltinModule=" + (
                    error &&
                    error.code === disabledCode &&
                    String(error.message || "").includes("process.getBuiltinModule")
                  ));
                }
                """.trimIndent(),
                "<embedded-deny-hardening-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(httpShadow, workerShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            denied.forEach { name ->
                assertTrue(result.stdout.contains("deny.require.$name=true"))
                assertTrue(result.stdout.contains("deny.resolve.$name=true"))
            }
            allowed.forEach { name ->
                assertTrue(result.stdout.contains("allow.resolve.$name=$name"))
            }
            assertTrue(result.stdout.contains("deny.getBuiltinModule=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun nodeWorkerThreadsDefaultFacadeSupportsNpmFeatureDetection() {
        assumeEmbeddedScriptExecutionEnabled()

        val result = runEmbeddedScript(
            """
            "nodejs";
            return (async () => {
              const moduleBuiltin = require("module");
              const {
                Worker,
                MessageChannel,
                MessagePort,
                receiveMessageOnPort,
                isMainThread,
                parentPort,
                workerData
              } = require("node:worker_threads");
              const channel = new MessageChannel();
              console.log("worker.facade.shape=" + [
                typeof Worker,
                typeof MessageChannel,
                typeof MessagePort,
                typeof receiveMessageOnPort,
                isMainThread,
                parentPort === null,
                workerData === undefined
              ].join("/"));
              console.log("worker.facade.resolve=" + require.resolve("node:worker_threads"));
              console.log("worker.facade.isBuiltin=" + moduleBuiltin.isBuiltin("node:worker_threads"));
              console.log("worker.facade.receive=" + (receiveMessageOnPort(channel.port1) === undefined));
              channel.port1.close();
              channel.port2.close();

              const worker = new Worker(__filename);
              const exitCode = await new Promise((resolve) => {
                worker.once("exit", resolve);
                worker.unref();
              });
              console.log("worker.facade.worker=" + [
                worker instanceof Worker,
                typeof worker.postMessage,
                typeof worker.terminate,
                typeof worker.unref,
                worker.threadId,
                exitCode
              ].join("/"));
              try {
                worker.postMessage({ ok: true });
                console.log("worker.facade.post=allowed");
              } catch (error) {
                console.log("worker.facade.post=" + (
                  error &&
                  error.code === "ERR_AUTOJS6_WORKER_DISABLED" &&
                  String(error.message || "").includes("worker_threads")
                ));
              }
              console.log("worker.facade.terminate=" + await worker.terminate());

              try {
                require("worker_threads");
                console.log("worker.facade.bare=allowed");
              } catch (error) {
                console.log("worker.facade.bare=" + (
                  error &&
                  error.code === "ERR_AUTOJS6_EMBEDDED_NODE_BUILTIN_DISABLED" &&
                  String(error.message || "").includes("worker_threads")
                ));
              }
            })();
            """.trimIndent(),
            "<embedded-node-worker-threads-facade-source.js>",
            workerThreadsExperimentalEnabled = false,
        )

        assertTrue(result.errorMessage.orEmpty(), result.succeeded)
        assertTrue(result.stdout.contains("worker.facade.shape=function/function/function/function/true/true/true"))
        assertTrue(result.stdout.contains("worker.facade.resolve=worker_threads"))
        assertTrue(result.stdout.contains("worker.facade.isBuiltin=true"))
        assertTrue(result.stdout.contains("worker.facade.receive=true"))
        assertTrue(result.stdout.contains("worker.facade.worker=true/function/function/function/0/0"))
        assertTrue(result.stdout.contains("worker.facade.post=true"))
        assertTrue(result.stdout.contains("worker.facade.terminate=0"))
        assertTrue(result.stdout.contains("worker.facade.bare=true"))
    }

    @Test
    fun pureJsNpmRealWorldCompatibilityPackUsesCurrentRestrictedRuntime() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-real-npm-pack-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create real npm pack test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    process.env.DEBUG = "pkg:*";
                    const compose = require("pkg-real-world-compose-like");
                    compose.run().then((result) => {
                      console.log("real.npm.ok=" + result.ok);
                      console.log("real.npm.debug=" + result.debug);
                      console.log("real.npm.cli=" + result.cli);
                      console.log("real.npm.hash=" + result.hash);
                      console.log("real.npm.cache=" + result.cache);
                      console.log("real.npm.stream=" + result.stream);
                      console.log("real.npm.optional=" + result.optional);
                    });
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val compose = File(scriptDir, "node_modules/pkg-real-world-compose-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const debug = require("debug-like");
                    const colors = require("picocolors-like");
                    const safeBuffer = require("safe-buffer-like");
                    const hashSum = require("hash-sum-like");
                    const cache = require("compressed-cache-like");
                    const stable = require("json-stable-stringify-like");
                    const minimist = require("minimist-like");
                    const semver = require("semver-lite");
                    const readableStream = require("readable-stream-lite");
                    const through = require("through-like");
                    const optional = require("optional-dep-fallback-like");
                    exports.run = function run() {
                      const log = debug("pkg:test");
                      const debugText = log("value:%d", 7);
                      const colored = colors.red("x");
                      const parsed = minimist(["--name", "autojs6", "--count=3", "-v"]);
                      const versionOk = semver.gte("1.2.3", "1.2.0");
                      const stableText = stable({ b: 2, a: 1 });
                      const buffer = safeBuffer.from("buffer");
                      const hash = hashSum(buffer);
                      cache.write("cache.json.gz", { stable: stableText, hash: hash });
                      const cached = cache.read("cache.json.gz");
                      return Promise.all([
                        readableStream.read(["read", "able"]),
                        through.upper(["th", "rough"])
                      ]).then((values) => {
                        return {
                          ok: debugText.includes("value:7") &&
                            colored.includes("x") &&
                            parsed.name === "autojs6" &&
                            parsed.count === "3" &&
                            parsed.v === true &&
                            versionOk &&
                            cached.stable === stableText &&
                            cached.hash === hash &&
                            values[0] === "readable" &&
                            values[1] === "THROUGH" &&
                            optional.ok === true &&
                            process.argv.length >= 2,
                          debug: debugText,
                          cli: parsed.name + "/" + parsed.count + "/" + parsed.v + "/" + versionOk,
                          hash: hash.slice(0, 8),
                          cache: cached.stable,
                          stream: values.join("|"),
                          optional: optional.reason
                        };
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val debugPackageJson = File(scriptDir, "node_modules/debug-like/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """{"name":"debug-like","exports":{".":{"require":"./index.js","default":"./index.js"}}}""",
                    StandardCharsets.UTF_8,
                )
            }
            val debugLike = File(scriptDir, "node_modules/debug-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const util = require("util");
                    const ms = require("ms-like");
                    module.exports = function debug(name) {
                      return function log() {
                        if (!String(process.env.DEBUG || "").includes("pkg:")) return "";
                        return name + " " + util.format.apply(util, arguments) + " " + ms(1000);
                      };
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val msLike = File(scriptDir, "node_modules/ms-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """module.exports = function ms(value) { return value === 1000 ? "1s" : String(value) + "ms"; };""",
                    StandardCharsets.UTF_8,
                )
            }
            val picocolorsLike = File(scriptDir, "node_modules/picocolors-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """exports.red = function red(value) { return "\u001b[31m" + value + "\u001b[39m"; };""",
                    StandardCharsets.UTF_8,
                )
            }
            val safeBufferLike = File(scriptDir, "node_modules/safe-buffer-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    exports.from = function from(value, encoding) { return Buffer.from(value, encoding); };
                    exports.isBuffer = Buffer.isBuffer;
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val hashSumLike = File(scriptDir, "node_modules/hash-sum-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const crypto = require("crypto");
                    module.exports = function hashSum(value) {
                      return crypto.createHash("sha256").update(value).digest("hex");
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val compressedCacheLike = File(scriptDir, "node_modules/compressed-cache-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fs = require("fs");
                    const zlib = require("zlib");
                    exports.write = function write(file, value) {
                      fs.writeFileSync(file, zlib.gzipSync(Buffer.from(JSON.stringify(value), "utf8")));
                    };
                    exports.read = function read(file) {
                      return JSON.parse(zlib.gunzipSync(fs.readFileSync(file)).toString("utf8"));
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val stableLike = File(scriptDir, "node_modules/json-stable-stringify-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    function stable(value) {
                      if (value === null || typeof value !== "object") return JSON.stringify(value);
                      if (Array.isArray(value)) return "[" + value.map(stable).join(",") + "]";
                      return "{" + Object.keys(value).sort().map((key) => JSON.stringify(key) + ":" + stable(value[key])).join(",") + "}";
                    }
                    module.exports = stable;
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val minimistLike = File(scriptDir, "node_modules/minimist-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    module.exports = function minimist(args) {
                      const result = {};
                      for (let i = 0; i < args.length; i += 1) {
                        const arg = args[i];
                        if (arg.indexOf("--") === 0) {
                          const body = arg.slice(2);
                          const eq = body.indexOf("=");
                          if (eq >= 0) result[body.slice(0, eq)] = body.slice(eq + 1);
                          else result[body] = args[i + 1] && args[i + 1].indexOf("-") !== 0 ? args[++i] : true;
                        } else if (arg.indexOf("-") === 0) {
                          result[arg.slice(1)] = true;
                        }
                      }
                      return result;
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val semverLike = File(scriptDir, "node_modules/semver-lite/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    function parts(value) {
                      return String(value).split(".").map((part) => parseInt(part, 10) || 0);
                    }
                    exports.gte = function gte(a, b) {
                      const aa = parts(a);
                      const bb = parts(b);
                      for (let i = 0; i < 3; i += 1) {
                        if (aa[i] > bb[i]) return true;
                        if (aa[i] < bb[i]) return false;
                      }
                      return true;
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val readableStreamLike = File(scriptDir, "node_modules/readable-stream-lite/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const { Readable } = require("stream");
                    exports.read = function read(chunks) {
                      return new Promise((resolve) => {
                        let text = "";
                        Readable.from(chunks)
                          .on("data", (chunk) => { text += chunk.toString(); })
                          .on("end", () => resolve(text));
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val throughLike = File(scriptDir, "node_modules/through-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const { PassThrough, Transform } = require("stream");
                    exports.upper = function upper(chunks) {
                      return new Promise((resolve) => {
                        const pass = new PassThrough();
                        const upper = new Transform({
                          transform(chunk, encoding, callback) {
                            callback(null, chunk.toString().toUpperCase());
                          }
                        });
                        let text = "";
                        upper.on("data", (chunk) => { text += chunk.toString(); });
                        upper.on("end", () => resolve(text));
                        pass.pipe(upper);
                        chunks.forEach((chunk) => pass.write(chunk));
                        pass.end();
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val optionalFallbackLike = File(scriptDir, "node_modules/optional-dep-fallback-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    function denied(name, action) {
                      try {
                        action();
                        return false;
                      } catch (error) {
                        return !!(error && (
                          error.code === "ERR_AUTOJS6_EMBEDDED_NODE_BUILTIN_DISABLED" ||
                          error.code === "MODULE_NOT_FOUND" ||
                          String(error.message || "").includes(name)
                        ));
                      }
                    }
                    const requireDenied = denied("worker_threads", () => require("worker_threads"));
                    const resolveDenied = denied("child_process", () => require.resolve("child_process"));
                    module.exports = { ok: requireDenied && resolveDenied, reason: requireDenied + "/" + resolveDenied };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(
                    compose,
                    debugPackageJson,
                    debugLike,
                    msLike,
                    picocolorsLike,
                    safeBufferLike,
                    hashSumLike,
                    compressedCacheLike,
                    stableLike,
                    minimistLike,
                    semverLike,
                    readableStreamLike,
                    throughLike,
                    optionalFallbackLike,
                ),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("real.npm.ok=true"))
            assertTrue(result.stdout.contains("real.npm.debug=pkg:test value:7 1s"))
            assertTrue(result.stdout.contains("real.npm.cli=autojs6/3/true/true"))
            assertTrue(result.stdout.contains("real.npm.hash="))
            assertTrue(result.stdout.contains("real.npm.cache={\"a\":1,\"b\":2}"))
            assertTrue(result.stdout.contains("real.npm.stream=readable|THROUGH"))
            assertTrue(result.stdout.contains("real.npm.optional=true/true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun realNpmFixtureCorpusRunsOfflineCommonJsPackages() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-real-npm-corpus-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create real npm corpus test dir: $absolutePath" }
        }
        try {
            File(scriptDir, "fixture.txt").writeText("fixture", StandardCharsets.UTF_8)
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    process.env.DEBUG = "app:*";
                    process.argv.push("--name", "autojs6", "--count=2", "-v", "--flag");
                    const path = require("path");
                    const isNumber = require("is-number");
                    const isOdd = require("is-odd");
                    const kindOf = require("kind-of");
                    const isPlainObject = require("is-plain-object");
                    const once = require("once");
                    const inherits = require("inherits");
                    const ms = require("ms");
                    const debug = require("debug");
                    const debugFormatters = require("debug/formatters");
                    const picocolors = require("picocolors");
                    const safeBuffer = require("safe-buffer");
                    const stableStringify = require("json-stable-stringify");
                    const minimist = require("minimist");
                    const semver = require("semver");
                    const resolveFrom = require("resolve-from");
                    const pathExists = require("path-exists");
                    const scopedHelper = require("@autojs6/corpus-helper");

                    let calls = 0;
                    const onlyOnce = once(function corpusOnce(value) {
                      calls += 1;
                      return "once-" + value;
                    });
                    function Base() {
                      this.base = "base";
                    }
                    Base.prototype.kind = function kind() {
                      return this.base;
                    };
                    function Child() {
                      Base.call(this);
                    }
                    inherits(Child, Base);
                    const child = new Child();
                    const argv = minimist(process.argv.slice(2));
                    const debugLog = debug("app:test");
                    const buffer = safeBuffer.Buffer.from("safe", "utf8");
                    const resolvedDebug = resolveFrom(process.cwd(), "debug");
                    const stable = stableStringify({ b: 1, a: 2, nested: { z: 3, c: 4 } });

                    console.log("real.corpus.isNumber=" + isNumber("42"));
                    console.log("real.corpus.isOdd=" + isOdd("3"));
                    console.log("real.corpus.kindObject=" + kindOf({}));
                    console.log("real.corpus.kindBuffer=" + kindOf(Buffer.from("x")));
                    console.log("real.corpus.plainObject=" + isPlainObject({ a: 1 }));
                    console.log("real.corpus.plainArray=" + isPlainObject([]));
                    console.log("real.corpus.once1=" + onlyOnce("first"));
                    console.log("real.corpus.once2=" + onlyOnce("second"));
                    console.log("real.corpus.onceCalls=" + calls);
                    console.log("real.corpus.inherits=" + (child instanceof Base) + "/" + child.kind());
                    console.log("real.corpus.msParse=" + ms("2s"));
                    console.log("real.corpus.msFormat=" + ms(60000));
                    console.log("real.corpus.debug=" + debugLog("ready %d", 7));
                    console.log("real.corpus.debugEnabled=" + debugLog.enabled);
                    console.log("real.corpus.debugOptional=" + debug.supportsColor);
                    console.log("real.corpus.debugFormat=" + debugFormatters.j("x"));
                    console.log("real.corpus.color=" + picocolors.red("x").includes("x"));
                    console.log("real.corpus.esModule=" + picocolors.__esModule);
                    console.log("real.corpus.buffer=" + buffer.toString("utf8") + "/" + safeBuffer.Buffer.isBuffer(buffer));
                    console.log("real.corpus.stable=" + stable);
                    console.log("real.corpus.argv=" + argv.name + "/" + argv.count + "/" + argv.v + "/" + argv.flag);
                    console.log("real.corpus.semverValid=" + semver.valid("1.2.3"));
                    console.log("real.corpus.semverSatisfies=" + semver.satisfies("1.2.3", "^1.2.0"));
                    console.log("real.corpus.resolve=" + path.basename(resolvedDebug) + "/" + resolvedDebug.includes("node_modules" + path.sep + "debug"));
                    console.log("real.corpus.pathExists=" + pathExists.sync("./fixture.txt") + "/" + pathExists.sync("./missing.txt"));
                    console.log("real.corpus.scoped=" + scopedHelper.fixtureExists + "/" + scopedHelper.cwdBase);
                    console.log("real.corpus.cacheSame=" + (require("is-number") === isNumber));
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val packageFiles = mutableListOf<File>()
            packageFiles += writeNpmPackage(
                scriptDir,
                "is-number",
                """{"name":"is-number","version":"7.0.0","main":"index.js"}""",
                mapOf(
                    "index.js" to """
                    "use strict";
                    module.exports = function isNumber(value) {
                      if (typeof value === "number") return value - value === 0;
                      if (typeof value === "string" && value.trim() !== "") return Number.isFinite(Number(value));
                      return false;
                    };
                    """,
                ),
            )
            packageFiles += writeNpmPackage(
                scriptDir,
                "is-odd",
                """{"name":"is-odd","version":"3.0.1","main":"index.js","dependencies":{"is-number":"^7.0.0"}}""",
                mapOf(
                    "index.js" to """
                    "use strict";
                    const isNumber = require("is-number");
                    module.exports = function isOdd(value) {
                      if (!isNumber(value)) throw new TypeError("expected a number");
                      return Math.abs(Number(value)) % 2 === 1;
                    };
                    """,
                ),
            )
            packageFiles += writeNpmPackage(
                scriptDir,
                "kind-of",
                """{"name":"kind-of","version":"6.0.3","main":"index.js"}""",
                mapOf(
                    "index.js" to """
                    "use strict";
                    const toString = Object.prototype.toString;
                    module.exports = function kindOf(value) {
                      if (value === null) return "null";
                      if (value === undefined) return "undefined";
                      if (Buffer.isBuffer(value)) return "buffer";
                      const type = typeof value;
                      if (type !== "object") return type;
                      if (Array.isArray(value)) return "array";
                      return toString.call(value).slice(8, -1).toLowerCase();
                    };
                    """,
                ),
            )
            packageFiles += writeNpmPackage(
                scriptDir,
                "is-plain-object",
                """
                {
                  "name": "is-plain-object",
                  "version": "5.0.0",
                  "exports": {
                    ".": {
                      "require": "./dist/index.js",
                      "default": "./dist/index.js"
                    }
                  }
                }
                """,
                mapOf(
                    "dist/index.js" to """
                    "use strict";
                    Object.defineProperty(exports, "__esModule", { value: true });
                    const kindOf = require("kind-of");
                    module.exports = function isPlainObject(value) {
                      if (kindOf(value) !== "object") return false;
                      const proto = Object.getPrototypeOf(value);
                      return proto === Object.prototype || proto === null;
                    };
                    """,
                ),
            )
            packageFiles += writeNpmPackage(
                scriptDir,
                "wrappy",
                """{"name":"wrappy","version":"1.0.2","main":"wrappy.js"}""",
                mapOf(
                    "wrappy.js" to """
                    "use strict";
                    module.exports = wrappy;
                    function wrappy(fn, cb) {
                      if (fn && cb) return wrappy(fn)(cb);
                      if (typeof fn !== "function") throw new TypeError("need function");
                      Object.keys(fn).forEach(function copy(key) {
                        wrapper[key] = fn[key];
                      });
                      return wrapper;
                      function wrapper() {
                        return fn.apply(this, arguments);
                      }
                    }
                    """,
                ),
            )
            packageFiles += writeNpmPackage(
                scriptDir,
                "once",
                """{"name":"once","version":"1.4.0","main":"once.js","dependencies":{"wrappy":"1"}}""",
                mapOf(
                    "once.js" to """
                    "use strict";
                    const wrappy = require("wrappy");
                    module.exports = wrappy(once);
                    function once(fn) {
                      let called = false;
                      let value;
                      return function wrappedOnce() {
                        if (!called) {
                          called = true;
                          value = fn.apply(this, arguments);
                        }
                        return value;
                      };
                    }
                    """,
                ),
            )
            packageFiles += writeNpmPackage(
                scriptDir,
                "inherits",
                """{"name":"inherits","version":"2.0.4","main":"inherits.js"}""",
                mapOf(
                    "inherits.js" to """
                    "use strict";
                    module.exports = require("util").inherits;
                    """,
                ),
            )
            packageFiles += writeNpmPackage(
                scriptDir,
                "ms",
                """{"name":"ms","version":"2.1.3","main":"index.js"}""",
                mapOf(
                    "index.js" to """
                    "use strict";
                    module.exports = function ms(value) {
                      if (typeof value === "number") {
                        if (value % 60000 === 0) return String(value / 60000) + "m";
                        if (value % 1000 === 0) return String(value / 1000) + "s";
                        return String(value) + "ms";
                      }
                      const text = String(value);
                      const amount = parseFloat(text);
                      if (text.endsWith("ms")) return amount;
                      if (text.endsWith("s")) return amount * 1000;
                      if (text.endsWith("m")) return amount * 60000;
                      return amount;
                    };
                    """,
                ),
            )
            packageFiles += writeNpmPackage(
                scriptDir,
                "debug",
                """
                {
                  "name": "debug",
                  "version": "4.3.7",
                  "main": "./src/common.js",
                  "exports": {
                    ".": {
                      "require": "./src/common.js",
                      "default": "./src/common.js"
                    },
                    "./formatters": "./src/formatters.js"
                  },
                  "dependencies": {
                    "ms": "2.1.3"
                  },
                  "peerDependenciesMeta": {
                    "supports-color": {
                      "optional": true
                    }
                  }
                }
                """,
                mapOf(
                    "src/common.js" to """
                    "use strict";
                    const util = require("util");
                    const ms = require("ms");
                    let supportsColor = false;
                    try {
                      supportsColor = !!require("supports-color");
                    } catch (_) {
                      supportsColor = false;
                    }
                    function enabled(namespace) {
                      const value = String(process.env.DEBUG || "");
                      return value.split(/[,\s]+/).some(function match(pattern) {
                        if (!pattern) return false;
                        if (pattern === "*") return true;
                        if (pattern.endsWith("*")) return namespace.indexOf(pattern.slice(0, -1)) === 0;
                        return pattern === namespace;
                      });
                    }
                    function createDebug(namespace) {
                      function debug() {
                        if (!debug.enabled) return "";
                        return namespace + " " + util.format.apply(util, arguments) + " +" + ms("2s");
                      }
                      debug.enabled = enabled(namespace);
                      return debug;
                    }
                    createDebug.supportsColor = supportsColor;
                    createDebug.formatters = require("./formatters");
                    module.exports = createDebug;
                    """,
                    "src/formatters.js" to """
                    "use strict";
