                "safe-buffer",
                """{"name":"safe-buffer","version":"5.2.1","main":"index.js"}""",
                mapOf(
                    "index.js" to """
                    "use strict";
                    exports.Buffer = Buffer;
                    exports.SafeBuffer = Buffer;
