                mapOf(
                    "index.js" to """
                    "use strict";
                    module.exports = function minimist(args) {
                      const result = { _: [] };
                      for (let i = 0; i < args.length; i += 1) {
                        const arg = args[i];
                        if (arg.indexOf("--") === 0) {
                          const body = arg.slice(2);
                          const eq = body.indexOf("=");
                          if (eq >= 0) {
                            result[body.slice(0, eq)] = body.slice(eq + 1);
                          } else {
                            result[body] = args[i + 1] && args[i + 1].indexOf("-") !== 0 ? args[++i] : true;
                          }
                        } else if (arg.indexOf("-") === 0 && arg.length > 1) {
                          arg.slice(1).split("").forEach(function flag(name) {
                            result[name] = true;
                          });
                        } else {
                          result._.push(arg);
                        }
                      }
                      return result;
                    };
                    """,
                ),
            )
            packageFiles += writeNpmPackage(
                scriptDir,
                "semver",
                """{"name":"semver","version":"7.6.3","main":"index.js"}""",
                mapOf(
                    "index.js" to """
                    "use strict";
                    function parse(value) {
                      const match = /^v?(\d+)\.(\d+)\.(\d+)/.exec(String(value));
                      return match && {
                        version: match[1] + "." + match[2] + "." + match[3],
                        major: Number(match[1]),
                        minor: Number(match[2]),
                        patch: Number(match[3])
                      };
                    }
                    function gte(a, b) {
                      const aa = parse(a);
                      const bb = parse(b);
                      if (!aa || !bb) return false;
                      if (aa.major !== bb.major) return aa.major > bb.major;
                      if (aa.minor !== bb.minor) return aa.minor > bb.minor;
                      return aa.patch >= bb.patch;
                    }
                    exports.valid = function valid(value) {
                      const parsed = parse(value);
                      return parsed ? parsed.version : null;
                    };
                    exports.gte = gte;
                    exports.satisfies = function satisfies(version, range) {
                      if (range.indexOf("^") === 0) {
                        const base = parse(range.slice(1));
                        const current = parse(version);
