            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(*packageFiles.toTypedArray()),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("real.corpus.isNumber=true"))
            assertTrue(result.stdout.contains("real.corpus.isOdd=true"))
            assertTrue(result.stdout.contains("real.corpus.kindObject=object"))
            assertTrue(result.stdout.contains("real.corpus.kindBuffer=buffer"))
            assertTrue(result.stdout.contains("real.corpus.plainObject=true"))
            assertTrue(result.stdout.contains("real.corpus.plainArray=false"))
            assertTrue(result.stdout.contains("real.corpus.once1=once-first"))
            assertTrue(result.stdout.contains("real.corpus.once2=once-first"))
            assertTrue(result.stdout.contains("real.corpus.onceCalls=1"))
            assertTrue(result.stdout.contains("real.corpus.inherits=true/base"))
            assertTrue(result.stdout.contains("real.corpus.msParse=2000"))
            assertTrue(result.stdout.contains("real.corpus.msFormat=1m"))
            assertTrue(result.stdout.contains("real.corpus.debug=app:test ready 7 +nested-2s"))
            assertTrue(result.stdout.contains("real.corpus.debugEnabled=true"))
            assertTrue(result.stdout.contains("real.corpus.debugOptional=false"))
            assertTrue(result.stdout.contains("real.corpus.debugFormat=\"x\""))
            assertTrue(result.stdout.contains("real.corpus.color=true"))
            assertTrue(result.stdout.contains("real.corpus.esModule=true"))
            assertTrue(result.stdout.contains("real.corpus.buffer=safe/true"))
            assertTrue(result.stdout.contains("real.corpus.stable={\"a\":2,\"b\":1,\"nested\":{\"c\":4,\"z\":3}}"))
            assertTrue(result.stdout.contains("real.corpus.argv=autojs6/2/true/true"))
            assertTrue(result.stdout.contains("real.corpus.semverValid=1.2.3"))
            assertTrue(result.stdout.contains("real.corpus.semverSatisfies=true"))
            assertTrue(result.stdout.contains("real.corpus.resolve=common.js/true"))
            assertTrue(result.stdout.contains("real.corpus.pathExists=true/false"))
            assertTrue(result.stdout.contains("real.corpus.scoped=true/true"))
            assertTrue(result.stdout.contains("real.corpus.cacheSame=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

