            assertTrue(result.stdout.contains("real.corpus2.camelDefault=true"))
            assertTrue(result.stdout.contains("real.corpus2.decamel=foo-bar-baz"))
            assertTrue(result.stdout.contains("real.corpus2.strip=red"))
            assertTrue(result.stdout.contains("real.corpus2.ansi=true"))
            assertTrue(result.stdout.contains("real.corpus2.width=5"))
            assertTrue(result.stdout.contains("real.corpus2.fullwidth=true"))
            assertTrue(result.stdout.contains("real.corpus2.emoji=true"))
            assertTrue(result.stdout.contains("real.corpus2.argv=auto-js-six/true/true/4"))
            assertTrue(result.stdout.contains("real.corpus2.color=true/true"))
            assertTrue(result.stdout.contains("real.corpus2.optional=true/true/true"))
