    @Test
    fun scopedFsSupportsStatfsSyncCallbackAndPromises() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-statfs-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs statfs test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const nodeFs = require("node:fs");
                const path = require("path");
                const url = require("url");
                const fsp = require("fs/promises");
                const nodeFsp = require("node:fs/promises");

                function statfsCallback(pathValue, options) {
                  return new Promise((resolve, reject) => {
                    const done = (error, stats) => {
                      if (error) reject(error);
                      else resolve(stats);
                    };
                    if (arguments.length >= 2) {
                      fs.statfs(pathValue, options, done);
                    } else {
                      fs.statfs(pathValue, done);
                    }
                  });
                }

                function numberStatfs(value) {
                  return !!(
                    value &&
                    typeof value.type === "number" &&
                    typeof value.bsize === "number" &&
                    typeof value.blocks === "number" &&
                    typeof value.bfree === "number" &&
                    typeof value.bavail === "number" &&
                    typeof value.files === "number" &&
                    typeof value.ffree === "number" &&
                    value.bsize > 0
                  );
                }

                function bigintStatfs(value) {
                  return !!(
                    value &&
                    typeof value.type === "bigint" &&
                    typeof value.bsize === "bigint" &&
                    typeof value.blocks === "bigint" &&
                    typeof value.bfree === "bigint" &&
                    typeof value.bavail === "bigint" &&
                    typeof value.files === "bigint" &&
                    typeof value.ffree === "bigint" &&
                    value.bsize > 0n
                  );
                }

                function captureSync(action, token) {
                  try {
                    action();
                    return false;
                  } catch (error) {
                    return String(error && error.message || error).includes(token);
                  }
                }

                function capturePromise(action, token) {
                  return Promise.resolve().then(action).then(
                    () => false,
                    (error) => String(error && error.message || error).includes(token)
                  );
                }

                function captureCallback(pathValue, token) {
                  return new Promise((resolve) => {
                    fs.statfs(pathValue, (error) => {
                      resolve(!!error && String(error && error.message || error).includes(token));
                    });
                  });
                }

                return (async () => {
                  fs.mkdirSync("./statfs/sub", { recursive: true });
                  fs.writeFileSync("./statfs/sub/a.txt", "x", "utf8");
                  const syncInfo = fs.statfsSync("./statfs/sub");
                  const syncFileInfo = fs.statfsSync("./statfs/sub/a.txt");
                  const callbackInfo = await statfsCallback(Buffer.from("./statfs/sub"));
                  const callbackBigInfo = await statfsCallback("./statfs/sub", { bigint: true });
                  const promiseInfo = await fsp.statfs(
                    url.pathToFileURL(path.resolve(process.cwd(), "./statfs/sub"))
                  );
                  const promiseBigInfo = await fsp.statfs("./statfs/sub", { bigint: true });
                  console.log("statfs.alias=" + (fs === nodeFs && fsp === nodeFsp && fs.promises === fsp));
                  console.log("statfs.types=" + [
                    typeof fs.statfsSync,
                    typeof fs.statfs,
                    typeof fsp.statfs
                  ].join(","));
                  console.log("statfs.values=" + [syncInfo, syncFileInfo, callbackInfo, promiseInfo].every(numberStatfs));
                  console.log("statfs.bigint=" + (bigintStatfs(callbackBigInfo) && bigintStatfs(promiseBigInfo)));

                  const nulPath = "bad" + String.fromCharCode(0) + "path";
                  const denied = [
                    captureSync(() => fs.statfsSync("../outside"), "escapes working directory"),
                    captureSync(() => fs.statfsSync("/sdcard"), "rejects absolute path"),
                    captureSync(() => fs.statfsSync(nulPath), "rejects NUL"),
                    captureSync(() => fs.statfs("./statfs/sub"), "callback must be a function"),
                    await capturePromise(() => fsp.statfs("../outside"), "escapes working directory"),
                    await capturePromise(() => fsp.statfs("./statfs/missing"), "path does not exist"),
                    await captureCallback(Buffer.from("../outside"), "escapes working directory")
                  ];
                  console.log("statfs.denied=" + denied.filter(Boolean).length + "/" + denied.length);
                })();
                """.trimIndent(),
                "<embedded-scoped-fs-statfs-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("statfs.alias=true"))
            assertTrue(result.stdout.contains("statfs.types=function,function,function"))
            assertTrue(result.stdout.contains("statfs.values=true"))
            assertTrue(result.stdout.contains("statfs.bigint=true"))
            assertTrue(result.stdout.contains("statfs.denied=7/7"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsSupportsHardLinksAndLegacyExists() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-link-exists-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs link/exists test dir: $absolutePath" }
        }
        val outsideSync = File(scriptDir.parentFile, "${scriptDir.name}-outside-sync.txt").apply {
            delete()
        }
        val outsidePromise = File(scriptDir.parentFile, "${scriptDir.name}-outside-promise.txt").apply {
            delete()
        }
        val outsideCallback = File(scriptDir.parentFile, "${scriptDir.name}-outside-callback.txt").apply {
            delete()
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const nodeFs = require("node:fs");
                const fsp = require("fs/promises");
                const nodeFsp = require("node:fs/promises");
                const path = require("path");
                const url = require("url");

                function linkCallback(existingPath, newPath) {
                  return new Promise((resolve, reject) => {
                    fs.link(existingPath, newPath, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                function existsCallback(pathValue) {
                  return new Promise((resolve) => {
                    fs.exists(pathValue, resolve);
                  });
                }

                function captureSync(action, token) {
                  try {
                    action();
                    return false;
                  } catch (error) {
                    return String(error && error.message || error).includes(token);
                  }
                }

                function capturePromise(action, token) {
                  return Promise.resolve().then(action).then(
                    () => false,
                    (error) => String(error && error.message || error).includes(token)
                  );
                }

                function captureLinkCallback(existingPath, newPath, token) {
                  return new Promise((resolve) => {
                    fs.link(existingPath, newPath, (error) => {
                      resolve(!!error && String(error && error.message || error).includes(token));
                    });
                  });
                }

                function isNativeLinkUnsupported(error) {
                  return error && ["EACCES", "EPERM", "ENOSYS", "EXDEV", "EOPNOTSUPP"].includes(error.code);
                }

                return (async () => {
                  fs.mkdirSync("./links", { recursive: true });
                  fs.writeFileSync("./links/source.txt", "source", "utf8");
                  let linkNativeUnsupported = false;
                  let linkNativeUnsupportedCode = "";
                  try {
                    fs.linkSync("./links/source.txt", "./links/sync.txt");
                    await linkCallback(Buffer.from("./links/source.txt"), "./links/callback.txt");
                    await fsp.link(
                      "./links/source.txt",
                      url.pathToFileURL(path.resolve(process.cwd(), "./links/promise.txt"))
                    );
                    fs.writeFileSync("./links/sync.txt", "linked", "utf8");
                  } catch (error) {
                    if (!isNativeLinkUnsupported(error)) {
                      throw error;
                    }
                    linkNativeUnsupported = true;
                    linkNativeUnsupportedCode = String(error.code || "UNKNOWN");
                  }

                  const existing = await existsCallback("./links/source.txt");
                  const missing = await existsCallback("./links/missing.txt");
                  const bufferExisting = linkNativeUnsupported
                    ? false
                    : await existsCallback(Buffer.from("./links/callback.txt"));
                  const urlExisting = linkNativeUnsupported
                    ? false
                    : await existsCallback(
                      url.pathToFileURL(path.resolve(process.cwd(), "./links/promise.txt"))
                    );
                  console.log("link.alias=" + (fs === nodeFs && fsp === nodeFsp && fs.promises === fsp));
                  console.log("link.types=" + [
                    typeof fs.linkSync,
                    typeof fs.link,
                    typeof fsp.link,
                    typeof fs.exists,
                    typeof fs.existsSync
                  ].join(","));
                  console.log("link.native_unsupported=" + linkNativeUnsupported);
                  console.log("link.content=" + (linkNativeUnsupported
                    ? "unsupported:" + linkNativeUnsupportedCode
                    : [
                      fs.readFileSync("./links/source.txt", "utf8"),
                      fs.readFileSync("./links/sync.txt", "utf8"),
                      fs.readFileSync("./links/callback.txt", "utf8"),
                      fs.readFileSync("./links/promise.txt", "utf8")
                    ].join("|")));
                  console.log("exists.legacy=" + [existing, missing, bufferExisting, urlExisting].join("|"));

                  const nulPath = "bad" + String.fromCharCode(0) + "path";
                  const denied = [
                    captureSync(() => fs.linkSync("../outside", "./links/out.txt"), "escapes working directory"),
                    captureSync(() => fs.linkSync("./links/source.txt", "../${outsideSync.name}"), "escapes working directory"),
                    captureSync(() => fs.linkSync(nulPath, "./links/nul.txt"), "rejects NUL"),
                    captureSync(() => fs.exists("../outside", () => {}), "escapes working directory"),
                    captureSync(() => fs.exists("./links/source.txt"), "callback must be a function"),
                    await capturePromise(() => fsp.link("./links/source.txt", "../${outsidePromise.name}"), "escapes working directory"),
                    await captureLinkCallback("./links/source.txt", "../${outsideCallback.name}", "escapes working directory")
                  ];
                  console.log("link.denied=" + denied.filter(Boolean).length + "/" + denied.length);
                })();
                """.trimIndent(),
                "<embedded-scoped-fs-link-exists-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("link.alias=true"))
            assertTrue(result.stdout.contains("link.types=function,function,function,function,function"))
            val hardLinksUnavailable = result.stdout.contains("link.native_unsupported=true")
            assertTrue(
                result.stdout,
                result.stdout.contains("link.content=linked|linked|linked|linked") || hardLinksUnavailable,
            )
            assertTrue(
                result.stdout,
                result.stdout.contains("exists.legacy=true|false|true|true") ||
                    result.stdout.contains("exists.legacy=true|false|false|false"),
            )
            assertTrue(result.stdout.contains("link.denied=7/7"))
            if (!hardLinksUnavailable) {
                assertEquals("linked", File(scriptDir, "links/source.txt").readText(StandardCharsets.UTF_8))
            }
            assertFalse(outsideSync.exists())
            assertFalse(outsidePromise.exists())
            assertFalse(outsideCallback.exists())
        } finally {
            outsideSync.delete()
            outsidePromise.delete()
            outsideCallback.delete()
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsSupportsNativeGlobSyncCallbackAndPromises() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-glob-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs glob test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const nodeFs = require("node:fs");
                const fsp = require("fs/promises");
                const nodeFsp = require("node:fs/promises");
                const path = require("path");
                const url = require("url");

                function normalizeList(values) {
                  return values.map((value) => String(value).replace(/\\/g, "/")).sort().join("|");
                }

                function globCallback(pattern, options) {
                  return new Promise((resolve, reject) => {
                    const done = (error, matches) => {
                      if (error) reject(error);
                      else resolve(matches);
                    };
                    if (arguments.length >= 2) {
                      fs.glob(pattern, options, done);
                    } else {
                      fs.glob(pattern, done);
                    }
                  });
                }

                async function collect(iterator) {
                  const values = [];
                  for await (const value of iterator) {
                    values.push(value);
                  }
                  return values;
                }

                function captureSync(action, token) {
                  try {
                    action();
                    return false;
                  } catch (error) {
                    return String(error && error.message || error).includes(token);
                  }
                }

                function capturePromise(action, token) {
                  return Promise.resolve().then(action).then(
                    () => false,
                    (error) => String(error && error.message || error).includes(token)
                  );
                }

                function captureGlobCallback(pattern, options, token) {
                  return new Promise((resolve) => {
                    fs.glob(pattern, options, (error) => {
                      resolve(!!error && String(error && error.message || error).includes(token));
                    });
                  });
                }

                return (async () => {
                  const workspace = "./glob/workspace";
                  fs.mkdirSync(workspace + "/src/a", { recursive: true });
                  fs.mkdirSync(workspace + "/src/b", { recursive: true });
                  fs.mkdirSync(workspace + "/src/c", { recursive: true });
                  fs.mkdirSync(workspace + "/lib", { recursive: true });
                  fs.writeFileSync(workspace + "/src/a/index.js", "a", "utf8");
                  fs.writeFileSync(workspace + "/src/a/index.test.js", "test", "utf8");
                  fs.writeFileSync(workspace + "/src/a/readme.md", "readme", "utf8");
                  fs.writeFileSync(workspace + "/src/b/main.js", "b", "utf8");
                  fs.writeFileSync(workspace + "/src/b/util.cjs", "cjs", "utf8");
                  fs.writeFileSync(workspace + "/src/c/skip.js", "skip", "utf8");
                  fs.writeFileSync(workspace + "/lib/tool.js", "tool", "utf8");

                  const allJs = fs.globSync("src/**/*.js", { cwd: workspace });
                  const excluded = fs.globSync("src/**/*.js", {
                    cwd: workspace,
                    exclude: ["**/*.test.js", "src/c/skip.js"]
                  });
                  const callbackCjs = await globCallback("src/**/*.cjs", { cwd: Buffer.from(workspace) });
                  const promiseMatches = await collect(fsp.glob(["src/**/*.js", "lib/**/*.js"], {
                    cwd: workspace,
                    exclude: ["**/*.test.js", "src/c/skip.js"]
                  }));
                  const urlCwdMatches = fs.globSync("src/b/*.js", {
                    cwd: url.pathToFileURL(path.resolve(process.cwd(), workspace))
                  });
                  const dirents = fs.globSync("src/a/*", {
                    cwd: workspace,
                    withFileTypes: true
                  });
                  const direntSummary = dirents
                    .map((entry) => entry.name + ":" + entry.isFile() + ":" + typeof entry.parentPath)
                    .sort()
                    .join("|");
                  const excludeFunctionCalls = [];
                  const functionExcluded = fs.globSync("src/**/*.js", {
                    cwd: workspace,
                    exclude: (entry) => {
                      const text = String(entry).replace(/\\/g, "/");
                      excludeFunctionCalls.push(text);
                      return text.endsWith("src/a/index.test.js") || text.endsWith("src/c/skip.js");
                    }
                  });
                  const direntExcludeCalls = [];
                  const direntFunctionEntries = fs.globSync("src/a/*", {
                    cwd: workspace,
                    withFileTypes: true,
                    exclude: (entry) => {
                      direntExcludeCalls.push(
                        entry.name + ":" +
                        String(entry.parentPath).replace(/\\/g, "/") + ":" +
                        Object.isFrozen(entry)
                      );
                      return entry.name.endsWith(".md");
                    }
                  });
                  const direntFunctionSummary = direntFunctionEntries
                    .map((entry) => entry.name + ":" + entry.isFile() + ":" + typeof entry.parentPath)
                    .sort()
                    .join("|");

                  console.log("glob.alias=" + (fs === nodeFs && fsp === nodeFsp && fs.promises === fsp));
                  console.log("glob.types=" + [
                    typeof fs.globSync,
                    typeof fs.glob,
                    typeof fsp.glob
                  ].join(","));
                  console.log("glob.sync=" + normalizeList(allJs));
                  console.log("glob.exclude=" + normalizeList(excluded));
                  console.log("glob.callback=" + normalizeList(callbackCjs));
                  console.log("glob.promise=" + normalizeList(promiseMatches));
                  console.log("glob.url_cwd=" + normalizeList(urlCwdMatches));
                  console.log("glob.dirent=" + direntSummary);
                  console.log("glob.exclude_function=" + normalizeList(functionExcluded) + ":" + excludeFunctionCalls.includes("src/a/index.js"));
                  console.log("glob.dirent_exclude_function=" + direntFunctionSummary + ":" + direntExcludeCalls.includes("readme.md:src/a:true"));

                  const nulPath = "bad" + String.fromCharCode(0) + "glob";
                  const denied = [
                    captureSync(() => fs.globSync("../**"), "parent segment"),
                    captureSync(() => fs.globSync("/sdcard/**/*.js"), "absolute glob pattern"),
                    captureSync(() => fs.globSync("src/**/*.js", { cwd: "../outside" }), "escapes working directory"),
                    captureSync(() => fs.globSync("src/**/*.js", { cwd: workspace, followSymlinks: true }), "followSymlinks"),
                    captureSync(() => fs.globSync("src/**/*.js", { cwd: workspace, exclude: "**/*.test.js" }), "exclude"),
                    captureSync(() => fs.globSync(["src/**/*.js", "../**"], { cwd: workspace }), "parent segment"),
                    captureSync(() => fs.globSync("src/**/*.js", { cwd: workspace + "/src/a/index.js" }), "cwd must be a directory"),
                    captureSync(() => fs.globSync("src/**/*.js", { cwd: url.pathToFileURL(path.resolve(process.cwd(), "..")) }), "escapes working directory"),
                    captureSync(() => fs.glob("src/**/*.js", { cwd: workspace }), "callback must be a function"),
                    await capturePromise(() => fsp.glob("../**"), "parent segment"),
                    await capturePromise(() => fsp.glob(["src/**/*.js", "/sdcard/**/*.js"], { cwd: workspace }), "absolute glob pattern"),
                    await captureGlobCallback(["src/**/*.js", nulPath], { cwd: workspace }, "NUL"),
                    await captureGlobCallback("../**", { cwd: workspace }, "parent segment")
                  ];
                  console.log("glob.denied=" + denied.filter(Boolean).length + "/" + denied.length);
                })();
                """.trimIndent(),
                "<embedded-scoped-fs-glob-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty() + "\n" + result.stdout, result.succeeded)
            assertTrue(result.stdout.contains("glob.alias=true"))
            assertTrue(result.stdout.contains("glob.types=function,function,function"))
            assertTrue(result.stdout.contains("glob.sync=src/a/index.js|src/a/index.test.js|src/b/main.js|src/c/skip.js"))
            assertTrue(result.stdout.contains("glob.exclude=src/a/index.js|src/b/main.js"))
            assertTrue(result.stdout.contains("glob.callback=src/b/util.cjs"))
            assertTrue(result.stdout.contains("glob.promise=lib/tool.js|src/a/index.js|src/b/main.js"))
            assertTrue(result.stdout.contains("glob.url_cwd=src/b/main.js"))
            assertTrue(result.stdout.contains("glob.dirent=index.js:true:string|index.test.js:true:string|readme.md:true:string"))
            assertTrue(result.stdout, result.stdout.contains("glob.exclude_function=src/a/index.js|src/b/main.js:true"))
            assertTrue(result.stdout.contains("glob.dirent_exclude_function=index.js:true:string|index.test.js:true:string:true"))
            assertTrue(result.stdout.contains("glob.denied=13/13"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsGapsHandleDirectoriesNestedFilesAndMissingAccess() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-gaps-hardening-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs gaps hardening test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                fs.mkdirSync("./nested/dir", { recursive: true });
                fs.writeFileSync("./nested/dir/file.txt", "x", "utf8");
                fs.accessSync("./nested/dir", fs.constants.F_OK);
                fs.accessSync("./nested/dir/file.txt", fs.constants.R_OK);
                console.log("lstat.dir=" + fs.lstatSync("./nested/dir").isDirectory());
                console.log("lstat.file=" + fs.lstatSync("./nested/dir/file.txt").isFile());
                console.log("realpath.dir=" + fs.realpathSync("./nested/dir").endsWith("nested/dir"));
                console.log("realpath.file=" + fs.realpathSync("./nested/dir/file.txt").endsWith("nested/dir/file.txt"));
                console.log("realpath.native.file=" + fs.realpathSync.native("./nested/dir/file.txt").endsWith("nested/dir/file.txt"));
                """.trimIndent(),
                "<embedded-scoped-fs-gaps-hardening-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("lstat.dir=true"))
            assertTrue(result.stdout.contains("lstat.file=true"))
            assertTrue(result.stdout.contains("realpath.dir=true"))
            assertTrue(result.stdout.contains("realpath.file=true"))
            assertTrue(result.stdout.contains("realpath.native.file=true"))

            settleEmbeddedScriptServiceProcess()

            val missingAccess = runEmbeddedScript(
                """require("fs").accessSync("./missing.txt");""",
                "<embedded-scoped-fs-access-missing-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )
            assertFalse(missingAccess.succeeded)
            assertEquals("Error", missingAccess.errorName)
            assertTrue(missingAccess.errorMessage.orEmpty().contains("path does not exist"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

