    @Test
    fun scopedFsSupportsSelectedCallbackFileApisAndWaitsForNestedCallbacks() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-callback-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create callback scoped fs test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                console.log("promises=" + typeof fs.promises);
                console.log("callback.types=" + [
                  fs.readFile,
                  fs.writeFile,
                  fs.appendFile,
                  fs.truncate,
                  fs.stat,
                  fs.lstat,
                  fs.access,
                  fs.readdir,
                  fs.mkdir,
                  fs.unlink,
                  fs.rm,
                  fs.cp,
                  fs.mkdtemp,
                  fs.rename
                ].every((fn) => typeof fn === "function"));
                fs.writeFile("./a.txt", "hello", "utf8", (writeError) => {
                  console.log("write.err=" + (writeError === null));
                  fs.appendFile("./a.txt", " world", "utf8", (appendError) => {
                    console.log("append.err=" + (appendError === null));
                    fs.readFile("./a.txt", "utf8", (readError, text) => {
                      console.log("read.err=" + (readError === null));
                      console.log("read.text=" + text);
                      fs.readFile("./a.txt", (bufferError, buffer) => {
                        console.log("read.buffer=" + (bufferError === null) + "/" + Buffer.isBuffer(buffer) + "/" + buffer.toString());
                        fs.stat("./a.txt", (statError, stat) => {
                          console.log("stat.file=" + (statError === null) + "/" + stat.isFile());
                          fs.mkdir("./dir/sub", { recursive: true }, (mkdirError) => {
                            console.log("mkdir.err=" + (mkdirError === null));
                            fs.writeFile("./dir/sub/file.txt", "x", "utf8", (nestedWriteError) => {
                              console.log("nested.write.err=" + (nestedWriteError === null));
                              fs.lstat("./dir", (lstatError, lstat) => {
                                console.log("lstat.dir=" + (lstatError === null) + "/" + lstat.isDirectory());
                                fs.access("./a.txt", fs.constants.R_OK, (accessError) => {
                                  console.log("access.err=" + (accessError === null));
                                  fs.readdir("./dir", (readdirError, entries) => {
                                    console.log("readdir=" + (readdirError === null) + "/" + entries.includes("sub"));
                                    fs.unlink("./a.txt", (unlinkError) => {
                                      console.log("unlink.err=" + (unlinkError === null));
                                      fs.rm("./dir", { recursive: true, force: true }, (rmError) => {
                                        console.log("rm.err=" + (rmError === null));
                                        console.log("final.exists=" + fs.existsSync("./a.txt") + "/" + fs.existsSync("./dir"));
                                      });
                                    });
                                  });
                                });
                              });
                            });
                          });
                        });
                      });
                    });
                  });
                });
                console.log("sync.after.schedule=true");
                """.trimIndent(),
                "<embedded-scoped-fs-callback-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertOutputOrder(result.stdout, "sync.after.schedule=true", "write.err=true", "rm.err=true")
            assertTrue(result.stdout.contains("promises=object"))
            assertTrue(result.stdout.contains("callback.types=true"))
            assertTrue(result.stdout.contains("write.err=true"))
            assertTrue(result.stdout.contains("append.err=true"))
            assertTrue(result.stdout.contains("read.err=true"))
            assertTrue(result.stdout.contains("read.text=hello world"))
            assertTrue(result.stdout.contains("read.buffer=true/true/hello world"))
            assertTrue(result.stdout.contains("stat.file=true/true"))
            assertTrue(result.stdout.contains("mkdir.err=true"))
            assertTrue(result.stdout.contains("nested.write.err=true"))
            assertTrue(result.stdout.contains("lstat.dir=true/true"))
            assertTrue(result.stdout.contains("access.err=true"))
            assertTrue(result.stdout.contains("readdir=true/true"))
            assertTrue(result.stdout.contains("unlink.err=true"))
            assertTrue(result.stdout.contains("rm.err=true"))
            assertTrue(result.stdout.contains("final.exists=false/false"))
            assertFalse(File(scriptDir, "a.txt").exists())
            assertFalse(File(scriptDir, "dir").exists())
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsSupportsReadWriteStreamsAndRejectsUnsafeStreamOptions() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-stream-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs stream test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const nodeFs = require("node:fs");
                const fsp = require("fs/promises");
                const url = require("url");

                function writeStream(pathValue, text, options) {
                  return new Promise((resolve, reject) => {
                    const writable = fs.createWriteStream(pathValue, options);
                    writable.on("error", reject);
                    writable.on("finish", resolve);
                    writable.end(text);
                  });
                }

                function readStream(pathValue, options) {
                  return new Promise((resolve, reject) => {
                    let text = "";
                    const readable = fs.createReadStream(pathValue, options);
                    readable.on("data", (chunk) => {
                      text += chunk.toString();
                    });
                    readable.on("error", reject);
                    readable.on("end", () => resolve(text));
                  });
                }

                function streamError(action) {
                  return new Promise((resolve) => {
                    let stream;
                    try {
                      stream = action();
                    } catch (error) {
                      resolve("throw:" + error.code + "/" + String(error.message).includes("Embedded Node scoped fs"));
                      return;
                    }
                    stream.on("error", (error) => {
                      resolve("error:" + error.code);
                    });
                    if (typeof stream.resume === "function") {
                      stream.resume();
                    }
                  });
                }

                function writeStreamError(pathValue, text, options) {
                  return new Promise((resolve) => {
                    let writable;
                    try {
                      writable = fs.createWriteStream(pathValue, options);
                    } catch (error) {
                      resolve("throw:" + error.code);
                      return;
                    }
                    writable.on("error", (error) => {
                      resolve("error:" + error.code);
                    });
                    writable.on("finish", () => resolve("finish"));
                    writable.end(text);
                  });
                }

                function captureSync(action, token) {
                  try {
                    action();
                    return false;
                  } catch (error) {
                    return error instanceof Error && String(error.message).includes(token);
                  }
                }

                return (async () => {
                  fs.mkdirSync("./streams", { recursive: true });
                  await writeStream("./streams/out.txt", "file-stream", { encoding: "utf8" });
                  const text = await readStream("./streams/out.txt", { encoding: "utf8", flags: "r" });
                  const urlFile = url.pathToFileURL("./streams/url.txt");
                  await writeStream(urlFile, "url-stream", "utf8");
                  const urlText = await readStream(urlFile, "utf8");
                  fs.writeFileSync("./streams/path-modern.txt", "0123456789", "utf8");
                  const pathModernReadText = await readStream("./streams/path-modern.txt", {
                    encoding: "utf8",
                    start: 2,
                    end: 5,
                    highWaterMark: 2,
                    emitClose: false
                  });
                  await writeStream("./streams/path-modern.txt", "XYZ", {
                    encoding: "utf8",
                    flags: "r+",
                    start: 6,
                    highWaterMark: 1,
                    emitClose: false,
                    flush: true
                  });
                  const streamAbortReadController = new AbortController();
                  streamAbortReadController.abort();
                  const streamAbortRead = await streamError(() => fs.createReadStream("./streams/path-modern.txt", {
                    encoding: "utf8",
                    signal: streamAbortReadController.signal
                  }));
                  const streamAbortWriteController = new AbortController();
                  streamAbortWriteController.abort();
                  const streamAbortWrite = await writeStreamError("./streams/path-modern.txt", "ABORT", {
                    encoding: "utf8",
                    flags: "r+",
                    start: 0,
                    signal: streamAbortWriteController.signal
                  });
                  const ownedReadFd = fs.openSync("./streams/out.txt", "r");
                  const ownedReadText = await readStream(undefined, { fd: ownedReadFd, autoClose: true, encoding: "utf8" });
                  const ownedReadClosed = captureSync(() => fs.closeSync(ownedReadFd), "not open or not owned");
                  const manualReadFd = fs.openSync("./streams/out.txt", "r");
                  const manualReadText = await readStream(null, { fd: manualReadFd, autoClose: false, encoding: "utf8" });
                  const manualReadStillOpen = fs.fstatSync(manualReadFd).isFile();
                  fs.closeSync(manualReadFd);
                  const ownedWriteFd = fs.openSync("./streams/fd-write.txt", "w");
                  await writeStream(undefined, "fd-write", { fd: ownedWriteFd, autoClose: true, encoding: "utf8" });
                  const ownedWriteClosed = captureSync(() => fs.closeSync(ownedWriteFd), "not open or not owned");
                  fs.writeFileSync("./streams/range.txt", "0123456789", "utf8");
                  const fileHandleReadFd = await fsp.open("./streams/range.txt", "r");
                  const fileHandleReadText = await readStream("./streams/ignored-read.txt", {
                    fd: fileHandleReadFd,
                    autoClose: false,
                    encoding: "utf8",
                    start: 2,
                    end: 5,
                    highWaterMark: 2,
                    emitClose: false
                  });
                  const fileHandleReadStillOpen = (await fileHandleReadFd.stat()).isFile();
                  await fileHandleReadFd.close();
                  fs.writeFileSync("./streams/filehandle-write.txt", "0123456789", "utf8");
                  const fileHandleWriteFd = await fsp.open("./streams/filehandle-write.txt", "r+");
                  await writeStream("./streams/ignored-write.txt", "XYZ", {
                    fd: fileHandleWriteFd,
                    autoClose: false,
                    encoding: "utf8",
                    start: 3,
                    highWaterMark: 2,
                    emitClose: false,
                    flush: true
                  });
                  const fileHandleWriteStillOpen = (await fileHandleWriteFd.stat()).isFile();
                  await fileHandleWriteFd.close();
                  const missing = await streamError(() => fs.createReadStream("./streams/missing.txt", "utf8"));
                  const fdPathGuardReadFd = fs.openSync("./streams/out.txt", "r");
                  const fdPathGuardWriteFd = fs.openSync("./streams/fd-path-guard.txt", "w");
                  const inheritedFdOptions = Object.create({ fd: 0 });
                  const inheritedFlagsOptions = Object.create({ flags: "w" });
                  const denied = [
                    captureSync(() => fs.createReadStream("../outside.txt"), "escapes working directory"),
                    captureSync(() => fs.createWriteStream("/sdcard/autojs6-stream.txt"), "rejects absolute path"),
                    captureSync(() => fs.createReadStream("/proc/self/cmdline"), "rejects absolute path"),
                    captureSync(() => fs.createReadStream("/sys/kernel"), "rejects absolute path"),
                    captureSync(() => fs.createWriteStream("/dev/null"), "rejects absolute path"),
                    captureSync(() => fs.createReadStream("./streams/out.txt", { fd: 0 }), "not open or not owned"),
                    captureSync(() => fs.createWriteStream("./streams/out.txt", { fd: 1 }), "not open or not owned"),
                    captureSync(() => fs.createReadStream("./streams/out.txt", { flags: "w" }), "read stream flags"),
                    captureSync(() => fs.createReadStream("./streams/out.txt", inheritedFdOptions), "fd option is unsupported"),
                    captureSync(() => fs.createReadStream("./streams/out.txt", inheritedFlagsOptions), "read stream flags"),
                    captureSync(() => fs.createReadStream("./streams/out.txt", { fs: { read() {} } }), "fs option is unsupported"),
                    captureSync(() => fs.createWriteStream("./streams/out.txt", { fs: { write() {} } }), "fs option is unsupported"),
                    captureSync(() => fs.createReadStream("../ignored-fd-read.txt", {
                      fd: fdPathGuardReadFd,
                      autoClose: false
                    }), "escapes working directory"),
                    captureSync(() => fs.createWriteStream("../ignored-fd-write.txt", {
                      fd: fdPathGuardWriteFd,
                      autoClose: false
                    }), "escapes working directory")
                  ];
                  fs.closeSync(fdPathGuardReadFd);
                  fs.closeSync(fdPathGuardWriteFd);
                  console.log("fs.stream.alias=" + (fs === nodeFs));
                  console.log("fs.stream.types=" + [typeof fs.createReadStream, typeof fs.createWriteStream].join(","));
                  console.log("fs.stream.read=" + text);
                  console.log("fs.stream.write=" + fs.readFileSync("./streams/out.txt", "utf8"));
                  console.log("fs.stream.url=" + urlText);
                  console.log("fs.stream.modern=" + [
                    pathModernReadText,
                    fs.readFileSync("./streams/path-modern.txt", "utf8"),
                    streamAbortRead,
                    streamAbortWrite
                  ].join("|"));
                  console.log("fs.stream.fd=" + [
                    ownedReadText,
                    ownedReadClosed,
                    manualReadText,
                    manualReadStillOpen,
                    fs.readFileSync("./streams/fd-write.txt", "utf8"),
                    ownedWriteClosed
                  ].join("|"));
                  console.log("fs.stream.filehandle_fd=" + [
                    fileHandleReadText,
                    fileHandleReadStillOpen,
                    fs.readFileSync("./streams/filehandle-write.txt", "utf8"),
                    fileHandleWriteStillOpen
                  ].join("|"));
                  console.log("fs.stream.missing=" + missing);
                  console.log("fs.stream.denied=" + denied.filter(Boolean).length + "/" + denied.length);
                })();
                """.trimIndent(),
                "<embedded-scoped-fs-stream-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("fs.stream.alias=true"))
            assertTrue(result.stdout.contains("fs.stream.types=function,function"))
            assertTrue(result.stdout.contains("fs.stream.read=file-stream"))
            assertTrue(result.stdout.contains("fs.stream.write=file-stream"))
            assertTrue(result.stdout.contains("fs.stream.url=url-stream"))
            assertTrue(result.stdout.contains("fs.stream.modern=2345|012345XYZ9|error:ABORT_ERR|error:ABORT_ERR"))
            assertTrue(result.stdout.contains("fs.stream.fd=file-stream|true|file-stream|true|fd-write|true"))
            assertTrue(result.stdout.contains("fs.stream.filehandle_fd=2345|true|012XYZ6789|true"))
            assertTrue(result.stdout.contains("fs.stream.missing=error:ENOENT"))
            assertTrue(result.stdout.contains("fs.stream.denied=14/14"))
            assertEquals(false, result.pendingScopedFsStreams)
            assertEquals(0, result.pendingScopedFsStreamCount)
            assertEquals("file-stream", File(scriptDir, "streams/out.txt").readText(StandardCharsets.UTF_8))
            assertEquals("url-stream", File(scriptDir, "streams/url.txt").readText(StandardCharsets.UTF_8))
            assertEquals("fd-write", File(scriptDir, "streams/fd-write.txt").readText(StandardCharsets.UTF_8))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsClassSurfaceSupportsInstanceofWithoutConstructorBypass() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-class-surface-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs class surface test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const nodeFs = require("node:fs");
                const fsp = require("fs/promises");

                function readStreamText(stream) {
                  return new Promise((resolve, reject) => {
                    let text = "";
                    stream.setEncoding("utf8");
                    stream.on("data", (chunk) => { text += chunk; });
                    stream.on("error", reject);
                    stream.on("end", () => resolve(text));
                  });
                }

                function writeStreamText(stream, text) {
                  return new Promise((resolve, reject) => {
                    stream.on("error", reject);
                    stream.on("finish", resolve);
                    stream.end(text);
                  });
                }

                function waitEvent(emitter, event) {
                  return new Promise((resolve, reject) => {
                    emitter.once("error", reject);
                    emitter.once(event, resolve);
                  });
                }

                function writeUtf8Stream(options, text) {
                  return new Promise((resolve, reject) => {
                    const stream = new fs.Utf8Stream(options);
                    const instanceOk = stream instanceof fs.Utf8Stream;
                    stream.on("error", reject);
                    stream.on("ready", () => {
                      stream.write(text);
                      stream.end();
                    });
                    stream.on("close", () => resolve(instanceOk));
                  });
                }

                function captureSync(action, token) {
                  try {
                    const value = action();
                    if (value && typeof value.destroy === "function") {
                      value.destroy();
                    }
                    return false;
                  } catch (error) {
                    return String(error && error.message || error).includes(token);
                  }
                }

                return (async () => {
                  fs.mkdirSync("./classes/sub", { recursive: true });
                  fs.writeFileSync("./classes/file.txt", "class-surface", "utf8");

                  const stat = fs.statSync("./classes/file.txt");
                  const promiseStat = await fsp.lstat("./classes/file.txt");
                  const dirents = fs.readdirSync("./classes", { withFileTypes: true });
                  const dirent = dirents.find((entry) => entry.name === "file.txt");
                  const promiseDirents = await fsp.readdir("./classes", { withFileTypes: true });
                  const promiseDirent = promiseDirents.find((entry) => entry.name === "sub");
                  const syncDir = fs.opendirSync("./classes");
                  const syncDirEntry = syncDir.readSync();
                  syncDir.closeSync();
                  const promiseDir = await fsp.opendir("./classes");
                  const promiseDirEntry = await promiseDir.read();
                  await promiseDir.close();

                  const readText = await readStreamText(new fs.ReadStream("./classes/file.txt"));
                  const createReadInstance = await new Promise((resolve, reject) => {
                    const stream = fs.createReadStream("./classes/file.txt");
                    const instanceOk = stream instanceof fs.ReadStream;
                    stream.on("error", reject);
                    stream.on("close", () => resolve(instanceOk));
                    stream.resume();
                  });
                  const writeStream = new fs.WriteStream("./classes/out.txt", { encoding: "utf8" });
                  const writeStreamInstance = writeStream instanceof fs.WriteStream;
                  await writeStreamText(writeStream, "constructor-write");
                  const aliasRead = fs.FileReadStream === fs.ReadStream;
                  const aliasWrite = fs.FileWriteStream === fs.WriteStream;
                  const utf8StreamInstance = await writeUtf8Stream({ dest: "./classes/utf8.txt", sync: true }, "utf8-class");
                  const utf8ReopenStream = new fs.Utf8Stream({ dest: "./classes/utf8-reopen.txt", sync: true });
                  await waitEvent(utf8ReopenStream, "ready");
                  const utf8ReopenDenied = captureSync(
                    () => utf8ReopenStream.reopen("../outside-utf8-reopen.txt"),
                    "escapes working directory"
                  );
                  utf8ReopenStream.end();
                  await waitEvent(utf8ReopenStream, "close");
                  fs.accessSync("./classes/file.txt", fs.R_OK);
                  const topLevelConstants =
                    fs.F_OK === fs.constants.F_OK &&
                    fs.R_OK === fs.constants.R_OK &&
                    fs.W_OK === fs.constants.W_OK &&
                    fs.X_OK === fs.constants.X_OK &&
                    fs.COPYFILE_EXCL === fs.constants.COPYFILE_EXCL &&
                    fs.COPYFILE_FICLONE === fs.constants.COPYFILE_FICLONE &&
                    fs.COPYFILE_FICLONE_FORCE === fs.constants.COPYFILE_FICLONE_FORCE;

                  const manualDirent = new fs.Dirent("manual.txt", 1, ".");
                  const denied = [
                    captureSync(() => new fs.Dir("../outside"), "constructor is unavailable"),
                    captureSync(() => new fs.Dir.prototype.constructor("../outside-prototype"), "constructor is unavailable"),
                    captureSync(() => new fs.ReadStream("../outside-read.txt"), "escapes working directory"),
                    captureSync(() => new fs.ReadStream.prototype.constructor("../outside-read-prototype.txt"), "escapes working directory"),
                    captureSync(() => fs.ReadStream("/sdcard/autojs6-readstream.txt"), "rejects absolute path"),
                    captureSync(() => new fs.WriteStream("../outside-write.txt"), "escapes working directory"),
                    captureSync(() => new fs.WriteStream.prototype.constructor("../outside-write-prototype.txt"), "escapes working directory"),
                    captureSync(() => fs.WriteStream("./classes/out.txt", { fs: { write() {} } }), "fs option is unsupported"),
                    captureSync(() => new fs.Utf8Stream({ dest: "../outside-utf8.txt" }), "escapes working directory"),
                    captureSync(() => new fs.Utf8Stream.prototype.constructor({ dest: "../outside-utf8-prototype.txt" }), "escapes working directory"),
                    captureSync(() => new fs.Utf8Stream({ dest: "/sdcard/autojs6-utf8stream.txt" }), "rejects absolute path"),
                    captureSync(() => new fs.Utf8Stream({ fd: 987654321 }), "not open or not owned"),
                    captureSync(() => new fs.Utf8Stream({ dest: "./classes/utf8-fs.txt", fs: { open() {} } }), "fs option is unsupported"),
                    captureSync(() => fs.Utf8Stream({ dest: "./classes/utf8-call.txt" }), "Class constructor"),
                    utf8ReopenDenied
                  ];

                  console.log("fs.class.alias=" + (fs === nodeFs));
                  console.log("fs.class.types=" + [
                    typeof fs.Stats,
                    typeof fs.Dirent,
                    typeof fs.Dir,
                    typeof fs.ReadStream,
                    typeof fs.WriteStream,
                    typeof fs.FileReadStream,
                    typeof fs.FileWriteStream,
                    typeof fs.Utf8Stream
                  ].join(","));
                  console.log("fs.class.stats=" + (
                    stat instanceof fs.Stats &&
                    promiseStat instanceof fs.Stats &&
                    stat.isFile() &&
                    promiseStat.isFile()
                  ));
                  console.log("fs.class.dirent=" + (
                    dirent instanceof fs.Dirent &&
                    promiseDirent instanceof fs.Dirent &&
                    syncDirEntry instanceof fs.Dirent &&
                    promiseDirEntry instanceof fs.Dirent &&
                    manualDirent instanceof fs.Dirent &&
                    typeof dirent.parentPath === "string" &&
                    dirent.isFile() &&
                    promiseDirent.isDirectory()
                  ));
                  console.log("fs.class.dir=" + (
                    syncDir instanceof fs.Dir &&
                    promiseDir instanceof fs.Dir &&
                    typeof syncDir.read === "function" &&
                    typeof promiseDir[Symbol.asyncIterator] === "function"
                  ));
                  console.log("fs.class.stream=" + (
                    aliasRead &&
                    aliasWrite &&
                    readText === "class-surface" &&
                    createReadInstance &&
                    writeStreamInstance &&
                    fs.readFileSync("./classes/out.txt", "utf8") === "constructor-write"
                  ));
                  console.log("fs.class.utf8_stream=" + (
                    utf8StreamInstance &&
                    fs.readFileSync("./classes/utf8.txt", "utf8") === "utf8-class" &&
                    fs.readFileSync("./classes/utf8-reopen.txt", "utf8") === ""
                  ));
                  console.log("fs.class.top_constants=" + topLevelConstants);
                  console.log("fs.class.denied=" + denied.filter(Boolean).length + "/" + denied.length);
                })();
                """.trimIndent(),
                "<embedded-scoped-fs-class-surface-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("fs.class.alias=true"))
            assertTrue(result.stdout.contains("fs.class.types=function,function,function,function,function,function,function,function"))
            assertTrue(result.stdout.contains("fs.class.stats=true"))
            assertTrue(result.stdout.contains("fs.class.dirent=true"))
            assertTrue(result.stdout.contains("fs.class.dir=true"))
            assertTrue(result.stdout.contains("fs.class.stream=true"))
            assertTrue(result.stdout.contains("fs.class.utf8_stream=true"))
            assertTrue(result.stdout.contains("fs.class.top_constants=true"))
            assertTrue(result.stdout.contains("fs.class.denied=15/15"))
            assertEquals("constructor-write", File(scriptDir, "classes/out.txt").readText(StandardCharsets.UTF_8))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsWatchSupportsScopedFilesAndClosesWatchers() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-watch-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs watch test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const nodeFs = require("node:fs");
                const path = require("path");
                const url = require("url");

                function delay(ms) {
                  return new Promise((resolve) => setTimeout(resolve, ms));
                }

                function watchWithListener(pathValue, changeAction) {
                  return new Promise((resolve, reject) => {
                    let watcher;
                    const timeout = setTimeout(() => {
                      if (watcher) watcher.close();
                      reject(new Error("watch timeout: " + pathValue));
                    }, 2000);
                    watcher = fs.watch(pathValue, { persistent: true }, (eventType, filename) => {
                      clearTimeout(timeout);
                      watcher.close();
                      resolve({ eventType, filename });
                    });
                    setTimeout(changeAction, 120);
                  });
                }

                function watchWithOptions(pathValue, options, changeAction) {
                  return new Promise((resolve, reject) => {
                    let watcher;
                    const timeout = setTimeout(() => {
                      if (watcher) watcher.close();
                      reject(new Error("watch options timeout: " + pathValue));
                    }, 2000);
                    watcher = fs.watch(pathValue, options, (eventType, filename) => {
                      clearTimeout(timeout);
                      watcher.close();
                      resolve({ eventType, filename });
                    });
                    setTimeout(changeAction, 120);
                  });
                }

                function watchWithEvent(pathValue, changeAction) {
                  return new Promise((resolve, reject) => {
                    const watcher = fs.watch(pathValue, { persistent: true });
                    const timeout = setTimeout(() => {
                      watcher.close();
                      reject(new Error("watch event timeout: " + pathValue));
                    }, 2000);
                    watcher.on("change", (eventType, filename) => {
                      clearTimeout(timeout);
                      watcher.close();
                      resolve({ eventType, filename });
                    });
                    setTimeout(changeAction, 120);
                  });
                }

                function captureSync(action, token) {
                  try {
                    action();
                    return false;
                  } catch (error) {
                    return String(error && error.message || error).includes(token);
                  }
                }

                return (async () => {
                  fs.mkdirSync("./watch-native", { recursive: true });
                  fs.writeFileSync("./watch-native/file.txt", "a", "utf8");
                  fs.writeFileSync("./watch-native/event.txt", "a", "utf8");
                  fs.writeFileSync("./watch-native/passive.txt", "a", "utf8");
                  fs.writeFileSync("./watch-native/abort.txt", "a", "utf8");
                  fs.writeFileSync("./watch-native/preabort.txt", "a", "utf8");
                  fs.writeFileSync("./watch-native/string-options.txt", "a", "utf8");
                  fs.writeFileSync("./watch-native/null-listener.txt", "a", "utf8");
                  fs.writeFileSync("./watch-native/url.txt", "a", "utf8");
                  fs.writeFileSync("./watch-native/buffer.txt", "a", "utf8");
                  console.log("fs.watch.alias=" + (fs === nodeFs));
                  console.log("fs.watch.types=" + [
                    typeof fs.watch,
                    typeof fs.watchFile,
                    typeof fs.unwatchFile
                  ].join(","));

                  const callbackEvent = await watchWithListener(
                    "./watch-native/file.txt",
                    () => fs.writeFileSync("./watch-native/file.txt", "abcd", "utf8")
                  );
                  console.log("fs.watch.callback=" + (
                    (callbackEvent.eventType === "change" || callbackEvent.eventType === "rename") &&
                    (callbackEvent.filename === null || String(callbackEvent.filename).length >= 0)
                  ));

                  const emitterEvent = await watchWithEvent(
                    "./watch-native/event.txt",
                    () => fs.writeFileSync("./watch-native/event.txt", "abcde", "utf8")
                  );
                  console.log("fs.watch.emitter=" + (
                    (emitterEvent.eventType === "change" || emitterEvent.eventType === "rename") &&
                    (emitterEvent.filename === null || String(emitterEvent.filename).length >= 0)
                  ));

                  const optionsObject = { persistent: true, encoding: "buffer" };
                  const objectOptionsEvent = await watchWithOptions(
                    "./watch-native",
                    optionsObject,
                    () => fs.writeFileSync("./watch-native/buffer-options.txt", "buffer", "utf8")
                  );
                  const stringOptionsEvent = await watchWithOptions(
                    "./watch-native/string-options.txt",
                    "buffer",
                    () => fs.writeFileSync("./watch-native/string-options.txt", "abcdef", "utf8")
                  );
                  console.log("fs.watch.options=" + (
                    (objectOptionsEvent.eventType === "change" || objectOptionsEvent.eventType === "rename") &&
                    (objectOptionsEvent.filename === null || Buffer.isBuffer(objectOptionsEvent.filename)) &&
                    (stringOptionsEvent.eventType === "change" || stringOptionsEvent.eventType === "rename") &&
                    (stringOptionsEvent.filename === null || Buffer.isBuffer(stringOptionsEvent.filename)) &&
                    optionsObject.persistent === true &&
                    optionsObject.encoding === "buffer"
                  ));

                  const passive = fs.watch("./watch-native/passive.txt", { persistent: false });
                  const passiveTypes = [typeof passive.close, typeof passive.ref, typeof passive.unref].join(",");
                  passive.close();
                  console.log("fs.watch.passive=" + passiveTypes);

                  fs.writeFileSync("./watch-native/ref-unref.txt", "a", "utf8");
                  const refUnrefWatcher = fs.watch("./watch-native/ref-unref.txt", { persistent: true }, () => {});
                  const refUnrefTypes = [typeof refUnrefWatcher.ref, typeof refUnrefWatcher.unref].join(",");
                  const refUnrefReturns = refUnrefWatcher.unref() === refUnrefWatcher &&
                    refUnrefWatcher.ref() === refUnrefWatcher &&
                    refUnrefWatcher.unref() === refUnrefWatcher;
                  console.log("fs.watch.ref_unref=" + refUnrefTypes + "/" + refUnrefReturns);

                  const nullListenerWatcher = fs.watch("./watch-native/null-listener.txt", { persistent: false }, null);
                  const nullListenerTypes = [typeof nullListenerWatcher.close, typeof nullListenerWatcher.on].join(",");
                  nullListenerWatcher.close();
                  nullListenerWatcher.close();
                  console.log("fs.watch.null_listener=" + nullListenerTypes);

                  const urlPathEvent = await watchWithListener(
                    url.pathToFileURL(path.resolve(process.cwd(), "./watch-native/url.txt")),
                    () => fs.writeFileSync("./watch-native/url.txt", "url", "utf8")
                  );
                  const bufferPathEvent = await watchWithListener(
                    Buffer.from("./watch-native/buffer.txt"),
                    () => fs.writeFileSync("./watch-native/buffer.txt", "buffer", "utf8")
                  );
                  console.log("fs.watch.pathlike=" + (
                    (urlPathEvent.eventType === "change" || urlPathEvent.eventType === "rename") &&
                    (urlPathEvent.filename === null || String(urlPathEvent.filename).length >= 0) &&
                    (bufferPathEvent.eventType === "change" || bufferPathEvent.eventType === "rename") &&
                    (bufferPathEvent.filename === null || String(bufferPathEvent.filename).length >= 0)
                  ));

                  const AbortControllerCtor = globalThis.AbortController;
                  let abortClosed = false;
                  let preAbortClosed = false;
                  if (typeof AbortControllerCtor === "function") {
                    const controller = new AbortControllerCtor();
                    const abortWatcher = fs.watch("./watch-native/abort.txt", { signal: controller.signal }, () => {});
                    abortClosed = await new Promise((resolve) => {
                      const timeout = setTimeout(() => {
                        abortWatcher.close();
                        resolve(false);
                      }, 1000);
                      abortWatcher.on("close", () => {
                        clearTimeout(timeout);
                        resolve(true);
                      });
                      controller.abort();
                    });

                    const preController = new AbortControllerCtor();
                    preController.abort();
                    const preAbortWatcher = fs.watch("./watch-native/preabort.txt", { signal: preController.signal }, null);
                    preAbortClosed = await new Promise((resolve) => {
                      const timeout = setTimeout(() => {
                        preAbortWatcher.close();
                        resolve(false);
                      }, 1000);
                      preAbortWatcher.on("close", () => {
                        clearTimeout(timeout);
                        resolve(true);
                      });
                    });
                  }
                  console.log("fs.watch.abort=" + abortClosed);
                  console.log("fs.watch.preabort=" + preAbortClosed);

                  const denied = [
                    captureSync(() => fs.watch("../outside.txt", () => {}), "escapes working directory"),
                    captureSync(() => fs.watch(Buffer.from("../outside-buffer-watch.txt"), () => {}), "escapes working directory"),
                    captureSync(() => fs.watch("/sdcard/autojs6-watch.txt", () => {}), "rejects absolute path"),
                    captureSync(() => fs.watch("./watch-native/missing.txt", () => {}), "path does not exist"),
                    captureSync(() => fs.watch("./watch-native/file.txt", { recursive: true }, () => {}), "recursive option"),
                    captureSync(() => fs.watch("./watch-native/file.txt", "utf8", "bad"), "listener must be a function")
                  ];
                  console.log("fs.watch.denied=" + denied.filter(Boolean).length + "/" + denied.length);
                })();
                """.trimIndent(),
                "<embedded-scoped-fs-watch-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("fs.watch.alias=true"))
            assertTrue(result.stdout.contains("fs.watch.types=function,function,function"))
            assertTrue(result.stdout.contains("fs.watch.callback=true"))
            assertTrue(result.stdout.contains("fs.watch.emitter=true"))
            assertTrue(result.stdout.contains("fs.watch.options=true"))
            assertTrue(result.stdout.contains("fs.watch.passive=function,function,function"))
            assertTrue(result.stdout.contains("fs.watch.ref_unref=function,function/true"))
            assertTrue(result.stdout.contains("fs.watch.null_listener=function,function"))
            assertTrue(result.stdout.contains("fs.watch.pathlike=true"))
            assertTrue(result.stdout.contains("fs.watch.abort=true"))
            assertTrue(result.stdout.contains("fs.watch.preabort=true"))
            assertTrue(result.stdout.contains("fs.watch.denied=6/6"))
            assertEquals("abcd", File(scriptDir, "watch-native/file.txt").readText(StandardCharsets.UTF_8))
            assertEquals("abcde", File(scriptDir, "watch-native/event.txt").readText(StandardCharsets.UTF_8))
            assertEquals("abcdef", File(scriptDir, "watch-native/string-options.txt").readText(StandardCharsets.UTF_8))
            assertEquals("url", File(scriptDir, "watch-native/url.txt").readText(StandardCharsets.UTF_8))
            assertEquals("buffer", File(scriptDir, "watch-native/buffer.txt").readText(StandardCharsets.UTF_8))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsPromisesWatchSupportsScopedAsyncIteratorAndAbort() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-promises-watch-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs promises watch test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const fsp = require("fs/promises");
                const nodeFsp = require("node:fs/promises");
                const path = require("path");
                const url = require("url");

                function watchNext(pathValue, options, changeAction) {
                  if (typeof options === "function") {
                    changeAction = options;
                    options = { persistent: true };
                  }
                  return (async () => {
                    const iterator = fsp.watch(pathValue, options);
                    const pending = iterator.next();
                    setTimeout(changeAction, 120);
                    const result = await pending;
                    await iterator.return();
                    return result.value;
                  })();
                }

                function captureSync(action, token) {
                  try {
                    action();
                    return false;
                  } catch (error) {
                    return String(error && error.message || error).includes(token);
                  }
                }

                return (async () => {
                  fs.mkdirSync("./watch-promises", { recursive: true });
                  fs.writeFileSync("./watch-promises/file.txt", "a", "utf8");
                  fs.writeFileSync("./watch-promises/loop.txt", "a", "utf8");
                  fs.writeFileSync("./watch-promises/passive.txt", "a", "utf8");
                  fs.writeFileSync("./watch-promises/abort.txt", "a", "utf8");
                  fs.writeFileSync("./watch-promises/preabort.txt", "a", "utf8");
                  fs.writeFileSync("./watch-promises/string-options.txt", "a", "utf8");
                  fs.writeFileSync("./watch-promises/dispose.txt", "a", "utf8");
                  fs.writeFileSync("./watch-promises/return.txt", "a", "utf8");
                  fs.writeFileSync("./watch-promises/url.txt", "a", "utf8");
                  fs.writeFileSync("./watch-promises/buffer.txt", "a", "utf8");
                  console.log("fsp.watch.alias=" + (fs.promises === fsp && fsp === nodeFsp));
                  console.log("fsp.watch.types=" + [
                    typeof fsp.watch,
                    typeof fsp.open,
                    typeof fsp.readFile
                  ].join(","));

                  const callbackEvent = await watchNext(
                    "./watch-promises/file.txt",
                    () => fs.writeFileSync("./watch-promises/file.txt", "abcd", "utf8")
                  );
                  console.log("fsp.watch.next=" + (
                    callbackEvent &&
                    (callbackEvent.eventType === "change" || callbackEvent.eventType === "rename") &&
                    (callbackEvent.filename === null || String(callbackEvent.filename).length >= 0)
                  ));

                  const loopEvent = await (async () => {
                    const iterator = fsp.watch("./watch-promises/loop.txt", { persistent: true });
                    setTimeout(() => fs.writeFileSync("./watch-promises/loop.txt", "abcde", "utf8"), 120);
                    for await (const event of iterator) {
                      return event;
                    }
                    return null;
                  })();
                  console.log("fsp.watch.loop=" + (
                    loopEvent &&
                    (loopEvent.eventType === "change" || loopEvent.eventType === "rename") &&
                    (loopEvent.filename === null || String(loopEvent.filename).length >= 0)
                  ));

                  const optionsObject = { persistent: true, encoding: "buffer", maxQueue: 4, overflow: "error" };
                  const objectOptionsEvent = await watchNext(
                    "./watch-promises",
                    optionsObject,
                    () => fs.writeFileSync("./watch-promises/buffer-options.txt", "buffer", "utf8")
                  );
                  const stringOptionsEvent = await watchNext(
                    "./watch-promises/string-options.txt",
                    "buffer",
                    () => fs.writeFileSync("./watch-promises/string-options.txt", "abcdef", "utf8")
                  );
                  console.log("fsp.watch.options=" + (
                    objectOptionsEvent &&
                    (objectOptionsEvent.eventType === "change" || objectOptionsEvent.eventType === "rename") &&
                    (objectOptionsEvent.filename === null || Buffer.isBuffer(objectOptionsEvent.filename)) &&
                    stringOptionsEvent &&
                    (stringOptionsEvent.eventType === "change" || stringOptionsEvent.eventType === "rename") &&
                    (stringOptionsEvent.filename === null || Buffer.isBuffer(stringOptionsEvent.filename)) &&
                    optionsObject.persistent === true &&
                    optionsObject.encoding === "buffer" &&
                    optionsObject.maxQueue === 4 &&
                    optionsObject.overflow === "error"
                  ));

                  const passive = fsp.watch("./watch-promises/passive.txt", { persistent: false });
                  const passiveTypes = [
                    typeof passive.next,
                    typeof passive.return,
                    typeof passive.throw,
                    typeof (typeof Symbol === "function" && Symbol.asyncIterator ? passive[Symbol.asyncIterator] : undefined),
                    typeof (typeof Symbol === "function" && Symbol.asyncDispose ? passive[Symbol.asyncDispose] : undefined)
                  ].join(",");
                  await passive.return();
                  console.log("fsp.watch.passive=" + passiveTypes);

                  const disposable = fsp.watch("./watch-promises/dispose.txt", { persistent: false });
                  const asyncDisposeType = typeof (typeof Symbol === "function" && Symbol.asyncDispose ? disposable[Symbol.asyncDispose] : undefined);
                  let asyncDisposeDone = false;
                  if (asyncDisposeType === "function") {
                    await disposable[Symbol.asyncDispose]();
                    const afterDispose = await disposable.next();
                    asyncDisposeDone = afterDispose && afterDispose.done === true;
                  } else {
                    await disposable.return();
                  }
                  console.log("fsp.watch.asyncDispose=" + asyncDisposeType + "/" + asyncDisposeDone);

                  const returnIterator = fsp.watch("./watch-promises/return.txt", { persistent: false });
                  const firstReturn = await returnIterator.return("first");
                  const secondReturn = await returnIterator.return("second");
                  const afterReturn = await returnIterator.next();
                  console.log("fsp.watch.return=" + (
                    firstReturn && firstReturn.done === true && firstReturn.value === "first" &&
                    secondReturn && secondReturn.done === true && secondReturn.value === "second" &&
                    afterReturn && afterReturn.done === true
                  ));

                  const urlPathEvent = await watchNext(
                    url.pathToFileURL(path.resolve(process.cwd(), "./watch-promises/url.txt")),
                    () => fs.writeFileSync("./watch-promises/url.txt", "url", "utf8")
                  );
                  const bufferPathEvent = await watchNext(
                    Buffer.from("./watch-promises/buffer.txt"),
                    () => fs.writeFileSync("./watch-promises/buffer.txt", "buffer", "utf8")
                  );
                  console.log("fsp.watch.pathlike=" + (
                    urlPathEvent &&
                    (urlPathEvent.eventType === "change" || urlPathEvent.eventType === "rename") &&
                    (urlPathEvent.filename === null || String(urlPathEvent.filename).length >= 0) &&
                    bufferPathEvent &&
                    (bufferPathEvent.eventType === "change" || bufferPathEvent.eventType === "rename") &&
                    (bufferPathEvent.filename === null || String(bufferPathEvent.filename).length >= 0)
                  ));

                  const AbortControllerCtor = globalThis.AbortController;
                  let abortRejected = false;
                  let preAbortRejected = false;
                  let preAbortReturned = false;
                  if (typeof AbortControllerCtor === "function") {
                    const controller = new AbortControllerCtor();
                    const iterator = fsp.watch("./watch-promises/abort.txt", { signal: controller.signal });
                    const pending = iterator.next().then(
                      () => false,
                      (error) => error && (error.name === "AbortError" || error.code === "ABORT_ERR")
                    );
                    controller.abort();
                    abortRejected = await pending;

                    const preController = new AbortControllerCtor();
                    preController.abort();
                    const preAbortIterator = fsp.watch("./watch-promises/preabort.txt", { signal: preController.signal });
                    preAbortRejected = await preAbortIterator.next().then(
                      () => false,
                      (error) => error && (error.name === "AbortError" || error.code === "ABORT_ERR")
                    );
                    const preAbortReturn = await preAbortIterator.return("closed");
                    preAbortReturned = preAbortReturn && preAbortReturn.done === true;
                  }
                  console.log("fsp.watch.abort=" + abortRejected);
                  console.log("fsp.watch.preabort=" + preAbortRejected + "/" + preAbortReturned);

                  const nulPath = "bad" + String.fromCharCode(0) + "path";
                  const denied = [
                    captureSync(() => fsp.watch("../outside.txt"), "escapes working directory"),
                    captureSync(() => fsp.watch(Buffer.from("../outside-buffer-promises-watch.txt")), "escapes working directory"),
                    captureSync(() => fsp.watch("/sdcard/autojs6-promises-watch.txt"), "rejects absolute path"),
                    captureSync(() => fsp.watch("./watch-promises/missing.txt"), "path does not exist"),
                    captureSync(() => fsp.watch("./watch-promises/file.txt", { recursive: true }), "recursive option"),
                    captureSync(() => fsp.watch(nulPath), "rejects NUL")
                  ];
                  console.log("fsp.watch.denied=" + denied.filter(Boolean).length + "/" + denied.length);
                })();
                """.trimIndent(),
                "<embedded-scoped-fs-promises-watch-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("fsp.watch.alias=true"))
            assertTrue(result.stdout.contains("fsp.watch.types=function,function,function"))
            assertTrue(result.stdout.contains("fsp.watch.next=true"))
            assertTrue(result.stdout.contains("fsp.watch.loop=true"))
            assertTrue(result.stdout.contains("fsp.watch.options=true"))
            assertTrue(result.stdout.contains("fsp.watch.passive=function,function,function,function,function"))
            assertTrue(result.stdout.contains("fsp.watch.asyncDispose=function/true"))
            assertTrue(result.stdout.contains("fsp.watch.return=true"))
            assertTrue(result.stdout.contains("fsp.watch.pathlike=true"))
            assertTrue(result.stdout.contains("fsp.watch.abort=true"))
            assertTrue(result.stdout.contains("fsp.watch.preabort=true/true"))
            assertTrue(result.stdout.contains("fsp.watch.denied=6/6"))
            assertEquals("abcd", File(scriptDir, "watch-promises/file.txt").readText(StandardCharsets.UTF_8))
            assertEquals("abcde", File(scriptDir, "watch-promises/loop.txt").readText(StandardCharsets.UTF_8))
            assertEquals("abcdef", File(scriptDir, "watch-promises/string-options.txt").readText(StandardCharsets.UTF_8))
            assertEquals("url", File(scriptDir, "watch-promises/url.txt").readText(StandardCharsets.UTF_8))
            assertEquals("buffer", File(scriptDir, "watch-promises/buffer.txt").readText(StandardCharsets.UTF_8))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsWatchFileSupportsScopedPollingAndUnwatch() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-watch-file-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs watchFile test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const nodeFs = require("node:fs");
                const path = require("path");
                const url = require("url");

                function delay(ms) {
                  return new Promise((resolve) => setTimeout(resolve, ms));
                }

                function watchOnce(pathValue, options, changeAction, accept) {
                  if (typeof options === "function") {
                    accept = changeAction;
                    changeAction = options;
                    options = undefined;
                  }
                  const watchOptions = Object.assign({ interval: 50 }, options || {});
                  return new Promise((resolve, reject) => {
                    const listener = (curr, prev) => {
                      if (accept && !accept(curr, prev)) {
                        return;
                      }
                      clearTimeout(timeout);
                      fs.unwatchFile(pathValue, listener);
                      resolve({ curr, prev });
                    };
                    const timeout = setTimeout(() => {
                      fs.unwatchFile(pathValue, listener);
                      reject(new Error("watchFile timeout: " + pathValue));
                    }, 2000);
                    fs.watchFile(pathValue, watchOptions, listener);
                    setTimeout(changeAction, 120);
                  });
                }

                function captureSync(action, token) {
                  try {
                    action();
                    return false;
                  } catch (error) {
                    return String(error && error.message || error).includes(token);
                  }
                }

                return (async () => {
                  fs.mkdirSync("./watch", { recursive: true });
                  fs.writeFileSync("./watch/file.txt", "a", "utf8");
                  fs.writeFileSync("./watch/url.txt", "a", "utf8");
                  fs.writeFileSync("./watch/buffer.txt", "a", "utf8");
                  console.log("fs.watchFile.alias=" + (fs === nodeFs));
                  console.log("fs.watchFile.types=" + [
                    typeof fs.watchFile,
                    typeof fs.unwatchFile,
                    typeof fs.watch
                  ].join(","));

                  const existing = await watchOnce(
                    "./watch/file.txt",
                    () => fs.writeFileSync("./watch/file.txt", "abcd", "utf8"),
                    (curr) => curr.size === 4
                  );
                  console.log("fs.watchFile.existing=" + existing.prev.size + "/" + existing.curr.size);

                  const urlPathEvent = await watchOnce(
                    url.pathToFileURL(path.resolve(process.cwd(), "./watch/url.txt")),
                    () => fs.writeFileSync("./watch/url.txt", "url", "utf8"),
                    (curr) => curr.size === 3
                  );
                  const bufferPathEvent = await watchOnce(
                    Buffer.from("./watch/buffer.txt"),
                    () => fs.writeFileSync("./watch/buffer.txt", "buffer", "utf8"),
                    (curr) => curr.size === 6
                  );
                  console.log("fs.watchFile.pathlike=" + (
                    urlPathEvent.prev.size === 1 &&
                    urlPathEvent.curr.size === 3 &&
                    bufferPathEvent.prev.size === 1 &&
                    bufferPathEvent.curr.size === 6
                  ));

                  fs.writeFileSync("./watch/bigint.txt", "a", "utf8");
                  const bigintEvent = await watchOnce(
                    "./watch/bigint.txt",
                    { interval: 50, bigint: true },
                    () => fs.writeFileSync("./watch/bigint.txt", "abcdef", "utf8"),
                    (curr) => typeof curr.size === "bigint" && String(curr.size) === "6"
                  );
                  console.log("fs.watchFile.bigint=" + (
                    typeof bigintEvent.prev.size + "/" +
                    typeof bigintEvent.curr.size + "/" +
                    String(bigintEvent.prev.size) + "/" +
                    String(bigintEvent.curr.size)
                  ));

                  const missing = await watchOnce(
                    "./watch/missing.txt",
                    () => fs.writeFileSync("./watch/missing.txt", "created", "utf8"),
                    (curr) => curr.size === 7
                  );
                  console.log("fs.watchFile.missing=" + missing.prev.size + "/" + missing.curr.size);

                  let cancelledCalled = false;
                  const cancelledListener = () => {
                    cancelledCalled = true;
                  };
                  fs.writeFileSync("./watch/cancel.txt", "a", "utf8");
                  fs.watchFile("./watch/cancel.txt", { interval: 50 }, cancelledListener);
                  fs.unwatchFile("./watch/cancel.txt", cancelledListener);
                  fs.writeFileSync("./watch/cancel.txt", "ab", "utf8");
                  await delay(160);
                  console.log("fs.watchFile.cancelled=" + cancelledCalled);

                  const multipleCalls = [];
                  const firstListener = () => {
                    multipleCalls.push("first");
                  };
                  const secondListener = () => {
                    multipleCalls.push("second");
                  };
                  fs.writeFileSync("./watch/multiple.txt", "a", "utf8");
                  fs.watchFile("./watch/multiple.txt", { interval: 50 }, firstListener);
                  fs.watchFile("./watch/multiple.txt", { interval: 50 }, secondListener);
                  fs.unwatchFile("./watch/multiple.txt", firstListener);
                  fs.writeFileSync("./watch/multiple.txt", "ab", "utf8");
                  await delay(260);
                  fs.unwatchFile("./watch/multiple.txt");
                  console.log("fs.watchFile.multiple=" + multipleCalls.join("|"));

                  let nonFunctionUnwatchCalled = false;
                  fs.writeFileSync("./watch/nonfunction-unwatch.txt", "a", "utf8");
                  fs.watchFile("./watch/nonfunction-unwatch.txt", { interval: 50 }, () => {
                    nonFunctionUnwatchCalled = true;
                  });
                  fs.unwatchFile("./watch/nonfunction-unwatch.txt", "bad");
                  fs.writeFileSync("./watch/nonfunction-unwatch.txt", "ab", "utf8");
                  await delay(180);
                  console.log("fs.watchFile.unwatch_nonfunction=" + nonFunctionUnwatchCalled);

                  let stoppedCalled = false;
                  const stopped = fs.watchFile("./watch/stop.txt", { interval: 50 }, () => {
                    stoppedCalled = true;
                  });
                  const stopType = typeof stopped.stop;
                  stopped.stop();
                  fs.writeFileSync("./watch/stop.txt", "stopped", "utf8");
                  await delay(160);
                  console.log("fs.watchFile.stop=" + stopType + "/" + stoppedCalled);

                  fs.writeFileSync("./watch/ref-unref.txt", "a", "utf8");
                  const refUnrefWatcher = fs.watchFile("./watch/ref-unref.txt", { interval: 50 }, () => {});
                  const refUnrefTypes = [typeof refUnrefWatcher.ref, typeof refUnrefWatcher.unref, typeof refUnrefWatcher.stop].join(",");
                  const refUnrefReturns = refUnrefWatcher.unref() === refUnrefWatcher &&
                    refUnrefWatcher.ref() === refUnrefWatcher &&
                    refUnrefWatcher.unref() === refUnrefWatcher;
                  console.log("fs.watchFile.ref_unref=" + refUnrefTypes + "/" + refUnrefReturns);

                  const denied = [
                    captureSync(() => fs.watchFile("../outside.txt", () => {}), "escapes working directory"),
                    captureSync(() => fs.watchFile(Buffer.from("../outside-buffer-watch-file.txt"), () => {}), "escapes working directory"),
                    captureSync(() => fs.unwatchFile("/sdcard/autojs6-watch-file.txt"), "rejects absolute path"),
                    captureSync(() => fs.watchFile("./watch/file.txt", { interval: 50 }, "bad"), "callback must be a function")
                  ];
                  console.log("fs.watchFile.denied=" + denied.filter(Boolean).length + "/" + denied.length);
                })();
                """.trimIndent(),
                "<embedded-scoped-fs-watch-file-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("fs.watchFile.alias=true"))
            assertTrue(result.stdout.contains("fs.watchFile.types=function,function,function"))
            assertTrue(result.stdout.contains("fs.watchFile.existing=1/4"))
            assertTrue(result.stdout.contains("fs.watchFile.pathlike=true"))
            assertTrue(result.stdout.contains("fs.watchFile.bigint=bigint/bigint/1/6"))
            assertTrue(result.stdout.contains("fs.watchFile.missing=0/7"))
            assertTrue(result.stdout.contains("fs.watchFile.cancelled=false"))
            assertTrue(result.stdout.contains("fs.watchFile.multiple=second"))
            assertTrue(result.stdout.contains("fs.watchFile.unwatch_nonfunction=false"))
            assertTrue(result.stdout.contains("fs.watchFile.stop=function/false"))
            assertTrue(result.stdout.contains("fs.watchFile.ref_unref=function,function,function/true"))
            assertTrue(result.stdout.contains("fs.watchFile.denied=4/4"))
            assertEquals("abcd", File(scriptDir, "watch/file.txt").readText(StandardCharsets.UTF_8))
            assertEquals("url", File(scriptDir, "watch/url.txt").readText(StandardCharsets.UTF_8))
            assertEquals("buffer", File(scriptDir, "watch/buffer.txt").readText(StandardCharsets.UTF_8))
            assertEquals("abcdef", File(scriptDir, "watch/bigint.txt").readText(StandardCharsets.UTF_8))
            assertEquals("created", File(scriptDir, "watch/missing.txt").readText(StandardCharsets.UTF_8))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsSupportsOwnedFileDescriptorsAndPromiseFileHandleSubset() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-fd-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs fd test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const nodeFs = require("node:fs");
                const fsp = require("fs/promises");
                const nodeFsp = require("node:fs/promises");

                function callbackOpen(pathValue, flags) {
                  return new Promise((resolve, reject) => {
                    fs.open(pathValue, flags, (error, fd) => {
                      if (error) reject(error);
                      else resolve(fd);
                    });
                  });
                }

                function callbackClose(fd) {
                  return new Promise((resolve, reject) => {
                    fs.close(fd, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                function callbackRead(fd, buffer, offset, length, position) {
                  return new Promise((resolve, reject) => {
                    fs.read(fd, buffer, offset, length, position, (error, bytesRead, returnedBuffer) => {
                      if (error) reject(error);
                      else resolve({ bytesRead, buffer: returnedBuffer });
                    });
                  });
                }

                function callbackReadAny(fd) {
                  const args = Array.prototype.slice.call(arguments, 1);
                  return new Promise((resolve, reject) => {
                    fs.read.apply(fs, [fd].concat(args, [(error, bytesRead, returnedBuffer) => {
                      if (error) reject(error);
                      else resolve({ bytesRead, buffer: returnedBuffer });
                    }]));
                  });
                }

                function callbackWrite(fd, data) {
                  return new Promise((resolve, reject) => {
                    fs.write(fd, data, (error, bytesWritten, returnedData) => {
                      if (error) reject(error);
                      else resolve({ bytesWritten, buffer: returnedData });
                    });
                  });
                }

                function callbackWriteAny(fd) {
                  const data = arguments[1];
                  const args = Array.prototype.slice.call(arguments, 1);
                  return new Promise((resolve, reject) => {
                    fs.write.apply(fs, [fd].concat(args, [(error, bytesWritten, returnedData) => {
                      if (error) reject(error);
                      else resolve({ bytesWritten, buffer: returnedData || data });
                    }]));
                  });
                }

                function callbackReadFileAny(file) {
                  const args = Array.prototype.slice.call(arguments, 1);
                  return new Promise((resolve, reject) => {
                    fs.readFile.apply(fs, [file].concat(args, [(error, data) => {
                      if (error) reject(error);
                      else resolve(data);
                    }]));
                  });
                }

                function callbackWriteFileAny(file, data) {
                  const args = Array.prototype.slice.call(arguments, 2);
                  return new Promise((resolve, reject) => {
                    fs.writeFile.apply(fs, [file, data].concat(args, [(error) => {
                      if (error) reject(error);
                      else resolve();
                    }]));
                  });
                }

                function callbackAppendFileAny(file, data) {
                  const args = Array.prototype.slice.call(arguments, 2);
                  return new Promise((resolve, reject) => {
                    fs.appendFile.apply(fs, [file, data].concat(args, [(error) => {
                      if (error) reject(error);
                      else resolve();
                    }]));
                  });
                }

                function callbackFstat(fd) {
                  return new Promise((resolve, reject) => {
                    fs.fstat(fd, (error, stat) => {
                      if (error) reject(error);
                      else resolve(stat);
                    });
                  });
                }

                function callbackFtruncate(fd, len) {
                  return new Promise((resolve, reject) => {
                    fs.ftruncate(fd, len, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                function callbackFchmod(fd, mode) {
                  return new Promise((resolve, reject) => {
                    fs.fchmod(fd, mode, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                function callbackFchown(fd, uid, gid) {
                  return new Promise((resolve, reject) => {
                    fs.fchown(fd, uid, gid, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                function callbackFutimes(fd, atime, mtime) {
                  return new Promise((resolve, reject) => {
                    fs.futimes(fd, atime, mtime, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                function callbackTruncate(pathValue, len) {
                  return new Promise((resolve, reject) => {
                    fs.truncate(pathValue, len, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                function callbackFdatasync(fd) {
                  return new Promise((resolve, reject) => {
                    fs.fdatasync(fd, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                function callbackFsync(fd) {
                  return new Promise((resolve, reject) => {
                    fs.fsync(fd, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                function callbackReadv(fd, buffers, position) {
                  return new Promise((resolve, reject) => {
                    fs.readv(fd, buffers, position, (error, bytesRead, returnedBuffers) => {
                      if (error) reject(error);
                      else resolve({ bytesRead, buffers: returnedBuffers });
                    });
                  });
                }

                function callbackWritev(fd, buffers, position) {
                  return new Promise((resolve, reject) => {
                    fs.writev(fd, buffers, position, (error, bytesWritten, returnedBuffers) => {
                      if (error) reject(error);
                      else resolve({ bytesWritten, buffers: returnedBuffers });
                    });
                  });
                }

                function readStream(stream) {
                  return new Promise((resolve, reject) => {
                    let text = "";
                    stream.on("data", (chunk) => { text += chunk; });
                    stream.on("error", reject);
                    stream.on("end", () => resolve(text));
                  });
                }

                async function collectLines(lines) {
                  const values = [];
                  for await (const line of lines) {
                    values.push(line);
                  }
                  return values.join("|");
                }

                async function readWebStream(webStream) {
                  const chunks = [];
                  const reader = webStream.getReader();
                  try {
                    while (true) {
                      const result = await reader.read();
                      if (result.done) {
                        break;
                      }
                      if (result.value !== undefined) {
                        chunks.push(Buffer.from(result.value));
                      }
                    }
                  } finally {
                    if (typeof reader.releaseLock === "function") {
                      reader.releaseLock();
                    }
                  }
                  return Buffer.concat(chunks).toString("utf8");
                }

                function closeTime(actual, expected) {
                  return Math.abs(Number(actual) - Number(expected)) < 5000;
                }

                function modeBits(stat) {
                  return Number(stat.mode) & 0o777;
                }

                function chownResultOk(error) {
                  const code = String(error && error.code || "");
                  return code === "EPERM" || code === "EACCES" || code === "EINVAL" || code === "ENOSYS";
                }

                function ownerChangeOk(action, statAction, uid, gid) {
                  try {
                    action();
                    const after = statAction();
                    return Number(after.uid) === Number(uid) && Number(after.gid) === Number(gid);
                  } catch (error) {
                    return chownResultOk(error);
                  }
                }

                async function ownerChangeAsyncOk(action, statAction, uid, gid) {
                  try {
                    await action();
