                        resolve(value);
                      }
                    }
                    let stream;
                    try {
                      stream = action();
                    } catch (error) {
                      settle("throw:" + error.code);
                      return;
                    }
                    stream.on("error", (error) => settle("error:" + error.code));
                    stream.on("end", () => settle("end"));
                    stream.on("finish", () => settle("finish"));
                    if (text !== undefined) {
                      stream.end(text);
                    } else if (typeof stream.resume === "function") {
                      stream.resume();
                    }
                  });
                }

