                  const manualLinesHandle = await fsp.open("./fd/filehandle-lines.txt", "r");
                  const manualLinesText = await collectLines(manualLinesHandle.readLines({ encoding: "utf8", autoClose: false }));
                  const manualLinesStat = await manualLinesHandle.stat();
                  await manualLinesHandle.close();
                  console.log("fs.fd.fileHandle.readLines=" + [
                    linesText,
                    linesAutoClosed,
                    manualLinesText,
                    manualLinesStat.isFile()
                  ].join("|"));

                  fs.writeFileSync("./fd/filehandle-web.txt", "web-stream", "utf8");
                  const webHandle = await fsp.open("./fd/filehandle-web.txt", "r");
                  const webText = await readWebStream(webHandle.readableWebStream());
                  const webDefaultStillOpen = (await webHandle.stat()).isFile();
                  await webHandle.close();
                  const webAutoHandle = await fsp.open("./fd/filehandle-web.txt", "r");
                  const webAutoText = await readWebStream(webAutoHandle.readableWebStream({ autoClose: true }));
                  const webAutoClosed = await capturePromise(() => webAutoHandle.stat(), "not open or not owned");
                  const webSingleUseHandle = await fsp.open("./fd/filehandle-web.txt", "r");
                  const webSingleUseStream = webSingleUseHandle.readableWebStream();
                  const webSingleUseDenied = captureSync(() => webSingleUseHandle.readableWebStream(), "only be called once");
                  const webSingleUseText = await readWebStream(webSingleUseStream);
                  await webSingleUseHandle.close();
                  console.log("fs.fd.fileHandle.webStream=" + [
                    webText,
                    webDefaultStillOpen,
                    webAutoText,
                    webAutoClosed,
                    webSingleUseText,
                    webSingleUseDenied
                  ].join("|"));

                  fs.writeFileSync("./fd/path-truncate.txt", "abcdef", "utf8");
                  fs.truncateSync("./fd/path-truncate.txt", 4);
                  await callbackTruncate("./fd/path-truncate.txt", 3);
                  await fsp.truncate("./fd/path-truncate.txt", 2);
                  console.log("fs.fd.truncate=" + fs.readFileSync("./fd/path-truncate.txt", "utf8"));

                  const fileHandleStreamOptionHandle = await fsp.open("./fd/promise.txt", "r");
                  const inheritedFdStreamOptions = Object.create({ fd: 0 });
                  const denied = [
                    captureSync(() => fs.openSync("../outside.txt", "w"), "escapes working directory"),
                    captureSync(() => fs.openSync("/sdcard/autojs6-fd.txt", "r"), "rejects absolute path"),
                    captureSync(() => fs.readSync(987654321, Buffer.alloc(1), 0, 1, 0), "not open or not owned"),
                    captureSync(() => fs.readFileSync(987654321, "utf8"), "not open or not owned"),
                    captureSync(() => fs.writeFileSync(987654321, "x", "utf8"), "not open or not owned"),
                    captureSync(() => fs.appendFileSync(987654321, "x", "utf8"), "not open or not owned"),
                    captureSync(() => fs.ftruncateSync(987654321, 0), "not open or not owned"),
                    captureSync(() => fs.fchmodSync(987654321, 0o600), "not open or not owned"),
                    captureSync(() => fs.fchownSync(987654321, 0, 0), "not open or not owned"),
                    captureSync(() => fs.futimesSync(987654321, new Date(), new Date()), "not open or not owned"),
                    captureSync(() => fs.readvSync(987654321, [Buffer.alloc(1)], 0), "not open or not owned"),
                    captureSync(() => fs.closeSync(987654321), "not open or not owned"),
                    captureSync(() => fs.truncateSync("../outside-truncate.txt", 0), "escapes working directory"),
                    capturePromise(() => fsp.open("../outside-promise.txt", "w"), "escapes working directory"),
                    capturePromise(() => fsp.truncate("../outside-truncate-promise.txt", 0), "escapes working directory"),
                    capturePromise(() => fsp.readFile(987654321, "utf8"), "must be a string"),
                    capturePromise(() => fsp.writeFile(987654321, "x", "utf8"), "must be a string"),
                    capturePromise(() => fsp.appendFile(987654321, "x", "utf8"), "must be a string"),
                    capturePromise(() => fileHandle.chmod(0o600), "not open or not owned"),
                    capturePromise(() => fileHandle.chown(0, 0), "not open or not owned"),
                    capturePromise(() => fileHandle.utimes(new Date(), new Date()), "not open or not owned"),
                    capturePromise(() => readerHandle.readFile("utf8"), "not open or not owned"),
                    capturePromise(() => vectorReader.readv([Buffer.alloc(1)], 0), "not open or not owned"),
                    captureSync(() => readerHandle.createReadStream(), "not open or not owned"),
                    captureSync(() => readerHandle.readLines(), "not open or not owned"),
                    captureSync(() => readerHandle.readableWebStream(), "not open or not owned"),
                    captureSync(() => manualHandle.createWriteStream({ fd: 0 }), "not open or not owned"),
                    captureSync(() => fileHandleStreamOptionHandle.createReadStream({ fd: 0 }), "not open or not owned"),
                    captureSync(() => fileHandleStreamOptionHandle.readLines({ fd: 0 }), "not open or not owned"),
                    captureSync(() => fileHandleStreamOptionHandle.readableWebStream({ fd: 0 }), "fd option is unsupported"),
                    captureSync(() => fileHandleStreamOptionHandle.readableWebStream({ type: "bytes" }), "type option is unsupported"),
                    captureSync(() => fileHandleStreamOptionHandle.readableWebStream({ encoding: "utf8" }), "encoding option is unsupported"),
                    captureSync(() => fileHandleStreamOptionHandle.createReadStream({ fs: { read() {} } }), "fs option is unsupported"),
                    captureSync(() => fileHandleStreamOptionHandle.createWriteStream({ fs: { write() {} } }), "fs option is unsupported"),
                    captureSync(() => fileHandleStreamOptionHandle.createWriteStream(inheritedFdStreamOptions), "fd option is unsupported"),
                    captureCallback((callback) => fs.open("../outside-callback.txt", "w", callback), "escapes working directory"),
                    captureCallback((callback) => fs.truncate("../outside-truncate-callback.txt", 0, callback), "escapes working directory"),
                    captureCallback((callback) => fs.close(987654321, callback), "not open or not owned"),
                    captureCallback((callback) => fs.readFile(987654321, "utf8", callback), "not open or not owned"),
                    captureCallback((callback) => fs.writeFile(987654321, "x", "utf8", callback), "not open or not owned"),
                    captureCallback((callback) => fs.appendFile(987654321, "x", "utf8", callback), "not open or not owned"),
                    captureCallback((callback) => fs.fchmod(987654321, 0o600, callback), "not open or not owned"),
                    captureCallback((callback) => fs.fchown(987654321, 0, 0, callback), "not open or not owned"),
                    captureCallback((callback) => fs.futimes(987654321, new Date(), new Date(), callback), "not open or not owned"),
                    captureCallback((callback) => fs.fsync(987654321, callback), "not open or not owned"),
                    captureCallback((callback) => fs.writev(987654321, [Buffer.from("x")], callback), "not open or not owned")
                  ];
                  const deniedResults = await Promise.all(denied);
                  await fileHandleStreamOptionHandle.close();
                  console.log("fs.fd.denied=" + deniedResults.filter(Boolean).length + "/" + deniedResults.length);
                })();
                """.trimIndent(),
                "<embedded-scoped-fs-fd-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty() + "\n" + result.stdout, result.succeeded)
            assertTrue(result.stdout.contains("fs.fd.alias=true"))
            assertTrue(result.stdout.contains("fs.fd.types=true"))
            assertTrue(result.stdout.contains("fs.fd.sync=3|bcd|5|bc+def|true|4|sync|8|vec-syn"))
            assertTrue(result.stdout.contains("fs.fd.sync.meta=600|true|true"))
            assertTrue(result.stdout.contains("fs.fd.sync.options=2|cd|3|bcd|6|1|OPTION!"))
            assertTrue(result.stdout.contains("fs.fd.callback=8|callback|8|8|callback"))
            assertTrue(result.stdout.contains("fs.fd.callback.vectors=8|call+back|4|ca+ll"))
            assertTrue(result.stdout.contains("fs.fd.callback.meta=600|true|true"))
            assertTrue(result.stdout.contains("fs.fd.callback.options=3|cde|6|abcdef|3|bcd|4|CALL|CALL"))
            assertTrue(result.stdout.contains("fs.fd.fileHandle.types=true"))
            assertTrue(result.stdout.contains("fs.fd.fileHandle.meta=600|true|true"))
            assertTrue(result.stdout.contains("fs.fd.fileHandle.asyncDispose=true|true|dispose"))
            assertTrue(result.stdout.contains("fs.fd.promise=true|true|promise-append|7|promise"))
            assertTrue(result.stdout.contains("fs.fd.promise.options=3|cde|6|abcdef|2|ef|7|PROMISE|PROMISE"))
            assertTrue(result.stdout.contains("fs.fd.fileio=cdef|sync-append|bcdef|callback-append|def|ef|promise-append-handle-fhappend"))
            assertTrue(result.stdout.contains("fs.fd.fileio.abort=true"))
            assertTrue(result.stdout.contains("fs.fd.promise.vectors=7|prom+ise|5|pr+omi"))
            assertTrue(result.stdout.contains("fs.fd.fileHandle.streams=fh-stream|fh-stream|true|true|true|manual"))
            assertTrue(result.stdout.contains("fs.fd.fileHandle.streamOptions=cdef|true|vwx|true|true|abZZef|true|0NUM0|true"))
            assertTrue(result.stdout.contains("fs.fd.fileHandle.streamAbort=error:ABORT_ERR|true|error:ABORT_ERR|true"))
            assertTrue(result.stdout.contains("fs.fd.fileHandle.readLines=alpha|beta|gamma|true|alpha|beta|gamma|true"))
            assertTrue(result.stdout.contains("fs.fd.fileHandle.webStream=web-stream|true|web-stream|true|web-stream|true"))
            assertTrue(result.stdout.contains("fs.fd.truncate=ab"))
            assertTrue(result.stdout.contains("fs.fd.denied=46/46"))
            assertEquals("sync", File(scriptDir, "fd/sync-out.txt").readText(StandardCharsets.UTF_8))
            assertEquals("vec-syn", File(scriptDir, "fd/sync-vector.txt").readText(StandardCharsets.UTF_8))
            assertEquals("callback", File(scriptDir, "fd/callback.txt").readText(StandardCharsets.UTF_8))
            assertEquals("call", File(scriptDir, "fd/callback-vector.txt").readText(StandardCharsets.UTF_8))
            assertEquals("promise-append", File(scriptDir, "fd/promise.txt").readText(StandardCharsets.UTF_8))
            assertEquals("promi", File(scriptDir, "fd/promise-vector.txt").readText(StandardCharsets.UTF_8))
            assertEquals("fh-stream", File(scriptDir, "fd/filehandle-stream.txt").readText(StandardCharsets.UTF_8))
            assertEquals("manual", File(scriptDir, "fd/filehandle-manual-stream.txt").readText(StandardCharsets.UTF_8))
            assertEquals("ab", File(scriptDir, "fd/path-truncate.txt").readText(StandardCharsets.UTF_8))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsPromisesSupportSelectedApisAliasesAndPromiseDrain() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-promises-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs promises test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const fsp = require("fs/promises");
                const nodeFsp = require("node:fs/promises");
                console.log("fsp.alias=" + (fs.promises === fsp && fsp === nodeFsp));
                console.log("fsp.constants=" + (
                  fsp.constants === fs.constants &&
                  fsp.constants.R_OK === fs.constants.R_OK &&
                  fsp.constants.W_OK === fs.constants.W_OK
                ));
                console.log("fsp.types=" + [
                  fsp.open,
                  fsp.readFile,
                  fsp.writeFile,
                  fsp.appendFile,
                  fsp.truncate,
                  fsp.stat,
                  fsp.lstat,
                  fsp.access,
                  fsp.readdir,
                  fsp.mkdir,
                  fsp.rm,
                  fsp.unlink,
                  fsp.realpath,
                  fsp.copyFile,
                  fsp.opendir,
                  fsp.cp,
                  fsp.mkdtemp,
                  fsp.rename
                ].every((fn) => typeof fn === "function"));

                fsp.mkdir("./fsp/sub", { recursive: true })
                  .then(() => fsp.writeFile("./fsp/sub/a.txt", "hello", "utf8"))
                  .then(() => fsp.appendFile("./fsp/sub/a.txt", " world", "utf8"))
                  .then(() => fsp.copyFile("./fsp/sub/a.txt", "./fsp/sub/b.txt"))
                  .then(() => Promise.all([
                    fsp.readFile("./fsp/sub/b.txt", "utf8"),
                    fsp.stat("./fsp/sub/b.txt"),
                    fsp.lstat("./fsp/sub/b.txt"),
                    fsp.access("./fsp/sub/b.txt", fs.constants.R_OK),
                    fsp.readdir("./fsp/sub"),
                    fsp.realpath("./fsp/sub/b.txt")
                  ]))
                  .then(([text, stat, lstat, accessResult, entries, realPath]) => {
                    console.log("fsp.read=" + text);
                    console.log("fsp.stat=" + (stat.isFile() && stat.size === text.length));
                    console.log("fsp.lstat=" + lstat.isFile());
                    console.log("fsp.access=" + (accessResult === undefined));
                    console.log("fsp.readdir=" + (entries.includes("a.txt") && entries.includes("b.txt")));
                    console.log("fsp.realpath=" + realPath.replace(/\\/g, "/").endsWith("/fsp/sub/b.txt"));
                    return fsp.unlink("./fsp/sub/a.txt");
                  })
                  .then(() => fsp.rm("./fsp", { recursive: true, force: true }))
                  .then(() => fsp.rm("./missing-fsp", { force: true }))
                  .then(() => {
                    console.log("fsp.final.exists=" + fs.existsSync("./fsp"));
                    console.log("fsp.done=true");
                  })
                  .catch((error) => {
                    console.log("fsp.error=" + (error && (error.stack || error.message) || error));
                    throw error;
                  });
                console.log("fsp.scheduled=true");
                """.trimIndent(),
                "<embedded-scoped-fs-promises-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertOutputOrder(result.stdout, "fsp.scheduled=true", "fsp.read=hello world", "fsp.done=true")
            assertTrue(result.stdout.contains("fsp.alias=true"))
            assertTrue(result.stdout.contains("fsp.constants=true"))
            assertTrue(result.stdout.contains("fsp.types=true"))
            assertTrue(result.stdout.contains("fsp.read=hello world"))
            assertTrue(result.stdout.contains("fsp.stat=true"))
            assertTrue(result.stdout.contains("fsp.lstat=true"))
            assertTrue(result.stdout.contains("fsp.access=true"))
            assertTrue(result.stdout.contains("fsp.readdir=true"))
            assertTrue(result.stdout.contains("fsp.realpath=true"))
            assertTrue(result.stdout.contains("fsp.final.exists=false"))
            assertTrue(result.stdout.contains("fsp.done=true"))
            assertFalse(File(scriptDir, "fsp").exists())
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsPathLikeSupportsBufferPathsAndFileUrls() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-pathlike-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs pathlike test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const fsp = require("fs/promises");
                const path = require("path");
                const url = require("url");

                function fileUrl(relativePath) {
                  return url.pathToFileURL(path.resolve(process.cwd(), relativePath));
                }

                function readCallback(pathValue) {
                  return new Promise((resolve, reject) => {
                    fs.readFile(pathValue, "utf8", (error, text) => {
                      if (error) reject(error);
                      else resolve(text);
                    });
                  });
                }

                function writeStream(pathValue, text) {
                  return new Promise((resolve, reject) => {
                    const stream = fs.createWriteStream(pathValue, { encoding: "utf8" });
                    stream.on("error", reject);
                    stream.on("finish", resolve);
                    stream.end(text);
                  });
                }

                function readStream(pathValue) {
                  return new Promise((resolve, reject) => {
                    let text = "";
                    const stream = fs.createReadStream(pathValue, { encoding: "utf8" });
                    stream.on("data", (chunk) => { text += chunk; });
                    stream.on("error", reject);
                    stream.on("end", () => resolve(text));
                  });
                }

                function captureSync(action, token) {
                  try {
                    action();
                    return false;
                  } catch (error) {
                    return String(error && error.message || error).includes(token);
                  }
                }

                function capturePromise(action, token) {
                  return Promise.resolve().then(action).then(
                    () => false,
                    (error) => String(error && error.message || error).includes(token)
                  );
                }

                return (async () => {
                  const nulBufferPath = Buffer.concat([
                    Buffer.from("bad"),
                    Buffer.from([0]),
                    Buffer.from("path")
                  ]);

                  fs.mkdirSync(Buffer.from("./pathlike/sub"), { recursive: true });
                  fs.writeFileSync(Buffer.from("./pathlike/sub/sync.txt"), "sync", "utf8");
                  await fsp.writeFile(Buffer.from("./pathlike/sub/promise.txt"), Buffer.from("promise"), "utf8");
                  await fsp.appendFile(Buffer.from("./pathlike/sub/promise.txt"), "-append", "utf8");
                  const callbackText = await readCallback(Buffer.from("./pathlike/sub/promise.txt"));

                  await fsp.writeFile(fileUrl("./pathlike/sub/url.txt"), "url", "utf8");
                  fs.renameSync(fileUrl("./pathlike/sub/url.txt"), fileUrl("./pathlike/sub/url-renamed.txt"));
                  fs.copyFileSync(fileUrl("./pathlike/sub/url-renamed.txt"), Buffer.from("./pathlike/sub/url-copy.txt"));

                  const fd = fs.openSync(Buffer.from("./pathlike/sub/fd.txt"), "w+");
                  fs.writeSync(fd, "fd");
                  fs.closeSync(fd);
                  await writeStream(Buffer.from("./pathlike/sub/stream.txt"), "stream");
                  const streamText = await readStream(Buffer.from("./pathlike/sub/stream.txt"));

                  const bufferTemp = fs.mkdtempSync(Buffer.from("./pathlike/tmp-buffer-"));
                  const urlTemp = await fsp.mkdtemp(fileUrl("./pathlike/tmp-url-"));
                  const entries = await fsp.readdir(Buffer.from("./pathlike/sub"));
                  const realPath = fs.realpathSync(Buffer.from("./pathlike/sub/url-copy.txt"));
                  const promiseText = await fsp.readFile(Buffer.from("./pathlike/sub/promise.txt"), "utf8");
                  console.log("pathlike.buffer=" + (
                    fs.readFileSync(Buffer.from("./pathlike/sub/sync.txt"), "utf8") === "sync" &&
                    promiseText === "promise-append" &&
                    callbackText === "promise-append" &&
                    fs.statSync(Buffer.from("./pathlike/sub/promise.txt")).isFile() &&
                    fs.existsSync(Buffer.from("./pathlike/sub/fd.txt")) &&
                    streamText === "stream" &&
                    entries.includes("sync.txt") &&
                    realPath.replace(/\\/g, "/").endsWith("/pathlike/sub/url-copy.txt")
                  ));
                  console.log("pathlike.url=" + (
                    fs.readFileSync(Buffer.from("./pathlike/sub/url-copy.txt"), "utf8") === "url" &&
                    !fs.existsSync(fileUrl("./pathlike/sub/url.txt"))
                  ));
                  console.log("pathlike.mkdtemp=" + (
                    fs.statSync(bufferTemp).isDirectory() &&
                    fs.statSync(urlTemp).isDirectory()
                  ));

                  await fsp.rm(Buffer.from("./pathlike"), { recursive: true, force: true });
                  console.log("pathlike.cleaned=" + !fs.existsSync(Buffer.from("./pathlike")));

                  const denied = [
                    captureSync(() => fs.readFileSync(Buffer.from("../outside.txt"), "utf8"), "escapes working directory"),
                    captureSync(() => fs.writeFileSync(Buffer.from("/sdcard/autojs6-buffer-path.txt"), "x", "utf8"), "rejects absolute path"),
                    captureSync(() => fs.readFileSync(nulBufferPath, "utf8"), "rejects NUL"),
                    await capturePromise(() => fsp.writeFile(Buffer.from("../outside-promise.txt"), "x", "utf8"), "escapes working directory"),
                    captureSync(() => fs.mkdtempSync(Buffer.from("../tmp-")), "escapes working directory"),
                    captureSync(() => fs.mkdtempSync(new URL("file://" + path.resolve(process.cwd(), "../tmp-"))), "escapes working directory")
                  ];
                  console.log("pathlike.denied=" + denied.filter(Boolean).length + "/" + denied.length);
                })();
                """.trimIndent(),
                "<embedded-scoped-fs-pathlike-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("pathlike.buffer=true"))
            assertTrue(result.stdout.contains("pathlike.url=true"))
            assertTrue(result.stdout.contains("pathlike.mkdtemp=true"))
            assertTrue(result.stdout.contains("pathlike.cleaned=true"))
            assertTrue(result.stdout.contains("pathlike.denied=6/6"))
            assertFalse(File(scriptDir, "pathlike").exists())
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsMkdtempAndRenameSupportAtomicWritePrimitives() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-temp-rename-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs temp/rename test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const nodeFs = require("node:fs");
                const fsp = require("fs/promises");
                const nodeFsp = require("node:fs/promises");
                const os = require("os");
                const path = require("path");
                const url = require("url");

                function normalize(value) {
                  return String(value).replace(/\\/g, "/");
                }

                function lstatGone(pathValue) {
                  try {
                    fs.lstatSync(pathValue);
                    return false;
                  } catch (error) {
                    return error && error.code === "ENOENT";
                  }
                }

                function callbackMkdtemp(prefix, options) {
                  return new Promise((resolve, reject) => {
                    fs.mkdtemp(prefix, options, (error, directory) => {
                      if (error) reject(error);
                      else resolve(directory);
                    });
                  });
                }

                function callbackRename(oldPath, newPath) {
                  return new Promise((resolve, reject) => {
                    fs.rename(oldPath, newPath, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                async function main() {
                  console.log("temp.alias=" + (fs === nodeFs && fsp === nodeFsp && fs.promises === fsp));
                  console.log("temp.types=" + [
                    fs.mkdtempSync,
                    fs.mkdtemp,
                    fsp.mkdtemp,
                    fs.mkdtempDisposableSync,
                    fsp.mkdtempDisposable,
                    fs.renameSync,
                    fs.rename,
                    fsp.rename
                  ].every((fn) => typeof fn === "function"));

                  const syncTemp = fs.mkdtempSync("./tmp-");
                  const promiseTemp = await fsp.mkdtemp("./tmp-");
                  const callbackTemp = await callbackMkdtemp("./tmp-", "utf8");
                  const bufferTemp = fs.mkdtempSync(Buffer.from("./buffer-"));
                  const urlTemp = await fsp.mkdtemp(url.pathToFileURL(path.resolve(process.cwd(), "./url-")));
                  console.log("mkdtemp.unique=" + (
                    syncTemp !== promiseTemp &&
                    promiseTemp !== callbackTemp &&
                    fs.statSync(syncTemp).isDirectory() &&
                    fs.statSync(promiseTemp).isDirectory() &&
                    fs.statSync(callbackTemp).isDirectory()
                  ));
                  console.log("mkdtemp.pathlike=" + (
                    fs.statSync(bufferTemp).isDirectory() &&
                    fs.statSync(urlTemp).isDirectory()
                  ));

                  const syncDisposable = fs.mkdtempDisposableSync("./dispose-sync-");
                  const syncDisposablePath = syncDisposable.path;
                  fs.writeFileSync(path.join(syncDisposablePath, "a.txt"), "sync", "utf8");
                  const syncDisposableShape = Object.isFrozen(syncDisposable) &&
                    typeof syncDisposable.path === "string" &&
                    typeof syncDisposable.remove === "function" &&
                    typeof syncDisposable[Symbol.dispose] === "function" &&
                    syncDisposable[Symbol.dispose] === syncDisposable.remove;
                  syncDisposable[Symbol.dispose]();
                  syncDisposable.remove();
                  const syncDisposableRemoved = !fs.existsSync(syncDisposablePath);

                  const promiseDisposable = await fsp.mkdtempDisposable("./dispose-promise-");
                  const promiseDisposablePath = promiseDisposable.path;
                  fs.writeFileSync(path.join(promiseDisposablePath, "a.txt"), "promise", "utf8");
                  const promiseDisposableShape = Object.isFrozen(promiseDisposable) &&
                    typeof promiseDisposable.path === "string" &&
                    typeof promiseDisposable.remove === "function" &&
                    typeof promiseDisposable[Symbol.asyncDispose] === "function" &&
                    promiseDisposable[Symbol.asyncDispose] === promiseDisposable.remove;
                  await promiseDisposable[Symbol.asyncDispose]();
                  await promiseDisposable.remove();
                  const promiseDisposableRemoved = !fs.existsSync(promiseDisposablePath);

                  fs.mkdirSync("./protected", { recursive: true });
                  fs.writeFileSync("./protected/keep.txt", "keep", "utf8");
                  const complexDisposable = fs.mkdtempDisposableSync(Buffer.from("./dispose-complex-"));
                  const complexDisposablePath = complexDisposable.path;
                  fs.mkdirSync(path.join(complexDisposablePath, "nested"), { recursive: true });
                  fs.writeFileSync(path.join(complexDisposablePath, "nested", "data.txt"), "data", "utf8");
                  fs.symlinkSync("../protected/keep.txt", path.join(complexDisposablePath, "keep-link.txt"));
                  complexDisposable.remove();
                  const complexDisposableRemoved =
                    !fs.existsSync(complexDisposablePath) &&
                    fs.readFileSync("./protected/keep.txt", "utf8") === "keep";

                  const brokenDisposable = await fsp.mkdtempDisposable(
                    url.pathToFileURL(path.resolve(process.cwd(), "./dispose-broken-"))
                  );
                  const brokenDisposablePath = brokenDisposable.path;
                  await fsp.rm(brokenDisposablePath, { recursive: true, force: true });
                  fs.symlinkSync("./missing-disposable-target", brokenDisposablePath);
                  await brokenDisposable.remove();
                  const brokenDisposableRemoved = lstatGone(brokenDisposablePath);

                  const cwdIndependentDisposable = await fsp.mkdtempDisposable("./dispose-cwd-");
                  const cwdIndependentPath = cwdIndependentDisposable.path;
                  fs.writeFileSync(path.join(cwdIndependentPath, "a.txt"), "cwd", "utf8");
                  const osTemp = await fsp.mkdtemp(path.join(os.tmpdir(), "os-"));
                  console.log("mkdtemp.os=" + (
                    fs.statSync(osTemp).isDirectory() &&
                    normalize(osTemp).indexOf("os-") >= 0
                  ));

                  fs.mkdirSync("./workspace", { recursive: true });
                  process.chdir("./workspace");
                  const cwdTemp = await fsp.mkdtemp("./cwd-");
                  console.log("mkdtemp.cwd=" + (
                    fs.statSync(cwdTemp).isDirectory() &&
                    normalize(process.cwd()).endsWith("/workspace")
                  ));
                  await cwdIndependentDisposable.remove();
                  const cwdIndependentRemoved = !fs.existsSync(path.join("..", cwdIndependentPath));
                  console.log("mkdtemp.disposable=" + (
                    syncDisposableShape &&
                    syncDisposableRemoved &&
                    promiseDisposableShape &&
                    promiseDisposableRemoved &&
                    cwdIndependentRemoved
                  ));
                  console.log("mkdtemp.disposable_extended=" + (
                    complexDisposableRemoved &&
                    brokenDisposableRemoved
                  ));

                  fs.writeFileSync("./old-sync.txt", "sync", "utf8");
                  fs.renameSync("./old-sync.txt", "./new-sync.txt");
                  console.log("rename.sync=" + (
                    fs.readFileSync("./new-sync.txt", "utf8") === "sync" &&
                    !fs.existsSync("./old-sync.txt")
                  ));

                  await fsp.writeFile("./old-promise.txt", "promise", "utf8");
                  await fsp.rename("./old-promise.txt", "./new-promise.txt");
                  console.log("rename.promise=" + (
                    await fsp.readFile("./new-promise.txt", "utf8") === "promise" &&
                    !fs.existsSync("./old-promise.txt")
                  ));

                  await fsp.writeFile("./old-callback.txt", "callback", "utf8");
                  await callbackRename("./old-callback.txt", "./new-callback.txt");
                  console.log("rename.callback=" + (
                    fs.readFileSync("./new-callback.txt", "utf8") === "callback" &&
                    !fs.existsSync("./old-callback.txt")
                  ));

                  await fsp.writeFile("./old-url.txt", "url", "utf8");
                  await fsp.rename(url.pathToFileURL("./old-url.txt"), url.pathToFileURL("./new-url.txt"));
                  console.log("rename.url=" + (
                    fs.readFileSync("./new-url.txt", "utf8") === "url" &&
                    !fs.existsSync("./old-url.txt")
                  ));

                  fs.writeFileSync("./overwrite-old.txt", "new", "utf8");
                  fs.writeFileSync("./overwrite-dest.txt", "old", "utf8");
                  fs.renameSync("./overwrite-old.txt", "./overwrite-dest.txt");
                  console.log("rename.overwrite=" + fs.readFileSync("./overwrite-dest.txt", "utf8"));

                  fs.mkdirSync("./dir-old/nested", { recursive: true });
                  fs.writeFileSync("./dir-old/nested/a.txt", "dir", "utf8");
                  fs.renameSync("./dir-old", "./dir-new");
                  console.log("rename.dir=" + (
                    fs.readFileSync("./dir-new/nested/a.txt", "utf8") === "dir" &&
                    !fs.existsSync("./dir-old")
                  ));

                  process.chdir("..");
                }

                return main();
                """.trimIndent(),
                "<embedded-scoped-fs-temp-rename-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("temp.alias=true"))
            assertTrue(result.stdout.contains("temp.types=true"))
            assertTrue(result.stdout.contains("mkdtemp.unique=true"))
            assertTrue(result.stdout.contains("mkdtemp.pathlike=true"))
            assertTrue(result.stdout.contains("mkdtemp.os=true"))
            assertTrue(result.stdout.contains("mkdtemp.cwd=true"))
            assertTrue(result.stdout.contains("mkdtemp.disposable=true"))
            assertTrue(result.stdout.contains("mkdtemp.disposable_extended=true"))
            assertTrue(result.stdout.contains("rename.sync=true"))
            assertTrue(result.stdout.contains("rename.promise=true"))
            assertTrue(result.stdout.contains("rename.callback=true"))
            assertTrue(result.stdout.contains("rename.url=true"))
            assertTrue(result.stdout.contains("rename.overwrite=new"))
            assertTrue(result.stdout.contains("rename.dir=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsMkdtempAndRenameRejectUnsafePaths() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-temp-rename-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs temp/rename deny test dir: $absolutePath" }
        }
        val outside = File(scriptDir.parentFile, "${scriptDir.name}-outside.txt").apply {
            writeText("outside", StandardCharsets.UTF_8)
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const fsp = require("fs/promises");
                const url = require("url");
                const outsideUrl = ${jsStringLiteral(outside.toURI().toString())};
                const outsidePrefixUrl = new URL("./outside-tmp-", new URL(outsideUrl));

                fs.mkdirSync("./dir/sub", { recursive: true });
                fs.mkdirSync("./existing-dir", { recursive: true });
                fs.writeFileSync("./dir/a.txt", "a", "utf8");
                fs.writeFileSync("./old.txt", "old", "utf8");

                function captureSync(label, action) {
                  try {
                    action();
                    console.log(label + ".isError=false");
                  } catch (error) {
                    const message = String(error && error.message || error);
                    console.log(label + ".isError=true");
                    console.log(label + ".code=" + String(error && error.code || ""));
                    console.log(label + ".sandbox=" + message.includes("sandboxRoot"));
                    console.log(label + ".temp=" + (message.includes("mkdtemp") || message.includes("rename")));
                    console.log(label + ".token=" + (
                      message.includes("unsupported") ||
                      message.includes("does not exist") ||
                      message.includes("escapes working directory") ||
                      message.includes("NUL") ||
                      message.includes("own child") ||
                      message.includes("directory overwrite")
                    ));
                  }
                }

                async function capturePromise(label, action) {
                  try {
                    await action();
                    console.log(label + ".isError=false");
                  } catch (error) {
                    const message = String(error && error.message || error);
                    console.log(label + ".isError=true");
                    console.log(label + ".code=" + String(error && error.code || ""));
                    console.log(label + ".sandbox=" + message.includes("sandboxRoot"));
                    console.log(label + ".temp=" + (message.includes("mkdtemp") || message.includes("rename")));
                  }
                }

                async function main() {
                  captureSync("mkdtemp.reject.escape", () => fs.mkdtempSync("../tmp-"));
                  captureSync("mkdtemp.reject.nul", () => fs.mkdtempSync("bad\u0000tmp-"));
                  captureSync("mkdtemp.reject.url_escape", () => fs.mkdtempSync(outsidePrefixUrl));
                  captureSync("mkdtemp_disposable.reject.escape", () => fs.mkdtempDisposableSync("../tmp-"));
                  captureSync("mkdtemp_disposable.reject.buffer_escape", () => fs.mkdtempDisposableSync(Buffer.from("../tmp-")));
                  await capturePromise("mkdtemp.reject.missing_parent", () => fsp.mkdtemp("./missing/tmp-"));
                  await capturePromise("mkdtemp_disposable.reject.escape_promise", () => fsp.mkdtempDisposable("../tmp-"));
                  await capturePromise("mkdtemp_disposable.reject.missing_parent", () => fsp.mkdtempDisposable("./missing/tmp-"));

                  captureSync("rename.reject.old_escape", () => fs.renameSync("../outside.txt", "./x"));
                  captureSync("rename.reject.new_escape", () => fs.renameSync("./old.txt", "../outside-rename.txt"));
                  captureSync("rename.reject.url_outside", () => fs.renameSync(new URL(outsideUrl), "./x"));
                  captureSync("rename.reject.dir_child", () => fs.renameSync("./dir", "./dir/sub/moved"));
                  captureSync("rename.reject.dir_overwrite", () => fs.renameSync("./dir", "./existing-dir"));
                  await capturePromise("rename.reject.missing_old", () => fsp.rename("./missing-old.txt", "./x"));
                  await capturePromise("rename.reject.missing_parent", () => fsp.rename("./dir/a.txt", "./missing-parent/x.txt"));
                  await capturePromise("rename.reject.new_escape_promise", () => fsp.rename("./dir/a.txt", "../outside-promise-rename.txt"));
                  console.log("temp.reject.done=true");
                }

                return main();
                """.trimIndent(),
                "<embedded-scoped-fs-temp-rename-deny-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("mkdtemp.reject.escape.isError=true"))
            assertTrue(result.stdout.contains("mkdtemp.reject.nul.isError=true"))
            assertTrue(result.stdout.contains("mkdtemp.reject.url_escape.isError=true"))
            assertTrue(result.stdout.contains("mkdtemp.reject.url_escape.code=EPERM"))
            assertTrue(result.stdout.contains("mkdtemp_disposable.reject.escape.isError=true"))
            assertTrue(result.stdout.contains("mkdtemp_disposable.reject.buffer_escape.isError=true"))
            assertTrue(result.stdout.contains("mkdtemp_disposable.reject.buffer_escape.code=EPERM"))
            assertTrue(result.stdout.contains("mkdtemp_disposable.reject.escape_promise.isError=true"))
            assertTrue(result.stdout.contains("mkdtemp_disposable.reject.escape_promise.code=EPERM"))
            assertTrue(result.stdout.contains("mkdtemp.reject.missing_parent.isError=true"))
            assertTrue(result.stdout.contains("mkdtemp.reject.missing_parent.code=ENOENT"))
            assertTrue(result.stdout.contains("mkdtemp_disposable.reject.missing_parent.isError=true"))
            assertTrue(result.stdout.contains("mkdtemp_disposable.reject.missing_parent.code=ENOENT"))
            assertTrue(result.stdout.contains("rename.reject.old_escape.isError=true"))
            assertTrue(result.stdout.contains("rename.reject.new_escape.isError=true"))
            assertTrue(result.stdout.contains("rename.reject.url_outside.isError=true"))
            assertTrue(result.stdout.contains("rename.reject.dir_child.isError=true"))
            assertTrue(result.stdout.contains("rename.reject.dir_child.code=EPERM"))
            assertTrue(result.stdout.contains("rename.reject.dir_overwrite.isError=true"))
            assertTrue(result.stdout.contains("rename.reject.dir_overwrite.code=EEXIST"))
            assertTrue(result.stdout.contains("rename.reject.missing_old.isError=true"))
            assertTrue(result.stdout.contains("rename.reject.missing_old.code=ENOENT"))
            assertTrue(result.stdout.contains("rename.reject.missing_parent.isError=true"))
            assertTrue(result.stdout.contains("rename.reject.missing_parent.code=ENOENT"))
            assertTrue(result.stdout.contains("rename.reject.new_escape_promise.isError=true"))
            assertTrue(result.stdout.contains("rename.reject.new_escape_promise.code=EPERM"))
            assertTrue(result.stdout.contains("temp.reject.done=true"))
            assertFalse(File(scriptDir.parentFile, "outside-rename.txt").exists())
            assertFalse(File(scriptDir.parentFile, "outside-promise-rename.txt").exists())
        } finally {
            outside.delete()
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsCpSyncCallbackAndPromisesCopyFilesDirectoriesAndUrls() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-cp-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs cp test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const nodeFs = require("node:fs");
                const fsp = require("fs/promises");
                const nodeFsp = require("node:fs/promises");
                const url = require("url");
                const buffer = Buffer.from([1, 2, 3]);

                function callbackCp(source, destination, options) {
                  return new Promise((resolve, reject) => {
                    fs.cp(source, destination, options, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                async function main() {
                  console.log("cp.types=" + [
                    fs.cpSync,
                    fs.cp,
                    fsp.cp
                  ].every((fn) => typeof fn === "function"));
                  console.log("cp.alias=" + (fs === nodeFs && fsp === nodeFsp && fs.promises === fsp));

                  fs.writeFileSync("./src.txt", "sync", "utf8");
                  fs.cpSync("./src.txt", "./out/sync.txt", { recursive: true });
                  await fsp.cp("./src.txt", "./out/promise.txt", { recursive: true });
                  await callbackCp("./src.txt", "./out/callback.txt", { recursive: true });
                  console.log("cp.sync.file=" + fs.readFileSync("./out/sync.txt", "utf8"));
                  console.log("cp.promise.file=" + await fsp.readFile("./out/promise.txt", "utf8"));
                  console.log("cp.callback.file=" + fs.readFileSync("./out/callback.txt", "utf8"));

                  fs.mkdirSync("./tree/nested", { recursive: true });
                  fs.mkdirSync("./tree/empty", { recursive: true });
                  fs.writeFileSync("./tree/a.txt", "a", "utf8");
                  fs.writeFileSync("./tree/nested/b.bin", buffer);
                  await fsp.cp("./tree", "./copy/tree", { recursive: true });
                  const binaryOk = fs.readFileSync("./copy/tree/nested/b.bin").equals(buffer);
                  console.log("cp.recursive=" + (
                    fs.readFileSync("./copy/tree/a.txt", "utf8") === "a" &&
                    fs.statSync("./copy/tree/empty").isDirectory() &&
                    binaryOk
                  ));

                  await fsp.cp(url.pathToFileURL("./src.txt"), url.pathToFileURL("./out/url.txt"), { recursive: true });
                  fs.cpSync(url.pathToFileURL("./src.txt"), url.pathToFileURL("./out/url-sync.txt"), { recursive: true });
                  await callbackCp("./src.txt", url.pathToFileURL("./out/url-callback.txt"), { recursive: true });
                  console.log("cp.url=" + (
                    fs.readFileSync("./out/url.txt", "utf8") === "sync" &&
                    fs.readFileSync("./out/url-sync.txt", "utf8") === "sync" &&
                    fs.readFileSync("./out/url-callback.txt", "utf8") === "sync"
                  ));

                  fs.mkdirSync("./as-dir", { recursive: true });
                  fs.cpSync("./src.txt", "./as-dir", { recursive: true });
                  console.log("cp.file.to.dir=" + fs.readFileSync("./as-dir/src.txt", "utf8"));

                  fs.writeFileSync("./overwrite.txt", "old", "utf8");
                  fs.cpSync("./src.txt", "./overwrite.txt", { force: true });
                  console.log("cp.force=" + fs.readFileSync("./overwrite.txt", "utf8"));
                  fs.writeFileSync("./skip.txt", "old", "utf8");
                  fs.cpSync("./src.txt", "./skip.txt", { force: false });
                  console.log("cp.force.false=" + fs.readFileSync("./skip.txt", "utf8"));

                  fs.writeFileSync("./mode-existing.txt", "old", "utf8");
                  const modeDenied = await fsp.cp("./src.txt", "./mode-existing.txt", {
                    mode: fs.constants.COPYFILE_EXCL
                  }).then(
                    () => false,
                    (error) => error && error.code === "EEXIST"
                  );
                  console.log("cp.mode=" + modeDenied);

                  fs.mkdirSync("./filter-src/nested", { recursive: true });
                  fs.mkdirSync("./filter-src/skip-dir", { recursive: true });
                  fs.writeFileSync("./filter-src/keep.txt", "keep", "utf8");
                  fs.writeFileSync("./filter-src/skip.tmp", "skip", "utf8");
                  fs.writeFileSync("./filter-src/nested/keep.md", "nested", "utf8");
                  fs.writeFileSync("./filter-src/skip-dir/drop.txt", "drop", "utf8");
                  const filterSeen = [];
                  await fsp.cp("./filter-src", "./filter-out", {
                    recursive: true,
                    filter(source, destination) {
                      filterSeen.push(source.endsWith("filter-src") + ":" + destination.endsWith("filter-out"));
                      return !source.endsWith(".tmp") && !source.includes("skip-dir");
                    }
                  });
                  fs.cpSync("./src.txt", "./filtered-root.txt", {
                    filter() {
                      return false;
                    }
                  });
                  console.log("cp.filter=" + (
                    fs.readFileSync("./filter-out/keep.txt", "utf8") === "keep" &&
                    fs.readFileSync("./filter-out/nested/keep.md", "utf8") === "nested" &&
                    !fs.existsSync("./filter-out/skip.tmp") &&
                    !fs.existsSync("./filter-out/skip-dir/drop.txt") &&
                    !fs.existsSync("./filtered-root.txt") &&
                    filterSeen.some((value) => value === "true:true")
                  ));

                  fs.mkdirSync("./symlink-src/sub", { recursive: true });
                  fs.writeFileSync("./symlink-src/target.txt", "target", "utf8");
                  fs.symlinkSync("target.txt", "./symlink-src/default-link.txt");
                  fs.symlinkSync("../target.txt", "./symlink-src/sub/verbatim-link.txt");
                  await fsp.cp("./symlink-src/default-link.txt", "./symlink-default-link.txt", { recursive: true });
                  fs.cpSync("./symlink-src", "./symlink-verbatim", {
                    recursive: true,
                    verbatimSymlinks: true
                  });
                  await callbackCp("./symlink-src/default-link.txt", "./symlink-deref.txt", {
                    recursive: true,
                    dereference: true
                  });
                  console.log("cp.symlink=" + (
                    fs.lstatSync("./symlink-default-link.txt").isSymbolicLink() &&
                    fs.readFileSync("./symlink-default-link.txt", "utf8") === "target" &&
                    fs.lstatSync("./symlink-verbatim/default-link.txt").isSymbolicLink() &&
                    fs.readlinkSync("./symlink-verbatim/default-link.txt") === "target.txt" &&
                    fs.lstatSync("./symlink-verbatim/sub/verbatim-link.txt").isSymbolicLink() &&
                    fs.readlinkSync("./symlink-verbatim/sub/verbatim-link.txt") === "../target.txt" &&
                    fs.readFileSync("./symlink-verbatim/sub/verbatim-link.txt", "utf8") === "target" &&
                    !fs.lstatSync("./symlink-deref.txt").isSymbolicLink() &&
                    fs.readFileSync("./symlink-deref.txt", "utf8") === "target"
                  ));

                  process.chdir("./copy");
                  await fsp.cp("./tree", "./cwd-copy", { recursive: true });
                  console.log("cp.cwd=" + (
                    fs.existsSync("./cwd-copy/a.txt") &&
                    fs.existsSync("./cwd-copy/nested/b.bin")
                  ));
                  process.chdir("..");
                }

                return main();
                """.trimIndent(),
                "<embedded-scoped-fs-cp-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("cp.types=true"))
            assertTrue(result.stdout.contains("cp.alias=true"))
            assertTrue(result.stdout.contains("cp.sync.file=sync"))
            assertTrue(result.stdout.contains("cp.promise.file=sync"))
            assertTrue(result.stdout.contains("cp.callback.file=sync"))
            assertTrue(result.stdout.contains("cp.recursive=true"))
            assertTrue(result.stdout.contains("cp.url=true"))
            assertTrue(result.stdout.contains("cp.file.to.dir=sync"))
            assertTrue(result.stdout.contains("cp.force=sync"))
            assertTrue(result.stdout.contains("cp.force.false=old"))
            assertTrue(result.stdout.contains("cp.mode=true"))
            assertTrue(result.stdout.contains("cp.filter=true"))
            assertTrue(result.stdout.contains("cp.symlink=true"))
            assertTrue(result.stdout.contains("cp.cwd=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsUtimesAndCpPreserveTimestampsSupportSyncCallbackPromisesUrlsAndCwd() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-utimes-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs utimes test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const nodeFs = require("node:fs");
                const fsp = require("fs/promises");
                const nodeFsp = require("node:fs/promises");
                const path = require("path");
                const { pathToFileURL } = require("url");
                const { Buffer } = require("buffer");

                function closeTime(actual, expected) {
                  return Math.abs(Number(actual) - Number(expected)) < 5000;
                }

                function callbackUtimes(pathValue, atime, mtime) {
                  return new Promise((resolve, reject) => {
                    fs.utimes(pathValue, atime, mtime, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                function callbackLutimes(pathValue, atime, mtime) {
                  return new Promise((resolve, reject) => {
                    fs.lutimes(pathValue, atime, mtime, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                function callbackCp(source, destination, options) {
                  return new Promise((resolve, reject) => {
                    fs.cp(source, destination, options, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                function callbackChmod(pathValue, mode) {
                  return new Promise((resolve, reject) => {
                    fs.chmod(pathValue, mode, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                function callbackLchmod(pathValue, mode) {
                  return new Promise((resolve, reject) => {
                    fs.lchmod(pathValue, mode, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                function callbackChown(pathValue, uid, gid) {
                  return new Promise((resolve, reject) => {
                    fs.chown(pathValue, uid, gid, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                function callbackLchown(pathValue, uid, gid) {
                  return new Promise((resolve, reject) => {
                    fs.lchown(pathValue, uid, gid, (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                function modeText(pathValue) {
                  return (fs.statSync(pathValue).mode & 0o777).toString(8);
                }

                function lmodeText(pathValue) {
                  return (fs.lstatSync(pathValue).mode & 0o777).toString(8);
                }

                function lchmodResultOk(error) {
                  const code = String(error && error.code || "");
                  return code === "EPERM" || code === "EACCES" || code === "EINVAL" || code === "ENOSYS" ||
                    code === "ERR_METHOD_NOT_IMPLEMENTED";
                }

                function lchmodChangeOk(action, pathValue, expectedMode) {
                  try {
                    action();
                    return lmodeText(pathValue) === expectedMode;
                  } catch (error) {
                    return lchmodResultOk(error);
                  }
                }

                async function lchmodChangeAsyncOk(action, pathValue, expectedMode) {
                  try {
                    await action();
                    return lmodeText(pathValue) === expectedMode;
                  } catch (error) {
                    return lchmodResultOk(error);
                  }
                }

                function chownResultOk(error) {
                  const code = String(error && error.code || "");
                  return code === "EPERM" || code === "EACCES" || code === "EINVAL" || code === "ENOSYS";
                }

                function lchmodResultOk(error) {
                  const code = String(error && error.code || "");
                  return code === "EPERM" || code === "EACCES" || code === "EINVAL" || code === "ENOSYS" ||
                    code === "ERR_METHOD_NOT_IMPLEMENTED";
                }

                function ownerChangeOk(action, statAction, uid, gid) {
                  try {
                    action();
                    const after = statAction();
                    return Number(after.uid) === Number(uid) && Number(after.gid) === Number(gid);
                  } catch (error) {
                    return chownResultOk(error);
                  }
                }

                async function ownerChangeAsyncOk(action, statAction, uid, gid) {
                  try {
                    await action();
                    const after = await statAction();
                    return Number(after.uid) === Number(uid) && Number(after.gid) === Number(gid);
                  } catch (error) {
                    return chownResultOk(error);
                  }
                }

                async function main() {
                  console.log("utimes.types=" + [
                    fs.utimesSync,
                    fs.utimes,
                    fsp.utimes
                  ].every((fn) => typeof fn === "function"));
