                    chownCallbackOwner.gid
                  ));

                  fs.writeFileSync("./chown-url.txt", "chown-url", "utf8");
                  const chownUrlOwner = fs.statSync("./chown-url.txt");
                  console.log("chown.url=" + await ownerChangeAsyncOk(
                    () => fsp.chown(pathToFileURL(path.resolve("./chown-url.txt")), chownUrlOwner.uid, chownUrlOwner.gid),
                    () => fsp.stat("./chown-url.txt"),
                    chownUrlOwner.uid,
                    chownUrlOwner.gid
                  ));

                  fs.writeFileSync("./chown-buffer.txt", "chown-buffer", "utf8");
                  const chownBufferOwner = fs.statSync("./chown-buffer.txt");
                  console.log("chown.buffer=" + ownerChangeOk(
                    () => fs.chownSync(Buffer.from("./chown-buffer.txt"), chownBufferOwner.uid, chownBufferOwner.gid),
                    () => fs.statSync("./chown-buffer.txt"),
                    chownBufferOwner.uid,
                    chownBufferOwner.gid
                  ));

                  fs.mkdirSync("./chown-workspace", { recursive: true });
                  fs.writeFileSync("./chown-workspace/cwd.txt", "chown-cwd", "utf8");
                  process.chdir("./chown-workspace");
                  const chownCwdOwner = fs.statSync("./cwd.txt");
                  console.log("chown.cwd=" + await ownerChangeAsyncOk(
                    () => fsp.chown("./cwd.txt", chownCwdOwner.uid, chownCwdOwner.gid),
                    () => fsp.stat("./cwd.txt"),
                    chownCwdOwner.uid,
                    chownCwdOwner.gid
                  ));
                  process.chdir("..");

                  fs.writeFileSync("./lchown-sync.txt", "lchown-sync", "utf8");
                  const lchownSyncOwner = fs.lstatSync("./lchown-sync.txt");
                  console.log("lchown.sync=" + ownerChangeOk(
                    () => fs.lchownSync("./lchown-sync.txt", lchownSyncOwner.uid, lchownSyncOwner.gid),
                    () => fs.lstatSync("./lchown-sync.txt"),
                    lchownSyncOwner.uid,
                    lchownSyncOwner.gid
                  ));

                  fs.writeFileSync("./lchown-callback.txt", "lchown-callback", "utf8");
                  const lchownCallbackOwner = fs.lstatSync("./lchown-callback.txt");
                  console.log("lchown.callback=" + await ownerChangeAsyncOk(
                    () => callbackLchown("./lchown-callback.txt", lchownCallbackOwner.uid, lchownCallbackOwner.gid),
                    () => fsp.lstat("./lchown-callback.txt"),
                    lchownCallbackOwner.uid,
                    lchownCallbackOwner.gid
                  ));

                  const preserveDate = new Date("2007-08-09T10:11:12Z");
                  fs.writeFileSync("./preserve-source.txt", "preserve", "utf8");
                  fs.utimesSync("./preserve-source.txt", preserveDate, preserveDate);
                  fs.cpSync("./preserve-source.txt", "./preserve/sync.txt", { recursive: true, preserveTimestamps: true });
                  await fsp.cp("./preserve-source.txt", "./preserve/promise.txt", { recursive: true, preserveTimestamps: true });
                  await callbackCp("./preserve-source.txt", "./preserve/callback.txt", { recursive: true, preserveTimestamps: true });
                  await fsp.cp(pathToFileURL("./preserve-source.txt"), pathToFileURL("./preserve/url.txt"), {
                    recursive: true,
                    preserveTimestamps: true
                  });
                  fs.mkdirSync("./tree/nested", { recursive: true });
                  fs.writeFileSync("./tree/nested/file.txt", "nested", "utf8");
                  fs.utimesSync("./tree/nested/file.txt", preserveDate, preserveDate);
                  await fsp.cp("./tree", "./preserve/tree", { recursive: true, preserveTimestamps: true });
                  console.log("cp.preserve.sync=" + closeTime(fs.statSync("./preserve/sync.txt").mtimeMs, preserveDate.getTime()));
                  console.log("cp.preserve.promise=" + closeTime(fs.statSync("./preserve/promise.txt").mtimeMs, preserveDate.getTime()));
                  console.log("cp.preserve.callback=" + closeTime(fs.statSync("./preserve/callback.txt").mtimeMs, preserveDate.getTime()));
                  console.log("cp.preserve.url=" + closeTime(fs.statSync("./preserve/url.txt").mtimeMs, preserveDate.getTime()));
                  console.log("cp.preserve.recursive=" + closeTime(fs.statSync("./preserve/tree/nested/file.txt").mtimeMs, preserveDate.getTime()));
                  console.log("utimes.stat.shape=" + (
                    typeof fs.statSync("./sync.txt").mtimeMs === "number" &&
                    fs.statSync("./sync.txt").mtime instanceof Date
                  ));
                }

                return main();
                """.trimIndent(),
                "<embedded-scoped-fs-utimes-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("utimes.types=true"))
