    @Test
    fun scopedFsUtimesRejectsUnsafeAndInvalidCases() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-utimes-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs utimes deny test dir: $absolutePath" }
        }
        val outside = File(scriptDir.parentFile, "${scriptDir.name}-outside.txt").apply {
            writeText("outside", StandardCharsets.UTF_8)
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const fsp = require("fs/promises");
                const { pathToFileURL } = require("url");
                const outsideUrl = ${jsStringLiteral(outside.toURI().toString())};

                fs.writeFileSync("./file.txt", "file", "utf8");
                fs.writeFileSync("./chmod.txt", "chmod", "utf8");

                function captureSync(label, action) {
                  try {
                    action();
                    console.log(label + ".isError=false");
                  } catch (error) {
                    console.log(label + ".isError=true");
                    console.log(label + ".code=" + String(error && error.code || ""));
                  }
                }

                async function capturePromise(label, action) {
                  try {
                    await action();
                    console.log(label + ".isError=false");
                  } catch (error) {
                    console.log(label + ".isError=true");
                    console.log(label + ".code=" + String(error && error.code || ""));
                  }
                }

                function captureCallback(label, start) {
                  return new Promise((resolve) => {
                    start((error) => {
                      if (!error) {
                        console.log(label + ".isError=false");
                      } else {
                        console.log(label + ".isError=true");
                        console.log(label + ".code=" + String(error && error.code || ""));
                      }
                      resolve();
                    });
                  });
                }

                async function main() {
                  captureSync("utimes.reject.invalid_nan", () => fs.utimesSync("./file.txt", NaN, Date.now()));
                  captureSync("utimes.reject.invalid_date", () => fs.utimesSync("./file.txt", new Date(NaN), new Date()));
                  captureSync("utimes.reject.nul", () => fs.utimesSync("bad\u0000file", new Date(), new Date()));
                  captureSync("utimes.reject.escape", () => fs.utimesSync("../outside.txt", new Date(), new Date()));
                  captureSync("utimes.reject.url_outside", () => fs.utimesSync(new URL(outsideUrl), new Date(), new Date()));
                  await capturePromise("utimes.reject.missing", () => fsp.utimes("./missing.txt", new Date(), new Date()));
                  await capturePromise("utimes.reject.promise_escape", () => fsp.utimes("../outside-promise.txt", new Date(), new Date()));
                  console.log("utimes.reject.done=true");
                  captureSync("lutimes.reject.invalid_nan", () => fs.lutimesSync("./file.txt", NaN, Date.now()));
                  captureSync("lutimes.reject.invalid_date", () => fs.lutimesSync("./file.txt", new Date(), new Date(NaN)));
                  captureSync("lutimes.reject.nul", () => fs.lutimesSync("bad\u0000file", new Date(), new Date()));
                  captureSync("lutimes.reject.escape", () => fs.lutimesSync("../outside-lutimes.txt", new Date(), new Date()));
                  captureSync("lutimes.reject.url_outside", () => fs.lutimesSync(new URL(outsideUrl), new Date(), new Date()));
                  await capturePromise("lutimes.reject.missing", () => fsp.lutimes("./missing-lutimes.txt", new Date(), new Date()));
                  await capturePromise("lutimes.reject.promise_escape", () => fsp.lutimes("../outside-promise-lutimes.txt", new Date(), new Date()));
                  await captureCallback("lutimes.reject.callback_missing", (callback) => fs.lutimes("./missing-callback-lutimes.txt", new Date(), new Date(), callback));
                  await captureCallback("lutimes.reject.callback_escape", (callback) => fs.lutimes("../outside-callback-lutimes.txt", new Date(), new Date(), callback));
                  console.log("lutimes.reject.done=true");
                  captureSync("chmod.reject.invalid_string_mode", () => fs.chmodSync("./chmod.txt", "bad"));
                  captureSync("chmod.reject.invalid_numeric_mode", () => fs.chmodSync("./chmod.txt", -1));
                  captureSync("chmod.reject.nul", () => fs.chmodSync("bad\u0000file", 0o600));
                  captureSync("chmod.reject.escape", () => fs.chmodSync("../outside-chmod.txt", 0o600));
                  captureSync("chmod.reject.url_outside", () => fs.chmodSync(new URL(outsideUrl), 0o600));
                  await capturePromise("chmod.reject.missing", () => fsp.chmod("./missing-chmod.txt", 0o600));
                  await capturePromise("chmod.reject.promise_escape", () => fsp.chmod("../outside-promise-chmod.txt", 0o600));
                  await captureCallback("chmod.reject.callback_missing", (callback) => fs.chmod("./missing-callback-chmod.txt", 0o600, callback));
                  await captureCallback("chmod.reject.callback_escape", (callback) => fs.chmod("../outside-callback-chmod.txt", 0o600, callback));
                  console.log("chmod.reject.done=true");
                  captureSync("lchmod.reject.invalid_string_mode", () => fs.lchmodSync("./chmod.txt", "bad"));
                  captureSync("lchmod.reject.invalid_numeric_mode", () => fs.lchmodSync("./chmod.txt", -1));
                  captureSync("lchmod.reject.nul", () => fs.lchmodSync("bad\u0000file", 0o600));
                  captureSync("lchmod.reject.escape", () => fs.lchmodSync("../outside-lchmod.txt", 0o600));
                  captureSync("lchmod.reject.url_outside", () => fs.lchmodSync(new URL(outsideUrl), 0o600));
                  await capturePromise("lchmod.reject.missing", () => fsp.lchmod("./missing-lchmod.txt", 0o600));
                  await capturePromise("lchmod.reject.promise_escape", () => fsp.lchmod("../outside-promise-lchmod.txt", 0o600));
                  await captureCallback("lchmod.reject.callback_missing", (callback) => fs.lchmod("./missing-callback-lchmod.txt", 0o600, callback));
                  await captureCallback("lchmod.reject.callback_escape", (callback) => fs.lchmod("../outside-callback-lchmod.txt", 0o600, callback));
                  console.log("lchmod.reject.done=true");
                  captureSync("chown.reject.invalid_uid_type", () => fs.chownSync("./file.txt", "0", 0));
                  captureSync("chown.reject.invalid_gid_range", () => fs.chownSync("./file.txt", 0, -2));
                  captureSync("chown.reject.nul", () => fs.chownSync("bad\u0000file", 0, 0));
                  captureSync("chown.reject.escape", () => fs.chownSync("../outside-chown.txt", 0, 0));
                  captureSync("chown.reject.url_outside", () => fs.chownSync(new URL(outsideUrl), 0, 0));
                  await capturePromise("chown.reject.missing", () => fsp.chown("./missing-chown.txt", 0, 0));
                  await capturePromise("chown.reject.promise_escape", () => fsp.chown("../outside-promise-chown.txt", 0, 0));
                  await captureCallback("chown.reject.callback_missing", (callback) => fs.chown("./missing-callback-chown.txt", 0, 0, callback));
                  await captureCallback("chown.reject.callback_escape", (callback) => fs.chown("../outside-callback-chown.txt", 0, 0, callback));
                  captureSync("lchown.reject.invalid_uid_type", () => fs.lchownSync("./file.txt", "0", 0));
                  captureSync("lchown.reject.invalid_gid_range", () => fs.lchownSync("./file.txt", 0, -2));
                  captureSync("lchown.reject.escape", () => fs.lchownSync("../outside-lchown.txt", 0, 0));
                  await capturePromise("lchown.reject.missing", () => fsp.lchown("./missing-lchown.txt", 0, 0));
                  await captureCallback("lchown.reject.callback_escape", (callback) => fs.lchown("../outside-callback-lchown.txt", 0, 0, callback));
                  console.log("chown.reject.done=true");
                }

                return main();
                """.trimIndent(),
