    @Test
    fun scopedFsCpRejectsUnsafeAndUnsupportedCases() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-cp-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs cp deny test dir: $absolutePath" }
        }
        val outside = File(scriptDir.parentFile, "${scriptDir.name}-outside.txt").apply {
            writeText("outside", StandardCharsets.UTF_8)
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const fsp = require("fs/promises");
                const url = require("url");
                const outsideUrl = ${jsStringLiteral(outside.toURI().toString())};

                fs.mkdirSync("./dir/sub", { recursive: true });
                fs.writeFileSync("./dir/a.txt", "a", "utf8");
                fs.writeFileSync("./exists.txt", "old", "utf8");

                function captureSync(label, action) {
                  try {
                    action();
                    console.log(label + ".isError=false");
                  } catch (error) {
                    const message = String(error && error.message || error);
                    console.log(label + ".isError=true");
                    console.log(label + ".code=" + String(error && error.code || ""));
                    console.log(label + ".sandbox=" + message.includes("sandboxRoot"));
                    console.log(label + ".cp=" + message.includes("cp"));
                    console.log(label + ".token=" + (
                      message.includes("recursive") ||
                      message.includes("already exists") ||
                      message.includes("self-copy") ||
                      message.includes("async filter") ||
                      message.includes("filter option must be a function") ||
                      message.includes("target escapes") ||
                      message.includes("escapes working directory")
                    ));
                  }
                }

                async function capturePromise(label, action) {
                  try {
                    await action();
                    console.log(label + ".isError=false");
                  } catch (error) {
                    const message = String(error && error.message || error);
                    console.log(label + ".isError=true");
                    console.log(label + ".code=" + String(error && error.code || ""));
                    console.log(label + ".sandbox=" + message.includes("sandboxRoot"));
                    console.log(label + ".cp=" + message.includes("cp"));
                  }
                }

                async function main() {
                  fs.mkdirSync("./safe/a/b/c", { recursive: true });
                  fs.writeFileSync("./safe/a/safe.txt", "safe", "utf8");
                  fs.symlinkSync("../../safe.txt", "./safe/a/b/c/link.txt");
                  captureSync("cp.reject.dir.no_recursive", () => fs.cpSync("./dir", "./dir-copy"));
                  captureSync("cp.reject.error_on_exist", () => fs.cpSync("./dir/a.txt", "./exists.txt", { errorOnExist: true }));
                  captureSync("cp.reject.src_escape", () => fs.cpSync("../outside.txt", "./x", { recursive: true }));
                  captureSync("cp.reject.dest_escape", () => fs.cpSync("./dir/a.txt", "../outside-dest.txt", { recursive: true }));
                  captureSync("cp.reject.url_outside", () => fs.cpSync(new URL(outsideUrl), "./x", { recursive: true }));
                  captureSync("cp.reject.self_child", () => fs.cpSync("./dir", "./dir/sub/copy", { recursive: true }));
                  captureSync("cp.reject.filter_type", () => fs.cpSync("./dir", "./filter-copy", { recursive: true, filter: true }));
                  captureSync("cp.reject.async_filter", () => fs.cpSync("./dir", "./filter-copy", {
                    recursive: true,
                    filter() {
                      return Promise.resolve(true);
                    }
                  }));
                  captureSync("cp.reject.verbatim_escape", () => fs.cpSync("./safe/a/b/c/link.txt", "./verbatim-link.txt", {
                    recursive: true,
                    verbatimSymlinks: true
                  }));
                  await capturePromise("cp.reject.promise_missing", () => fsp.cp("./missing", "./x", { recursive: true }));
                  await capturePromise("cp.reject.promise_dest_escape", () => fsp.cp("./dir/a.txt", "../outside-promise.txt", { recursive: true }));
                  console.log("cp.reject.done=true");
                }

                return main();
                """.trimIndent(),
                "<embedded-scoped-fs-cp-deny-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("cp.reject.dir.no_recursive.isError=true"))
            assertTrue(result.stdout.contains("cp.reject.dir.no_recursive.code=EISDIR"))
            assertTrue(result.stdout.contains("cp.reject.error_on_exist.isError=true"))
            assertTrue(result.stdout.contains("cp.reject.error_on_exist.code=EEXIST"))
            assertTrue(result.stdout.contains("cp.reject.src_escape.isError=true"))
            assertTrue(result.stdout.contains("cp.reject.dest_escape.isError=true"))
            assertTrue(result.stdout.contains("cp.reject.url_outside.isError=true"))
            assertTrue(result.stdout.contains("cp.reject.self_child.isError=true"))
            assertTrue(result.stdout.contains("cp.reject.filter_type.isError=true"))
            assertTrue(result.stdout.contains("cp.reject.filter_type.code=ERR_INVALID_ARG_TYPE"))
            assertTrue(result.stdout.contains("cp.reject.async_filter.isError=true"))
            assertTrue(result.stdout.contains("cp.reject.async_filter.code=ERR_AUTOJS6_EMBEDDED_NODE_UNSUPPORTED_OPTION"))
            assertTrue(result.stdout.contains("cp.reject.verbatim_escape.isError=true"))
            assertTrue(result.stdout.contains("cp.reject.verbatim_escape.code=EPERM"))
            assertTrue(result.stdout.contains("cp.reject.promise_missing.isError=true"))
            assertTrue(result.stdout.contains("cp.reject.promise_missing.code=ENOENT"))
            assertTrue(result.stdout.contains("cp.reject.promise_dest_escape.isError=true"))
            assertTrue(result.stdout.contains("cp.reject.promise_dest_escape.code=EPERM"))
            assertTrue(result.stdout.contains("cp.reject.done=true"))
            assertFalse(File(scriptDir.parentFile, "outside-dest.txt").exists())
            assertFalse(File(scriptDir.parentFile, "outside-promise.txt").exists())
        } finally {
            outside.delete()
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsDirentWithFileTypesAndOpendirSupportModernTraversal() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-dirent-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs dirent test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const fsp = require("fs/promises");
                const path = require("path");
                const url = require("url");

                function entryNames(entries) {
                  return entries.map((entry) => String(entry.name || entry)).sort().join("|");
                }

                function normalizePath(value) {
                  return String(value).replace(/\\/g, "/");
                }

                function recursiveDirentSummary(entries) {
                  return entries
                    .map((entry) => (
                      normalizePath(path.join(String(entry.parentPath), String(entry.name))) + ":" +
                      entry.isDirectory() + ":" +
                      entry.isFile() + ":" +
                      entry.isSymbolicLink()
                    ))
                    .sort()
                    .join("|");
                }

                function recursiveNameSummary(entries) {
                  return entries.map(normalizePath).sort().join("|");
                }

                function captureSyncToken(action, token) {
                  try {
                    action();
                    return false;
                  } catch (error) {
                    return String(error && error.message || error).includes(token);
                  }
                }

                function capturePromiseToken(action, token) {
                  return Promise.resolve().then(action).then(
                    () => false,
                    (error) => String(error && error.message || error).includes(token)
                  );
                }

                function callbackOpendir(pathValue, options) {
                  return new Promise((resolve, reject) => {
                    const done = (error, dir) => {
                      if (error) reject(error);
                      else resolve(dir);
                    };
                    if (arguments.length >= 2) {
                      fs.opendir(pathValue, options, done);
                    } else {
                      fs.opendir(pathValue, done);
                    }
                  });
                }

                function callbackDirRead(dir) {
                  return new Promise((resolve, reject) => {
                    dir.read((error, entry) => {
                      if (error) reject(error);
                      else resolve(entry);
                    });
                  });
                }

                function callbackDirClose(dir) {
                  return new Promise((resolve, reject) => {
                    dir.close((error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                }

                async function main() {
                  fs.mkdirSync("./walk/sub", { recursive: true });
                  fs.writeFileSync("./walk/a.txt", "a", "utf8");
                  fs.writeFileSync("./walk/sub/b.js", "b", "utf8");

                  const plain = fs.readdirSync("./walk").sort();
                  const syncEntries = fs.readdirSync("./walk", { withFileTypes: true });
                  const syncFile = syncEntries.find((entry) => entry.name === "a.txt");
                  const syncDir = syncEntries.find((entry) => entry.name === "sub");
                  console.log("dirent.plain=" + (plain.join("|") === "a.txt|sub"));
                  console.log("dirent.sync.names=" + entryNames(syncEntries));
                  console.log("dirent.sync.shape=" + (
                    syncFile &&
                    syncDir &&
                    syncFile.isFile() &&
                    !syncFile.isDirectory() &&
                    !syncFile.isSymbolicLink() &&
                    syncDir.isDirectory() &&
                    !syncDir.isFile() &&
                    syncFile.isBlockDevice() === false &&
                    syncFile.isCharacterDevice() === false &&
                    syncFile.isFIFO() === false &&
                    syncFile.isSocket() === false &&
                    Object.isFrozen(syncFile)
                  ));

                  await new Promise((resolve, reject) => {
                    fs.readdir("./walk", { withFileTypes: true }, (error, entries) => {
                      if (error) {
                        reject(error);
                        return;
                      }
                      const file = entries.find((entry) => entry.name === "a.txt");
                      const dir = entries.find((entry) => entry.name === "sub");
                      console.log("dirent.callback=" + (
                        entryNames(entries) === "a.txt|sub" &&
                        file.isFile() &&
                        dir.isDirectory()
                      ));
                      resolve();
                    });
                  });

                  const promiseEntries = await fsp.readdir("./walk", { withFileTypes: true });
                  const promiseFile = promiseEntries.find((entry) => entry.name === "a.txt");
                  const promiseDir = promiseEntries.find((entry) => entry.name === "sub");
                  console.log("dirent.promise=" + (
                    entryNames(promiseEntries) === "a.txt|sub" &&
                    promiseFile.isFile() &&
                    promiseDir.isDirectory()
                  ));

                  const recursiveSyncNames = recursiveNameSummary(fs.readdirSync("./walk", { recursive: true }));
                  const recursiveCallbackNames = await new Promise((resolve, reject) => {
                    fs.readdir("./walk", { recursive: true }, (error, entries) => {
                      if (error) reject(error);
                      else resolve(recursiveNameSummary(entries));
                    });
                  });
                  const recursivePromiseNames = recursiveNameSummary(await fsp.readdir(
                    url.pathToFileURL(path.resolve(process.cwd(), "./walk")),
                    { recursive: true }
                  ));
                  const recursiveDirents = fs.readdirSync("./walk", { recursive: true, withFileTypes: true });
                  const recursiveDirentNames = recursiveDirentSummary(recursiveDirents);
                  console.log("dirent.readdir.recursive=" + (
                    recursiveSyncNames === "a.txt|sub|sub/b.js" &&
                    recursiveCallbackNames === recursiveSyncNames &&
                    recursivePromiseNames === recursiveSyncNames &&
                    recursiveDirentNames === "walk/a.txt:false:true:false|walk/sub/b.js:false:true:false|walk/sub:true:false:false"
                  ));

                  process.chdir("./walk");
                  const cwdEntries = await fsp.readdir(".", { withFileTypes: true });
                  console.log("dirent.cwd=" + (entryNames(cwdEntries) === "a.txt|sub"));
                  console.log("dirent.opendir.types=" + [
                    typeof fs.opendirSync,
                    typeof fs.opendir,
                    typeof fsp.opendir
                  ].join(","));

                  const syncOpened = fs.opendirSync(".", { bufferSize: 2 });
                  const syncOpenedEntries = [];
                  for (;;) {
                    const entry = syncOpened.readSync();
                    if (entry === null) break;
                    syncOpenedEntries.push(entry);
                  }
                  syncOpened.closeSync();
                  const syncClosed = captureSyncToken(() => syncOpened.readSync(), "Dir is closed");
                  console.log("dirent.opendir.sync=" + (
                    entryNames(syncOpenedEntries) === "a.txt|sub" &&
                    syncOpenedEntries.some((entry) => entry.name === "a.txt" && entry.isFile()) &&
                    syncOpenedEntries.some((entry) => entry.name === "sub" && entry.isDirectory()) &&
                    syncClosed
                  ));

                  const syncDisposeDir = fs.opendirSync(".");
                  const syncDisposeType = typeof syncDisposeDir[Symbol.dispose] === "function";
                  syncDisposeDir[Symbol.dispose]();
                  const syncDisposedClosed = captureSyncToken(() => syncDisposeDir.readSync(), "Dir is closed");
                  const asyncDisposeDir = await fsp.opendir(".");
                  const asyncDisposeType = typeof asyncDisposeDir[Symbol.asyncDispose] === "function";
                  await asyncDisposeDir[Symbol.asyncDispose]();
                  const asyncDisposedClosed = await capturePromiseToken(() => asyncDisposeDir.read(), "Dir is closed");
                  console.log("dirent.opendir.dispose=" + (
                    syncDisposeType &&
                    syncDisposedClosed &&
                    asyncDisposeType &&
                    asyncDisposedClosed
                  ));

                  const callbackOpened = await callbackOpendir(".", { bufferSize: 2 });
                  const callbackEntries = [];
                  for (;;) {
                    const entry = await callbackDirRead(callbackOpened);
                    if (entry === null) break;
                    callbackEntries.push(entry);
                  }
                  await callbackDirClose(callbackOpened);
                  const callbackClosed = await new Promise((resolve) => {
                    callbackOpened.read((error) => {
                      resolve(!!error && String(error && error.message || error).includes("Dir is closed"));
                    });
                  });
                  console.log("dirent.opendir.callback=" + (
                    entryNames(callbackEntries) === "a.txt|sub" &&
                    callbackEntries.some((entry) => entry.name === "a.txt" && entry.isFile()) &&
                    callbackEntries.some((entry) => entry.name === "sub" && entry.isDirectory()) &&
                    callbackClosed
                  ));

                  const dir = await fsp.opendir(".");
                  const first = await dir.read();
                  const remaining = [];
                  for (;;) {
                    const next = await dir.read();
                    if (next === null) break;
                    remaining.push(String(next.name));
                  }
                  console.log("dirent.opendir.read=" + (
                    first &&
                    typeof first.isFile === "function" &&
                    [String(first.name)].concat(remaining).sort().join("|") === "a.txt|sub"
                  ));
                  await dir.close();
                  console.log("dirent.opendir.close=" + await capturePromiseToken(() => dir.read(), "Dir is closed"));

                  const iterated = [];
                  const iterDir = await fsp.opendir(".");
                  for await (const entry of iterDir) {
                    iterated.push(String(entry.name) + ":" + entry.isDirectory() + ":" + entry.isFile());
                  }
                  iterated.sort();
                  const iterClosed = await capturePromiseToken(() => iterDir.read(), "Dir is closed");
                  console.log("dirent.opendir.iter=" + (
                    iterated.join("|") === "a.txt:false:true|sub:true:false" &&
                    iterClosed
                  ));

                  function readSyncDirEntries(dir) {
                    const entries = [];
                    for (;;) {
                      const entry = dir.readSync();
                      if (entry === null) break;
                      entries.push(entry);
                    }
                    dir.closeSync();
                    return entries;
                  }

                  async function readCallbackDirEntries(dir) {
                    const entries = [];
                    for (;;) {
                      const entry = await callbackDirRead(dir);
                      if (entry === null) break;
                      entries.push(entry);
                    }
                    await callbackDirClose(dir);
                    return entries;
                  }

                  const recursiveOpendirExpected = "a.txt:false:true:false|sub/b.js:false:true:false|sub:true:false:false";
                  const syncRecursiveDir = fs.opendirSync(".", { recursive: true, bufferSize: 1 });
                  const syncRecursiveSummary = recursiveDirentSummary(readSyncDirEntries(syncRecursiveDir));
                  const callbackRecursiveDir = await callbackOpendir(".", { recursive: true, bufferSize: 1 });
                  const callbackRecursiveSummary = recursiveDirentSummary(await readCallbackDirEntries(callbackRecursiveDir));
                  const promiseRecursiveDir = await fsp.opendir(Buffer.from("."), { recursive: true, bufferSize: 1 });
                  const promiseRecursiveEntries = [];
                  for await (const entry of promiseRecursiveDir) {
                    promiseRecursiveEntries.push(entry);
                  }
                  const promiseRecursiveSummary = recursiveDirentSummary(promiseRecursiveEntries);
                  console.log("dirent.opendir.recursive=" + (
                    syncRecursiveSummary === recursiveOpendirExpected &&
                    callbackRecursiveSummary === recursiveOpendirExpected &&
                    promiseRecursiveSummary === recursiveOpendirExpected
                  ));

                  const bufferDir = await fsp.opendir(".", { encoding: "buffer" });
                  const bufferEntry = await bufferDir.read();
                  await bufferDir.close();
                  console.log("dirent.opendir.buffer=" + (
                    bufferEntry &&
                    Buffer.isBuffer(bufferEntry.name) &&
                    ["a.txt", "sub"].includes(bufferEntry.name.toString("utf8"))
                  ));
                }

                return main();
                """.trimIndent(),
                "<embedded-scoped-fs-dirent-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("dirent.plain=true"))
            assertTrue(result.stdout.contains("dirent.sync.names=a.txt|sub"))
            assertTrue(result.stdout.contains("dirent.sync.shape=true"))
            assertTrue(result.stdout.contains("dirent.callback=true"))
            assertTrue(result.stdout.contains("dirent.promise=true"))
            assertTrue(result.stdout.contains("dirent.readdir.recursive=true"))
            assertTrue(result.stdout.contains("dirent.cwd=true"))
            assertTrue(result.stdout.contains("dirent.opendir.types=function,function,function"))
            assertTrue(result.stdout.contains("dirent.opendir.sync=true"))
            assertTrue(result.stdout.contains("dirent.opendir.dispose=true"))
            assertTrue(result.stdout.contains("dirent.opendir.callback=true"))
            assertTrue(result.stdout.contains("dirent.opendir.read=true"))
            assertTrue(result.stdout.contains("dirent.opendir.close=true"))
            assertTrue(result.stdout.contains("dirent.opendir.iter=true"))
            assertTrue(result.stdout.contains("dirent.opendir.recursive=true"))
            assertTrue(result.stdout.contains("dirent.opendir.buffer=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsDirentAndOpendirRejectUnsafePaths() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-dirent-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs dirent deny test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const fsp = require("fs/promises");
                fs.mkdirSync("./safe", { recursive: true });
                fs.writeFileSync("./safe/file.txt", "x", "utf8");
                const nulPath = "bad" + String.fromCharCode(0) + "path";

                function captureSync(label, action) {
                  try {
                    action();
                    console.log(label + ".unexpected=true");
                  } catch (error) {
                    console.log(label + ".isError=" + (error instanceof Error));
                    console.log(label + ".message=" + String(error.message).replace(/\s+/g, " "));
                  }
                }

                function capturePromise(label, action) {
                  return Promise.resolve()
                    .then(action)
                    .then(() => {
                      console.log(label + ".unexpected=true");
                    })
                    .catch((error) => {
                      console.log(label + ".isError=" + (error instanceof Error));
                      console.log(label + ".code=" + error.code);
                      console.log(label + ".message=" + String(error.message).replace(/\s+/g, " "));
                    });
                }

                function captureCallback(label, action) {
                  return new Promise((resolve) => {
                    action((error) => {
                      console.log(label + ".isError=" + (error instanceof Error));
                      console.log(label + ".code=" + (error && error.code));
                      console.log(label + ".message=" + String(error && error.message).replace(/\s+/g, " "));
                      resolve();
                    });
                  });
                }

                captureSync("dirent.sync.absolute", () => fs.readdirSync("/sdcard", { withFileTypes: true }));
                captureSync("dirent.sync.recursive_escape", () => fs.readdirSync("../outside", { recursive: true }));
                captureSync("opendir.sync.escape", () => fs.opendirSync("../outside"));
                captureSync("opendir.sync.recursive_escape", () => fs.opendirSync("../outside", { recursive: true }));
                captureSync("opendir.callback.missing_callback", () => fs.opendir("./safe"));
                return Promise.all([
                  capturePromise("dirent.promise.escape", () => fsp.readdir("../outside", { withFileTypes: true })),
                  capturePromise("dirent.promise.recursive_escape", () => fsp.readdir("../outside", { recursive: true })),
                  captureCallback("dirent.callback.missing", (callback) => fs.readdir("./missing", { withFileTypes: true }, callback)),
                  captureCallback("opendir.callback.escape", (callback) => fs.opendir("../outside", callback)),
                  capturePromise("opendir.missing", () => fsp.opendir("./missing")),
                  capturePromise("opendir.file", () => fsp.opendir("./safe/file.txt")),
                  capturePromise("opendir.escape", () => fsp.opendir("../outside")),
                  capturePromise("opendir.absolute", () => fsp.opendir("/sdcard")),
                  capturePromise("opendir.nul", () => fsp.opendir(nulPath)),
                  capturePromise("opendir.recursive_escape", () => fsp.opendir("../outside", { recursive: true }))
                ]).then(() => {
                  console.log("dirent.security.done=true");
                });
                """.trimIndent(),
                "<embedded-scoped-fs-dirent-deny-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("dirent.sync.absolute.isError=true"))
            assertTrue(result.stdout.contains("dirent.sync.absolute.message="))
            assertTrue(result.stdout.contains("dirent.sync.recursive_escape.isError=true"))
            assertTrue(result.stdout.contains("dirent.sync.recursive_escape.message="))
            assertTrue(result.stdout.contains("opendir.sync.escape.isError=true"))
            assertTrue(result.stdout.contains("opendir.sync.escape.message="))
            assertTrue(result.stdout.contains("opendir.sync.recursive_escape.isError=true"))
            assertTrue(result.stdout.contains("opendir.sync.recursive_escape.message="))
            assertTrue(result.stdout.contains("opendir.callback.missing_callback.isError=true"))
            assertTrue(result.stdout.contains("opendir.callback.missing_callback.message="))
            assertTrue(result.stdout.contains("dirent.promise.escape.isError=true"))
            assertTrue(result.stdout.contains("dirent.promise.escape.code=EPERM"))
            assertTrue(result.stdout.contains("dirent.promise.recursive_escape.isError=true"))
            assertTrue(result.stdout.contains("dirent.promise.recursive_escape.code=EPERM"))
            assertTrue(result.stdout.contains("dirent.callback.missing.isError=true"))
            assertTrue(result.stdout.contains("dirent.callback.missing.code=ENOENT"))
            assertTrue(result.stdout.contains("opendir.callback.escape.isError=true"))
            assertTrue(result.stdout.contains("opendir.callback.escape.code=EPERM"))
            assertTrue(result.stdout.contains("opendir.missing.isError=true"))
            assertTrue(result.stdout.contains("opendir.missing.code=ENOENT"))
            assertTrue(result.stdout.contains("opendir.file.isError=true"))
            assertTrue(result.stdout.contains("opendir.file.code=ENOTDIR"))
            assertTrue(result.stdout.contains("opendir.escape.isError=true"))
            assertTrue(result.stdout.contains("opendir.escape.code=EPERM"))
            assertTrue(result.stdout.contains("opendir.absolute.isError=true"))
            assertTrue(result.stdout.contains("opendir.absolute.code=EPERM"))
            assertTrue(result.stdout.contains("opendir.nul.isError=true"))
            assertTrue(result.stdout.contains("opendir.nul.code=EPERM"))
            assertTrue(result.stdout.contains("opendir.recursive_escape.isError=true"))
            assertTrue(result.stdout.contains("opendir.recursive_escape.code=EPERM"))
            assertFalse(result.stdout.contains(".unexpected=true"))
            assertTrue(result.stdout.contains("dirent.security.done=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsReadlinkSurfaceAndRejectsUnsafeOrNonSymlinkPaths() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-readlink-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs readlink deny test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const nodeFs = require("node:fs");
                const fsp = require("fs/promises");
                const nodeFsp = require("node:fs/promises");
                const url = require("url");
                fs.writeFileSync("./file.txt", "file", "utf8");
                const nulPath = "bad" + String.fromCharCode(0) + "path";

                function captureSync(label, action) {
                  try {
                    action();
                    console.log(label + ".unexpected=true");
                  } catch (error) {
                    console.log(label + ".isError=" + (error instanceof Error));
                    console.log(label + ".code=" + error.code);
                    console.log(label + ".message=" + String(error.message).replace(/\s+/g, " "));
                  }
                }

                function capturePromise(label, action) {
                  return Promise.resolve()
                    .then(action)
                    .then(() => {
                      console.log(label + ".unexpected=true");
                    })
                    .catch((error) => {
                      console.log(label + ".isError=" + (error instanceof Error));
                      console.log(label + ".code=" + error.code);
                      console.log(label + ".message=" + String(error.message).replace(/\s+/g, " "));
                    });
                }

                function captureCallback(label, action) {
                  return new Promise((resolve) => {
                    action((error) => {
                      console.log(label + ".isError=" + (error instanceof Error));
                      console.log(label + ".code=" + (error && error.code));
                      console.log(label + ".message=" + String(error && error.message).replace(/\s+/g, " "));
                      resolve();
                    });
                  });
                }

                console.log("readlink.surface=" + (
                  fs === nodeFs &&
                  fsp === nodeFsp &&
                  fs.promises === fsp &&
                  typeof fs.readlinkSync === "function" &&
                  typeof fs.readlink === "function" &&
                  typeof fsp.readlink === "function" &&
                  typeof fs.symlink === "function" &&
                  typeof fs.symlinkSync === "function" &&
                  typeof fsp.symlink === "function"
                ));
                captureSync("readlink.file", () => fs.readlinkSync("./file.txt"));
                captureSync("readlink.invalid_encoding", () => fs.readlinkSync("./file.txt", { encoding: "bad-encoding" }));
                captureSync("readlink.nul", () => fs.readlinkSync(nulPath));
                captureSync("readlink.absolute", () => fs.readlinkSync("/sdcard"));
                captureSync("readlink.url_outside", () => fs.readlinkSync(new URL("file:///sdcard/autojs6-readlink")));
                return Promise.all([
                  capturePromise("readlink.promise.missing", () => fsp.readlink("./missing")),
                  capturePromise("readlink.promise.escape", () => fsp.readlink("../outside-link")),
                  captureCallback("readlink.callback.missing", (callback) => fs.readlink("./missing", callback))
                ]).then(() => {
                  console.log("readlink.reject.done=true");
                });
                """.trimIndent(),
                "<embedded-scoped-fs-readlink-deny-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("readlink.surface=true"))
            assertTrue(result.stdout.contains("readlink.file.isError=true"))
            assertTrue(result.stdout.contains("readlink.file.code=EINVAL"))
            assertTrue(result.stdout.contains("readlink.invalid_encoding.isError=true"))
            assertTrue(result.stdout.contains("readlink.invalid_encoding.code=ERR_INVALID_ARG_VALUE"))
            assertTrue(result.stdout.contains("readlink.nul.isError=true"))
            assertTrue(result.stdout.contains("readlink.nul.code=ERR_INVALID_ARG_TYPE"))
            assertTrue(result.stdout, result.stdout.contains("readlink.absolute.isError=true"))
            assertTrue(result.stdout.contains("readlink.absolute.code=EPERM"))
            assertTrue(result.stdout.contains("readlink.url_outside.isError=true"))
            assertTrue(result.stdout.contains("readlink.url_outside.code=EPERM"))
            assertTrue(result.stdout.contains("readlink.promise.missing.isError=true"))
            assertTrue(result.stdout.contains("readlink.promise.missing.code=ENOENT"))
            assertTrue(result.stdout.contains("readlink.promise.escape.isError=true"))
            assertTrue(result.stdout.contains("readlink.promise.escape.code=EPERM"))
            assertTrue(result.stdout.contains("readlink.callback.missing.isError=true"))
            assertTrue(result.stdout.contains("readlink.callback.missing.code=ENOENT"))
            assertTrue(result.stdout.contains("readlink.reject.done=true"))
            assertFalse(result.stdout.contains(".unexpected=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsReadlinkSupportsInternalSymlinkAndDirentWhenAvailable() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-readlink-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs readlink test dir: $absolutePath" }
        }
        val outsideDir = File(context.cacheDir, "embedded-scoped-fs-readlink-outside-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs readlink outside dir: $absolutePath" }
        }
        try {
            val target = File(scriptDir, "target.txt").apply {
                writeText("target", StandardCharsets.UTF_8)
            }
            val link = File(scriptDir, "link.txt")
            val subDir = File(scriptDir, "sub").apply {
                check(mkdirs()) { "Failed to create readlink sub dir: $absolutePath" }
            }
            val cwdLink = File(subDir, "cwd-link.txt")
            val outsideTarget = File(outsideDir, "outside.txt").apply {
                writeText("outside", StandardCharsets.UTF_8)
            }
            val outsideLink = File(scriptDir, "outside-link")
            val loopLink = File(scriptDir, "loop-link")
            val symlinkReady = try {
                Files.createSymbolicLink(link.toPath(), target.toPath())
                Files.createSymbolicLink(cwdLink.toPath(), target.toPath())
                Files.createSymbolicLink(outsideLink.toPath(), outsideTarget.toPath())
                Files.createSymbolicLink(loopLink.toPath(), loopLink.toPath().fileSystem.getPath("loop-link"))
                true
            } catch (_: Throwable) {
                false
            }
            assumeTrue("Symlink creation unavailable on this device", symlinkReady)

            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const fsp = require("fs/promises");
                const path = require("path");
                const consumers = require("stream/consumers");
                const url = require("url");
                const { Buffer } = require("buffer");

                function normalize(text) {
                  return String(text).replace(/\\/g, "/");
                }

                function closeTime(actual, expected) {
                  return Math.abs(Number(actual) - Number(expected)) < 5000;
                }

                function chownResultOk(error) {
                  const code = String(error && error.code || "");
                  return code === "EPERM" || code === "EACCES" || code === "EINVAL" || code === "ENOSYS";
                }

                function ownerChangeOk(action, statAction, uid, gid) {
                  try {
                    action();
                    const after = statAction();
                    return Number(after.uid) === Number(uid) && Number(after.gid) === Number(gid);
                  } catch (error) {
                    return chownResultOk(error);
                  }
                }

                function lchmodResultOk(error) {
                  const code = String(error && error.code || "");
                  return code === "EPERM" || code === "EACCES" || code === "EINVAL" || code === "ENOSYS" ||
                    code === "ERR_METHOD_NOT_IMPLEMENTED";
                }

                function lchmodSymlinkOk(action, pathValue) {
                  try {
                    action();
                    return fs.lstatSync(pathValue).isSymbolicLink();
                  } catch (error) {
                    return lchmodResultOk(error);
                  }
                }

                async function capture(label, action) {
                  try {
                    const value = await action();
                    console.log(label + ".ok=true");
                    console.log(label + ".value=" + normalize(value));
                  } catch (error) {
                    console.log(label + ".ok=false");
                    console.log(label + ".code=" + error.code);
                    console.log(label + ".message=" + String(error.message).replace(/\s+/g, " "));
                  }
                }

                async function main() {
                  const syncTarget = fs.readlinkSync("./link.txt");
                  const syncBufferTarget = fs.readlinkSync("./link.txt", "buffer");
                  const syncObjectBufferTarget = fs.readlinkSync(Buffer.from("./link.txt"), { encoding: "buffer" });
                  const callbackTarget = await new Promise((resolve, reject) => {
                    fs.readlink("./link.txt", (error, value) => {
                      if (error) reject(error);
                      else resolve(value);
                    });
                  });
                  const callbackHexTarget = await new Promise((resolve, reject) => {
                    fs.readlink("./link.txt", { encoding: "hex" }, (error, value) => {
                      if (error) reject(error);
                      else resolve(value);
                    });
                  });
                  const promiseTarget = await fsp.readlink("./link.txt");
                  const promiseBase64Target = await fsp.readlink("./link.txt", { encoding: "base64" });
                  const promiseBufferPathTarget = await fsp.readlink(Buffer.from("./link.txt"));
                  const urlTarget = fs.readlinkSync(url.pathToFileURL("./link.txt"));
                  const lstatLink = fs.lstatSync("./link.txt");
                  const dirents = fs.readdirSync(".", { withFileTypes: true });
                  const syncDirent = dirents.find((entry) => entry.name === "link.txt");
                  const promiseDirents = await fsp.readdir(".", { withFileTypes: true });
                  const promiseDirent = promiseDirents.find((entry) => entry.name === "link.txt");
                  const opened = await fsp.opendir(".");
                  let openedLink = false;
                  for await (const entry of opened) {
                    if (entry.name === "link.txt") {
                      openedLink = entry.isSymbolicLink();
                    }
                  }
                  process.chdir("./sub");
                  const cwdTarget = await fsp.readlink("./cwd-link.txt");
                  process.chdir("..");
                  const lutimesDate = new Date("2013-02-15T16:17:18Z");
                  fs.lutimesSync("./link.txt", lutimesDate, lutimesDate);
                  const lutimesLink = fs.lstatSync("./link.txt");
                  const lchownOwner = fs.lstatSync("./link.txt");
                  const lchownSymlinkOk = ownerChangeOk(
                    () => fs.lchownSync("./link.txt", lchownOwner.uid, lchownOwner.gid),
                    () => fs.lstatSync("./link.txt"),
                    lchownOwner.uid,
                    lchownOwner.gid
                  );
                  const lchmodLinkOk = lchmodSymlinkOk(
                    () => fs.lchmodSync("./link.txt", 0o600),
                    "./link.txt"
                  );
                  fs.symlinkSync("./target.txt", "./created-sync-link.txt");
                  await new Promise((resolve, reject) => {
                    fs.symlink("./target.txt", "./created-callback-link.txt", (error) => {
                      if (error) reject(error);
                      else resolve();
                    });
                  });
                  await fsp.symlink("./target.txt", "./created-promise-link.txt");
                  fs.symlinkSync(Buffer.from("./target.txt"), Buffer.from("./created-buffer-link.txt"));
                  await fsp.symlink(
                    "./target.txt",
                    url.pathToFileURL(path.resolve(process.cwd(), "./created-url-link.txt"))
                  );
                  process.chdir("./sub");
                  await fsp.symlink("../target.txt", "./created-cwd-link.txt");
                  const createdCwdTarget = await fsp.readlink("./created-cwd-link.txt");
                  process.chdir("..");
                  const createdSyncTarget = fs.readlinkSync("./created-sync-link.txt");
                  const createdCallbackTarget = await fsp.readlink("./created-callback-link.txt");
                  const createdPromiseTarget = await fsp.readlink("./created-promise-link.txt");
                  const createdBufferTarget = fs.readlinkSync("./created-buffer-link.txt");
                  const createdUrlTarget = await fsp.readlink("./created-url-link.txt");
                  const createdSyncLstat = fs.lstatSync("./created-sync-link.txt");
                  await capture("symlink.target_outside", () => fsp.symlink("../outside-created.txt", "./created-target-outside"));
                  await capture("symlink.path_outside", () => fsp.symlink("./target.txt", "../created-path-outside"));
                  await capture("symlink.invalid_type", () => fsp.symlink("./target.txt", "./created-invalid-type", "bad"));
                  await capture("readlink.outside", () => fsp.readlink("./outside-link"));
                  await capture("readlink.loop", () => fsp.readlink("./loop-link"));
                  await capture("lutimes.outside", () => fsp.lutimes("./outside-link", lutimesDate, lutimesDate));
                  await capture("lutimes.loop", () => fsp.lutimes("./loop-link", lutimesDate, lutimesDate));
                  await capture("lchown.outside", () => fsp.lchown("./outside-link", lchownOwner.uid, lchownOwner.gid));
                  await capture("lchmod.outside", () => fsp.lchmod("./outside-link", 0o600));
                  console.log("readlink.sync=" + normalize(syncTarget).endsWith("/target.txt"));
                  console.log("readlink.encoding=" + (
                    Buffer.isBuffer(syncBufferTarget) &&
                    Buffer.isBuffer(syncObjectBufferTarget) &&
                    normalize(syncBufferTarget.toString("utf8")).endsWith("/target.txt") &&
                    normalize(syncObjectBufferTarget.toString("utf8")).endsWith("/target.txt") &&
                    callbackHexTarget === Buffer.from(String(syncTarget), "utf8").toString("hex") &&
                    promiseBase64Target === Buffer.from(String(syncTarget), "utf8").toString("base64")
                  ));
                  console.log("readlink.callback=" + normalize(callbackTarget).endsWith("/target.txt"));
                  console.log("readlink.promise=" + normalize(promiseTarget).endsWith("/target.txt"));
                  console.log("readlink.pathlike=" + normalize(promiseBufferPathTarget).endsWith("/target.txt"));
                  console.log("readlink.url=" + normalize(urlTarget).endsWith("/target.txt"));
                  console.log("readlink.cwd=" + normalize(cwdTarget).endsWith("/target.txt"));
                  console.log("readlink.lstat=" + lstatLink.isSymbolicLink());
                  console.log("readlink.dirent.sync=" + (syncDirent && syncDirent.isSymbolicLink()));
                  console.log("readlink.dirent.promise=" + (promiseDirent && promiseDirent.isSymbolicLink()));
                  console.log("readlink.dirent.opendir=" + openedLink);
                  console.log("lutimes.symlink=" + (
                    lutimesLink.isSymbolicLink() &&
                    closeTime(lutimesLink.mtimeMs, lutimesDate.getTime())
                  ));
                  console.log("lchown.symlink=" + lchownSymlinkOk);
                  console.log("lchmod.symlink=" + lchmodLinkOk);
                  console.log("symlink.types=" + [
                    fs.symlinkSync,
                    fs.symlink,
                    fsp.symlink
                  ].every((value) => typeof value === "function"));
                  console.log("symlink.sync=" + (
                    createdSyncLstat.isSymbolicLink() &&
                    normalize(createdSyncTarget).endsWith("target.txt")
                  ));
                  console.log("symlink.callback=" + normalize(createdCallbackTarget).endsWith("target.txt"));
                  console.log("symlink.promise=" + normalize(createdPromiseTarget).endsWith("target.txt"));
                  console.log("symlink.pathlike=" + normalize(createdBufferTarget).endsWith("target.txt"));
                  console.log("symlink.url=" + normalize(createdUrlTarget).endsWith("target.txt"));
                  console.log("symlink.cwd=" + normalize(createdCwdTarget).endsWith("target.txt"));
                }

                return main();
                """.trimIndent(),
                "<embedded-scoped-fs-readlink-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("readlink.sync=true"))
            assertTrue(result.stdout.contains("readlink.encoding=true"))
            assertTrue(result.stdout.contains("readlink.callback=true"))
            assertTrue(result.stdout.contains("readlink.promise=true"))
            assertTrue(result.stdout.contains("readlink.pathlike=true"))
            assertTrue(result.stdout.contains("readlink.url=true"))
            assertTrue(result.stdout.contains("readlink.cwd=true"))
            assertTrue(result.stdout.contains("readlink.lstat=true"))
            assertTrue(result.stdout.contains("readlink.dirent.sync=true"))
            assertTrue(result.stdout.contains("readlink.dirent.promise=true"))
            assertTrue(result.stdout.contains("readlink.dirent.opendir=true"))
            assertTrue(result.stdout.contains("readlink.outside.ok=false"))
            assertTrue(result.stdout.contains("readlink.outside.code=EPERM"))
            assertTrue(result.stdout.contains("lutimes.symlink=true"))
            assertTrue(result.stdout.contains("lchown.symlink=true"))
            assertTrue(result.stdout.contains("lchmod.symlink=true"))
            assertTrue(result.stdout.contains("symlink.types=true"))
            assertTrue(result.stdout.contains("symlink.sync=true"))
            assertTrue(result.stdout.contains("symlink.callback=true"))
            assertTrue(result.stdout.contains("symlink.promise=true"))
            assertTrue(result.stdout.contains("symlink.pathlike=true"))
            assertTrue(result.stdout.contains("symlink.url=true"))
            assertTrue(result.stdout.contains("symlink.cwd=true"))
            assertTrue(result.stdout.contains("symlink.target_outside.ok=false"))
            assertTrue(result.stdout.contains("symlink.target_outside.code=EPERM"))
            assertTrue(result.stdout.contains("symlink.path_outside.ok=false"))
            assertTrue(result.stdout.contains("symlink.path_outside.code=EPERM"))
            assertTrue(result.stdout.contains("symlink.invalid_type.ok=false"))
            assertTrue(result.stdout.contains("symlink.invalid_type.code=ERR_INVALID_ARG_VALUE"))
            assertTrue(result.stdout.contains("lutimes.outside.ok=false"))
            assertTrue(result.stdout.contains("lutimes.outside.code=EPERM"))
            assertTrue(result.stdout.contains("lchown.outside.ok=false"))
            assertTrue(result.stdout.contains("lchown.outside.code=EPERM"))
            assertTrue(result.stdout.contains("lchmod.outside.ok=false"))
            assertTrue(result.stdout.contains("lchmod.outside.code=EPERM"))
            assertTrue(result.stdout.contains("symlink escapes sandboxRoot"))
            assertTrue(
                result.stdout.contains("readlink.loop.ok=true") ||
                    result.stdout.contains("readlink.loop.ok=false")
            )
        } finally {
            scriptDir.deleteRecursively()
            outsideDir.deleteRecursively()
        }
    }

    @Test
    fun packageBinSymlinkScurryLiteUsesReadlinkWhenSymlinkCreationIsAvailable() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-symlink-scurry-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create symlink scurry test dir: $absolutePath" }
        }
        val outsideDir = File(context.cacheDir, "embedded-symlink-scurry-outside-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create symlink scurry outside dir: $absolutePath" }
        }
        try {
            val toolDir = File(scriptDir, "symlink-tool").apply {
                check(mkdirs()) { "Failed to create symlink tool dir: $absolutePath" }
            }
            File(toolDir, "package.json").writeText(
                """{"name":"symlink-tool","bin":{"symlink-tool":"./cli.js"}}""",
                StandardCharsets.UTF_8,
            )
            File(toolDir, "cli.js").writeText(
                """
                #!/usr/bin/env node
                const fs = require("fs");
                const fsp = require("fs/promises");
                const path = require("path");
                const { Buffer } = require("buffer");
                const scurry = require("symlink-scurry-lite");

                function argValue(name) {
                  const index = process.argv.indexOf(name);
                  return index >= 0 ? process.argv[index + 1] : undefined;
                }

                async function main() {
                  const cwd = argValue("--cwd") || ".";
                  const out = argValue("--out") || "./symlink-scurry.json";
                  process.chdir(cwd);
                  const result = await scurry.scan(".");
                  await fsp.writeFile(out, Buffer.from(JSON.stringify(result), "utf8"));
                  const stored = JSON.parse(await fsp.readFile(out, "utf8"));
                  console.log("symlink.scurry.ready=" + (
                    stored.files.includes("target.txt") &&
                    stored.links.includes("link.txt") &&
                    stored.escapeRejected === true
                  ));
                  console.log("symlink.scurry.readlink=" + stored.readlinkOk);
                  console.log("symlink.scurry.dirent=" + stored.direntOk);
                  console.log("symlink.scurry.escape_rejected=" + stored.escapeRejected);
                }

                return main();
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )
            val packageDir = File(toolDir, "node_modules/symlink-scurry-lite").apply {
                check(mkdirs()) { "Failed to create symlink scurry package dir: $absolutePath" }
            }
            File(packageDir, "package.json").writeText(
                """{"name":"symlink-scurry-lite","version":"1.0.0","exports":{".":"./index.js"}}""",
                StandardCharsets.UTF_8,
            )
            File(packageDir, "index.js").writeText(
                """
                const fsp = require("fs/promises");
                const path = require("path");

                function normalize(value) {
                  return String(value || ".").replace(/\\/g, "/").replace(/^\.\/+/, "");
                }

                async function scan(relativeDir) {
                  const files = [];
                  const links = [];
                  const rejected = [];
                  let readlinkOk = false;
                  let direntOk = false;
                  const entries = await fsp.readdir(relativeDir, { withFileTypes: true });
                  for (const entry of entries) {
                    const entryPath = normalize(path.join(relativeDir, entry.name));
                    if (entry.isSymbolicLink()) {
                      direntOk = true;
                      try {
                        const target = await fsp.readlink(entryPath);
                        links.push(entryPath);
                        readlinkOk = readlinkOk || normalize(target).endsWith("target.txt");
                      } catch (error) {
                        rejected.push(String(error.code) + ":" + /symlink escapes sandboxRoot/.test(String(error.message)));
                      }
                    } else if (entry.isDirectory()) {
                      const child = await scan(entryPath);
                      files.push(...child.files);
                      links.push(...child.links);
                      rejected.push(...child.rejected);
                      readlinkOk = readlinkOk || child.readlinkOk;
                      direntOk = direntOk || child.direntOk;
                    } else if (entry.isFile()) {
                      files.push(entryPath);
                    }
                  }
                  files.sort();
                  links.sort();
                  return {
                    files,
                    links,
                    rejected,
                    readlinkOk,
                    direntOk,
                    escapeRejected: rejected.some((item) => item === "EPERM:true")
                  };
                }

                exports.scan = scan;
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )
            val workspace = File(scriptDir, "workspace").apply {
                check(mkdirs()) { "Failed to create symlink workspace: $absolutePath" }
            }
            val target = File(workspace, "target.txt").apply {
                writeText("target", StandardCharsets.UTF_8)
            }
            val link = File(workspace, "link.txt")
            val outsideTarget = File(outsideDir, "outside.txt").apply {
                writeText("outside", StandardCharsets.UTF_8)
            }
            val outsideLink = File(workspace, "outside-link")
            val symlinkReady = try {
                Files.createSymbolicLink(link.toPath(), target.toPath())
                Files.createSymbolicLink(outsideLink.toPath(), outsideTarget.toPath())
                true
            } catch (_: Throwable) {
                false
            }
            assumeTrue("Symlink creation unavailable on this device", symlinkReady)

            val result = runEmbeddedPackageBin(
                projectDir = scriptDir,
                packageDir = toolDir,
                binName = "symlink-tool",
                args = listOf("--cwd", "workspace", "--out", "symlink-result.json"),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("symlink.scurry.ready=true"))
            assertTrue(result.stdout.contains("symlink.scurry.readlink=true"))
            assertTrue(result.stdout.contains("symlink.scurry.dirent=true"))
            assertTrue(result.stdout.contains("symlink.scurry.escape_rejected=true"))
            val output = JSONObject(File(workspace, "symlink-result.json").readText(StandardCharsets.UTF_8))
            assertTrue(output.getJSONArray("files").join("|").contains("target.txt"))
            assertTrue(output.getJSONArray("links").join("|").contains("link.txt"))
            assertTrue(output.getBoolean("escapeRejected"))
        } finally {
            scriptDir.deleteRecursively()
            outsideDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsPromisesRejectSecurityAndMissingPathCases() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-promises-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs promises deny test dir: $absolutePath" }
        }
        val outside = File(scriptDir.parentFile, "${scriptDir.name}-outside.txt").apply {
            delete()
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const fsp = require("fs/promises");
                fs.mkdirSync("./dir", { recursive: true });
                const nulPath = "bad" + String.fromCharCode(0) + "path";

                function capture(label, action) {
                  return Promise.resolve()
                    .then(action)
                    .then(() => {
                      console.log(label + ".unexpected=true");
                    })
                    .catch((error) => {
                      console.log(label + ".isError=" + (error instanceof Error));
                      console.log(label + ".code=" + error.code);
                      console.log(label + ".message=" + String(error.message).replace(/\s+/g, " "));
                    });
                }

                return Promise.all([
                  capture("absolute", () => fsp.readFile("/sdcard/file.txt", "utf8")),
                  capture("escape", () => fsp.writeFile("../${outside.name}", "x", "utf8")),
                  capture("nul", () => fsp.readFile(nulPath, "utf8")),
                  capture("missing", () => fsp.readFile("./missing.txt", "utf8")),
                  capture("rmRoot", () => fsp.rm(".", { recursive: true, force: true })),
                  capture("unlinkDir", () => fsp.unlink("./dir"))
                ]).then(() => {
                  console.log("fsp.security.done=true");
                });
                """.trimIndent(),
                "<embedded-scoped-fs-promises-deny-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            listOf("absolute", "escape", "nul", "missing", "rmRoot", "unlinkDir").forEach { label ->
                assertTrue(result.stdout.contains("$label.isError=true"))
                assertTrue(result.stdout.contains("$label.message="))
                assertFalse(result.stdout.contains("$label.unexpected=true"))
            }
            assertTrue(result.stdout.contains("absolute.code=EPERM"))
            assertTrue(result.stdout.contains("escape.code=EPERM"))
            assertTrue(result.stdout.contains("nul.code=EPERM"))
            assertTrue(result.stdout.contains("missing.code=ENOENT"))
            assertTrue(result.stdout.contains("rmRoot.code=EPERM"))
            assertTrue(result.stdout.contains("unlinkDir.code=EISDIR"))
            assertTrue(result.stdout.contains("fsp.security.done=true"))
            assertTrue(scriptDir.exists())
            assertFalse(outside.exists())
        } finally {
            outside.delete()
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsOpenAsBlobSupportsPathLikeBlobReadsAndRejectsUnsafePaths() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-open-as-blob-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs openAsBlob test dir: $absolutePath" }
        }
        val outside = File(scriptDir.parentFile, "${scriptDir.name}-outside.txt").apply {
            writeText("outside", StandardCharsets.UTF_8)
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const nodeFs = require("node:fs");
                const fsp = require("fs/promises");
                const path = require("path");
                const url = require("url");
                const consumers = require("stream/consumers");
                const { Buffer } = require("buffer");

                fs.mkdirSync("./blob/sub", { recursive: true });
                fs.writeFileSync("./blob/sub/file.txt", "hello blob", "utf8");
                const nulPath = "bad" + String.fromCharCode(0) + "path";
                const outsideUrl = new URL(${jsStringLiteral(outside.toURI().toString())});

                async function capture(label, action) {
                  try {
                    await action();
                    console.log(label + ".unexpected=true");
                  } catch (error) {
                    console.log(label + ".isError=" + (error instanceof Error));
                    console.log(label + ".code=" + error.code);
                    console.log(label + ".message=" + String(error.message).replace(/\s+/g, " "));
                  }
                }

                async function readWebStream(webStream) {
                  const reader = webStream.getReader();
                  const chunks = [];
                  try {
                    for (;;) {
                      const result = await reader.read();
                      if (result.done) {
                        break;
                      }
                      chunks.push(Buffer.from(result.value));
                    }
                  } finally {
                    if (typeof reader.releaseLock === "function") {
                      reader.releaseLock();
                    }
                  }
                  return Buffer.concat(chunks).toString("utf8");
                }

                async function main() {
                  const stringBlob = await fs.openAsBlob("./blob/sub/file.txt", { type: "text/plain" });
                  const bufferBlob = await fs.openAsBlob(Buffer.from("./blob/sub/file.txt"));
                  const urlBlob = await fs.openAsBlob(
                    url.pathToFileURL(path.resolve(process.cwd(), "./blob/sub/file.txt")),
                    { type: "text/custom" }
                  );
                  const stringText = await stringBlob.text();
                  const bufferText = Buffer.from(await bufferBlob.arrayBuffer()).toString("utf8");
                  const urlText = await urlBlob.text();
                  const arrayTextFirst = Buffer.from(await stringBlob.arrayBuffer()).toString("utf8");
                  const arrayTextSecond = Buffer.from(await stringBlob.arrayBuffer()).toString("utf8");
                  const consumerStreamText = await consumers.text(stringBlob.stream());
                  const manualStreamText = await readWebStream(urlBlob.stream());
                  const slice = stringBlob.slice(6, 10, "text/slice");
                  const sliceText = await slice.text();

                  console.log("openAsBlob.surface=" + (
                    typeof fs.openAsBlob === "function" &&
                    typeof nodeFs.openAsBlob === "function" &&
                    typeof fsp.openAsBlob === "undefined"
                  ));
                  console.log("openAsBlob.string=" + (
                    stringBlob.size === 10 &&
                    stringBlob.type === "text/plain" &&
                    stringText === "hello blob"
                  ));
                  console.log("openAsBlob.pathlike=" + (
                    bufferText === "hello blob" &&
                    urlBlob.size === 10 &&
                    urlBlob.type === "text/custom" &&
                    urlText === "hello blob"
                  ));
                  console.log("openAsBlob.web=" + (
                    typeof stringBlob.stream === "function" &&
                    arrayTextFirst === "hello blob" &&
                    arrayTextSecond === "hello blob" &&
                    consumerStreamText === "hello blob" &&
                    manualStreamText === "hello blob"
                  ));
                  console.log("openAsBlob.slice=" + (
                    slice.size === 4 &&
                    slice.type === "text/slice" &&
                    sliceText === "blob"
                  ));

                  await capture("openAsBlob.escape", () => fs.openAsBlob("../${outside.name}"));
                  await capture("openAsBlob.buffer_escape", () => fs.openAsBlob(Buffer.from("../${outside.name}")));
                  await capture("openAsBlob.url_escape", () => fs.openAsBlob(outsideUrl));
                  await capture("openAsBlob.absolute", () => fs.openAsBlob("/sdcard/autojs6-open-as-blob.txt"));
                  await capture("openAsBlob.missing", () => fs.openAsBlob("./blob/sub/missing.txt"));
                  await capture("openAsBlob.nul", () => fs.openAsBlob(nulPath));
                  await capture("openAsBlob.invalid_options", () => fs.openAsBlob("./blob/sub/file.txt", "text/plain"));
                  await capture("openAsBlob.invalid_type", () => fs.openAsBlob("./blob/sub/file.txt", { type: 42 }));
                  console.log("openAsBlob.security.done=true");
                }

                return main();
                """.trimIndent(),
                "<embedded-scoped-fs-open-as-blob-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("openAsBlob.surface=true"))
            assertTrue(result.stdout.contains("openAsBlob.string=true"))
            assertTrue(result.stdout.contains("openAsBlob.pathlike=true"))
            assertTrue(result.stdout.contains("openAsBlob.web=true"))
            assertTrue(result.stdout.contains("openAsBlob.slice=true"))
            assertTrue(result.stdout.contains("openAsBlob.escape.isError=true"))
            assertTrue(result.stdout.contains("openAsBlob.escape.code=EPERM"))
            assertTrue(result.stdout.contains("openAsBlob.buffer_escape.isError=true"))
            assertTrue(result.stdout.contains("openAsBlob.buffer_escape.code=EPERM"))
            assertTrue(result.stdout.contains("openAsBlob.url_escape.isError=true"))
            assertTrue(result.stdout.contains("openAsBlob.url_escape.code=EPERM"))
            assertTrue(result.stdout.contains("openAsBlob.absolute.isError=true"))
            assertTrue(result.stdout.contains("openAsBlob.absolute.code=EPERM"))
            assertTrue(result.stdout.contains("openAsBlob.missing.isError=true"))
            assertTrue(result.stdout.contains("openAsBlob.missing.code=ENOENT"))
            assertTrue(result.stdout.contains("openAsBlob.nul.isError=true"))
            assertTrue(result.stdout.contains("openAsBlob.nul.code=EPERM"))
            assertTrue(result.stdout.contains("openAsBlob.invalid_options.isError=true"))
            assertTrue(result.stdout.contains("openAsBlob.invalid_options.code=ERR_INVALID_ARG_TYPE"))
            assertTrue(result.stdout.contains("openAsBlob.invalid_type.isError=true"))
            assertTrue(result.stdout.contains("openAsBlob.invalid_type.code=ERR_INVALID_ARG_TYPE"))
            assertTrue(result.stdout.contains("openAsBlob.security.done=true"))
            assertFalse(result.stdout.contains(".unexpected=true"))
        } finally {
            outside.delete()
            scriptDir.deleteRecursively()
        }
    }

