                      try {
                        action();
                        return false;
                      } catch (error) {
                        return error instanceof Error && String(error.message).includes(token);
                      }
                    }

                    async function capturePromise(action, token) {
                      try {
                        await action();
                        return false;
                      } catch (error) {
                        return error instanceof Error && String(error.message).includes(token);
                      }
                    }

                    function captureCallback(start, token) {
                      return new Promise((resolve) => {
                        start((error) => {
                          resolve(error instanceof Error && String(error.message).includes(token));
                        });
                      });
                    }

                    function deniedRequire(name) {
                      try {
                        require(name);
                        return false;
                      } catch (error) {
                        return error && error.code === "ERR_AUTOJS6_EMBEDDED_NODE_BUILTIN_DISABLED" &&
                          String(error.message).includes(name);
                      }
                    }

                    function deniedResolve(name) {
                      try {
                        require.resolve(name);
                        return false;
                      } catch (error) {
                        return error && error.code === "ERR_AUTOJS6_EMBEDDED_NODE_BUILTIN_DISABLED" &&
                          String(error.message).includes(name);
                      }
                    }

                    function deniedGetBuiltin(name) {
                      try {
                        process.getBuiltinModule(name);
                        return false;
                      } catch (error) {
                        return String(error.message).includes("disabled") &&
                          String(error.message).includes(name);
                      }
                    }

                    exports.run = async function run() {
                      fs.mkdirSync("./npm-fs-failure/dir/sub", { recursive: true });
                      fs.writeFileSync("./npm-fs-failure/safe.txt", "safe", "utf8");
                      const nulPath = "bad" + String.fromCharCode(0) + "path";

                      const syncChecks = [
                        captureSync(() => fs.readFileSync("/sdcard/autojs6-fs-denied.txt", "utf8"), "rejects absolute path"),
                        captureSync(() => fs.writeFileSync("../${outsideFiles[0].name}", "x", "utf8"), "escapes working directory"),
                        captureSync(() => fs.readFileSync(nulPath, "utf8"), "rejects NUL"),
                        captureSync(() => fs.rmSync(".", { recursive: true, force: true }), "cannot remove workingDirectory root"),
                        captureSync(() => fs.unlinkSync("./npm-fs-failure/dir"), "rejects directories"),
                        captureSync(() => fs.copyFileSync("./npm-fs-failure/safe.txt", "../${outsideFiles[1].name}"), "escapes working directory"),
                        captureSync(() => fs.renameSync("./npm-fs-failure/safe.txt", "../${outsideFiles[2].name}"), "escapes working directory"),
                        captureSync(() => fs.truncateSync("../${outsideFiles[9].name}", 0), "escapes working directory"),
                        captureSync(() => fs.realpathSync("../${outsideFiles[27].name}"), "escapes working directory"),
                        captureSync(() => fs.rmdirSync("../${outsideFiles[28].name}"), "escapes working directory"),
                        captureSync(() => fs.rmdirSync("."), "cannot remove workingDirectory root"),
                        captureSync(() => fs.watch("../${outsideFiles[12].name}", () => {}), "escapes working directory"),
