                        captureSync(() => fs.lchmodSync("../${outsideFiles[54].name}", 0o600), "escapes working directory"),
                        captureSync(() => fs.lutimesSync("../${outsideFiles[18].name}", new Date(), new Date()), "escapes working directory"),
                        captureSync(() => fs.lutimesSync("./npm-fs-failure/missing-lutimes.txt", new Date(), new Date()), "path does not exist"),
