                        captureSync(() => fs.globSync(["npm-fs-failure/**/*.txt", "/sdcard/**/*.txt"]), "absolute glob pattern"),
                        captureSync(() => fs.globSync("**/*.txt", { cwd: "./npm-fs-failure/safe.txt" }), "cwd must be a directory")
                      ];
                      const promiseChecks = await Promise.all([
                        capturePromise(() => fsp.readFile("/sdcard/autojs6-fs-promise-denied.txt", "utf8"), "rejects absolute path"),
                        capturePromise(() => fsp.writeFile("../${outsideFiles[3].name}", "x", "utf8"), "escapes working directory"),
                        capturePromise(() => fsp.rm(".", { recursive: true, force: true }), "cannot remove workingDirectory root"),
                        capturePromise(() => fsp.unlink("./npm-fs-failure/dir"), "rejects directories"),
                        capturePromise(() => fsp.copyFile("./npm-fs-failure/safe.txt", "../${outsideFiles[4].name}"), "escapes working directory"),
                        capturePromise(() => fsp.rename("./npm-fs-failure/safe.txt", "../${outsideFiles[5].name}"), "escapes working directory"),
                        capturePromise(() => fsp.truncate("../${outsideFiles[10].name}", 0), "escapes working directory"),
                        capturePromise(() => fsp.realpath("../${outsideFiles[29].name}"), "escapes working directory"),
                        capturePromise(() => fsp.rmdir("../${outsideFiles[30].name}"), "escapes working directory"),
                        capturePromise(() => fsp.rmdir("."), "cannot remove workingDirectory root"),
                        capturePromise(() => fsp.chmod("../${outsideFiles[16].name}", 0o600), "escapes working directory"),
                        capturePromise(() => fsp.chmod("./npm-fs-failure/missing-chmod.txt", 0o600), "path does not exist"),
                        capturePromise(() => fsp.lchmod("../${outsideFiles[55].name}", 0o600), "escapes working directory"),
                        capturePromise(() => fsp.lutimes("../${outsideFiles[19].name}", new Date(), new Date()), "escapes working directory"),
                        capturePromise(() => fsp.lutimes("./npm-fs-failure/missing-promise-lutimes.txt", new Date(), new Date()), "path does not exist"),
                        capturePromise(() => fsp.chown("../${outsideFiles[23].name}", 0, 0), "escapes working directory"),
                        capturePromise(() => fsp.chown("./npm-fs-failure/missing-promise-chown.txt", 0, 0), "path does not exist"),
                        capturePromise(() => fsp.lchown("../${outsideFiles[24].name}", 0, 0), "escapes working directory"),
                        capturePromise(() => fsp.lchown("./npm-fs-failure/missing-promise-lchown.txt", 0, 0), "path does not exist"),
                        capturePromise(() => fsp.symlink("../../${outsideFiles[36].name}", "./npm-fs-failure/promise-symlink-target"), "target escapes working directory"),
                        capturePromise(() => fsp.symlink("./npm-fs-failure/safe.txt", "../${outsideFiles[37].name}"), "escapes working directory"),
                        capturePromise(() => fs.openAsBlob("../${outsideFiles[40].name}"), "escapes working directory"),
                        capturePromise(() => fsp.glob("../${outsideFiles[42].name}/**"), "parent segment"),
                        capturePromise(() => fsp.glob("**/*.txt", { cwd: "../${outsideFiles[42].name}" }), "escapes working directory"),
                        capturePromise(() => fsp.glob(["npm-fs-failure/**/*.txt", nulPath]), "NUL"),
                        capturePromise(() => fsp.readdir("../${outsideFiles[48].name}", { recursive: true }), "escapes working directory"),
                        capturePromise(() => fsp.opendir("../${outsideFiles[49].name}", { recursive: true }), "escapes working directory"),
                        capturePromise(() => fsp.mkdtempDisposable("../${outsideFiles[53].name}"), "escapes working directory")
                      ]);
                      const callbackChecks = await Promise.all([
                        captureCallback((callback) => fs.readFile("/sdcard/autojs6-fs-callback-denied.txt", "utf8", callback), "rejects absolute path"),
                        captureCallback((callback) => fs.writeFile("../${outsideFiles[6].name}", "x", "utf8", callback), "escapes working directory"),
                        captureCallback((callback) => fs.rm(".", { recursive: true, force: true }, callback), "cannot remove workingDirectory root"),
                        captureCallback((callback) => fs.unlink("./npm-fs-failure/dir", callback), "rejects directories"),
                        captureCallback((callback) => fs.cp("./npm-fs-failure/safe.txt", "../${outsideFiles[7].name}", callback), "escapes working directory"),
                        captureCallback((callback) => fs.copyFile("./npm-fs-failure/safe.txt", "../${outsideFiles[31].name}", callback), "escapes working directory"),
                        captureCallback((callback) => fs.rename("./npm-fs-failure/safe.txt", "../${outsideFiles[8].name}", callback), "escapes working directory"),
                        captureCallback((callback) => fs.truncate("../${outsideFiles[11].name}", 0, callback), "escapes working directory"),
                        captureCallback((callback) => fs.realpath("../${outsideFiles[32].name}", callback), "escapes working directory"),
                        captureCallback((callback) => fs.rmdir("../${outsideFiles[33].name}", callback), "escapes working directory"),
                        captureCallback((callback) => fs.rmdir(".", callback), "cannot remove workingDirectory root"),
                        captureCallback((callback) => fs.chmod("../${outsideFiles[17].name}", 0o600, callback), "escapes working directory"),
                        captureCallback((callback) => fs.chmod("./npm-fs-failure/missing-callback-chmod.txt", 0o600, callback), "path does not exist"),
                        captureCallback((callback) => fs.lchmod("../${outsideFiles[56].name}", 0o600, callback), "escapes working directory"),
                        captureCallback((callback) => fs.lutimes("../${outsideFiles[20].name}", new Date(), new Date(), callback), "escapes working directory"),
                        captureCallback((callback) => fs.lutimes("./npm-fs-failure/missing-callback-lutimes.txt", new Date(), new Date(), callback), "path does not exist"),
                        captureCallback((callback) => fs.chown("../${outsideFiles[25].name}", 0, 0, callback), "escapes working directory"),
                        captureCallback((callback) => fs.chown("./npm-fs-failure/missing-callback-chown.txt", 0, 0, callback), "path does not exist"),
                        captureCallback((callback) => fs.lchown("../${outsideFiles[26].name}", 0, 0, callback), "escapes working directory"),
                        captureCallback((callback) => fs.lchown("./npm-fs-failure/missing-callback-lchown.txt", 0, 0, callback), "path does not exist"),
                        captureCallback((callback) => fs.symlink("../../${outsideFiles[38].name}", "./npm-fs-failure/callback-symlink-target", callback), "target escapes working directory"),
                        captureCallback((callback) => fs.symlink("./npm-fs-failure/safe.txt", "../${outsideFiles[39].name}", callback), "escapes working directory"),
                        captureCallback((callback) => fs.glob("../${outsideFiles[43].name}/**", callback), "parent segment"),
                        captureCallback((callback) => fs.glob(["npm-fs-failure/**/*.txt", "/sdcard/**/*.txt"], callback), "absolute glob pattern"),
                        captureCallback((callback) => fs.glob("**/*.txt", { cwd: "./npm-fs-failure/safe.txt" }, callback), "cwd must be a directory"),
                        captureCallback((callback) => fs.readdir("../${outsideFiles[50].name}", { recursive: true }, callback), "escapes working directory"),
                        captureCallback((callback) => fs.opendir("../${outsideFiles[51].name}", { recursive: true }, callback), "escapes working directory")
                      ]);

                      const aliasGuard = fs === nodeFs &&
                        fs.promises === fsp &&
                        fsp === nodeFsp &&
                        require.resolve("fs") === "fs" &&
                        require.resolve("node:fs") === "fs" &&
                        require.resolve("fs/promises") === "fs/promises" &&
                        require.resolve("node:fs/promises") === "fs/promises" &&
                        fs.shadow !== true &&
                        fsp.shadow !== true &&
                        Object.isFrozen(fs) &&
                        Object.isFrozen(fsp);
                      const hiddenGuard = [
                        typeof fs.createReadStream,
                        typeof fs.createWriteStream,
                        typeof fs.watch,
                        typeof fs.watchFile,
                        typeof fs.unwatchFile,
                        typeof fs.Stats,
                        typeof fs.Dirent,
                        typeof fs.Dir,
                        typeof fs.ReadStream,
                        typeof fs.WriteStream,
                        typeof fs.FileReadStream,
                        typeof fs.FileWriteStream,
                        typeof fs.Utf8Stream,
                        typeof fs.openAsBlob,
                        typeof fs.symlink,
                        typeof fs.symlinkSync,
                        typeof fs.chmod,
                        typeof fs.chmodSync,
                        typeof fs.lchmod,
                        typeof fs.lchmodSync,
                        typeof fs.copyFile,
                        typeof fs.realpath,
                        typeof fs.rmdir,
                        typeof fs.rmdirSync,
                        typeof fs.glob,
                        typeof fs.globSync,
                        typeof fs.open,
                        typeof fs.openSync,
                        typeof fsp.open,
                        typeof fsp.symlink,
                        typeof fsp.chmod,
                        typeof fsp.lchmod,
                        typeof fsp.rmdir,
                        typeof fsp.glob,
                        typeof fsp.watch
                      ].every((value) => value === "function") &&
                        fs.F_OK === fs.constants.F_OK &&
                        fs.R_OK === fs.constants.R_OK &&
                        fs.W_OK === fs.constants.W_OK &&
                        fs.X_OK === fs.constants.X_OK &&
                        fs.COPYFILE_EXCL === fs.constants.COPYFILE_EXCL &&
                        fs.COPYFILE_FICLONE === fs.constants.COPYFILE_FICLONE &&
                        fs.COPYFILE_FICLONE_FORCE === fs.constants.COPYFILE_FICLONE_FORCE;
                      const limitedNetGuard = (() => {
                        const netBuiltin = require("node:net");
                        try {
                          netBuiltin.connect(80, "127.0.0.1");
                          return false;
                        } catch (error) {
                          return netBuiltin.isIP("127.0.0.1") === 4 &&
                            error && error.code === "ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED";
                        }
                      })();
                      const limitedTlsGuard = (() => {
                        const tlsBuiltin = require("node:tls");
                        try {
                          tlsBuiltin.connect(443, "example.com");
                          return false;
                        } catch (error) {
                          return require.resolve("node:tls") === "tls" &&
                            typeof tlsBuiltin.createSecureContext === "function" &&
                            error && error.code === "ERR_AUTOJS6_EMBEDDED_NODE_NETWORK_DISABLED";
                        }
                      })();
                      const deniedGuard = deniedRequire("child_process") &&
                        limitedNetGuard &&
                        limitedTlsGuard &&
                        deniedRequire("worker_threads") &&
                        deniedGetBuiltin("fs");
                      const treeOk = fs.existsSync("./npm-fs-failure/safe.txt") &&
                        fs.existsSync("./npm-fs-failure/dir/sub");
                      assert.equal(syncChecks.filter(Boolean).length, syncChecks.length);
                      assert.equal(promiseChecks.filter(Boolean).length, promiseChecks.length);
                      assert.equal(callbackChecks.filter(Boolean).length, callbackChecks.length);
                      await fsp.rm("./npm-fs-failure", { recursive: true, force: true });
                      return {
                        ok: syncChecks.every(Boolean) &&
                          promiseChecks.every(Boolean) &&
                          callbackChecks.every(Boolean) &&
                          aliasGuard &&
                          hiddenGuard &&
                          deniedGuard &&
                          treeOk &&
                          !fs.existsSync("./npm-fs-failure"),
                        sync: syncChecks.filter(Boolean).length + "/" + syncChecks.length,
                        promise: promiseChecks.filter(Boolean).length + "/" + promiseChecks.length,
                        callback: callbackChecks.filter(Boolean).length + "/" + callbackChecks.length,
                        guards: aliasGuard && hiddenGuard && deniedGuard,
                        tree: treeOk && !fs.existsSync("./npm-fs-failure")
                      };
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val fsShadow = File(scriptDir, "node_modules/fs/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(compose, fsShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertOutputOrder(result.stdout, "npm.fs.failure.scheduled=true", "npm.fs.failure.ok=true")
            assertTrue(result.stdout.contains("npm.fs.failure.ok=true"))
            assertTrue(result.stdout.contains("npm.fs.failure.sync=45/45"))
            assertTrue(result.stdout.contains("npm.fs.failure.promise=28/28"))
            assertTrue(result.stdout.contains("npm.fs.failure.callback=27/27"))
            assertTrue(result.stdout.contains("npm.fs.failure.guards=true"))
            assertTrue(result.stdout.contains("npm.fs.failure.tree=true"))
            outsideFiles.forEach { outside ->
                assertFalse("Outside file should not be created: ${outside.absolutePath}", outside.exists())
            }
        } finally {
            outsideFiles.forEach { it.delete() }
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun pureJsNpmFsPromisesSmokeUsesNodeModulesAndPromiseDrain() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-npm-fs-promises-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create npm fs promises test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const compose = require("pkg-fsp-compose");
                    const run = compose.run().then((result) => {
                      console.log("npm.fsp.ok=" + result.ok);
                      console.log("npm.fsp.alias=" + result.alias);
                      console.log("npm.fsp.text=" + result.text);
                      console.log("npm.fsp.blob=" + result.blob);
                      console.log("npm.fsp.blobRejected=" + result.blobRejected);
                      console.log("npm.fsp.glob=" + result.glob);
                      console.log("npm.fsp.globRejected=" + result.globRejected);
                      console.log("npm.fsp.entries=" + result.entries);
                      console.log("npm.fsp.stat=" + result.stat);
                      console.log("npm.fsp.cleaned=" + result.cleaned);
                    });
                    console.log("npm.fsp.scheduled=true");
                    return run;
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val compose = File(scriptDir, "node_modules/pkg-fsp-compose/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fs = require("fs");
                    const fsp = require("fs/promises");
                    const nodeFsp = require("node:fs/promises");
                    const reader = require("pkg-fsp-reader");
                    const blobReader = require("pkg-fsp-blob-reader");
                    const globReader = require("pkg-fsp-glob-reader");

                    exports.run = async function run() {
                      await fsp.mkdir("./pkg-fsp/sub", { recursive: true });
                      await fsp.writeFile("./pkg-fsp/sub/file.txt", "pkg", "utf8");
                      await fsp.appendFile("./pkg-fsp/sub/file.txt", "-fsp", "utf8");
                      await fsp.writeFile("./pkg-fsp/sub/main.js", "main", "utf8");
                      await fsp.writeFile("./pkg-fsp/sub/main.test.js", "test", "utf8");
                      const text = await reader.read("./pkg-fsp/sub/file.txt");
                      const blob = await blobReader.read("./pkg-fsp/sub/file.txt");
                      const glob = await globReader.read("./pkg-fsp");
                      const entries = await fsp.readdir("./pkg-fsp/sub");
                      const stat = await fsp.stat("./pkg-fsp/sub/file.txt");
                      const blobEscapeRejected = await blobReader.rejects("../pkg-fsp-escape.txt");
                      const globEscapeRejected = await globReader.rejects("../pkg-fsp-escape");
                      await fsp.rm("./pkg-fsp", { recursive: true, force: true });
                      return {
                        ok: text === "pkg-fsp" &&
                          blob.text === "pkg-fsp" &&
                          blob.type === "text/plain" &&
                          blob.size === text.length &&
                          blobEscapeRejected &&
                          glob === "sub/main.js" &&
                          globEscapeRejected &&
                          entries.includes("file.txt") &&
                          entries.includes("main.js") &&
                          stat.isFile() &&
                          !fs.existsSync("./pkg-fsp") &&
                          fs.promises === fsp &&
                          fsp === nodeFsp,
                        alias: fs.promises === fsp && fsp === nodeFsp,
                        text,
                        blob: blob.text + ":" + blob.type + ":" + blob.size,
                        blobRejected: blobEscapeRejected,
                        glob,
                        globRejected: globEscapeRejected,
                        entries: entries.includes("file.txt"),
                        stat: stat.isFile(),
                        cleaned: !fs.existsSync("./pkg-fsp")
                      };
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val blobReader = File(scriptDir, "node_modules/pkg-fsp-blob-reader/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fs = require("fs");
                    exports.read = async function read(file) {
                      const blob = await fs.openAsBlob(file, { type: "text/plain" });
                      return {
                        text: await blob.text(),
                        type: blob.type,
                        size: blob.size
                      };
                    };
                    exports.rejects = async function rejects(file) {
                      try {
                        await fs.openAsBlob(file);
                        return false;
                      } catch (error) {
                        return error && error.code === "EPERM" &&
                          String(error.message).includes("escapes working directory");
                      }
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val reader = File(scriptDir, "node_modules/pkg-fsp-reader/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fsp = require("fs/promises");
                    exports.read = function read(file) {
                      return fsp.readFile(file, "utf8");
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val globReader = File(scriptDir, "node_modules/pkg-fsp-glob-reader/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fsp = require("fs/promises");

                    exports.read = async function read(root) {
                      const matches = [];
                      for await (const entry of fsp.glob("**/*.js", {
                        cwd: root,
                        exclude: ["**/*.test.js"]
                      })) {
                        matches.push(String(entry).replace(/\\/g, "/"));
                      }
                      return matches.sort().join("|");
                    };

                    exports.rejects = async function rejects(root) {
                      try {
                        for await (const _ of fsp.glob("**/*.js", { cwd: root })) {
                        }
                        return false;
                      } catch (error) {
                        return error && error.code === "EPERM" &&
                          String(error.message).includes("escapes working directory");
                      }
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(compose, blobReader, globReader, reader),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertOutputOrder(result.stdout, "npm.fsp.scheduled=true", "npm.fsp.ok=true")
            assertTrue(result.stdout.contains("npm.fsp.ok=true"))
            assertTrue(result.stdout.contains("npm.fsp.alias=true"))
            assertTrue(result.stdout.contains("npm.fsp.text=pkg-fsp"))
            assertTrue(result.stdout.contains("npm.fsp.blob=pkg-fsp:text/plain:7"))
            assertTrue(result.stdout.contains("npm.fsp.blobRejected=true"))
            assertTrue(result.stdout.contains("npm.fsp.glob=sub/main.js"))
            assertTrue(result.stdout.contains("npm.fsp.globRejected=true"))
            assertTrue(result.stdout.contains("npm.fsp.entries=true"))
            assertTrue(result.stdout.contains("npm.fsp.stat=true"))
            assertTrue(result.stdout.contains("npm.fsp.cleaned=true"))
            assertFalse(File(scriptDir, "pkg-fsp").exists())
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsCallbackApisReturnErrorsForSecurityAndMissingPathCases() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-callback-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create callback scoped fs deny test dir: $absolutePath" }
        }
        val outside = File(scriptDir.parentFile, "${scriptDir.name}-outside.txt").apply {
            delete()
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                fs.mkdirSync("./dir", { recursive: true });
                const nulPath = "bad" + String.fromCharCode(0) + "path";
                let pending = 0;
                function capture(label, action) {
                  pending += 1;
                  action((error) => {
                    console.log(label + ".isError=" + (error instanceof Error));
                    console.log(label + ".code=" + error.code);
                    console.log(label + ".message=" + String(error.message).replace(/\s+/g, " "));
                    pending -= 1;
                    if (pending === 0) {
                      console.log("security.done=true");
                    }
                  });
                }
                capture("absolute", (callback) => fs.readFile("/sdcard/file.txt", "utf8", callback));
                capture("escape", (callback) => fs.writeFile("../${outside.name}", "x", "utf8", callback));
                capture("nul", (callback) => fs.readFile(nulPath, "utf8", callback));
                capture("missing", (callback) => fs.access("./missing.txt", callback));
                capture("rmRoot", (callback) => fs.rm(".", { recursive: true, force: true }, callback));
                capture("unlinkDir", (callback) => fs.unlink("./dir", callback));
                """.trimIndent(),
                "<embedded-scoped-fs-callback-deny-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            listOf("absolute", "escape", "nul", "missing", "rmRoot", "unlinkDir").forEach { label ->
                assertTrue(result.stdout.contains("$label.isError=true"))
                assertTrue(result.stdout.contains("$label.message="))
            }
            assertTrue(result.stdout.contains("absolute.code=EPERM"))
            assertTrue(result.stdout.contains("escape.code=EPERM"))
            assertTrue(result.stdout.contains("nul.code=EPERM"))
            assertTrue(result.stdout.contains("missing.code=ENOENT"))
            assertTrue(result.stdout.contains("rmRoot.code=EPERM"))
            assertTrue(result.stdout.contains("unlinkDir.code=EISDIR"))
            assertTrue(result.stdout.contains("security.done=true"))
            assertTrue(scriptDir.exists())
            assertFalse(outside.exists())
        } finally {
            outside.delete()
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun pureJsNpmCallbackFsSmokeUsesNodeModulesAndDrainsEventLoop() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-npm-callback-fs-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create npm callback fs test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const compose = require("pkg-callback-fs-compose");
                    compose.run((error, result) => {
                      if (error) throw error;
                      console.log("npm.callback.ok=" + result.ok);
                      console.log("npm.callback.text=" + result.text);
                      console.log("npm.callback.exists=" + result.exists);
                      console.log("npm.callback.stat=" + result.stat);
                      console.log("npm.callback.entries=" + result.entries);
                    });
                    console.log("npm.callback.scheduled=true");
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val compose = File(scriptDir, "node_modules/pkg-callback-fs-compose/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const writer = require("pkg-callback-fs-writer");
                    const reader = require("pkg-callback-fs-reader");
                    const probe = require("pkg-callback-fs-probe");
                    exports.run = function run(callback) {
                      writer.write("./pkg-callback.txt", "pkg", (writeError) => {
                        if (writeError) return callback(writeError);
                        reader.read("./pkg-callback.txt", (readError, text) => {
                          if (readError) return callback(readError);
                          probe.check("./pkg-callback.txt", (probeError, info) => {
                            if (probeError) return callback(probeError);
                            callback(null, {
                              ok: text === "pkg-ok" && info.exists && info.stat && info.entries,
                              text,
                              exists: info.exists,
                              stat: info.stat,
                              entries: info.entries
                            });
                          });
                        });
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val writer = File(scriptDir, "node_modules/pkg-callback-fs-writer/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fs = require("fs");
                    exports.write = function write(file, prefix, callback) {
                      fs.writeFile(file, prefix, "utf8", (writeError) => {
                        if (writeError) return callback(writeError);
                        fs.appendFile(file, "-ok", "utf8", callback);
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val reader = File(scriptDir, "node_modules/pkg-callback-fs-reader/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fs = require("fs");
                    exports.read = function read(file, callback) {
                      fs.readFile(file, "utf8", callback);
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val probe = File(scriptDir, "node_modules/pkg-callback-fs-probe/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fs = require("fs");
                    exports.check = function check(file, callback) {
                      fs.access(file, fs.constants.R_OK, (accessError) => {
                        if (accessError) return callback(accessError);
                        fs.stat(file, (statError, stat) => {
                          if (statError) return callback(statError);
                          fs.readdir(".", (readdirError, entries) => {
                            if (readdirError) return callback(readdirError);
                            callback(null, {
                              exists: true,
                              stat: stat.isFile(),
                              entries: entries.includes("pkg-callback.txt")
                            });
                          });
                        });
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(compose, writer, reader, probe),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertOutputOrder(result.stdout, "npm.callback.scheduled=true", "npm.callback.ok=true")
            assertTrue(result.stdout.contains("npm.callback.ok=true"))
            assertTrue(result.stdout.contains("npm.callback.text=pkg-ok"))
            assertTrue(result.stdout.contains("npm.callback.exists=true"))
            assertTrue(result.stdout.contains("npm.callback.stat=true"))
            assertTrue(result.stdout.contains("npm.callback.entries=true"))
            assertEquals("pkg-ok", File(scriptDir, "pkg-callback.txt").readText(StandardCharsets.UTF_8))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsCallbackApisValidateArgumentsOptionalFormsAndAsyncCallbacks() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-callback-semantics-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create callback fs semantics test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                fs.writeFileSync("./seed.txt", "hello", "utf8");
                fs.writeFileSync("./append-target.txt", "start", "utf8");
                fs.mkdirSync("./rm-dir/sub", { recursive: true });
                fs.mkdirSync("./rmdir-dir");

                function invalid(label, action) {
                  try {
                    action();
                    console.log(label + ".threw=false");
                  } catch (error) {
                    console.log(label + ".threw=true");
                    console.log(label + ".name=" + error.name);
                    console.log(label + ".code=" + error.code);
                  }
                }

                invalid("invalid.readFile", () => fs.readFile("./seed.txt"));
                invalid("invalid.writeFile", () => fs.writeFile("./missing-callback.txt", "x"));
                invalid("invalid.appendFile", () => fs.appendFile("./append-target.txt", "x"));
                invalid("invalid.access", () => fs.access("./seed.txt"));
                invalid("invalid.mkdir", () => fs.mkdir("./missing-callback-dir"));
                invalid("invalid.rm", () => fs.rm("./missing-callback-rm"));
                invalid("invalid.copyFile", () => fs.copyFile("./seed.txt", "./missing-copy-callback.txt"));
                invalid("invalid.realpath", () => fs.realpath("./seed.txt"));
                invalid("invalid.rmdir", () => fs.rmdir("./missing-callback-rmdir"));

                let pending = 0;
                let sync = true;
                function safeThis(value) {
                  return value === undefined || value === globalThis || (typeof global !== "undefined" && value === global);
                }
                function schedule(label, action, detail) {
                  pending += 1;
                  action(function (error, value) {
                    console.log(label + ".async=" + (!sync));
                    console.log(label + ".this.safe=" + safeThis(this));
                    console.log(label + ".err=" + (error === null));
                    if (detail) {
                      console.log(label + ".detail=" + detail(value));
                    }
                    pending -= 1;
                    if (pending === 0) {
                      console.log("callback.semantic.done=true");
                    }
                  });
                }

                schedule("read.default", (callback) => fs.readFile("./seed.txt", callback), (value) => Buffer.isBuffer(value) + "/" + value.toString());
                schedule("read.string", (callback) => fs.readFile("./seed.txt", "utf8", callback), (value) => value);
                schedule("read.object", (callback) => fs.readFile("./seed.txt", { encoding: "utf8" }, callback), (value) => value);
                schedule("write.string", (callback) => fs.writeFile("./write-string.txt", "x", callback));
                schedule("write.buffer", (callback) => fs.writeFile("./write-buffer.txt", Buffer.from("buf"), callback));
                schedule("append.string", (callback) => fs.appendFile("./append-target.txt", "-tail", "utf8", callback));
                schedule("access.default", (callback) => fs.access("./seed.txt", callback));
                schedule("access.mode", (callback) => fs.access("./seed.txt", fs.constants.R_OK, callback));
                schedule("stat.file", (callback) => fs.stat("./seed.txt", callback), (value) => value.isFile());
                schedule("copyFile.default", (callback) => fs.copyFile("./seed.txt", "./copy-callback.txt", callback), () => fs.readFileSync("./copy-callback.txt", "utf8"));
                schedule("realpath.default", (callback) => fs.realpath("./seed.txt", callback), (value) => value.replace(/\\/g, "/").endsWith("/seed.txt"));
                schedule("realpath.native", (callback) => fs.realpath.native("./seed.txt", callback), (value) => value.replace(/\\/g, "/").endsWith("/seed.txt"));
                schedule("mkdir.simple", (callback) => fs.mkdir("./simple-dir", callback));
                schedule("mkdir.recursive", (callback) => fs.mkdir("./recursive-dir/sub", { recursive: true }, callback));
                schedule("rm.recursive", (callback) => fs.rm("./rm-dir", { recursive: true, force: true }, callback));
                schedule("rm.forceMissing", (callback) => fs.rm("./missing-rm", { force: true }, callback));
                schedule("rmdir.simple", (callback) => fs.rmdir("./rmdir-dir", callback), () => !fs.existsSync("./rmdir-dir"));
                sync = false;
                console.log("callback.semantic.scheduled=true");
                """.trimIndent(),
                "<embedded-scoped-fs-callback-semantics-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            listOf("readFile", "writeFile", "appendFile", "access", "mkdir", "rm", "copyFile", "realpath", "rmdir").forEach { label ->
                assertTrue(result.stdout.contains("invalid.$label.threw=true"))
                assertTrue(result.stdout.contains("invalid.$label.name=TypeError"))
                assertTrue(result.stdout.contains("invalid.$label.code=ERR_INVALID_ARG_TYPE"))
            }
            listOf(
                "read.default",
                "read.string",
                "read.object",
                "write.string",
                "write.buffer",
                "append.string",
                "access.default",
                "access.mode",
                "stat.file",
                "copyFile.default",
                "realpath.default",
                "realpath.native",
                "mkdir.simple",
                "mkdir.recursive",
                "rm.recursive",
                "rm.forceMissing",
                "rmdir.simple",
            ).forEach { label ->
                assertTrue(result.stdout.contains("$label.async=true"))
                assertTrue(result.stdout.contains("$label.this.safe=true"))
                assertTrue(result.stdout.contains("$label.err=true"))
            }
            assertOutputOrder(result.stdout, "callback.semantic.scheduled=true", "read.default.async=true", "callback.semantic.done=true")
            assertTrue(result.stdout.contains("read.default.detail=true/hello"))
            assertTrue(result.stdout.contains("read.string.detail=hello"))
            assertTrue(result.stdout.contains("read.object.detail=hello"))
            assertTrue(result.stdout.contains("stat.file.detail=true"))
            assertTrue(result.stdout.contains("copyFile.default.detail=hello"))
            assertTrue(result.stdout.contains("realpath.default.detail=true"))
            assertTrue(result.stdout.contains("realpath.native.detail=true"))
            assertTrue(result.stdout.contains("rmdir.simple.detail=true"))
            assertEquals("start-tail", File(scriptDir, "append-target.txt").readText(StandardCharsets.UTF_8))
            assertEquals("x", File(scriptDir, "write-string.txt").readText(StandardCharsets.UTF_8))
            assertEquals("buf", File(scriptDir, "write-buffer.txt").readText(StandardCharsets.UTF_8))
            assertEquals("hello", File(scriptDir, "copy-callback.txt").readText(StandardCharsets.UTF_8))
            assertTrue(File(scriptDir, "simple-dir").isDirectory)
            assertTrue(File(scriptDir, "recursive-dir/sub").isDirectory)
            assertFalse(File(scriptDir, "rm-dir").exists())
            assertFalse(File(scriptDir, "rmdir-dir").exists())
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun scopedFsCallbackApisWorkWithUtilPromisifyAndPromiseDrain() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-scoped-fs-promisify-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create scoped fs promisify test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const { promisify } = require("util");
                const readFile = promisify(fs.readFile);
                const writeFile = promisify(fs.writeFile);
                const appendFile = promisify(fs.appendFile);
                const stat = promisify(fs.stat);
                const access = promisify(fs.access);
                const readdir = promisify(fs.readdir);
                const mkdir = promisify(fs.mkdir);
                const rm = promisify(fs.rm);

                const chain = writeFile("./promisify.txt", "hello", "utf8")
                  .then(() => appendFile("./promisify.txt", " world", "utf8"))
                  .then(() => readFile("./promisify.txt", "utf8"))
                  .then((text) => {
                    console.log("promisify.read=" + text);
                    return stat("./promisify.txt");
                  })
                  .then((info) => {
                    console.log("promisify.stat=" + info.isFile());
                    return access("./promisify.txt", fs.constants.R_OK);
                  })
                  .then(() => {
                    console.log("promisify.access=true");
                    return mkdir("./promisify-dir/sub", { recursive: true });
                  })
                  .then(() => writeFile("./promisify-dir/sub/file.txt", Buffer.from("buf")))
                  .then(() => readdir("./promisify-dir/sub"))
                  .then((entries) => {
                    console.log("promisify.readdir=" + entries.includes("file.txt"));
                    return rm("./promisify-dir", { recursive: true, force: true });
                  })
                  .then(() => rm("./missing-dir", { force: true }))
                  .then(() => readFile("./missing.txt").catch((error) => {
                    console.log("promisify.missing.code=" + error.code);
                  }))
                  .then(() => readFile("../outside.txt").catch((error) => {
                    console.log("promisify.escape.code=" + error.code);
                  }))
                  .then(() => {
                    console.log("promisify.fs.promises=" + typeof fs.promises);
                    console.log("promisify.done=true");
                    return "promisify-result";
                  });
                console.log("promisify.scheduled=true");
                return chain;
                """.trimIndent(),
                "<embedded-scoped-fs-promisify-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertOutputOrder(result.stdout, "promisify.scheduled=true", "promisify.read=hello world", "promisify.done=true")
            assertTrue(result.stdout.contains("promisify.read=hello world"))
            assertTrue(result.stdout.contains("promisify.stat=true"))
            assertTrue(result.stdout.contains("promisify.access=true"))
            assertTrue(result.stdout.contains("promisify.readdir=true"))
            assertTrue(result.stdout.contains("promisify.missing.code=ENOENT"))
            assertTrue(result.stdout.contains("promisify.escape.code=EPERM"))
            assertTrue(result.stdout.contains("promisify.fs.promises=object"))
            assertTrue(result.stdout.contains("promisify.done=true"))
            assertEquals("hello world", File(scriptDir, "promisify.txt").readText(StandardCharsets.UTF_8))
            assertFalse(File(scriptDir, "promisify-dir").exists())
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun pureJsNpmPromisifyFsSmokeUsesNodeModulesAndPromiseDrain() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-npm-promisify-fs-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create npm promisify fs test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const compose = require("pkg-promisify-fs-compose");
                    const run = compose.run().then((result) => {
                      console.log("npm.promisify.ok=" + result.ok);
                      console.log("npm.promisify.config=" + result.configName);
                      console.log("npm.promisify.text=" + result.text);
                      console.log("npm.promisify.access=" + result.access);
                      console.log("npm.promisify.missingFallback=" + result.missingFallback);
                      console.log("npm.promisify.missingCode=" + result.missingCode);
                      console.log("npm.promisify.fs.promises=" + result.promisesType);
                    });
                    console.log("npm.promisify.scheduled=true");
                    return run;
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val compose = File(scriptDir, "node_modules/pkg-promisify-fs-compose/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const { promisify } = require("util");
                    const fs = require("fs");
                    const writeFile = promisify(fs.writeFile);
                    const appendFile = promisify(fs.appendFile);
                    const readFile = promisify(fs.readFile);
                    const stat = promisify(fs.stat);
                    const access = promisify(fs.access);
                    const readdir = promisify(fs.readdir);
                    const mkdir = promisify(fs.mkdir);
                    const rm = promisify(fs.rm);
                    const configReader = require("pkg-config-reader-like");
                    const graceful = require("pkg-graceful-like");

                    exports.run = function run() {
                      return writeFile("./config.json", JSON.stringify({ name: "promisify-config", ok: true }), "utf8")
                        .then(() => mkdir("./promisify-work/sub", { recursive: true }))
                        .then(() => writeFile("./promisify-work/sub/file.txt", "inside", "utf8"))
                        .then(() => appendFile("./promisify-work/sub/file.txt", "-done", "utf8"))
                        .then(() => configReader.read())
                        .then((config) => Promise.all([
                          readFile("./promisify-work/sub/file.txt", "utf8"),
                          stat("./promisify-work/sub/file.txt"),
                          access("./promisify-work/sub/file.txt", fs.constants.R_OK).then(() => true),
                          readdir("./promisify-work/sub"),
                          new Promise((resolve, reject) => {
                            graceful.existsReadable("./missing-config.json", (error, exists) => {
                              if (error) reject(error);
                              else resolve(exists === false);
                            });
                          })
                        ]).then(([text, info, accessOk, entries, missingFallback]) => {
                          return rm("./promisify-work", { recursive: true, force: true })
                            .then(() => readFile("./missing-config.json").catch((error) => error.code))
                            .then((missingCode) => ({
                              ok: config.ok && text === "inside-done" && info.isFile() && accessOk && entries.includes("file.txt") && missingFallback && missingCode === "ENOENT",
                              configName: config.name,
                              text,
                              access: accessOk,
                              missingFallback,
                              missingCode,
                              promisesType: typeof fs.promises
                            }));
                        }));
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val configReader = File(scriptDir, "node_modules/pkg-config-reader-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const path = require("path");
                    const loader = require("pkg-json-loader-like");
                    exports.read = function read() {
                      return loader.load(path.join(".", "config.json"));
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val jsonLoader = File(scriptDir, "node_modules/pkg-json-loader-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const { promisify } = require("util");
                    const fs = require("fs");
                    const readFile = promisify(fs.readFile);
                    exports.load = function load(file) {
                      return readFile(file, "utf8").then((text) => JSON.parse(text));
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val graceful = File(scriptDir, "node_modules/pkg-graceful-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fs = require("fs");
                    exports.existsReadable = function existsReadable(file, callback) {
                      fs.access(file, fs.constants.R_OK, (error) => {
                        callback(null, !error);
                      });
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(compose, configReader, jsonLoader, graceful),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertOutputOrder(result.stdout, "npm.promisify.scheduled=true", "npm.promisify.ok=true")
            assertTrue(result.stdout.contains("npm.promisify.ok=true"))
            assertTrue(result.stdout.contains("npm.promisify.config=promisify-config"))
            assertTrue(result.stdout.contains("npm.promisify.text=inside-done"))
            assertTrue(result.stdout.contains("npm.promisify.access=true"))
            assertTrue(result.stdout.contains("npm.promisify.missingFallback=true"))
            assertTrue(result.stdout.contains("npm.promisify.missingCode=ENOENT"))
            assertTrue(result.stdout.contains("npm.promisify.fs.promises=object"))
            assertFalse(File(scriptDir, "promisify-work").exists())
        } finally {
            scriptDir.deleteRecursively()
        }
    }

