    @Test
    fun processAndGlobalCompatibilitySurfaceIsAvailable() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-process-surface-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create process surface test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const cwd = process.cwd();
                const memory = process.memoryUsage();
                const hr = process.hrtime();
                const hrDiff = process.hrtime(hr);
                const hrBigint = process.hrtime.bigint();
                const hrBigintLater = process.hrtime.bigint();
                const cpu = process.cpuUsage();
                const cpuDiff = process.cpuUsage(cpu);
                const resource = process.resourceUsage();
                const resourceKeys = [
                  "userCPUTime",
                  "systemCPUTime",
                  "maxRSS",
                  "minorPageFault",
                  "majorPageFault",
                  "fsRead",
                  "fsWrite",
                  "voluntaryContextSwitches",
                  "involuntaryContextSwitches"
                ];
                console.log("global.same=" + (global === globalThis));
                console.log("cwd.ends=" + cwd.endsWith("${scriptDir.name}"));
                console.log("uptime.type=" + typeof process.uptime);
                console.log("uptime.value=" + (process.uptime() >= 0));
                console.log("hrtime.type=" + typeof process.hrtime);
                console.log("hrtime.array=" + (Array.isArray(hr) && hr.length === 2));
                console.log("hrtime.parts=" + (Number.isInteger(hr[0]) && Number.isInteger(hr[1]) && hr[1] >= 0 && hr[1] < 1000000000));
                console.log("hrtime.diff=" + (Array.isArray(hrDiff) && hrDiff.length === 2 && Number.isInteger(hrDiff[0]) && Number.isInteger(hrDiff[1])));
                console.log("hrtime.bigint.type=" + typeof process.hrtime.bigint);
                console.log("hrtime.bigint.value=" + (hrBigint > 0n));
                console.log("hrtime.bigint.monotonic=" + (hrBigintLater >= hrBigint));
