    @Test
    fun processModernMetadataReportAndStdinAreScoped() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-process-modern-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create process modern test dir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const originalTitle = process.title;
                process.title = "autojs6-test-title";
                const flags = process.allowedNodeEnvironmentFlags;
                flags.add("--inspect");
                const report = process.report.getReport(new Error("report boom"));
                let reportWriteDisabled = false;
                try {
                  process.report.writeReport();
                } catch (error) {
                  reportWriteDisabled = String(error && error.message || error).includes("disabled");
                }
                let stdinSeen = "";
                const destination = { name: "destination" };
                process.stdin.setEncoding("utf8").pause().resume().ref().unref();
                process.stdin.on("custom", (value) => {
                  stdinSeen = value;
                });
                process.stdin.emit("custom", "seen");
                console.log("process.modern.execArgv=" + (
                  Array.isArray(process.execArgv) &&
                  process.execArgv.length === 0
                ));
                console.log("process.modern.title=" + (
                  originalTitle === "autojs6-node" &&
                  process.title === "autojs6-test-title"
                ));
                console.log("process.modern.features=" + (
                  Object.isFrozen(process.features) &&
                  process.features.inspector === false &&
                  process.features.debug === false &&
                  process.features.uv === true &&
                  process.features.require_module === false
                ));
                console.log("process.modern.flags=" + (
                  flags instanceof Set &&
                  Object.isFrozen(flags) &&
                  flags.size === 0 &&
                  flags.has("--inspect") === false &&
                  Array.from(flags).length === 0
                ));
                console.log("process.modern.stdin=" + (
                  process.stdin.fd === 0 &&
                  process.stdin.isTTY === false &&
                  process.stdin.readable === true &&
                  process.stdin.writable === false &&
                  typeof process.stdin.on === "function" &&
                  typeof process.stdin.once === "function" &&
                  typeof process.stdin.read === "function" &&
                  typeof process.stdin.setEncoding === "function" &&
                  typeof process.stdin.pause === "function" &&
                  typeof process.stdin.resume === "function" &&
                  process.stdin.read() === null &&
                  process.stdin.pipe(destination) === destination &&
                  stdinSeen === "seen" &&
                  typeof process.stdin[Symbol.asyncIterator] === "function"
                ));
                console.log("process.modern.report=" + (
                  typeof process.report === "object" &&
                  typeof process.report.getReport === "function" &&
                  reportWriteDisabled &&
                  report.header.cwd === process.cwd() &&
                  report.header.commandLine.join("|") === process.argv.join("|") &&
                  report.header.nodejsVersion === process.version &&
                  report.javascriptStack.message === "report boom" &&
                  typeof report.resourceUsage.rss === "number" &&
                  report.environmentVariables.AUTOJS6_EMBEDDED_NODE === "1" &&
                  Object.isFrozen(report) &&
                  Object.isFrozen(report.header) &&
                  Object.isFrozen(report.javascriptStack)
                ));
                process.title = originalTitle;
                """.trimIndent(),
                "<embedded-process-modern-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty() + "\n" + result.stdout, result.succeeded)
            assertTrue(result.stdout.contains("process.modern.execArgv=true"))
            assertTrue(result.stdout.contains("process.modern.title=true"))
            assertTrue(result.stdout, result.stdout.contains("process.modern.features=true"))
            assertTrue(result.stdout.contains("process.modern.flags=true"))
            assertTrue(result.stdout.contains("process.modern.stdin=true"))
            assertTrue(result.stdout.contains("process.modern.report=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun processDangerousApisRemainDisabled() {
        assumeEmbeddedScriptExecutionEnabled()

        listOf(
            "binding" to """process.binding("fs");""",
            "dlopen" to """process.dlopen({}, "native.node");""",
            "_linkedBinding" to """process._linkedBinding("fs");""",
            "exit" to """process.exit(1);""",
            "abort" to """process.abort();""",
            "kill" to """process.kill(process.pid, 0);""",
            "umask" to """process.umask(0);""",
            "report.writeReport" to """process.report.writeReport();""",
        ).forEach { (apiName, script) ->
            val result = runEmbeddedScript(
                script,
                "<embedded-process-$apiName-guard-source.js>",
            )
            assertFalse(result.succeeded)
            assertEquals("Error", result.errorName)
            assertEquals("ERR_AUTOJS6_PROCESS_API_DISABLED", result.errorCode)
            assertTrue(result.errorMessage.orEmpty().contains("process.$apiName is disabled"))
            settleEmbeddedScriptServiceProcess()
        }
    }

    @Test
    fun processAndConstantsBuiltinsExposeLimitedWrappersAndBlockShadows() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-process-constants-builtin-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create process/constants builtin test dir: $absolutePath" }
        }
        try {
            val processShadow = File(scriptDir, "node_modules/process/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: "process" };""" + "\n", StandardCharsets.UTF_8)
            }
            val constantsShadow = File(scriptDir, "node_modules/constants/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: "constants" };""" + "\n", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const { createRequire } = require("module");
                const processBuiltin = require("process");
                const nodeProcessBuiltin = require("node:process");
                const constantsBuiltin = require("constants");
                const nodeConstantsBuiltin = require("node:constants");
                const osBuiltin = require("os");
                const req = createRequire(__filename);

                function disabled(action) {
                  try {
                    action();
                    return false;
                  } catch (error) {
                    return /disabled/.test(String(error && error.message || error));
                  }
                }

                processBuiltin.env.PROCESS_BUILTIN_TEST = "ok";
                processBuiltin.argv.push("--process-builtin");

                const shadowLoaded = Object.keys(require.cache).some(filename => {
                  const normalized = filename.replace(/\\/g, "/");
                  return normalized.includes("/node_modules/process/") ||
                    normalized.includes("/node_modules/constants/");
                });
                const processSurface =
                  typeof processBuiltin.version === "string" &&
                  typeof processBuiltin.versions === "object" &&
                  typeof processBuiltin.release === "object" &&
                  typeof processBuiltin.platform === "string" &&
                  typeof processBuiltin.arch === "string" &&
                  Array.isArray(processBuiltin.argv) &&
                  Array.isArray(processBuiltin.execArgv) &&
                  typeof processBuiltin.argv0 === "string" &&
                  typeof processBuiltin.title === "string" &&
                  typeof processBuiltin.execPath === "string" &&
                  processBuiltin.stdin && typeof processBuiltin.stdin.read === "function" &&
                  processBuiltin.stdin.isTTY === false &&
                  processBuiltin.allowedNodeEnvironmentFlags instanceof Set &&
                  typeof processBuiltin.features === "object" &&
                  typeof processBuiltin.report.getReport === "function" &&
                  typeof processBuiltin.cwd === "function" &&
                  typeof processBuiltin.chdir === "function" &&
                  typeof processBuiltin.nextTick === "function" &&
                  typeof processBuiltin.uptime === "function" &&
                  typeof processBuiltin.hrtime === "function" &&
                  typeof processBuiltin.hrtime.bigint === "function" &&
                  typeof processBuiltin.memoryUsage === "function" &&
                  typeof processBuiltin.cpuUsage === "function" &&
                  typeof processBuiltin.resourceUsage === "function" &&
                  typeof processBuiltin.umask === "function" &&
                  typeof processBuiltin.pid === "number" &&
                  typeof processBuiltin.ppid === "number" &&
                  processBuiltin.stdout && typeof processBuiltin.stdout.write === "function" &&
                  processBuiltin.stderr && typeof processBuiltin.stderr.write === "function" &&
                  typeof processBuiltin.emitWarning === "function" &&
                  typeof processBuiltin.on === "function" &&
                  typeof processBuiltin.once === "function" &&
                  typeof processBuiltin.removeListener === "function";
                const processState =
                  processBuiltin === process &&
                  nodeProcessBuiltin === processBuiltin &&
                  processBuiltin.env === process.env &&
                  processBuiltin.env.PROCESS_BUILTIN_TEST === "ok" &&
                  process.argv.includes("--process-builtin") &&
                  processBuiltin.argv === process.argv &&
                  processBuiltin.cwd() === process.cwd();
                const processDangerous =
                  disabled(() => processBuiltin.getBuiltinModule("fs")) &&
                  disabled(() => processBuiltin.binding("fs")) &&
                  disabled(() => processBuiltin.dlopen({}, "native.node")) &&
                  disabled(() => processBuiltin._linkedBinding("fs")) &&
                  disabled(() => processBuiltin.exit(1)) &&
                  disabled(() => processBuiltin.abort()) &&
                  disabled(() => processBuiltin.kill(process.pid, 0)) &&
                  typeof processBuiltin.umask() === "number" &&
                  disabled(() => processBuiltin.umask(0));
                const constantsFs =
                  constantsBuiltin.fs.F_OK === fs.constants.F_OK &&
                  constantsBuiltin.fs.R_OK === fs.constants.R_OK &&
                  constantsBuiltin.fs.W_OK === fs.constants.W_OK &&
                  constantsBuiltin.fs.X_OK === fs.constants.X_OK &&
                  constantsBuiltin.F_OK === fs.constants.F_OK &&
                  constantsBuiltin.R_OK === fs.constants.R_OK &&
                  constantsBuiltin.W_OK === fs.constants.W_OK &&
                  constantsBuiltin.X_OK === fs.constants.X_OK;
                const constantsGroups =
                  typeof constantsBuiltin.os === "object" &&
                  typeof constantsBuiltin.errno === "object" &&
                  typeof constantsBuiltin.signals === "object" &&
                  typeof constantsBuiltin.crypto === "object" &&
                  Object.isFrozen(constantsBuiltin.fs) &&
                  Object.isFrozen(constantsBuiltin.os) &&
                  Object.isFrozen(constantsBuiltin.errno) &&
                  Object.isFrozen(constantsBuiltin.signals);
                const constantsOs =
                  constantsBuiltin.os === osBuiltin.constants &&
                  constantsBuiltin.errno === osBuiltin.constants.errno &&
                  constantsBuiltin.signals === osBuiltin.constants.signals &&
                  Object.isFrozen(osBuiltin.constants.dlopen) &&
                  Object.isFrozen(osBuiltin.constants.priority) &&
                  constantsBuiltin.SIGINT === osBuiltin.constants.signals.SIGINT &&
                  constantsBuiltin.SIGTERM === osBuiltin.constants.signals.SIGTERM &&
                  constantsBuiltin.EACCES === osBuiltin.constants.errno.EACCES &&
                  constantsBuiltin.ENOENT === osBuiltin.constants.errno.ENOENT &&
                  constantsBuiltin.RTLD_NOW === osBuiltin.constants.dlopen.RTLD_NOW &&
                  constantsBuiltin.PRIORITY_NORMAL === osBuiltin.constants.priority.PRIORITY_NORMAL;

                console.log("process.builtin.alias=" + (processBuiltin === nodeProcessBuiltin));
                console.log("process.builtin.global=" + processState);
                console.log("process.builtin.surface=" + processSurface);
                console.log("process.builtin.dangerous=" + processDangerous);
                console.log("process.builtin.resolve=" + (
                  require.resolve("process") === "process" &&
                  require.resolve("node:process") === "process" &&
                  req.resolve("process") === "process"
                ));
                console.log("process.builtin.shadow=" + (processBuiltin.shadow === undefined && !shadowLoaded));
                console.log("process.builtin.createRequire=" + (req("process") === processBuiltin));
                console.log("constants.builtin.alias=" + (constantsBuiltin === nodeConstantsBuiltin));
                console.log("constants.builtin.frozen=" + Object.isFrozen(constantsBuiltin));
                console.log("constants.builtin.fs=" + constantsFs);
                console.log("constants.builtin.groups=" + constantsGroups);
                console.log("constants.builtin.os=" + constantsOs);
                console.log("constants.builtin.resolve=" + (
                  require.resolve("constants") === "constants" &&
                  require.resolve("node:constants") === "constants" &&
                  req.resolve("constants") === "constants"
                ));
                console.log("constants.builtin.shadow=" + (constantsBuiltin.shadow === undefined && !shadowLoaded));
                console.log("constants.builtin.createRequire=" + (req("constants") === constantsBuiltin));
                """.trimIndent(),
                "<embedded-process-constants-builtin-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(processShadow, constantsShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("process.builtin.alias=true"))
            assertTrue(result.stdout.contains("process.builtin.global=true"))
            assertTrue(result.stdout.contains("process.builtin.surface=true"))
            assertTrue(result.stdout.contains("process.builtin.dangerous=true"))
            assertTrue(result.stdout.contains("process.builtin.resolve=true"))
            assertTrue(result.stdout.contains("process.builtin.shadow=true"))
            assertTrue(result.stdout.contains("process.builtin.createRequire=true"))
            assertTrue(result.stdout.contains("constants.builtin.alias=true"))
            assertTrue(result.stdout.contains("constants.builtin.frozen=true"))
            assertTrue(result.stdout.contains("constants.builtin.fs=true"))
            assertTrue(result.stdout.contains("constants.builtin.groups=true"))
            assertTrue(result.stdout.contains("constants.builtin.os=true"))
            assertTrue(result.stdout.contains("constants.builtin.resolve=true"))
            assertTrue(result.stdout.contains("constants.builtin.shadow=true"))
            assertTrue(result.stdout.contains("constants.builtin.createRequire=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun processBuiltinStateIsExecutionScopedAndCwdAware() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-process-builtin-state-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create process builtin state test dir: $absolutePath" }
        }
        val subDir = File(scriptDir, "sub").apply {
            check(mkdirs()) { "Failed to create process builtin state subdir: $absolutePath" }
        }
        try {
            val first = runEmbeddedScript(
                """
                "nodejs";
                const processBuiltin = require("process");
                processBuiltin.env.PROCESS_BUILTIN_LEAK = "bad";
                processBuiltin.argv.push("--process-builtin-leak");
                processBuiltin.chdir("./sub");
                console.log("process.builtin.cwd.current=" + (
                  processBuiltin.cwd() === process.cwd() &&
                  process.cwd().endsWith("/${scriptDir.name}/sub")
                ));
                console.log("process.builtin.env.current=" + (
                  process.env.PROCESS_BUILTIN_LEAK === "bad" &&
                  processBuiltin.env === process.env
                ));
                console.log("process.builtin.argv.current=" + (
                  process.argv.includes("--process-builtin-leak") &&
                  processBuiltin.argv === process.argv
                ));
                """.trimIndent(),
                "<embedded-process-builtin-state-first.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(first.errorMessage.orEmpty(), first.succeeded)
            assertTrue(first.stdout.contains("process.builtin.cwd.current=true"))
            assertTrue(first.stdout.contains("process.builtin.env.current=true"))
            assertTrue(first.stdout.contains("process.builtin.argv.current=true"))
            assertEquals(subDir.canonicalPath, first.nativeValues["embedded_script.current_working_directory"])

            settleEmbeddedScriptServiceProcess()

            val second = runEmbeddedScript(
                """
                "nodejs";
                const processBuiltin = require("process");
                console.log("process.builtin.env.leak=" + (processBuiltin.env.PROCESS_BUILTIN_LEAK === undefined));
                console.log("process.builtin.argv.leak=" + !processBuiltin.argv.includes("--process-builtin-leak"));
                console.log("process.builtin.cwd.initial=" + processBuiltin.cwd().endsWith("/${scriptDir.name}"));
                """.trimIndent(),
                "<embedded-process-builtin-state-second.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(second.errorMessage.orEmpty(), second.succeeded)
            assertTrue(second.stdout.contains("process.builtin.env.leak=true"))
            assertTrue(second.stdout.contains("process.builtin.argv.leak=true"))
            assertTrue(second.stdout.contains("process.builtin.cwd.initial=true"))
            assertEquals(scriptDir.canonicalPath, second.nativeValues["embedded_script.current_working_directory"])
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun processChdirUpdatesCwdAndScopedFsApisWithinSandbox() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-process-chdir-fs-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create process chdir fs test dir: $absolutePath" }
        }
        val subDir = File(scriptDir, "sub").apply {
            check(mkdirs()) { "Failed to create process chdir fs subdir: $absolutePath" }
        }
        try {
            val result = runEmbeddedScript(
                """
                "nodejs";
                const fs = require("fs");
                const fsp = require("fs/promises");

                async function main() {
                  const start = process.cwd();
                  process.chdir("./sub");
                  fs.writeFileSync("./sync.txt", "sync", "utf8");
                  await fsp.writeFile("./promise.txt", "promise", "utf8");
                  const promiseText = await fsp.readFile("./promise.txt", "utf8");
                  const callbackText = await new Promise((resolve, reject) => {
                    fs.readFile("./sync.txt", "utf8", (error, text) => {
                      if (error) reject(error);
                      else resolve(text);
                    });
                  });
                  console.log("chdir.cwd.initial=" + start.endsWith("/${scriptDir.name}"));
                  console.log("chdir.cwd.sub=" + process.cwd().endsWith("/${scriptDir.name}/sub"));
                  console.log("chdir.fs.sync=" + fs.readFileSync("./sync.txt", "utf8"));
                  console.log("chdir.fs.promise=" + promiseText);
                  console.log("chdir.fs.callback=" + callbackText);
                }

                return main();
                """.trimIndent(),
                "<embedded-process-chdir-fs-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("chdir.cwd.initial=true"))
            assertTrue(result.stdout.contains("chdir.cwd.sub=true"))
            assertTrue(result.stdout.contains("chdir.fs.sync=sync"))
            assertTrue(result.stdout.contains("chdir.fs.promise=promise"))
            assertTrue(result.stdout.contains("chdir.fs.callback=sync"))
            assertEquals(scriptDir.canonicalPath, result.nativeValues["embedded_script.sandbox_root"])
            assertEquals(subDir.canonicalPath, result.nativeValues["embedded_script.current_working_directory"])
            assertEquals("sync", File(subDir, "sync.txt").readText(StandardCharsets.UTF_8))
            assertEquals("promise", File(subDir, "promise.txt").readText(StandardCharsets.UTF_8))

            settleEmbeddedScriptServiceProcess()

            val second = runEmbeddedScript(
                """
                "nodejs";
                console.log("chdir.cwd.leak=" + process.cwd().endsWith("/${scriptDir.name}"));
                """.trimIndent(),
                "<embedded-process-chdir-leak-source.js>",
                workingDirectory = scriptDir.canonicalPath,
            )
            assertTrue(second.errorMessage.orEmpty(), second.succeeded)
            assertTrue(second.stdout.contains("chdir.cwd.leak=true"))
            assertEquals(scriptDir.canonicalPath, second.nativeValues["embedded_script.current_working_directory"])
        } finally {
            scriptDir.deleteRecursively()
        }
    }

