                """
                globalThis.__autojs6ChdirRootHelperLoads = (globalThis.__autojs6ChdirRootHelperLoads || 0) + 1;
                const nestedName = "./nested";
                exports.where = "root";
                exports.nested = require(nestedName).value;
                """.trimIndent() + "\n",
