            )
            File(scriptDir, "nested.js").writeText("""exports.value = "root-nested";""" + "\n", StandardCharsets.UTF_8)
            File(scriptDir, "sub/helper.js").writeText("""exports.where = "sub";""" + "\n", StandardCharsets.UTF_8)
            File(scriptDir, "node_modules/pkg").mkdirs()
            File(scriptDir, "node_modules/pkg/package.json").writeText("""{"name":"pkg","main":"index.js"}""")
            File(scriptDir, "node_modules/pkg/index.js").writeText("""exports.where = "root-pkg";""" + "\n")
            File(scriptDir, "sub/node_modules/pkg").mkdirs()
            File(scriptDir, "sub/node_modules/pkg/package.json").writeText("""{"name":"pkg","main":"index.js"}""")
            File(scriptDir, "sub/node_modules/pkg/index.js").writeText("""exports.where = "sub-pkg";""" + "\n")

            val mainFile = File(scriptDir, "main.js")
            val result = runEmbeddedScript(
                """
                "nodejs";
                process.chdir("./sub");
                const helperName = "./helper";
                const helperA = require(helperName);
                const helperB = require("./" + "helper");
                const pkg = require("pkg");
                const helperResolved = require.resolve("./helper").replace(/\\/g, "/");
                const pkgResolved = require.resolve("pkg").replace(/\\/g, "/");
                console.log("chdir.require.local=" + helperA.where + "/" + helperA.nested);
                console.log("chdir.require.cache=" + (helperA === helperB && globalThis.__autojs6ChdirRootHelperLoads === 1));
                console.log("chdir.require.pkg=" + pkg.where);
                console.log("chdir.require.resolve=" + (
                  helperResolved.endsWith("/helper.js") &&
                  pkgResolved.indexOf("/sub/node_modules/pkg/") < 0
                ));
                """.trimIndent(),
                mainFile.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("chdir.require.local=root/root-nested"))
            assertTrue(result.stdout.contains("chdir.require.cache=true"))
            assertTrue(result.stdout.contains("chdir.require.pkg=root-pkg"))
            assertTrue(result.stdout.contains("chdir.require.resolve=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

