    @Test
    fun limitedModuleBuiltinExposesScopedHelpersAndBlocksShadow() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-module-builtin-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create module builtin test dir: $absolutePath" }
        }
        try {
            val moduleShadow = File(scriptDir, "node_modules/module/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { shadow: true };""" + "\n", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                """
                "nodejs";
                const moduleBuiltin = require("module");
                const nodeModuleBuiltin = require("node:module");
                const shadowLoaded = Object.keys(require.cache).some(filename => {
                  return filename.replace(/\\/g, "/").includes("/node_modules/module/");
                });
                const dangerousMissing =
                  moduleBuiltin.Module === undefined &&
                  moduleBuiltin._load === undefined &&
                  moduleBuiltin._resolveFilename === undefined &&
                  moduleBuiltin._compile === undefined &&
                  moduleBuiltin.wrap === undefined &&
                  moduleBuiltin.globalPaths === undefined;
                console.log("module.builtin.same=" + (moduleBuiltin === nodeModuleBuiltin));
                console.log("module.builtin.frozen=" + Object.isFrozen(moduleBuiltin));
                console.log("module.builtin.keys=" + Object.keys(moduleBuiltin).join(","));
                console.log("module.builtin.createRequire=" + typeof moduleBuiltin.createRequire);
                console.log("module.builtin.isBuiltin=" + [
                  moduleBuiltin.isBuiltin("fs"),
                  moduleBuiltin.isBuiltin("node:fs/promises"),
                  moduleBuiltin.isBuiltin("path/posix"),
                  moduleBuiltin.isBuiltin("node:stream/web"),
                  moduleBuiltin.isBuiltin("console"),
                  moduleBuiltin.isBuiltin("v8"),
                  moduleBuiltin.isBuiltin("async_hooks"),
                  moduleBuiltin.isBuiltin("node:diagnostics_channel"),
                  moduleBuiltin.isBuiltin("dns"),
                  moduleBuiltin.isBuiltin("node:dns/promises"),
                  moduleBuiltin.isBuiltin("net"),
                  moduleBuiltin.isBuiltin("perf_hooks"),
                  moduleBuiltin.isBuiltin("tty"),
                  moduleBuiltin.isBuiltin("node:timers/promises"),
                  moduleBuiltin.isBuiltin("http"),
                  moduleBuiltin.isBuiltin("https"),
                  moduleBuiltin.isBuiltin("tls"),
                  moduleBuiltin.isBuiltin("node:vm")
                ].join("/"));
                console.log("module.builtin.modules=" + (
                  Array.isArray(moduleBuiltin.builtinModules) &&
                  Object.isFrozen(moduleBuiltin.builtinModules) &&
                  moduleBuiltin.builtinModules.includes("fs") &&
                  moduleBuiltin.builtinModules.includes("stream/web") &&
                  moduleBuiltin.builtinModules.includes("module") &&
                  moduleBuiltin.builtinModules.includes("console") &&
                  moduleBuiltin.builtinModules.includes("v8") &&
                  moduleBuiltin.builtinModules.includes("async_hooks") &&
                  moduleBuiltin.builtinModules.includes("diagnostics_channel") &&
                  moduleBuiltin.builtinModules.includes("dns") &&
                  moduleBuiltin.builtinModules.includes("dns/promises") &&
                  moduleBuiltin.builtinModules.includes("net") &&
                  moduleBuiltin.builtinModules.includes("perf_hooks") &&
                  moduleBuiltin.builtinModules.includes("tty") &&
                  moduleBuiltin.builtinModules.includes("timers/promises") &&
                  moduleBuiltin.builtinModules.includes("http") &&
                  moduleBuiltin.builtinModules.includes("https") &&
                  moduleBuiltin.builtinModules.includes("tls") &&
                  moduleBuiltin.builtinModules.includes("vm")
                ));
                console.log("module.builtin.sync=" + (
                  typeof moduleBuiltin.syncBuiltinESMExports === "function" &&
                  moduleBuiltin.syncBuiltinESMExports() === undefined
                ));
                console.log("module.builtin.dangerous_missing=" + dangerousMissing);
                console.log("module.builtin.resolve=" + require.resolve("module") + "/" + require.resolve("node:module"));
                console.log("module.builtin.shadow=" + (moduleBuiltin.shadow !== true && nodeModuleBuiltin.shadow !== true && !shadowLoaded));
                try {
                  process.getBuiltinModule("module");
                  console.log("module.builtin.getBuiltinModule=false");
                } catch (error) {
                  console.log("module.builtin.getBuiltinModule=" + (
                    error &&
                    error.code === "ERR_AUTOJS6_EMBEDDED_NODE_BUILTIN_DISABLED" &&
                    /disabled/.test(error.message)
                  ));
                }
                """.trimIndent(),
                "<embedded-module-builtin-source.js>",
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(moduleShadow),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("module.builtin.same=true"))
            assertTrue(result.stdout.contains("module.builtin.frozen=true"))
            assertTrue(result.stdout.contains("module.builtin.keys=createRequire,isBuiltin,builtinModules,syncBuiltinESMExports"))
            assertTrue(result.stdout.contains("module.builtin.createRequire=function"))
            assertTrue(result.stdout.contains("module.builtin.isBuiltin=true/true/true/true/true/true/true/true/true/true/true/true/true/true/true/true/true/true"))
            assertTrue(result.stdout.contains("module.builtin.modules=true"))
            assertTrue(result.stdout.contains("module.builtin.sync=true"))
            assertTrue(result.stdout.contains("module.builtin.dangerous_missing=true"))
            assertTrue(result.stdout.contains("module.builtin.resolve=module/module"))
            assertTrue(result.stdout.contains("module.builtin.shadow=true"))
            assertTrue(result.stdout.contains("module.builtin.getBuiltinModule=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun moduleCreateRequireFromFilenameLoadsLocalPackageAndSharesCache() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-module-create-require-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create module createRequire test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(""""nodejs";""" + "\n", StandardCharsets.UTF_8)
            }
            File(scriptDir, "child.js").writeText(
                """
                globalThis.__autojs6CreateRequireChildLoads = (globalThis.__autojs6CreateRequireChildLoads || 0) + 1;
                exports.value = "child";
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "node_modules/pkg").mkdirs()
            File(scriptDir, "node_modules/pkg/package.json").writeText(
                """{"name":"pkg","main":"index.js"}""",
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "node_modules/pkg/index.js").writeText(
                """exports.value = "pkg";""" + "\n",
                StandardCharsets.UTF_8,
            )

            val result = runEmbeddedScript(
                """
                "nodejs";
                const { createRequire } = require("module");
                const req = createRequire(__filename);
                const childA = req("./child");
                const childB = require("./" + "child");
                const pkg = req("pkg");
                const childResolved = req.resolve("./child").replace(/\\/g, "/");
                const pkgResolved = req.resolve("pkg").replace(/\\/g, "/");
                console.log("module.createRequire.local=" + childA.value);
                console.log("module.createRequire.pkg=" + pkg.value);
                console.log("module.createRequire.resolve=" + (
                  childResolved.endsWith("/child.js") &&
                  pkgResolved.endsWith("/node_modules/pkg/index.js")
                ));
                console.log("module.createRequire.surface=" + (
                  req.cache === require.cache &&
                  req.extensions === require.extensions &&
                  req.main === require.main
                ));
                console.log("module.createRequire.cache=" + (
                  childA === childB &&
                  globalThis.__autojs6CreateRequireChildLoads === 1 &&
                  require.cache[req.resolve("./child")].exports === childA
                ));
                """.trimIndent(),
                main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("module.createRequire.local=child"))
            assertTrue(result.stdout.contains("module.createRequire.pkg=pkg"))
            assertTrue(result.stdout.contains("module.createRequire.resolve=true"))
            assertTrue(result.stdout.contains("module.createRequire.surface=true"))
            assertTrue(result.stdout.contains("module.createRequire.cache=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

