    @Test
    fun moduleCreateRequirePreservesUnsupportedTargetsBudgetsAndModuleSourcesPrecedence() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-module-create-require-budget-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create module createRequire budget test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(""""nodejs";""" + "\n", StandardCharsets.UTF_8)
            }
            val preferred = File(scriptDir, "preferred.js").apply {
                writeText("""module.exports = "disk";""" + "\n", StandardCharsets.UTF_8)
            }
            File(scriptDir, "esm.mjs").writeText("""export default 1;""" + "\n", StandardCharsets.UTF_8)
            File(scriptDir, "native.node").writeText("native", StandardCharsets.UTF_8)

            val precedence = runEmbeddedScript(
                """
                "nodejs";
                const req = require("module").createRequire(__filename);
                function check(label, action) {
                  try {
                    action();
                    console.log(label + ".unexpected=true");
                  } catch (error) {
                    console.log(label + ".code=" + error.code);
                    console.log(label + ".message=" + String(error.message).includes(label === "module.createRequire.target.esm" ? "ESM/import" : "Unsupported Embedded Node local module extension"));
                  }
                }
                console.log("module.createRequire.target.esm.default=" + req("./esm.mjs").default);
                check("module.createRequire.target.native", () => req("./native.node"));
                const target = "./preferred";
                console.log("module.createRequire.precedence=" + req(target));
                """.trimIndent(),
                main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = mapOf(preferred.canonicalPath to """module.exports = "preloaded";"""),
            )
            assertTrue(precedence.errorMessage.orEmpty(), precedence.succeeded)
            assertTrue(precedence.stdout.contains("module.createRequire.target.esm.default=1"))
            assertTrue(precedence.stdout.contains("module.createRequire.target.native.message=true"))
            assertTrue(precedence.stdout.contains("module.createRequire.precedence=preloaded"))
            assertEquals("1", precedence.nativeValues["embedded_script.dynamic_require_fallback_loaded_count"])

            settleEmbeddedScriptServiceProcess()

            File(scriptDir, "extra.js").writeText("""module.exports = true;""" + "\n", StandardCharsets.UTF_8)
            val maxCountSources = (0 until moduleSourceMaxCount).associate { index ->
                "${scriptDir.canonicalPath}/preloaded-create-require-$index.js" to "module.exports = $index;"
            }
            val tooMany = runEmbeddedScript(
                source = """
                    "nodejs";
                    const req = require("module").createRequire(__filename);
                    const target = "./extra";
                    req(target);
                """.trimIndent(),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = maxCountSources,
            )
            assertFalse(tooMany.succeeded)
            assertTrue(tooMany.errorMessage.orEmpty().contains("dynamic require fallback"))
            assertTrue(tooMany.errorMessage.orEmpty().contains("module source count is too large"))
            assertTrue(tooMany.errorMessage.orEmpty().contains("$moduleSourceOverLimitCount > $moduleSourceMaxCount"))

            settleEmbeddedScriptServiceProcess()

            File(scriptDir, "big.js").writeText("x".repeat(moduleSourceOverLimitBytes), StandardCharsets.UTF_8)
            val singleTooLarge = runEmbeddedScript(
                source = """
                    "nodejs";
                    const req = require("module").createRequire(__filename);
                    const target = "./big";
                    req(target);
                """.trimIndent(),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )
            assertFalse(singleTooLarge.succeeded)
            assertTrue(singleTooLarge.errorMessage.orEmpty().contains("dynamic require fallback module source is too large"))
            assertTrue(
                singleTooLarge.errorMessage.orEmpty()
                    .contains("$moduleSourceOverLimitBytes bytes > $moduleSourceMaxBytes bytes"),
            )
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun nodeProjectRunnerRunsEntryWithArgvEnvCwdShebangAndEscaping() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-node-project-runner-simple-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create Node project runner test dir: $absolutePath" }
        }
        try {
            val binDir = File(projectRoot, "bin").apply { check(mkdirs()) }
            val workspace = File(projectRoot, "workspace").apply { check(mkdirs()) }
            val quotedArg = "line\nquote\"slash\\done"
            val envValue = "env\nquote\"slash\\done"
            val entry = File(binDir, "cli.js").apply {
                writeText(
                    """
                    #!/usr/bin/env node
                    "nodejs";
                    const fs = require("fs");
                    const argvJson = JSON.stringify(process.argv.slice(2));
                    const envJson = JSON.stringify(process.env.RUNNER_VALUE);
                    const argvOk = process.argv.length === 5 &&
                      process.argv[2] === "--name" &&
                      process.argv[3] === "AutoJs6" &&
                      process.argv[4] === ${jsStringLiteral(quotedArg)};
                    const envOk = process.env.RUNNER_VALUE === ${jsStringLiteral(envValue)};
                    const cwdOk = process.cwd().replace(/\\/g, "/").endsWith("/workspace");
                    const argv0Ok = process.argv[0] === "autojs6-node";
                    const normalizeDataPath = (value) => String(value).replace(/^\/data\/user\/0\//, "/data/data/");
                    const argv1Ok = normalizeDataPath(process.argv[1]) === normalizeDataPath(__filename);
                    const requireMainOk = require.main === module;
                    const parentOk = module.parent === null;
                    const sourceOk = argv0Ok && argv1Ok && requireMainOk && parentOk;
                    fs.writeFileSync("./runner-output.txt", "ok", "utf8");
                    const envEmpty = process.env.RUNNER_EMPTY === "";
                    const outputExists = fs.existsSync("./runner-output.txt");
                    const ready = envOk &&
                      envEmpty &&
                      cwdOk &&
                      sourceOk &&
                      outputExists;
                    fs.writeFileSync("./runner-status.json", JSON.stringify({
                      argvJson,
                      envJson,
                      argvOk,
                      envOk,
                      envEmpty,
                      cwdOk,
                      argv0Ok,
                      argv1Ok,
                      requireMainOk,
                      parentOk,
                      outputExists,
                      ready
                    }), "utf8");
                    console.log("runner.simple.argv_json=" + argvJson);
                    console.log("runner.simple.env_json=" + envJson);
                    console.log("runner.simple.argv_ok=" + argvOk);
                    console.log("runner.simple.env_ok=" + envOk);
                    console.log("runner.simple.env_empty=" + envEmpty);
                    console.log("runner.simple.cwd=" + cwdOk);
                    console.log("runner.simple.argv0=" + argv0Ok);
                    console.log("runner.simple.argv1=" + argv1Ok);
                    console.log("runner.simple.require_main=" + requireMainOk);
                    console.log("runner.simple.parent=" + parentOk);
                    console.log("runner.simple.output_exists=" + outputExists);
                    console.log("runner.simple.ready=" + ready);
                    """.trimIndent() + "\n",
                    StandardCharsets.UTF_8,
                )
            }

            val request = NodeProjectRunRequest(
                projectRoot = projectRoot,
                entryFile = entry,
                workingDirectory = workspace,
                argv = listOf("--name", "AutoJs6", "--quoted", quotedArg),
                env = mapOf(
                    "RUNNER_VALUE" to envValue,
                    "RUNNER_EMPTY" to "",
                ),
            )
            val result = runNodeProject(request)

            val diagnostic = describeNodeProjectRun(request, result)
            assertTrue(diagnostic, result.succeeded)
            val status = JSONObject(File(workspace, "runner-status.json").readText(StandardCharsets.UTF_8))
            val argv = JSONArray(status.getString("argvJson"))
            assertEquals(diagnostic, 4, argv.length())
            assertEquals(diagnostic, "--name", argv.getString(0))
            assertEquals(diagnostic, "AutoJs6", argv.getString(1))
            assertEquals(diagnostic, "--quoted", argv.getString(2))
            assertEquals(diagnostic, quotedArg, argv.getString(3))
            assertTrue(diagnostic, status.getBoolean("envOk"))
            assertTrue(diagnostic, status.getBoolean("envEmpty"))
            assertTrue(diagnostic, status.getBoolean("cwdOk"))
            assertTrue(diagnostic, status.getBoolean("argv0Ok"))
            assertTrue(diagnostic, status.getBoolean("argv1Ok"))
            assertTrue(diagnostic, status.getBoolean("requireMainOk"))
            assertTrue(diagnostic, status.getBoolean("parentOk"))
            assertTrue(diagnostic, status.getBoolean("outputExists"))
            assertTrue(diagnostic, status.getBoolean("ready"))
            assertEquals("ok", File(workspace, "runner-output.txt").readText(StandardCharsets.UTF_8))
        } finally {
            projectRoot.deleteRecursively()
        }
    }

