    @Test
    fun projectRunnerDescribeIncludesSourceBudgetsAndFailureContext() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-runner-describe-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create runner describe dir: $absolutePath" }
        }
        try {
            val entry = File(projectRoot, "entry.js").apply {
                writeText(
                    """
                    "nodejs";
                    require("./helper");
                    throw new Error("describe failure");
                    """.trimIndent() + "\n",
                    StandardCharsets.UTF_8,
                )
            }
            val helper = File(projectRoot, "helper.js").apply {
                writeText("""exports.value = "helper";""" + "\n", StandardCharsets.UTF_8)
            }
            val request = NativeNodeEmbeddedProjectRunner.Request(
                projectRoot = projectRoot,
                entryFile = entry,
                argv = listOf("--describe"),
                env = mapOf("DESCRIBE_KEY" to "describe-value"),
                moduleSources = moduleSourcesFor(helper),
                entrySource = entry.readText(StandardCharsets.UTF_8),
            )
            val result = NativeNodeEmbeddedProjectRunner.run(context, request)
            val diagnostic = NativeNodeEmbeddedProjectRunner.describe(request, result)

            assertFalse(result.succeeded)
            val nativeValues = result.nativeValues
            assertEquals("entry", nativeValues["embedded_project_runner.kind"])
            assertEquals(projectRoot.canonicalPath, nativeValues["embedded_project_runner.project_root"])
            assertEquals(entry.canonicalPath, nativeValues["embedded_project_runner.entry_file"])
            assertEquals("[--describe]", nativeValues["embedded_project_runner.argv"])
            assertEquals("[DESCRIBE_KEY]", nativeValues["embedded_project_runner.env_keys"])
            assertEquals("1", nativeValues["embedded_project_runner.module_source_count"])
            assertEquals("0", nativeValues["embedded_project_runner.runtime_module_source_count"])
            assertTrue(nativeValues["embedded_project_runner.entry_source_bytes"].orEmpty().toInt() > 0)
            assertFalse(nativeValues.values.any { value -> value.contains("describe-value") })
            assertTrue(diagnostic, diagnostic.contains("kind=entry"))
            assertTrue(diagnostic, diagnostic.contains("projectRoot=${projectRoot.absolutePath}"))
            assertTrue(diagnostic, diagnostic.contains("entryFile=${entry.absolutePath}"))
            assertTrue(diagnostic, diagnostic.contains("argv=[--describe]"))
            assertTrue(diagnostic, diagnostic.contains("envKeys=[DESCRIBE_KEY]"))
            assertFalse(diagnostic, diagnostic.contains("describe-value"))
            assertTrue(diagnostic, diagnostic.contains("moduleSourceCount=1"))
            assertTrue(diagnostic, diagnostic.contains("runtimeModuleSourceCount=0"))
            assertTrue(diagnostic, diagnostic.contains("entrySourceBytes="))
            assertTrue(diagnostic, diagnostic.contains("describe failure"))
        } finally {
            projectRoot.deleteRecursively()
        }
    }

