    @Test
    fun nodeProjectRunnerProjectRequestRejectsEntrySourceForPackageScriptAndBin() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-node-project-entry-source-conflict-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create project entrySource conflict dir: $absolutePath" }
        }
        try {
            File(projectRoot, "project.json").writeText("""{"type":"node","main":"main.js"}""", StandardCharsets.UTF_8)
            File(projectRoot, "package.json").writeText(
                JSONObject()
                    .put("name", "project-entry-source-conflict-root")
                    .put("version", "1.0.0")
                    .put("scripts", JSONObject().put("build", "node ./scripts/build.js"))
                    .put("bin", JSONObject().put("entry-source-bin", "./bin/cli.js"))
                    .toString(),
                StandardCharsets.UTF_8,
            )
            File(projectRoot, "scripts/build.js").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText(""""nodejs"; console.log("entrySource package script should not run");""" + "\n", StandardCharsets.UTF_8)
            }
            File(projectRoot, "bin/cli.js").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText(""""nodejs"; console.log("entrySource package bin should not run");""" + "\n", StandardCharsets.UTF_8)
            }

            fun assertEntrySourceRejected(request: NativeNodeEmbeddedProjectRunner.ProjectRequest, expectedLaunchKind: String) {
                val failure = runCatching {
                    NativeNodeEmbeddedProjectRunner.runProject(context, request)
                }.exceptionOrNull()

                assertTrue(failure is IllegalArgumentException)
                val message = failure?.message.orEmpty()
                assertTrue(message, message.contains(NodeProjectLaunchDiagnostics.RUNNER_REQUEST_FAILURE_MARKER))
                assertTrue(message, message.contains("Node project entrySource is only supported for project entry launch"))
                assertTrue(message, message.contains("Node project runner request:"))
                assertTrue(message, message.contains("kind=project"))
                assertTrue(message, message.contains("launchKind=$expectedLaunchKind"))
                assertTrue(
                    message,
                    message.contains("entrySourceBytes=${request.entrySource.orEmpty().toByteArray(StandardCharsets.UTF_8).size}"),
                )
                assertTrue(message, message.contains("envKeys=[SECRET_SHOULD_NOT_PRINT_VALUE]"))
                assertFalse(message, message.contains("secret-value"))
                assertFalse(message, message.contains("console.log('override should not run')"))
            }

            val commonEntrySource = "console.log('override should not run');"
            assertEntrySourceRejected(
                NativeNodeEmbeddedProjectRunner.ProjectRequest(
                    projectRoot = projectRoot,
                    scriptName = "build",
                    argv = listOf("--script-conflict"),
                    env = mapOf("SECRET_SHOULD_NOT_PRINT_VALUE" to "secret-value"),
                    entrySource = commonEntrySource,
                ),
                "package-script",
            )
            assertEntrySourceRejected(
                NativeNodeEmbeddedProjectRunner.ProjectRequest(
                    projectRoot = projectRoot,
                    binName = "entry-source-bin",
                    argv = listOf("--bin-conflict"),
                    env = mapOf("SECRET_SHOULD_NOT_PRINT_VALUE" to "secret-value"),
                    entrySource = commonEntrySource,
                ),
                "package-bin",
            )
        } finally {
            projectRoot.deleteRecursively()
        }
    }

    @Test
    fun nodeProjectRunnerProjectRequestRejectsPackageLaunchPathEscapesWithDescriptor() {
        assumeEmbeddedScriptExecutionEnabled()

        val root = File(context.cacheDir, "embedded-node-project-request-boundary-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create project request boundary root: $absolutePath" }
        }
        val projectRoot = File(root, "project").apply {
            check(mkdirs()) { "Failed to create project request boundary project dir: $absolutePath" }
        }
        val packageDir = File(projectRoot, "packages/boundary-tool").apply {
            check(mkdirs()) { "Failed to create project request boundary package dir: $absolutePath" }
        }
        val outsidePackageDir = File(root, "outside-package").apply {
            check(mkdirs()) { "Failed to create project request outside package dir: $absolutePath" }
        }
        val outsideWorkspace = File(root, "outside-workspace").apply {
            check(mkdirs()) { "Failed to create project request outside workspace dir: $absolutePath" }
        }
        try {
            File(projectRoot, "project.json").writeText("""{"type":"node","main":"main.js"}""", StandardCharsets.UTF_8)
            listOf(packageDir, outsidePackageDir).forEach { dir ->
                File(dir, "package.json").writeText(
                    JSONObject()
                        .put("name", "project-request-boundary-tool")
                        .put("version", "1.0.0")
                        .put("scripts", JSONObject().put("build", "node ./scripts/build.js"))
                        .put("bin", JSONObject().put("boundary-bin", "./bin/cli.js"))
                        .toString(),
                    StandardCharsets.UTF_8,
                )
                File(dir, "scripts/build.js").apply {
                    parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                    writeText(""""nodejs"; console.log("project request boundary script should not run");""" + "\n", StandardCharsets.UTF_8)
                }
                File(dir, "bin/cli.js").apply {
                    parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                    writeText(""""nodejs"; console.log("project request boundary bin should not run");""" + "\n", StandardCharsets.UTF_8)
                }
            }

            fun assertBoundaryRejection(
                request: NativeNodeEmbeddedProjectRunner.ProjectRequest,
                expectedLaunchKind: String,
                expectedToken: String,
            ) {
                val failure = runCatching {
                    NativeNodeEmbeddedProjectRunner.runProject(context, request)
                }.exceptionOrNull()
                assertTrue(failure is IllegalArgumentException)
                val message = failure?.message.orEmpty()
                assertTrue(message, message.contains(NodeProjectLaunchDiagnostics.RUNNER_REQUEST_FAILURE_MARKER))
                assertTrue(message, message.contains(expectedToken))
                assertTrue(message, message.contains("Node project runner request:"))
                assertTrue(message, message.contains("kind=project"))
                assertTrue(message, message.contains("launchKind=$expectedLaunchKind"))
                assertTrue(message, message.contains("envKeys=[PROJECT_BOUNDARY_SECRET]"))
                assertFalse(message, message.contains("project-boundary-secret-value"))
                assertFalse(message, message.contains("project request boundary script should not run"))
                assertFalse(message, message.contains("project request boundary bin should not run"))
            }

            assertBoundaryRejection(
                NativeNodeEmbeddedProjectRunner.ProjectRequest(
                    projectRoot = projectRoot,
                    packageDir = outsidePackageDir,
                    scriptName = "build",
                    env = mapOf("PROJECT_BOUNDARY_SECRET" to "project-boundary-secret-value"),
                ),
                "package-script",
                "Node package script packageDir escapes Node project root",
            )
            assertBoundaryRejection(
                NativeNodeEmbeddedProjectRunner.ProjectRequest(
                    projectRoot = projectRoot,
                    packageDir = packageDir,
                    scriptName = "build",
                    workingDirectory = outsideWorkspace,
                    env = mapOf("PROJECT_BOUNDARY_SECRET" to "project-boundary-secret-value"),
                ),
                "package-script",
                "Node package script workingDirectory escapes Node project root",
            )
            assertBoundaryRejection(
                NativeNodeEmbeddedProjectRunner.ProjectRequest(
                    projectRoot = projectRoot,
                    packageDir = outsidePackageDir,
                    binName = "boundary-bin",
                    env = mapOf("PROJECT_BOUNDARY_SECRET" to "project-boundary-secret-value"),
                ),
                "package-bin",
                "Node package bin packageDir escapes Node project root",
            )
            assertBoundaryRejection(
                NativeNodeEmbeddedProjectRunner.ProjectRequest(
                    projectRoot = projectRoot,
                    packageDir = packageDir,
                    binName = "boundary-bin",
                    workingDirectory = outsideWorkspace,
                    env = mapOf("PROJECT_BOUNDARY_SECRET" to "project-boundary-secret-value"),
                ),
                "package-bin",
                "Node package bin workingDirectory escapes Node project root",
            )
        } finally {
            root.deleteRecursively()
        }
    }

