    @Test
    fun nodeProjectRunnerRejectsUnsafeProjectMainTargets() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-node-project-main-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create project main deny runner dir: $absolutePath" }
        }
        try {
            fun assertInvalidMain(target: String, token: String) {
                File(projectRoot, "project.json").writeText(
                    JSONObject()
                        .put("type", "node")
                        .put("main", target)
                        .toString(),
                    StandardCharsets.UTF_8,
                )
                val request = NativeNodeEmbeddedProjectRunner.ProjectRequest(
                    projectRoot = projectRoot,
                    argv = listOf("--deny"),
                    env = mapOf("SECRET_SHOULD_NOT_PRINT_VALUE" to "secret-value"),
                )
                val failure = runCatching {
                    NativeNodeEmbeddedProjectRunner.runProject(context, request)
                }.exceptionOrNull()

                assertTrue(failure is IllegalArgumentException)
                val message = failure?.message.orEmpty()
                assertTrue(message, message.contains(token))
                assertTrue(message, message.contains("Node project runner request:"))
                assertTrue(message, message.contains("kind=project"))
                assertTrue(message, message.contains("projectRoot=${projectRoot.absolutePath}"))
                assertTrue(message, message.contains("argv=[--deny]"))
                assertTrue(message, message.contains("envKeys=[SECRET_SHOULD_NOT_PRINT_VALUE]"))
                assertFalse(message, message.contains("secret-value"))
            }

            assertInvalidMain("../outside.js", "escapes project sandbox")
            assertInvalidMain("/absolute.js", "must be relative")
            assertInvalidMain("file:entry.js", "must be relative")
            assertInvalidMain("", "Node project entry target is empty")
            assertInvalidMain("entry.node", "native addon")
            assertInvalidMain("entry.txt", "Unsupported Node project entry extension")
            assertInvalidMain("missing.js", "Node project entry missing")

            File(projectRoot, "project.json").writeText("""{"type":"rhino","main":"main.js"}""", StandardCharsets.UTF_8)
            val typeFailure = runCatching {
                NativeNodeEmbeddedProjectRunner.runProject(
                    context,
                    NativeNodeEmbeddedProjectRunner.ProjectRequest(projectRoot = projectRoot),
                )
            }.exceptionOrNull()
            assertTrue(typeFailure is IllegalArgumentException)
            assertTrue(typeFailure?.message.orEmpty().contains("type must be node"))
        } finally {
            projectRoot.deleteRecursively()
        }
    }

