    @Test
    fun proStyleNodeEntryDirectivesParseToStableMetadata() {
        val nodeUi = JavaScriptSource.parseExecutionMode(""""nodejs ui"; console.log("ui");""").mode
        assertTrue((nodeUi and JavaScriptSource.EXECUTION_MODE_NODEJS) != 0)
        assertTrue((nodeUi and JavaScriptSource.EXECUTION_MODE_UI) != 0)
        assertFalse((nodeUi and JavaScriptSource.EXECUTION_MODE_UI_THREAD) != 0)
        assertEquals(NodeEntryDirective.DIRECTIVE_NODEJS_UI, NodeEntryDirective.fromExecutionMode(nodeUi))
        assertTrue(NodeEntryDirective.requiresUiActivity(NodeEntryDirective.fromExecutionMode(nodeUi)))
        assertFalse(NodeEntryDirective.requiresUiThread(NodeEntryDirective.fromExecutionMode(nodeUi)))

        val nodeUiThread = JavaScriptSource.parseExecutionMode(""""nodejs ui-thread"; console.log("ui-thread");""").mode
        assertTrue((nodeUiThread and JavaScriptSource.EXECUTION_MODE_NODEJS) != 0)
        assertFalse((nodeUiThread and JavaScriptSource.EXECUTION_MODE_UI) != 0)
        assertTrue((nodeUiThread and JavaScriptSource.EXECUTION_MODE_UI_THREAD) != 0)
        assertEquals(NodeEntryDirective.DIRECTIVE_NODEJS_UI_THREAD, NodeEntryDirective.fromExecutionMode(nodeUiThread))
        assertFalse(NodeEntryDirective.requiresUiActivity(NodeEntryDirective.fromExecutionMode(nodeUiThread)))
        assertTrue(NodeEntryDirective.requiresUiThread(NodeEntryDirective.fromExecutionMode(nodeUiThread)))

        assertEquals(NodeEntryDirective.DIRECTIVE_NODEJS_UI_THREAD, NodeEntryDirective.normalize("ui_thread"))
        assertEquals(
            NodeEntryDirective.DIRECTIVE_NODEJS_UI_AND_UI_THREAD,
            NodeEntryDirective.normalize("node ui | ui-thread"),
        )
        val invalid = runCatching { NodeEntryDirective.normalize("nodejs native") }.exceptionOrNull()
        assertTrue(invalid is IllegalArgumentException)
    }

    @Test
    fun nodeProjectLaunchDescriptorParsesAndValidatesInternalOptions() {
        val projectRoot = File(context.cacheDir, "embedded-node-project-launch-descriptor-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create node project launch descriptor dir: $absolutePath" }
        }
        try {
            val packageDir = File(projectRoot, "packages/tool").apply {
                check(mkdirs()) { "Failed to create node project launch descriptor package dir: $absolutePath" }
            }
            val workspace = File(projectRoot, "workspace").apply {
                check(mkdirs()) { "Failed to create node project launch descriptor workspace dir: $absolutePath" }
            }
            val descriptor = NodeProjectLaunchDescriptor.descriptorFile(projectRoot)

            assertEquals(NodeProjectLaunchKind.PROJECT_ENTRY, NodeProjectLaunchDescriptor.readOptionsOrDefault(projectRoot).launchKind)

            File(projectRoot, NodeProjectLaunchDescriptor.INTERNAL_DESCRIPTOR_FILE_NAME).writeText(
                JSONObject()
                    .put("launchKind", "project-entry")
                    .put("timeoutMs", 4321)
                    .put("executionMode", "interactive_long_running")
                    .toString(),
                StandardCharsets.UTF_8,
            )
            val internalOptions = NodeProjectLaunchDescriptor.readOptions(projectRoot)
            assertEquals(NodeProjectLaunchKind.PROJECT_ENTRY, internalOptions.launchKind)
            assertEquals(4321L, internalOptions.timeoutMs)
            assertEquals("interactive_long_running", internalOptions.executionMode)
            File(projectRoot, NodeProjectLaunchDescriptor.INTERNAL_DESCRIPTOR_FILE_NAME).delete()

            descriptor.writeText(
                JSONObject()
                    .put("launchKind", "package-script")
                    .put("packageDir", "packages/tool")
                    .put("workingDirectory", "workspace")
                    .put("scriptName", "build")
                    .put("argv", JSONArray().put("--from-descriptor"))
                    .put("env", JSONObject().put("DESCRIPTOR_SECRET", "hidden-value"))
                    .put("timeoutMs", 1234)
                    .put("entryDirective", "nodejs ui-thread")
                    .put("processPoolSlot", NodeEmbeddedProcessPoolPolicy.OVERFLOW_SLOT_ID)
                    .put("processPoolSlotSource", NodeEmbeddedProcessPoolPolicy.SLOT_SELECTION_EXPLICIT_REQUEST)
                    .toString(),
                StandardCharsets.UTF_8,
            )
            val scriptOptions = NodeProjectLaunchDescriptor.readOptions(projectRoot)
            assertEquals(NodeProjectLaunchKind.PACKAGE_SCRIPT, scriptOptions.launchKind)
            assertEquals(packageDir.canonicalFile, scriptOptions.packageDir)
            assertEquals(workspace.canonicalFile, scriptOptions.workingDirectory)
            assertEquals("build", scriptOptions.scriptName)
            assertEquals(null, scriptOptions.binName)
            assertEquals(listOf("--from-descriptor"), scriptOptions.argv)
            assertEquals(mapOf("DESCRIPTOR_SECRET" to "hidden-value"), scriptOptions.env)
            assertEquals(1234L, scriptOptions.timeoutMs)
            assertEquals(NodeEntryDirective.DIRECTIVE_NODEJS_UI_THREAD, scriptOptions.entryDirective)
            assertEquals(NodeEmbeddedProcessPoolPolicy.OVERFLOW_SLOT_ID, scriptOptions.processPoolSlot)
            assertEquals(NodeEmbeddedProcessPoolPolicy.SLOT_SELECTION_EXPLICIT_REQUEST, scriptOptions.processPoolSlotSource)

            descriptor.writeText(
                JSONObject()
                    .put("launchKind", "package-script")
                    .put("packageDir", "   ")
                    .put("workingDirectory", " \t ")
                    .put("scriptName", "build")
                    .toString(),
                StandardCharsets.UTF_8,
            )
            val blankPathOptions = NodeProjectLaunchDescriptor.readOptions(projectRoot)
            assertEquals(NodeProjectLaunchKind.PACKAGE_SCRIPT, blankPathOptions.launchKind)
            assertEquals(null, blankPathOptions.packageDir)
            assertEquals(null, blankPathOptions.workingDirectory)
            assertEquals("build", blankPathOptions.scriptName)

            descriptor.writeText(
                JSONObject()
                    .put("launchKind", "package-bin")
                    .put("binName", "tool")
                    .toString(),
                StandardCharsets.UTF_8,
            )
            assertEquals(NodeProjectLaunchKind.PACKAGE_BIN, NodeProjectLaunchDescriptor.readOptions(projectRoot).launchKind)

            descriptor.writeText(
                JSONObject()
                    .put("launchKind", "ambiguous")
                    .put("scriptName", "build")
                    .put("binName", "tool")
                    .toString(),
                StandardCharsets.UTF_8,
            )
            assertEquals(NodeProjectLaunchKind.AMBIGUOUS, NodeProjectLaunchDescriptor.readOptions(projectRoot).launchKind)
        } finally {
            projectRoot.deleteRecursively()
        }
    }

    @Test
    fun nodeProjectLaunchDescriptorFileSourceAndProjectRequestStayAligned() {
        val projectRoot = File(context.cacheDir, "embedded-node-project-launch-alignment-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create node project launch alignment dir: $absolutePath" }
        }
        try {
            File(projectRoot, "project.json").writeText(
                """
                {
                  "type": "node",
                  "main": "src/main.js"
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            val entry = File(projectRoot, "src/main.js").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText(""""nodejs"; console.log("alignment");""" + "\n", StandardCharsets.UTF_8)
            }
            val scriptPackageDir = File(projectRoot, "packages/script-tool").apply {
                check(mkdirs()) { "Failed to create alignment script package dir: $absolutePath" }
            }
            val scriptWorkspace = File(projectRoot, "workspace/script").apply {
                check(mkdirs()) { "Failed to create alignment script workspace: $absolutePath" }
            }
            val binPackageDir = File(projectRoot, "packages/bin-tool").apply {
                check(mkdirs()) { "Failed to create alignment bin package dir: $absolutePath" }
            }
            val binWorkspace = File(projectRoot, "workspace/bin").apply {
                check(mkdirs()) { "Failed to create alignment bin workspace: $absolutePath" }
            }
            val descriptor = NodeProjectLaunchDescriptor.descriptorFile(projectRoot)

            fun assertAligned(
                label: String,
                expectedLaunchKind: NodeProjectLaunchKind,
                expectedPackageDir: File?,
                expectedWorkingDirectory: File?,
                expectedScriptName: String?,
                expectedBinName: String?,
                expectedArgv: List<String>,
                expectedEnv: Map<String, String>,
                expectedTimeoutMs: Long?,
                expectedExecutionMode: String? = null,
                expectedOptionsEntryDirective: String? = null,
                expectedEntryDirective: String? = NodeEntryDirective.DIRECTIVE_NODEJS,
                expectedProcessPoolSlot: String? = null,
                expectedProcessPoolSlotSource: String? = null,
            ) {
                val options = NodeProjectLaunchDescriptor.readOptionsOrDefault(projectRoot)
                assertEquals("$label descriptor launchKind", expectedLaunchKind, options.launchKind)
                assertEquals("$label descriptor packageDir", expectedPackageDir?.canonicalFile, options.packageDir)
                assertEquals(
                    "$label descriptor workingDirectory",
                    expectedWorkingDirectory?.canonicalFile,
                    options.workingDirectory,
                )
                assertEquals("$label descriptor scriptName", expectedScriptName, options.scriptName)
                assertEquals("$label descriptor binName", expectedBinName, options.binName)
                assertEquals("$label descriptor argv", expectedArgv, options.argv)
                assertEquals("$label descriptor env", expectedEnv, options.env)
                assertEquals("$label descriptor timeoutMs", expectedTimeoutMs, options.timeoutMs)
                assertEquals("$label descriptor executionMode", expectedExecutionMode, options.executionMode)
                assertEquals("$label descriptor entryDirective", expectedOptionsEntryDirective, options.entryDirective)
                assertEquals("$label descriptor processPoolSlot", expectedProcessPoolSlot, options.processPoolSlot)
                assertEquals("$label descriptor processPoolSlotSource", expectedProcessPoolSlotSource, options.processPoolSlotSource)

                val source = NodeProjectScriptSourceFactory.create(entry)
                assertTrue("$label source should be Node project launch source", source is NodeProjectLaunchSource)
                val launchSource = source as NodeProjectLaunchSource
                assertTrue("$label source should preserve Node project file source type", source is NodeProjectJavaScriptFileSource)
                assertEquals("$label source launchKind", expectedLaunchKind, launchSource.nodeProjectLaunchKind)
                assertEquals("$label source projectRoot", projectRoot.canonicalFile, launchSource.nodeProjectRootFile)
                assertEquals(
                    "$label source packageDir",
                    expectedPackageDir?.canonicalFile,
                    launchSource.nodeProjectPackageDirFile,
                )
                assertEquals(
                    "$label source workingDirectory",
                    expectedWorkingDirectory?.canonicalFile,
                    launchSource.nodeProjectWorkingDirectoryFile,
                )
                assertEquals("$label source scriptName", expectedScriptName, launchSource.nodeProjectScriptName)
                assertEquals("$label source binName", expectedBinName, launchSource.nodeProjectBinName)
                assertEquals("$label source argv", expectedArgv, launchSource.nodeProjectArgv)
                assertEquals("$label source env", expectedEnv, launchSource.nodeProjectEnv)
                assertEquals("$label source timeoutMs", expectedTimeoutMs, launchSource.nodeProjectTimeoutMs)
                assertEquals("$label source executionMode", expectedExecutionMode, launchSource.nodeProjectExecutionMode)
                assertEquals("$label source entryDirective", expectedEntryDirective, launchSource.nodeProjectEntryDirective)
                assertEquals("$label source processPoolSlot", expectedProcessPoolSlot, launchSource.nodeProjectProcessPoolSlot)
                assertEquals(
                    "$label source processPoolSlotSource",
                    expectedProcessPoolSlotSource,
                    launchSource.nodeProjectProcessPoolSlotSource,
                )

                val request = NativeNodeEmbeddedProjectRunner.buildProjectRequest(launchSource)
                assertEquals("$label request projectRoot", projectRoot.canonicalFile, request.projectRoot)
                assertEquals(
                    "$label request packageDir",
                    (expectedPackageDir ?: projectRoot).canonicalFile,
                    request.packageDir,
                )
                assertEquals(
                    "$label request workingDirectory",
                    (expectedWorkingDirectory ?: projectRoot).canonicalFile,
                    request.workingDirectory,
                )
                assertEquals("$label request scriptName", expectedScriptName, request.scriptName)
                assertEquals("$label request binName", expectedBinName, request.binName)
                assertEquals("$label request argv", expectedArgv, request.argv)
                assertEquals("$label request env", expectedEnv, request.env)
                assertEquals("$label request timeoutMs", expectedTimeoutMs ?: 5000L, request.timeoutMs)
                assertEquals(
                    "$label request executionMode",
                    expectedExecutionMode ?: NodeExecutionModePolicy.MODE_ONE_SHOT,
                    request.executionMode,
                )
                assertEquals("$label request entryDirective", expectedEntryDirective, request.entryDirective)
                assertEquals("$label request processPoolSlot", expectedProcessPoolSlot, request.processPoolSlot)
                assertEquals(
                    "$label request processPoolSlotSource",
                    expectedProcessPoolSlotSource,
                    request.processPoolSlotSource,
                )
                assertEquals(
                    "$label request launchKind",
                    expectedLaunchKind,
                    NodeProjectLaunchKind.from(request.scriptName, request.binName),
                )

                val debugDescriptor = NativeNodeEmbeddedProjectRunner.describe(request)
                assertEquals("$label debug launchKind", expectedLaunchKind.descriptorValue, debugDescriptor.launchKind)
                assertEquals(
                    "$label debug packageDir",
                    (expectedPackageDir ?: projectRoot).canonicalFile.absolutePath,
                    debugDescriptor.packageDir,
                )
                assertEquals(
                    "$label debug workingDirectory",
                    (expectedWorkingDirectory ?: projectRoot).canonicalFile.absolutePath,
                    debugDescriptor.workingDirectory,
                )
                assertEquals("$label debug scriptName", expectedScriptName, debugDescriptor.scriptName)
                assertEquals("$label debug binName", expectedBinName, debugDescriptor.binName)
                assertEquals("$label debug env keys", expectedEnv.keys.sorted(), debugDescriptor.envKeys)
                assertEquals("$label debug argv", expectedArgv, debugDescriptor.argv)
                assertEquals("$label debug timeoutMs", expectedTimeoutMs ?: 5000L, debugDescriptor.timeoutMs)
                assertEquals(
                    "$label debug executionMode",
                    expectedExecutionMode ?: NodeExecutionModePolicy.MODE_ONE_SHOT,
                    debugDescriptor.executionMode,
                )
                assertEquals("$label debug entryDirective", expectedEntryDirective, debugDescriptor.entryDirective)
                assertEquals("$label debug processPoolSlot", expectedProcessPoolSlot, debugDescriptor.processPoolSlot)
                assertEquals(
                    "$label debug processPoolSlotSource",
                    expectedProcessPoolSlotSource,
                    debugDescriptor.processPoolSlotSource,
                )
                val nativeValues = debugDescriptor.toNativeValues()
                assertEquals(
                    "$label native entryDirective",
                    expectedEntryDirective.orEmpty(),
                    nativeValues["embedded_project_runner.entry_directive"],
                )
                assertEquals(
                    "$label native ui activity",
                    NodeEntryDirective.requiresUiActivity(expectedEntryDirective).toString(),
                    nativeValues["embedded_project_runner.entry_directive_ui_activity"],
                )
                assertEquals(
                    "$label native ui thread",
                    NodeEntryDirective.requiresUiThread(expectedEntryDirective).toString(),
                    nativeValues["embedded_project_runner.entry_directive_ui_thread"],
                )
                assertEquals(
                    "$label native processPoolSlot",
                    expectedProcessPoolSlot.orEmpty(),
                    nativeValues["embedded_project_runner.process_pool_slot"],
                )
                assertEquals(
                    "$label native processPoolSlotSource",
                    expectedProcessPoolSlotSource.orEmpty(),
                    nativeValues["embedded_project_runner.process_pool_slot_source"],
                )
                val debugText = debugDescriptor.toDebugString()
                expectedEnv.values.forEach { secretValue ->
                    assertFalse("$label debug descriptor leaked env value", debugText.contains(secretValue))
                }
            }

            assertAligned(
                label = "project-entry",
                expectedLaunchKind = NodeProjectLaunchKind.PROJECT_ENTRY,
                expectedPackageDir = null,
                expectedWorkingDirectory = null,
                expectedScriptName = null,
                expectedBinName = null,
                expectedArgv = emptyList(),
                expectedEnv = emptyMap(),
                expectedTimeoutMs = null,
            )

            descriptor.writeText(
                JSONObject()
                    .put("launchKind", "package-script")
                    .put("packageDir", "packages/script-tool")
                    .put("workingDirectory", "workspace/script")
                    .put("scriptName", "verify")
                    .put("argv", JSONArray().put("--from-script-descriptor"))
                    .put("env", JSONObject().put("ALIGN_SCRIPT_SECRET", "script-secret-value"))
                    .put("timeoutMs", 2345L)
                    .put("processPoolSlot", NodeEmbeddedProcessPoolPolicy.OVERFLOW_SLOT_ID)
                    .put("processPoolSlotSource", NodeEmbeddedProcessPoolPolicy.SLOT_SELECTION_EXPLICIT_REQUEST)
                    .toString(),
                StandardCharsets.UTF_8,
            )
            assertAligned(
                label = "package-script",
                expectedLaunchKind = NodeProjectLaunchKind.PACKAGE_SCRIPT,
                expectedPackageDir = scriptPackageDir,
                expectedWorkingDirectory = scriptWorkspace,
                expectedScriptName = "verify",
                expectedBinName = null,
                expectedArgv = listOf("--from-script-descriptor"),
                expectedEnv = mapOf("ALIGN_SCRIPT_SECRET" to "script-secret-value"),
                expectedTimeoutMs = 2345L,
                expectedProcessPoolSlot = NodeEmbeddedProcessPoolPolicy.OVERFLOW_SLOT_ID,
                expectedProcessPoolSlotSource = NodeEmbeddedProcessPoolPolicy.SLOT_SELECTION_EXPLICIT_REQUEST,
            )

            descriptor.writeText(
                JSONObject()
                    .put("launchKind", "package-bin")
                    .put("packageDir", "packages/bin-tool")
                    .put("workingDirectory", "workspace/bin")
                    .put("binName", "align-bin")
                    .put("argv", JSONArray().put("--from-bin-descriptor"))
                    .put("env", JSONObject().put("ALIGN_BIN_SECRET", "bin-secret-value"))
                    .put("timeoutMs", 3456L)
                    .put("entryDirective", "nodejs ui")
                    .toString(),
                StandardCharsets.UTF_8,
            )
            assertAligned(
                label = "package-bin",
                expectedLaunchKind = NodeProjectLaunchKind.PACKAGE_BIN,
                expectedPackageDir = binPackageDir,
                expectedWorkingDirectory = binWorkspace,
                expectedScriptName = null,
                expectedBinName = "align-bin",
                expectedArgv = listOf("--from-bin-descriptor"),
                expectedEnv = mapOf("ALIGN_BIN_SECRET" to "bin-secret-value"),
                expectedTimeoutMs = 3456L,
                expectedOptionsEntryDirective = NodeEntryDirective.DIRECTIVE_NODEJS_UI,
                expectedEntryDirective = NodeEntryDirective.DIRECTIVE_NODEJS_UI,
            )
        } finally {
            projectRoot.deleteRecursively()
        }
    }

    @Test
    fun nodeProjectLaunchDescriptorRejectsUnsafeOrMismatchedFieldsWithoutEnvLeak() {
        val projectRoot = File(context.cacheDir, "embedded-node-project-launch-descriptor-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create node project launch descriptor deny dir: $absolutePath" }
        }
        try {
            val descriptor = NodeProjectLaunchDescriptor.descriptorFile(projectRoot)
            File(projectRoot, "file-instead-of-directory").writeText("not a directory\n", StandardCharsets.UTF_8)

            fun assertInvalid(json: JSONObject, token: String) {
                descriptor.writeText(json.toString(), StandardCharsets.UTF_8)
                val failure = runCatching { NodeProjectLaunchDescriptor.readOptions(projectRoot) }.exceptionOrNull()
                val message = failure?.message.orEmpty()
                assertTrue(message, failure is IllegalArgumentException)
                assertTrue(message, message.contains(token))
                assertFalse(message, message.contains("secret-value"))
            }

            descriptor.writeText(
                """{"launchKind":"package-script","env":{"SECRET":"secret-value"}""",
                StandardCharsets.UTF_8,
            )
            val invalidJsonFailure = runCatching { NodeProjectLaunchDescriptor.readOptions(projectRoot) }.exceptionOrNull()
            val invalidJsonMessage = invalidJsonFailure?.message.orEmpty()
            assertTrue(invalidJsonMessage, invalidJsonFailure is IllegalArgumentException)
            assertTrue(invalidJsonMessage, invalidJsonMessage.contains("Invalid internal Node project launch descriptor"))
            assertTrue(
                invalidJsonMessage,
                invalidJsonMessage.contains(NodeProjectLaunchDescriptor.INVALID_JSON_SANITIZED_MARKER),
            )
            assertFalse(invalidJsonMessage, invalidJsonMessage.contains("secret-value"))
            val invalidJsonStack = invalidJsonFailure?.stackTraceToString().orEmpty()
            assertFalse(invalidJsonStack, invalidJsonStack.contains("secret-value"))

            assertInvalid(
                JSONObject()
                    .put("launchKind", "unknown-kind")
                    .put("env", JSONObject().put("SECRET", "secret-value")),
                "Unsupported Node project launch kind",
            )
            assertInvalid(
                JSONObject()
                    .put("launchKind", "package-script")
                    .put("binName", "tool")
                    .put("env", JSONObject().put("SECRET", "secret-value")),
                "launchKind mismatch",
            )
            assertInvalid(
                JSONObject()
                    .put("workingDirectory", "../outside")
                    .put("env", JSONObject().put("SECRET", "secret-value")),
                "escapes project root",
            )
            assertInvalid(
                JSONObject()
                    .put("packageDir", "../outside")
                    .put("env", JSONObject().put("SECRET", "secret-value")),
                "escapes project root",
            )
            assertInvalid(
                JSONObject()
                    .put("workingDirectory", File(projectRoot, "absolute").absolutePath)
                    .put("env", JSONObject().put("SECRET", "secret-value")),
                "must be relative",
            )
            assertInvalid(
                JSONObject()
                    .put("packageDir", File(projectRoot, "absolute-package").absolutePath)
                    .put("env", JSONObject().put("SECRET", "secret-value")),
                "must be relative",
            )
            assertInvalid(
                JSONObject()
                    .put("workingDirectory", "file:workspace")
                    .put("env", JSONObject().put("SECRET", "secret-value")),
                "must be relative",
            )
            assertInvalid(
                JSONObject()
                    .put("packageDir", "C:\\packages\\tool")
                    .put("env", JSONObject().put("SECRET", "secret-value")),
                "must be relative",
            )
            assertInvalid(
                JSONObject()
                    .put("workingDirectory", "missing")
                    .put("env", JSONObject().put("SECRET", "secret-value")),
                "is not a directory",
            )
            assertInvalid(
                JSONObject()
                    .put("packageDir", "file-instead-of-directory")
                    .put("env", JSONObject().put("SECRET", "secret-value")),
                "is not a directory",
            )
            assertInvalid(
                JSONObject()
                    .put("workingDirectory", "bad\u0000dir")
                    .put("env", JSONObject().put("SECRET", "secret-value")),
                "contains NUL",
            )
            assertInvalid(
                JSONObject()
                    .put("packageDir", "bad\u0000dir")
                    .put("env", JSONObject().put("SECRET", "secret-value")),
                "contains NUL",
            )
            assertInvalid(
                JSONObject()
                    .put("entryDirective", "nodejs native")
                    .put("env", JSONObject().put("SECRET", "secret-value")),
                "Unsupported Node entry directive token",
            )
        } finally {
            projectRoot.deleteRecursively()
        }
    }

    @Test
    fun scriptFileNodeProjectEntryUsesLaunchDescriptorForPackageScriptRequestAndRun() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-script-file-launch-source-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create script file launch source dir: $absolutePath" }
        }
        try {
            File(projectRoot, "project.json").writeText(
                """
                {
                  "name": "script-file-launch-source",
                  "packageName": "org.autojs.test.script.file.launch.source",
                  "versionName": "1.0.0",
                  "versionCode": 1,
                  "type": "node",
                  "main": "src/main.js"
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            val main = File(projectRoot, "src/main.js").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText(
                    """"nodejs"; require("fs").writeFileSync("./unexpected-script-file-main.txt", "main", "utf8");""" + "\n",
                    StandardCharsets.UTF_8,
                )
            }
            File(projectRoot, "scripts/verify.js").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText(
                    """
                    "nodejs";
                    const fs = require("fs");
                    const path = require("path");
                    const ready =
                      path.basename(process.cwd()) === "script-file-workspace" &&
                      process.argv.includes("--from-package-script") &&
                      process.argv.includes("--from-script-file-descriptor") &&
                      process.env.SCRIPT_FILE_SOURCE_ENV === "source-secret" &&
                      process.env.npm_lifecycle_event === "verify" &&
                      require.main === module &&
                      module.parent === null &&
                      !fs.existsSync("./unexpected-script-file-main.txt");
                    fs.writeFileSync("../script-file-source.txt", ready ? "ok" : "bad", "utf8");
                    console.log("script_file.launch_source.ready=" + ready);
                    """.trimIndent() + "\n",
                    StandardCharsets.UTF_8,
                )
            }
            File(projectRoot, "package.json").writeText(
                """
                {
                  "name": "script-file-launch-source-root",
                  "version": "1.0.0",
                  "scripts": {
                    "verify": "node ./scripts/verify.js --from-package-script"
                  }
                }
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )
            val workspace = File(projectRoot, "script-file-workspace").apply {
                check(mkdirs()) { "Failed to create script file launch workspace: $absolutePath" }
            }
            NodeProjectLaunchDescriptor.descriptorFile(projectRoot).writeText(
                JSONObject()
                    .put("launchKind", "package-script")
                    .put("scriptName", "verify")
                    .put("workingDirectory", "script-file-workspace")
                    .put("argv", JSONArray().put("--from-script-file-descriptor"))
                    .put("env", JSONObject().put("SCRIPT_FILE_SOURCE_ENV", "source-secret"))
                    .put("processPoolSlot", NodeEmbeddedProcessPoolPolicy.OVERFLOW_SLOT_ID)
                    .put("processPoolSlotSource", NodeEmbeddedProcessPoolPolicy.SLOT_SELECTION_EXPLICIT_REQUEST)
                    .toString(),
                StandardCharsets.UTF_8,
            )

            val source = ScriptFile(main).toSource()
            assertTrue(source is NodeProjectLaunchSource)
            val launchSource = source as NodeProjectLaunchSource
            assertEquals(NodeProjectLaunchKind.PACKAGE_SCRIPT, launchSource.nodeProjectLaunchKind)
            assertTrue(NodeProjectScriptSourceFactory.create(main) is NodeProjectLaunchSource)
            val pathLaunch = ScriptLaunchSourceFactory.createPathLaunch(main.absolutePath)
            assertEquals(workspace.canonicalPath, pathLaunch.workingDirectory)
            assertTrue(pathLaunch.source is NodeProjectLaunchSource)
            val pathRequest = NativeNodeEmbeddedProjectRunner.buildProjectRequest(pathLaunch.source as NodeProjectLaunchSource)
            assertEquals(projectRoot.canonicalFile, pathRequest.projectRoot)
            assertEquals(projectRoot.canonicalFile, pathRequest.packageDir)
            assertEquals(workspace.canonicalFile, pathRequest.workingDirectory)
            assertEquals("verify", pathRequest.scriptName)
            assertEquals(NodeEmbeddedProcessPoolPolicy.OVERFLOW_SLOT_ID, pathRequest.processPoolSlot)
            assertEquals(NodeEmbeddedProcessPoolPolicy.SLOT_SELECTION_EXPLICIT_REQUEST, pathRequest.processPoolSlotSource)
            val request = NativeNodeEmbeddedProjectRunner.buildProjectRequest(launchSource)
            assertEquals(projectRoot.canonicalFile, request.projectRoot)
            assertEquals(projectRoot.canonicalFile, request.packageDir)
            assertEquals(workspace.canonicalFile, request.workingDirectory)
            assertEquals("verify", request.scriptName)
            assertEquals(null, request.binName)
            assertEquals(listOf("--from-script-file-descriptor"), request.argv)
            assertEquals(mapOf("SCRIPT_FILE_SOURCE_ENV" to "source-secret"), request.env)
            assertEquals(NodeEmbeddedProcessPoolPolicy.OVERFLOW_SLOT_ID, request.processPoolSlot)
            assertEquals(NodeEmbeddedProcessPoolPolicy.SLOT_SELECTION_EXPLICIT_REQUEST, request.processPoolSlotSource)

            val engine = NativeNodeEmbeddedJavaScriptEngine(context)
            assertEquals(0, engine.doExecution(source as JavaScriptSource))

            assertEquals("ok", File(projectRoot, "script-file-source.txt").readText(StandardCharsets.UTF_8))
            val descriptor = engine.lastNodeProjectRunnerDescriptor
            assertEquals("package-script", descriptor?.launchKind)
            assertEquals("verify", descriptor?.scriptName)
            assertEquals(workspace.canonicalPath, descriptor?.workingDirectory)
            assertEquals(listOf("--from-script-file-descriptor"), descriptor?.argv)
            assertEquals(listOf("SCRIPT_FILE_SOURCE_ENV"), descriptor?.envKeys)
            assertEquals(NodeEmbeddedProcessPoolPolicy.OVERFLOW_SLOT_ID, descriptor?.processPoolSlot)
            assertEquals(NodeEmbeddedProcessPoolPolicy.SLOT_SELECTION_EXPLICIT_REQUEST, descriptor?.processPoolSlotSource)
            val nativeValues = engine.lastEmbeddedScriptResultNativeValues
            assertEquals(
                NodeEmbeddedProcessPoolPolicy.OVERFLOW_SLOT_ID,
                nativeValues["embedded_script.process_pool.selected_slot_id"],
            )
            assertEquals(
                NodeEmbeddedProcessPoolPolicy.MODE_EXPLICIT_TWO_SLOT,
                nativeValues["embedded_script.process_pool.mode"],
            )
            assertEquals(
                NodeEmbeddedProcessPoolPolicy.SLOT_SELECTION_EXPLICIT_REQUEST,
                nativeValues["embedded_script.process_pool.slot_selection_source"],
            )
            assertEquals(
                NodeEmbeddedProcessPoolPolicy.OVERFLOW_SLOT_ID,
                nativeValues["embedded_project_runner.process_pool_slot"],
            )
        } finally {
            projectRoot.deleteRecursively()
        }
    }

