            assertEquals("ok", File(projectRoot, "project-launcher-bin.txt").readText(StandardCharsets.UTF_8))
            val descriptor = engine.lastNodeProjectRunnerDescriptor
            assertEquals("package-bin", descriptor?.launchKind)
            assertEquals("launcher-bin", descriptor?.binName)
            assertEquals(File(projectRoot, "project-launcher-bin-workspace").canonicalPath, descriptor?.workingDirectory)
            assertEquals(listOf("--from-launcher-bin"), descriptor?.argv)
            assertEquals(listOf("PROJECT_LAUNCHER_BIN_ENV"), descriptor?.envKeys)
        } finally {
            projectRoot.deleteRecursively()
        }
    }

    @Test
    fun nodeProjectJavaScriptFileSourceExposesLaunchKindAndStableOptionSnapshots() {
        val root = File(context.cacheDir, "embedded-node-project-launch-source-options-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create node project launch source options dir: $absolutePath" }
        }
        try {
            val carrier = File(root, "main.js").apply {
                writeText(""""nodejs";""" + "\n", StandardCharsets.UTF_8)
            }
            val packageDir = File(root, "node_modules/source-tool").apply {
                check(mkdirs()) { "Failed to create node project launch source options package dir: $absolutePath" }
            }
            val workspace = File(root, "workspace").apply {
                check(mkdirs()) { "Failed to create node project launch source options workspace dir: $absolutePath" }
            }
            val argv = mutableListOf("--before")
            val env = mutableMapOf("SOURCE_ENV" to "before")
            val source = NodeProjectJavaScriptFileSource(
                projectRoot = root,
                file = carrier,
                launchOptions = NodeProjectLaunchOptions(
                    packageDir = packageDir,
                    workingDirectory = workspace,
                    scriptName = "build",
                    argv = argv,
                    env = env,
                    timeoutMs = 1234L,
                    executionMode = NodeExecutionModePolicy.MODE_INTERACTIVE_LONG_RUNNING,
                    entryDirective = "node ui_thread",
                ),
            )

            argv += "--after"
            env["SOURCE_ENV"] = "after"
            env["EXTRA_ENV"] = "extra"

            assertEquals(NodeProjectLaunchKind.PROJECT_ENTRY, NodeProjectLaunchOptions().launchKind)
            assertEquals(NodeProjectLaunchKind.PACKAGE_SCRIPT, NodeProjectLaunchOptions(scriptName = "build").launchKind)
            assertEquals(NodeProjectLaunchKind.PACKAGE_BIN, NodeProjectLaunchOptions(binName = "tool").launchKind)
            assertEquals(
                NodeProjectLaunchKind.AMBIGUOUS,
                NodeProjectLaunchOptions(scriptName = "build", binName = "tool").launchKind,
            )
            assertEquals(NodeProjectLaunchKind.PROJECT_ENTRY, NodeProjectLaunchKind.fromDescriptorValue("project-entry"))
            assertEquals(NodeProjectLaunchKind.PACKAGE_SCRIPT, NodeProjectLaunchKind.fromDescriptorValue("package-script"))
            assertEquals(NodeProjectLaunchKind.PACKAGE_BIN, NodeProjectLaunchKind.fromDescriptorValue("package-bin"))
            assertEquals(NodeProjectLaunchKind.AMBIGUOUS, NodeProjectLaunchKind.fromDescriptorValue("ambiguous"))
            val invalidLaunchKind = runCatching {
                NodeProjectLaunchKind.fromDescriptorValue("unknown-kind")
            }.exceptionOrNull()
            assertTrue(invalidLaunchKind is IllegalArgumentException)
            assertEquals(NodeProjectLaunchKind.PACKAGE_SCRIPT, source.nodeProjectLaunchKind)
            assertEquals(root.canonicalFile, source.nodeProjectRootFile)
            assertEquals(packageDir.canonicalFile, source.nodeProjectPackageDirFile)
            assertEquals(workspace.canonicalFile, source.nodeProjectWorkingDirectoryFile)
            assertEquals(listOf("--before"), source.nodeProjectArgv)
            assertEquals(mapOf("SOURCE_ENV" to "before"), source.nodeProjectEnv)
            assertEquals(1234L, source.nodeProjectTimeoutMs)
            assertEquals(NodeExecutionModePolicy.MODE_INTERACTIVE_LONG_RUNNING, source.nodeProjectExecutionMode)
            assertEquals(NodeEntryDirective.DIRECTIVE_NODEJS_UI_THREAD, source.nodeProjectEntryDirective)
            val request = NativeNodeEmbeddedProjectRunner.buildProjectRequest(source)
            assertEquals(root.canonicalFile, request.projectRoot)
            assertEquals(packageDir.canonicalFile, request.packageDir)
            assertEquals(workspace.canonicalFile, request.workingDirectory)
            assertEquals("build", request.scriptName)
            assertEquals(null, request.binName)
            assertEquals(listOf("--before"), request.argv)
            assertEquals(mapOf("SOURCE_ENV" to "before"), request.env)
            assertEquals(1234L, request.timeoutMs)
            assertEquals(NodeExecutionModePolicy.MODE_INTERACTIVE_LONG_RUNNING, request.executionMode)
            assertEquals(NodeEntryDirective.DIRECTIVE_NODEJS_UI_THREAD, request.entryDirective)

            val argvMutation = runCatching {
                @Suppress("UNCHECKED_CAST")
                (source.nodeProjectArgv as MutableList<String>).add("--mutated")
            }.exceptionOrNull()
            val envMutation = runCatching {
                @Suppress("UNCHECKED_CAST")
                (source.nodeProjectEnv as MutableMap<String, String>)["MUTATED"] = "true"
            }.exceptionOrNull()
            assertTrue(
                argvMutation is UnsupportedOperationException || argvMutation is ClassCastException,
            )
            assertTrue(
                envMutation is UnsupportedOperationException || envMutation is ClassCastException,
            )
            assertEquals(listOf("--before"), source.nodeProjectArgv)
            assertEquals(mapOf("SOURCE_ENV" to "before"), source.nodeProjectEnv)
        } finally {
            root.deleteRecursively()
        }
    }

    @Test
    fun fileEngineNodeProjectLaunchSourceRunsThroughProjectDescriptor() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-node-project-launch-source-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create node project launch source dir: $absolutePath" }
        }
        try {
            File(projectRoot, "project.json").writeText(
                """{"type":"node","main":"packages/app/main.js"}""",
                StandardCharsets.UTF_8,
            )
            File(projectRoot, "root.txt").writeText("root-launch", StandardCharsets.UTF_8)
            File(projectRoot, "node_modules/root-pkg/index.js").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText("""exports.value = "root-pkg";""" + "\n", StandardCharsets.UTF_8)
            }
            val entry = File(projectRoot, "packages/app/main.js").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText(
                    """
                    "nodejs";
                    const fs = require("fs");
                    const helper = require("./helper");
                    const rootPkg = require("root-pkg");
                    const normalizeDataPath = (value) => String(value).replace(/^\/data\/user\/0\//, "/data/data/");
                    const ready =
                      process.cwd() === ${jsStringLiteral(projectRoot.canonicalPath)} &&
                      fs.readFileSync("./root.txt", "utf8") === "root-launch" &&
                      helper.value === "helper" &&
                      rootPkg.value === "root-pkg" &&
                      require.main === module &&
                      module.parent === null &&
                      normalizeDataPath(process.argv[1]) === normalizeDataPath(__filename);
                    fs.writeFileSync("./project-launch-source.txt", ready ? "ok" : "bad", "utf8");
                    console.log("project.launch_source.ready=" + ready);
                    """.trimIndent() + "\n",
                    StandardCharsets.UTF_8,
                )
            }
            File(projectRoot, "packages/app/helper.js").writeText(
                """exports.value = "helper";""" + "\n",
                StandardCharsets.UTF_8,
            )

            val engine = NativeNodeEmbeddedJavaScriptEngine(context)
            assertEquals(0, engine.doExecution(NodeProjectJavaScriptFileSource(projectRoot, entry)))

            assertEquals("ok", File(projectRoot, "project-launch-source.txt").readText(StandardCharsets.UTF_8))
            val descriptor = engine.lastNodeProjectRunnerDescriptor
            assertEquals("project", descriptor?.kind)
            assertEquals("project-entry", descriptor?.launchKind)
            assertEquals(projectRoot.canonicalPath, descriptor?.projectRoot)
            assertEquals(entry.canonicalPath, descriptor?.entryFile)
            assertEquals(projectRoot.canonicalPath, descriptor?.workingDirectory)
            assertTrue("Expected project launch preload modules", (descriptor?.moduleSourceCount ?: 0) >= 2)
            val diagnostics = engine.lastCommonJsPreloadDiagnostics
            assertTrue("Expected project launch static require diagnostics", diagnostics.staticRequireCount >= 3)
            assertTrue(diagnostics.moduleSourceNames.map { it.replace('\\', '/') }.any {
                it.endsWith("/packages/app/helper.js")
            })
            assertEquals("project", engine.lastEmbeddedScriptResultNativeValues["embedded_project_runner.kind"])
            assertEquals(
                projectRoot.canonicalPath,
                engine.lastEmbeddedScriptResultNativeValues["embedded_project_runner.project_root"],
            )
        } finally {
            runCatching { RhinoContext.exit() }
            projectRoot.deleteRecursively()
        }
    }

