                    "nodejs";
                    const fs = require("fs");
                    const helper = require("./helper");
                    const ready =
                      process.argv.includes("--from-script") &&
                      process.argv.includes("--from-source") &&
                      process.env.SOURCE_SCRIPT_ENV === "source-script-secret-value" &&
                      process.env.npm_lifecycle_event === "build" &&
                      process.env.npm_package_name === "source-script-root" &&
                      process.env.INIT_CWD === ${jsStringLiteral(workspace.canonicalPath)} &&
                      process.cwd() === ${jsStringLiteral(workspace.canonicalPath)} &&
                      helper.value === "script-helper" &&
                      require.main === module &&
                      module.parent === null;
                    fs.writeFileSync("./source-package-script.txt", ready ? "ok" : "bad", "utf8");
                    console.log("source.package_script.ready=" + ready);
                    """.trimIndent() + "\n",
                    StandardCharsets.UTF_8,
                )
            }
            File(projectRoot, "scripts/helper.js").writeText(
                """exports.value = "script-helper";""" + "\n",
                StandardCharsets.UTF_8,
            )

            val engine = NativeNodeEmbeddedJavaScriptEngine(context)
            assertEquals(
                0,
                engine.doExecution(
                    NodeProjectJavaScriptFileSource(
                        projectRoot = projectRoot,
                        file = carrier,
                        launchOptions = NodeProjectLaunchOptions(
                            workingDirectory = workspace,
                            scriptName = "build",
                            argv = listOf("--from-source"),
                            env = mapOf("SOURCE_SCRIPT_ENV" to "source-script-secret-value"),
                        ),
                    ),
                ),
            )

            assertEquals("ok", File(workspace, "source-package-script.txt").readText(StandardCharsets.UTF_8))
            val descriptor = engine.lastNodeProjectRunnerDescriptor
            assertEquals("package-script", descriptor?.kind)
            assertEquals("package-script", descriptor?.launchKind)
            assertEquals(projectRoot.canonicalPath, descriptor?.projectRoot)
            assertEquals(entry.canonicalPath, descriptor?.entryFile)
            assertEquals(workspace.canonicalPath, descriptor?.workingDirectory)
            assertEquals(listOf("--from-source"), descriptor?.argv)
            assertEquals(listOf("SOURCE_SCRIPT_ENV"), descriptor?.envKeys)
            assertEquals("build", descriptor?.scriptName)
            assertEquals("node ./scripts/build.js --from-script", descriptor?.scriptCommand)
            assertFalse(descriptor?.toDebugString().orEmpty().contains("source-script-secret-value"))
            val diagnostics = engine.lastCommonJsPreloadDiagnostics
            assertEquals(entry.canonicalPath, diagnostics.sourceName)
            assertTrue(diagnostics.moduleSourceNames.map { it.replace('\\', '/') }.any {
                it.endsWith("/scripts/helper.js")
            })
            val nativeValues = engine.lastEmbeddedScriptResultNativeValues
            assertEquals("package-script", nativeValues["embedded_project_runner.kind"])
            assertEquals("package-script", nativeValues["embedded_project_runner.launch_kind"])
            assertEquals("build", nativeValues["embedded_project_runner.script_name"])
            assertEquals("[SOURCE_SCRIPT_ENV]", nativeValues["embedded_project_runner.env_keys"])
            assertFalse(nativeValues.toString().contains("source-script-secret-value"))
        } finally {
            runCatching { RhinoContext.exit() }
            projectRoot.deleteRecursively()
        }
    }

