            check(mkdirs()) { "Failed to create node project launch source ambiguous dir: $absolutePath" }
        }
        try {
            File(projectRoot, "project.json").writeText(
                """{"type":"node","main":"main.js"}""",
                StandardCharsets.UTF_8,
            )
            val carrier = File(projectRoot, "main.js").apply {
                writeText(""""nodejs"; console.log("ambiguous carrier should not run");""" + "\n", StandardCharsets.UTF_8)
            }

            val engine = NativeNodeEmbeddedJavaScriptEngine(context)
            val failure = runCatching {
                engine.doExecution(
                    NodeProjectJavaScriptFileSource(
                        projectRoot = projectRoot,
                        file = carrier,
                        launchOptions = NodeProjectLaunchOptions(
                            scriptName = "build",
                            binName = "source-bin-tool",
                            argv = listOf("--ambiguous-source"),
                            env = mapOf("SECRET_SHOULD_NOT_PRINT_VALUE" to "secret-value"),
                        ),
                    ),
                )
            }.exceptionOrNull()

            assertTrue(failure is IllegalArgumentException)
            val message = failure?.message.orEmpty()
            assertTrue(message, message.contains(NodeProjectLaunchDiagnostics.RUNNER_REQUEST_FAILURE_MARKER))
            assertTrue(message, message.contains("cannot specify both scriptName and binName"))
            assertTrue(message, message.contains("Node project runner request:"))
            assertTrue(message, message.contains("kind=project"))
            assertTrue(message, message.contains("launchKind=ambiguous"))
            assertTrue(message, message.contains("scriptName=build"))
            assertTrue(message, message.contains("binName=source-bin-tool"))
            assertTrue(message, message.contains("argv=[--ambiguous-source]"))
            assertTrue(message, message.contains("envKeys=[SECRET_SHOULD_NOT_PRINT_VALUE]"))
            assertFalse(message, message.contains("secret-value"))
        } finally {
            runCatching { RhinoContext.exit() }
            projectRoot.deleteRecursively()
        }
    }

