    @Test
    fun nodeProjectRunnerIsolatesArgvEnvCwdAndModuleCacheAcrossExecutions() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-node-project-runner-isolation-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create Node project runner isolation dir: $absolutePath" }
        }
        try {
            val entry = File(projectRoot, "entry.js").apply {
                writeText(
                    """
                    "nodejs";
                    const mutable = require("./mutable");
                    console.log("runner.isolation.argv=" + process.argv.includes("--first"));
                    console.log("runner.isolation.env=" + String(process.env.RUNNER_LEAK));
                    console.log("runner.isolation.cwd=" + (process.cwd() === ${jsStringLiteral(projectRoot.canonicalPath)}));
                    console.log("runner.isolation.mutable=" + mutable.value);
                    process.env.RUNNER_LEAK = "dirty";
                    """.trimIndent() + "\n",
                    StandardCharsets.UTF_8,
                )
            }
            val mutable = File(projectRoot, "mutable.js")
            mutable.writeText("""exports.value = "one";""" + "\n", StandardCharsets.UTF_8)

            val firstRequest = NodeProjectRunRequest(
                projectRoot = projectRoot,
                entryFile = entry,
                argv = listOf("--first"),
                env = mapOf("RUNNER_LEAK" to "first"),
            )
            val first = runNodeProject(firstRequest)
            assertTrue(describeNodeProjectRun(firstRequest, first), first.succeeded)
            assertTrue(first.stdout, first.stdout.contains("runner.isolation.argv=true"))
            assertTrue(first.stdout, first.stdout.contains("runner.isolation.env=first"))
            assertTrue(first.stdout, first.stdout.contains("runner.isolation.cwd=true"))
            assertTrue(first.stdout, first.stdout.contains("runner.isolation.mutable=one"))

            settleEmbeddedScriptServiceProcess()
            mutable.writeText("""exports.value = "two";""" + "\n", StandardCharsets.UTF_8)

            val secondRequest = NodeProjectRunRequest(projectRoot = projectRoot, entryFile = entry)
            val second = runNodeProject(secondRequest)
            assertTrue(describeNodeProjectRun(secondRequest, second), second.succeeded)
            assertTrue(second.stdout, second.stdout.contains("runner.isolation.argv=false"))
            assertTrue(second.stdout, second.stdout.contains("runner.isolation.env=undefined"))
            assertTrue(second.stdout, second.stdout.contains("runner.isolation.cwd=true"))
            assertTrue(second.stdout, second.stdout.contains("runner.isolation.mutable=two"))
        } finally {
            projectRoot.deleteRecursively()
        }
    }

    @Test
    fun nodeProjectRunnerTimeoutPropagatesAndNextRunRecovers() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-node-project-runner-timeout-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create Node project runner timeout dir: $absolutePath" }
        }
        try {
            val timeoutEntry = File(projectRoot, "timeout.js").apply {
                writeText(
                    """
                    "nodejs";
                    setInterval(() => console.log("runner.timeout.tick"), 50);
                    console.log("runner.timeout.started=true");
                    """.trimIndent() + "\n",
                    StandardCharsets.UTF_8,
                )
            }
            val timeoutRequest = NodeProjectRunRequest(
                projectRoot = projectRoot,
                entryFile = timeoutEntry,
                timeoutMs = 900L,
            )
            val timeout = runNodeProject(timeoutRequest)
            assertFalse(timeout.succeeded)
            assertTrue(timeout.timedOut)
            assertEquals("ERR_AUTOJS6_EMBEDDED_NODE_SCRIPT_TIMEOUT", timeout.errorCode)
            assertEquals(900L, timeout.timeoutMs ?: -1L)
            assertTrue(timeout.errorMessage.orEmpty().contains(timeoutEntry.canonicalPath))

            settleEmbeddedScriptServiceProcess()

            val recoveryEntry = File(projectRoot, "recovery.js").apply {
                writeText(
                    """
                    "nodejs";
                    console.log("runner.timeout.recovered=true");
                    """.trimIndent() + "\n",
                    StandardCharsets.UTF_8,
                )
            }
            val recoveryRequest = NodeProjectRunRequest(projectRoot = projectRoot, entryFile = recoveryEntry)
            val recovery = runNodeProject(recoveryRequest)
            assertTrue(describeNodeProjectRun(recoveryRequest, recovery), recovery.succeeded)
            assertTrue(recovery.stdout.contains("runner.timeout.recovered=true"))
        } finally {
            projectRoot.deleteRecursively()
        }
    }

