            val esmRequest = NodeProjectRunRequest(projectRoot = projectRoot, entryFile = esmEntry)
            val esm = runNodeProject(esmRequest)
            assertTrue(describeNodeProjectRun(esmRequest, esm), esm.succeeded)
            assertEquals("true", esm.nativeValues["embedded_script.esm_enabled"])
            assertEquals("true", esm.nativeValues["embedded_script.esm_entry"])

            val nativeEntry = File(projectRoot, "entry.node").apply {
                writeText("native", StandardCharsets.UTF_8)
            }
            val nativeFailure = runCatching {
                runNodeProject(NodeProjectRunRequest(projectRoot = projectRoot, entryFile = nativeEntry))
            }.exceptionOrNull()
            assertTrue(nativeFailure is IllegalArgumentException)
            assertTrue(nativeFailure?.message.orEmpty().contains("native addon"))

            outside.writeText("""console.log("outside");""" + "\n", StandardCharsets.UTF_8)
            val outsideFailure = runCatching {
                runNodeProject(NodeProjectRunRequest(projectRoot = projectRoot, entryFile = outside))
            }.exceptionOrNull()
            assertTrue(outsideFailure is IllegalArgumentException)
            val outsideMessage = outsideFailure?.message.orEmpty()
            assertTrue(outsideMessage, outsideMessage.contains("escapes Node project root"))
            assertTrue(outsideMessage, outsideMessage.contains("Node project runner request:"))
            assertTrue(outsideMessage, outsideMessage.contains("kind=entry"))
            assertTrue(outsideMessage, outsideMessage.contains("projectRoot=${projectRoot.canonicalPath}"))
        } finally {
            projectRoot.deleteRecursively()
            outside.delete()
        }
    }

    @Test
    fun nativeEmbeddedProjectRunnerRunsPackageBinRequestDirectly() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-node-package-bin-runner-direct-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create direct package bin runner dir: $absolutePath" }
        }
        try {
            val packageDir = File(projectRoot, "node_modules/direct-bin-tool").apply {
                check(mkdirs()) { "Failed to create direct package bin package dir: $absolutePath" }
            }
            val workspace = File(projectRoot, "workspace").apply {
                check(mkdirs()) { "Failed to create direct package bin workspace dir: $absolutePath" }
            }

            File(packageDir, "package.json").writeText(
                """{"name":"direct-bin-tool","bin":{"direct-bin-tool":"./cli.js"}}""",
                StandardCharsets.UTF_8,
            )
            File(packageDir, "cli.js").writeText(
                """
                #!/usr/bin/env node
                "nodejs";
                const fs = require("fs");
                const normalizeDataPath = (value) => String(value).replace(/^\/data\/user\/0\//, "/data/data/");
                const ready =
                  process.argv[0] === "autojs6-node" &&
                  normalizeDataPath(process.argv[1]) === normalizeDataPath(__filename) &&
                  process.argv.includes("--bin-direct") &&
                  process.env.PACKAGE_BIN_DIRECT === "ok" &&
                  process.cwd().replace(/\\/g, "/").endsWith("/workspace") &&
                  require.main === module &&
                  module.parent === null;
                fs.writeFileSync("./package-bin-direct.txt", ready ? "ok" : "bad", "utf8");
                console.log("runner.package_bin.direct.ready=" + ready);
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )

            val request = NativeNodeEmbeddedProjectRunner.PackageBinRequest(
                projectRoot = projectRoot,
                packageDir = packageDir,
                binName = "direct-bin-tool",
                workingDirectory = workspace,
                argv = listOf("--bin-direct"),
                env = mapOf("PACKAGE_BIN_DIRECT" to "ok"),
            )
            val plan = NativeNodeEmbeddedProjectRunner.resolvePackageBinLaunchPlan(request)
            assertEquals("package-bin", plan.kind)
            assertEquals(projectRoot.canonicalFile, plan.projectRoot)
            assertEquals(packageDir.canonicalFile, plan.packageDir)
            assertEquals(File(packageDir, "cli.js").canonicalFile, plan.entryFile)
            assertEquals(workspace.canonicalFile, plan.workingDirectory)

            val result = NativeNodeEmbeddedProjectRunner.runPackageBin(context, request)

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            val descriptor = NativeNodeEmbeddedProjectRunner.describe(plan)
            assertEquals("package-bin", descriptor.kind)
            assertEquals("package-bin", descriptor.launchKind)
            assertEquals("direct-bin-tool", descriptor.binName)
            assertEquals(listOf("--bin-direct"), descriptor.argv)
            assertEquals(listOf("PACKAGE_BIN_DIRECT"), descriptor.envKeys)
            val nativeValues = result.nativeValues
            assertEquals("package-bin", nativeValues["embedded_project_runner.kind"])
            assertEquals("package-bin", nativeValues["embedded_project_runner.launch_kind"])
            assertEquals(projectRoot.canonicalPath, nativeValues["embedded_project_runner.project_root"])
            assertEquals(File(packageDir, "cli.js").canonicalPath, nativeValues["embedded_project_runner.entry_file"])
            assertEquals(workspace.canonicalPath, nativeValues["embedded_project_runner.working_directory"])
            assertEquals(packageDir.canonicalPath, nativeValues["embedded_project_runner.package_dir"])
            assertEquals("direct-bin-tool", nativeValues["embedded_project_runner.bin_name"])
            assertEquals("[--bin-direct]", nativeValues["embedded_project_runner.argv"])
            assertEquals("[PACKAGE_BIN_DIRECT]", nativeValues["embedded_project_runner.env_keys"])
            assertTrue(result.stdout.contains("runner.package_bin.direct.ready=true"))
            assertEquals(
                "ok",
                File(workspace, "package-bin-direct.txt").readText(StandardCharsets.UTF_8),
            )
        } finally {
            projectRoot.deleteRecursively()
        }
    }

