        }
        val outsidePackageDir = File(root, "outside-package").apply {
            check(mkdirs()) { "Failed to create outside package bin package dir: $absolutePath" }
        }
        val outsideWorkspace = File(root, "outside-workspace").apply {
            check(mkdirs()) { "Failed to create outside package bin workspace dir: $absolutePath" }
        }
        try {
            listOf(packageDir, outsidePackageDir).forEach { dir ->
                File(dir, "package.json").writeText(
                    """{"name":"boundary-bin","bin":{"boundary-bin":"./cli.js"}}""",
                    StandardCharsets.UTF_8,
                )
                File(dir, "cli.js").writeText(
                    """"nodejs"; console.log("boundary bin should not run");""" + "\n",
                    StandardCharsets.UTF_8,
                )
            }

            fun assertBoundaryRejection(
                request: NativeNodeEmbeddedProjectRunner.PackageBinRequest,
