                assertTrue(message, message.contains("kind=package-bin"))
                assertTrue(message, message.contains("binName=boundary-bin"))
                assertTrue(message, message.contains("envKeys=[BOUNDARY_SECRET]"))
                assertFalse(message, message.contains("boundary-secret-value"))
            }

            assertBoundaryRejection(
                NativeNodeEmbeddedProjectRunner.PackageBinRequest(
                    projectRoot = projectRoot,
                    packageDir = outsidePackageDir,
                    binName = "boundary-bin",
                    env = mapOf("BOUNDARY_SECRET" to "boundary-secret-value"),
                ),
                "Node package bin packageDir escapes Node project root",
            )
            assertBoundaryRejection(
                NativeNodeEmbeddedProjectRunner.PackageBinRequest(
                    projectRoot = projectRoot,
                    packageDir = packageDir,
                    binName = "boundary-bin",
                    workingDirectory = outsideWorkspace,
                    env = mapOf("BOUNDARY_SECRET" to "boundary-secret-value"),
                ),
                "Node package bin workingDirectory escapes Node project root",
            )
        } finally {
            root.deleteRecursively()
        }
    }

