    @Test
    fun packageScriptAndBinRunnerRejectMetadataFailuresWithSanitizedDescriptor() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-package-metadata-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create package metadata deny project dir: $absolutePath" }
        }
        val workspace = File(projectRoot, "workspace").apply {
            check(mkdirs()) { "Failed to create package metadata deny workspace: $absolutePath" }
        }
        val secretKey = "RUNNER_METADATA_SECRET"
        val secretValue = "runner-metadata-secret-value"
        try {
            fun writeFile(root: File, relativePath: String, content: String) {
                File(root, relativePath).apply {
                    parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                    writeText(content, StandardCharsets.UTF_8)
                }
            }

            fun assertFailure(
                label: String,
                kind: String,
                expectedToken: String,
                packageDir: File,
                workingDirectory: File,
                scriptName: String? = null,
                binName: String? = null,
                action: () -> Unit,
            ) {
                val failure = runCatching { action() }.exceptionOrNull()
                assertTrue("$label should fail fast", failure is IllegalArgumentException)
                val message = failure?.message.orEmpty()
                assertTrue(message, message.contains(NodeProjectLaunchDiagnostics.RUNNER_REQUEST_FAILURE_MARKER))
                assertTrue(message, message.contains(expectedToken))
                assertTrue(message, message.contains("Node project runner request:"))
                assertTrue(message, message.contains("kind=$kind"))
                assertTrue(message, message.contains("launchKind=$kind"))
                assertTrue(message, message.contains("requestReady=true"))
                assertTrue(message, message.contains("packageDir=${packageDir.canonicalPath}"))
                assertTrue(message, message.contains("workingDirectory=${workingDirectory.canonicalPath}"))
                assertTrue(message, message.contains("argv=[--metadata-deny]"))
                assertTrue(message, message.contains("argvCount=1"))
                assertTrue(message, message.contains("envKeys=[$secretKey]"))
                scriptName?.let {
                    assertTrue(message, message.contains("script=$it"))
                    assertTrue(message, message.contains("scriptName=$it"))
                }
                binName?.let {
                    assertTrue(message, message.contains("bin=$it"))
                    assertTrue(message, message.contains("binName=$it"))
                }
                assertFalse(message, message.contains(secretValue))
                assertFalse(message, message.contains("metadata deny fallback should not run"))
            }

            fun scriptPackageJson(scriptValue: Any?): String {
                return JSONObject()
                    .put("name", "metadata-deny-script")
                    .put("version", "1.0.0")
                    .put("scripts", JSONObject().put("bad", scriptValue))
                    .toString()
            }

            fun binPackageJson(binValue: Any?): String {
                return JSONObject()
                    .put("name", "metadata-deny-bin")
                    .put("version", "1.0.0")
                    .put("bin", JSONObject().put("bad-bin", binValue))
                    .toString()
            }

            fun assertScriptRejected(
                id: String,
                expectedToken: String,
                packageJson: String? = null,
                files: Map<String, String> = emptyMap(),
                packageDirAsFile: Boolean = false,
                workingDirectoryAsFile: Boolean = false,
            ) {
                val packageDir = File(projectRoot, "packages/script-$id")
                packageDir.deleteRecursively()
                if (packageDirAsFile) {
                    packageDir.parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                    packageDir.writeText("not a directory\n", StandardCharsets.UTF_8)
                } else {
                    check(packageDir.mkdirs()) { "Failed to create script metadata deny package dir: ${packageDir.absolutePath}" }
                    packageJson?.let { File(packageDir, "package.json").writeText(it, StandardCharsets.UTF_8) }
                    files.forEach { (relativePath, content) -> writeFile(packageDir, relativePath, content) }
                }
                val workingDirectory = if (workingDirectoryAsFile) {
                    File(projectRoot, "workspace-file-$id.txt").apply {
                        writeText("not a directory\n", StandardCharsets.UTF_8)
                    }
                } else {
                    workspace
                }
                val request = NativeNodeEmbeddedProjectRunner.PackageScriptRequest(
                    projectRoot = projectRoot,
                    packageDir = packageDir,
                    scriptName = "bad",
                    workingDirectory = workingDirectory,
                    argv = listOf("--metadata-deny"),
                    env = mapOf(secretKey to secretValue),
                )
                assertFailure(
                    label = "script $id",
                    kind = "package-script",
                    expectedToken = expectedToken,
                    packageDir = packageDir,
                    workingDirectory = workingDirectory,
                    scriptName = "bad",
                ) {
                    NativeNodeEmbeddedProjectRunner.runPackageScript(context, request)
                }
            }

            fun assertBinRejected(
                id: String,
                expectedToken: String,
                packageJson: String? = null,
                files: Map<String, String> = emptyMap(),
                packageDirAsFile: Boolean = false,
                workingDirectoryAsFile: Boolean = false,
            ) {
                val packageDir = File(projectRoot, "packages/bin-$id")
                packageDir.deleteRecursively()
                if (packageDirAsFile) {
                    packageDir.parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                    packageDir.writeText("not a directory\n", StandardCharsets.UTF_8)
                } else {
                    check(packageDir.mkdirs()) { "Failed to create bin metadata deny package dir: ${packageDir.absolutePath}" }
                    packageJson?.let { File(packageDir, "package.json").writeText(it, StandardCharsets.UTF_8) }
                    files.forEach { (relativePath, content) -> writeFile(packageDir, relativePath, content) }
                }
                val workingDirectory = if (workingDirectoryAsFile) {
                    File(projectRoot, "bin-workspace-file-$id.txt").apply {
                        writeText("not a directory\n", StandardCharsets.UTF_8)
                    }
                } else {
                    workspace
                }
                val request = NativeNodeEmbeddedProjectRunner.PackageBinRequest(
                    projectRoot = projectRoot,
                    packageDir = packageDir,
                    binName = "bad-bin",
                    workingDirectory = workingDirectory,
                    argv = listOf("--metadata-deny"),
                    env = mapOf(secretKey to secretValue),
                )
                assertFailure(
                    label = "bin $id",
                    kind = "package-bin",
                    expectedToken = expectedToken,
                    packageDir = packageDir,
                    workingDirectory = workingDirectory,
                    binName = "bad-bin",
                ) {
                    NativeNodeEmbeddedProjectRunner.runPackageBin(context, request)
                }
            }

            assertScriptRejected(
                id = "package-dir-file",
                expectedToken = "Node package script packageDir is not a directory",
                packageDirAsFile = true,
            )
            assertScriptRejected(
                id = "working-directory-file",
                expectedToken = "Node package script workingDirectory is not a directory",
                packageJson = scriptPackageJson("node ./scripts/run.js"),
                files = mapOf("scripts/run.js" to """"nodejs"; console.log("metadata deny fallback should not run");""" + "\n"),
                workingDirectoryAsFile = true,
            )
            assertScriptRejected(
                id = "missing-package-json",
                expectedToken = "Missing package.json for package script",
            )
            assertScriptRejected(
                id = "missing-scripts",
                expectedToken = "Missing package scripts",
                packageJson = JSONObject().put("name", "metadata-deny-script").put("version", "1.0.0").toString(),
            )
            assertScriptRejected(
                id = "missing-script",
                expectedToken = "Missing package script 'bad'",
                packageJson = JSONObject()
                    .put("name", "metadata-deny-script")
                    .put("version", "1.0.0")
                    .put("scripts", JSONObject())
                    .toString(),
            )
            assertScriptRejected(
                id = "unsupported-script",
                expectedToken = "Unsupported package script 'bad'",
                packageJson = scriptPackageJson(42),
            )
            assertScriptRejected(
                id = "node-entry-missing",
                expectedToken = "Package script node entry missing: ./scripts/missing.js",
                packageJson = scriptPackageJson("node ./scripts/missing.js"),
            )
            assertScriptRejected(
                id = "node-entry-extension",
                expectedToken = "Unsupported package script node entry extension: ./README.txt",
                packageJson = scriptPackageJson("node ./README.txt"),
                files = mapOf("README.txt" to "not javascript\n"),
            )
            assertScriptRejected(
                id = "node-native-addon",
                expectedToken = "Unsupported package script node native addon entry: ./addon.node",
                packageJson = scriptPackageJson("node ./addon.node"),
                files = mapOf("addon.node" to "native-addon-placeholder\n"),
            )

            assertBinRejected(
                id = "package-dir-file",
                expectedToken = "Node package bin packageDir is not a directory",
                packageDirAsFile = true,
            )
            assertBinRejected(
                id = "working-directory-file",
                expectedToken = "Node package bin workingDirectory is not a directory",
                packageJson = binPackageJson("./cli.js"),
                files = mapOf("cli.js" to """"nodejs"; console.log("metadata deny fallback should not run");""" + "\n"),
                workingDirectoryAsFile = true,
            )
            assertBinRejected(
                id = "missing-package-json",
                expectedToken = "Missing package.json for package bin",
            )
            assertBinRejected(
                id = "missing-bin",
                expectedToken = "Missing package bin",
                packageJson = JSONObject().put("name", "metadata-deny-bin").put("version", "1.0.0").toString(),
            )
            assertBinRejected(
                id = "unsupported-bin-shape",
                expectedToken = "Unsupported package bin shape",
                packageJson = JSONObject()
                    .put("name", "metadata-deny-bin")
                    .put("version", "1.0.0")
                    .put("bin", 42)
                    .toString(),
            )
            assertBinRejected(
                id = "missing-bin-entry",
                expectedToken = "Missing package bin entry 'bad-bin'",
                packageJson = JSONObject()
                    .put("name", "metadata-deny-bin")
                    .put("version", "1.0.0")
                    .put("bin", JSONObject().put("other-bin", "./cli.js"))
                    .toString(),
            )
            assertBinRejected(
                id = "unsupported-bin-entry",
                expectedToken = "Unsupported package bin entry 'bad-bin'",
                packageJson = binPackageJson(42),
            )
            assertBinRejected(
                id = "empty-bin-target",
                expectedToken = "Package bin target is empty",
                packageJson = binPackageJson(""),
            )
            assertBinRejected(
                id = "missing-bin-target",
                expectedToken = "Package bin target missing: ./missing.js",
                packageJson = binPackageJson("./missing.js"),
            )
            assertBinRejected(
                id = "bin-target-extension",
                expectedToken = "Unsupported package bin target extension: ./cli.txt",
                packageJson = binPackageJson("./cli.txt"),
                files = mapOf("cli.txt" to "not javascript\n"),
            )
            assertBinRejected(
                id = "bin-native-addon",
                expectedToken = "Unsupported package bin native addon target: ./addon.node",
                packageJson = binPackageJson("./addon.node"),
                files = mapOf("addon.node" to "native-addon-placeholder\n"),
            )
        } finally {
            projectRoot.deleteRecursively()
        }
    }

