                    "build": "direct-bin-tool --from-script \"quoted arg\""
                  }
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(toolDir, "package.json").writeText(
                """{"name":"direct-bin-tool","version":"1.0.0","bin":{"direct-bin-tool":"./cli.js"}}""",
                StandardCharsets.UTF_8,
            )
            File(toolDir, "cli.js").writeText(
                """
                "nodejs";
                const fs = require("fs");
                const normalizeDataPath = (value) => String(value).replace(/^\/data\/user\/0\//, "/data/data/");
                const ready =
                  process.argv[0] === "autojs6-node" &&
                  normalizeDataPath(process.argv[1]) === normalizeDataPath(__filename) &&
                  process.argv.includes("--from-script") &&
                  process.argv.includes("quoted arg") &&
                  process.argv.includes("--from-request") &&
                  process.env.REQUEST_ENV === "visible" &&
                  process.env.npm_lifecycle_event === "build" &&
                  process.env.npm_package_name === "script-root" &&
                  process.env.npm_package_version === "1.2.3" &&
                  normalizeDataPath(process.env.npm_package_json).endsWith("/package.json") &&
                  process.env.INIT_CWD === ${jsStringLiteral(workspace.canonicalPath)} &&
                  process.cwd() === ${jsStringLiteral(workspace.canonicalPath)} &&
                  require.main === module &&
                  module.parent === null;
                fs.writeFileSync("./package-script-bin.txt", ready ? "ok" : "bad", "utf8");
                console.log("runner.package_script.bin.ready=" + ready);
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )

            val request = NativeNodeEmbeddedProjectRunner.PackageScriptRequest(
                projectRoot = projectRoot,
                packageDir = projectRoot,
                scriptName = "build",
                workingDirectory = workspace,
                argv = listOf("--from-request"),
                env = mapOf("REQUEST_ENV" to "visible"),
            )
            val plan = NativeNodeEmbeddedProjectRunner.resolvePackageScriptLaunchPlan(request)
            val planDescriptor = NativeNodeEmbeddedProjectRunner.describe(plan)
            assertEquals("package-script", plan.kind)
            assertEquals(File(toolDir, "cli.js").canonicalFile, plan.entryFile)
            assertEquals(listOf("--from-script", "quoted arg", "--from-request"), plan.argv)
            assertEquals("visible", plan.env["REQUEST_ENV"])
            assertEquals("build", plan.env["npm_lifecycle_event"])
            assertEquals(listOf("--from-request"), planDescriptor.argv)
            assertEquals(listOf("REQUEST_ENV"), planDescriptor.envKeys)
            assertFalse(planDescriptor.toDebugString().contains("visible"))

            val result = NativeNodeEmbeddedProjectRunner.runPackageScript(context, request)

            assertTrue(NativeNodeEmbeddedProjectRunner.describe(request, result), result.succeeded)
            assertTrue(result.stdout, result.stdout.contains("runner.package_script.bin.ready=true"))
            assertEquals("ok", File(workspace, "package-script-bin.txt").readText(StandardCharsets.UTF_8))
            val nativeValues = result.nativeValues
            assertEquals("package-script", nativeValues["embedded_project_runner.kind"])
            assertEquals("package-script", nativeValues["embedded_project_runner.launch_kind"])
            assertEquals(projectRoot.canonicalPath, nativeValues["embedded_project_runner.project_root"])
            assertEquals(File(toolDir, "cli.js").canonicalPath, nativeValues["embedded_project_runner.entry_file"])
            assertEquals(workspace.canonicalPath, nativeValues["embedded_project_runner.working_directory"])
            assertEquals(projectRoot.canonicalPath, nativeValues["embedded_project_runner.package_dir"])
            assertEquals("direct-bin-tool", nativeValues["embedded_project_runner.bin_name"])
            assertEquals("build", nativeValues["embedded_project_runner.script_name"])
            assertEquals("direct-bin-tool --from-script \"quoted arg\"", nativeValues["embedded_project_runner.script_command"])
            assertTrue(nativeValues["embedded_project_runner.resolved_command"].orEmpty().contains("direct-bin-tool"))
            assertEquals("[--from-request]", nativeValues["embedded_project_runner.argv"])
            assertEquals("[REQUEST_ENV]", nativeValues["embedded_project_runner.env_keys"])
        } finally {
            projectRoot.deleteRecursively()
        }
    }

    @Test
    fun packageScriptRunnerRunsNodeModulesBinEquivalentCommands() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-package-script-node-modules-bin-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create package script node_modules bin dir: $absolutePath" }
        }
        try {
            val workspace = File(projectRoot, "workspace").apply {
                check(mkdirs()) { "Failed to create package script node_modules bin workspace: $absolutePath" }
            }
            val toolDir = File(projectRoot, "node_modules/direct-bin-tool").apply {
                check(mkdirs()) { "Failed to create package script node_modules bin tool dir: $absolutePath" }
            }
            File(projectRoot, "package.json").writeText(
                """
                {
                  "name": "script-node-modules-bin-root",
                  "version": "1.0.0",
                  "scripts": {
                    "dot-bin": "./node_modules/.bin/direct-bin-tool --from-dot-bin",
                    "plain-bin": "node_modules/.bin/direct-bin-tool --from-plain-bin"
                  }
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(toolDir, "package.json").writeText(
                """{"name":"direct-bin-tool","version":"1.0.0","bin":{"direct-bin-tool":"./cli.js"}}""",
                StandardCharsets.UTF_8,
            )
            File(toolDir, "cli.js").writeText(
                """
                "nodejs";
                const fs = require("fs");
                const normalizeDataPath = (value) => String(value).replace(/^\/data\/user\/0\//, "/data/data/");
                const event = process.env.npm_lifecycle_event;
                const expectedArg = event === "dot-bin" ? "--from-dot-bin" : "--from-plain-bin";
                const ready =
                  process.argv[0] === "autojs6-node" &&
                  normalizeDataPath(process.argv[1]) === normalizeDataPath(__filename) &&
                  process.argv.includes(expectedArg) &&
                  process.argv.includes("--from-request") &&
                  process.env.REQUEST_ENV === "visible" &&
                  process.env.npm_package_name === "script-node-modules-bin-root" &&
                  process.env.INIT_CWD === ${jsStringLiteral(workspace.canonicalPath)} &&
                  process.cwd() === ${jsStringLiteral(workspace.canonicalPath)} &&
                  require.main === module &&
                  module.parent === null;
                fs.writeFileSync("./package-script-node-modules-bin-" + event + ".txt", ready ? "ok" : "bad", "utf8");
                console.log("runner.package_script.node_modules_bin." + event + ".ready=" + ready);
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )
            assertFalse(File(projectRoot, "node_modules/.bin").exists())

            fun assertNodeModulesBinScript(
                scriptName: String,
                scriptCommand: String,
                scriptArg: String,
            ) {
                val request = NativeNodeEmbeddedProjectRunner.PackageScriptRequest(
                    projectRoot = projectRoot,
                    packageDir = projectRoot,
                    scriptName = scriptName,
                    workingDirectory = workspace,
                    argv = listOf("--from-request"),
                    env = mapOf("REQUEST_ENV" to "visible"),
                )
                val plan = NativeNodeEmbeddedProjectRunner.resolvePackageScriptLaunchPlan(request)
                assertEquals(File(toolDir, "cli.js").canonicalFile, plan.entryFile)
                assertEquals("direct-bin-tool", plan.binName)
                assertEquals(scriptName, plan.scriptName)
                assertEquals(scriptCommand, plan.scriptCommand)
                assertTrue(plan.resolvedCommand.orEmpty().contains("direct-bin-tool ->"))
                assertEquals(listOf(scriptArg, "--from-request"), plan.argv)

                val result = NativeNodeEmbeddedProjectRunner.runPackageScript(context, request)

                assertTrue(NativeNodeEmbeddedProjectRunner.describe(request, result), result.succeeded)
                assertTrue(
                    result.stdout,
                    result.stdout.contains("runner.package_script.node_modules_bin.$scriptName.ready=true"),
                )
                assertEquals(
                    "ok",
                    File(workspace, "package-script-node-modules-bin-$scriptName.txt").readText(StandardCharsets.UTF_8),
                )
                assertEquals("direct-bin-tool", result.nativeValues["embedded_project_runner.bin_name"])
                assertEquals(scriptCommand, result.nativeValues["embedded_project_runner.script_command"])
                assertEquals(File(toolDir, "cli.js").canonicalPath, result.nativeValues["embedded_project_runner.entry_file"])
            }

            assertNodeModulesBinScript(
                scriptName = "dot-bin",
                scriptCommand = "./node_modules/.bin/direct-bin-tool --from-dot-bin",
                scriptArg = "--from-dot-bin",
            )
            settleEmbeddedScriptServiceProcess()
            assertNodeModulesBinScript(
                scriptName = "plain-bin",
                scriptCommand = "node_modules/.bin/direct-bin-tool --from-plain-bin",
                scriptArg = "--from-plain-bin",
            )
        } finally {
            projectRoot.deleteRecursively()
        }
    }

    @Test
    fun packageScriptAndBinRunnerRunOfflineNpmToolchainCorpus() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-npm-toolchain-corpus-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create npm toolchain corpus dir: $absolutePath" }
        }
        try {
            val corpus = EmbeddedNodeFixtureCorpus.writeNpmToolchainCorpus(projectRoot)
            assertFalse(File(corpus.packageDir, "node_modules/.bin").exists())

            fun assertToolchainScript(
                scriptName: String,
                expectedLabel: String,
                expectedBinName: String,
                expectedEntry: File,
            ) {
                val request = NativeNodeEmbeddedProjectRunner.PackageScriptRequest(
                    projectRoot = projectRoot,
                    packageDir = corpus.packageDir,
                    scriptName = scriptName,
                    workingDirectory = corpus.workingDirectory,
                    argv = listOf("--from-request", "--color"),
                    env = mapOf("TOOLCHAIN_REQUEST_ENV" to "visible"),
                )
                val plan = NativeNodeEmbeddedProjectRunner.resolvePackageScriptLaunchPlan(request)
                assertEquals("package-script", plan.kind)
                assertEquals(expectedEntry.canonicalFile, plan.entryFile)
                assertEquals(corpus.workingDirectory.canonicalFile, plan.workingDirectory)
                assertEquals(expectedBinName, plan.binName)
                assertEquals(scriptName, plan.scriptName)
                assertTrue(plan.argv.contains("--from-request"))
                assertTrue(plan.argv.contains("--color"))
                assertTrue(plan.argv.contains("--mode=build") || plan.argv.contains("--mode=helper"))

                val result = NativeNodeEmbeddedProjectRunner.runPackageScript(context, request)

                assertTrue(NativeNodeEmbeddedProjectRunner.describe(request, result), result.succeeded)
                assertTrue(result.stdout, result.stdout.contains("$expectedLabel.ready=true"))
                assertTrue(result.stdout, result.stdout.contains("$expectedLabel.argv=true"))
                assertTrue(result.stdout, result.stdout.contains("$expectedLabel.env=true"))
                assertTrue(result.stdout, result.stdout.contains("$expectedLabel.lifecycle=true"))
                assertTrue(result.stdout, result.stdout.contains("$expectedLabel.package_dir=true"))
                assertTrue(result.stdout, result.stdout.contains("$expectedLabel.working_directory=true"))
                assertTrue(result.stdout, result.stdout.contains("$expectedLabel.bin_name=$expectedBinName:true"))
                assertTrue(result.stdout, result.stdout.contains("$expectedLabel.toolchain.npm=true"))
                assertTrue(result.stdout, result.stdout.contains("$expectedLabel.toolchain.config=true"))
                assertTrue(result.stdout, result.stdout.contains("$expectedLabel.toolchain.plugin=true"))
                assertTrue(
                    result.stdout,
                    result.stdout.contains("$expectedLabel.toolchain.discovery=src/index.js|plugins/local.js"),
                )
                assertEquals("package-script", result.nativeValues["embedded_project_runner.kind"])
                assertEquals("package-script", result.nativeValues["embedded_project_runner.launch_kind"])
                assertEquals(corpus.packageDir.canonicalPath, result.nativeValues["embedded_project_runner.package_dir"])
                assertEquals(corpus.workingDirectory.canonicalPath, result.nativeValues["embedded_project_runner.working_directory"])
                assertEquals(expectedEntry.canonicalPath, result.nativeValues["embedded_project_runner.entry_file"])
                assertEquals(expectedBinName, result.nativeValues["embedded_project_runner.bin_name"])
                assertEquals(scriptName, result.nativeValues["embedded_project_runner.script_name"])
                assertEquals("[--from-request, --color]", result.nativeValues["embedded_project_runner.argv"])
                assertEquals("[TOOLCHAIN_REQUEST_ENV]", result.nativeValues["embedded_project_runner.env_keys"])
                assertFalse(result.nativeValues.toString().contains("visible"))
                assertTrue(File(corpus.workingDirectory, "toolchain-$scriptName.json").isFile)
            }

            assertToolchainScript(
                scriptName = "toolchain",
                expectedLabel = "runner.toolchain.script",
                expectedBinName = "@autojs6/toolchain-cli",
                expectedEntry = corpus.scopedCliEntry,
            )
            settleEmbeddedScriptServiceProcess()
            assertToolchainScript(
                scriptName = "toolchain-helper",
                expectedLabel = "runner.toolchain.helper",
                expectedBinName = "toolchain-helper",
                expectedEntry = corpus.helperCliEntry,
            )
            settleEmbeddedScriptServiceProcess()

            val packageBinDir = File(corpus.packageDir, "node_modules/@autojs6/toolchain-cli")
            val packageBinRequest = NativeNodeEmbeddedProjectRunner.PackageBinRequest(
                projectRoot = projectRoot,
                packageDir = packageBinDir,
                binName = "@autojs6/toolchain-cli",
                workingDirectory = corpus.workingDirectory,
                argv = listOf(
                    "--label=runner.toolchain.bin",
                    "--mode=bin",
                    "--from-bin-request",
                    "--expect-entry=packages/toolchain-app/node_modules/@autojs6/toolchain-cli/bin/cli.js",
                    "--expect-cwd=workspace/toolchain-run",
                    "--expect-config=${corpus.configPathFromWorkingDirectory}",
                    "--expect-bin=@autojs6/toolchain-cli",
                    "--expect-request-arg=--from-bin-request",
                    "--expect-env-key=TOOLCHAIN_BIN_ENV",
                    "--color",
                ),
                env = mapOf("TOOLCHAIN_BIN_ENV" to "visible-bin"),
            )
            val packageBinPlan = NativeNodeEmbeddedProjectRunner.resolvePackageBinLaunchPlan(packageBinRequest)
            assertEquals("package-bin", packageBinPlan.kind)
            assertEquals(corpus.scopedCliEntry.canonicalFile, packageBinPlan.entryFile)
            assertEquals(corpus.workingDirectory.canonicalFile, packageBinPlan.workingDirectory)

            val packageBinResult = NativeNodeEmbeddedProjectRunner.runPackageBin(context, packageBinRequest)

            assertTrue(NativeNodeEmbeddedProjectRunner.describe(packageBinRequest, packageBinResult), packageBinResult.succeeded)
            assertTrue(packageBinResult.stdout, packageBinResult.stdout.contains("runner.toolchain.bin.ready=true"))
            assertTrue(packageBinResult.stdout, packageBinResult.stdout.contains("runner.toolchain.bin.argv=true"))
            assertTrue(packageBinResult.stdout, packageBinResult.stdout.contains("runner.toolchain.bin.env=true"))
            assertTrue(packageBinResult.stdout, packageBinResult.stdout.contains("runner.toolchain.bin.bin_name=@autojs6/toolchain-cli:true"))
            assertTrue(packageBinResult.stdout, packageBinResult.stdout.contains("runner.toolchain.bin.toolchain.npm=true"))
            assertTrue(packageBinResult.stdout, packageBinResult.stdout.contains("runner.toolchain.bin.toolchain.config=true"))
            assertTrue(packageBinResult.stdout, packageBinResult.stdout.contains("runner.toolchain.bin.toolchain.plugin=true"))
            assertTrue(
                packageBinResult.stdout,
                packageBinResult.stdout.contains("runner.toolchain.bin.toolchain.discovery=src/index.js|plugins/local.js"),
            )
            assertEquals("package-bin", packageBinResult.nativeValues["embedded_project_runner.kind"])
            assertEquals("package-bin", packageBinResult.nativeValues["embedded_project_runner.launch_kind"])
            assertEquals(packageBinDir.canonicalPath, packageBinResult.nativeValues["embedded_project_runner.package_dir"])
            assertEquals(corpus.workingDirectory.canonicalPath, packageBinResult.nativeValues["embedded_project_runner.working_directory"])
            assertEquals(corpus.scopedCliEntry.canonicalPath, packageBinResult.nativeValues["embedded_project_runner.entry_file"])
            assertEquals("@autojs6/toolchain-cli", packageBinResult.nativeValues["embedded_project_runner.bin_name"])
            assertEquals("[TOOLCHAIN_BIN_ENV]", packageBinResult.nativeValues["embedded_project_runner.env_keys"])
            assertFalse(packageBinResult.nativeValues.toString().contains("visible-bin"))
            assertTrue(File(corpus.workingDirectory, "toolchain-bin.json").isFile)
        } finally {
            projectRoot.deleteRecursively()
        }
    }

