    @Test
    fun packageScriptRunnerRunsNodeRelativeEntry() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-package-script-node-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create package script node dir: $absolutePath" }
        }
        try {
            File(projectRoot, "package.json").writeText(
                """
                {
                  "name": "script-node-root",
                  "version": "2.0.0",
                  "scripts": {
                    "start": "node ./scripts/start.js --from-node"
                  }
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            val entry = File(projectRoot, "scripts/start.js").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText(
                    """
                    "nodejs";
                    const fs = require("fs");
                    const normalizeDataPath = (value) => String(value).replace(/^\/data\/user\/0\//, "/data/data/");
                    const ready =
                      process.argv[0] === "autojs6-node" &&
                      normalizeDataPath(process.argv[1]) === normalizeDataPath(__filename) &&
                      process.argv.includes("--from-node") &&
                      process.argv.includes("--request-node") &&
                      process.env.npm_lifecycle_event === "start" &&
                      process.env.npm_package_name === "script-node-root" &&
                      process.cwd() === ${jsStringLiteral(projectRoot.canonicalPath)} &&
                      require.main === module &&
                      module.parent === null;
                    fs.writeFileSync("./package-script-node.txt", ready ? "ok" : "bad", "utf8");
                    console.log("runner.package_script.node.ready=" + ready);
                    """.trimIndent() + "\n",
                    StandardCharsets.UTF_8,
                )
            }

            val request = NativeNodeEmbeddedProjectRunner.PackageScriptRequest(
                projectRoot = projectRoot,
                packageDir = projectRoot,
                scriptName = "start",
                argv = listOf("--request-node"),
            )
            val result = NativeNodeEmbeddedProjectRunner.runPackageScript(context, request)

            assertTrue(NativeNodeEmbeddedProjectRunner.describe(request, result, entry), result.succeeded)
            assertTrue(result.stdout, result.stdout.contains("runner.package_script.node.ready=true"))
            assertEquals("ok", File(projectRoot, "package-script-node.txt").readText(StandardCharsets.UTF_8))
            val nativeValues = result.nativeValues
            assertEquals("package-script", nativeValues["embedded_project_runner.kind"])
            assertEquals("package-script", nativeValues["embedded_project_runner.launch_kind"])
            assertEquals("", nativeValues["embedded_project_runner.bin_name"])
            assertEquals("start", nativeValues["embedded_project_runner.script_name"])
            assertEquals("node ./scripts/start.js --from-node", nativeValues["embedded_project_runner.script_command"])
            assertEquals("node ./scripts/start.js", nativeValues["embedded_project_runner.resolved_command"])
            assertEquals(entry.canonicalPath, nativeValues["embedded_project_runner.entry_file"])
        } finally {
            projectRoot.deleteRecursively()
        }
    }

