    @Test
    fun packageScriptRunnerRejectsNodeModulesBinResolutionFailures() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-package-script-bin-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create package script bin deny dir: $absolutePath" }
        }
        try {
            val packageDir = File(projectRoot, "packages/app")
            val workspace = File(projectRoot, "workspace").apply {
                check(mkdirs()) { "Failed to create package script bin deny workspace: $absolutePath" }
            }

            fun writeToolPackage(packageName: String, binTarget: String) {
                val toolDir = packageName.split('/').fold(File(packageDir, "node_modules")) { current, part ->
                    File(current, part)
                }.apply {
                    check(mkdirs()) { "Failed to create package script bin deny tool dir: $absolutePath" }
                }
                File(toolDir, "package.json").writeText(
                    JSONObject()
                        .put("name", packageName)
                        .put("version", "1.0.0")
                        .put("bin", JSONObject().put(packageName, binTarget))
                        .toString(),
                    StandardCharsets.UTF_8,
                )
            }

            fun assertRejected(
                scriptCommand: String,
                expectedToken: String,
                prepare: () -> Unit = {},
            ) {
                packageDir.deleteRecursively()
                check(packageDir.mkdirs()) { "Failed to recreate package script bin deny package dir: ${packageDir.absolutePath}" }
                File(packageDir, "package.json").writeText(
                    JSONObject()
                        .put("name", "script-bin-deny-root")
                        .put("version", "1.0.0")
                        .put("scripts", JSONObject().put("bad", scriptCommand))
                        .toString(),
                    StandardCharsets.UTF_8,
                )
                prepare()

                val request = NativeNodeEmbeddedProjectRunner.PackageScriptRequest(
                    projectRoot = projectRoot,
                    packageDir = packageDir,
                    scriptName = "bad",
                    workingDirectory = workspace,
                    argv = listOf("--request"),
                    env = mapOf("SECRET_SHOULD_NOT_PRINT_VALUE" to "secret-value"),
                )
                val failure = runCatching {
                    NativeNodeEmbeddedProjectRunner.runPackageScript(context, request)
                }.exceptionOrNull()

                assertTrue(failure is IllegalArgumentException)
                val message = failure?.message.orEmpty()
                assertTrue(message, message.contains(expectedToken))
                assertTrue(message, message.contains("Node project runner request:"))
                assertTrue(message, message.contains("kind=package-script"))
                assertTrue(message, message.contains("scriptName=bad"))
                assertTrue(message, message.contains("packageDir=${packageDir.canonicalPath}"))
                assertTrue(message, message.contains("workingDirectory=${workspace.canonicalPath}"))
                assertTrue(message, message.contains("argv=[--request]"))
                assertTrue(message, message.contains("envKeys=[SECRET_SHOULD_NOT_PRINT_VALUE]"))
                assertFalse(message, message.contains("secret-value"))
            }

            assertRejected(
                "node_modules/.bin/missing-tool --from-script",
                "Missing package script bin 'missing-tool'",
            )
            assertRejected(
                "node_modules/.bin/@autojs6/missing-tool --from-script",
                "Missing package script bin '@autojs6/missing-tool'",
            )
            assertRejected(
                "node_modules/.bin/@autojs6/broken-tool --from-script",
                "Package bin target missing: ./missing.js",
            ) {
                writeToolPackage("@autojs6/broken-tool", "./missing.js")
            }
            assertRejected(
                "node_modules/.bin/@autojs6/escape-tool --from-script",
                "Package bin target escapes package sandbox: ../escape.js",
            ) {
                writeToolPackage("@autojs6/escape-tool", "../escape.js")
            }
            assertRejected(
                "node_modules/.bin/@autojs6/native-tool --from-script",
                "Unsupported package bin native addon target: ./addon.node",
            ) {
                writeToolPackage("@autojs6/native-tool", "./addon.node")
            }
        } finally {
            projectRoot.deleteRecursively()
        }
    }

    @Test
    fun packageScriptRunnerRejectsShellOperatorsAndDangerousCommands() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-package-script-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create package script deny dir: $absolutePath" }
        }
        try {
            fun assertRejected(command: String, expectedToken: String) {
                File(projectRoot, "package.json").writeText(
                    JSONObject()
                        .put("name", "script-deny-root")
                        .put("version", "1.0.0")
                        .put("scripts", JSONObject().put("bad", command))
                        .toString(),
                    StandardCharsets.UTF_8,
                )
                val request = NativeNodeEmbeddedProjectRunner.PackageScriptRequest(
                    projectRoot = projectRoot,
                    packageDir = projectRoot,
                    scriptName = "bad",
                    argv = listOf("--request"),
                    env = mapOf("SECRET_SHOULD_NOT_PRINT_VALUE" to "secret-value"),
                )
                val failure = runCatching {
                    NativeNodeEmbeddedProjectRunner.runPackageScript(context, request)
                }.exceptionOrNull()

                assertTrue(failure is IllegalArgumentException)
                val message = failure?.message.orEmpty()
                assertTrue(message, message.contains(expectedToken))
                assertTrue(message, message.contains("Node project runner request:"))
                assertTrue(message, message.contains("kind=package-script"))
                assertTrue(message, message.contains("scriptName=bad"))
                assertTrue(message, message.contains("packageDir=${projectRoot.canonicalPath}"))
                assertTrue(message, message.contains("argv=[--request]"))
                assertTrue(message, message.contains("envKeys=[SECRET_SHOULD_NOT_PRINT_VALUE]"))
                assertFalse(message, message.contains("secret-value"))
            }

            assertRejected("direct-bin-tool && echo bad", "shell operators are unsupported")
            assertRejected("direct-bin-tool | other", "shell operators are unsupported")
            assertRejected("npm install", "Unsupported package script command")
            assertRejected("./node_modules/.bin/npm install", "Unsupported package script command")
            assertRejected("node_modules/.bin/corepack enable", "Unsupported package script command")
            assertRejected("node_modules/.bin/../bad", "must be a package bin or node")
            assertRejected("node_modules/.bin/@scope", "must be a package bin or node")
            assertRejected("node_modules/.bin/@scope/../bad", "must be a package bin or node")
            assertRejected("node -e \"1 + 1\"", "Unsupported package script node option")
            assertRejected("FOO=bar direct-bin-tool", "env assignment prefix is unsupported")
        } finally {
            projectRoot.deleteRecursively()
        }
    }

    @Test
    fun packageScriptRunnerIsolatesEnvArgvCwdAndModuleCacheAcrossExecutions() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-package-script-isolation-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create package script isolation dir: $absolutePath" }
        }
        try {
            File(projectRoot, "package.json").writeText(
                """
                {
                  "name": "script-isolation-root",
                  "version": "1.0.0",
                  "scripts": {
                    "state": "state-tool --from-script"
                  }
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            val toolDir = File(projectRoot, "node_modules/state-tool").apply {
                check(mkdirs()) { "Failed to create state package script tool dir: $absolutePath" }
            }
            File(toolDir, "package.json").writeText(
                """{"name":"state-tool","version":"1.0.0","bin":{"state-tool":"./cli.js"}}""",
                StandardCharsets.UTF_8,
            )
            File(toolDir, "cli.js").writeText(
                """
                "nodejs";
                const mutable = require("./mutable");
                console.log("runner.package_script.isolation.argv=" + process.argv.includes("--first"));
                console.log("runner.package_script.isolation.env=" + String(process.env.PKG_SCRIPT_LEAK));
                console.log("runner.package_script.isolation.cwd=" + (process.cwd() === ${jsStringLiteral(projectRoot.canonicalPath)}));
                console.log("runner.package_script.isolation.mutable=" + mutable.value);
                process.env.PKG_SCRIPT_LEAK = "dirty";
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )
            val mutable = File(toolDir, "mutable.js")
            mutable.writeText("""exports.value = "one";""" + "\n", StandardCharsets.UTF_8)

            val firstRequest = NativeNodeEmbeddedProjectRunner.PackageScriptRequest(
                projectRoot = projectRoot,
                packageDir = projectRoot,
                scriptName = "state",
                argv = listOf("--first"),
                env = mapOf("PKG_SCRIPT_LEAK" to "first"),
            )
            val first = NativeNodeEmbeddedProjectRunner.runPackageScript(context, firstRequest)
            assertTrue(NativeNodeEmbeddedProjectRunner.describe(firstRequest, first), first.succeeded)
            assertTrue(first.stdout, first.stdout.contains("runner.package_script.isolation.argv=true"))
            assertTrue(first.stdout, first.stdout.contains("runner.package_script.isolation.env=first"))
            assertTrue(first.stdout, first.stdout.contains("runner.package_script.isolation.cwd=true"))
            assertTrue(first.stdout, first.stdout.contains("runner.package_script.isolation.mutable=one"))

            settleEmbeddedScriptServiceProcess()
            mutable.writeText("""exports.value = "two";""" + "\n", StandardCharsets.UTF_8)

            val secondRequest = NativeNodeEmbeddedProjectRunner.PackageScriptRequest(
                projectRoot = projectRoot,
                packageDir = projectRoot,
                scriptName = "state",
            )
            val second = NativeNodeEmbeddedProjectRunner.runPackageScript(context, secondRequest)
            assertTrue(NativeNodeEmbeddedProjectRunner.describe(secondRequest, second), second.succeeded)
            assertTrue(second.stdout, second.stdout.contains("runner.package_script.isolation.argv=false"))
            assertTrue(second.stdout, second.stdout.contains("runner.package_script.isolation.env=undefined"))
            assertTrue(second.stdout, second.stdout.contains("runner.package_script.isolation.cwd=true"))
            assertTrue(second.stdout, second.stdout.contains("runner.package_script.isolation.mutable=two"))
        } finally {
            projectRoot.deleteRecursively()
        }
    }

    @Test
    fun packageBinObjectFormRunsCliComboProject() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-package-bin-cli-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create package bin cli test dir: $absolutePath" }
        }
        try {
            val toolDir = File(scriptDir, "node_modules/tool").apply {
                check(mkdirs()) { "Failed to create package bin tool dir: $absolutePath" }
            }
            File(scriptDir, "workspace").mkdirs()
            File(scriptDir, "tool.config.json").writeText(
                """{"plugin":"alpha","suffix":"ok"}""",
                StandardCharsets.UTF_8,
            )
            File(toolDir, "package.json").writeText(
                """
                {
                  "name": "tool",
                  "version": "1.0.0",
                  "bin": {
                    "tool": "./cli.js"
                  },
                  "exports": {
                    ".": {
                      "require": "./lib/self.js",
                      "default": "./lib/self.js"
                    }
                  }
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(toolDir, "cli.js").writeText(
                """
                #!/usr/bin/env node
                "nodejs";
                const fs = require("fs");
                const fsp = require("fs/promises");
                const path = require("path");
                const { Buffer } = require("buffer");
                const { createRequire } = require("module");

                function argValue(flag) {
                  const index = process.argv.indexOf(flag);
                  return index >= 0 ? process.argv[index + 1] : undefined;
                }

                async function main() {
                  const configName = argValue("--config");
                  const cliName = argValue("--name");
                  const req = createRequire(__filename);
                  const helper = req("./lib/helper");
                  const helperAgain = require("./lib/helper");
                  const config = JSON.parse(await fsp.readFile(configName, "utf8"));
                  const plugin = require("./plugins/" + config.plugin);
                  const nested = req("nested-dep");
                  const self = require("tool");
                  const argvOk =
                    process.argv[0] === "autojs6-node" &&
                    process.argv[1] === __filename &&
                    process.argv.includes("--config") &&
                    process.argv.includes("tool.config.json") &&
                    cliName === "AutoJs6";
                  const mainOk =
                    require.main === module &&
                    module.parent === null &&
                    module.filename === __filename &&
                    __dirname.replace(/\\/g, "/").endsWith("/node_modules/tool");
                  const cacheOk =
                    helper === helperAgain &&
                    require.cache[req.resolve("./lib/helper")].exports === helper;

                  process.chdir("./workspace");
                  await fsp.writeFile(
                    "./output.txt",
                    Buffer.from([cliName, helper.value, plugin.value, nested.value, self.value, config.suffix].join("|")),
                  );
                  const output = await fsp.readFile("./output.txt", "utf8");
                  process.chdir("..");

                  console.log("cli.combo.ready=" + (
                    argvOk &&
                    mainOk &&
                    cacheOk &&
                    plugin.value === "plugin-alpha" &&
                    nested.value === "nested" &&
                    self.value === "self" &&
                    output === "AutoJs6|helper|plugin-alpha|nested|self|ok" &&
                    fs.existsSync("./workspace/output.txt") &&
                    path.basename(process.cwd()) !== "workspace"
                  ));
                  console.log("cli.argv.ok=" + argvOk);
                  console.log("cli.require_main.ok=" + mainOk);
                  console.log("cli.cache.ok=" + cacheOk);
                  console.log("cli.nested.ok=" + (nested.value === "nested"));
                }

                return main();
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )
            File(toolDir, "lib").mkdirs()
            File(toolDir, "lib/helper.js").writeText(
                """exports.value = "helper";""" + "\n",
                StandardCharsets.UTF_8,
            )
            File(toolDir, "lib/self.js").writeText(
                """exports.value = "self";""" + "\n",
                StandardCharsets.UTF_8,
            )
            File(toolDir, "plugins").mkdirs()
            File(toolDir, "plugins/alpha.js").writeText(
                """exports.value = "plugin-alpha";""" + "\n",
                StandardCharsets.UTF_8,
            )
            File(toolDir, "node_modules/nested-dep").mkdirs()
            File(toolDir, "node_modules/nested-dep/package.json").writeText(
                """{"name":"nested-dep","main":"index.js"}""",
                StandardCharsets.UTF_8,
            )
            File(toolDir, "node_modules/nested-dep/index.js").writeText(
                """exports.value = "nested";""" + "\n",
                StandardCharsets.UTF_8,
            )

            val result = runEmbeddedPackageBin(
                projectDir = scriptDir,
                packageDir = toolDir,
                binName = "tool",
                args = listOf("--config", "tool.config.json", "--name", "AutoJs6"),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("cli.combo.ready=true"))
            assertTrue(result.stdout.contains("cli.argv.ok=true"))
            assertTrue(result.stdout.contains("cli.require_main.ok=true"))
            assertTrue(result.stdout.contains("cli.cache.ok=true"))
            assertTrue(result.stdout.contains("cli.nested.ok=true"))
            assertEquals(
                "AutoJs6|helper|plugin-alpha|nested|self|ok",
                File(scriptDir, "workspace/output.txt").readText(StandardCharsets.UTF_8),
            )
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun packageBinCliCorpusUsesProcessAndConstantsBuiltins() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-package-bin-process-constants-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create package bin process/constants test dir: $absolutePath" }
        }
        try {
            val toolDir = File(scriptDir, "node_modules/process-constants-tool").apply {
                check(mkdirs()) { "Failed to create process/constants tool dir: $absolutePath" }
            }
            File(scriptDir, "workspace").mkdirs()
            File(scriptDir, "tool.config.json").writeText(
                """{"plugin":"alpha","name":"AutoJs6","suffix":"ok"}""",
                StandardCharsets.UTF_8,
            )
            File(toolDir, "package.json").writeText(
                """
                {
                  "name": "process-constants-tool",
                  "version": "1.0.0",
                  "bin": {
                    "process-constants-tool": "./cli.js"
                  },
                  "exports": {
                    ".": {
                      "require": "./lib/self.js",
                      "default": "./lib/self.js"
                    }
                  }
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(toolDir, "cli.js").writeText(
                """
                #!/usr/bin/env node
                "nodejs";
                const fs = require("fs");
                const fsp = require("fs/promises");
                const path = require("path");
                const processBuiltin = require("process");
                const nodeProcessBuiltin = require("node:process");
                const constantsBuiltin = require("constants");
                const nodeConstantsBuiltin = require("node:constants");
                const { Buffer } = require("buffer");
                const { createRequire } = require("module");

                function argValue(flag) {
                  const index = process.argv.indexOf(flag);
                  return index >= 0 ? process.argv[index + 1] : undefined;
                }

                async function main() {
                  const configPath = argValue("--config");
                  const outName = argValue("--out");
                  const cliName = argValue("--name");
                  const config = JSON.parse(await fsp.readFile(configPath, "utf8"));
                  const req = createRequire(__filename);
                  processBuiltin.env.CLI_CORPUS_PLUGIN = config.plugin;
                  const plugin = require("./plugins/" + config.plugin);
                  const pluginPath = require.resolve("./plugins/" + config.plugin);
                  const nested = req("nested-constants-dep");
                  const feature = req("nested-constants-dep/feature");
                  const self = require("process-constants-tool");
                  const processOk =
                    processBuiltin === process &&
                    nodeProcessBuiltin === processBuiltin &&
                    processBuiltin.env === process.env &&
                    processBuiltin.argv === process.argv &&
                    processBuiltin.argv.includes("--color") &&
                    processBuiltin.argv.includes("--config") &&
                    processBuiltin.argv.includes(configPath) &&
                    processBuiltin.argv.includes("--out") &&
                    processBuiltin.argv.includes(outName) &&
                    cliName === config.name;
                  const constantsOk =
                    constantsBuiltin === nodeConstantsBuiltin &&
                    Object.isFrozen(constantsBuiltin) &&
                    constantsBuiltin.fs.F_OK === fs.constants.F_OK &&
                    constantsBuiltin.F_OK === fs.constants.F_OK &&
                    req("constants") === constantsBuiltin &&
                    req("process") === processBuiltin;
                  const mainOk =
                    require.main === module &&
                    module.parent === null &&
                    module.filename === __filename &&
                    __dirname.replace(/\\/g, "/").endsWith("/node_modules/process-constants-tool");

                  processBuiltin.chdir("./workspace");
                  await fsp.writeFile(
                    "./" + outName,
                    Buffer.from([
                      config.name,
                      plugin.value(config),
                      nested.value,
                      feature.value,
                      self.value,
                      path.basename(processBuiltin.cwd()),
                      config.suffix
                    ].join("|"), "utf8"),
                  );
                  const output = await fsp.readFile("./" + outName, "utf8");
                  processBuiltin.chdir("..");

                  const cacheOk =
                    require.cache[pluginPath] &&
                    require.cache[pluginPath].exports === plugin &&
                    require("./plugins/" + config.plugin) === plugin;
                  const outputOk =
                    output === "AutoJs6|alpha:AutoJs6:true|nested-constants|exported-feature|self-exports|workspace|ok" &&
                    fs.existsSync("./workspace/" + outName);
                  const combo = processOk &&
                    constantsOk &&
                    mainOk &&
                    cacheOk &&
                    outputOk &&
                    nested.fs === true &&
                    feature.constants === true &&
                    processBuiltin.cwd().endsWith("/${scriptDir.name}");

                  console.log("cli.process_constants.ready=" + combo);
                  console.log("cli.process_constants.process=" + processOk);
                  console.log("cli.process_constants.constants=" + constantsOk);
                  console.log("cli.process_constants.require_main=" + mainOk);
                  console.log("cli.process_constants.cache=" + cacheOk);
                  console.log("cli.process_constants.output=" + outputOk);
                }

                return main();
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )
            File(toolDir, "lib").mkdirs()
            File(toolDir, "lib/self.js").writeText(
                """exports.value = "self-exports";""" + "\n",
                StandardCharsets.UTF_8,
            )
            File(toolDir, "plugins").mkdirs()
            File(toolDir, "plugins/alpha.js").writeText(
                """
                const processBuiltin = require("process");
                const constantsBuiltin = require("constants");
                const fs = require("fs");
                const { Buffer } = require("buffer");
                exports.value = function(config) {
                  return Buffer.from([
                    processBuiltin.env.CLI_CORPUS_PLUGIN,
                    config.name,
                    constantsBuiltin.F_OK === fs.constants.F_OK
                  ].join(":"), "utf8").toString("utf8");
                };
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )
            val nestedDir = File(toolDir, "node_modules/nested-constants-dep").apply {
                check(mkdirs()) { "Failed to create nested constants dep dir: $absolutePath" }
            }
            File(nestedDir, "package.json").writeText(
                """
                {
                  "name": "nested-constants-dep",
                  "version": "1.0.0",
                  "exports": {
                    ".": "./index.js",
                    "./feature": "./feature.js"
                  }
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(nestedDir, "index.js").writeText(
                """
                const fs = require("fs");
                const constantsBuiltin = require("node:constants");
                exports.value = "nested-constants";
                exports.fs = constantsBuiltin.fs.R_OK === fs.constants.R_OK;
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )
            File(nestedDir, "feature.js").writeText(
                """
                const constantsBuiltin = require("constants");
                exports.value = "exported-feature";
                exports.constants = Object.isFrozen(constantsBuiltin) &&
                  constantsBuiltin.W_OK === require("fs").constants.W_OK;
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )

            val result = runEmbeddedPackageBin(
                projectDir = scriptDir,
                packageDir = toolDir,
                binName = "process-constants-tool",
                args = listOf(
                    "--config",
                    "tool.config.json",
                    "--name",
                    "AutoJs6",
                    "--color",
                    "--out",
                    "output.txt",
                ),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("cli.process_constants.ready=true"))
            assertTrue(result.stdout.contains("cli.process_constants.process=true"))
            assertTrue(result.stdout.contains("cli.process_constants.constants=true"))
            assertTrue(result.stdout.contains("cli.process_constants.require_main=true"))
            assertTrue(result.stdout.contains("cli.process_constants.cache=true"))
            assertTrue(result.stdout.contains("cli.process_constants.output=true"))
            assertEquals(
                "AutoJs6|alpha:AutoJs6:true|nested-constants|exported-feature|self-exports|workspace|ok",
                File(scriptDir, "workspace/output.txt").readText(StandardCharsets.UTF_8),
            )
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun packageBinGlobLiteCorpusRunsOfflinePureJsToolchain() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-package-bin-glob-lite-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create glob-lite package bin test dir: $absolutePath" }
        }
        try {
            val toolDir = writeGlobLiteToolFixture(scriptDir)
            val workspace = File(scriptDir, "workspace").apply {
                check(mkdirs()) { "Failed to create glob-lite workspace dir: $absolutePath" }
            }
            mapOf(
                "src/a/index.js" to "module.exports = 'a';\n",
                "src/a/index.test.js" to "module.exports = 'test';\n",
                "src/a/readme.md" to "# readme\n",
                "src/b/main.js" to "module.exports = 'b';\n",
                "src/b/util.cjs" to "module.exports = 'cjs';\n",
                "src/c/skip.js" to "module.exports = 'skip';\n",
                "lib/tool.js" to "module.exports = 'tool';\n",
                "node_modules/ignored.txt" to "ignored\n",
            ).forEach { (relativePath, content) ->
                File(workspace, relativePath).apply {
                    parentFile?.mkdirs()
                    writeText(content, StandardCharsets.UTF_8)
                }
            }

            val result = runEmbeddedPackageBin(
                projectDir = scriptDir,
                packageDir = toolDir,
                binName = "glob-lite",
                args = listOf(
                    "--cwd",
                    "workspace",
                    "--pattern",
                    "src/{a,b}/**/*.js",
                    "--ignore",
                    "**/*.test.js",
                    "--out",
                    "matches.json",
                    "--json",
                ),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("glob.cli.ready=true"))
            assertTrue(result.stdout.contains("glob.cli.matches=src/a/index.js|src/b/main.js"))
            assertTrue(result.stdout.contains("glob.cli.ignore=true"))
            assertTrue(result.stdout.contains("glob.cli.chdir=true"))
            assertTrue(result.stdout.contains("glob.cli.fs_promises=true"))
            assertTrue(result.stdout.contains("glob.cli.exports=true"))
            assertTrue(result.stdout.contains("glob.cli.nested=true"))
            assertTrue(result.stdout.contains("glob.cli.dynamic=true"))
            assertTrue(result.stdout.contains("glob.cli.cache=true"))
            assertTrue(result.stdout.contains("glob.cli.process_constants=true"))
            assertTrue(result.stdout.contains("glob.cli.dirent=true"))
            assertEquals(
                """{"matches":["src/a/index.js","src/b/main.js"]}""",
                File(workspace, "matches.json").readText(StandardCharsets.UTF_8),
            )
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun packageBinGlobLiteCorpusRejectsUnsafeCwdOutAndMatcher() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-package-bin-glob-lite-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create glob-lite deny test dir: $absolutePath" }
        }
        try {
            val toolDir = writeGlobLiteToolFixture(scriptDir)
            val workspace = File(scriptDir, "workspace/src/a").apply {
                check(mkdirs()) { "Failed to create glob-lite deny workspace dir: $absolutePath" }
            }
            File(workspace, "index.js").writeText("module.exports = true;\n", StandardCharsets.UTF_8)

            val cwdEscape = runEmbeddedPackageBin(
                projectDir = scriptDir,
                packageDir = toolDir,
                binName = "glob-lite",
                args = listOf(
                    "--cwd",
                    "..",
                    "--pattern",
                    "src/**/*.js",
                    "--out",
                    "matches.json",
                ),
            )
            assertFalse(cwdEscape.succeeded)
            assertEquals("EPERM", cwdEscape.errorCode)
            assertTrue(cwdEscape.errorMessage.orEmpty().contains("process.chdir"))

            settleEmbeddedScriptServiceProcess()

            val outEscape = runEmbeddedPackageBin(
                projectDir = scriptDir,
                packageDir = toolDir,
                binName = "glob-lite",
                args = listOf(
                    "--cwd",
                    "workspace",
                    "--pattern",
                    "src/**/*.js",
                    "--out",
                    "../../outside.json",
                ),
            )
            assertFalse(outEscape.succeeded)
            assertTrue(outEscape.errorMessage.orEmpty().contains("Embedded Node scoped fs"))
            assertTrue(outEscape.errorMessage.orEmpty().contains("escapes working directory"))

            settleEmbeddedScriptServiceProcess()

            val matcherEscape = runEmbeddedPackageBin(
                projectDir = scriptDir,
                packageDir = toolDir,
                binName = "glob-lite",
                args = listOf(
                    "--cwd",
                    "workspace",
                    "--pattern",
                    "src/**/*.js",
                    "--matcher",
                    "../../../../../../outside",
                    "--out",
                    "matches.json",
                ),
            )
            assertFalse(matcherEscape.succeeded)
            assertTrue(
                matcherEscape.errorMessage.orEmpty(),
                matcherEscape.errorMessage.orEmpty().contains("escapes") ||
                        matcherEscape.errorMessage.orEmpty().contains("Cannot find module") ||
                        matcherEscape.errorMessage.orEmpty().contains("MODULE_NOT_FOUND"),
            )
        } finally {
            scriptDir.deleteRecursively()
        }
    }

