            val badExportWorkspace = writeDiscoveryWorkspace(
                scriptDir,
                "workspace-bad-export",
                "rc-json",
                plugin = "bad-export-discover-plugin",
            )
            writeBadDiscoveryPluginPackages(badExportWorkspace, includeNative = false)
            val badExport = runDeny(
                badExportWorkspace,
                listOf(
                    "--start",
                    "${badExportWorkspace.name}/packages/app/src/deep",
