            settleEmbeddedScriptServiceProcess()

            val malformedWorkspace = writeDiscoveryWorkspace(scriptDir, "workspace-malformed", "none")
            File(malformedWorkspace, "package.json").writeText(
                """{"name":"malformed","discoverTool":""",
