            assertTrue(missing.errorMessage.orEmpty(), missing.errorMessage.orEmpty().contains("start="))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun packageBinStringAndObjectFormsRunWithIsolatedArgv() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-package-bin-forms-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create package bin forms test dir: $absolutePath" }
        }
        try {
            val stringProject = File(scriptDir, "string-form").apply {
                check(mkdirs()) { "Failed to create string bin form dir: $absolutePath" }
            }
            File(stringProject, "package.json").writeText(
                """{"name":"string-tool","bin":"./cli.js"}""",
                StandardCharsets.UTF_8,
            )
            File(stringProject, "cli.js").writeText(
                """
                #!/usr/bin/env node
                "nodejs";
                console.log("cli.bin.string=" + (
                  require.main === module &&
                  process.argv[0] === "autojs6-node" &&
                  process.argv[1] === __filename &&
                  process.argv.includes("--string")
                ));
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )
            val stringResult = runEmbeddedPackageBin(
                projectDir = stringProject,
                packageDir = stringProject,
                binName = "string-tool",
                args = listOf("--string"),
            )
            assertTrue(stringResult.errorMessage.orEmpty(), stringResult.succeeded)
            assertTrue(stringResult.stdout.contains("cli.bin.string=true"))

            settleEmbeddedScriptServiceProcess()

            val isolated = runEmbeddedScript(
                """
                "nodejs";
                console.log("cli.argv.leak=" + process.argv.includes("--string"));
                """.trimIndent(),
                "<embedded-package-bin-argv-leak-source.js>",
                workingDirectory = stringProject.canonicalPath,
            )
            assertTrue(isolated.errorMessage.orEmpty(), isolated.succeeded)
            assertTrue(isolated.stdout.contains("cli.argv.leak=false"))

            settleEmbeddedScriptServiceProcess()

            val objectProject = File(scriptDir, "object-form").apply {
                check(mkdirs()) { "Failed to create object bin form dir: $absolutePath" }
            }
            File(objectProject, "package.json").writeText(
                """{"name":"object-tool","bin":{"object-tool":"./cli.js","other":"./other.js"}}""",
                StandardCharsets.UTF_8,
            )
            File(objectProject, "cli.js").writeText(
                """
                #!/usr/bin/env node
                "nodejs";
                console.log("cli.bin.object=" + (
                  require.main === module &&
                  module.parent === null &&
                  process.argv.includes("--object")
                ));
                """.trimIndent() + "\n",
                StandardCharsets.UTF_8,
            )
            File(objectProject, "other.js").writeText("""console.log("other");""" + "\n", StandardCharsets.UTF_8)
            val objectResult = runEmbeddedPackageBin(
                projectDir = objectProject,
                packageDir = objectProject,
                binName = "object-tool",
                args = listOf("--object"),
            )
            assertTrue(objectResult.errorMessage.orEmpty(), objectResult.succeeded)
            assertTrue(objectResult.stdout.contains("cli.bin.object=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun packageBinHelperRejectsUnsafeTargetsAndUnsupportedEntries() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-package-bin-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create package bin deny test dir: $absolutePath" }
        }
        try {
            fun packageDir(name: String, packageJson: String, files: Map<String, String> = emptyMap()): File {
                return File(scriptDir, name).apply {
                    check(mkdirs()) { "Failed to create package bin deny case dir: $absolutePath" }
                    File(this, "package.json").writeText(packageJson, StandardCharsets.UTF_8)
                    files.forEach { (relativePath, content) ->
                        File(this, relativePath).apply {
                            parentFile?.mkdirs()
                            writeText(content, StandardCharsets.UTF_8)
                        }
                    }
                }
            }

            assertPackageBinHelperRejects("Missing package bin") {
                val pkg = packageDir("missing-bin", """{"name":"missing-bin"}""")
                runEmbeddedPackageBin(projectDir = pkg, packageDir = pkg, binName = "missing-bin")
            }
            assertPackageBinHelperRejects("Unsupported package bin shape") {
                val pkg = packageDir("unsupported-shape", """{"name":"unsupported-shape","bin":42}""")
                runEmbeddedPackageBin(projectDir = pkg, packageDir = pkg, binName = "unsupported-shape")
            }
            assertPackageBinHelperRejects("Missing package bin entry") {
                val pkg = packageDir("missing-object-entry", """{"name":"missing-object-entry","bin":{"other":"./cli.js"}}""")
                runEmbeddedPackageBin(projectDir = pkg, packageDir = pkg, binName = "missing-object-entry")
            }
            assertPackageBinHelperRejects("escapes package sandbox") {
                val pkg = packageDir("escape", """{"name":"escape","bin":"../outside.js"}""")
                runEmbeddedPackageBin(projectDir = pkg, packageDir = pkg, binName = "escape")
            }
            assertPackageBinHelperRejects("must be relative") {
                val absolutePath = File(scriptDir, "absolute-cli.js").canonicalPath.replace("\\", "\\\\")
                val pkg = packageDir("absolute", """{"name":"absolute","bin":"$absolutePath"}""")
                runEmbeddedPackageBin(projectDir = pkg, packageDir = pkg, binName = "absolute")
            }
            assertPackageBinHelperRejects("contains NUL") {
                val pkg = packageDir("nul", "{\"name\":\"nul\",\"bin\":\"bad\\u0000path\"}")
                runEmbeddedPackageBin(projectDir = pkg, packageDir = pkg, binName = "nul")
            }
            assertPackageBinHelperRejects("native addon") {
                val pkg = packageDir(
                    "native",
                    """{"name":"native","bin":"./cli.node"}""",
                    mapOf("cli.node" to "native"),
                )
                runEmbeddedPackageBin(projectDir = pkg, packageDir = pkg, binName = "native")
            }

            val esmPackage = packageDir(
                "esm",
                """{"name":"esm","bin":"./cli.mjs"}""",
                mapOf("cli.mjs" to "export default 1;\n"),
            )
            val esm = runEmbeddedPackageBin(projectDir = esmPackage, packageDir = esmPackage, binName = "esm")
            assertTrue(esm.errorMessage.orEmpty(), esm.succeeded)
            assertEquals("true", esm.nativeValues["embedded_script.esm_enabled"])
            assertEquals("true", esm.nativeValues["embedded_script.esm_entry"])
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun commonJsLocalModulesSupportExportsJsonAndCache() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-commonjs-direct-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create CommonJS test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const helper = require("./helper");
                    const data = require("./data.json");
                    const counterA = require("./counter");
                    const counterB = require("./counter.js");
                    console.log("helper.answer=" + helper.answer);
                    console.log("helper.extra=" + helper.extra);
                    console.log("data.name=" + data.name);
                    console.log("cache.same=" + (counterA === counterB));
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val helper = File(scriptDir, "helper.js").apply {
                writeText(
                    """
                    exports.answer = 42;
                    module.exports.extra = "extra";
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val data = File(scriptDir, "data.json").apply {
                writeText("""{"name":"embedded-commonjs"}""", StandardCharsets.UTF_8)
            }
            val counter = File(scriptDir, "counter.js").apply {
                writeText(
                    """
                    console.log("counter:load");
                    module.exports = { loaded: true };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(helper, data, counter),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("helper.answer=42"))
            assertTrue(result.stdout.contains("helper.extra=extra"))
            assertTrue(result.stdout.contains("data.name=embedded-commonjs"))
            assertTrue(result.stdout.contains("cache.same=true"))
            assertOccurrenceCount(result.stdout, "counter:load", 1)
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun requireResolveSupportsBuiltinLocalAndNodeModules() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-require-resolve-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create require.resolve test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const path = require("path");
                    console.log("resolve.path=" + require.resolve("path"));
                    console.log("resolve.fs=" + require.resolve("fs"));
                    console.log("resolve.helper=" + path.basename(require.resolve("./helper")));
                    console.log("resolve.pkg=" + require.resolve("resolve-pkg").endsWith("node_modules/resolve-pkg/index.js"));
                    console.log("resolve.subpath=" + require.resolve("resolve-pkg/sub/value").endsWith("node_modules/resolve-pkg/sub/value.js"));
                    console.log("value=" + require("resolve-pkg/sub/value").value);
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val helper = File(scriptDir, "helper.js").apply {
                writeText("""exports.ok = true;""", StandardCharsets.UTF_8)
            }
            val pkgIndex = File(scriptDir, "node_modules/resolve-pkg/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { root: true };""", StandardCharsets.UTF_8)
            }
            val pkgSubpath = File(scriptDir, "node_modules/resolve-pkg/sub/value.js").apply {
                parentFile?.mkdirs()
                writeText("""exports.value = "resolved-subpath";""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(helper, pkgIndex, pkgSubpath),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("resolve.path=path"))
            assertTrue(result.stdout.contains("resolve.fs=fs"))
            assertTrue(result.stdout.contains("resolve.helper=helper.js"))
            assertTrue(result.stdout.contains("resolve.pkg=true"))
            assertTrue(result.stdout.contains("resolve.subpath=true"))
            assertTrue(result.stdout.contains("value=resolved-subpath"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

