    @Test
    fun commonJsModuleResolutionEdgeCasesSupportCacheReloadCyclesModulePathsAndIgnoredPackageFields() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-commonjs-edge-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create CommonJS edge test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const path = require("path");
                    const reloadA = require("./reload");
                    delete require.cache[require.resolve("./reload")];
                    const reloadB = require("./reload");
                    const cycle = require("./cycle/a");
                    const pathsCheck = require("./paths/check");
                    const ignoredFields = require("ignored-fields");
                    console.log("reload.same=" + (reloadA === reloadB));
                    console.log("reload.count=" + reloadB.count);
                    console.log("cycle=" + cycle.name + "/" + cycle.bName + "/" + cycle.bAName + "/" + cycle.bSawADone);
                    console.log("paths.main.hasRoot=" + module.paths.some((item) => item.endsWith("node_modules")));
                    console.log("paths.child.hasNested=" + pathsCheck.hasNested);
                    console.log("paths.child.hasRoot=" + pathsCheck.hasRoot);
                    console.log("paths.child.dirname=" + path.basename(pathsCheck.dirname));
                    console.log("ignored=" + ignoredFields.value);
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val reload = File(scriptDir, "reload.js").apply {
                writeText(
                    """
                    globalThis.__autojs6ReloadCount = (globalThis.__autojs6ReloadCount || 0) + 1;
                    module.exports = { count: globalThis.__autojs6ReloadCount };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val cycleA = File(scriptDir, "cycle/a.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    exports.name = "a";
                    const b = require("./b");
                    exports.bName = b.name;
                    exports.bAName = b.aName;
                    exports.bSawADone = b.aDoneDuringLoad;
                    exports.done = true;
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val cycleB = File(scriptDir, "cycle/b.js").apply {
                writeText(
                    """
                    exports.name = "b";
                    const a = require("./a");
                    exports.aName = a.name;
                    exports.aDoneDuringLoad = a.done === true;
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val pathsCheck = File(scriptDir, "paths/check.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const path = require("path");
                    exports.dirname = __dirname;
                    exports.hasNested = module.paths.some((item) => item.endsWith("paths/node_modules"));
                    exports.hasRoot = module.paths.some((item) => item.endsWith("node_modules"));
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val ignoredFieldsPackageJson = File(scriptDir, "node_modules/ignored-fields/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    {
                      "main": "main.js",
                      "module": "module.js",
                      "browser": "browser.js",
                      "type": "module"
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val ignoredFieldsMain = File(scriptDir, "node_modules/ignored-fields/main.js").apply {
                writeText("""exports.value = "main-field";""", StandardCharsets.UTF_8)
            }
            val ignoredFieldsModule = File(scriptDir, "node_modules/ignored-fields/module.js").apply {
                writeText("""exports.value = "module-field";""", StandardCharsets.UTF_8)
            }
            val ignoredFieldsBrowser = File(scriptDir, "node_modules/ignored-fields/browser.js").apply {
                writeText("""exports.value = "browser-field";""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(
                    reload,
                    cycleA,
                    cycleB,
                    pathsCheck,
                    ignoredFieldsPackageJson,
                    ignoredFieldsMain,
                    ignoredFieldsModule,
                    ignoredFieldsBrowser,
                ),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("reload.same=false"))
            assertTrue(result.stdout.contains("reload.count=2"))
            assertTrue(result.stdout.contains("cycle=a/b/a/false"))
            assertTrue(result.stdout.contains("paths.main.hasRoot=true"))
            assertTrue(result.stdout.contains("paths.child.hasNested=true"))
            assertTrue(result.stdout.contains("paths.child.hasRoot=true"))
            assertTrue(result.stdout.contains("paths.child.dirname=paths"))
            assertTrue(result.stdout.contains("ignored=main-field"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun commonJsCompatibilitySurfaceSupportsModuleRequireExtensionsJsonCacheAndExportsAlias() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-commonjs-surface-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create CommonJS surface test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const path = require("path");
                    const child = require("./child");
                    const childViaModuleRequire = module.require("./child");
                    const jsonA = require("./data.json");
                    const jsonB = require("./data.json");
                    jsonA.mutated = true;
                    delete require.cache[require.resolve("./data.json")];
                    const jsonC = require("./data.json");
                    const reassign = require("./reassign");
                    const alias = require("./alias");
                    const originalExtensions = require.extensions;
                    const originalJsExtension = require.extensions[".js"];
                    try {
                      require.extensions[".js"] = function shouldNotRun() {
                        throw new Error("should-not-run");
                      };
                    } catch (_) {}
                    try {
                      require.extensions = {};
                    } catch (_) {}
                    const extensionChild = require("./extension-child");
                    console.log("main.id.filename=" + (module.id === module.filename));
                    console.log("main.path.dirname=" + (module.path === __dirname));
                    console.log("main.require.function=" + (typeof module.require === "function"));
                    console.log("main.module.require.same=" + (childViaModuleRequire === child));
                    console.log("main.require.main=" + (require.main === module));
                    console.log("main.module.require.main=" + (module.require.main === module));
                    console.log("main.metadata=" + (require.main.filename === __filename) + "/" + (require.main.id === require.main.filename) + "/" + (require.main.path === __dirname));
                    console.log("child.surface=" + child.idMatches + "/" + child.pathMatches + "/" + child.requireIsFunction + "/" + child.requiredSibling + "/" + child.parentIsMain + "/" + child.mainIsEntry + "/" + child.childrenHasSibling);
                    console.log("extensions.shape=" + (typeof require.extensions === "object") + "/" + (typeof require.extensions[".js"] === "function") + "/" + (typeof require.extensions[".cjs"] === "function") + "/" + (typeof require.extensions[".json"] === "function") + "/" + (".node" in require.extensions));
                    console.log("extensions.blocked=" + (require.extensions === originalExtensions) + "/" + (require.extensions[".js"] === originalJsExtension));
                    console.log("extensions.child=" + extensionChild.value);
                    console.log("json.cache.hit=" + (jsonA === jsonB));
                    console.log("json.cache.mutation=" + jsonB.mutated);
                    console.log("json.cache.reload=" + (jsonA !== jsonC) + "/" + Boolean(jsonC.mutated));
                    console.log("exports.reassign=" + (typeof reassign) + "/" + Boolean(reassign.before) + "/" + Boolean(reassign.after));
                    console.log("exports.alias=" + alias.foo + "/" + alias.bar);
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val child = File(scriptDir, "child.js").apply {
                writeText(
                    """
                    const path = require("path");
                    const sibling = module.require("./sibling");
                    exports.idMatches = module.id === module.filename;
                    exports.pathMatches = module.path === __dirname;
                    exports.requireIsFunction = typeof module.require === "function";
                    exports.requiredSibling = sibling.value;
                    exports.parentIsMain = module.parent === require.main;
                    exports.mainIsEntry = require.main !== module;
                    exports.childrenHasSibling = module.children.some((item) => path.basename(item.filename) === "sibling.js");
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val sibling = File(scriptDir, "sibling.js").apply {
                writeText("""exports.value = "sibling";""", StandardCharsets.UTF_8)
            }
            val data = File(scriptDir, "data.json").apply {
                writeText("""{"value":"json"}""", StandardCharsets.UTF_8)
            }
            val reassign = File(scriptDir, "reassign.js").apply {
                writeText(
                    """
                    exports.before = true;
                    module.exports = function named() {};
                    exports.after = true;
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val alias = File(scriptDir, "alias.js").apply {
                writeText(
                    """
                    exports.foo = 1;
                    module.exports.bar = 2;
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val extensionChild = File(scriptDir, "extension-child.js").apply {
                writeText("""module.exports = { value: "extension-child" };""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(child, sibling, data, reassign, alias, extensionChild),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("main.id.filename=true"))
            assertTrue(result.stdout.contains("main.path.dirname=true"))
            assertTrue(result.stdout.contains("main.require.function=true"))
            assertTrue(result.stdout.contains("main.module.require.same=true"))
            assertTrue(result.stdout.contains("main.require.main=true"))
            assertTrue(result.stdout.contains("main.module.require.main=true"))
            assertTrue(result.stdout.contains("main.metadata=true/true/true"))
            assertTrue(result.stdout.contains("child.surface=true/true/true/sibling/true/true/true"))
            assertTrue(result.stdout.contains("extensions.shape=true/true/true/true/false"))
            assertTrue(result.stdout.contains("extensions.blocked=true/true"))
            assertTrue(result.stdout.contains("extensions.child=extension-child"))
            assertTrue(result.stdout.contains("json.cache.hit=true"))
            assertTrue(result.stdout.contains("json.cache.mutation=true"))
            assertTrue(result.stdout.contains("json.cache.reload=true/false"))
            assertTrue(result.stdout.contains("exports.reassign=function/false/false"))
            assertTrue(result.stdout.contains("exports.alias=1/2"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun commonJsErrorsExposeNodeStyleCodesAndJsonModuleSourceNames() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-commonjs-errors-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create CommonJS error test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    function capture(label, fn) {
                      try {
                        fn();
                        console.log(label + "=no-error");
                      } catch (error) {
                        const message = String(error.message).replace(/\s+/g, " ");
                        console.log(label + ".isError=" + (error instanceof Error));
                        console.log(label + ".code=" + error.code);
                        console.log(label + ".message=" + message.slice(0, 240));
                        console.log(label + ".stackHasBadJson=" + String(error.stack || "").includes("bad.json"));
                      }
                    }
                    capture("missing.relative", () => require("./missing"));
                    capture("missing.package", () => require("optional-dep"));
                    capture("missing.subpath", () => require("plain-pkg/missing"));
                    capture("missing.import", () => require("#missing"));
                    capture("exports.missing", () => require("exports-limited/private"));
                    capture("exports.null", () => require("exports-limited/private/secret"));
                    capture("bad.json", () => require("./bad.json"));
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val rootPackageJson = File(scriptDir, "package.json").apply {
                writeText("""{"imports":{}}""", StandardCharsets.UTF_8)
            }
            val plainPackage = File(scriptDir, "node_modules/plain-pkg/index.js").apply {
                parentFile?.mkdirs()
                writeText("""exports.value = "plain";""", StandardCharsets.UTF_8)
            }
            val exportsPackageJson = File(scriptDir, "node_modules/exports-limited/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    {
                      "exports": {
                        ".": "./index.js",
                        "./private/*": null
                      }
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val exportsIndex = File(scriptDir, "node_modules/exports-limited/index.js").apply {
                writeText("""exports.value = "public";""", StandardCharsets.UTF_8)
            }
            val badJson = File(scriptDir, "bad.json").apply {
                writeText("""{"broken":""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(rootPackageJson, plainPackage, exportsPackageJson, exportsIndex, badJson),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            listOf("missing.relative", "missing.package", "missing.subpath").forEach { label ->
                assertTrue(result.stdout.contains("$label.isError=true"))
                assertTrue(result.stdout.contains("$label.code=MODULE_NOT_FOUND"))
                assertTrue(result.stdout.contains("$label.message=Cannot find module"))
            }
            assertTrue(result.stdout, result.stdout.contains("missing.import.isError=true"))
            assertTrue(result.stdout.contains("missing.import.code=ERR_PACKAGE_IMPORT_NOT_DEFINED"))
            assertTrue(result.stdout.contains("exports.missing.isError=true"))
            assertTrue(result.stdout.contains("exports.missing.code=ERR_PACKAGE_PATH_NOT_EXPORTED"))
            assertTrue(result.stdout.contains("exports.null.isError=true"))
            assertTrue(result.stdout.contains("exports.null.code=ERR_PACKAGE_PATH_NOT_EXPORTED"))
            assertTrue(result.stdout.contains("bad.json.isError=true"))
            assertTrue(result.stdout.contains("bad.json.code=undefined"))
            assertTrue(result.stdout.contains("bad.json.message=Invalid Embedded Node JSON module"))
            assertTrue(result.stdout.contains("bad.json.message=") && result.stdout.contains("bad.json"))
            assertTrue(result.stdout.contains("bad.json.stackHasBadJson=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun commonJsResolverDiagnosticsIncludeRequirePackageAndCreateRequireContext() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-commonjs-diagnostics-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create CommonJS diagnostics dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(""""nodejs";""", StandardCharsets.UTF_8)
            }
            val configFile = File(scriptDir, "config/tool.config.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = {};""", StandardCharsets.UTF_8)
            }
            File(scriptDir, "package.json").writeText(
                """{"imports":{"#known":"./known.js"}}""",
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "node_modules/diag-exports/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"exports":{"./blocked":null}}""", StandardCharsets.UTF_8)
            }
            File(scriptDir, "node_modules/diag-main/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"main":"../outside.js"}""", StandardCharsets.UTF_8)
            }
            val needsDgram = File(scriptDir, "node_modules/needs-dgram/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = require("dgram");""", StandardCharsets.UTF_8)
            }
            File(scriptDir, "esm.mjs").writeText("""export default 1;""", StandardCharsets.UTF_8)
            File(scriptDir, "async-esm.mjs").writeText("""export default await Promise.resolve(1);""", StandardCharsets.UTF_8)
            File(scriptDir, "native.node").writeText("native", StandardCharsets.UTF_8)

            fun runFailure(source: String): NativeNodeEmbeddedRuntimeBridge.EmbeddedScriptResult {
                val result = runEmbeddedScript(
                    source = source,
                    sourceName = main.canonicalPath,
                    workingDirectory = scriptDir.canonicalPath,
                )
                assertFalse(result.errorMessage.orEmpty(), result.succeeded)
                settleEmbeddedScriptServiceProcess()
                return result
            }

            fun assertMessageContains(
                result: NativeNodeEmbeddedRuntimeBridge.EmbeddedScriptResult,
                vararg tokens: String,
            ) {
                val message = result.errorMessage.orEmpty()
                tokens.forEach { token ->
                    assertTrue("Expected error message to contain '$token': $message", message.contains(token))
                }
            }

            val missing = runFailure("""const target = "./missing"; require(target);""")
            assertEquals("MODULE_NOT_FOUND", missing.errorCode)
            assertMessageContains(
                missing,
                "Cannot find module './missing'",
                "Embedded Node require diagnostics",
                "request='./missing'",
                "referrer='${main.canonicalPath}'",
                "cwd='${scriptDir.canonicalPath}'",
                "sandboxRoot='${scriptDir.canonicalPath}'",
                "dynamic require fallback",
            )
            assertEquals("./missing", missing.nativeValues["embedded_script.dynamic_require_fallback_last_request"])
            assertEquals(main.canonicalPath, missing.nativeValues["embedded_script.dynamic_require_fallback_last_referrer"])
            assertTrue(
                missing.nativeValues["embedded_script.dynamic_require_fallback_last_candidate"].orEmpty(),
                missing.nativeValues["embedded_script.dynamic_require_fallback_last_candidate"].orEmpty().contains("missing"),
            )

            val escape = runFailure("""const target = "../outside"; require(target);""")
            assertMessageContains(
                escape,
                "Relative require escapes Embedded Node working directory",
                "request='../outside'",
                "dynamic require fallback denied",
            )
            assertTrue(
                escape.nativeValues["embedded_script.dynamic_require_fallback_last_denied_reason"].orEmpty(),
                escape.nativeValues["embedded_script.dynamic_require_fallback_last_denied_reason"].orEmpty()
                    .contains("dynamic require fallback denied"),
            )

            val exportsBlocked = runFailure("""require("diag-exports/blocked");""")
            assertEquals("ERR_PACKAGE_PATH_NOT_EXPORTED", exportsBlocked.errorCode)
            assertMessageContains(
                exportsBlocked,
                "package subpath is not exported",
                "diag-exports",
                "package.json",
                "request='./blocked'",
                "target=null",
            )

            val importsMissing = runFailure("""require("#missing");""")
            assertEquals("ERR_PACKAGE_IMPORT_NOT_DEFINED", importsMissing.errorCode)
            assertMessageContains(
                importsMissing,
                "imports does not define alias '#missing'",
                "package.json",
                "field='imports'",
                "request='#missing'",
            )

            val unsafeMain = runFailure("""require("diag-main");""")
            assertMessageContains(
                unsafeMain,
                "Package main escapes Embedded Node package directory",
                "diag-main",
                "package.json",
                "field='main'",
                "target='../outside.js'",
            )

            val createRequireMissing = runFailure(
                """const req = require("module").createRequire("./config/tool.config.js"); req("missing-plugin");""",
            )
            assertEquals("MODULE_NOT_FOUND", createRequireMissing.errorCode)
            assertMessageContains(
                createRequireMissing,
                "missing-plugin",
                "Embedded Node require diagnostics",
                "request='missing-plugin'",
                "referrer='${configFile.canonicalPath}'",
            )

            val createRequireEscape = runFailure("""require("module").createRequire("../outside.js");""")
            assertMessageContains(createRequireEscape, "module.createRequire", "base escapes sandboxRoot", "../outside.js")
            assertTrue(
                createRequireEscape.nativeValues["embedded_script.create_require_failure_reason"].orEmpty(),
                createRequireEscape.nativeValues["embedded_script.create_require_failure_reason"].orEmpty()
                    .contains("base escapes sandboxRoot"),
            )

            val disabledBuiltin = runFailure("""require("needs-dgram");""")
            assertEquals("ERR_AUTOJS6_EMBEDDED_NODE_BUILTIN_DISABLED", disabledBuiltin.errorCode)
            assertMessageContains(
                disabledBuiltin,
                "builtin module 'dgram' is not allowed",
                "request='dgram'",
                "referrer='${needsDgram.canonicalPath}'",
            )

            val esm = runEmbeddedScript(
                source = """const target = "./esm.mjs"; console.log("diagnostics.esm.default=" + require(target).default);""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )
            assertTrue(esm.errorMessage.orEmpty(), esm.succeeded)
            assertTrue(esm.stdout.contains("diagnostics.esm.default=1"))
            settleEmbeddedScriptServiceProcess()

            val asyncEsm = runFailure("""const target = "./async-esm.mjs"; require(target);""")
            assertEquals("ERR_REQUIRE_ASYNC_MODULE", asyncEsm.errorCode)
            assertMessageContains(asyncEsm, "cannot synchronously load", "./async-esm.mjs", "request='./async-esm.mjs'")

            val native = runFailure("""const target = "./native.node"; require(target);""")
            assertMessageContains(native, "Unsupported Embedded Node local module extension", "./native.node", "request='./native.node'")
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun commonJsDynamicFallbackDiagnosticsIncludeCandidatesAndBudgetDetails() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-dynamic-fallback-diagnostics-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create dynamic fallback diagnostics dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(""""nodejs";""", StandardCharsets.UTF_8)
            }
            val extra = File(scriptDir, "extra.js").apply {
                writeText("""module.exports = true;""", StandardCharsets.UTF_8)
            }
            val maxCountSources = (0 until moduleSourceMaxCount).associate { index ->
                "${scriptDir.canonicalPath}/preloaded-$index.js" to "module.exports = $index;"
            }
            val tooMany = runEmbeddedScript(
                source = """const target = "./extra"; require(target);""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = maxCountSources,
            )
            assertFalse(tooMany.errorMessage.orEmpty(), tooMany.succeeded)
            assertTrue(tooMany.errorMessage.orEmpty().contains("dynamic require fallback"))
            assertTrue(tooMany.errorMessage.orEmpty().contains("module source count is too large"))
            assertTrue(tooMany.errorMessage.orEmpty().contains("$moduleSourceOverLimitCount > $moduleSourceMaxCount"))
            assertTrue(tooMany.errorMessage.orEmpty().contains("request='./extra'"))
            assertEquals("./extra", tooMany.nativeValues["embedded_script.dynamic_require_fallback_last_request"])
            assertEquals(main.canonicalPath, tooMany.nativeValues["embedded_script.dynamic_require_fallback_last_referrer"])
            assertEquals(extra.canonicalPath, tooMany.nativeValues["embedded_script.dynamic_require_fallback_last_candidate"])
            assertTrue(
                tooMany.nativeValues["embedded_script.dynamic_require_fallback_last_denied_reason"].orEmpty(),
                tooMany.nativeValues["embedded_script.dynamic_require_fallback_last_denied_reason"].orEmpty()
                    .contains("$moduleSourceOverLimitCount > $moduleSourceMaxCount"),
            )

            settleEmbeddedScriptServiceProcess()

            val big = File(scriptDir, "big.js").apply {
                writeText("x".repeat(moduleSourceOverLimitBytes), StandardCharsets.UTF_8)
            }
            val singleTooLarge = runEmbeddedScript(
                source = """const target = "./big"; require(target);""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )
            assertFalse(singleTooLarge.errorMessage.orEmpty(), singleTooLarge.succeeded)
            assertTrue(singleTooLarge.errorMessage.orEmpty().contains("dynamic require fallback module source is too large"))
            assertTrue(
                singleTooLarge.errorMessage.orEmpty()
                    .contains("$moduleSourceOverLimitBytes bytes > $moduleSourceMaxBytes bytes"),
            )
            assertTrue(singleTooLarge.errorMessage.orEmpty().contains("request='./big'"))
            assertEquals("./big", singleTooLarge.nativeValues["embedded_script.dynamic_require_fallback_last_request"])
            assertEquals(main.canonicalPath, singleTooLarge.nativeValues["embedded_script.dynamic_require_fallback_last_referrer"])
            assertEquals(big.canonicalPath, singleTooLarge.nativeValues["embedded_script.dynamic_require_fallback_last_candidate"])
            assertTrue(
                singleTooLarge.nativeValues["embedded_script.dynamic_require_fallback_last_denied_reason"].orEmpty(),
                singleTooLarge.nativeValues["embedded_script.dynamic_require_fallback_last_denied_reason"].orEmpty()
                    .contains("$moduleSourceOverLimitBytes bytes > $moduleSourceMaxBytes bytes"),
            )
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun commonJsResolverHardeningCoversPriorityFallbackShadowingAndScopedSpecifierEdges() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-commonjs-resolver-hardening-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create CommonJS resolver hardening dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    function capture(label, fn) {
                      try {
                        fn();
                        console.log(label + "=no-error");
                      } catch (error) {
                        const message = String(error.message).replace(/\s+/g, " ");
                        console.log(label + ".code=" + error.code);
                        console.log(label + ".message=" + message.slice(0, 240));
                      }
                    }
                    const path = require("path");
                    const fs = require("fs");
                    console.log("priority.file=" + require("./dual").kind);
                    console.log("priority.main=" + require("main-priority").kind);
                    console.log("priority.index=" + require("./index-priority").kind);
                    console.log("main.fallback=" + require("main-fallback").kind);
                    console.log("exports.priority=" + require("exports-priority").kind);
                    console.log("builtin.path=" + path.join("a", "b"));
                    console.log("builtin.nodePath=" + require("node:path").basename("/tmp/value.txt"));
                    console.log("builtin.fs=" + (typeof fs.readFileSync));
                    console.log("scoped.root=" + require("@scope/pkg").kind);
                    console.log("scoped.sub=" + require("@scope/pkg/sub").kind);
                    capture("main.unsafe", () => require("main-unsafe"));
                    capture("main.native", () => require("main-native"));
                    capture("exports.noFallback", () => require("exports-priority/private"));
                    capture("scoped.only", () => require("@scope"));
                    capture("scoped.empty", () => require("@scope/"));
                    capture("scoped.escape", () => require("@scope/pkg/../escape"));
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val dualJs = File(scriptDir, "dual.js").apply {
                writeText("""exports.kind = "js";""", StandardCharsets.UTF_8)
            }
            val dualJson = File(scriptDir, "dual.json").apply {
                writeText("""{"kind":"json"}""", StandardCharsets.UTF_8)
            }
            val indexJs = File(scriptDir, "index-priority/index.js").apply {
                parentFile?.mkdirs()
                writeText("""exports.kind = "index-js";""", StandardCharsets.UTF_8)
            }
            val indexJson = File(scriptDir, "index-priority/index.json").apply {
                writeText("""{"kind":"index-json"}""", StandardCharsets.UTF_8)
            }
            val mainPriorityPackageJson = File(scriptDir, "node_modules/main-priority/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"main":"entry"}""", StandardCharsets.UTF_8)
            }
            val mainPriorityJs = File(scriptDir, "node_modules/main-priority/entry.js").apply {
                writeText("""exports.kind = "main-js";""", StandardCharsets.UTF_8)
            }
            val mainPriorityJson = File(scriptDir, "node_modules/main-priority/entry.json").apply {
                writeText("""{"kind":"main-json"}""", StandardCharsets.UTF_8)
            }
            val mainFallbackPackageJson = File(scriptDir, "node_modules/main-fallback/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"main":"missing.js"}""", StandardCharsets.UTF_8)
            }
            val mainFallbackIndex = File(scriptDir, "node_modules/main-fallback/index.js").apply {
                writeText("""exports.kind = "index-fallback";""", StandardCharsets.UTF_8)
            }
            val mainUnsafePackageJson = File(scriptDir, "node_modules/main-unsafe/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"main":"../outside.js"}""", StandardCharsets.UTF_8)
            }
            val mainUnsafeIndex = File(scriptDir, "node_modules/main-unsafe/index.js").apply {
                writeText("""exports.kind = "should-not-fallback";""", StandardCharsets.UTF_8)
            }
            val mainNativePackageJson = File(scriptDir, "node_modules/main-native/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"main":"native.node"}""", StandardCharsets.UTF_8)
            }
            val mainNativeIndex = File(scriptDir, "node_modules/main-native/index.js").apply {
                writeText("""exports.kind = "should-not-fallback";""", StandardCharsets.UTF_8)
            }
            val exportsPriorityPackageJson = File(scriptDir, "node_modules/exports-priority/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"main":"main.js","exports":"./exports.js"}""", StandardCharsets.UTF_8)
            }
            val exportsPriorityMain = File(scriptDir, "node_modules/exports-priority/main.js").apply {
                writeText("""exports.kind = "main";""", StandardCharsets.UTF_8)
            }
            val exportsPriorityExports = File(scriptDir, "node_modules/exports-priority/exports.js").apply {
                writeText("""exports.kind = "exports";""", StandardCharsets.UTF_8)
            }
            val exportsPriorityPrivate = File(scriptDir, "node_modules/exports-priority/private.js").apply {
                writeText("""exports.kind = "private";""", StandardCharsets.UTF_8)
            }
            val pathShadow = File(scriptDir, "node_modules/path/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { join: () => "shadow-path" };""", StandardCharsets.UTF_8)
            }
            val fsShadow = File(scriptDir, "node_modules/fs/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { readFileSync: "shadow-fs" };""", StandardCharsets.UTF_8)
            }
            val scopedRoot = File(scriptDir, "node_modules/@scope/pkg/index.js").apply {
                parentFile?.mkdirs()
                writeText("""exports.kind = "scoped-root";""", StandardCharsets.UTF_8)
            }
            val scopedSub = File(scriptDir, "node_modules/@scope/pkg/sub.js").apply {
                writeText("""exports.kind = "scoped-sub";""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(
                    dualJs,
                    dualJson,
                    indexJs,
                    indexJson,
                    mainPriorityPackageJson,
                    mainPriorityJs,
                    mainPriorityJson,
                    mainFallbackPackageJson,
                    mainFallbackIndex,
                    mainUnsafePackageJson,
                    mainUnsafeIndex,
                    mainNativePackageJson,
                    mainNativeIndex,
                    exportsPriorityPackageJson,
                    exportsPriorityMain,
                    exportsPriorityExports,
                    exportsPriorityPrivate,
                    pathShadow,
                    fsShadow,
                    scopedRoot,
                    scopedSub,
                ),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("priority.file=js"))
            assertTrue(result.stdout.contains("priority.main=main-js"))
            assertTrue(result.stdout.contains("priority.index=index-js"))
            assertTrue(result.stdout.contains("main.fallback=index-fallback"))
            assertTrue(result.stdout.contains("exports.priority=exports"))
            assertTrue(result.stdout.contains("builtin.path=a/b") || result.stdout.contains("builtin.path=a\\b"))
            assertTrue(result.stdout.contains("builtin.nodePath=value.txt"))
            assertTrue(result.stdout.contains("builtin.fs=function"))
            assertTrue(result.stdout.contains("scoped.root=scoped-root"))
            assertTrue(result.stdout.contains("scoped.sub=scoped-sub"))
            assertTrue(result.stdout.contains("main.unsafe.code=ERR_INVALID_PACKAGE_TARGET"))
            assertTrue(
                result.stdout,
                result.stdout.contains("main.native.code=${NodeRuntimeErrorCodes.NATIVE_ADDON_DISABLED}"),
            )
            assertTrue(result.stdout.contains("exports.noFallback.code=ERR_PACKAGE_PATH_NOT_EXPORTED"))
            assertTrue(result.stdout, result.stdout.contains("scoped.only.message=Invalid Embedded Node scoped package specifier"))
            assertTrue(result.stdout, result.stdout.contains("scoped.empty.message=Invalid Embedded Node package specifier"))
            assertTrue(result.stdout, result.stdout.contains("scoped.escape.message=Embedded Node node_modules package subpath escapes working directory"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun commonJsPreloaderHandlesMediumModuleGraphAndDeduplicatesSharedTargets() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-commonjs-preloader-scale-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create CommonJS preloader scale dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const fan = [
                      require("./fan/0"),
                      require("./fan/1"),
                      require("./fan/2"),
                      require("./fan/3"),
                      require("./fan/4")
                    ];
                    const dedupeRoot = require("dedupe-pkg");
                    const dedupeSame = require("dedupe-pkg/same");
                    const dedupeImport = require("dedupe-pkg/uses-import");
                    const chainTotal = require("./chain/0");
                    const jsonA = require("./config/a.json");
                    const jsonB = require("./config/b.json");
                    if (chainTotal !== 48) {
                      throw new Error("chain mismatch: " + chainTotal);
                    }
                    if (jsonA.kind !== "a" || jsonB.count !== 2) {
                      throw new Error("json mismatch");
                    }
                    console.log("chain.total=" + chainTotal);
                    console.log("json.graph=" + jsonA.kind + "/" + jsonB.count);
                    console.log("fan.same=" + fan.every((item) => item === fan[0]));
                    console.log("fan.count=" + fan[0].count);
                    console.log("nested=" + require("nest-0"));
                    console.log("dedupe.same=" + (dedupeRoot === dedupeSame));
                    console.log("dedupe.import=" + (dedupeImport.same === dedupeRoot) + "/" + (dedupeImport.self === dedupeRoot));
                    console.log("dedupe.count=" + globalThis.__autojs6DedupePackageCount);
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            (0 until 48).forEach { index ->
                File(scriptDir, "chain/$index.js").apply {
                    parentFile?.mkdirs()
                    writeText(
                        if (index == 47) {
                            """module.exports = 1;"""
                        } else {
                            """module.exports = 1 + require("./${index + 1}");"""
                        },
                        StandardCharsets.UTF_8,
                    )
                }
            }
            File(scriptDir, "fan/shared.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    globalThis.__autojs6FanSharedCount = (globalThis.__autojs6FanSharedCount || 0) + 1;
                    module.exports = { value: "shared", count: globalThis.__autojs6FanSharedCount };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            (0 until 5).forEach { index ->
                File(scriptDir, "fan/$index.js").writeText("""module.exports = require("./shared");""", StandardCharsets.UTF_8)
            }
            (0 until 5).forEach { index ->
                var packageDir = File(scriptDir, "node_modules/nest-0")
                (1..index).forEach { nestedIndex ->
                    packageDir = File(packageDir, "node_modules/nest-$nestedIndex")
                }
                val file = File(packageDir, "index.js")
                file.parentFile?.mkdirs()
                file.writeText(
                    if (index == 4) {
                        """module.exports = "nest-4";"""
                    } else {
                        """module.exports = "nest-$index+" + require("nest-${index + 1}");"""
                    },
                    StandardCharsets.UTF_8,
                )
            }
            File(scriptDir, "config/a.json").apply {
                parentFile?.mkdirs()
                writeText("""{"kind":"a"}""", StandardCharsets.UTF_8)
            }
            File(scriptDir, "config/b.json").writeText("""{"count":2}""", StandardCharsets.UTF_8)
            File(scriptDir, "node_modules/dedupe-pkg/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    {
                      "name": "dedupe-pkg",
                      "exports": {
                        ".": "./shared.js",
                        "./same": "./shared.js",
                        "./uses-import": "./uses-import.js"
                      },
                      "imports": {
                        "#same": "./shared.js"
                      }
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            File(scriptDir, "node_modules/dedupe-pkg/shared.js").writeText(
                """
                globalThis.__autojs6DedupePackageCount = (globalThis.__autojs6DedupePackageCount || 0) + 1;
                module.exports = { count: globalThis.__autojs6DedupePackageCount };
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "node_modules/dedupe-pkg/uses-import.js").writeText(
                """
                exports.same = require("#same");
                exports.self = require("dedupe-pkg/same");
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )

            val engine = NativeNodeEmbeddedJavaScriptEngine(context)
            assertEquals(0, engine.doExecution(JavaScriptFileSource(main)))
            val diagnostics = engine.lastCommonJsPreloadDiagnostics
            assertEquals(64, diagnostics.moduleCount)
            assertEquals(1, diagnostics.packageJsonCount)
            assertEquals(2, diagnostics.jsonModuleCount)
            assertEquals(48, diagnostics.maxDepth)
            assertTrue("Expected shared module duplicates", diagnostics.duplicateSkippedCount > 0)
            assertTrue("Expected static require scan count", diagnostics.staticRequireCount >= 70)
            assertEquals(0, diagnostics.dynamicRequireIgnoredCount)
            assertEquals(0, diagnostics.unresolvedStaticRequireCount)
            assertTrue("Expected preloaded source bytes", diagnostics.totalSourceBytes > 0)
            assertTrue(
                diagnostics.moduleSourceNames.any {
                    it.replace('\\', '/').endsWith("/node_modules/dedupe-pkg/shared.js")
                },
            )
        } finally {
            runCatching { RhinoContext.exit() }
            scriptDir.deleteRecursively()
        }
    }

