    @Test
    fun fileEnginePreloaderRejectsGraphOverModuleSourceLimitWithDiagnostics() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-commonjs-preloader-limit-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create CommonJS preloader limit dir: $absolutePath" }
        }
        val main = File(scriptDir, "main.js")
        try {
            main.writeText(
                """
                "nodejs";
                require("./chain/0");
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            (0 until moduleSourceOverLimitCount).forEach { index ->
                File(scriptDir, "chain/$index.js").apply {
                    parentFile?.mkdirs()
                    writeText(
                        if (index == moduleSourceMaxCount) {
                            """module.exports = 1;"""
                        } else {
                            """module.exports = require("./${index + 1}") + 1;"""
                        },
                        StandardCharsets.UTF_8,
                    )
                }
            }

            val engine = NativeNodeEmbeddedJavaScriptEngine(context)
            val failure = runCatching { engine.doExecution(JavaScriptFileSource(main)) }.exceptionOrNull()
            assertTrue("Expected pre-service module source limit rejection", failure != null)
            val message = failure?.message.orEmpty()
            assertTrue(message, message.contains(NodeRuntimeErrorCodes.MODULE_SOURCE_BUDGET_EXCEEDED))
            assertTrue(message, message.contains("module source count is too large"))
            assertTrue(message, message.contains("$moduleSourceOverLimitCount > $moduleSourceMaxCount"))

            val diagnostics = engine.lastCommonJsPreloadDiagnostics
            assertEquals(moduleSourceOverLimitCount, diagnostics.moduleCount)
            assertEquals(moduleSourceOverLimitCount, diagnostics.maxDepth)
            assertEquals(moduleSourceOverLimitCount, diagnostics.staticRequireCount)
            assertEquals(0, diagnostics.dynamicRequireIgnoredCount)
            assertEquals(0, diagnostics.unresolvedStaticRequireCount)
        } finally {
            runCatching { RhinoContext.exit() }
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun embeddedScriptModuleSourcesLimitsAreRejectedBeforeServiceStart() {
        assumeEmbeddedScriptExecutionEnabled()

        val withinBudgetModule = File(context.cacheDir, "embedded-module-budget-within.js")
        val withinBudget = runEmbeddedScript(
            source = """
                "nodejs";
                console.log("moduleSources.budget.within=" + require("./embedded-module-budget-within"));
            """.trimIndent(),
            sourceName = "<embedded-module-budget-within-source.js>",
            moduleSources = mapOf(withinBudgetModule.absolutePath to "module.exports = 42;"),
        )
        assertTrue(withinBudget.errorMessage.orEmpty(), withinBudget.succeeded)
        assertTrue(withinBudget.stdout, withinBudget.stdout.contains("moduleSources.budget.within=42"))

        settleEmbeddedScriptServiceProcess()

        val tooManySources = (0 until moduleSourceOverLimitCount).associate { index ->
            "${context.cacheDir.absolutePath}/embedded-module-limit-$index.js" to "module.exports = $index;"
        }
        val tooManySourceBytes = tooManySources.values.map { it.toByteArray(StandardCharsets.UTF_8).size }
        val tooMany = runEmbeddedScript(
            source = """"nodejs";""",
            sourceName = "<embedded-module-count-limit-source.js>",
            moduleSources = tooManySources,
        )
        assertFalse(tooMany.succeeded)
        assertEquals("EmbeddedScriptExecutionError", tooMany.errorName)
        assertEquals(NodeRuntimeErrorCodes.MODULE_SOURCE_BUDGET_EXCEEDED, tooMany.errorCode)
        assertTrue(tooMany.errorMessage.orEmpty().contains("module source count is too large"))
        assertTrue(tooMany.errorMessage.orEmpty().contains("$moduleSourceOverLimitCount > $moduleSourceMaxCount"))
        assertEquals("count", tooMany.nativeValues["embedded_script.module_sources.budget.exceeded"])
        assertEquals(moduleSourceOverLimitCount.toString(), tooMany.nativeValues["embedded_script.module_sources.count"])
        assertEquals(moduleSourceMaxCount.toString(), tooMany.nativeValues["embedded_script.module_sources.max_count"])
        assertEquals(tooManySourceBytes.sum().toString(), tooMany.nativeValues["embedded_script.module_sources.total_bytes"])
        assertEquals(tooManySourceBytes.maxOrNull().toString(), tooMany.nativeValues["embedded_script.module_sources.largest.bytes"])
        assertTrue(
            tooMany.nativeValues["embedded_script.module_sources.largest.name"].orEmpty(),
            tooMany.nativeValues["embedded_script.module_sources.largest.name"].orEmpty().contains("embedded-module-limit-"),
        )

        val singleTooLarge = runEmbeddedScript(
            source = """"nodejs";""",
            sourceName = "<embedded-module-single-limit-source.js>",
            moduleSources = mapOf("${context.cacheDir.absolutePath}/single-too-large.js" to "x".repeat(moduleSourceOverLimitBytes)),
        )
        assertFalse(singleTooLarge.succeeded)
        assertEquals("EmbeddedScriptExecutionError", singleTooLarge.errorName)
        assertEquals(NodeRuntimeErrorCodes.MODULE_SOURCE_BUDGET_EXCEEDED, singleTooLarge.errorCode)
        assertTrue(singleTooLarge.errorMessage.orEmpty().contains("module source is too large"))
        assertTrue(
            singleTooLarge.errorMessage.orEmpty()
                .contains("$moduleSourceOverLimitBytes bytes > $moduleSourceMaxBytes bytes"),
        )
        assertEquals("per-module", singleTooLarge.nativeValues["embedded_script.module_sources.budget.exceeded"])
        assertEquals(moduleSourceOverLimitBytes.toString(), singleTooLarge.nativeValues["embedded_script.module_sources.largest.bytes"])
        assertEquals(moduleSourceOverLimitBytes.toString(), singleTooLarge.nativeValues["embedded_script.module_sources.total_bytes"])
        assertTrue(
            singleTooLarge.nativeValues["embedded_script.module_sources.largest.name"].orEmpty(),
            singleTooLarge.nativeValues["embedded_script.module_sources.largest.name"].orEmpty().contains("single-too-large.js"),
        )

        val totalTooLarge = runEmbeddedScript(
            source = """"nodejs";""",
            sourceName = "<embedded-module-total-limit-source.js>",
            moduleSources = buildMap {
                var total = 0
                var index = 0
                while (total <= moduleSourcesMaxBytes) {
                    val bytes = minOf(moduleSourceMaxBytes - 1, moduleSourcesMaxBytes - total + 1)
                    put("${context.cacheDir.absolutePath}/total-$index.js", "x".repeat(bytes))
                    total += bytes
                    index += 1
                }
            },
        )
        val totalTooLargeBytes = totalTooLarge.nativeValues["embedded_script.module_sources.total_bytes"].orEmpty()
        assertFalse(totalTooLarge.succeeded)
        assertEquals("EmbeddedScriptExecutionError", totalTooLarge.errorName)
        assertEquals(NodeRuntimeErrorCodes.MODULE_SOURCE_BUDGET_EXCEEDED, totalTooLarge.errorCode)
        assertTrue(totalTooLarge.errorMessage.orEmpty().contains("module sources are too large"))
        assertTrue(totalTooLarge.errorMessage.orEmpty().contains("$totalTooLargeBytes bytes > $moduleSourcesMaxBytes bytes"))
        assertEquals("total", totalTooLarge.nativeValues["embedded_script.module_sources.budget.exceeded"])
        assertTrue(totalTooLargeBytes.toInt() > moduleSourcesMaxBytes)
        assertEquals((moduleSourceMaxBytes - 1).toString(), totalTooLarge.nativeValues["embedded_script.module_sources.largest.bytes"])
    }

    @Test
    fun commonJsPackageResolutionRejectsUnsafePackageMain() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-commonjs-package-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create CommonJS package deny test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(""""nodejs";""", StandardCharsets.UTF_8)
            }
            val escapePackageJson = File(scriptDir, "escape/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"main":"../outside.js"}""", StandardCharsets.UTF_8)
            }
            File(scriptDir, "outside.js").writeText("""module.exports = {};""", StandardCharsets.UTF_8)

            val escape = runEmbeddedScript(
                source = """require("./escape");""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(escapePackageJson),
            )
            assertFalse(escape.succeeded)
            assertEquals("Error", escape.errorName)
            assertTrue(escape.errorMessage.orEmpty().contains("Package main escapes Embedded Node package directory"))
            assertTrue(escape.errorMessage.orEmpty().contains("../outside.js"))

            settleEmbeddedScriptServiceProcess()

            val nativePackageJson = File(scriptDir, "native/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"main":"native.node"}""", StandardCharsets.UTF_8)
            }
            val unsupported = runEmbeddedScript(
                source = """require("./native");""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(nativePackageJson),
            )
            assertFalse(unsupported.succeeded)
            assertEquals("Error", unsupported.errorName)
            assertTrue(unsupported.errorMessage.orEmpty().contains("Unsupported Embedded Node package main extension"))
            assertTrue(unsupported.errorMessage.orEmpty().contains("native.node"))

            settleEmbeddedScriptServiceProcess()

            val absolutePackageJson = File(scriptDir, "absolute/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"main":"/sdcard/package-main.js"}""", StandardCharsets.UTF_8)
            }
            val absolute = runEmbeddedScript(
                source = """require("./absolute");""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(absolutePackageJson),
            )
            assertFalse(absolute.succeeded)
            assertEquals("Error", absolute.errorName)
            assertTrue(absolute.errorMessage.orEmpty().contains("rejects absolute path"))
            assertTrue(absolute.errorMessage.orEmpty().contains("/sdcard/package-main.js"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun commonJsDynamicRequireFallbackLoadsScopedProjectFilesAndCaches() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-dynamic-require-local-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create dynamic require fallback test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const childName = "./dynamic-child";
                    const concatName = "./" + "concat-child";
                    const jsonName = "./data.json";
                    const dirName = "./dynamic-dir";
                    const cjsName = "./dynamic-cjs";
                    const childA = require(childName);
                    const childB = require(childName);
                    const concat = require(concatName);
                    const data = require(jsonName);
                    const dir = require(dirName);
                    const cjs = require(cjsName);
                    const childResolved = require.resolve(childName);
                    console.log("fallback.local.result=" + [childA.value, concat.value, data.name, dir.kind, cjs.kind].join("/"));
                    console.log("fallback.local.cache=" + (childA === childB));
                    console.log("fallback.local.cache_entry=" + Boolean(require.cache[childResolved]));
                    console.log("fallback.local.children=" + module.children.some((item) => item.filename.endsWith("dynamic-child.js")));
                    console.log("fallback.local.load_count=" + globalThis.__autojs6DynamicFallbackLoads);
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            File(scriptDir, "dynamic-child.js").writeText(
                """
                globalThis.__autojs6DynamicFallbackLoads = (globalThis.__autojs6DynamicFallbackLoads || 0) + 1;
                module.exports = { value: "child" };
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "concat-child.js").writeText("""exports.value = "concat";""", StandardCharsets.UTF_8)
            File(scriptDir, "data.json").writeText("""{"name":"json"}""", StandardCharsets.UTF_8)
            File(scriptDir, "dynamic-dir/index.js").apply {
                parentFile?.mkdirs()
                writeText("""exports.kind = "dir-index";""", StandardCharsets.UTF_8)
            }
            File(scriptDir, "dynamic-cjs.cjs").writeText("""exports.kind = "cjs";""", StandardCharsets.UTF_8)

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("fallback.local.result=child/concat/json/dir-index/cjs"))
            assertTrue(result.stdout.contains("fallback.local.cache=true"))
            assertTrue(result.stdout.contains("fallback.local.cache_entry=true"))
            assertTrue(result.stdout.contains("fallback.local.children=true"))
            assertTrue(result.stdout.contains("fallback.local.load_count=1"))
            assertEquals("5", result.nativeValues["embedded_script.dynamic_require_fallback_loaded_count"])
            assertEquals("0", result.nativeValues["embedded_script.dynamic_require_fallback_denied_count"])
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun commonJsDynamicRequireFallbackLoadsNodeModulesPackagesSubpathsAndNestedDeps() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-dynamic-require-packages-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create dynamic require package test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const packageName = "dynamic-pkg";
                    const packageSubpath = packageName + "/subpath";
                    const parentName = "dynamic-parent";
                    const scopedName = "@scope/dynamic";
                    const fallbackMainName = "dynamic-fallback-main";
                    const pkgA = require(packageName);
                    const pkgB = require(packageName);
                    const subpath = require(packageSubpath);
                    const parent = require(parentName);
                    const scoped = require(scopedName);
                    const fallbackMain = require(fallbackMainName);
                    console.log("fallback.pkg.main=" + pkgA.value);
                    console.log("fallback.pkg.cache=" + (pkgA === pkgB));
                    console.log("fallback.pkg.subpath=" + subpath.value);
                    console.log("fallback.pkg.nested=" + parent.value);
                    console.log("fallback.pkg.scoped=" + scoped.value);
                    console.log("fallback.pkg.main_fallback=" + fallbackMain.value);
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            File(scriptDir, "node_modules/dynamic-pkg/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"main":"main"}""", StandardCharsets.UTF_8)
            }
            File(scriptDir, "node_modules/dynamic-pkg/main.js").writeText(
                """
                globalThis.__autojs6DynamicPackageLoads = (globalThis.__autojs6DynamicPackageLoads || 0) + 1;
                module.exports = { value: "pkg-" + globalThis.__autojs6DynamicPackageLoads };
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "node_modules/dynamic-pkg/subpath.js").writeText("""exports.value = "pkg-subpath";""", StandardCharsets.UTF_8)
            File(scriptDir, "node_modules/dynamic-parent/index.js").apply {
                parentFile?.mkdirs()
                writeText("""exports.value = "parent+" + require("dynamic-shared").value;""", StandardCharsets.UTF_8)
            }
            File(scriptDir, "node_modules/dynamic-parent/node_modules/dynamic-shared/index.js").apply {
                parentFile?.mkdirs()
                writeText("""exports.value = "nested";""", StandardCharsets.UTF_8)
            }
            File(scriptDir, "node_modules/dynamic-shared/index.js").apply {
                parentFile?.mkdirs()
                writeText("""exports.value = "root";""", StandardCharsets.UTF_8)
            }
            File(scriptDir, "node_modules/@scope/dynamic/index.js").apply {
                parentFile?.mkdirs()
                writeText("""exports.value = "scoped";""", StandardCharsets.UTF_8)
            }
            File(scriptDir, "node_modules/dynamic-fallback-main/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"main":"missing"}""", StandardCharsets.UTF_8)
            }
            File(scriptDir, "node_modules/dynamic-fallback-main/index.js").writeText(
                """exports.value = "index-fallback";""",
                StandardCharsets.UTF_8,
            )

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("fallback.pkg.main=pkg-1"))
            assertTrue(result.stdout.contains("fallback.pkg.cache=true"))
            assertTrue(result.stdout.contains("fallback.pkg.subpath=pkg-subpath"))
            assertTrue(result.stdout.contains("fallback.pkg.nested=parent+nested"))
            assertTrue(result.stdout.contains("fallback.pkg.scoped=scoped"))
            assertTrue(result.stdout.contains("fallback.pkg.main_fallback=index-fallback"))
            assertFalse(result.stdout.contains("root"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

