    @Test
    fun commonJsDynamicRequireFallbackRejectsMissingEscapeAbsoluteNativeAndLoadsSyncMjs() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-dynamic-require-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create dynamic require deny test dir: $absolutePath" }
        }
        val outsideFile = File(scriptDir.parentFile, "outside-dynamic-${System.nanoTime()}.js")
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(""""nodejs";""", StandardCharsets.UTF_8)
            }
            outsideFile.writeText("""module.exports = {};""", StandardCharsets.UTF_8)
            val absoluteTarget = File(scriptDir, "absolute-target.js").apply {
                writeText("""module.exports = {};""", StandardCharsets.UTF_8)
            }.canonicalPath
            File(scriptDir, "native.node").writeText("native", StandardCharsets.UTF_8)
            File(scriptDir, "esm.mjs").writeText("""export default 1;""", StandardCharsets.UTF_8)

            val missing = runEmbeddedScript(
                source = """const target = "./missing-dynamic"; require(target);""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )
            assertFalse(missing.succeeded)
            assertEquals("MODULE_NOT_FOUND", missing.errorCode)
            assertTrue(missing.errorMessage.orEmpty().contains("Cannot find Embedded Node local module"))
            assertTrue(missing.errorMessage.orEmpty().contains("./missing-dynamic"))

            settleEmbeddedScriptServiceProcess()

            val escape = runEmbeddedScript(
                source = """const target = "../${outsideFile.nameWithoutExtension}"; require(target);""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )
            assertFalse(escape.succeeded)
            assertTrue(escape.errorMessage.orEmpty().contains("escapes Embedded Node working directory"))
            assertTrue(escape.errorMessage.orEmpty().contains("../${outsideFile.nameWithoutExtension}"))

            settleEmbeddedScriptServiceProcess()

            val absolute = runEmbeddedScript(
                source = """const target = "$absoluteTarget"; require(target);""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )
            assertFalse(absolute.succeeded)
            assertTrue(absolute.errorMessage.orEmpty().contains("rejects absolute"))
            assertTrue(absolute.errorMessage.orEmpty().contains(absoluteTarget))

            settleEmbeddedScriptServiceProcess()

            val native = runEmbeddedScript(
                source = """const target = "./native.node"; require(target);""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )
            assertFalse(native.succeeded)
            assertTrue(native.errorMessage.orEmpty().contains("Unsupported Embedded Node local module extension"))
            assertTrue(native.errorMessage.orEmpty().contains("./native.node"))

            settleEmbeddedScriptServiceProcess()

            val esm = runEmbeddedScript(
                source = """const target = "./esm.mjs"; console.log("fallback.esm.default=" + require(target).default);""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )
            assertTrue(esm.errorMessage.orEmpty(), esm.succeeded)
            assertTrue(esm.stdout.contains("fallback.esm.default=1"))
        } finally {
            outsideFile.delete()
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun commonJsDynamicRequireFallbackEnforcesRuntimeBudgetsAndModuleSourcesPrecedence() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-dynamic-require-budget-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create dynamic require budget test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(""""nodejs";""", StandardCharsets.UTF_8)
            }
            val preferred = File(scriptDir, "preferred.js").apply {
                writeText("""module.exports = "disk";""", StandardCharsets.UTF_8)
            }
            val precedence = runEmbeddedScript(
                source = """
                    const target = "./preferred";
                    console.log("fallback.precedence=" + require(target));
                """.trimIndent(),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = mapOf(preferred.canonicalPath to """module.exports = "preloaded";"""),
            )
            assertTrue(precedence.errorMessage.orEmpty(), precedence.succeeded)
            assertTrue(precedence.stdout.contains("fallback.precedence=preloaded"))
            assertEquals("0", precedence.nativeValues["embedded_script.dynamic_require_fallback_loaded_count"])

            settleEmbeddedScriptServiceProcess()

            File(scriptDir, "extra.js").writeText("""module.exports = true;""", StandardCharsets.UTF_8)
            val maxCountSources = (0 until moduleSourceMaxCount).associate { index ->
                "${scriptDir.canonicalPath}/preloaded-$index.js" to "module.exports = $index;"
            }
            val tooMany = runEmbeddedScript(
                source = """const target = "./extra"; require(target);""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = maxCountSources,
            )
            assertFalse(tooMany.succeeded)
            assertTrue(tooMany.errorMessage.orEmpty().contains("dynamic require fallback"))
            assertTrue(tooMany.errorMessage.orEmpty().contains("module source count is too large"))
            assertTrue(tooMany.errorMessage.orEmpty().contains("$moduleSourceOverLimitCount > $moduleSourceMaxCount"))

            settleEmbeddedScriptServiceProcess()

            File(scriptDir, "big.js").writeText("x".repeat(moduleSourceOverLimitBytes), StandardCharsets.UTF_8)
            val singleTooLarge = runEmbeddedScript(
                source = """const target = "./big"; require(target);""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )
            assertFalse(singleTooLarge.succeeded)
            assertTrue(singleTooLarge.errorMessage.orEmpty().contains("dynamic require fallback module source is too large"))
            assertTrue(
                singleTooLarge.errorMessage.orEmpty()
                    .contains("$moduleSourceOverLimitBytes bytes > $moduleSourceMaxBytes bytes"),
            )
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun commonJsNodeModulesSupportsPackagesScopedSubpathNestedAndBuiltinPrecedence() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-node-modules-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create node_modules test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    process.env.TEST_FROM_MAIN = "main-env";
                    const isNumber = require("is-number");
                    const pkgA = require("pkg-main");
                    const pkgB = require("pkg-main");
                    const scoped = require("@scope/pkg");
                    const foo = require("pkg-sub/lib/foo");
                    const envCheck = require("env-check");
                    const nested = require("a");
                    const path = require("path");
                    console.log("is-number=" + isNumber(1));
                    console.log("pkg.answer=" + pkgA.answer);
                    console.log("pkg.cache=" + (pkgA === pkgB));
                    console.log("scoped=" + scoped.name);
                    console.log("subpath=" + foo.value);
                    console.log("env-check=" + envCheck);
                    console.log("nested=" + nested);
                    console.log("builtin.path=" + path.join("x", "y"));
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val isNumber = File(scriptDir, "node_modules/is-number/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = (value) => typeof value === "number";""", StandardCharsets.UTF_8)
            }
            val pkgMainJson = File(scriptDir, "node_modules/pkg-main/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"main":"main"}""", StandardCharsets.UTF_8)
            }
            val pkgMain = File(scriptDir, "node_modules/pkg-main/main.js").apply {
                writeText(
                    """
                    console.log("pkg-main:load");
                    module.exports = { answer: 42 };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val scoped = File(scriptDir, "node_modules/@scope/pkg/index.js").apply {
                parentFile?.mkdirs()
                writeText("""exports.name = "scoped-pkg";""", StandardCharsets.UTF_8)
            }
            val subpath = File(scriptDir, "node_modules/pkg-sub/lib/foo.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = { value: "subpath-foo" };""", StandardCharsets.UTF_8)
            }
            val envCheck = File(scriptDir, "node_modules/env-check/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    if (!process.env.AUTOJS6_EMBEDDED_NODE) throw new Error("missing env");
                    if (!process.platform) throw new Error("missing platform");
                    if (!process.arch) throw new Error("missing arch");
                    module.exports = process.platform + "/" + process.arch + "/" + process.env.TEST_FROM_MAIN;
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val nestedA = File(scriptDir, "node_modules/a/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = "a+" + require("b");""", StandardCharsets.UTF_8)
            }
            val nestedB = File(scriptDir, "node_modules/a/node_modules/b/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = "b-nested";""", StandardCharsets.UTF_8)
            }
            val rootB = File(scriptDir, "node_modules/b/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = "b-root";""", StandardCharsets.UTF_8)
            }
            val pathPackage = File(scriptDir, "node_modules/path/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    console.log("path-package:load");
                    module.exports = { join: () => "wrong" };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(
                    isNumber,
                    pkgMainJson,
                    pkgMain,
                    scoped,
                    subpath,
                    envCheck,
                    nestedA,
                    nestedB,
                    rootB,
                    pathPackage,
                ),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("is-number=true"))
            assertTrue(result.stdout.contains("pkg.answer=42"))
            assertTrue(result.stdout.contains("pkg.cache=true"))
            assertTrue(result.stdout.contains("scoped=scoped-pkg"))
            assertTrue(result.stdout.contains("subpath=subpath-foo"))
            assertTrue(result.stdout.contains("env-check="))
            assertTrue(result.stdout.contains("/main-env"))
            assertTrue(result.stdout.contains("nested=a+b-nested"))
            assertTrue(result.stdout.contains("builtin.path=x/y"))
            assertFalse(result.stdout.contains("path-package:load"))
            assertOccurrenceCount(result.stdout, "pkg-main:load", 1)
        } finally {
            scriptDir.deleteRecursively()
        }
    }

