        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-package-imports-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create package imports test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const rootImport = require("#root");
                    const rootConfig = require("#config");
                    const pkg = require("imports-pkg");
                    console.log("root=" + rootImport.value);
                    console.log("root.config=" + rootConfig.value);
                    console.log("pkg=" + pkg.value);
                    console.log("pkg.resolve=" + pkg.resolved);
                    console.log("root.resolve=" + require.resolve("#root").endsWith("src/root.js"));
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val rootPackageJson = File(scriptDir, "package.json").apply {
                writeText(
                    """
                    {
                      "imports": {
                        "#root": "./src/root.js",
                        "#config": {
                          "require": "./src/config-require.js",
                          "default": "./src/config-default.js"
                        }
                      }
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val rootImport = File(scriptDir, "src/root.js").apply {
                parentFile?.mkdirs()
                writeText("""exports.value = "root-import";""", StandardCharsets.UTF_8)
            }
            val rootRequireConfig = File(scriptDir, "src/config-require.js").apply {
                writeText("""exports.value = "root-require";""", StandardCharsets.UTF_8)
            }
            val rootDefaultConfig = File(scriptDir, "src/config-default.js").apply {
                writeText("""exports.value = "root-default";""", StandardCharsets.UTF_8)
            }
            val packageJson = File(scriptDir, "node_modules/imports-pkg/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    {
                      "main": "index.js",
                      "imports": {
                        "#util": "./util.js",
                        "#config": {
                          "node": "./node-config.js",
                          "default": "./default-config.js"
                        }
                      }
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val packageIndex = File(scriptDir, "node_modules/imports-pkg/index.js").apply {
                writeText(
                    """
                    const util = require("#util");
                    const config = require("#config");
                    exports.value = util.value + "+" + config.value;
                    exports.resolved = require.resolve("#util").endsWith("node_modules/imports-pkg/util.js");
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val packageUtil = File(scriptDir, "node_modules/imports-pkg/util.js").apply {
                writeText("""exports.value = "pkg-util";""", StandardCharsets.UTF_8)
            }
            val packageNodeConfig = File(scriptDir, "node_modules/imports-pkg/node-config.js").apply {
                writeText("""exports.value = "pkg-node";""", StandardCharsets.UTF_8)
            }
            val packageDefaultConfig = File(scriptDir, "node_modules/imports-pkg/default-config.js").apply {
                writeText("""exports.value = "pkg-default";""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(
                    rootPackageJson,
                    rootImport,
                    rootRequireConfig,
                    rootDefaultConfig,
                    packageJson,
                    packageIndex,
                    packageUtil,
                    packageNodeConfig,
                    packageDefaultConfig,
                ),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("root=root-import"))
            assertTrue(result.stdout.contains("root.config=root-require"))
            assertTrue(result.stdout.contains("pkg=pkg-util+pkg-node"))
            assertTrue(result.stdout.contains("pkg.resolve=true"))
            assertTrue(result.stdout.contains("root.resolve=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun commonJsResolverTraceIsEnvGatedAndIncludesPackageSteps() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-resolver-trace-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create resolver trace project dir: $absolutePath" }
        }
        try {
            val entry = File(projectRoot, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const local = require("./local");
                    const pkg = require("trace-pkg/feature");
                    const root = require("#root");
                    try {
                      require("trace-pkg/private");
                    } catch (error) {
                      const message = String(error.message);
                      console.log("trace.blocked.code=" + error.code);
                      console.log("trace.blocked.explain=" + message.includes("AutoJs6 resolver explanation:"));
                      console.log("trace.blocked.search_paths=" + message.includes("search paths='"));
                      console.log("trace.blocked.null_branch=" + message.includes("[resolve] exports blocked"));
                    }
                    console.log("trace.values=" + local.value + "/" + pkg.value + "/" + root.value);
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val local = File(projectRoot, "local.js").apply {
                writeText("""exports.value = "local";""", StandardCharsets.UTF_8)
            }
            val rootPackageJson = File(projectRoot, "package.json").apply {
                writeText("""{"imports":{"#root":"./root.js"}}""", StandardCharsets.UTF_8)
            }
            val rootImport = File(projectRoot, "root.js").apply {
                writeText("""exports.value = "root";""", StandardCharsets.UTF_8)
            }
            val tracePackageJson = File(projectRoot, "node_modules/trace-pkg/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    {
                      "exports": {
                        "./feature": "./feature.js",
                        "./private": null
                      }
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val traceFeature = File(projectRoot, "node_modules/trace-pkg/feature.js").apply {
                writeText("""exports.value = "feature";""", StandardCharsets.UTF_8)
            }
            val moduleSources = moduleSourcesFor(
                local,
                rootPackageJson,
                rootImport,
                tracePackageJson,
                traceFeature,
            )
            val quietRequest = NodeProjectRunRequest(
                projectRoot = projectRoot,
                entryFile = entry,
                moduleSources = moduleSources,
                entrySource = entry.readText(StandardCharsets.UTF_8),
            )
            val quiet = runNodeProject(quietRequest)

            assertTrue(describeNodeProjectRun(quietRequest, quiet), quiet.succeeded)
            assertTrue(quiet.stdout.contains("trace.values=local/feature/root"))
            assertTrue(quiet.stdout.contains("trace.blocked.code=ERR_PACKAGE_PATH_NOT_EXPORTED"))
            assertFalse("Resolver trace should be disabled by default:\n${quiet.stderr}", quiet.stderr.contains("[resolve]"))

            settleEmbeddedScriptServiceProcess()

            val tracedRequest = quietRequest.copy(env = mapOf("AUTOJS6_NODE_RESOLVE_TRACE" to "1"))
            val traced = runNodeProject(tracedRequest)
            val diagnostic = describeNodeProjectRun(tracedRequest, traced)
            val trace = traced.stderr

            assertTrue(diagnostic, traced.succeeded)
            assertTrue(trace, trace.contains("[resolve] request request=\"./local\""))
            assertTrue(trace, trace.contains("[resolve] final kind=\"local\" request=\"./local\""))
            assertTrue(trace, trace.contains("[resolve] request request=\"trace-pkg/feature\""))
            assertTrue(trace, trace.contains("[resolve] node_modules search request=\"trace-pkg/feature\""))
            assertTrue(trace, trace.contains("[resolve] exports matched request=\"./feature\""))
            assertTrue(trace, trace.contains("[resolve] final kind=\"node_modules\" request=\"trace-pkg/feature\""))
            assertTrue(trace, trace.contains("[resolve] request request=\"#root\""))
            assertTrue(trace, trace.contains("[resolve] package scope request=\"#root\""))
            assertTrue(trace, trace.contains("[resolve] imports matched request=\"#root\""))
            assertTrue(trace, trace.contains("[resolve] request request=\"trace-pkg/private\""))
            assertTrue(trace, trace.contains("[resolve] exports blocked request=\"./private\""))
            assertTrue(trace, trace.contains("[resolve] error request=\"trace-pkg/private\""))
            assertTrue(trace, trace.contains("code=\"ERR_PACKAGE_PATH_NOT_EXPORTED\""))
            assertTrue(traced.stdout, traced.stdout.contains("trace.blocked.explain=true"))
            assertTrue(traced.stdout, traced.stdout.contains("trace.blocked.search_paths=true"))
            assertTrue(traced.stdout, traced.stdout.contains("trace.blocked.null_branch=true"))
            assertOutputOrder(
                trace,
                "[resolve] request request=\"./local\"",
                "[resolve] request request=\"trace-pkg/feature\"",
                "[resolve] request request=\"#root\"",
                "[resolve] request request=\"trace-pkg/private\"",
            )
        } finally {
            projectRoot.deleteRecursively()
        }
    }

    @Test
    fun esmPartialSupportsMjsEntrypointsAndCommonJsRequireSyncBoundary() {
        assumeEmbeddedScriptExecutionEnabled()

        assertTrue(BuildConfig.NODEJS_ESM_EXPERIMENTAL_ENABLED)
        val scriptDir = File(context.cacheDir, "embedded-esm-gate-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create ESM gate test dir: $absolutePath" }
        }
        try {
            val entryMjs = File(scriptDir, "entry.mjs").apply {
                writeText("""console.log("esm.entry.default=true");""", StandardCharsets.UTF_8)
            }

            val entry = runEmbeddedScript(
                source = entryMjs.readText(StandardCharsets.UTF_8),
                sourceName = entryMjs.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )
            assertTrue(entry.errorMessage.orEmpty(), entry.succeeded)
            assertTrue(entry.stdout, entry.stdout.contains("esm.entry.default=true"))

            settleEmbeddedScriptServiceProcess()

            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    function capture(label, fn) {
                      try {
                        const value = fn();
                        console.log(label + ".ok=true");
                        if (value && typeof value === "object") {
                          console.log(label + ".default=" + value.default);
                          if ("value" in value) console.log(label + ".value=" + value.value);
                        } else {
                          console.log(label + "=" + value);
                        }
                      } catch (error) {
                        console.log(label + ".code=" + error.code);
                        const message = String(error.message).replace(/\s+/g, " ");
                        console.log(label + ".asyncMessage=" + message.includes("cannot synchronously load"));
                        console.log(label + ".mjsMessage=" + message.includes(".mjs"));
                      }
                    }
                    console.log("cjs=" + require("./dep.cjs"));
                    const typeModuleJs = require("pkg-type-module-js");
                    console.log("typeModuleJs=" + typeModuleJs.value);
                    console.log("typeModuleJs.alias=" + typeModuleJs.aliasValue);
                    console.log("typeModuleJs.nested=" + typeModuleJs.nestedValue);
                    console.log("typeModuleJs.missing=" + typeModuleJs.missing);
                    console.log("typeModuleJs.rest=" + typeModuleJs.restValues.extraSource);
                    console.log("typeModuleJs.first=" + typeModuleJs.firstValue);
                    console.log("typeModuleJs.third=" + typeModuleJs.thirdValue);
                    console.log("typeModuleJs.fixture=" + typeModuleJs.fixtureValue);
                    const keywordObject = require("./keyword-object.mjs").default;
                    console.log("keywordObject.import=" + keywordObject.import);
                    console.log("keywordObject.export=" + keywordObject.export);
                    capture("relativeMjs", () => require("./esm.mjs"));
                    capture("mainMjs", () => require("pkg-main-mjs"));
                    capture("exportsMjs", () => require("pkg-export-mjs"));
                    capture("importsMjs", () => require("#esm"));
                    capture("tlaMjs", () => require("./tla.mjs"));
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val rootPackageJson = File(scriptDir, "package.json").apply {
                writeText("""{"imports":{"#esm":"./esm.mjs"}}""", StandardCharsets.UTF_8)
            }
            val depCjs = File(scriptDir, "dep.cjs").apply {
                writeText("""module.exports = require("./inner.cjs") + "+dep";""", StandardCharsets.UTF_8)
            }
            val innerCjs = File(scriptDir, "inner.cjs").apply {
                writeText("""module.exports = "inner";""", StandardCharsets.UTF_8)
            }
            val relativeMjs = File(scriptDir, "esm.mjs").apply {
                writeText("""export default "esm";""", StandardCharsets.UTF_8)
            }
            val tlaMjs = File(scriptDir, "tla.mjs").apply {
                writeText("""export default await Promise.resolve("tla");""", StandardCharsets.UTF_8)
            }
            val keywordObjectMjs = File(scriptDir, "keyword-object.mjs").apply {
                writeText(
                    """
                    import value from "./esm.mjs";
                    export default {
                      import: value,
                      export: "keyword-key",
                      "font-face": "font-face",
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val typeModulePackageJson = File(scriptDir, "node_modules/pkg-type-module-js/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"type":"module","main":"index.js"}""", StandardCharsets.UTF_8)
            }
            val typeModuleIndex = File(scriptDir, "node_modules/pkg-type-module-js/index.js").apply {
                writeText(
                    """
                    import { createRequire } from "module";
                    const require = createRequire(import.meta.url);
                    const fixture = require("./fixture.json");
                    const syntax = {
                      value: fixture.value,
                      aliasSource: "alias-value",
                      extraSource: "rest-value",
                      nested: { nestedValue: "nested-value" },
                    };
                    export const {
                      value,
                      aliasSource: aliasValue,
                      nested: { nestedValue },
                      missing = "fallback-value",
                      ...restValues
                    } = syntax;
                    export const [firstValue, , thirdValue = "third-value"] = ["first-value", "skip"];
                    export const fixtureValue = fixture.value;
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val typeModuleFixture = File(scriptDir, "node_modules/pkg-type-module-js/fixture.json").apply {
                writeText("""{"value":"type-module-js-esm"}""", StandardCharsets.UTF_8)
            }
            val mainMjsPackageJson = File(scriptDir, "node_modules/pkg-main-mjs/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"main":"index.mjs"}""", StandardCharsets.UTF_8)
            }
            val mainMjsIndex = File(scriptDir, "node_modules/pkg-main-mjs/index.mjs").apply {
                writeText("""export default "main-mjs";""", StandardCharsets.UTF_8)
            }
            val exportsMjsPackageJson = File(scriptDir, "node_modules/pkg-export-mjs/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"exports":"./index.mjs"}""", StandardCharsets.UTF_8)
            }
            val exportsMjsIndex = File(scriptDir, "node_modules/pkg-export-mjs/index.mjs").apply {
                writeText("""export default "exports-mjs";""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(
                    rootPackageJson,
                    depCjs,
                    innerCjs,
                    relativeMjs,
                    tlaMjs,
                    keywordObjectMjs,
                    typeModulePackageJson,
                    typeModuleIndex,
                    typeModuleFixture,
                    mainMjsPackageJson,
                    mainMjsIndex,
                    exportsMjsPackageJson,
                    exportsMjsIndex,
                ),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout, result.stdout.contains("cjs=inner+dep"))
            assertTrue(result.stdout, result.stdout.contains("typeModuleJs=type-module-js-esm"))
            assertTrue(result.stdout, result.stdout.contains("typeModuleJs.alias=alias-value"))
            assertTrue(result.stdout, result.stdout.contains("typeModuleJs.nested=nested-value"))
            assertTrue(result.stdout, result.stdout.contains("typeModuleJs.missing=fallback-value"))
            assertTrue(result.stdout, result.stdout.contains("typeModuleJs.rest=rest-value"))
            assertTrue(result.stdout, result.stdout.contains("typeModuleJs.first=first-value"))
            assertTrue(result.stdout, result.stdout.contains("typeModuleJs.third=third-value"))
            assertTrue(result.stdout, result.stdout.contains("typeModuleJs.fixture=type-module-js-esm"))
            assertTrue(result.stdout, result.stdout.contains("keywordObject.import=esm"))
            assertTrue(result.stdout, result.stdout.contains("keywordObject.export=keyword-key"))
            assertTrue(result.stdout, result.stdout.contains("relativeMjs.ok=true"))
            assertTrue(result.stdout, result.stdout.contains("relativeMjs.default=esm"))
            assertTrue(result.stdout, result.stdout.contains("mainMjs.ok=true"))
            assertTrue(result.stdout, result.stdout.contains("mainMjs.default=main-mjs"))
            assertTrue(result.stdout, result.stdout.contains("exportsMjs.ok=true"))
            assertTrue(result.stdout, result.stdout.contains("exportsMjs.default=exports-mjs"))
            assertTrue(result.stdout, result.stdout.contains("importsMjs.ok=true"))
            assertTrue(result.stdout, result.stdout.contains("importsMjs.default=esm"))
            assertTrue(result.stdout, result.stdout.contains("tlaMjs.code=ERR_REQUIRE_ASYNC_MODULE"))
            assertTrue(result.stdout, result.stdout.contains("tlaMjs.asyncMessage=true"))
            result.nativeValues["embedded_script.package_type_module_policy"]?.let {
                assertEquals("type=module accepted by Embedded Node partial ESM", it)
            }
            result.nativeValues["embedded_script.package_type_module_package_json"]?.let {
                assertTrue(it, it.endsWith("node_modules/pkg-type-module-js/package.json"))
            }
            result.nativeValues["embedded_script.package_type_module_filename"]?.let {
                assertTrue(it, it.endsWith("node_modules/pkg-type-module-js/index.js"))
            }
            result.nativeValues["embedded_script.package_resolution_field"]?.let {
                assertEquals("imports", it)
            }
            result.nativeValues["embedded_script.package_resolution_request"]?.let {
                assertEquals("#esm", it)
            }
            result.nativeValues["embedded_script.package_resolution_target"]?.let {
                assertEquals("./esm.mjs", it)
            }
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun esmConditionGateKeepsRequireConditionAndRejectsImportOnly() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-esm-conditions-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create ESM condition test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    function capture(label, fn) {
                      try {
                        console.log(label + "=" + fn());
                      } catch (error) {
                        console.log(label + ".code=" + error.code);
                        console.log(label + ".message=" + String(error.message).replace(/\s+/g, " "));
                      }
                    }
                    console.log("exportsDual=" + require("exports-dual").mode);
                    console.log("exportsDual.resolve=" + require.resolve("exports-dual").endsWith("node_modules/exports-dual/cjs.js"));
                    console.log("importsDual=" + require("#dual").mode);
                    console.log("importsDual.resolve=" + require.resolve("#dual").endsWith("root-cjs.js"));
                    capture("exportsImportOnly", () => require("exports-import-only"));
                    capture("importsImportOnly", () => require("#import-only"));
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val rootPackageJson = File(scriptDir, "package.json").apply {
                writeText(
                    """
                    {
                      "imports": {
                        "#dual": {
                          "import": "./root-esm.mjs",
                          "require": "./root-cjs.js",
                          "default": "./root-default.js"
                        },
                        "#import-only": {
                          "import": "./root-esm.mjs"
                        }
                      }
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val rootCjs = File(scriptDir, "root-cjs.js").apply {
                writeText("""exports.mode = "root-cjs";""", StandardCharsets.UTF_8)
            }
            val rootDefault = File(scriptDir, "root-default.js").apply {
                writeText("""exports.mode = "root-default";""", StandardCharsets.UTF_8)
            }
            val rootEsm = File(scriptDir, "root-esm.mjs").apply {
                writeText("""export default "root-esm";""", StandardCharsets.UTF_8)
            }
            val dualPackageJson = File(scriptDir, "node_modules/exports-dual/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    {
                      "exports": {
                        ".": {
                          "import": "./esm.mjs",
                          "require": "./cjs.js",
                          "default": "./fallback.js"
                        }
                      }
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val dualCjs = File(scriptDir, "node_modules/exports-dual/cjs.js").apply {
                writeText("""exports.mode = "exports-cjs";""", StandardCharsets.UTF_8)
            }
            val dualFallback = File(scriptDir, "node_modules/exports-dual/fallback.js").apply {
                writeText("""exports.mode = "exports-default";""", StandardCharsets.UTF_8)
            }
            val dualEsm = File(scriptDir, "node_modules/exports-dual/esm.mjs").apply {
                writeText("""export default "exports-esm";""", StandardCharsets.UTF_8)
            }
            val importOnlyPackageJson = File(scriptDir, "node_modules/exports-import-only/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"exports":{".":{"import":"./esm.mjs"}}}""", StandardCharsets.UTF_8)
            }
            val importOnlyEsm = File(scriptDir, "node_modules/exports-import-only/esm.mjs").apply {
                writeText("""export default "import-only";""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(
                    rootPackageJson,
                    rootCjs,
                    rootDefault,
                    rootEsm,
                    dualPackageJson,
                    dualCjs,
                    dualFallback,
                    dualEsm,
                    importOnlyPackageJson,
                    importOnlyEsm,
                ),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout, result.stdout.contains("exportsDual=exports-cjs"))
            assertTrue(result.stdout, result.stdout.contains("exportsDual.resolve=true"))
            assertTrue(result.stdout, result.stdout.contains("importsDual=root-cjs"))
            assertTrue(result.stdout, result.stdout.contains("importsDual.resolve=true"))
            assertTrue(result.stdout, result.stdout.contains("exportsImportOnly.code=ERR_PACKAGE_PATH_NOT_EXPORTED"))
            assertTrue(result.stdout, result.stdout.contains("exportsImportOnly.message=Embedded Node package exports unsupported condition ignored"))
            assertTrue(result.stdout, result.stdout.contains("importsImportOnly.code=ERR_PACKAGE_IMPORT_NOT_DEFINED"))
            assertTrue(result.stdout, result.stdout.contains("importsImportOnly.message=Embedded Node package imports unsupported condition ignored"))
            assertTrue(result.stdout, result.stdout.contains("condition keys=import"))
            assertTrue(
                result.nativeValues["embedded_script.package_resolution_reason"].orEmpty(),
                result.nativeValues["embedded_script.package_resolution_reason"].orEmpty().contains("condition keys=import"),
            )
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun dualPackageResolverIgnoresBrowserModuleTypesAndUnsupportedConditions() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-dual-package-resolver-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create dual package resolver dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(""""nodejs";""", StandardCharsets.UTF_8)
            }
            File(scriptDir, "package.json").writeText(
                """
                {
                  "imports": {
                    "#dual": {
                      "browser": "./root-browser.js",
                      "import": "./root-esm.mjs",
                      "require": "./root-require.js",
                      "default": "./root-default.js"
                    },
                    "#browserOnly": {
                      "browser": "./root-browser.js",
                      "types": "./root-types.d.ts"
                    }
                  }
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "root-require.js").writeText("""exports.mode = "root-require";""", StandardCharsets.UTF_8)
            File(scriptDir, "root-default.js").writeText("""exports.mode = "root-default";""", StandardCharsets.UTF_8)
            File(scriptDir, "root-browser.js").writeText("""throw new Error("browser condition should be ignored");""", StandardCharsets.UTF_8)
            File(scriptDir, "root-esm.mjs").writeText("""export default "root-esm";""", StandardCharsets.UTF_8)
            File(scriptDir, "root-types.d.ts").writeText("""export {};""", StandardCharsets.UTF_8)

            writeNpmPackage(
                scriptDir,
                "main-field-pkg",
                """
                {
                  "name": "main-field-pkg",
                  "main": "./cjs.js",
                  "module": "./esm.mjs",
                  "browser": "./browser.js",
                  "types": "./index.d.ts",
                  "typings": "./typings.d.ts"
                }
                """,
                mapOf(
                    "cjs.js" to """exports.value = "main-cjs";""",
                    "index.js" to """exports.value = "index-should-not-load";""",
                    "browser.js" to """throw new Error("browser field should be ignored");""",
                    "esm.mjs" to """export default "esm";""",
                    "index.d.ts" to """export {};""",
                    "typings.d.ts" to """export {};""",
                ),
            )
            writeNpmPackage(
                scriptDir,
                "index-fallback-pkg",
                """
                {
                  "name": "index-fallback-pkg",
                  "module": "./esm.mjs",
                  "browser": "./browser.js",
                  "types": "./index.d.ts"
                }
                """,
                mapOf(
                    "index.js" to """exports.value = "index-fallback";""",
                    "browser.js" to """throw new Error("browser field should be ignored");""",
                    "esm.mjs" to """export default "esm";""",
                    "index.d.ts" to """export {};""",
                ),
            )
            writeNpmPackage(
                scriptDir,
                "main-missing-pkg",
                """
                {
                  "name": "main-missing-pkg",
                  "main": "./missing.js",
                  "module": "./esm.mjs",
                  "browser": "./browser.js"
                }
                """,
                mapOf(
                    "index.js" to """exports.value = "main-missing-index";""",
                    "browser.js" to """throw new Error("browser field should be ignored");""",
                    "esm.mjs" to """export default "esm";""",
                ),
            )
            writeNpmPackage(
                scriptDir,
                "dual-package-lite",
                """
                {
                  "name": "dual-package-lite",
                  "main": "./main.js",
                  "module": "./esm.mjs",
                  "browser": "./browser.js",
                  "types": "./index.d.ts",
                  "exports": {
                    ".": {
                      "browser": "./browser.js",
                      "import": "./esm.mjs",
                      "require": "./cjs.js",
                      "default": "./default.js"
                    }
                  }
                }
                """,
                mapOf(
                    "main.js" to """exports.mode = "main-should-not-load";""",
                    "cjs.js" to """exports.mode = "exports-require";""",
                    "default.js" to """exports.mode = "exports-default";""",
                    "browser.js" to """throw new Error("browser condition should be ignored");""",
                    "esm.mjs" to """export default "esm";""",
                    "index.d.ts" to """export {};""",
                ),
            )
            writeNpmPackage(
                scriptDir,
                "exports-node-pkg",
                """
                {
                  "name": "exports-node-pkg",
                  "exports": {
                    ".": {
                      "browser": "./browser.js",
                      "import": "./esm.mjs",
                      "node": "./node.js",
                      "default": "./default.js"
                    }
                  }
                }
                """,
                mapOf(
                    "node.js" to """exports.mode = "exports-node";""",
                    "default.js" to """exports.mode = "exports-default";""",
                    "browser.js" to """throw new Error("browser condition should be ignored");""",
                    "esm.mjs" to """export default "esm";""",
                ),
            )
            writeNpmPackage(
                scriptDir,
                "exports-default-pkg",
                """{"name":"exports-default-pkg","exports":{".":{"default":"./default.js"}}}""",
                mapOf("default.js" to """exports.mode = "exports-default-only";"""),
            )
            writeNpmPackage(
                scriptDir,
                "exports-browser-only-pkg",
                """{"name":"exports-browser-only-pkg","exports":{".":{"browser":"./browser.js","types":"./index.d.ts"}}}""",
                mapOf(
                    "browser.js" to """exports.mode = "browser-only";""",
                    "index.d.ts" to """export {};""",
                ),
            )
            writeNpmPackage(
                scriptDir,
                "exports-import-only-pkg",
                """{"name":"exports-import-only-pkg","exports":{".":{"import":"./esm.mjs"}}}""",
                mapOf("esm.mjs" to """export default "import-only";"""),
            )
            writeNpmPackage(
                scriptDir,
                "self-browser-dual",
                """
                {
                  "name": "self-browser-dual",
                  "exports": {
                    ".": {
                      "browser": "./browser.js",
                      "import": "./esm.mjs",
                      "require": "./index.cjs"
                    },
                    "./sub": {
                      "browser": "./browser.js",
                      "import": "./sub.mjs",
                      "require": "./sub.cjs"
                    }
                  }
                }
                """,
                mapOf(
                    "index.cjs" to """exports.value = "self-" + require("self-browser-dual/sub").value;""",
                    "sub.cjs" to """exports.value = "sub-cjs";""",
                    "browser.js" to """throw new Error("browser condition should be ignored");""",
                    "esm.mjs" to """export default "self-esm";""",
                    "sub.mjs" to """export default "sub-esm";""",
                ),
            )
            writeNpmPackage(
                scriptDir,
                "@autojs6/scoped-dual",
                """
                {
                  "name": "@autojs6/scoped-dual",
                  "main": "./main.js",
                  "module": "./esm.mjs",
                  "browser": "./browser.js",
                  "types": "./index.d.ts"
                }
                """,
                mapOf(
                    "main.js" to """exports.value = "scoped-main";""",
                    "index.js" to """exports.value = "scoped-index";""",
                    "browser.js" to """throw new Error("browser field should be ignored");""",
                    "esm.mjs" to """export default "scoped-esm";""",
                    "index.d.ts" to """export {};""",
                ),
            )
            writeNpmPackage(
                scriptDir,
                "main-mjs-pkg",
                """
                {
                  "name": "main-mjs-pkg",
                  "main": "./esm.mjs",
                  "module": "./ignored.mjs",
                  "browser": "./browser.js",
                  "types": "./index.d.ts"
                }
                """,
                mapOf(
                    "esm.mjs" to """export default "main-mjs";""",
                    "index.js" to """exports.value = "index-should-not-load";""",
                    "browser.js" to """throw new Error("browser field should be ignored");""",
                    "ignored.mjs" to """export default "ignored";""",
                    "index.d.ts" to """export {};""",
                ),
            )
            writeNpmPackage(
                scriptDir,
                "main-unsafe-pkg",
                """
                {
                  "name": "main-unsafe-pkg",
                  "main": "../outside.js",
                  "module": "./ignored.mjs",
                  "browser": "./browser.js"
                }
                """,
                mapOf(
                    "index.js" to """exports.value = "index-should-not-load";""",
                    "browser.js" to """throw new Error("browser field should be ignored");""",
                    "ignored.mjs" to """export default "ignored";""",
                ),
            )
            File(scriptDir, "node_modules/outside.js").writeText(
                """exports.value = "outside-should-not-load";""",
                StandardCharsets.UTF_8,
            )

            fun run(source: String): NativeNodeEmbeddedRuntimeBridge.EmbeddedScriptResult {
                return runEmbeddedScript(
                    source = source.trimIndent(),
                    sourceName = main.canonicalPath,
                    workingDirectory = scriptDir.canonicalPath,
                )
            }

            val success = run(
                """
                "nodejs";
                const { createRequire } = require("module");
                const req = createRequire(__filename);
                const mainField = require("main-field-pkg").value;
                const indexFallback = require("index-fallback-pkg").value;
                const mainMissing = require("main-missing-pkg").value;
                const dual = require("dual-package-lite");
                const dualAgain = req("dual-package-lite");
                const exportsNode = require("exports-node-pkg").mode;
                const exportsDefault = require("exports-default-pkg").mode;
                const importsDual = require("#dual").mode;
                const selfDual = require("self-browser-dual").value;
                const scoped = require("@autojs6/scoped-dual").value;
                const mainMjs = require("main-mjs-pkg").default;
                console.log("dual.fields.main=" + mainField);
                console.log("dual.fields.index=" + indexFallback);
                console.log("dual.fields.main_missing_index=" + mainMissing);
                console.log("dual.exports.require=" + dual.mode);
                console.log("dual.exports.node=" + exportsNode);
                console.log("dual.exports.default=" + exportsDefault);
                console.log("dual.imports.require=" + importsDual);
                console.log("dual.createRequire.cache=" + (dual === dualAgain));
                console.log("dual.self.require=" + selfDual);
                console.log("dual.scoped.ignored=" + scoped);
                console.log("dual.main_mjs.default=" + mainMjs);
                console.log("dual.package.ready=" + (
                  mainField === "main-cjs" &&
                  indexFallback === "index-fallback" &&
                  mainMissing === "main-missing-index" &&
                  dual.mode === "exports-require" &&
                  exportsNode === "exports-node" &&
                  exportsDefault === "exports-default-only" &&
                  importsDual === "root-require" &&
                  selfDual === "self-sub-cjs" &&
                  scoped === "scoped-main" &&
                  mainMjs === "main-mjs"
                ));
                console.log("dual.package.main=" + (mainField === "main-cjs" && mainMissing === "main-missing-index"));
                console.log("dual.package.exports_require=" + (dual.mode === "exports-require"));
                console.log("dual.package.ignored_browser=true");
                console.log("dual.package.ignored_module=true");
                """
            )
            assertTrue(success.errorMessage.orEmpty(), success.succeeded)
            assertTrue(success.stdout, success.stdout.contains("dual.fields.main=main-cjs"))
            assertTrue(success.stdout, success.stdout.contains("dual.fields.index=index-fallback"))
            assertTrue(success.stdout, success.stdout.contains("dual.fields.main_missing_index=main-missing-index"))
            assertTrue(success.stdout, success.stdout.contains("dual.exports.require=exports-require"))
            assertTrue(success.stdout, success.stdout.contains("dual.exports.node=exports-node"))
            assertTrue(success.stdout, success.stdout.contains("dual.exports.default=exports-default-only"))
            assertTrue(success.stdout, success.stdout.contains("dual.imports.require=root-require"))
            assertTrue(success.stdout, success.stdout.contains("dual.createRequire.cache=true"))
            assertTrue(success.stdout, success.stdout.contains("dual.self.require=self-sub-cjs"))
            assertTrue(success.stdout, success.stdout.contains("dual.scoped.ignored=scoped-main"))
            assertTrue(success.stdout, success.stdout.contains("dual.main_mjs.default=main-mjs"))
            assertTrue(success.stdout, success.stdout.contains("dual.package.ready=true"))
            assertTrue(success.stdout, success.stdout.contains("dual.package.main=true"))
            assertTrue(success.stdout, success.stdout.contains("dual.package.exports_require=true"))
            assertTrue(success.stdout, success.stdout.contains("dual.package.ignored_browser=true"))
            assertTrue(success.stdout, success.stdout.contains("dual.package.ignored_module=true"))

            settleEmbeddedScriptServiceProcess()

            val browserOnly = run(
                """
                "nodejs";
                require("exports-browser-only-pkg");
                """
            )
            assertFalse(browserOnly.succeeded)
            assertEquals("ERR_PACKAGE_PATH_NOT_EXPORTED", browserOnly.errorCode)
            assertTrue(browserOnly.errorMessage.orEmpty().contains("exports-browser-only-pkg"))
            assertTrue(browserOnly.errorMessage.orEmpty().contains("condition keys=browser|types"))
            assertTrue(browserOnly.errorMessage.orEmpty().contains("unsupported condition ignored"))
            assertEquals("browser|types", browserOnly.nativeValues["embedded_script.package_resolution_condition_keys"])
            assertEquals("browser|types", browserOnly.nativeValues["embedded_script.package_resolution_ignored_conditions"])

            settleEmbeddedScriptServiceProcess()

            val importsBrowserOnly = run(
                """
                "nodejs";
                require("#browserOnly");
                """
            )
            assertFalse(importsBrowserOnly.succeeded)
            assertEquals("ERR_PACKAGE_IMPORT_NOT_DEFINED", importsBrowserOnly.errorCode)
            assertTrue(importsBrowserOnly.errorMessage.orEmpty().contains("#browserOnly"))
            assertTrue(importsBrowserOnly.errorMessage.orEmpty().contains("condition keys=browser|types"))
            assertTrue(importsBrowserOnly.errorMessage.orEmpty().contains("unsupported condition ignored"))
            assertEquals("browser|types", importsBrowserOnly.nativeValues["embedded_script.package_resolution_condition_keys"])
            assertEquals("browser|types", importsBrowserOnly.nativeValues["embedded_script.package_resolution_ignored_conditions"])

            settleEmbeddedScriptServiceProcess()

            val importOnly = run(
                """
                "nodejs";
                require("exports-import-only-pkg");
                """
            )
            assertFalse(importOnly.succeeded)
            assertEquals("ERR_PACKAGE_PATH_NOT_EXPORTED", importOnly.errorCode)
            assertTrue(importOnly.errorMessage.orEmpty().contains("condition keys=import"))
            assertTrue(importOnly.errorMessage.orEmpty().contains("unsupported condition ignored"))
            assertEquals("import", importOnly.nativeValues["embedded_script.package_resolution_ignored_conditions"])

            settleEmbeddedScriptServiceProcess()

            val mainUnsafe = run(
                """
                "nodejs";
                require("main-unsafe-pkg");
                """
            )
            assertFalse(mainUnsafe.succeeded)
            assertEquals("ERR_INVALID_PACKAGE_TARGET", mainUnsafe.errorCode)
            assertTrue(mainUnsafe.errorMessage.orEmpty().contains("main-unsafe-pkg"))
            assertTrue(mainUnsafe.errorMessage.orEmpty().contains("../outside.js"))
            assertTrue(mainUnsafe.errorMessage.orEmpty().contains("ignoredFields='module|browser'"))
            assertEquals("module|browser", mainUnsafe.nativeValues["embedded_script.package_resolution_ignored_fields"])
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun nodeModulesResolutionScopeHonorsNearestHoistPackageBoundaryAndCreateRequire() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-node-modules-scope-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create node_modules scope test dir: $absolutePath" }
        }
        try {
            File(scriptDir, "package.json").writeText(
                """
                {
                  "name": "root-workspace",
                  "imports": {
                    "#root": "./root-import.js"
                  }
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "root-import.js").writeText("""exports.value = "root-import";""", StandardCharsets.UTF_8)
            File(scriptDir, "root-entry.js").writeText("""module.exports = true;""", StandardCharsets.UTF_8)
            writeNpmPackage(
                scriptDir,
                "shared",
                """{"name":"shared","main":"index.js"}""",
                mapOf("index.js" to """exports.value = "root-shared";"""),
            )
            writeNpmPackage(
                scriptDir,
                "hoisted-only",
                """{"name":"hoisted-only","main":"index.js"}""",
                mapOf("index.js" to """exports.value = "hoisted-root";"""),
            )
            writeNpmPackage(
                scriptDir,
                "path",
                """{"name":"path","main":"index.js"}""",
                mapOf("index.js" to """exports.__autojs6Shadow = true;"""),
            )

            val packagesNodeModulesShared = File(scriptDir, "packages/node_modules/shared").apply {
                check(mkdirs()) { "Failed to create packages shared dir: $absolutePath" }
            }
            File(packagesNodeModulesShared, "package.json").writeText(
                """{"name":"shared","main":"index.js"}""",
                StandardCharsets.UTF_8,
            )
            File(packagesNodeModulesShared, "index.js").writeText(
                """exports.value = "packages-shared";""",
                StandardCharsets.UTF_8,
            )

            val appDir = File(scriptDir, "packages/app").apply {
                check(mkdirs()) { "Failed to create app package dir: $absolutePath" }
            }
            File(appDir, "package.json").writeText(
                """
                {
                  "name": "app-pkg",
                  "imports": {
                    "#app": "./src/app-import.js"
                  },
                  "exports": {
                    ".": "./src/self.js",
                    "./sub": "./src/sub.js"
                  }
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            val appSrcDir = File(appDir, "src").apply {
                check(mkdirs()) { "Failed to create app src dir: $absolutePath" }
            }
            File(appSrcDir, "app-import.js").writeText("""exports.value = "app-import";""", StandardCharsets.UTF_8)
            File(appSrcDir, "self.js").writeText(
                """exports.value = "app-self+" + require("app-pkg/sub").value;""",
                StandardCharsets.UTF_8,
            )
            File(appSrcDir, "sub.js").writeText("""exports.value = "app-sub";""", StandardCharsets.UTF_8)
            val appSrcNodeModulesLocal = File(appSrcDir, "node_modules/local-only").apply {
                check(mkdirs()) { "Failed to create src local node_modules dir: $absolutePath" }
            }
            File(appSrcNodeModulesLocal, "package.json").writeText(
                """{"name":"local-only","main":"index.js"}""",
                StandardCharsets.UTF_8,
            )
            File(appSrcNodeModulesLocal, "index.js").writeText(
                """exports.value = "src-local";""",
                StandardCharsets.UTF_8,
            )
            val appNodeModulesShared = File(appDir, "node_modules/shared").apply {
                check(mkdirs()) { "Failed to create app shared dir: $absolutePath" }
            }
            File(appNodeModulesShared, "package.json").writeText(
                """
                {
                  "name": "shared",
                  "main": "index.js",
                  "exports": {
                    ".": "./index.js",
                    "./sub": "./sub.js"
                  }
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(appNodeModulesShared, "index.js").writeText(
                """exports.value = "app-shared";""",
                StandardCharsets.UTF_8,
            )
            File(appNodeModulesShared, "sub.js").writeText(
                """exports.value = "app-shared-sub";""",
                StandardCharsets.UTF_8,
            )
            val nestedParentDir = File(appDir, "node_modules/nested-parent").apply {
                check(mkdirs()) { "Failed to create nested parent dir: $absolutePath" }
            }
            File(nestedParentDir, "package.json").writeText(
                """
                {
                  "name": "nested-parent",
                  "exports": {
                    ".": "./index.js",
                    "./self": "./self.js"
                  }
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(nestedParentDir, "index.js").writeText(
                """
                const shared = require("shared");
                const self = require("nested-parent/self");
                exports.shared = shared.value;
                exports.self = self.value;
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(nestedParentDir, "self.js").writeText("""exports.value = "nested-self";""", StandardCharsets.UTF_8)
            val nestedShared = File(nestedParentDir, "node_modules/shared").apply {
                check(mkdirs()) { "Failed to create nested shared dir: $absolutePath" }
            }
            File(nestedShared, "package.json").writeText(
                """{"name":"shared","main":"index.js"}""",
                StandardCharsets.UTF_8,
            )
            File(nestedShared, "index.js").writeText(
                """exports.value = "nested-shared";""",
                StandardCharsets.UTF_8,
            )

            val scopedParentDir = File(appDir, "node_modules/@scope/scoped-parent").apply {
                check(mkdirs()) { "Failed to create scoped parent dir: $absolutePath" }
            }
            File(scopedParentDir, "package.json").writeText(
                """
                {
                  "name": "@scope/scoped-parent",
                  "exports": {
                    ".": "./index.js",
                    "./sub": "./sub.js"
                  }
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(scopedParentDir, "index.js").writeText(
                """exports.value = "scoped-" + require("@scope/scoped-parent/sub").value;""",
                StandardCharsets.UTF_8,
            )
            File(scopedParentDir, "sub.js").writeText("""exports.value = "self-sub";""", StandardCharsets.UTF_8)

            val libDir = File(scriptDir, "packages/lib").apply {
                check(mkdirs()) { "Failed to create lib package dir: $absolutePath" }
            }
            File(libDir, "package.json").writeText(
                """
                {
                  "name": "lib-pkg",
                  "imports": {
                    "#lib": "./lib-import.js"
                  },
                  "exports": {
                    ".": "./index.js"
                  }
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(libDir, "index.js").writeText("""exports.value = "lib-index";""", StandardCharsets.UTF_8)
            File(libDir, "lib-import.js").writeText("""exports.value = "lib-import";""", StandardCharsets.UTF_8)

            val main = File(appSrcDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const path = require("path");
                    const { createRequire } = require("module");
                    function capture(label, fn) {
                      try {
                        const value = fn();
                        console.log(label + ".value=" + value);
                      } catch (error) {
                        const message = String(error && error.message || error).replace(/\s+/g, " ");
                        console.log(label + ".code=" + (error && error.code || "NO_CODE"));
                        console.log(label + ".message.has_app_package=" + message.includes("packages/app/package.json"));
                        console.log(label + ".message.has_search_paths=" + message.includes("node_modules search paths="));
                        console.log(label + ".message.has_sandbox=" + message.includes("sandboxRoot="));
                        console.log(label + ".message.has_scoped_escape=" + message.includes("package subpath escapes working directory"));
                      }
                    }
                    const dynamicShared = "shared";
                    const dynamicAlias = "#app";
                    const nestedParent = require("nested-parent");
                    const reqFromApp = createRequire(__filename);
                    const reqFromLib = createRequire(path.resolve("packages/lib/index.js"));
                    const reqFromRoot = createRequire(path.resolve("root-entry.js"));
                    console.log("scope.nearest.shared=" + require("shared").value);
                    console.log("scope.hoisted=" + require("hoisted-only").value);
                    console.log("scope.local_only=" + require("local-only").value);
                    console.log("scope.nested.shared=" + nestedParent.shared);
                    console.log("scope.nested.self=" + nestedParent.self);
                    console.log("scope.imports.app=" + require("#app").value);
                    capture("scope.imports.root_from_app", () => require("#root").value);
                    console.log("scope.self.app=" + require("app-pkg").value);
                    console.log("scope.self.scoped=" + require("@scope/scoped-parent").value);
                    console.log("scope.create_require.app_shared=" + reqFromApp("shared").value);
                    console.log("scope.create_require.lib_import=" + reqFromLib("#lib").value);
                    console.log("scope.create_require.root_import=" + reqFromRoot("#root").value);
                    capture("scope.create_require.root_from_app", () => reqFromApp("#root").value);
                    console.log("scope.dynamic.shared=" + require(dynamicShared).value);
                    console.log("scope.dynamic.imports=" + require(dynamicAlias).value);
                    console.log("scope.dynamic.subpath=" + require("shared/sub").value);
                    console.log("scope.builtin.path=" + (require.resolve("path") === "path" && path.__autojs6Shadow !== true));
                    capture("scope.escape.scoped", () => require("@scope/scoped-parent/../escape"));
                    capture("scope.missing", () => require("missing-edge-package"));
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout, result.stdout.contains("scope.nearest.shared=app-shared"))
            assertTrue(result.stdout, result.stdout.contains("scope.hoisted=hoisted-root"))
            assertTrue(result.stdout, result.stdout.contains("scope.local_only=src-local"))
            assertTrue(result.stdout, result.stdout.contains("scope.nested.shared=nested-shared"))
            assertTrue(result.stdout, result.stdout.contains("scope.nested.self=nested-self"))
            assertTrue(result.stdout, result.stdout.contains("scope.imports.app=app-import"))
            assertTrue(result.stdout, result.stdout.contains("scope.imports.root_from_app.code=ERR_PACKAGE_IMPORT_NOT_DEFINED"))
            assertTrue(result.stdout, result.stdout.contains("scope.imports.root_from_app.message.has_app_package=true"))
            assertTrue(result.stdout, result.stdout.contains("scope.self.app=app-self+app-sub"))
            assertTrue(result.stdout, result.stdout.contains("scope.self.scoped=scoped-self-sub"))
            assertTrue(result.stdout, result.stdout.contains("scope.create_require.app_shared=app-shared"))
            assertTrue(result.stdout, result.stdout.contains("scope.create_require.lib_import=lib-import"))
            assertTrue(result.stdout, result.stdout.contains("scope.create_require.root_import=root-import"))
            assertTrue(result.stdout, result.stdout.contains("scope.create_require.root_from_app.code=ERR_PACKAGE_IMPORT_NOT_DEFINED"))
            assertTrue(result.stdout, result.stdout.contains("scope.dynamic.shared=app-shared"))
            assertTrue(result.stdout, result.stdout.contains("scope.dynamic.imports=app-import"))
            assertTrue(result.stdout, result.stdout.contains("scope.dynamic.subpath=app-shared-sub"))
            assertTrue(result.stdout, result.stdout.contains("scope.builtin.path=true"))
            assertTrue(result.stdout, result.stdout.contains("scope.escape.scoped.code=NO_CODE"))
            assertTrue(result.stdout, result.stdout.contains("scope.escape.scoped.message.has_scoped_escape=true"))
            assertTrue(result.stdout, result.stdout.contains("scope.missing.code=MODULE_NOT_FOUND"))
            assertTrue(result.stdout, result.stdout.contains("scope.missing.message.has_search_paths=true"))
            assertTrue(result.stdout, result.stdout.contains("scope.missing.message.has_sandbox=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun esmPackageDiagnosticsCoverCreateRequireSelfReferenceAndDynamicFallback() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-esm-diagnostics-hardening-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create ESM diagnostics hardening dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(""""nodejs";""", StandardCharsets.UTF_8)
            }
            File(scriptDir, "package.json").writeText(
                """
                {
                  "imports": {
                    "#dual": {
                      "import": "./root-esm.mjs",
                      "node": "./root-node.cjs",
                      "default": "./root-default.cjs"
                    },
                    "#default-mjs": {
                      "default": "./root-esm.mjs"
                    }
                  }
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "root-node.cjs").writeText("""exports.mode = "root-node";""", StandardCharsets.UTF_8)
            File(scriptDir, "root-default.cjs").writeText("""exports.mode = "root-default";""", StandardCharsets.UTF_8)
            File(scriptDir, "root-esm.mjs").writeText("""export default "root-esm";""", StandardCharsets.UTF_8)

            File(scriptDir, "node_modules/@scope/dual/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    {
                      "name": "@scope/dual",
                      "type": "module",
                      "exports": {
                        ".": {
                          "import": "./esm.mjs",
                          "require": "./cjs.cjs",
                          "default": "./default.cjs"
                        }
                      }
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            File(scriptDir, "node_modules/@scope/dual/cjs.cjs").writeText(
                """exports.mode = "scoped-require";""",
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "node_modules/@scope/dual/default.cjs").writeText(
                """exports.mode = "scoped-default";""",
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "node_modules/@scope/dual/esm.mjs").writeText(
                """export default "scoped-esm";""",
                StandardCharsets.UTF_8,
            )

            File(scriptDir, "node_modules/self-dual/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    {
                      "name": "self-dual",
                      "type": "module",
                      "exports": {
                        ".": {
                          "import": "./esm.mjs",
                          "require": "./index.cjs"
                        },
                        "./feature": {
                          "import": "./feature.mjs",
                          "require": "./feature.cjs"
                        }
                      }
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            File(scriptDir, "node_modules/self-dual/index.cjs").writeText(
                """exports.value = "self+" + require("self-dual/feature").value;""",
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "node_modules/self-dual/feature.cjs").writeText(
                """exports.value = "feature-cjs";""",
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "node_modules/self-dual/esm.mjs").writeText(
                """export default "self-esm";""",
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "node_modules/self-dual/feature.mjs").writeText(
                """export default "feature-esm";""",
                StandardCharsets.UTF_8,
            )

            File(scriptDir, "node_modules/import-only-pkg/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"name":"import-only-pkg","exports":{".":{"import":"./esm.mjs"}}}""", StandardCharsets.UTF_8)
            }
            File(scriptDir, "node_modules/import-only-pkg/esm.mjs").writeText(
                """export default "import-only";""",
                StandardCharsets.UTF_8,
            )

            File(scriptDir, "node_modules/require-mjs-pkg/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """{"name":"require-mjs-pkg","exports":{".":{"import":"./esm.mjs","require":"./esm.mjs"}}}""",
                    StandardCharsets.UTF_8,
                )
            }
            File(scriptDir, "node_modules/require-mjs-pkg/esm.mjs").writeText(
                """export default "require-mjs";""",
                StandardCharsets.UTF_8,
            )

            File(scriptDir, "node_modules/dynamic-type/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"name":"dynamic-type","type":"module","main":"index.js"}""", StandardCharsets.UTF_8)
            }
            File(scriptDir, "node_modules/dynamic-type/index.js").writeText(
                """exports.value = "dynamic-type-cjs";""",
                StandardCharsets.UTF_8,
            )

            fun run(source: String): NativeNodeEmbeddedRuntimeBridge.EmbeddedScriptResult {
                return runEmbeddedScript(
                    source = source.trimIndent(),
                    sourceName = main.canonicalPath,
                    workingDirectory = scriptDir.canonicalPath,
                )
            }

            val success = run(
                """
                "nodejs";
                const { createRequire } = require("module");
                const req = createRequire(__filename);
                console.log("esm.diag.scoped=" + req("@scope/dual").mode);
                console.log("esm.diag.imports=" + require("#dual").mode);
                console.log("esm.diag.self=" + require("self-dual").value);
                console.log("esm.diag.dynamic_type=" + require("dynamic-type").value);
                """
            )
            assertTrue(success.errorMessage.orEmpty(), success.succeeded)
            assertTrue(success.stdout.contains("esm.diag.scoped=scoped-require"))
            assertTrue(success.stdout.contains("esm.diag.imports=root-node"))
            assertTrue(success.stdout.contains("esm.diag.self=self+feature-cjs"))
            assertTrue(success.stdout.contains("esm.diag.dynamic_type=dynamic-type-cjs"))
            assertEquals(
                "type=module ignored by Embedded Node CommonJS MVP",
                success.nativeValues["embedded_script.package_type_module_policy"],
            )
            assertEquals("dynamic-type", success.nativeValues["embedded_script.package_type_module_package"])
            assertTrue(
                success.nativeValues["embedded_script.package_type_module_package_json"].orEmpty(),
                success.nativeValues["embedded_script.package_type_module_package_json"].orEmpty()
                    .endsWith("node_modules/dynamic-type/package.json"),
            )

            settleEmbeddedScriptServiceProcess()

            val createRequireImportOnly = run(
                """
                "nodejs";
                require("module").createRequire(__filename)("import-only-pkg");
                """
            )
            assertFalse(createRequireImportOnly.succeeded)
            assertEquals("ERR_PACKAGE_PATH_NOT_EXPORTED", createRequireImportOnly.errorCode)
            assertTrue(createRequireImportOnly.errorMessage.orEmpty().contains("import-only-pkg"))
            assertTrue(createRequireImportOnly.errorMessage.orEmpty().contains("package.json"))
            assertTrue(createRequireImportOnly.errorMessage.orEmpty().contains("condition keys=import"))
            assertTrue(createRequireImportOnly.errorMessage.orEmpty().contains(main.canonicalPath))
            assertTrue(
                createRequireImportOnly.nativeValues["embedded_script.package_resolution_reason"].orEmpty(),
                createRequireImportOnly.nativeValues["embedded_script.package_resolution_reason"].orEmpty()
                    .contains("condition keys=import"),
            )

            settleEmbeddedScriptServiceProcess()

            val createRequireMjs = run(
                """
                "nodejs";
                const value = require("module").createRequire(__filename)("require-mjs-pkg").default;
                console.log("esm.diag.require_mjs=" + value);
                """
            )
            assertTrue(createRequireMjs.errorMessage.orEmpty(), createRequireMjs.succeeded)
            assertTrue(createRequireMjs.stdout.contains("esm.diag.require_mjs=require-mjs"))
            assertEquals("exports", createRequireMjs.nativeValues["embedded_script.package_resolution_field"])
            assertEquals("import|require", createRequireMjs.nativeValues["embedded_script.package_resolution_condition_keys"])
            assertEquals("require", createRequireMjs.nativeValues["embedded_script.package_resolution_selected_condition"])

            settleEmbeddedScriptServiceProcess()

            val importsDefaultMjs = run(
                """
                "nodejs";
                console.log("esm.diag.imports_default_mjs=" + require("#default-mjs").default);
                """
            )
            assertTrue(importsDefaultMjs.errorMessage.orEmpty(), importsDefaultMjs.succeeded)
            assertTrue(importsDefaultMjs.stdout.contains("esm.diag.imports_default_mjs=root-esm"))
            assertEquals("imports", importsDefaultMjs.nativeValues["embedded_script.package_resolution_field"])
            assertEquals("default", importsDefaultMjs.nativeValues["embedded_script.package_resolution_selected_condition"])
            assertEquals("./root-esm.mjs", importsDefaultMjs.nativeValues["embedded_script.package_resolution_target"])
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun dynamicAndStaticImportSyntaxAreRejectedWithStableErrorCodes() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-import-syntax-gate-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create import syntax gate dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(""""nodejs";""", StandardCharsets.UTF_8)
            }
            val dependency = File(scriptDir, "dependency.js").apply {
                writeText("""exports.value = "dependency";""", StandardCharsets.UTF_8)
            }

            val dynamicImport = runEmbeddedScript(
                source = """
                    "nodejs";
                    return import("./dependency.js").then(mod => {
                      console.log("dynamic.import.cjs=" + mod.default.value);
                    });
                """.trimIndent(),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(dependency),
            )
            assertTrue(dynamicImport.errorMessage.orEmpty() + "\n" + dynamicImport.stdout, dynamicImport.succeeded)
            assertTrue(dynamicImport.stdout.contains("dynamic.import.cjs=dependency"))

            settleEmbeddedScriptServiceProcess()

            val staticImport = runEmbeddedScript(
                source = """
                    "nodejs";
                    import value from "./dependency.js";
                    console.log(value);
                """.trimIndent(),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(dependency),
            )
            assertFalse(staticImport.succeeded)
            assertEquals("ERR_AUTOJS6_EMBEDDED_NODE_ESM_UNSUPPORTED", staticImport.errorCode)
            assertTrue(staticImport.errorMessage.orEmpty().contains("ESM/import is not supported in Embedded Node.js MVP"))
            assertTrue(staticImport.errorMessage.orEmpty().contains("static import syntax is disabled"))

            settleEmbeddedScriptServiceProcess()

            val evalImport = runEmbeddedScript(
                source = """
                    "nodejs";
                    eval("import('./dependency.js')");
                """.trimIndent(),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(dependency),
            )
            assertFalse(evalImport.succeeded)
            assertEquals("ERR_AUTOJS6_EMBEDDED_NODE_DYNAMIC_IMPORT_UNSUPPORTED", evalImport.errorCode)
            assertTrue(evalImport.errorMessage.orEmpty().contains("dynamic import is disabled"))

            settleEmbeddedScriptServiceProcess()

            val functionImport = runEmbeddedScript(
                source = """
                    "nodejs";
                    Function("return import('./dependency.js')")();
                """.trimIndent(),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(dependency),
            )
            assertFalse(functionImport.succeeded)
            assertEquals("ERR_AUTOJS6_EMBEDDED_NODE_DYNAMIC_IMPORT_UNSUPPORTED", functionImport.errorCode)
            assertTrue(functionImport.errorMessage.orEmpty().contains("dynamic import is disabled"))

            settleEmbeddedScriptServiceProcess()

            val prototypeFunctionImport = runEmbeddedScript(
                source = """
                    "nodejs";
                    Function.prototype.constructor("return import('./dependency.js')")();
                """.trimIndent(),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(dependency),
            )
            assertFalse(prototypeFunctionImport.succeeded)
            assertEquals("ERR_AUTOJS6_EMBEDDED_NODE_DYNAMIC_IMPORT_UNSUPPORTED", prototypeFunctionImport.errorCode)
            assertTrue(prototypeFunctionImport.errorMessage.orEmpty().contains("dynamic import is disabled"))

            settleEmbeddedScriptServiceProcess()

            val asyncFunctionImport = runEmbeddedScript(
                source = """
                    "nodejs";
                    Object.getPrototypeOf(async function() {}).constructor("return import('./dependency.js')")();
                """.trimIndent(),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(dependency),
            )
            assertFalse(asyncFunctionImport.succeeded)
            assertEquals("ERR_AUTOJS6_EMBEDDED_NODE_DYNAMIC_IMPORT_UNSUPPORTED", asyncFunctionImport.errorCode)
            assertTrue(asyncFunctionImport.errorMessage.orEmpty().contains("dynamic import is disabled"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun modernPackageSmokeSupportsPatternsConditionsAndNullBlocking() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-modern-package-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create modern package test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    const modern = require("modern-pkg");
                    const featureA = require("modern-pkg/features/a");
                    const conditionA = require("modern-pkg/condition/a");
                    console.log("modern.name=" + modern.name);
                    console.log("modern.util=" + modern.util);
                    console.log("modern.config=" + modern.config);
                    console.log("feature=" + featureA.name);
                    console.log("condition=" + conditionA.mode);
                    console.log("feature.resolve=" + require.resolve("modern-pkg/features/a").endsWith("node_modules/modern-pkg/cjs/features/a.js"));
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val packageJson = File(scriptDir, "node_modules/modern-pkg/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    {
                      "exports": {
                        ".": "./cjs/index.js",
                        "./features/*": "./cjs/features/*.js",
                        "./condition/*": {
                          "require": "./cjs/condition/*.js",
                          "default": "./src/condition/*.js"
                        },
                        "./blocked-entry": "./cjs/blocked-entry.js",
                        "./private/*": null
                      },
                      "imports": {
                        "#utils/*": "./src/utils/*.js",
                        "#config": {
                          "require": "./cjs/config.js",
                          "default": "./src/config.js"
                        },
                        "#blocked/*": null
                      }
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val packageIndex = File(scriptDir, "node_modules/modern-pkg/cjs/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const util = require("#utils/a");
                    const config = require("#config");
                    module.exports = {
                      name: "modern",
                      util: util.name,
                      config: config.mode
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val featureA = File(scriptDir, "node_modules/modern-pkg/cjs/features/a.js").apply {
                parentFile?.mkdirs()
                writeText("""exports.name = "feature-a";""", StandardCharsets.UTF_8)
            }
            val conditionA = File(scriptDir, "node_modules/modern-pkg/cjs/condition/a.js").apply {
                parentFile?.mkdirs()
                writeText("""exports.mode = "condition-require";""", StandardCharsets.UTF_8)
            }
            val conditionDefaultA = File(scriptDir, "node_modules/modern-pkg/src/condition/a.js").apply {
                parentFile?.mkdirs()
                writeText("""exports.mode = "condition-default";""", StandardCharsets.UTF_8)
            }
            val utilA = File(scriptDir, "node_modules/modern-pkg/src/utils/a.js").apply {
                parentFile?.mkdirs()
                writeText("""exports.name = "util-a";""", StandardCharsets.UTF_8)
            }
            val configRequire = File(scriptDir, "node_modules/modern-pkg/cjs/config.js").apply {
                writeText("""exports.mode = "config-require";""", StandardCharsets.UTF_8)
            }
            val configDefault = File(scriptDir, "node_modules/modern-pkg/src/config.js").apply {
                parentFile?.mkdirs()
                writeText("""exports.mode = "config-default";""", StandardCharsets.UTF_8)
            }
            val blockedEntry = File(scriptDir, "node_modules/modern-pkg/cjs/blocked-entry.js").apply {
                writeText("""module.exports = require("#blocked/secret");""", StandardCharsets.UTF_8)
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(
                    packageJson,
                    packageIndex,
                    featureA,
                    conditionA,
                    conditionDefaultA,
                    utilA,
                    configRequire,
                    configDefault,
                    blockedEntry,
                ),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("modern.name=modern"))
            assertTrue(result.stdout.contains("modern.util=util-a"))
            assertTrue(result.stdout.contains("modern.config=config-require"))
            assertTrue(result.stdout.contains("feature=feature-a"))
            assertTrue(result.stdout.contains("condition=condition-require"))
            assertTrue(result.stdout.contains("feature.resolve=true"))

            settleEmbeddedScriptServiceProcess()

            val privateBlocked = runEmbeddedScript(
                source = """require("modern-pkg/private/secret");""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(packageJson),
            )
            assertFalse(privateBlocked.succeeded)
            assertEquals("Error", privateBlocked.errorName)
            assertTrue(privateBlocked.errorMessage.orEmpty().contains("package subpath is not exported"))

            settleEmbeddedScriptServiceProcess()

            val importBlocked = runEmbeddedScript(
                source = """require("modern-pkg/blocked-entry");""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(packageJson, blockedEntry),
            )
            assertFalse(importBlocked.succeeded)
            assertEquals("Error", importBlocked.errorName)
            assertTrue(importBlocked.errorMessage.orEmpty().contains("package import is blocked"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

