            }
            val nestedSub = File(scriptDir, "node_modules/nested-self/sub.js").apply {
                writeText("""exports.value = "self-sub";""", StandardCharsets.UTF_8)
            }
            val nestedShadowPackageJson = File(scriptDir, "node_modules/nested-self/node_modules/nested-self/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    {
                      "name": "nested-self",
                      "exports": {
                        ".": "./wrong.js",
                        "./sub": "./wrong.js"
                      }
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val nestedShadow = File(scriptDir, "node_modules/nested-self/node_modules/nested-self/wrong.js").apply {
                writeText("""exports.value = "shadow-sub";""", StandardCharsets.UTF_8)
            }

