            }
            val packageJson = File(scriptDir, "package.json").apply {
                writeText(
                    """
                    {
                      "imports": {
                        "#escape": "./../outside.js",
                        "#absolute": "/sdcard/outside.js",
                        "#external": "dep",
                        "#native": "./native.node",
                        "#multi/*/*": "./src/*.js",
