    @Test
    fun pureJsNpmSmokeSupportsCommonJsMetadataProcessFsAndResolve() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-npm-smoke-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create npm smoke test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    process.env.SMOKE_ENV = "smoke";
                    const path = require("path");
                    const isNumber = require("is-number");
                    const kindOf = require("kind-of");
                    const inherits = require("inherits");
                    const once = require("once");
                    const outer = require("outer");
                    const resolved = require("resolve-user");
                    const readLocal = require("read-local");
                    const metadata = require("metadata-check");
                    let calls = 0;
                    const onlyOnce = once((value) => {
                      calls += 1;
                      return "once-" + value;
                    });
                    console.log("isNumber=" + isNumber(123));
                    console.log("kind=" + kindOf({}));
                    console.log("inherits=" + typeof inherits);
                    console.log("once.first=" + onlyOnce("first"));
                    console.log("once.second=" + onlyOnce("second"));
                    console.log("once.calls=" + calls);
                    console.log("nested=" + outer);
                    console.log("resolved=" + resolved.endsWith("node_modules/is-number/index.js"));
                    console.log("readLocal=" + readLocal);
                    console.log("metadata.filename=" + metadata.filename);
                    console.log("metadata.parent=" + metadata.parent);
                    console.log("metadata.loadedDuringRequire=" + metadata.loadedDuringRequire);
                    console.log("metadata.cacheSame=" + metadata.cacheSame);
                    console.log("metadata.fileVars=" + metadata.fileVars);
                    console.log("metadata.env=" + metadata.env);
                    console.log("metadata.platformArch=" + metadata.platformArch);
                    console.log("metadata.cache.loaded=" + require.cache[require.resolve("metadata-check")].loaded);
                    console.log("main.cache=" + Boolean(require.cache[__filename]));
                    console.log("main.parent=" + (module.parent === null));
                    console.log("main.loaded=" + module.loaded);
                    console.log("main.filename=" + path.basename(module.filename));
                    console.log("main.dirname=" + path.basename(__dirname));
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            File(scriptDir, "fixture.txt").writeText("fixture\n", StandardCharsets.UTF_8)
            val isNumber = File(scriptDir, "node_modules/is-number/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    module.exports = function isNumber(value) {
                      return typeof value === "number" && !Number.isNaN(value);
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val kindOfPackageJson = File(scriptDir, "node_modules/kind-of/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"main":"kind"}""", StandardCharsets.UTF_8)
            }
            val kindOfMain = File(scriptDir, "node_modules/kind-of/kind.js").apply {
                writeText(
                    """
                    module.exports = function kindOf(value) {
                      if (value === null) return "null";
                      if (Array.isArray(value)) return "array";
                      return typeof value;
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val inherits = File(scriptDir, "node_modules/inherits/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const util = require("util");
                    module.exports = util.inherits;
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val once = File(scriptDir, "node_modules/once/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    module.exports = function once(fn) {
                      let called = false;
                      let value;
                      return function wrappedOnce(...args) {
                        if (!called) {
                          called = true;
                          value = fn.apply(this, args);
                        }
                        return value;
                      };
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val outer = File(scriptDir, "node_modules/outer/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = "outer+" + require("inner");""", StandardCharsets.UTF_8)
            }
            val inner = File(scriptDir, "node_modules/outer/node_modules/inner/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = "inner";""", StandardCharsets.UTF_8)
            }
            val resolveUser = File(scriptDir, "node_modules/resolve-user/index.js").apply {
                parentFile?.mkdirs()
                writeText("""module.exports = require.resolve("is-number");""", StandardCharsets.UTF_8)
            }
            val readLocalFixture = File(scriptDir, "node_modules/read-local/fixture.txt").apply {
                parentFile?.mkdirs()
                writeText("fixture\n", StandardCharsets.UTF_8)
            }
            val readLocal = File(scriptDir, "node_modules/read-local/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fs = require("fs");
                    const path = require("path");
                    module.exports = fs.readFileSync(path.join(__dirname, "fixture.txt"), "utf8").trim();
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val metadataCheck = File(scriptDir, "node_modules/metadata-check/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const path = require("path");
                    const resolved = require.resolve("metadata-check");
                    module.exports = {
                      filename: path.basename(module.filename),
                      parent: Boolean(module.parent && module.parent.filename && module.parent.filename.endsWith("main.js")),
                      loadedDuringRequire: module.loaded,
                      cacheSame: require.cache[resolved] === module,
                      fileVars: __filename === module.filename && __dirname === path.dirname(module.filename),
                      env: process.env.SMOKE_ENV,
                      platformArch: process.platform + "/" + process.arch,
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(
                    isNumber,
                    kindOfPackageJson,
                    kindOfMain,
                    inherits,
                    once,
                    outer,
                    inner,
                    resolveUser,
                    readLocalFixture,
                    readLocal,
                    metadataCheck,
                ),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("isNumber=true"))
            assertTrue(result.stdout.contains("kind=object"))
            assertTrue(result.stdout.contains("inherits=function"))
            assertTrue(result.stdout.contains("once.first=once-first"))
            assertTrue(result.stdout.contains("once.second=once-first"))
            assertTrue(result.stdout.contains("once.calls=1"))
            assertTrue(result.stdout.contains("nested=outer+inner"))
            assertTrue(result.stdout.contains("resolved=true"))
            assertTrue(result.stdout.contains("readLocal=fixture"))
            assertTrue(result.stdout.contains("metadata.filename=index.js"))
            assertTrue(result.stdout.contains("metadata.parent=true"))
            assertTrue(result.stdout.contains("metadata.loadedDuringRequire=false"))
            assertTrue(result.stdout.contains("metadata.cacheSame=true"))
            assertTrue(result.stdout.contains("metadata.fileVars=true"))
            assertTrue(result.stdout.contains("metadata.env=smoke"))
            assertTrue(result.stdout.contains("metadata.platformArch="))
            assertTrue(result.stdout.contains("metadata.cache.loaded=true"))
            assertTrue(result.stdout.contains("main.cache=true"))
            assertTrue(result.stdout.contains("main.parent=true"))
            assertTrue(result.stdout.contains("main.loaded=false"))
            assertTrue(result.stdout.contains("main.filename=main.js"))
            assertTrue(result.stdout.contains("main.dirname=${scriptDir.name}"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun pureJsNpmCompatibilitySmokeSuite2SupportsPackageShapesAndModuleMainChildren() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-npm-smoke-2-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create npm smoke suite 2 dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(
                    """
                    "nodejs";
                    process.env.DEBUG_LIKE = "debug-like";
                    const path = require("path");
                    const pc = require("picocolors-like");
                    const ms = require("ms-like");
                    const debug = require("debug-like");
                    const isPlainObject = require("is-plain-object-like");
                    const resolveFrom = require("resolve-from-like");
                    const mainCheck = require("./main-check");
                    console.log("pc.red=" + pc.red("x"));
                    console.log("ms.root=" + ms("2s"));
                    console.log("debug=" + debug("debug-like")("ready"));
                    console.log("plain.object=" + isPlainObject({}));
                    console.log("plain.array=" + isPlainObject([]));
                    console.log("resolve.basename=" + resolveFrom("debug-like/format").basename);
                    console.log("resolve.exists=" + resolveFrom("debug-like/format").exists);
                    console.log("main.requireMain=" + (require.main === module));
                    console.log("main.children.hasMainCheck=" + module.children.some((child) => path.basename(child.filename) === "main-check.js"));
                    console.log("child.isMain=" + mainCheck.isMain);
                    console.log("child.mainBasename=" + mainCheck.mainBasename);
                    console.log("child.parentHasChild=" + mainCheck.parentHasChild);
                    console.log("child.childrenAfter=" + mainCheck.childrenAfter);
                    console.log("child.value=" + mainCheck.childValue);
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val mainCheck = File(scriptDir, "main-check.js").apply {
                writeText(
                    """
                    const path = require("path");
                    exports.isMain = require.main === module;
                    exports.mainBasename = path.basename(require.main.filename);
                    exports.parentHasChild = Boolean(module.parent && module.parent.children.indexOf(module) >= 0);
                    const child = require("./main-child");
                    exports.childrenAfter = module.children.some((item) => path.basename(item.filename) === "main-child.js");
                    exports.childValue = child.value;
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val mainChild = File(scriptDir, "main-child.js").apply {
                writeText("""exports.value = "main-child";""", StandardCharsets.UTF_8)
            }
            val picocolorsPackageJson = File(scriptDir, "node_modules/picocolors-like/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    {
                      "name": "picocolors-like",
                      "exports": {
                        ".": {
                          "require": "./picocolors.js",
                          "default": "./picocolors.js"
                        }
                      }
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val picocolors = File(scriptDir, "node_modules/picocolors-like/picocolors.js").apply {
                writeText(
                    """
                    exports.red = function red(value) {
                      return "<red>" + value + "</red>";
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val msLike = File(scriptDir, "node_modules/ms-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    module.exports = function ms(value) {
                      const match = /^(\d+)s${'$'}/.exec(String(value));
                      return match ? String(Number(match[1]) * 1000) : String(value);
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val debugPackageJson = File(scriptDir, "node_modules/debug-like/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    {
                      "name": "debug-like",
                      "exports": {
                        ".": "./index.js",
                        "./format": "./format.js"
                      }
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val debugIndex = File(scriptDir, "node_modules/debug-like/index.js").apply {
                writeText(
                    """
                    const ms = require("ms-like");
                    const format = require("debug-like/format");
                    module.exports = function createDebug(name) {
                      return function debugLike(message) {
                        return process.env.DEBUG_LIKE === name ? format(name, message, ms("2s")) : "";
                      };
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val debugFormat = File(scriptDir, "node_modules/debug-like/format.js").apply {
                writeText(
                    """
                    module.exports = function format(name, message, delay) {
                      return name + ":" + message + ":" + delay;
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val debugNestedMs = File(scriptDir, "node_modules/debug-like/node_modules/ms-like/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    module.exports = function nestedMs(value) {
                      return "nested-" + value;
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val plainObjectPackageJson = File(scriptDir, "node_modules/is-plain-object-like/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"exports":"./index.js"}""", StandardCharsets.UTF_8)
            }
            val plainObject = File(scriptDir, "node_modules/is-plain-object-like/index.js").apply {
                writeText(
                    """
                    module.exports = function isPlainObject(value) {
                      return Object.prototype.toString.call(value) === "[object Object]";
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val resolveFromPackageJson = File(scriptDir, "node_modules/resolve-from-like/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"exports":"./index.js"}""", StandardCharsets.UTF_8)
            }
            val resolveFrom = File(scriptDir, "node_modules/resolve-from-like/index.js").apply {
                writeText(
                    """
                    const fs = require("fs");
                    const path = require("path");
                    module.exports = function resolveFromLike(name) {
                      const resolved = require.resolve(name);
                      const relative = path.relative(process.cwd(), resolved);
                      return {
                        basename: path.basename(resolved),
                        exists: fs.existsSync(relative)
                      };
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(
                    mainCheck,
                    mainChild,
                    picocolorsPackageJson,
                    picocolors,
                    msLike,
                    debugPackageJson,
                    debugIndex,
                    debugFormat,
                    debugNestedMs,
                    plainObjectPackageJson,
                    plainObject,
                    resolveFromPackageJson,
                    resolveFrom,
                ),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("pc.red=<red>x</red>"))
            assertTrue(result.stdout.contains("ms.root=2000"))
            assertTrue(result.stdout.contains("debug=debug-like:ready:nested-2s"))
            assertTrue(result.stdout.contains("plain.object=true"))
            assertTrue(result.stdout.contains("plain.array=false"))
            assertTrue(result.stdout.contains("resolve.basename=format.js"))
            assertTrue(result.stdout.contains("resolve.exists=true"))
            assertTrue(result.stdout.contains("main.requireMain=true"))
            assertTrue(result.stdout.contains("main.children.hasMainCheck=true"))
            assertTrue(result.stdout.contains("child.isMain=false"))
            assertTrue(result.stdout.contains("child.mainBasename=main.js"))
            assertTrue(result.stdout.contains("child.parentHasChild=true"))
            assertTrue(result.stdout.contains("child.childrenAfter=true"))
            assertTrue(result.stdout.contains("child.value=main-child"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

