                      }
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val probeIndex = File(scriptDir, "node_modules/pkg-probe-fs/index.js").apply {
                writeText(
                    """
                    const fs = require("fs");
                    const timing = require("#timing");
                    const realpath = require("pkg-realpath-check");
                    const access = require("pkg-access-check");
                    const lstat = require("pkg-lstat-check");
                    const jsonMain = require("pkg-json-main");
                    const selfFeature = require("pkg-probe-fs/features/a");
                    module.exports = {
                      realpathFile: realpath.file,
                      realpathNative: realpath.nativeFile,
                      access: access.fileOk && access.dirOk,
                      accessMissing: access.missingThrows,
                      lstat: lstat.file && lstat.dir,
                      timing: timing.hr && timing.bigint && timing.uptime,
                      memory: timing.memory,
                      usage: timing.cpu && timing.resource,
                      constants: [fs.constants.F_OK, fs.constants.R_OK, fs.constants.W_OK, fs.constants.X_OK].every((value) => typeof value === "number"),
                      imports: timing.imported,
                      selfFeature: selfFeature.value,
                      json: jsonMain.value,
                      resolvedFeature: require.resolve("pkg-probe-fs/features/a").endsWith("node_modules/pkg-probe-fs/features/a.js")
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val probeTiming = File(scriptDir, "node_modules/pkg-probe-fs/timing.js").apply {
                writeText(
                    """
                    const timing = require("pkg-process-timing");
                    module.exports = Object.assign({ imported: true }, timing);
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val probeFeature = File(scriptDir, "node_modules/pkg-probe-fs/features/a.js").apply {
                parentFile?.mkdirs()
                writeText("""exports.value = "self-feature-a";""", StandardCharsets.UTF_8)
            }
            val realpathCheck = File(scriptDir, "node_modules/pkg-realpath-check/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fs = require("fs");
                    module.exports = {
                      dir: fs.realpathSync("./nested/dir").endsWith("nested/dir"),
                      file: fs.realpathSync("./nested/dir/file.txt").endsWith("nested/dir/file.txt"),
                      nativeFile: fs.realpathSync.native("./nested/dir/file.txt").endsWith("nested/dir/file.txt")
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val accessCheck = File(scriptDir, "node_modules/pkg-access-check/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fs = require("fs");
                    let missingThrows = false;
                    fs.accessSync("./fixture.txt", fs.constants.R_OK);
                    fs.accessSync("./nested/dir", fs.constants.F_OK);
                    try {
                      fs.accessSync("./missing-from-package.txt");
                    } catch (error) {
                      missingThrows = String(error && error.message).includes("path does not exist");
                    }
                    module.exports = {
                      fileOk: true,
                      dirOk: true,
                      missingThrows
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val lstatCheck = File(scriptDir, "node_modules/pkg-lstat-check/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fs = require("fs");
                    module.exports = {
                      file: fs.lstatSync("./nested/dir/file.txt").isFile(),
                      dir: fs.lstatSync("./nested/dir").isDirectory()
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val processTiming = File(scriptDir, "node_modules/pkg-process-timing/index.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const hr = process.hrtime();
                    const memory = process.memoryUsage();
                    const cpu = process.cpuUsage();
                    const cpuDiff = process.cpuUsage(cpu);
                    const resource = process.resourceUsage();
                    module.exports = {
                      hr: Array.isArray(hr) && hr.length === 2,
                      bigint: typeof process.hrtime.bigint === "function" && process.hrtime.bigint() > 0n,
                      uptime: typeof process.uptime === "function" && process.uptime() >= 0,
                      memory: typeof memory.rss === "number" && typeof memory.heapTotal === "number",
                      cpu: typeof process.cpuUsage === "function" &&
                        typeof cpu.user === "number" &&
                        typeof cpu.system === "number" &&
                        typeof cpuDiff.user === "number" &&
                        typeof cpuDiff.system === "number",
                      resource: typeof process.resourceUsage === "function" &&
                        typeof resource.userCPUTime === "number" &&
                        typeof resource.systemCPUTime === "number" &&
                        typeof resource.maxRSS === "number"
                    };
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val jsonMainPackageJson = File(scriptDir, "node_modules/pkg-json-main/package.json").apply {
                parentFile?.mkdirs()
                writeText("""{"main":"data.json"}""", StandardCharsets.UTF_8)
            }
            val jsonMain = File(scriptDir, "node_modules/pkg-json-main/data.json").apply {
                writeText("""{"value":"json-main"}""", StandardCharsets.UTF_8)
            }
            val patternPackageJson = File(scriptDir, "node_modules/pkg-exports-pattern-realpath/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    {
                      "name": "pkg-exports-pattern-realpath",
                      "exports": {
                        ".": "./index.js",
                        "./features/*": "./dist/features/*.js"
                      }
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            val patternIndex = File(scriptDir, "node_modules/pkg-exports-pattern-realpath/index.js").apply {
                writeText("""exports.root = true;""", StandardCharsets.UTF_8)
            }
            val patternFeature = File(scriptDir, "node_modules/pkg-exports-pattern-realpath/dist/features/a.js").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    const fs = require("fs");
                    exports.realpath = fs.realpathSync("./nested/dir/file.txt").endsWith("nested/dir/file.txt");
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }

            val result = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = moduleSourcesFor(
                    probePackageJson,
                    probeIndex,
                    probeTiming,
                    probeFeature,
                    realpathCheck,
                    accessCheck,
                    lstatCheck,
                    processTiming,
                    jsonMainPackageJson,
                    jsonMain,
                    patternPackageJson,
                    patternIndex,
                    patternFeature,
                ),
            )

            assertTrue(result.errorMessage.orEmpty(), result.succeeded)
            assertTrue(result.stdout.contains("probe.realpath.file=true"))
            assertTrue(result.stdout.contains("probe.realpath.native=true"))
            assertTrue(result.stdout.contains("probe.access=true"))
            assertTrue(result.stdout.contains("probe.access.missing=true"))
            assertTrue(result.stdout.contains("probe.lstat=true"))
            assertTrue(result.stdout.contains("probe.timing=true"))
            assertTrue(result.stdout.contains("probe.memory=true"))
            assertTrue(result.stdout.contains("probe.usage=true"))
            assertTrue(result.stdout.contains("probe.constants=true"))
            assertTrue(result.stdout.contains("probe.imports=true"))
            assertTrue(result.stdout.contains("probe.selfFeature=self-feature-a"))
            assertTrue(result.stdout.contains("probe.json=json-main"))
            assertTrue(result.stdout.contains("feature.realpath=true"))
            assertTrue(result.stdout.contains("json.main=json-main"))
            assertTrue(result.stdout.contains("resolve.logical=true"))
            assertTrue(result.stdout.contains("resolve.afterRealpath=true"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun commonJsNodeModulesRejectsUnsafePackageSpecifiers() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-node-modules-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create node_modules deny test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(""""nodejs";""", StandardCharsets.UTF_8)
            }

            val escape = runEmbeddedScript(
                source = """require("pkg/../../outside");""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )
            assertFalse(escape.succeeded)
            assertEquals("Error", escape.errorName)
            assertTrue(escape.errorMessage.orEmpty().contains("package subpath escapes"))
            assertTrue(escape.errorMessage.orEmpty().contains("pkg/../../outside"))

            settleEmbeddedScriptServiceProcess()

            val protocol = runEmbeddedScript(
                source = """require("file:pkg");""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )
            assertFalse(protocol.succeeded)
            assertEquals("Error", protocol.errorName)
            assertTrue(protocol.errorMessage.orEmpty().contains("rejects protocol specifier"))
            assertTrue(protocol.errorMessage.orEmpty().contains("file:pkg"))

            settleEmbeddedScriptServiceProcess()

            val scoped = runEmbeddedScript(
                source = """require("@scope");""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )
            assertFalse(scoped.succeeded)
            assertEquals("Error", scoped.errorName)
            assertTrue(scoped.errorMessage.orEmpty().contains("Invalid Embedded Node scoped package specifier"))
            assertTrue(scoped.errorMessage.orEmpty().contains("@scope"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

    @Test
