        }
    }

    @Test
    fun commonJsLocalRequireRejectsMissingEscapeAndUnsupportedModules() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-commonjs-deny-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create CommonJS deny test dir: $absolutePath" }
        }
        try {
            val main = File(scriptDir, "main.js").apply {
                writeText(""""nodejs";""", StandardCharsets.UTF_8)
            }

            val missing = runEmbeddedScript(
                source = """require("./missing");""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )
            assertFalse(missing.succeeded)
            assertEquals("Error", missing.errorName)
            assertTrue(missing.errorMessage.orEmpty().contains("Cannot find Embedded Node local module"))
            assertTrue(missing.errorMessage.orEmpty().contains("./missing"))

            settleEmbeddedScriptServiceProcess()

            val escape = runEmbeddedScript(
                source = """require("../outside.js");""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )
            assertFalse(escape.succeeded)
            assertEquals("Error", escape.errorName)
            assertTrue(escape.errorMessage.orEmpty().contains("Relative require escapes Embedded Node working directory"))
            assertTrue(escape.errorMessage.orEmpty().contains("../outside.js"))

            settleEmbeddedScriptServiceProcess()

            val unsupported = runEmbeddedScript(
                source = """require("./native.node");""",
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
            )
            assertFalse(unsupported.succeeded)
            assertEquals("Error", unsupported.errorName)
            assertTrue(unsupported.errorMessage.orEmpty().contains("Unsupported Embedded Node local module extension"))
            assertTrue(unsupported.errorMessage.orEmpty().contains("./native.node"))
        } finally {
            scriptDir.deleteRecursively()
        }
    }

