            }
            File(scriptDir, "node_modules/exports-sub/sub.js").writeText(
                """
                const leaf = require("./leaf");
                module.exports = "exports-sub+" + leaf.value;
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "node_modules/exports-sub/leaf.js").writeText(
                """exports.value = "leaf";""",
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "node_modules/self-engine/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    {
                      "name": "self-engine",
                      "exports": {
                        ".": "./index.js",
                        "./sub": "./sub.js"
                      }
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            File(scriptDir, "node_modules/self-engine/index.js").writeText(
                """module.exports = "self-engine+" + require("self-engine/sub").value;""",
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "node_modules/self-engine/sub.js").writeText(
                """exports.value = "sub";""",
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "node_modules/self-engine/node_modules/self-engine/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """
                    {
                      "name": "self-engine",
                      "exports": {
                        ".": "./wrong.js",
                        "./sub": "./wrong.js"
                      }
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            File(scriptDir, "node_modules/self-engine/node_modules/self-engine/wrong.js").writeText(
                """exports.value = "wrong";""",
                StandardCharsets.UTF_8,
            )
            main.writeText(
                """
                "nodejs";
                const helper = require("./helper");
                const data = require("./data.json");
                const lib = require("./lib");
                const pkg = require("./pkg");
                const nodeModule = require("a");
                const exportsRoot = require("exports-root");
                const exportsSub = require("exports-sub/sub");
                const exportsPattern = require("exports-pattern/feature/a");
                const rootImport = require("#engine-root");
                const importsEngine = require("imports-engine");
                const selfEngine = require("self-engine");
                if (helper.value !== "helper:nested") {
                  throw new Error("helper mismatch: " + helper.value);
                }
                if (data.name !== "engine") {
                  throw new Error("data mismatch: " + data.name);
                }
                if (lib.name !== "engine-lib-index") {
                  throw new Error("lib mismatch: " + lib.name);
                }
                if (pkg.answer !== 42) {
                  throw new Error("pkg mismatch: " + pkg.answer);
                }
                if (nodeModule !== "a+b-nested") {
                  throw new Error("node_modules mismatch: " + nodeModule);
                }
                if (exportsRoot.value !== "exports-root") {
                  throw new Error("exports root mismatch: " + exportsRoot.value);
                }
                if (exportsSub !== "exports-sub+leaf") {
                  throw new Error("exports sub mismatch: " + exportsSub);
                }
                if (exportsPattern !== "exports-pattern+leaf") {
                  throw new Error("exports pattern mismatch: " + exportsPattern);
                }
                if (rootImport.value !== "root-import+leaf+util") {
                  throw new Error("root import mismatch: " + rootImport.value);
                }
                if (importsEngine !== "imports-engine+leaf") {
                  throw new Error("imports engine mismatch: " + importsEngine);
                }
                if (selfEngine !== "self-engine+sub") {
                  throw new Error("self engine mismatch: " + selfEngine);
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )

            val engine = NativeNodeEmbeddedJavaScriptEngine(context)
            assertEquals(0, engine.doExecution(JavaScriptFileSource(main)))
        } finally {
            runCatching { RhinoContext.exit() }
            scriptDir.deleteRecursively()
        }
    }

    @Test
    fun fileEnginePreloaderSupportsStaticRequireCommentAndModuleRequireShapes() {
        assumeEmbeddedScriptExecutionEnabled()

        val scriptDir = File(context.cacheDir, "embedded-commonjs-preloader-shapes-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create CommonJS preloader shape test dir: $absolutePath" }
        }
        val main = File(scriptDir, "main.js")
        try {
            main.writeText(
                """
                "nodejs";
                const multiline = require(
                  "./multiline"
                );
                const commented = require /* block comment */ ("./commented");
                const lineCommented = require // line comment
                ("./line-commented");
                const viaModule = module.require("./module-require");
                const pkg = module.require("preload-shapes");
                if (false) {
                  const r = require;
                  r("./alias-hidden");
                  require("./" + "concat-hidden");
                }
                if (multiline.value !== "multiline") {
                  throw new Error("multiline mismatch: " + multiline.value);
                }
                if (commented.value !== "commented+nested") {
                  throw new Error("commented mismatch: " + commented.value);
                }
                if (lineCommented.value !== "line-commented") {
                  throw new Error("line commented mismatch: " + lineCommented.value);
                }
                if (viaModule.value !== "module-require") {
                  throw new Error("module.require mismatch: " + viaModule.value);
                }
                if (pkg.value !== "pkg+leaf") {
                  throw new Error("package mismatch: " + pkg.value);
                }
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "multiline.js").writeText("""exports.value = "multiline";""", StandardCharsets.UTF_8)
            File(scriptDir, "commented.js").writeText(
                """
                const nested = require /* nested comment */ ("./nested");
                exports.value = "commented+" + nested.value;
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "nested.js").writeText("""exports.value = "nested";""", StandardCharsets.UTF_8)
            File(scriptDir, "line-commented.js").writeText(
                """exports.value = "line-commented";""",
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "module-require.js").writeText(
                """exports.value = "module-require";""",
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "node_modules/preload-shapes/package.json").apply {
                parentFile?.mkdirs()
                writeText(
                    """{"name":"preload-shapes","exports":{"require":"./index.js","default":"./index.js"}}""",
                    StandardCharsets.UTF_8,
                )
            }
            File(scriptDir, "node_modules/preload-shapes/index.js").writeText(
                """
                const leaf = require /* package comment */ ("./leaf");
                exports.value = "pkg+" + leaf.value;
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "node_modules/preload-shapes/leaf.js").writeText(
                """exports.value = "leaf";""",
                StandardCharsets.UTF_8,
            )
            File(scriptDir, "alias-hidden.js").writeText("""throw new Error("alias hidden should not preload");""", StandardCharsets.UTF_8)
            File(scriptDir, "concat-hidden.js").writeText("""throw new Error("concat hidden should not preload");""", StandardCharsets.UTF_8)

            val engine = NativeNodeEmbeddedJavaScriptEngine(context)
            assertEquals(0, engine.doExecution(JavaScriptFileSource(main)))
            val diagnostics = engine.lastCommonJsPreloadDiagnostics
            assertEquals(8, diagnostics.moduleCount)
            assertEquals(1, diagnostics.packageJsonCount)
            assertEquals(0, diagnostics.jsonModuleCount)
            assertEquals(7, diagnostics.staticRequireCount)
            assertEquals(1, diagnostics.dynamicRequireIgnoredCount)
            assertEquals(0, diagnostics.unresolvedStaticRequireCount)
            assertTrue(
                diagnostics.moduleSourceNames.none {
                    it.replace('\\', '/').endsWith("/alias-hidden.js") ||
                            it.replace('\\', '/').endsWith("/concat-hidden.js")
                },
            )
        } finally {
            runCatching { RhinoContext.exit() }
            scriptDir.deleteRecursively()
        }
    }

