        val main = File(scriptDir, "main.js")
        try {
            main.writeText(
                """
                "nodejs";
                const target = "./dynamic-child";
                const child = require(target);
                console.log("dynamic.child=" + child.value);
                """.trimIndent(),
                StandardCharsets.UTF_8,
            )
            val child = File(scriptDir, "dynamic-child.js").apply {
                writeText("""exports.value = "loaded";""", StandardCharsets.UTF_8)
            }

            val engine = NativeNodeEmbeddedJavaScriptEngine(context)
            assertEquals(0, engine.doExecution(JavaScriptFileSource(main)))
            val diagnostics = engine.lastCommonJsPreloadDiagnostics
            assertEquals(0, diagnostics.moduleCount)
            assertEquals(0, diagnostics.staticRequireCount)
            assertEquals(1, diagnostics.dynamicRequireIgnoredCount)

            settleEmbeddedScriptServiceProcess()

            val explicit = runEmbeddedScript(
                source = main.readText(StandardCharsets.UTF_8),
                sourceName = main.canonicalPath,
                workingDirectory = scriptDir.canonicalPath,
                moduleSources = mapOf(child.canonicalPath to """exports.value = "explicit";"""),
            )
            assertTrue(explicit.errorMessage.orEmpty(), explicit.succeeded)
            assertTrue(explicit.stdout.contains("dynamic.child=explicit"))
            assertEquals("0", explicit.nativeValues["embedded_script.dynamic_require_fallback_loaded_count"])
        } finally {
            runCatching { RhinoContext.exit() }
            scriptDir.deleteRecursively()
        }
    }

