    @Test
    fun errorEnvelopeCompletenessCoversCommonFailureKinds() {
        assumeEmbeddedScriptExecutionEnabled()

        val runtime = runEmbeddedScript(
            """throw new Error("envelope runtime boom");""",
            "<embedded-envelope-runtime-source.js>",
        )
        assertErrorEnvelope(
            result = runtime,
            sourceName = "<embedded-envelope-runtime-source.js>",
            errorName = "Error",
            messageToken = "envelope runtime boom",
            errorCode = null,
        )
        assertTrue(runtime.errorStack.orEmpty().contains("<embedded-envelope-runtime-source.js>"))
        assertEquals(context.cacheDir.absolutePath, runtime.workingDirectory)
        assertEquals(false, runtime.pendingTimers)
        assertEquals(0, runtime.pendingTimerCount ?: -1)

        settleEmbeddedScriptServiceProcess()

        val promise = runEmbeddedScript(
            """Promise.reject(new Error("envelope promise boom"));""",
            "<embedded-envelope-promise-source.js>",
        )
        assertErrorEnvelope(
            result = promise,
            sourceName = "<embedded-envelope-promise-source.js>",
            errorName = "Error",
            messageToken = "envelope promise boom",
            errorCode = null,
        )

        settleEmbeddedScriptServiceProcess()

        val disabledBuiltin = runEmbeddedScript(
            """require("child_process");""",
            "<embedded-envelope-disabled-builtin-source.js>",
        )
        assertErrorEnvelope(
            result = disabledBuiltin,
            sourceName = "<embedded-envelope-disabled-builtin-source.js>",
            errorName = "Error",
            messageToken = "child_process",
            errorCode = "ERR_AUTOJS6_EMBEDDED_NODE_BUILTIN_DISABLED",
        )

        settleEmbeddedScriptServiceProcess()

        val esmSource = File(context.cacheDir, "embedded-envelope-esm-source.mjs").absolutePath
        val esmJson = File(context.cacheDir, "embedded-envelope-data.json").absolutePath
        val esm = runEmbeddedScript(
            """import data from "./embedded-envelope-data.json"; console.log(data);""",
            esmSource,
            moduleSources = mapOf(esmJson to """{"value":1}"""),
        )
        assertErrorEnvelope(
            result = esm,
            sourceName = esmSource,
            errorName = "Error",
            messageToken = """requires with { type: "json" }""",
            errorCode = "ERR_AUTOJS6_EMBEDDED_NODE_ESM_UNSUPPORTED",
        )

        settleEmbeddedScriptServiceProcess()

        val timeout = runEmbeddedScript(
            """
            "nodejs";
            setInterval(() => {}, 100);
            """.trimIndent(),
            "<embedded-envelope-timeout-source.js>",
            timeoutMs = 900L,
        )
        assertErrorEnvelope(
            result = timeout,
            sourceName = "<embedded-envelope-timeout-source.js>",
            errorName = "EmbeddedScriptTimeoutError",
            messageToken = "Embedded Node.js script timed out after 900ms",
            errorCode = "ERR_AUTOJS6_EMBEDDED_NODE_SCRIPT_TIMEOUT",
            expectedExitCode = 124,
            timedOut = true,
        )
        assertEquals(900L, timeout.timeoutMs ?: -1L)
        assertEquals(true, timeout.pendingTimers)
    }

    @Test
