            ),
        )
    }

    @Test
    fun fileEngineRunsTypeNodeProjectThroughProjectRunnerWithProjectRootCwd() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-type-node-project-runner-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create type=node project dir: $absolutePath" }
        }
        try {
            File(projectRoot, "project.json").writeText("""{"type":"node"}""", StandardCharsets.UTF_8)
            File(projectRoot, "root.txt").writeText("root-file", StandardCharsets.UTF_8)
            File(projectRoot, "node_modules/root-pkg/index.js").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText("""exports.value = "root-pkg";""" + "\n", StandardCharsets.UTF_8)
            }
            val entry = File(projectRoot, "packages/app/main.js").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText(
                    """
                    "nodejs";
                    const fs = require("fs");
                    const normalizeDataPath = (value) => String(value).replace(/^\/data\/user\/0\//, "/data/data/");
                    const rootPkg = require("root-pkg");
                    const ready =
                      process.cwd() === ${jsStringLiteral(projectRoot.canonicalPath)} &&
                      fs.readFileSync("./root.txt", "utf8") === "root-file" &&
                      rootPkg.value === "root-pkg" &&
                      require.main === module &&
                      module.parent === null &&
                      normalizeDataPath(process.argv[1]) === normalizeDataPath(__filename);
                    fs.writeFileSync("./type-node-project-runner.txt", ready ? "ok" : "bad", "utf8");
                    console.log("type.node.project.runner.ready=" + ready);
                    """.trimIndent() + "\n",
                    StandardCharsets.UTF_8,
                )
            }

            val engine = NativeNodeEmbeddedJavaScriptEngine(context)
            assertEquals(0, engine.doExecution(JavaScriptFileSource(entry)))
            val descriptor = engine.lastNodeProjectRunnerDescriptor
            assertEquals("entry", descriptor?.kind)
            assertEquals(projectRoot.canonicalPath, descriptor?.projectRoot)
            assertEquals(entry.canonicalPath, descriptor?.entryFile)
            assertEquals(projectRoot.canonicalPath, descriptor?.workingDirectory)
            val nativeValues = engine.lastEmbeddedScriptResultNativeValues
            assertEquals("entry", nativeValues["embedded_project_runner.kind"])
            assertEquals(projectRoot.canonicalPath, nativeValues["embedded_project_runner.project_root"])
            assertEquals(entry.canonicalPath, nativeValues["embedded_project_runner.entry_file"])
            assertEquals(projectRoot.canonicalPath, nativeValues["embedded_project_runner.working_directory"])
            assertEquals(
                "ok",
                File(projectRoot, "type-node-project-runner.txt").readText(StandardCharsets.UTF_8),
            )
        } finally {
            runCatching { RhinoContext.exit() }
            projectRoot.deleteRecursively()
        }
    }

