    @Test
    fun fileEngineTypeNodeProjectRunnerPreloadsStaticCommonJsGraphWithDiagnostics() {
        assumeEmbeddedScriptExecutionEnabled()

        val projectRoot = File(context.cacheDir, "embedded-type-node-project-preload-${System.nanoTime()}").apply {
            check(mkdirs()) { "Failed to create type=node preload project dir: $absolutePath" }
        }
        try {
            File(projectRoot, "project.json").writeText("""{"type":"node"}""", StandardCharsets.UTF_8)
            val entry = File(projectRoot, "packages/app/main.js").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText(
                    """
                    "nodejs";
                    const helper = require("./lib/helper");
                    const rootPkg = require("root-pkg");
                    console.log("type.node.preload.ready=" + (
                      helper.value === "helper+nested" &&
                      rootPkg.value === "root-pkg"
                    ));
                    """.trimIndent() + "\n",
                    StandardCharsets.UTF_8,
                )
            }
            File(projectRoot, "packages/app/lib/helper.js").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText(
                    """
                    const nested = require("./nested");
                    exports.value = "helper+" + nested.value;
                    """.trimIndent() + "\n",
                    StandardCharsets.UTF_8,
                )
            }
            File(projectRoot, "packages/app/lib/nested.js").writeText(
                """exports.value = "nested";""" + "\n",
                StandardCharsets.UTF_8,
            )
            File(projectRoot, "node_modules/root-pkg/package.json").apply {
                parentFile?.let { parent -> check(parent.mkdirs() || parent.isDirectory) }
                writeText("""{"name":"root-pkg","main":"./index.js"}""", StandardCharsets.UTF_8)
            }
            File(projectRoot, "node_modules/root-pkg/index.js").writeText(
                """exports.value = "root-pkg";""" + "\n",
                StandardCharsets.UTF_8,
            )

            val engine = NativeNodeEmbeddedJavaScriptEngine(context)
            assertEquals(0, engine.doExecution(JavaScriptFileSource(entry)))

            val diagnostics = engine.lastCommonJsPreloadDiagnostics
            val moduleNames = diagnostics.moduleSourceNames.map { it.replace('\\', '/') }

            assertTrue("Expected project runner preload output", diagnostics.moduleCount >= 3)
            assertTrue("Expected static require diagnostics", diagnostics.staticRequireCount >= 3)
            assertEquals(0, diagnostics.dynamicRequireIgnoredCount)
            assertTrue(moduleNames.any { it.endsWith("/packages/app/lib/helper.js") })
            assertTrue(moduleNames.any { it.endsWith("/packages/app/lib/nested.js") })
            assertTrue(moduleNames.any { it.endsWith("/node_modules/root-pkg/index.js") })
        } finally {
            runCatching { RhinoContext.exit() }
            projectRoot.deleteRecursively()
        }
    }

