    @Test
    fun nativeOneShotStillRunsProcessVersion() {
        val scriptFile = File(context.cacheDir, "native-node-version-${System.nanoTime()}.js")
        scriptFile.writeText("console.log(process.version);\n", StandardCharsets.UTF_8)
        val stdout = StringBuilder()
        val stderr = StringBuilder()
        val sink = object : NativeNodeRuntimeBridge.OutputSink {
            override fun onStdout(bytes: ByteArray) {
                stdout.append(bytes.toString(StandardCharsets.UTF_8))
            }

            override fun onStderr(bytes: ByteArray) {
                stderr.append(bytes.toString(StandardCharsets.UTF_8))
            }
        }

        try {
            val exitCode = NativeNodeProcessService.run(
                context = context,
                argv = arrayOf("autojs6-node", scriptFile.absolutePath),
                workingDirectory = scriptFile.parent,
                outputSink = sink,
            )

            assertEquals(stderr.toString(), 0, exitCode)
            assertTrue(stdout.toString().contains("v24.5.0"))
        } finally {
            scriptFile.delete()
        }
    }

    private fun runEmbeddedScript(
        source: String,
        sourceName: String = "<embedded-mvp-test.js>",
        workingDirectory: String? = context.cacheDir.absolutePath,
        timeoutMs: Long = 5000L,
        moduleSources: Map<String, String> = emptyMap(),
        runtimeModuleSources: Map<String, String> = emptyMap(),
        env: Map<String, String> = emptyMap(),
        workerThreadsExperimentalEnabled: Boolean = BuildConfig.NODEJS_WORKER_THREADS_EXPERIMENTAL_ENABLED,
    ): NativeNodeEmbeddedRuntimeBridge.EmbeddedScriptResult {
        return NativeNodeEmbeddedScriptService.runScript(
            context,
            NativeNodeEmbeddedRuntimeBridge.EmbeddedScriptRequest(
                source = source,
                sourceName = sourceName,
                workingDirectory = workingDirectory,
                timeoutMs = timeoutMs,
                env = env,
                moduleSources = moduleSources,
                runtimeModuleSources = runtimeModuleSources,
                workerThreadsExperimentalEnabled = workerThreadsExperimentalEnabled,
            ),
        )
    }

    private data class NodeProjectRunRequest(
        val projectRoot: File,
        val entryFile: File,
        val workingDirectory: File = projectRoot,
        val argv: List<String> = emptyList(),
        val env: Map<String, String> = emptyMap(),
        val timeoutMs: Long = 5000L,
        val moduleSources: Map<String, String> = emptyMap(),
        val runtimeModuleSources: Map<String, String> = emptyMap(),
        val entrySource: String? = null,
    )

    private fun runNodeProject(
        request: NodeProjectRunRequest,
    ): NativeNodeEmbeddedRuntimeBridge.EmbeddedScriptResult {
        return NativeNodeEmbeddedProjectRunner.run(context, request.toProjectRunnerRequest())
    }

    private fun describeNodeProjectRun(
        request: NodeProjectRunRequest,
        result: NativeNodeEmbeddedRuntimeBridge.EmbeddedScriptResult,
    ): String {
        return NativeNodeEmbeddedProjectRunner.describe(request.toProjectRunnerRequest(), result)
    }

    private fun NodeProjectRunRequest.toProjectRunnerRequest(): NativeNodeEmbeddedProjectRunner.Request {
        return NativeNodeEmbeddedProjectRunner.Request(
            projectRoot = projectRoot,
            entryFile = entryFile,
            workingDirectory = workingDirectory,
            argv = argv,
            env = env,
            timeoutMs = timeoutMs,
            moduleSources = moduleSources,
            runtimeModuleSources = runtimeModuleSources,
            entrySource = entrySource,
        )
    }

    private fun projectLauncherMainScriptFile(launcher: ProjectLauncher): File {
        val field = ProjectLauncher::class.java.getDeclaredField("mMainScriptFile")
        field.isAccessible = true
        return field.get(launcher) as File
    }

    private fun projectLauncherMainScriptLaunch(launcher: ProjectLauncher): ScriptLaunchSourceFactory.Launch {
        val method = ProjectLauncher::class.java.getDeclaredMethod("createMainScriptLaunch")
        method.isAccessible = true
        return try {
            method.invoke(launcher) as ScriptLaunchSourceFactory.Launch
        } catch (e: InvocationTargetException) {
            throw e.targetException
        }
    }

    private fun clearProjectLauncherLogcat() {
        runCatching { shellOutput("logcat -c") }
    }

    private fun clearEmbeddedNodeLifecycleLogcat() {
        runCatching { shellOutput("logcat -c") }
    }

    private fun waitForEmbeddedNodeLifecycleLogcatMarkers(markers: List<String>, timeoutMs: Long = 5000L): String {
        val deadline = SystemClock.elapsedRealtime() + timeoutMs
        var latest = ""
        do {
            latest = shellOutput("logcat -d -v time -s NativeNodeEmbeddedScriptService:I")
            if (markers.all { marker -> latest.contains(marker) }) {
                return latest
            }
            SystemClock.sleep(100L)
        } while (SystemClock.elapsedRealtime() < deadline)
        return latest
    }

    private fun waitForProjectLauncherLogcatMarkers(markers: List<String>, timeoutMs: Long = 5000L): String {
        val deadline = SystemClock.elapsedRealtime() + timeoutMs
        var latest = ""
        do {
            latest = shellOutput("logcat -d -v time -s ProjectLauncher:E")
            if (markers.all { marker -> latest.contains(marker) }) {
                return latest
            }
            SystemClock.sleep(100L)
        } while (SystemClock.elapsedRealtime() < deadline)
        return latest
    }

    private fun waitForFileText(file: File, timeoutMs: Long = 10_000L): String {
        val deadline = SystemClock.elapsedRealtime() + timeoutMs
        do {
            if (file.isFile) {
                return file.readText(StandardCharsets.UTF_8)
            }
            SystemClock.sleep(100L)
        } while (SystemClock.elapsedRealtime() < deadline)
        throw AssertionError("Timed out waiting for file: ${file.absolutePath}")
    }

    private fun shellOutput(command: String): String {
        val descriptor = InstrumentationRegistry.getInstrumentation()
            .uiAutomation
            .executeShellCommand(command)
        return ParcelFileDescriptor.AutoCloseInputStream(descriptor).use { input ->
            input.bufferedReader(StandardCharsets.UTF_8).readText()
        }
    }

