        assertTrue(json.getBoolean("process"))
        assertTrue(json.getBoolean("constants"))
        assertTrue(json.getBoolean("exports"))
        assertTrue(json.getBoolean("imports"))
        assertTrue(json.getBoolean("nested"))
        assertTrue(json.getBoolean("cache"))
        assertTrue(json.getBoolean("shadowBlocked"))
    }

