        )
        File(toolDir, "index.js").writeText(
            """
            exports.value = "discover-tool";
            exports.summary = require("#internal/summary").value;
            """.trimIndent() + "\n",
            StandardCharsets.UTF_8,
        )
        File(toolDir, "cli.js").writeText(
            """
            #!/usr/bin/env node
            "nodejs";
            const path = require("path");
            const processBuiltin = require("process");
            const runner = require("#internal/runner");

            function argValue(flag) {
              const index = process.argv.indexOf(flag);
              return index >= 0 ? process.argv[index + 1] : undefined;
            }

            async function main() {
              const startArg = argValue("--start") || ".";
              const outArg = argValue("--out") || "discovery-result.json";
              const nameArg = argValue("--name") || "discoverTool";
              processBuiltin.chdir(startArg);
              const startOk =
                path.basename(processBuiltin.cwd()) === "deep" &&
                processBuiltin.argv[0] === "autojs6-node" &&
