              const result = await runner.run(nameArg, outArg);
              const ready = startOk && result.ready;
              console.log("discovery.cli.ready=" + ready);
              console.log("discovery.cli.type=" + result.type);
              console.log("discovery.cli.start=" + startOk);
              console.log("discovery.cli.find_up=" + result.findUp);
              console.log("discovery.cli.package_json=" + result.packageJson);
              console.log("discovery.cli.create_require=" + result.createRequire);
              console.log("discovery.cli.plugin=" + result.plugin);
              console.log("discovery.cli.scoped=" + result.scoped);
              console.log("discovery.cli.exports=" + result.exports);
              console.log("discovery.cli.imports=" + result.imports);
              console.log("discovery.cli.nested=" + result.nested);
              console.log("discovery.cli.cache=" + result.cache);
              console.log("discovery.cli.output=" + result.output);
            }

            return main();
            """.trimIndent() + "\n",
            StandardCharsets.UTF_8,
        )
        File(toolDir, "lib").mkdirs()
        File(toolDir, "lib/summary.js").writeText(
            """
            exports.value = "summary";
            """.trimIndent() + "\n",
            StandardCharsets.UTF_8,
        )
        File(toolDir, "lib/runner.js").writeText(
            """
            const fs = require("fs");
            const fsp = require("fs/promises");
            const path = require("path");
            const processBuiltin = require("process");
            const constantsBuiltin = require("constants");
            const { Buffer } = require("buffer");
            const { pathToFileURL, fileURLToPath } = require("url");
            const { createRequire } = require("module");
            const explorer = require("cosmiconfig-lite");
            const summary = require("#internal/summary");

            exports.run = async function(name, outPath) {
              const loaded = await explorer.search(name);
              const config = loaded.config;
              const configRequire = loaded.require;
              const inputPath = path.join(loaded.configDir, config.input || "src/input.txt");
              const inputUrl = pathToFileURL(inputPath);
              const input = (await fsp.readFile(inputUrl, "utf8")).trim();
              processBuiltin.env.DISCOVER_PLUGIN = config.plugin;
              const plugin = configRequire(config.plugin);
              const pluginAgain = createRequire(loaded.configFile)(config.plugin);
              const scoped = configRequire(config.scopedPlugin);
              const formatter = require("./formatters/" + (config.formatter || "json"));
              const self = require("discover-tool");
              const alpha = plugin.transform(config, input);
              const scopedResult = scoped.apply(config, input);
              const pluginPath = configRequire.resolve(config.plugin);
              const scopedPath = configRequire.resolve(config.scopedPlugin);
              const cacheOk =
                require.cache[pluginPath] &&
                require.cache[pluginPath].exports === plugin &&
                require.cache[scopedPath] &&
                require.cache[scopedPath].exports === scoped &&
                pluginAgain === plugin;
              const outputDir = path.dirname(outPath);
              if (outputDir && outputDir !== ".") {
                await fsp.mkdir(outputDir, { recursive: true });
              }
              const outUrl = pathToFileURL(outPath);
              const payload = {
                name: config.name,
                type: loaded.type,
                input,
                alpha: alpha.alpha,
                scoped: scopedResult.scoped,
                process: alpha.processOk && scopedResult.processOk,
                constants: alpha.constantsOk && scopedResult.constantsOk && constantsBuiltin.F_OK === fs.constants.F_OK,
                buffer: Buffer.from(input, "utf8").toString("utf8") === input,
                exports: self.value === "discover-tool" && self.summary === "summary",
                imports: summary.value === "summary",
                nested: alpha.helper === "discover-helper",
                cache: cacheOk,
                shadowBlocked: plugin.shadow !== true,
                url: fileURLToPath(outUrl).replace(/\\/g, "/").endsWith(outPath.replace(/\\/g, "/").replace(/^(\.\.\/)+/, "")),
                configPath: loaded.configFile.replace(/\\/g, "/")
              };
              await fsp.writeFile(outUrl, Buffer.from(formatter.format(payload), "utf8"));
              const written = JSON.parse(await fsp.readFile(outUrl, "utf8"));
              return {
                type: loaded.type,
                ready:
                  written.name === "AutoJs6" &&
                  written.input === "hello discovery" &&
                  written.alpha === "HELLO DISCOVERY" &&
                  written.scoped === true &&
                  written.process === true &&
                  written.constants === true &&
                  written.buffer === true &&
                  written.exports === true &&
                  written.imports === true &&
                  written.nested === true &&
                  written.cache === true &&
                  written.shadowBlocked === true &&
                  fs.existsSync(outPath),
                findUp: loaded.candidates.length > 0 && loaded.configFile.length > 0,
                packageJson: loaded.type === "package-json",
                createRequire: typeof configRequire.resolve === "function",
                plugin: alpha.alpha === "HELLO DISCOVERY" && alpha.processOk && alpha.constantsOk && plugin.shadow !== true,
                scoped: scopedResult.scoped === true && scopedResult.self === "scoped-self",
                exports: self.value === "discover-tool",
                imports: summary.value === "summary",
                nested: alpha.helper === "discover-helper",
                cache: cacheOk,
                output: fs.existsSync(outPath)
              };
            };
            """.trimIndent() + "\n",
            StandardCharsets.UTF_8,
        )
        File(toolDir, "lib/formatters").mkdirs()
        File(toolDir, "lib/formatters/json.js").writeText(
            """
            exports.format = function(payload) {
              return JSON.stringify(payload);
            };
            """.trimIndent() + "\n",
            StandardCharsets.UTF_8,
        )
        writeDiscoverySupportPackages(toolDir)
        return toolDir
    }

    private fun writeDiscoverySupportPackages(toolDir: File) {
        val modulesDir = File(toolDir, "node_modules").apply {
            check(mkdirs()) { "Failed to create discover-tool node_modules dir: $absolutePath" }
        }

        val findUpDir = File(modulesDir, "find-up-lite").apply {
            check(mkdirs()) { "Failed to create find-up-lite package dir: $absolutePath" }
        }
        File(findUpDir, "package.json").writeText(
            """{"name":"find-up-lite","version":"1.0.0","exports":{".":"./index.js"}}""",
            StandardCharsets.UTF_8,
        )
        File(findUpDir, "index.js").writeText(
            """
            const fsp = require("fs/promises");
            const pathExists = require("path-exists-lite");

            function joinCandidate(prefix, name) {
              return prefix ? prefix + "/" + name : name;
            }

            exports.findUp = async function(candidates, options) {
              const packageField = options && options.packageField || "discoverTool";
              const tried = [];
              let prefix = "";
              for (let depth = 0; depth < 16; depth += 1) {
                for (const name of candidates) {
                  const candidate = joinCandidate(prefix, name);
                  tried.push(candidate);
                  try {
                    if (await pathExists.exists(candidate)) {
                      return { path: candidate, kind: name === "package.json" ? "package" : "file", candidates: tried, nested: pathExists.value };
                    }
                  } catch (error) {
                    const message = String(error && error.message || error);
                    if (message.includes("escapes working directory") || message.includes("EPERM")) {
                      return { path: null, kind: "missing", candidates: tried, denied: message, nested: pathExists.value };
                    }
                  }
                }
                const packageJson = joinCandidate(prefix, "package.json");
                tried.push(packageJson + "#" + packageField);
                try {
                  if (await pathExists.exists(packageJson)) {
                    return { path: packageJson, kind: "package", candidates: tried, nested: pathExists.value };
                  }
                } catch (error) {
                  const message = String(error && error.message || error);
                  if (message.includes("escapes working directory") || message.includes("EPERM")) {
                    return { path: null, kind: "missing", candidates: tried, denied: message, nested: pathExists.value };
                  }
                }
                prefix = prefix ? prefix + "/.." : "..";
              }
              return { path: null, kind: "missing", candidates: tried, nested: pathExists.value };
            };
            """.trimIndent() + "\n",
            StandardCharsets.UTF_8,
        )
        val pathExistsDir = File(findUpDir, "node_modules/path-exists-lite").apply {
            check(mkdirs()) { "Failed to create path-exists-lite nested package dir: $absolutePath" }
        }
        File(pathExistsDir, "package.json").writeText(
            """{"name":"path-exists-lite","version":"1.0.0","exports":{".":"./index.js"}}""",
            StandardCharsets.UTF_8,
        )
        File(pathExistsDir, "index.js").writeText(
            """
            const fsp = require("fs/promises");
            exports.value = "path-exists-lite";
            exports.exists = async function(path) {
              try {
                await fsp.access(path);
                return true;
              } catch (error) {
                const message = String(error && error.message || error);
                if (message.includes("escapes working directory") || message.includes("EPERM")) {
                  throw error;
                }
                return false;
              }
            };
            """.trimIndent() + "\n",
            StandardCharsets.UTF_8,
        )

        val pkgDir = File(modulesDir, "pkg-dir-lite").apply {
            check(mkdirs()) { "Failed to create pkg-dir-lite package dir: $absolutePath" }
        }
        File(pkgDir, "package.json").writeText(
            """{"name":"pkg-dir-lite","version":"1.0.0","exports":{".":"./index.js"}}""",
            StandardCharsets.UTF_8,
        )
        File(pkgDir, "index.js").writeText(
            """
            const path = require("path");
            exports.packageDirectory = function(packageJsonPath) {
              return path.dirname(packageJsonPath);
            };
            """.trimIndent() + "\n",
            StandardCharsets.UTF_8,
        )

        val cosmiconfigDir = File(modulesDir, "cosmiconfig-lite").apply {
            check(mkdirs()) { "Failed to create cosmiconfig-lite package dir: $absolutePath" }
        }
        File(cosmiconfigDir, "package.json").writeText(
            """{"name":"cosmiconfig-lite","version":"1.0.0","exports":{".":"./index.js"}}""",
            StandardCharsets.UTF_8,
        )
        File(cosmiconfigDir, "index.js").writeText(
            """
            const fsp = require("fs/promises");
            const path = require("path");
            const { createRequire } = require("module");
            const findUp = require("find-up-lite");
            const pkgDir = require("pkg-dir-lite");

            function configRequire(configFile) {
              const req = createRequire(configFile);
              const loaded = req("./" + path.basename(configFile));
              return {
                req,
                config: loaded && typeof loaded === "object" && Object.prototype.hasOwnProperty.call(loaded, "default")
                  ? loaded.default
                  : loaded
              };
            }

            async function parseJsonFile(file, label) {
              try {
                return JSON.parse(await fsp.readFile(file, "utf8"));
              } catch (error) {
                throw new Error("Malformed " + label + " for discovery: " + file + ": " + (error && error.message || error));
              }
            }

            exports.search = async function(name) {
              const configNames = ["." + name.toLowerCase() + "rc.json", name.toLowerCase() + ".config.js", "tool.config.js", name.toLowerCase() + ".config.mjs"];
              const found = await findUp.findUp(configNames, { packageField: name });
              if (!found.path) {
                throw new Error("Config not found: start=" + process.cwd() + "; candidates=" + found.candidates.join("|"));
              }
              if (found.kind === "package") {
                const pkg = await parseJsonFile(found.path, "package.json");
                if (!pkg || !pkg[name]) {
                  throw new Error("Config not found: start=" + process.cwd() + "; candidates=" + found.candidates.join("|"));
                }
                return {
                  type: "package-json",
                  configFile: found.path,
                  configDir: pkgDir.packageDirectory(found.path),
                  require: createRequire(found.path),
                  config: pkg[name],
                  candidates: found.candidates,
                  nested: found.nested
                };
              }
              if (found.path.endsWith(".json")) {
                return {
                  type: "rc-json",
                  configFile: found.path,
                  configDir: path.dirname(found.path),
                  require: createRequire(found.path),
                  config: await parseJsonFile(found.path, "JSON config"),
                  candidates: found.candidates,
                  nested: found.nested
                };
              }
              const loaded = configRequire(found.path);
              return {
                type: found.path.endsWith(".mjs") ? "mjs" : "js",
                configFile: found.path,
                configDir: path.dirname(found.path),
                require: loaded.req,
                config: loaded.config,
                candidates: found.candidates,
                nested: found.nested
              };
            };
            """.trimIndent() + "\n",
            StandardCharsets.UTF_8,
        )

        val shadowPluginDir = File(modulesDir, "discover-plugin-alpha").apply {
            check(mkdirs()) { "Failed to create discover plugin shadow package dir: $absolutePath" }
        }
        File(shadowPluginDir, "package.json").writeText(
            """{"name":"discover-plugin-alpha","exports":{".":"./index.js"}}""",
            StandardCharsets.UTF_8,
        )
        File(shadowPluginDir, "index.js").writeText(
            """
            exports.shadow = true;
            exports.transform = () => ({ alpha: "SHADOW" });
            """.trimIndent() + "\n",
            StandardCharsets.UTF_8,
        )
    }

    private fun writeDiscoveryWorkspace(
        projectDir: File,
        name: String,
        mode: String,
        plugin: String = "discover-plugin-alpha",
    ): File {
        val workspace = File(projectDir, name).apply {
            check(mkdirs()) { "Failed to create discovery workspace dir: $absolutePath" }
        }
        File(workspace, "packages/app/src/deep").mkdirs()
        File(workspace, "src").mkdirs()
        File(workspace, "src/input.txt").writeText("hello discovery\n", StandardCharsets.UTF_8)
        writeDiscoveryPluginPackages(workspace)
        val config = """
            {
              "name": "AutoJs6",
              "input": "src/input.txt",
              "plugin": "$plugin",
              "scopedPlugin": "@autojs6/discover-plugin-scoped",
              "formatter": "json"
            }
        """.trimIndent()
        when (mode) {
            "rc-json" -> {
                File(workspace, ".discovertoolrc.json").writeText(config, StandardCharsets.UTF_8)
                File(workspace, "package.json").writeText(
                    """{"name":"$name","private":true}""",
                    StandardCharsets.UTF_8,
                )
            }
            "js" -> {
                File(workspace, "tool.config.js").writeText(
                    """
                    module.exports = $config;
                    """.trimIndent() + "\n",
                    StandardCharsets.UTF_8,
                )
                File(workspace, "package.json").writeText(
                    """{"name":"$name","private":true}""",
                    StandardCharsets.UTF_8,
                )
            }
            "package-json" -> {
                File(workspace, "package.json").writeText(
                    """
                    {
                      "name": "$name",
                      "private": true,
                      "discoverTool": $config
                    }
                    """.trimIndent(),
                    StandardCharsets.UTF_8,
                )
            }
            "mjs" -> {
                File(workspace, "discovertool.config.mjs").writeText(
                    "export default $config;\n",
                    StandardCharsets.UTF_8,
                )
                File(workspace, "package.json").writeText(
                    """{"name":"$name","private":true}""",
                    StandardCharsets.UTF_8,
                )
            }
            "none" -> {
                File(workspace, "package.json").writeText(
                    """{"name":"$name","private":true}""",
                    StandardCharsets.UTF_8,
                )
            }
            else -> error("Unsupported discovery workspace mode: $mode")
        }
        return workspace
    }

    private fun writeDiscoveryPluginPackages(workspace: File) {
        val alphaDir = File(workspace, "node_modules/discover-plugin-alpha").apply {
            check(mkdirs()) { "Failed to create discover-plugin-alpha package dir: $absolutePath" }
        }
        File(alphaDir, "package.json").writeText(
            """{"name":"discover-plugin-alpha","version":"1.0.0","exports":{".":"./index.js"}}""",
            StandardCharsets.UTF_8,
        )
        File(alphaDir, "index.js").writeText(
            """
            const fs = require("fs");
            const processBuiltin = require("process");
            const constantsBuiltin = require("constants");
            const { Buffer } = require("buffer");
            const helper = require("discover-helper");

            exports.shadow = false;
            exports.transform = function(config, input) {
              return {
                alpha: Buffer.from(input, "utf8").toString("utf8").toUpperCase(),
                processOk: processBuiltin.argv.includes("--start") && processBuiltin.env.DISCOVER_PLUGIN === config.plugin,
                constantsOk: constantsBuiltin.fs.R_OK === fs.constants.R_OK,
                helper: helper.value
              };
            };
            """.trimIndent() + "\n",
            StandardCharsets.UTF_8,
        )
        val helperDir = File(alphaDir, "node_modules/discover-helper").apply {
            check(mkdirs()) { "Failed to create discover-helper nested package dir: $absolutePath" }
        }
        File(helperDir, "package.json").writeText(
            """{"name":"discover-helper","version":"1.0.0","exports":{".":"./index.js"}}""",
            StandardCharsets.UTF_8,
        )
        File(helperDir, "index.js").writeText(
            """exports.value = "discover-helper";""" + "\n",
            StandardCharsets.UTF_8,
        )

        val scopedDir = File(workspace, "node_modules/@autojs6/discover-plugin-scoped").apply {
            check(mkdirs()) { "Failed to create scoped discovery plugin package dir: $absolutePath" }
        }
        File(scopedDir, "package.json").writeText(
            """
            {
              "name": "@autojs6/discover-plugin-scoped",
              "version": "1.0.0",
              "exports": {
                ".": "./main.js",
                "./self": "./self.js"
              }
            }
            """.trimIndent(),
            StandardCharsets.UTF_8,
        )
        File(scopedDir, "main.js").writeText(
            """
            const fs = require("fs");
            const processBuiltin = require("node:process");
            const constantsBuiltin = require("node:constants");
            const self = require("@autojs6/discover-plugin-scoped/self");

            exports.apply = function() {
              return {
                scoped: true,
                self: self.value,
                processOk: processBuiltin.argv.includes("--name"),
                constantsOk: constantsBuiltin.F_OK === fs.constants.F_OK
              };
            };
            """.trimIndent() + "\n",
            StandardCharsets.UTF_8,
        )
        File(scopedDir, "self.js").writeText(
            """exports.value = "scoped-self";""" + "\n",
            StandardCharsets.UTF_8,
        )
    }

    private fun writeBadDiscoveryPluginPackages(workspace: File, includeNative: Boolean) {
        val badExportDir = File(workspace, "node_modules/bad-export-discover-plugin").apply {
            check(mkdirs()) { "Failed to create bad discovery export package dir: $absolutePath" }
        }
        File(badExportDir, "package.json").writeText(
            """{"name":"bad-export-discover-plugin","exports":{".":"../outside.js"}}""",
            StandardCharsets.UTF_8,
        )
        if (includeNative) {
            val badNativeDir = File(workspace, "node_modules/bad-native-discover-plugin").apply {
                check(mkdirs()) { "Failed to create bad discovery native package dir: $absolutePath" }
            }
            File(badNativeDir, "package.json").writeText(
                """{"name":"bad-native-discover-plugin","exports":{".":"./native.node"}}""",
                StandardCharsets.UTF_8,
            )
            File(badNativeDir, "native.node").writeText("native", StandardCharsets.UTF_8)
        }
    }

    private fun writeConfigToolFixture(projectDir: File): File {
        val toolDir = File(projectDir, "node_modules/config-tool").apply {
            check(mkdirs()) { "Failed to create config-tool package dir: $absolutePath" }
        }
        File(toolDir, "package.json").writeText(
            """
