        File(minimatchDir, "index.js").writeText(
            """
            function normalize(value) {
              return String(value).replace(/\\/g, "/").replace(/^\.\/+/, "").replace(/\/+/g, "/");
            }

            function escapeRegex(value) {
              return value.replace(/[|\\{}()[\]^$+?.]/g, "\\$&");
            }

            function segmentPattern(segment) {
              return new RegExp("^" + segment.split("*").map(escapeRegex).join("[^/]*") + "$");
            }

            function matchSegments(fileSegments, patternSegments) {
              if (patternSegments.length === 0) {
                return fileSegments.length === 0;
              }
              const head = patternSegments[0];
              if (head === "**") {
                if (patternSegments.length === 1) {
                  return true;
                }
                for (let index = 0; index <= fileSegments.length; index += 1) {
                  if (matchSegments(fileSegments.slice(index), patternSegments.slice(1))) {
                    return true;
                  }
                }
                return false;
              }
              if (fileSegments.length === 0) {
                return false;
              }
              return segmentPattern(head).test(fileSegments[0]) &&
                matchSegments(fileSegments.slice(1), patternSegments.slice(1));
            }

            module.exports = function minimatchLite(file, pattern) {
              const fileSegments = normalize(file).split("/").filter(Boolean);
              const patternSegments = normalize(pattern).split("/").filter(Boolean);
              return matchSegments(fileSegments, patternSegments);
            };
