            """
            module.exports = function slashLite(value) {
              return String(value).replace(/\\/g, "/").replace(/^\.\/+/, "").replace(/\/+/g, "/");
            };
            """.trimIndent() + "\n",
            StandardCharsets.UTF_8,
        )

        val scurryDir = File(toolDir, "node_modules/path-scurry-lite").apply {
            check(mkdirs()) { "Failed to create path-scurry-lite package dir: $absolutePath" }
        }
        File(scurryDir, "package.json").writeText(
            """{"name":"path-scurry-lite","version":"1.0.0","exports":{".":"./index.js"}}""",
            StandardCharsets.UTF_8,
        )
        File(scurryDir, "index.js").writeText(
            """
            const fs = require("fs");
            const fsp = require("fs/promises");
            const path = require("path");
            const constantsBuiltin = require("constants");
            const normalize = require("normalize-path-lite");

            exports.direntOk = false;
            exports.mode = "uninitialized";
            async function walk(root) {
              const start = root || ".";
              const results = [];
              let sawDirent = false;
              let mode = "readdir";
              async function readDirents(relativePath) {
                if (typeof fsp.opendir === "function") {
                  mode = "opendir";
                  const dir = await fsp.opendir(relativePath);
                  const entries = [];
                  for await (const dirent of dir) {
                    entries.push(dirent);
                  }
                  return entries;
                }
                return fsp.readdir(relativePath, { withFileTypes: true });
              }
              async function visit(relativePath) {
                const entries = await readDirents(relativePath);
                for (const entry of entries) {
                  sawDirent = sawDirent ||
                    (entry && typeof entry.isFile === "function" && typeof entry.isDirectory === "function");
                  const childName = String(entry.name);
                  const child = relativePath === "." ? childName : path.join(relativePath, childName);
                  if (entry.isDirectory()) {
                    await visit(child);
                  } else if (entry.isFile()) {
                    results.push(normalize(child));
                  }
                }
              }
              await fsp.access(start, fs.constants.F_OK);
              await visit(start);
              exports.direntOk = sawDirent;
              exports.mode = mode;
              return results.sort();
            }

            exports.walk = walk;
            exports.constantsOk = constantsBuiltin.fs.R_OK === fs.constants.R_OK;
            exports.nestedOk = normalize.nested === "normalize-path-lite";
            """.trimIndent() + "\n",
            StandardCharsets.UTF_8,
        )
        val normalizeDir = File(scurryDir, "node_modules/normalize-path-lite").apply {
            check(mkdirs()) { "Failed to create normalize-path-lite package dir: $absolutePath" }
        }
        File(normalizeDir, "package.json").writeText(
            """{"name":"normalize-path-lite","version":"1.0.0","exports":{".":"./index.js"}}""",
            StandardCharsets.UTF_8,
        )
        File(normalizeDir, "index.js").writeText(
            """
            function normalizePathLite(value) {
              return String(value).replace(/\\/g, "/").replace(/^\.\/+/, "").replace(/\/+/g, "/");
            }

            normalizePathLite.nested = "normalize-path-lite";
            module.exports = normalizePathLite;
            """.trimIndent() + "\n",
            StandardCharsets.UTF_8,
        )

        return toolDir
    }

    private fun runEmbeddedPackageBin(
        projectDir: File,
        packageDir: File,
        binName: String,
        args: List<String> = emptyList(),
        timeoutMs: Long = 5000L,
    ): NativeNodeEmbeddedRuntimeBridge.EmbeddedScriptResult {
        return NativeNodeEmbeddedProjectRunner.runPackageBin(
            context,
            NativeNodeEmbeddedProjectRunner.PackageBinRequest(
                projectRoot = projectDir,
                packageDir = packageDir,
                binName = binName,
                workingDirectory = projectDir,
                argv = args,
                timeoutMs = timeoutMs,
            ),
        )
    }

    private fun jsStringLiteral(value: String): String {
        val escaped = StringBuilder(value.length + 2)
        escaped.append('"')
        value.forEach { char ->
            when (char) {
                '\\' -> escaped.append("\\\\")
                '"' -> escaped.append("\\\"")
                '\b' -> escaped.append("\\b")
                '\u000C' -> escaped.append("\\f")
                '\n' -> escaped.append("\\n")
                '\r' -> escaped.append("\\r")
                '\t' -> escaped.append("\\t")
                else -> {
                    if (char.code < 0x20) {
                        escaped.append("\\u")
                        escaped.append(char.code.toString(16).padStart(4, '0'))
                    } else {
                        escaped.append(char)
                    }
                }
            }
        }
        escaped.append('"')
        return escaped.toString()
    }

    private fun assertPackageBinHelperRejects(expectedToken: String, action: () -> Any?) {
        val failure = runCatching { action() }.exceptionOrNull()
        assertTrue("Expected package bin helper rejection containing '$expectedToken'", failure is IllegalArgumentException)
        assertTrue(failure?.message.orEmpty(), failure?.message.orEmpty().contains(expectedToken))
    }

    private fun moduleSourcesFor(vararg files: File): Map<String, String> {
        return files.associate { file ->
            file.canonicalPath to file.readText(StandardCharsets.UTF_8)
        }
    }

    private fun writeNpmPackage(
        root: File,
        name: String,
        packageJson: String,
        files: Map<String, String>,
    ): List<File> {
        val packageDir = File(root, "node_modules/$name").apply {
            check(mkdirs() || isDirectory) { "Failed to create npm package dir: $absolutePath" }
        }
        val written = mutableListOf<File>()
        written += File(packageDir, "package.json").apply {
            writeText(packageJson.trimIndent(), StandardCharsets.UTF_8)
        }
        files.forEach { (relativePath, content) ->
            require(!relativePath.startsWith("/") && !relativePath.contains("..")) {
                "Unsafe npm fixture path: $relativePath"
            }
            written += File(packageDir, relativePath).apply {
                parentFile?.mkdirs()
                writeText(content.trimIndent(), StandardCharsets.UTF_8)
            }
        }
        return written
    }

    private fun gzipBase64(bytes: ByteArray): String {
        val output = ByteArrayOutputStream()
        GZIPOutputStream(output).use { gzip ->
            gzip.write(bytes)
        }
        return Base64.encodeToString(output.toByteArray(), Base64.NO_WRAP)
    }

    private fun assertOutputOrder(output: String, vararg expected: String) {
        var cursor = -1
        expected.forEach { token ->
            val next = output.indexOf(token, startIndex = cursor + 1)
            assertTrue("Expected '$token' after index $cursor in output:\n$output", next >= 0)
            cursor = next
        }
    }

    private fun assertOccurrenceCount(output: String, token: String, expectedCount: Int) {
        var count = 0
        var cursor = output.indexOf(token)
        while (cursor >= 0) {
            count += 1
            cursor = output.indexOf(token, startIndex = cursor + token.length)
        }
        assertEquals("Unexpected occurrence count for '$token' in output:\n$output", expectedCount, count)
    }

    private fun assertErrorEnvelope(
        result: NativeNodeEmbeddedRuntimeBridge.EmbeddedScriptResult,
        sourceName: String,
        errorName: String,
        messageToken: String,
        errorCode: String?,
        expectedExitCode: Int = 1,
        timedOut: Boolean = false,
    ) {
        assertFalse(result.succeeded)
        assertEquals(expectedExitCode, result.exitCode ?: -1)
        assertEquals(errorName, result.errorName)
        assertTrue(result.errorMessage.orEmpty().contains(messageToken))
        assertEquals(errorCode, result.errorCode)
        assertEquals(sourceName, result.sourceName)
        assertEquals(timedOut, result.timedOut)
        assertTrue(result.elapsedMs >= 0L)
    }

    private data class ExpectedNodeProjectRequest(
        val projectRoot: File,
        val launchKind: NodeProjectLaunchKind,
        val packageDir: File = projectRoot,
        val workingDirectory: File = projectRoot,
        val scriptName: String? = null,
        val binName: String? = null,
        val argv: List<String> = emptyList(),
        val env: Map<String, String> = emptyMap(),
        val timeoutMs: Long = 5000L,
        val executionMode: String = NodeExecutionModePolicy.MODE_ONE_SHOT,
    )

    private fun assertNodeProjectLaunchRequest(
        label: String,
        launch: ScriptLaunchSourceFactory.Launch,
        expected: ExpectedNodeProjectRequest,
    ): NativeNodeEmbeddedProjectRunner.ProjectRequest {
        assertEquals("$label launch kind", expected.launchKind, launch.nodeProjectLaunchKind)
        assertEquals("$label launch workingDirectory", expected.workingDirectory.canonicalPath, launch.workingDirectory)
        val request = checkNotNull(launch.buildNodeProjectRequestOrNull()) {
            "$label should build Node project request"
        }
        assertNodeProjectRequest(label, request, expected)
        return request
    }

    private fun assertNodeProjectRequest(
        label: String,
        request: NativeNodeEmbeddedProjectRunner.ProjectRequest,
        expected: ExpectedNodeProjectRequest,
    ) {
        assertEquals("$label request projectRoot", expected.projectRoot.canonicalFile, request.projectRoot)
        assertEquals("$label request packageDir", expected.packageDir.canonicalFile, request.packageDir)
        assertEquals("$label request workingDirectory", expected.workingDirectory.canonicalFile, request.workingDirectory)
        assertEquals("$label request scriptName", expected.scriptName, request.scriptName)
        assertEquals("$label request binName", expected.binName, request.binName)
        assertEquals("$label request argv", expected.argv, request.argv)
        assertEquals("$label request env", expected.env, request.env)
        assertEquals("$label request timeoutMs", expected.timeoutMs, request.timeoutMs)
        assertEquals("$label request executionMode", expected.executionMode, request.executionMode)
        assertEquals("$label request launchKind", expected.launchKind, NodeProjectLaunchKind.from(request.scriptName, request.binName))
    }

    private fun assertTaskNodeProjectRequest(
        label: String,
        task: Task.PendingTask,
        launch: ScriptLaunchSourceFactory.Launch,
        expected: ExpectedNodeProjectRequest,
    ): NativeNodeEmbeddedProjectRunner.ProjectRequest {
        val launchRequest = assertNodeProjectLaunchRequest(label, launch, expected)
        val taskRequest = checkNotNull(task.createNodeProjectRequestOrNull()) {
            "$label task should build Node project request"
        }
        assertEquals("$label task request should match launch request", launchRequest, taskRequest)
        assertEquals(
            "$label task execution workingDirectory",
            expected.workingDirectory.canonicalPath,
            task.createLaunchExecutionConfig(launch, ExecutionConfig()).workingDirectory,
        )
        return taskRequest
    }

    private fun assumeEmbeddedScriptExecutionEnabled() {
        assumeTrue(
            "Build with -Pautojs.nodejs.embedded.script.enabled=true to run embedded script MVP tests.",
            BuildConfig.NODEJS_EMBEDDED_SCRIPT_EXECUTION_BUILD_ENABLED,
        )
    }

    private fun assertPendingTaskEngineName(scriptFile: File, expectedEngineName: String) {
        val timedTask = TimedTask().apply {
            scriptPath = scriptFile.absolutePath
        }
        assertEquals(expectedEngineName, Task.PendingTask(context, timedTask).engineName)
    }

    private fun assertPendingTaskNodeProjectLaunchKind(scriptFile: File, expectedLaunchKind: NodeProjectLaunchKind?) {
        val timedTask = TimedTask().apply {
            scriptPath = scriptFile.absolutePath
        }
        val task = Task.PendingTask(context, timedTask)
        assertEquals(expectedLaunchKind != null, task.isNodeProjectLaunch)
        assertEquals(expectedLaunchKind?.descriptorValue.orEmpty(), task.nodeProjectLaunchKindDescriptor)
        val launch = task.createLaunch()
        assertEquals(expectedLaunchKind, launch.nodeProjectLaunchKind)
        assertEquals(
            launch.workingDirectory,
            task.createLaunchExecutionConfig(launch, ExecutionConfig()).workingDirectory,
        )
        val request = task.createNodeProjectRequestOrNull()
        assertEquals(expectedLaunchKind != null, request != null)
        if (request != null) {
            assertEquals(expectedLaunchKind, NodeProjectLaunchKind.from(request.scriptName, request.binName))
        }
    }

    private fun settleEmbeddedScriptServiceProcess() {
        context.stopService(Intent(context, NativeNodeEmbeddedScriptService::class.java))
        Thread.sleep(600L)
    }
}
